-- Sources: data/i18n/svSE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:2206"] = {n="Snatch and Grab",s="Master Mathias Shaw skickar agenter till Jerod's Landing för att få information om frakt. Defias Brotherhood använder flodbryggan för att i hemlighet flytta förnödenheter.",h="Master Mathias Shaw skickar agenter till Jerod's Landing för att få information om frakt.",kw={"crystal lake","defias","dockmaster","goldshire","jerod's landing","mathias shaw","shipping schedule","si:7","snatch and grab"},ang={["class:Rogue"]="Som skurk får du träffa SI:7 och prövas i smygförmåga och ficktjuvskonst. Vinn Mathias Shaws erkännande och en signaturklinga.",["faction:Alliance"]="Som medlem av Alliansen hjälper du till att stoppa Defias försörjningsvägar vid Jerod's Landing. Du skyddar Elwynn Forest och försvagar det kriminella syndikat som hotar Stormwinds omgivande områden."},sec={{t="Ett prov i spionkonst",b="Master Mathias Shaw prövar blivande agenter som vill få en plats i Stormwinds hemliga underrättelsetjänst. Han kräver finess och smygförmåga, inte råstyrka. SI:7-agenter oskadliggör nyckelpersoner i tysthet och hämtar viktiga dokument utan att dra in riket i en öppen skandal. Varje ny agent måste bevisa att hen kan arbeta obemärkt."},{t="Smugglare på floden",b="Jerod's Landing ligger vid floden i södra Elwynn, söder om Goldshire och strax öster om The Maclure Vineyards. Defias Brotherhood tog över den tidigare stillsamma bryggan och gjorde den till en illegal smuggelväg. Smuggelvapen, förnödenheter och förbjudna varor förs över vattnet från Redridge mot Westfall, utom räckhåll för kungliga vägpatruller."},{t="Trovärdig förnekelse",b="Master Mathias Shaw varnar agenterna för att de står utan kronans stöd om de grips, röjs eller dödas. Stormwind och dess spionmästare kommer att förneka att de någonsin existerat. Om SI:7 återfår Defias Dockmasters fraktlista får de bevis på Brotherhoods försörjningsvägar, samtidigt som Stormwinds officiella inblandning förblir dold."}},faq={{q="Vem ger uppdraget Snatch and Grab?",a="Master Mathias Shaw, ledare för Stormwinds underrättelsetjänst SI:7, tilldelar uppdraget från dess högkvarter i Old Town.",al={"vem ger snatch and grab","uppdragsgivare snatch and grab"}},{q="Var ligger Jerod's Landing?",a="Jerod's Landing är en flodbrygga i södra Elwynn Forest, söder om Goldshire och strax öster om The Maclure Vineyards. Defias Brotherhood har tagit kontroll över bryggorna och brygghuset.",al={"jerod's landing plats","var ligger jerod's landing","dockmasters plats"}},{q="Vad smugglar Defias genom Jerod's Landing?",a="Defias för förbjudna varor och förnödenheter över vattnet mellan Redridge och Westfall, utanför kungarikets vaktposter och vägspärrar.",al={"vad smugglar de","defias förbjudna varor"}},{q="Vem bär på Defias Shipping Schedule?",a="Defias Dockmaster bär på fraktlistan och vaktar brygghuset vid Jerod's Landing.",al={"var finns shipping schedule","vem tappar fraktlistan","defias dockmaster"}},{q="Vad händer om en agent grips under uppdraget?",a="Master Mathias Shaw varnar för att SI:7 kommer att förneka all koppling till en agent som röjs eller grips.",al={"vad händer om jag misslyckas","förnekas av si:7"}},{q="Varför är SI:7 intresserade av fraktlistan?",a="Fraktlistan beskriver hur Defias Brotherhood transporterar förbjudna varor mellan Redridge och Westfall. Den gör det möjligt för Stormwinds underrättelsenätverk att kartlägga fiendens försörjningsvägar utan att varna syndikatet.",al={"varför behövs fraktlistan","si:7 shipping schedule"}}},fx={["170a7301"]={q="Vad är Defias Shipping Schedule?",a="Tidtabellen beskriver transporten av olagligt gods längs Elwynn Forests vattenvägar. Defias Brotherhood har tagit över Jerod's Landing för att frakta stora mängder smugglegods mellan Redridge och Westfall mitt framför näsan på riket. Om du återfinner tidtabellerna får SI:7 konkreta uppgifter om Defias rörelsekorridorer och transportvägar.",al={"defias shipping schedule","vad är shipping schedule","vad används shipping schedule till"}},["5dd0ffd3"]={q="Vem är Defias Dockmaster?",a="Dockmaster leder Brotherhoods hemliga verksamhet vid Jerod's Landing, ett hamnhus vid floden söder om Goldshire. Därifrån samordnar han flödet av smugglade förnödenheter, vapen och stulet gods mellan Redridge och Westfall. Han bär lastförteckningarna på sig för att kunna styra Defias flodsmugglare.",al={"defias dockmaster","vem är dockmastern","dockmaster vid jerod's landing"}},a07026c6={q="Varför skickar Mathias Shaw dig i stället för erfarna SI:7-agenter?",a="Du skickades till Mathias Shaw som en lovande ny skurkrekryt, upptäckt av Keryn Sylvius. Att infiltrera Jerod's Landing blir både ett praktiskt prov på din smygförmåga och stöldkonst och ett uppdrag som går att förneka. SI:7 tänker förneka all kännedom om dig om du åker fast, så en grön agent håller Stormwinds främsta underrättelsenätverk borta från offentlighetens blickar.",al={"varför skicka mig","varför rekrytera till si7","varför behöver mathias shaw dig"}}},fp="15,158,20.313.0,22.321.0,21.312.0,38.121.0,25.175.0,54.135.0,41.97.0,61.104.0,48.197.0"}
P.entries["quest:221"] = {n="Worgen in the Woods",s="När Nightbane-flocken tränger allt längre in mot Darkshire ger Calor äventyrarna i uppdrag att slå ut flockens främsta förtrupper. Dessa våldsamma Dark Runners har tagit över Rotting Orchard i närheten och hotar att helt omringa den belägrade staden.",h="När Nightbane-flocken tränger allt längre in mot Darkshire ger Calor äventyrarna i uppdrag att slå ut...",kw={"calor","carevin","dark runner","darkshire","duskwood","night watch","nightbane","the rotting orchard","worgen"},ang={["class:Hunter"]="De onaturliga, tvåbenta vargarnas snabba framryckning vid Rotting Orchard ger jägarna en dyster lärdom om hur man hanterar utomvärldsliga bestar vars instinkter trotsar Azeroths naturliga ekologi.",["faction:Alliance"]="Duskwood har knappt fått några förstärkningar från Stormwinds krona, så lokala frivilliga miliser som Night Watch måste helt förlita sig på resande Alliance-hjältar för att decimera de framryckande rovdjursflockarna."},sec={{t="En allt snävare ring",b="Spejare mötte först ensamma worgen som vävde skuggmagi i skogens utkanter, men Calors patrullering avslöjade ett mycket mer akut taktiskt hot. Större och snabbare bestar, kända som Nightbane Dark Runners, har samlats i Rotting Orchard strax sydväst om Darkshire. De håller sig inte bara gömda under trädkronorna, utan utgör huvuddelen av flocken och har upprättat ett uppmarschområde inom räckhåll från byns portar."},{t="En outsinlig ström",b="Att decimera Dark Runners hejdar tillfälligt flockens anfall, men det ger Night Watch föga sinnesro. Calor noterar med växande fasa att varje fälld best genast verkar ersättas av en annan som stryker omkring i dimman. Nightbanes övernaturliga motståndskraft och enorma återväxt förbryllar stadens försvarare. De tvingas vända sig till erfarna monsterjägare som Master Jonathan Carevin för att avslöja vilken vidrig kraft som kallade dessa främmande fasor till Duskwood."}},faq={{q="Vad är Nightbane Dark Runners?",a="Nightbane Dark Runners är större, fysiskt imponerande worgen som utgör flockens främsta frontstyrkor i Duskwood. Till skillnad från de mystiska Shadow Weavers förlitar sig Dark Runners på rå snabbhet, klor och ren rovdjursvildhet.",al={"dark runners","vad är dark runners","nightbane dark runner"}},{q="Var ligger Rotting Orchard?",a="Rotting Orchard ligger strax sydväst om Darkshire. Den var en gång bördig jordbruksmark, men har förvandlats till en fördärvad, härjad glänta som Nightbane-flocken lagt beslag på som ett framskjutet fäste nära staden.",al={"rotting orchard plats","var ligger rotting orchard"}},{q="Vem är Calor?",a="Calor är en skogvaktare i Darkshire som tjänar Master Jonathan Carevin. Han spejar i utkanten av bosättningen och följer worgenflockarnas aggressiva rörelser, som hotar stadens överlevnad.",al={"vem är calor","calor duskwood","calor uppdragsgivare"}},{q="Varför verkar worgen vara oändligt många för försvararna?",a="Försvararna förstår ännu inte den övernaturliga naturen hos worgenhotet. De tror att en ondskefull kraft aktivt kallar på eller lockar bestarna till Duskwood, så att nya vågor dyker upp lika snabbt som de gamla fälls.",al={"varför så många worgen","outsinliga worgen","var kommer worgen ifrån"}},{q="Vem är Master Carevin?",a="Master Jonathan Carevin leder familjen Carevins kamp mot de odöda och andra onda krafter i Duskwood från Darkshire. Calor litar djupt på hans expertis för att spåra källan till de monstruösa angrepp som plågar regionen.",al={"master carevin","jonathan carevin","vem är carevin"}},{q="Hur bidrar detta uppdrag till Darkshires försvar?",a="Darkshire är en isolerad bosättning med sinande förråd och utan hjälp från Stormwind. Genom att rensa Rotting Orchard hindrar man Nightbane-flocken från att iscensätta direkta, överväldigande bakhåll mot stadens sydvästra försvarslinje.",al={"varför döda dark runners","darkshires försvar"}}},fx={e2dcc78b={q="Varför vill Calor att Nightbane Dark Runners ska gallras ut?",a="Calor håller uppsikt över bestarnas intrång kring Darkshire och vet att Dark Runners utgör den överväldigande majoriteten av worgenstyrkorna som stryker omkring i skogen. Än värre är att de helt har tagit över The Rotting Orchard strax sydväst om staden. Om en så stor och vild flock lämnas i fred så nära Darkshire väntar en katastrof, så han behöver minska deras antal innan bosättningen övermannas.",al={"calors motiv","varför döda dark runners","varför vill calor att detta görs"}},["99fe833d"]={q="Varför förlitar sig Calor på dig i stället för att själv rensa fruktträdgården?",a="Calor är spejare och skogsvaktare. Hans främsta uppgift är att hålla uppsikt över skogen, spåra bestarnas rörelser och rapportera hot till Darkshire. Nightbane-worgenerna är aggressiva, starka och verkar aldrig ta slut, vilket pressar stadens försvarare till bristningsgränsen. Med fasor som belägrar Darkshire från alla håll förlitar sig skogsvaktare som Calor på dugliga äventyrare som kan föra striden rakt in i angripna dungar som The Rotting Orchard.",al={"varför jag","varför gör inte calor det själv","varför behöver calor hjälp"}}},fp="19,162,22.358.0,21.338.1,32.206.0,37.184.0,13.164.0,56.210.0,22.208.0,53.204.0"}
P.entries["quest:222"] = {n="Worgen in the Woods",s="När Nightbane-flocken stärker sitt grepp om Duskwood leder Calor äventyrare till angrepp mot dess farligaste led. Genom att strida direkt mot dem i deras sydliga hålor och gruvor pressar försvararna tillbaka det vilda hotet som närmar sig Darkshire.",h="När Nightbane-flocken stärker sitt grepp om Duskwood leder Calor äventyrare till angrepp mot dess farligaste...",kw={"calor","carevin","darkshire","duskwood","nightbane","tainted one","vile fang","worgen"},ang={["class:Hunter"]="Nightbane-flockens list gör dem till ett onaturligt byte och kräver vaksamhet av spårare som närmar sig deras mörka hålor.",["faction:Alliance"]="Darkshire ligger isolerat i rikets dystra söder. Att rensa de södra grottorna hjälper till att skydda Duskwoods bräckliga försörjningsleder och kvarvarande gårdar."},sec={{t="Ett fäste i vildmarken",b="Worgenplågan som hemsöker Duskwood är långt ifrån tanklöst kaos. Djuren som kallas Nightbane har skurit ut ett område i det mörka landskapet söder om Darkshire och börjat bygga befästa läger. Calor ser deras brasor fladdra i fjärran med växande oro och noterar att varelserna har tagit över djupa grottor och övergivna gruvschakt. Bland dem är Vile Fangs och Tainted Ones de grymmaste raserna, med våldsam vildhet och en envishet som hotar att övermanna stadens försvar."},{t="Calors rekommendation",b="Calor är en vaksam rekryterare vid Darkshires frontlinje, men han hyser få illusioner om de varglika inkräktarnas skräckinjagande natur. Att knäcka Vile Fangs och Tainted Ones prövar varje hjältes mod. De som lyckas decimera dessa härdade flockar får mer än bara mynt; de vinner Calors respekt och en personlig rekommendation till Master Carevin, den tillbakadragna person som samordnar den större offensiven mot worgenplågan."}},faq={{q="Var finns Vile Fangs och Tainted Ones?",a="Dessa farliga raser i Nightbane-flocken samlas kring grottor och gruvan i södra Duskwood, ofta runt synliga brasor.",al={"var finns tainted ones","var finns vile fangs","worgenplatser duskwood"}},{q="Vem är Calor?",a="Calor är en hängiven invånare i Darkshire som håller uppsikt över worgenhotet i skogen och värvar dugliga äventyrare för att hejda varelsernas framfart.",al={"calor darkshire","vem ger worgen in the woods 3"}},{q="Vem är Master Carevin?",a="Master Carevin är Jonathan Carevin från Darkshire. Hans familj bekämpar regionens onda krafter, och han samordnar försöken att utplåna worgenhotet i trakten.",al={"master carevin","carevin duskwood"}},{q="Varför har worgen brasor?",a="Trots sitt monstruösa, varglika utseende uppvisar Nightbane-worgen en oroande intelligens. De samlas i organiserade läger, använder eld och håller befästa platser som gruvor.",al={"varför gör worgen upp eld","nightbanes brasor"}},{q="Vad händer när jakten är över?",a="Om du imponerar på Calor får du ett rekommendationsbrev som skickar dig direkt till Master Carevin för att hjälpa honom i nästa fas av jakten.",al={"nästa uppdrag efter worgen in the woods 3","fortsättning på worgen in the woods"}},{q="Varför oroar sig Darkshire så mycket för just dessa worgen?",a="Vile Fangs och Tainted Ones hör till flockens mest dödliga och aggressiva medlemmar. Om de lämnas ostörda nära de södra gruvorna riskerar bestarna att helt ta över vägarna i trakten.",al={"varför nightbane vile fang","fara med vile fang"}}},fx={["0c2f2969"]={q="Varför vill Calor att de här worgenerna ska dödas?",a="Calor försöker skydda Darkshire och hjälpa Master Carevin i hans pågående korståg mot varulvshotet. Nightbane-flocken har befäst sig i söder, tänt eldar och etablerat fästen i grottor och gruvor. Genom att skicka dig för att slå ut deras farligaste krigare hoppas Calor försvaga flocken innan den övermannar det lilla försvar som finns kvar i Duskwood.",al={"varför döda worgenerna","calors motiv","varför vill calor detta"}},["5cfb2401"]={q="Vad är Vile Fangs och Tainted Ones som du jagar?",a="De hör till de dödligaste och mest våldsamma i Nightbane-flocken. Till skillnad från de mindre bestarna som stryker omkring i vildmarken har dessa worgener organiserade läger nära Roland's Doom och andra grottor i söder. De håller eldar brinnande och visar prov på en listig, samordnad närvaro som hotar hela Darkshire.",al={"vilka är vile fangs","tainted ones i duskwood","worgenmålet"}},["5e6f00dd"]={q="Varför rekryterar Calor dig i stället för att själv ta hand om bestarna?",a="Darkshires försvarare, Night Watch, är hopplöst fåtaliga när de ska skydda stadens utkanter mot odöda, spindlar och vilda bestar. Att föra striden djupt in på worgenmark kräver erfarna kämpar som kan stå emot mörk magi och brutal vildhet, och dina tidigare framgångar har visat Calor att du har färdigheterna som krävs för att överleva.",al={"varför behöver calor mig","varför skicka mig","varför tar inte night watch hand om det"}}},fp="19,129,16.324.0,19.288.1,50.107.0,13.120.0,22.147.0,32.183.0,40.123.0,58.175.0"}
P.entries["quest:223"] = {n="Worgen in the Woods",s="Det här ärendet för Calors rekommendationsbrev till Jonathan Carevin i Darkshire och avslutar din jakt på de vilda worgen som hemsöker Duskwood. Imponerad av din skicklighet mot de bestialiska inkräktarna hänvisar Calor dig direkt till en man som bekämpar större hot bland skuggorna.",h="Det här ärendet för Calors rekommendationsbrev till Jonathan Carevin i Darkshire och avslutar din jakt på de...",kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","worgen i skogen"},ang={["class:Paladin"]="Carevin hälsar beprövade bundsförvanter med åkallan av det Heliga Ljuset och söker heliga hjältar som står fast mot Duskwoods utbredda oheliga ondska.",["class:Priest"]="Carevins avskedsvälsignelse, ”Ära under Ljuset”, återspeglar den desperata tro som Darkshires återstående försvarare håller fast vid inför den aldrig sinande mörka korruptionen.",["faction:Alliance"]="När kungariket Stormwind inte kan avvara soldater till Duskwoods gränsland är självständiga äventyrare från Alliansen och väktare som Carevin stadens enda försvarslinje."},sec={{t="En sällsynt rekommendation",b="Efter att ha gallrat ut Nightbane-flocken som stryker kring Roland's Doom och de skuggiga gläntorna vinner du Calors svårvunna respekt. Calor är posterad vid skogens mörka gräns och delar sällan ut beröm, än mindre formella introduktioner. Han räcker över en bleknad papperslapp och ber dig överlämna hans hälsning direkt till Jonathan Carevin i Darkshire. Han säger att om de hade fler kämpar av din kaliber kunde deras lilla styrka till slut överträffa stadens hårt ansatta Night Watch."},{t="Carevins vaka",b="Jonathan Carevin arbetar i Darkshire under enorm press, på sin vakt mot främlingar och ständigt pressad på tid. Staden hotas inte bara av glupska worgen, utan också av rastlösa odöda, skuggiga demoniska krafter och förrädiska kultister som hjälper korruptionen inifrån. Calors lysande rekommendation får Carevin att släppa på sin kyliga fasad och bekräftar att du är en pålitlig kämpe som vill värna Ljuset mot Duskwoods kvävande fasor."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Calor skickar dig på det här ärendet. Han har sett hur väl du lyckats mot de glupska worgenflockarna i Duskwood och ger dig en bleknad rekommendation att ta med till sin bundsförvant, Jonathan Carevin.",al={"uppdragsgivare","vem ger det här uppdraget","calor"}},{q="Vem är Jonathan Carevin?",a="Jonathan Carevin är en bister och mycket fokuserad invånare i Darkshire som samordnar kampen mot de övernaturliga ondskor som hotar staden. Han är misstänksam mot främlingar, men samarbetar med betrodda personer som Calor för att rensa ut odöda, demoner och deras medhjälpare.",al={"carevin","vem är carevin","mäster carevin"}},{q="Varför är Calor så avfärdande mot Night Watch?",a="Calor antyder att stadens officiella Night Watch har det kämpigt och är för få för att hantera alla fasor som invaderar Duskwood. Han tror att några skickliga och hängivna kämpar utanför den formella byråkratin kan uträtta mycket mer mot de annalkande skuggorna.",al={"calor night watch","vara fler än night watch","varför konkurrera med night watch"}},{q="Vilka hot varnar Carevin för när jag lämnar brevet?",a="När Carevin läser rekommendationen varnar han för att Darkshire hotas från alla håll: glupska worgen, strövande odöda, invaderande demoner och lömska kultister eller medhjälpare som bistår dem. Han uppmanar dig att alltid vara vaksam och bara lita på beprövade bundsförvanter.",al={"carevins fiender","vad säger carevin","vad slåss vi mot"}},{q="Kräver det här uppdraget någon strid?",a="Nej. Det här sista steget är en ren leverans. Efter de farliga jakterna på Nightbane-worgen i Duskwood under de tidigare delarna av uppdragskedjan behöver du bara föra Calors brev säkert till Carevin i Darkshire.",al={"blir det strid","måste jag döda något","bara leverans"}},{q="Var hittar jag Jonathan Carevin?",a="Jonathan Carevin finns inne i staden Darkshire i Duskwood, där han tar hand om brådskande frågor kring stadens utsatta försvar.",al={"carevins plats","var är carevin","var lämnar jag in"}}},fx={f56a577c={q="Varför skickar Calor dig till Jonathan Carevin?",a="Calor tycker att du har bevisat ditt mod i skogen och vill formellt presentera dig för sin överordnade, Master Jonathan Carevin. Hans lilla orden verkar i Duskwoods skuggor, skild från den hårt pressade Night Watch. Han hoppas att dugliga kämpar som du ska stärka deras hemliga insatser mot de mörkare hot som plågar trakten.",al={"varför skicka mig till carevin","calors motiv","varför ta med meddelandet till carevin"}},["47a08b52"]={q="Varför förlitar sig Calor på dig i stället för Night Watch?",a="Calor har föga förtroende för stadens vanliga vakter och anser att Night Watch inte duger för det dystra specialarbete hans orden utför. Du visade din förmåga genom att ta itu med worgenhotet direkt där andra misslyckades, så han ser dig som någon som verkligen kan hjälpa deras hemliga korståg mot Duskwoods mörkare fasor.",al={"varför inte night watch","varför litar han på mig mer än vakterna","varför behöver calor mig"}}},fp="19,196,21.434.0,15.337.0,29.162.0,24.233.0,46.182.0,51.159.0,35.136.0,34.73.0"}
P.entries["quest:224"] = {n="In Defense of the King's Lands",s="Mountaineer Cobbleflint vaktar det södra tornet i Valley of Kings och söker desperat hjälp mot de framryckande Stonesplinter-troggarna. Ironforges styrkor är hårt ansatta på avlägsna fronter, så försvaret av Loch Modans södra pass vilar på förbipasserande frivilliga från Alliansen.",h="Mountaineer Cobbleflint vaktar det södra tornet i Valley of Kings och söker desperat hjälp mot de...",kw={"cobbleflint","gravelgaw","ironforge","loch modan","mountaineer","stonesplinter","trogg","valley of kings"},ang={["class:Hunter"]="Klippbranterna och utsprången i Stonesplinter Valley erbjuder idealisk terräng för att slå ut aggressiva troggvakter och spaningspatruller från höga utsiktsplatser.",["faction:Alliance"]="När du hjälper till att säkra Valley of Kings visar du Alliansens styrka och besvarar Ironforges vädjan medan dvärgtrupperna är utplacerade på avlägsna allierade fronter.",["race:Dwarf"]="För dvärgäventyrare är det avgörande att hörsamma Cobbleflints uppmaning till försvar av hemlandet. Det hindrar King Magnis förfäders dalar från att falla i underjordiska skadedjurs händer medan armén strider på andra håll."},sec={{t="En tunn försvarslinje i Valley of Kings",b="De väldiga dvärgmonumenten, uthuggna i bergen i Valley of Kings, tornar över en hårt pressad garnison. Mountaineer Cobbleflint och hans vakter vid det södra vakttornet möter en ständigt växande invasion av troggar som väller fram ur berget. Eftersom stora delar av King Magni Bronzebeards reguljära armé skickats utomlands för att stödja Alliansens åtaganden, är försvaret av hemlandet starkt beroende av lokala patruller och inhyrda svärd för att hindra provinsen från att bli övermannad."},{t="Stonesplinter-intrånget",b="Hotet under jord kommer från Stonesplinter Valley, en klippig ravin som skär in i Loch Modans södra bergstoppar. Troggar och deras spejare har grävt sig upp mot ytan i enorma antal och anlagt befästa läger längs dalens botten. Om de lämnas ostörda hotar deras spaningspatruller de viktiga vägarna som förbinder Loch Modan med de södra passen, vilket tvingar Mountaineers att föra ett oavbrutet utnötningskrig."}},faq={{q="Varför har garnisonen i Loch Modan så få soldater?",a="King Magni Bronzebeard har skickat stora delar av Ironforges militär till avlägsna slagfält och utposter för Alliansen runtom i Azeroth. Detta engagemang utomlands innebär att hemtrakter som Loch Modan främst skyddas av lätta patruller från Mountaineers, som måste kalla på resande äventyrare för att hejda regionala invasioner.",al={"varför så få vakter","var är ironforges soldater","varför så få soldater"}},{q="Vem är Mountaineer Cobbleflint?",a="Mountaineer Cobbleflint är en dvärgvakt vid det södra vakttornet i Valley of Kings. Han samordnar bevakningen längs Loch Modans södra gräns och leder motangrepp mot de häckande troggstammarna.",al={"cobbleflint","vem ger uppdraget","uppdragsgivare"}},{q="Var ligger Stonesplinter Valley?",a="Stonesplinter Valley ligger söder om Thelsamar. Du når dalen via en ingång nära huvudvägen, innan du kommer fram till de väldiga dvärgstatyerna i Valley of Kings. Troggarna har flera läger längs dess klippiga botten.",al={"stonesplinter-plats","var finns troggar","hitta stonesplinter valley"}},{q="Varför utgör troggar ett så allvarligt hot mot dvärgarna?",a="Troggar är aggressiva, underjordiska bestar som gräver genom fast berg och kringgår vanliga murar och befästningar ovan jord. Eftersom de utan förvarning kan bryta fram under vägar, bosättningar och gruvor ser dvärgarnas myndigheter deras okontrollerade spridning som ett existentiellt hot mot Ironforges säkerhet.",al={"trogg-hot","varför slåss mot troggar","är troggar farliga"}},{q="Vem ska jag tala med när jag har hjälpt Cobbleflint?",a="När du har decimerat leden av Stonesplinter-troggar och spejare hänvisar Cobbleflint dig till Mountaineer Gravelgaw, som står strax innanför det intilliggande vakttornet. Han sköter nästa del av patrulleringen längs dalfronten.",al={"nästa uppdrag","vart efteråt","gravelgaw"}},{q="Är Stonesplinter-troggarna organiserade?",a="Stonesplinter-klanen är primitiv, men uppvisar en enkel organisation genom att skicka ut särskilda spejare för att rekognoscera vägarna tillsammans med brutala fotsoldater, som håller försvarsläger i hela ravinen.",al={"troggspejare","är troggar smarta","stonesplinter-struktur"}}},fx={abec66b9={q="Varför vill Mountaineer Cobbleflint att troggerna ska gallras ut?",a="Mountaineer Cobbleflint ser troggernas angrepp som det största hotet mot Loch Modan och själva Ironforge. Varelserna gräver sig upp ur varje skreva och hotar Valley of Kings och de omgivande trakterna. Eftersom den reguljära dvärgarmén är utplacerad på avlägsna slagfält måste Cobbleflint förlita sig på djärva frivilliga för att minska deras svärmande antal innan de lokala tornen och bosättningarna blir helt övermannade.",al={"varför döda trogger","cobbleflints motiv","varför behöver cobbleflint få trogger dödade"}},["515fdd78"]={q="Vad gör Stonesplinter-troggerna i Loch Modan?",a="Stonesplinter-troggerna är vilda mutanter från underjorden som grävt sig upp i Lochs södra delar och upprättat läger i hela Stonesplinter Valley. Deras spejare sonderar oupphörligen dvärgarnas territorium och söker efter svagheter längs dalens vägar och nära det södra vakttornet. Om de lämnas i fred hotar deras snabba framryckning att skära av färdvägarna och översvämma trakten.",al={"vilka är troggerna","varför är stonesplinter-troggerna här","stonesplinter-troggernas mål"}}},fp="30,170,34.307.0,27.321.0,49.266.0,31.204.0,38.197.0,54.178.0,44.193.0,39.136.0"}
P.entries["quest:2242"] = {n="Destiny Calls",s="Destiny Calls är ett diskret uppdrag från Syurna för att hitta källan till den röta som sprider sig bland Teldrassils grenar. Du ska smyga förbi eller konfrontera en fientlig satyr vid namn Sethir the Ancient nära The Oracle Glade och hämta hans dagbok.",h="Destiny Calls är ett diskret uppdrag från Syurna för att hitta källan till den röta som sprider sig bland...",kw={"darkshore","darnassus","destiny calls","dagbok","the oracle glade","satyr","sethir the ancient","syurna","teldrassil"},ang={["class:Rogue"]="Det här uppdraget kommer från Darnassus egna tränare i smygande och prövar om en infiltratör kan stjäla känslig information rakt under näsan på en farlig satyr.",["faction:Alliance"]="Upptäckten knyter oron i Teldrassils skogar till en större korruption över hela kontinenten och banar väg för Alliansens styrkor på väg till norra Kalimdor.",["race:NightElf"]="För kaldoreiernas försvarare är beskedet att Darkshores uråldriga förbannelse har korsat havet till Teldrassil ett alarmerande hot mot deras heliga tillflykt."},sec={{t="En tyst spaning",b="Ledarna bland Night Elves i Darnassus har i tysthet oroat sig över Teldrassils växande sjukdom. I stället för att skicka ut beväpnade patruller som slutar döda söker skurkarnas tränare Syurna någon som kan arbeta diskret. Sethir the Ancient, en satyr som håller till på en avlägsen gren nära The Oracle Glade, har avvisat alla försök med våld och diplomati. För att ta reda på vad han vet måste du smyga in i hans tillhåll och lägga beslag på hans personliga tillhörigheter."},{t="Ett hot från Darkshore",b="De återfunna sidorna ur Sethirs dagbok avslöjar dystra sanningar. Den lömska smitta som hotar det nyfödda världsträdet har direkt samband med den uråldriga röta och korruption som slukar skogarna och vattendragen i Darkshore, på andra sidan det dimhöljda havet. Det handlar inte om en isolerad sjukdom i jorden. Plågan tyder på en större, avsiktlig illvilja som hotar kaldoreiernas hemland."}},faq={{q="Vem är Sethir the Ancient?",a="Sethir the Ancient är en svårfångad satyr som gömmer sig på en gren nära den norra utkanten av Teldrassils Oracle Glade. Han är fientlig och slug och har omintetgjort både militära angrepp och fredliga försök att ta reda på vad han vet om öns korruption.",al={"sethir","vem är sethir","satyr i oracle glade"}},{q="Varför vill Syurna ha Sethirs dagbok?",a="Syurna tror att Sethir vet viktiga saker om den onaturliga sjukdom som sprider sig genom Teldrassil. I hans personliga dagbok finns anteckningar om satyrens aktiviteter och den mörka smittans natur.",al={"varför sethirs dagbok","syurnas mål","vad finns i dagboken"}},{q="Vad avslöjar dagboken när uppdraget är slutfört?",a="Dagboken bekräftar att sjukdomen som tar över Teldrassils grenar hänger samman med den djupare, demoniska pest som greppar de uråldriga skogarna och kusterna i Darkshore på andra sidan sundet.",al={"dagbokens bakgrund","vad upptäckte sethir","samband med darkshore"}},{q="Var får man uppdraget?",a="Syurna, skurkarnas tränare i Darnassus skuggor, ger dig uppdraget när du har klarat en första prövning av din förmåga.",al={"var får jag destiny calls","uppdragsgivare för destiny calls","vem ger destiny calls"}},{q="Vart ska äventyrare ta vägen efter att ha slutfört uppdraget?",a="Syurna säger att det inte finns något mer du kan göra här i den här frågan och belönar din tjänst för Teldrassil med en klinga.",al={"what comes next","nästa steg efter destiny calls","efter sethir"}},{q="Varför sköter en skurkarnas tränare skogskorruptionen i stället för druider?",a="Vanliga metoder, både militära styrkor och druidisk diplomati, misslyckades mot Sethir med dödlig utgång. När öppna försök leder till blodiga återvändsgränder vänder sig Syurna till hemlig spaning och infiltration.",al={"varför skurkarnas uppdrag","varför syurna","varför inte cenarion circle"}}},fp="13,178,23.373.0,31.286.1,26.231.0,38.154.0,45.152.1,29.106.0,58.120.1,68.159.0"}
P.entries["quest:2258"] = {n="Badlands Reagent Run",s="I utposten Kargath behöver Jarkal Mossmeld, en framstående alkemist, reagenser från Badlands för att fylla på sina förråd. Han lovar mynt, men bara till den som kommer med varorna.",h="I utposten Kargath behöver Jarkal Mossmeld, en framstående alkemist, reagenser från Badlands för att fylla på...",kw={"alkemi","badlands","gamkråva","klippcoyotens huggtand","jarkal mossmeld","kargath","klippementalens skärva","uldaman"},sec={{t="Fyll på förråden",b="Jarkal Mossmeld saknar ingredienser: krävor från fem gamar, huggtänder från tio klippcoyoter och skärvor från fem klippementaler. Alla tre kan tas från varelserna själva. Den som inte är stridstyp får leta upp vänner som är det. Jarkal betalar med mynt, men först när du har reagenserna."},{t="Efter bytet",b="Jarkal är nöjd med bytet och säger att det bör räcka ett tag. Alkemisten behöver samla in fler reagenser, men de finns bara långt nere i utgrävningen vid Uldaman och blir inte lätta att få tag på. Jarkal antyder att ersättningen kan vara värd mer än blänkande mynt."}},faq={{q="Vem ber om de här reagenserna?",a="Jarkal Mossmeld, en framstående alkemist i utposten Kargath i Badlands, vill fylla på förråden.",al={"vem ger reagensrundan i badlands","jarkal mossmeld","vem är jarkal mossmeld"}},{q="Vilka ingredienser behöver Jarkal?",a="Krävor från fem gamar, huggtänder från tio klippcoyoter och skärvor från fem klippementaler. Allt kommer från varelserna själva.",al={"vilka föremål behövs","lista över reagenser i badlands","reagenser som behövs"}},{q="Var finns Jarkal Mossmeld?",a="Jarkal finns i utposten Kargath i Badlands.",al={"jarkal mossmelds plats","var finns alkemisten i kargath","var lämnar jag in reagensrundan i badlands"}},{q="Vad erbjuder Jarkal i utbyte mot ingredienserna?",a="Mynt, som betalas när du lämnar reagenserna till Jarkal i Kargath. Innan dess får du inget betalt.",al={"belöning för reagensrundan i badlands","vad får jag"}}},fp="20,192,20.320.0,14.266.1,33.120.0,34.142.0,33.53.0,55.91.0"}
P.entries["quest:2259"] = {n="Erion Shadewhisper",s="Erion Shadewhisper skickar en rak kallelse som leder nya Alliance-skurkar till Darnassus. Jannok Breezesong överlämnar meddelandet och hänvisar resenärerna till Cenarion Enclave, där Erion väntar på att föra deras uppdrag bortom de lokala gränserna.",h="Erion Shadewhisper skickar en rak kallelse som leder nya Alliance-skurkar till Darnassus.",kw={"cenarion enclave","darnassus","erion shadewhisper","erion's behest","jannok breezesong","vägvisaruppdrag för skurkar","syurna"},ang={["class:Rogue"]="Det här vägvisaruppdraget markerar övergången från nybörjararbete på Teldrassil och leder dig direkt till Erion Shadewhisper för uppdrag som kräver finess bortom startskogarna.",["faction:Alliance"]="Uppdraget leder Alliance-agenter i norra Kalimdor till att samordna sig med Darnassus kontaktpersoner innan de beger sig in i omstridda områden.",["race:NightElf"]="För Night Elf-skuggjägare är rapporteringen till Erion i Darnassus en viktig övergångsrit, från lokalt beskydd till uppgifter över hela kontinenten."},sec={{t="En kallelse till enklaven",b="När en skurk gör sig ett namn i trakterna kring Teldrassil ser Jannok Breezesong till att talangen inte går till spillo. För att stilla eventuell oro över att skickas till den krävande tränaren Syurna hänvisar Jannok i stället agenten direkt till hjärtat av Darnassus. Där, djupt bland Cenarion Enclaves grönskande grenar, övervakar Erion Shadewhisper uppdrag som kräver en tystare och mer subtil hand."},{t="Blicken mot horisonten",b="Att nå Erion markerar en viktig vändpunkt för varje skurk som verkar i Night Elf-områden. Hans hälsning gör klart att Teldrassils skyddande skogar inte längre rymmer en agents ansvar. Erions uppgift är att leda dugliga händer ut i en större och farligare värld och fungera som språngbräda till uppdrag på andra sidan havet."}},faq={{q="Vem skickar dig för att hitta Erion Shadewhisper?",a="Jannok Breezesong utfärdar kallelsen och säger åt dig att genast bege dig till Darnassus för att tala med Erion Shadewhisper i Cenarion Enclave.",al={"uppdragsgivare","vem startar erion shadewhisper","jannok breezesong uppdrag"}},{q="Var finns Erion Shadewhisper?",a="Erion Shadewhisper finns i Cenarion Enclave i Darnassus, bland träden på enklavens övre nivåer.",al={"erions plats","var finns erion","var hittar man erion shadewhisper"}},{q="Varför nämner Jannok Syurna?",a="Syurna är en framstående skurk-tränare i Darnassus, känd för sin stränghet och krävande träning. Jannok skämtar lättsamt för att försäkra dig om att du inte är i trubbel och inte ska släpas iväg till hennes hårda lektioner.",al={"vem är syurna","varför inte syurna","jannok och syurnas replik"}},{q="Vad händer efter att du rapporterat till Erion?",a="När du har avlagt rapporten ger Erion dig nästa uppgift i uppdraget Erion's Behest och skickar dig bort från Teldrassil för att utöka ditt verksamhetsområde i Kalimdor.",al={"vad händer sedan","uppföljning med erion","uppdrag efter erion shadewhisper"}},{q="Vilken sorts arbete övervakar Erion?",a="Erion samordnar verksamhet och vägleder oerfarna skurkar i Darnassus. Han fungerar som kontaktperson mellan lokala agenter och större uppdrag inom Alliance-nätverket.",al={"är erion en skurk-tränare","erion shadewhispers roll","vad gör erion"}},{q="Varför är en skurkkontakt stationerad i Cenarion Enclave?",a="Cenarion Enclave är främst känt för druider och naturdyrkan, men dess vidsträckta, skuggiga träd erbjuder gott om avskildhet där mer diskreta agenter kan samlas och sköta sina ärenden, långt från Temple of the Moon.",al={"skurk i cenarion enclave","varför druiderområde för skurkar"}}},fx={["8fe8a3c2"]={q="Varför skickar Jannok Breezesong dig till Erion?",a="Jannok Breezesong ger dig inget eget uppdrag, utan agerar budbärare. Erion Shadewhisper bad uttryckligen att du skulle komma till Cenarion Enclave för att pröva dina färdigheter och skicka dig bortom Teldrassil i takt med att din träning går framåt.",al={"varför skickar jannok dig","jannok breezesongs motiv","varför träffa erion shadewhisper"}}},fp="18,158,24.243.0,19.210.0,41.98.0,36.105.0,31.197.0,38.132.0,37.95.0,57.175.0"}
P.entries["quest:226"] = {n="Wolves at Our Heels",s="Wolves at Our Heels är ett uppdrag för Alliansen som Lars erbjuder vid Sven's Camp i västra Duskwood. Du får i uppgift att jaga de rabiata och utsvultna jättelika vargarna som stryker i skogarna runt omkring. Då hjälper du resenärer att undanröja de omedelbara hoten i vildmarken, så att Sven och Lars kan fokusera på sin vendetta mot nekromantikern Morbent Fel.",h="Wolves at Our Heels är ett uppdrag för Alliansen som Lars erbjuder vid Sven's Camp i västra Duskwood.",kw={"jättelik varg","duskwood","flash bundles","lars","morbent fel","rabid dire wolf","starving dire wolf","sven","svens läger"},ang={["class:Hunter"]="Att tämja eller gallra bland Duskwoods förvridna vilda djur kräver skärpt uppmärksamhet. De här jättelika vargarna är långt mer desperata och vildsinta än vanliga skogsdjur.",["faction:Alliance"]="När du hjälper Lars får Svens avlägsna läger en tryggare tillvaro, och en allierad utgångspunkt säkras i kampen mot de odöda styrkor som plågar västra Duskwood."},sec={{t="Ett utsatt läger",b="Undangömda bland Duskwoods västra kullar nära gränsen till Westfall håller Sven Yorgen och hans följeslagare Lars till vid en avlägsen utpost. Eftersom de bor långt från Darkshire är de helt beroende av att själva samla och jaga mat för att överleva. Men när Lars bär färskt villebråd genom de mörka skogarna blir han ett oemotståndligt mål för de glupska rovdjur som stryker längs de skuggiga flodbankarna och i snåren."},{t="Rensa skogen",b="De lokala flockarna av utsvultna och rabiata jättelika vargar strövar främst norr och öster om lägret, mot floden. När du gallrar bland dessa vildsinta bestar lättar du den omedelbara pressen på Lars jakt. Färre vargar gör att båda männen slipper kämpa för sitt dagliga bröd, så att de kan rikta all sin uppmärksamhet mot nekromantikern Morbent Fel, som håller till längre österut."}},faq={{q="Vem är Lars?",a="Lars är en stryktålig överlevare som hjälper Sven Yorgen i ett litet läger bland kullarna i västra Duskwood. Han sköter lägrets dagliga jakt och matinsamling, medan Sven är besatt av att hämnas på de mörka krafter som hotar regionen.",al={"lars","vem ger wolves at our heels","uppdragsgivare lars"}},{q="Var stryker vargarna omkring?",a="De jättelika vargarna strövar i skogarna alldeles norr och öster om Sven's Camp, särskilt längs flodstränderna som skiljer Duskwood från områdena norrut.",al={"var finns vargarna","var finns rabiata jättelika vargar","var finns utsvultna jättelika vargar"}},{q="Varför är de jättelika vargarna så aggressiva?",a="Vildmarken i Duskwood har förfallit under ett tilltagande mörker. Det finns ont om villebråd, så de jättelika vargarna svälter nästan. Sjukdom eller mörk förvridning har gjort många av dem rabiata och hänsynslöst våldsamma mot alla som bär på färskt kött.",al={"varför anfaller vargarna","rabiata vargar duskwood"}},{q="Vem är Morbent Fel?",a="Morbent Fel är en mäktig nekromantiker som utövar mörk magi från kyrkogården och gravhögarna i öster. Sven och Lars hyser ett bittert agg mot honom och förbereder sig på att ta honom av daga när de väl har säkrat sina grundläggande överlevnadsbehov.",al={"morbent fel","nekromantikern","vem är nekromantikern i öster"}},{q="Vad är Flash Bundles som Lars ger som belöning?",a="Flash Bundles är bländande ljusgranater som tillverkats av invånarna i Darkshire. Sympatiska invånare skänkte dem till Svens läger för att hjälpa honom i kampen mot de odöda och bestarna som hemsöker skogarna.",al={"flash bundles","lars belöning","vad är flash bundle"}},{q="Varför bor inte Sven och Lars i Darkshire?",a="En tragedi drabbade Svens familj och gjorde honom bitter och besatt av att skipa rättvisa på egen hand. I stället för att söka skydd bakom Night Watch i Darkshire slog sig Sven och Lars ner i vildmarken för att själva spåra upp de onda krafter som plågar skogarna.",al={"varför bo i ett läger","var ligger svens läger","varför inte i staden"}}},fx={e2641657={q="Varför vill Lars att de monstruösa vargarna dödas?",a="Sven och Lars lever isolerade i västra Duskwood och måste själva jaga för att överleva. Varje gång Lars försöker bära tillbaka kött till lägret överfaller flockar av glupska monstruösa vargar honom. När rovdjuren röjts undan tryggas lägrets matförråd, och de kan koncentrera sig på det hot som nekromantikern Morbent Fel utgör.",al={"varför döda vargarna","lars motiv med vargarna","varför vill lars ha vargar dödade"}},["8ad2a450"]={q="Vilka är de monstruösa vargarna som stryker omkring i västra Duskwood?",a="Dessa våldsamma bestar stryker omkring i skogarna och längs flodstränderna norr och öster om Svens läger. Svälten och sjukdomens spridning har drivit de utsvultna, rabiata vargarna till vårdslöst asätande. De dras genast till färskt kött och utgör en dödlig fara för alla som färdas genom den västra vildmarken.",al={"vilka är vargarna","utsvultna monstruösa vargar i duskwood","rabiata monstruösa vargar"}},["6ca73ecd"]={q="Varför kan inte Lars ta hand om vargarna själv?",a="Lars och Sven är ensamma vid ytterkanten av området, långt utom räckhåll för Night Watch och Stormwinds vakter. Lars är redan upptagen med förberedelserna inför kampen mot Morbent Fel och har knappt tid att jaga för dagen. Han har helt enkelt inte råd att strida mot hela flockar av våldsamma vargar utan hjälp från en äventyrare.",al={"varför dödar inte lars vargarna","varför be mig döda vargar","varför inte lars"}}},fp="19,200,17.296.0,18.261.0,12.199.0,30.140.0,38.231.0,19.203.0,50.188.0,42.230.0"}
P.entries["quest:2260"] = {n="Erion's Behest",s="Erion's Behest är en kallelse till lovande Night Elf-roguar verksamma i Darnassus. När deras gryende förmåga inom smygande uppmärksammas skickar rogue-mentorn Erion Shadewhisper dem över havet till Stormwind City, för att rapportera direkt till Stormwind Intelligence.",h="Erion's Behest är en kallelse till lovande Night Elf-roguar verksamma i Darnassus.",kw={"darnassus","erion shadewhisper","erion's behest","old town","renzik the shiv","rogue","si:7","stormwind"},ang={["class:Rogue"]="Den här kallelsen markerar att du lämnar lokala skärmytslingar i Kalimdor bakom dig och träder in i en större värld av spionage mellan kontinenter och dödlig träning under SI:7.",["faction:Alliance"]="SI:7 samordnar hemliga operationer för Alliansen och ser till att skickliga spejare från varje medlemsras kan skickas dit kronan behöver dem som mest.",["race:NightElf"]="Att lämna Darnassus och Teldrassils skydd för att tjäna människornas underrättelsenätverk i Stormwinds stenlagda gränder innebär ofta en rejäl kulturkrock för Kaldorei-spejare."},sec={{t="En kallelse över havet",b="Night Elf-roguar som verkar i Teldrassils skugga finslipar vanligtvis sina färdigheter under mentorer som Erion Shadewhisper. Men när en agent visar enastående talang sprids ryktet långt bortom världsträdets grenar. Genom Erion erbjuder Stormwind Intelligence, mer känt som SI:7, en direkt inbjudan att resa över Stora havet till människornas huvudstad."},{t="I SI:7:s tjänst",b="Resan är mödosam och för agenten från Kalimdors nordligaste trakter via hamnarna i Darkshore eller Wetlands till Stormwind Citys livliga gator. Väl i huvudstaden måste agenten smyga sig in i Old Town och rapportera till SI:7:s högkvarter. Där väntar Renzik \"The Shiv\" för att bedöma nykomlingen och öppna dörren till avancerat spionage, giftmästerskap och hemliga operationer på Alliansens uppdrag."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Erion Shadewhisper, rogue-tränaren i Darnassus, ger dig uppdraget när dina tidiga bedrifter väcker underrättelsenätverkens intresse på andra sidan havet.",al={"uppdragsgivare","erion shadewhisper","vem gav mig det här"}},{q="Varför kontaktar Stormwind Intelligence en Night Elf?",a="Även om Night Elves har egna traditioner inom smygande förlitar sig Alliansen i hög grad på SI:7 för att samordna hemlig underrättelseverksamhet och sabotage. Stormwind Intelligence söker regelbundet efter skickliga rogues från alla alliansraser för att stärka sina operativa led.",al={"varför si:7","varför stormwind","varför bryr sig människor"}},{q="Var hittar jag Renzik 'The Shiv'?",a="Renzik 'The Shiv' finns vid SI:7:s högkvarter, undangömt i stadsdelen Old Town i Stormwind City.",al={"var finns renzik","var är the shiv","hitta renzik"}},{q="Är det här uppdraget bara för rogues?",a="Ja. Det här är ett klassuppdrag för Alliance-roguar, avsett att vägleda agenter från Kalimdor till Alliansens centrala nav för underrättelseträning i Stormwind.",al={"bara för rogues","kan andra klasser göra det här","är det här ett rogue-uppdrag"}},{q="Vad händer efter mötet med Renzik?",a="När du rapporterar till Renzik blir du en del av SI:7:s träningsverksamhet i Eastern Kingdoms och får tillgång till specialiserad träning och hemliga uppdrag i människornas länder.",al={"nästa uppdrag","vad får jag","efter renzik"}},{q="Hur tar sig en Night Elf till Stormwind City i det här skedet?",a="En resenär kan ta skeppet från Auberdine i Darkshore. Det seglar rakt över havet till Stormwind Harbor.",al={"hur tar jag mig till stormwind","resa till stormwind","vägen till stormwind"}}},fx={["4c3449b0"]={q="Varför skickar Erion Shadewhisper dig till Stormwind?",a="Erion Shadewhisper agerar efter en formell kallelse från Stormwind Intelligence. Ditt växande rykte som skurk har nått mänskliga öron på andra sidan Stora havet, och SI:7 har bett särskilt om dig. Erion inser att det hemliga gillet i Old Town erbjuder specialiserad träning och resurser långt utöver vad Teldrassils stilla skuggor kan ge. Han uppmanar dig att ta vara på möjligheten i stället för att stanna isolerad i Darnassus.",al={"varför skicka dig till stormwind","erion shadewhispers motiv","varför erions begäran"}}},fp="14,223,24.273.0,28.325.0,29.144.0,53.208.0,34.75.0,30.127.0,34.171.0,57.85.0"}
P.entries["quest:2281"] = {n="Redridge Rendezvous",s="Lovande Alliance-rogues skickas österut från Stormwinds underrättelsehögkvarter för att tränas i Lakeshire. SI:7 vill att de ska vara redo för farliga uppdrag under erfarna agenter.",h="Lovande Alliance-rogues skickas österut från Stormwinds underrättelsehögkvarter för att tränas i Lakeshire.",kw={"lakeshire","lucius","redridge rendezvous","renzik the shiv","rogue-uppdrag","si:7","stormwind"},ang={["class:Rogue"]="Som rogue inleder du här ditt formella fältarbete för SI:7 och går från småskalig gatustöld till beräknat statligt spionage.",["faction:Alliance"]="Som medlem av Alliance ser du hur Stormwinds hemliga gren når ut till avlägsna bosättningar som Lakeshire, där lågmälda agenter är stationerade."},sec={{t="Ett mått av överlevnad",b="Renzik 'The Shiv', SI:7:s andreman i Stormwind, varnar för att otränade rogues sällan överlever farliga uppdrag. Att skicka oerfarna rekryter till fientligt territorium leder till förluster i stället för underrättelser. SI:7 skickar lovande agenter österut till Redridge Mountains, där de tränar under Lucius, som är stationerad bland Lakeshires bryggor."},{t="Ögon i Lakeshire",b="Lakeshire är en utmärkt plats för hemlig träning. Gnolls och Blackrock-orcher hotar gränsstaden, medan dess bryggor ger Lucius skydd att pröva en rogues smygförmåga, reflexer och låsdyrkning utan att väcka stadsbornas eller vakternas uppmärksamhet."}},faq={{q="Vem ger uppdraget Redridge Rendezvous?",a="Renzik 'The Shiv', en goblinmästare på spionage i Stormwinds Old Town, ger SI:7:s uppdrag från högkvarteret till rogues som rapporterar till underrättelseledningen.",al={"vem startar redridge rendezvous","uppdragsgivare för redridge rendezvous","vem ger uppdraget"}},{q="Var finns Lucius?",a="Lucius väntar längs Lakeshires träbryggor i Redridge Mountains, bland traktens dagdrivare och fiskare vid vattnet.",al={"var finns lucius","lucius plats","hitta lucius"}},{q="Varför skickar SI:7 rogues till Redridge?",a="Renzik anser att oerfarna rogues inte är lämpade för farligt underrättelsearbete. Lucius slipar bort deras ojämnheter och prövar färdigheter som ficktjuveri och låsdyrkning under gränsförhållanden.",al={"varför lakeshire","syftet med redridge rendezvous","varför redridge"}},{q="Vad händer när du har slutfört Redridge Rendezvous?",a="När du rapporterar till Lucius får du träningsövningar som börjar vid Alther's Mill, där agenten prövar sin smygförmåga och fingerfärdighet.",al={"nästa uppdrag","uppföljning till redridge rendezvous","efter redridge rendezvous"}},{q="Är uppdraget tillgängligt för andra klasser än rogues?",a="Nej. Redridge Rendezvous är för Alliance-rogues och ingår i deras fältträning hos SI:7.",al={"kan warriors göra redridge rendezvous","är uppdraget bara för rogues","klasskrav"}},{q="Varför arbetar Renzik för Stormwinds underrättelsetjänst?",a="Trots att han är goblin är Renzik 'The Shiv' en betrodd löjtnant till spionmästaren Mathias Shaw. Han ansvarar för rekrytering och träning av agenter från SI:7:s fäste.",al={"varför är en goblin med i si:7","renziks historia","goblin i stormwind"}}},fx={da1ebf68={q="Varför behöver Renzik mig till det här uppdraget?",a="SI:7 behöver nya agenter som kan hantera farligt hemligt arbete, men Renzik vet att det i princip är en dödsdom att kasta en oprövad skurk rakt in i aktiva fältoperationer. I stället för att slösa bort en lovande talang skickar han dig särskilt för att du ska vässa dina färdigheter under Lucius ledning innan du tar dig an uppdrag som kan kosta dig livet.",al={"varför behöver renzik mig","varför välja mig i redridge","varför skicka mig till lucius"}}},fp="19,183,21.327.0,17.237.0,40.154.0,24.120.0,38.206.0,48.117.0,53.85.0,48.160.0"}
P.entries["quest:2282"] = {n="Alther's Mill",s="Alther's Mill är ett avgörande träningsuppdrag som Lucius i Lakeshire ger till alliansens skurkar. De skickas till den närbelägna kvarnen med en uppsättning tjuvverktyg och ska infiltrera ett område under Blackrock-orkernas uppsikt, dyrka upp en låst kista och hämta en stöldbricka.",h="Alther's Mill är ett avgörande träningsuppdrag som Lucius i Lakeshire ger till alliansens skurkar.",kw={"alther's mill","blackrock-orcher","lakeshire","dyrka upp lås","lucius","redridge mountains","si:7","tjuvverktyg","token of thievery"},ang={["class:Rogue"]="Den här övergångsriten ger dig nödvändiga verktyg för att dyrka upp lås och fältmeriter, samtidigt som ditt tålamod och din smygförmåga sätts på prov bland patrullerande Blackrock-orcher.",["faction:Alliance"]="Genom att utbilda specialiserade tjuvar och infiltratörer i Lakeshires utkanter stärker alliansen sin underrättelsetjänst och håller samtidigt noggrann uppsikt över Blackrocks rörelser."},sec={{t="Ett prov i smidighet och finess",b="I Lakeshire slösar skurklärare inte tid på abstrakta föreläsningar när en låst kista kan lära ut samma sak snabbare. Lucius skickar lovande agenter nordost längs vägen till Alther's Mill och ger dem deras första uppsättning tjuvverktyg. För att få sitt officiella Certificate of Thievery måste noviserna smyga in i den övergivna kvarnen, dyrka upp Lucius personliga kassaskrin och ta med sig brickan som gömts därinne."},{t="Skuggor kring sågarna",b="Alther's Mill var en gång en vanlig timmerstation, men har nyligen väckt de Blackrock-orkers farliga intresse när de rycker fram genom Redridge. Lucius ser med förtjusning de krigiska inkräktarna som ett extra praktiskt prov. Att smyga genom fiendekontrollerat område och dyrka upp lås utan att bli upptäckt är precis den sorts prövning som SI:7 förväntar sig att dess agenter ska överleva."}},faq={{q="Vad är syftet med uppdraget till Alther's Mill?",a="Det är ett praktiskt fältprov för alliansens skurkar som lär sig konsten att dyrka upp lås. Lucius ger dig tjuvverktyg och kräver att du hämtar en särskild bricka ur en låst fotkista för att bevisa din finess.",al={"varför bege sig till alther's mill","uppdragets syfte","vad gör det här uppdraget"}},{q="Vem är Lucius?",a="Lucius är en erfaren skurktränare som verkar från Lakeshire i Redridge Mountains. I åratal har han utbildat skurkaktiga rekryter som kontakter i hela alliansen skickat till honom och prövat deras smygförmåga och fingerfärdighet.",al={"vem är lucius","lucius i lakeshire","vem ger uppdraget"}},{q="Var ligger Alther's Mill?",a="Alther's Mill ligger strax intill vägen, en bit nordost och öster om Lakeshire, inbäddad mot bergens fot innan de högre bergspassen.",al={"var ligger kvarnen","alther's mills plats","hur hittar jag alther's mill"}},{q="Varför finns det orcher vid Alther's Mill?",a="Orcher från Blackrock-klanen har kommit ned från Stonewatchs höjder och de brinnande bergskammarna ovanför. De plundrar mänskliga bosättningar och upprättar utposter i hela Redridge, även kring den övergivna kvarnen.",al={"varför är orcher här","blackrock-orcher i redridge","vem kontrollerar alther's mill"}},{q="Vilken belöning ger Lucius när uppgiften är slutförd?",a="Lucius ger dig Certificate of Thievery som bekräftelse på att du behärskar grunderna i låskolvar och dyrkar och nu kan tjänstgöra som fullt certifierad fältskurk.",al={"vad är belöningen","certificate of thievery","belöning när uppdraget slutförs"}},{q="Hur passar det här uppdraget in i skurkarnas utbildning i alliansen?",a="Skurkar i alliansens områden hänvisas av kontakter som Mathias Shaws SI:7-kontakter i Stormwind till ett möte med Lucius i Lakeshire. Uppdraget vid Alther's Mill är höjdpunkten i deras grundläggande fältutbildning.",al={"skurkarnas uppdragskedja","kopplingen till si7","uppföljning på mötet i redridge"}}},fx={bca91f0e={q="Varför skickar Lucius dig till Alther's Mill?",a="Lucius tränar blivande skurkar för Alliansen och vill pröva din praktiska fingerfärdighet under press. En låst kista nära Alther's Mill, ett område som Blackrock-orcer har trängt in i, tvingar dig att visa verklig färdighet i låsdyrkning i en fientlig miljö i stället för i ett bekvämt klassrum.",al={"lucius motiv","varför vill lucius ha det gjort","varför skicka mig till althers mill"}},["7e02fd2a"]={q="Vad ska Token of Thievery användas till?",a="Token of Thievery bevisar vad du har åstadkommit. Den ligger säkert inlåst i Lucius kista och är ett fysiskt bevis på att du lyckades ta dig in i Alther's Mill, dyrka upp låset och försvinna obemärkt. När du återlämnar den får du Lucius officiella Certificate of Thievery.",al={"token of thievery användning","vad är token of thievery","token of thievery syfte"}}},fp="13,177,27.266.0,23.251.0,52.148.0,14.163.0,31.126.0,40.198.0,55.151.0,64.218.0"}
P.entries["quest:23"] = {n="Ursangous's Paw",s="Det här uppdraget är beviset på att du fällt Ursangous, ett av Ashenvales mest ursinniga och legendariska rovdjur. För du dess avhuggna tass till Senani Thunderheart vid Splintertree Post vinner du ära bland Hordens spårare.",h="Det här uppdraget är beviset på att du fällt Ursangous, ett av Ashenvales mest ursinniga och legendariska...",kw={"ashenvale","ashenvale hunt","björn","halvmåneemblem","tass","senani thunderheart","splintertree post","ursangous"},ang={["class:Hunter"]="Att spåra upp och övervinna ett av Ashenvales äldsta och dödligaste rovdjur är ett ypperligt prov på fältkunskap, överlevnadsförmåga och stridsfärdighet.",["faction:Horde"]="Hordens jägare ser Ursangous som ett farligt byte vars nederlag ger ära vid Splintertree Post.",["race:Tauren"]="För tauren-jägare är det en helig handling att ta Ursangous tass: de hedrar besten och visar samtidigt sin stridsvilja och respekt för jaktens andar."},sec={{t="En trofé från den stora jakten",b="Som en del av Ashenvale Hunt får spårare med bas vid Splintertree Post i uppdrag att jaga de uråldriga bestar som härskar över den täta skogens trädkronor. Ursangous räknas till de vildaste toppredatorerna och är känd för att ha dödat många resande och krigare som korsat hans väg. Att fälla en sådan best är ingen liten bedrift, och hans tass är ett obestridligt fysiskt bevis på att den mäktiga varelsen till slut fått sin överman."},{t="Kopplingen till Night Elf",b="Vid närmare granskning av Ursangous tass syns ett litet emblem i form av en kvarts halvmåne, inristat eller märkt i köttet. När Senani Thunderheart får se det identifierar hon märket som ett tydligt tecken på kaldoreiinflytande. Night Elf tränar ofta skogens mäktiga bestar och knyter band till dem för att försvara sina heliga gränser. Ursangous var därför troligen mer än bara ett vilt rovdjur – han tjänade som en ovetande väktare eller ett vapen åt Alliansen."}},faq={{q="Vad är Ursangous?",a="Ursangous är en ovanligt stor och dödlig björn som strövar omkring i Ashenvales skogar. Både jägare och vägfarare fruktar honom. Han har krävt oräkneliga liv innan han föll för Hordens jakt.",al={"vem är ursangous","ursangous björn","ursangous bakgrund"}},{q="Vad betyder halvmåneemblemet på tassen?",a="Kvartshalvmåneemblemet är ett mysterium när du undersöker trofén. Senani Thunderheart kan granska det när du lämnar över tassen.",al={"halvmånemärke på tass","tassemblem","varför finns en halvmåne"}},{q="Vem ska jag lämna Ursangous tass till?",a="Tassen ska lämnas till Senani Thunderheart, tauren-jägarinnan som är stationerad vid Splintertree Post i östra Ashenvale.",al={"var lämnar man in tassen","vem vill ha ursangous tass","var finns senani thunderheart"}},{q="Hur passar det här in i Ashenvale Hunt?",a="Ursangous är ett av tre stora vidunder som jagas i Ashenvale Hunt, tillsammans med Shadumbra och Sharptalon. Du måste besegra alla tre och visa upp deras troféer för att fullborda riten.",al={"ashenvale hunt uppdragskedja","vad är jakten","jaktuppdragskedja"}},{q="Varför jagar Horden Ashenvales stora vidunder?",a="Hordens jägare, särskilt tauren och orcherna vid Splintertree Post, jagar dessa toppredatorer både för att pröva sin stridsförmåga och för att minska hoten nära sina sårbara försörjningslinjer och läger.",al={"varför jaga björnar","jaktlore vid splintertree"}},{q="Vad händer när jag lämnar in tassen?",a="När du har samlat troféerna från Ursangous och de andra utvalda bytena kommer Senani Thunderheart att erkänna din triumf i det avslutande provet, The Hunt Completed.",al={"nästa uppdrag efter tassen","vad följer efter ursangous"}}},fp="15,188,26.275.0,24.336.1,18.177.0,46.141.0,34.108.0,42.161.0,55.191.0,38.173.0"}
P.entries["quest:230"] = {n="Sven's Camp",s="Sven's Camp är ett Alliance-uppdrag i Duskwood som avslöjar en avgörande ledtråd om tragedin på Yorgen-gården. Genom att gräva fram en begravd, namnlös dagbok ur en jordhög på den övergivna gården får äventyrarna veta vem som bevittnade slakten på Sven Yorgens familj.",h="Sven's Camp är ett Alliance-uppdrag i Duskwood som avslöjar en avgörande ledtråd om tragedin på Yorgen-gården.",kw={"mörka ryttare","duskwood","hög med lös jord","skuggfigur","sven yorgen","yorgen-gården"},ang={["faction:Alliance"]="Undersökningen av massakern på Yorgen-gården är en del av Alliances bredare kamp för att förstå de mörka krafter som tränger in i Duskwood."},sec={{t="En ledtråd i jorden",b="Sven Yorgen var borta när mörka ryttare slog till mot hans gård. Han återvände och fann sin familj mördad och gården i ruiner. Försjunken i sorg och hämndlystnad skickade han allierade för att genomsöka gårdens ruiner. Begravd under en hög nyvänd jord låg en liten, jordfläckad bok, hastigt gömd där av en skuggfigur."},{t="Ett tyst vittne",b="När boken överlämnas till Sven i hans läger i de västra kullarna avslöjar den en kuslig detalj. Den bevisar att en skuggfigur såg den fruktansvärda massakern på hans familj. Dagboken ger inte Sven någon ro, utan får honom att söka efter den okända åskådaren och kräva svar."}},faq={{q="Vad är det för bok som hittades i jordhögen?",a="Det är en namnlös, jordfläckad dagbok som låg begravd på Yorgen-gården. Innehållet bevisar att en oidentifierad åskådare såg massakern på Sven Yorgens familj.",al={"vad är det här för bok","boken från svens gård","vad grävde jag upp"}},{q="Vart leder uppdraget härnäst?",a="När du lämnar boken till Sven Yorgen leder det direkt vidare till uppdraget 'The Shadowy Figure' och inleder sökandet efter det mystiska vittnet.",al={"what comes next","nästa uppdrag efter svens camp","vem är skuggfiguren"}},{q="Var finns Sven Yorgen?",a="Sven har sökt skydd i ett läger i de nordvästra kullarna i Duskwood. Där sörjer han sin familjs öde och planerar sin hämnd.",al={"var är sven","sven yorgens plats","var lämnar jag in det här"}},{q="Varför begravdes boken på gården?",a="Boken gömdes i en hög lös jord bland gårdens ruiner, antingen hastigt övergiven eller gömd av åskådaren som dröjde sig kvar efter angreppet.",al={"varför begravdes den","vem gömde boken","hög med lös jord"}},{q="Vem dödade Svens familj?",a="Mörka ryttare från Deadwind Pass stormade gården medan Sven var borta och slaktade hans familj.",al={"vem angrep gården","vem dödade svens familj","svens familjs mördare"}},{q="Vilken fraktion kan slutföra uppdraget?",a="Uppdraget är exklusivt för Alliance-spelare, eftersom Sven Yorgen bara söker hjälp från Duskwoods försvarare och Alliance.",al={"är uppdraget bara för alliance","kan horde göra svens camp"}}},fp="11,160,18.304.0,16.246.1,44.167.0,32.114.0,29.118.0,36.165.0,25.89.0,37.109.0"}
P.entries["quest:2300"] = {n="SI:7",s="I Goldshire skickar Keryn Sylvius lovande unga skurkar till Stormwinds dolda led. Rekryterna anmäler sig hos Renzik \"The Shiv\" i Old Town, där de träder i Master Mathias Shaws tjänst.",h="I Goldshire skickar Keryn Sylvius lovande unga skurkar till Stormwinds dolda led.",kw={"keryn sylvius","mathias shaw","old town","renzik the shiv","skurk","sentinel hill","si:7","stormwind"},ang={["class:Rogue"]="Som skurk tar den här kallelsen dig från lokala uppdrag till tjänst som agent i Stormwinds officiella underrättelsegren.",["faction:Alliance"]="Som medlem i Alliansen kan du vända dig till SI:7 för farligt spionage utanför vanliga marskalkers och infanteristers räckvidd."},sec={{t="En kallelse till Old Town",b="Keryn Sylvius håller uppsikt över lokala rekryter från Lion's Pride Inn i Goldshire. När en skurk visar sig listig och skicklig mot det växande Defias-hotet vidarebefordrar Sylvius ett meddelande från högkvarteret. Ordern är tydlig: anmäl dig hos Renzik \"The Shiv\" utan dröjsmål. Rekryten lämnar Elwynn-fälten och beger sig till Stormwinds dolda hjärta."},{t="Stormwinds dolda ögon",b="SI:7 har sitt högkvarter bakom en anspråkslös kasern i Old Town. Master Mathias Shaw leder myndigheten, vars arbete omfattar hemliga operationer, spaning och lönnmord i kungariket och bortom dess gränser. Renzik \"The Shiv\", Shaws skarptungade andreman, bedömer lovande agenter innan han skickar dem på farliga uppdrag utanför kungarikets reguljära militärs räckvidd."}},faq={{q="Vem skickar mig att anmäla mig till SI:7?",a="Keryn Sylvius, skurkarnas tränare på Lion's Pride Inn i Goldshire, skickar dig att anmäla dig till SI:7. När du har visat vad du går för ute på fältet ger Sylvius dig order att bege dig till högkvarteret i Stormwind.",al={"vem ger uppdraget","uppdragsgivare","keryn sylvius"}},{q="Vem är Renzik \"The Shiv\"?",a="Renzik \"The Shiv\" är en goblinagent och SI:7:s andreman under Master Mathias Shaw. Han bedömer fältagenter och samordnar hemliga underrättelseuppdrag från högkvarteret i Old Town.",al={"renzik the shiv","vem är renzik","renzik"}},{q="Vad är SI:7?",a="SI:7, eller Stormwind Intelligence, sköter hemligt spionage, spaning och lönnmord för kungariket Stormwind. Organisationen leds av Mathias Shaw, och dess agenter samlar in underrättelser om hot som kungarikets vakter och soldater inte kan hantera.",al={"vad är si7","vad gör si7","stormwind intelligence"}},{q="Var ligger SI:7:s högkvarter?",a="SI:7:s högkvarter ligger i östra Old Town i Stormwind City. Organisationen verkar från ett befäst gillehus och en träningskasern, avskilt från huvudgatorna.",al={"var finns si7","si7 plats","var finns renzik"}},{q="Vad händer efter att jag har anmält mig hos Renzik?",a="När du har anmält dig hos Renzik prövar han om du är redo och skickar dig sedan utanför stadsmurarna för att träffa en agent som är stationerad i Redridge.",al={"nästa uppdrag","vad händer sedan","möte i redridge"}},{q="Varför kallar Keryn Sylvius mig för ”fisk”?",a="”Fisk” är slang för en oprövad nybörjare eller rekryt. Organisationens agenter använder färgstarka, bitska öknamn för att hålla nykomlingar ödmjuka tills de bevisar vad de går för på riktiga uppdrag.",al={"varför kallas jag fisk","betydelsen av fisk"}}},fx={d2c94cb8={q="Varför skickar Keryn Sylvius mig till SI:7?",a="Keryn Sylvius följer order från högre ort. Renzik \"The Shiv\" meddelade särskilt att han sökte dig, och Keryn vet bättre än att ignorera en kallelse från Mathias Shaws andreman. I Stormwinds underrättelsetjänsts hemliga hierarki vidarebefordrar mellanhänder som Keryn genast ordern när Renzik kallar in en agent, utan att låta högkvarteret vänta.",al={"varför skickar keryn mig","keryn sylvius motiv","varför rapportera till si7"}},fe886311={q="Varför behöver SI:7 mig i stället för sina egna agenter?",a="Renzik \"The Shiv\" bad uttryckligen efter dig vid namn. Som en lovande skurk inom Alliansens nätverk är du en ny talang som ännu inte är under de lokala motståndarnas direkta uppsikt. Master Shaw och Renzik förlitar sig ofta på skickliga, nyprövade fältagenter för diskreta uppdrag runt om i kungariket, där erfarna och välkända ansikten kan väcka oönskad uppmärksamhet.",al={"varför jag för si7","varför vill renzik ha mig","varför kalla på mig"}}},fp="4,166,21.292.0,23.413.0,31.202.0,25.204.0,13.239.0,39.159.0,39.136.1,38.183.0"}
P.entries["quest:233"] = {n="Coldridge Valley Mail Delivery",s="Coldridge Valley Mail Delivery är ett enkelt buduppdrag som Sten Stoutarm ger rekryter vid Anvilmar. När bergspassen ofta täpps igen av snö och troggs tränger sig nära inpå, håller färsk post till lägren vid den frusna sjön dalens isolerade försvarare i kontakt med varandra.",h="Coldridge Valley Mail Delivery är ett enkelt buduppdrag som Sten Stoutarm ger rekryter vid Anvilmar.",kw={"anvilmar","coldridge valley","dun morogh","grelin whitebeard","postutdelning","sten stoutarm","talin keeneye"},ang={["faction:Alliance"]="Varje utpost i Coldridge Valley bidrar till att hålla Dun Morogh säkert, så tillförlitlig post är viktig för den tidiga militära samordningen.",["race:Dwarf"]="Att bära meddelanden mellan utposterna visar Ironforge-dvärgarnas gemensamma uthållighet och håller även avlägsna spejare i dalen knutna till sina klaner.",["race:Gnome"]="Som gäster och allierade i Dun Morogh efter Gnomeregans fall stärker hjälpen med att hålla kommunikationslinjerna öppna förtroendet hos de lokala dvärgarna som försvarar området."},sec={{t="Ett bud i snön",b="Livet i Coldridge Valley är avskilt även under de lugnaste årstiderna. När vinterbud lyckas ta sig genom bergspasset med post från resten av Dun Morogh, samlas breven snabbt vid Anvilmar. Sten Stoutarm, som har fullt upp med lokala försörjningsfrågor och säkerhet, förlitar sig på kringvandrande rekryter som kan bära buntarna längs den västra vägen i stället för att låta viktiga meddelanden bli liggande i hallen."},{t="Utposter vid gränsen",b="Den avsedda mottagaren, Talin Keeneye, håller vakt vid den frusna sjön i väster och spanar efter troggs rörelser och farligt vilt. Även ute i kylan är nyheter från Ironforge och de omgivande utposterna värdefulla. Men postsortering under hårda bergsförhållanden blir sällan helt felfri, och brev till olika spejare följs ofta åt i samma bunt."}},faq={{q="Vem startar postutdelningen?",a="Sten Stoutarm ger dig utdelningsuppdraget utanför Anvilmar. Han har fått en bunt brev som nyligen förts genom bergspasset, men kan inte lämna sina uppgifter för att själv leverera dem.",al={"uppdragsgivare","vem ger coldridge valley mail delivery","sten stoutarm uppdrag"}},{q="Var finns Talin Keeneye?",a="Talin Keeneye har slagit läger väster om Anvilmar, precis intill vägen vid den frusna sjön i Coldridge Valley.",al={"var är talin keeneye","talin keeneyes plats","hitta talin keeneye"}},{q="Är alla breven i bunten verkligen till Talin?",a="Nej. När Talin går igenom bunten upptäcker han att ett av breven är adresserat till Grelin Whitebeard, som är stationerad i närheten i dalen.",al={"är all post till talin","brev till grelin whitebeard","felsorterad post"}},{q="Varför behöver Sten en äventyrare som kan dela ut posten?",a="Anvilmar hanterar aktivt troggintrång och lokala hot, så dvärgar som Sten är upptagna med brådskande försörjnings- och försvarsuppgifter. Förbipasserande och unga rekryter är det snabbaste sättet att få ut breven till avlägsna poster.",al={"varför dela ut posten","varför delar sten inte ut posten","postutdelning"}},{q="Leder det här uppdraget till fler uppgifter?",a="Ja. När du har slutfört utdelningen ber Talin dig ta det felsorterade brevet till Grelin Whitebeard som nästa del i postutdelningen.",al={"nästa uppdrag","postkedja","fortsättning på postutdelningen"}},{q="Varifrån kom breven ursprungligen?",a="Breven kom genom passet in i Coldridge Valley, från de vidare landområdena i Dun Morogh och Ironforge in till den skyddade dalen.",al={"varifrån kom posten","brevens ursprung"}}},fx={bf556c8e={q="Varför vill Sten Stoutarm att breven levereras?",a="En ny bunt brev kom just genom bergspasset, men Sten är upptagen med sina egna plikter vid Anvilmar och kan inte själv ge sig av med dem. I stället för att låta viktiga nyheter och rapporter samla damm medan bergsvakter ute i fält väntar på besked, förlitar han sig på en hjälpsam resenär som kan se till att de kommer säkert fram längs vägen.",al={"varför leverera breven","sten stoutarms motiv","varför skicka posten"}}},fp="30,181,21.258.0,17.299.0,29.159.0,31.99.0,52.86.1,49.173.0,36.124.1,43.108.0"}
P.entries["quest:234"] = {n="Coldridge Valley Mail Delivery",s="Det här ärendet slutför en budrunda genom Coldridge Valleys snötäckta vidder. När bergsspejaren Talin Keeneyes försändelse förs vidare längs den sydöstra vägen hålls Grelin Whitebeard i kontakt med dvärgarnas huvudstad.",h="Det här ärendet slutför en budrunda genom Coldridge Valleys snötäckta vidder.",kw={"coldridge valley","bud","dun morogh","grelin whitebeard","ironforge","postleverans","talin keeneye"},ang={["faction:Alliance"]="Pålitliga budrutter genom förrädiska snöpass förser avlägsna spejare i Alliansen med order och viktig information.",["race:Dwarf"]="Varje utpost i Dun Morogh är beroende av försändelser från kung Magni i Ironforge för att samordna rikets försvar."},sec={{t="En länk till bergen",b="Även i en avlägsen dal som Coldridge Valley måste nyheter och officiell korrespondens färdas. Anvilmar är dalens administrativa centrum, men fältspanare och vakter längs stigarna förlitar sig på bud till fots för att vidarebefordra försändelser mellan de höga passen och Ironforge."},{t="Besked till Whitebeard",b="Grelin Whitebeard håller ett litet läger längre ner längs vägen sydost om Talin Keeneyes postering. Veteraner bland bergsspejarna vid dessa avlägsna utkiksposter står ut med iskalla snödrivor och ständiga troggangrepp. De behöver regelbundna meddelanden för att hålla sig underrättade om vad som händer i Dun Morogh och riket bortom."}},faq={{q="Vem är Grelin Whitebeard?",a="Grelin Whitebeard är en dvärgveteran stationerad vid en utpost längs den sydöstra vägen i Coldridge Valley. Han bevakar dalens vägar och håller utkik efter lokala hot, som framryckande trogger och vilddjur.",al={"grelin","information om grelin whitebeard","vem är grelin"}},{q="Varifrån kommer brevet?",a="Brevet skickades från dvärgarnas huvudstad Ironforge. Lokala löpare och vakter förde det in i Coldridge Valley och bar det nerför bergspassen till mottagaren.",al={"varifrån kommer brevet","brev från ironforge","brevets avsändare"}},{q="Varför levereras posten till fots här?",a="Coldridge Valley omges av branta, frostbitna toppar och är avskuret från Dun Moroghs huvudvägar. Gryffonrutter går inte ända fram till de avlägsna fältlägren, så betrodda resenärer och bergsspejare bär försändelser för hand mellan utposterna.",al={"varför bud till fots","varför springa med posten","inga brevlådor i coldridge"}},{q="Var ligger Grelin Whitebeards läger?",a="Hans läger ligger längre ner längs den sydöstra vägen genom Coldridge Valley, förbi jakt- och spaningsmarkerna vid det övre passet.",al={"var ligger grelins läger","grelin whitebeards plats","hitta grelin"}},{q="Vem lämnade över brevet till Grelin?",a="Talin Keeneye, en erfaren jägare och spejare stationerad längs passet, lämnade över brevet efter att det förts från det främsta samlingsområdet nära Anvilmar.",al={"vem gav brevet","talin keeneyes roll","vem startar uppdraget"}},{q="Vad händer när Grelin får sin post?",a="När Grelin får nyheterna från Ironforge riktar han uppmärksamheten mot de akuta farorna som hotar dalen. Ofta skickar han rekryter för att hjälpa till mot Frostmane-trollens och troggernas intrång.",al={"vad händer efter posten","grelin whitebeards nästa uppdrag","efter postleveransen"}}},fx={c573251b={q="Varför vill Talin Keeneye att det här blir gjort?",a="Talin Keeneye är posterad ute i kylan längs vägen och vet att Grelin Whitebeard väntar i sitt läger utan några nyheter. Talin har tagit med sig rapporten från Anvilmar och vill se till att hans dvärgkamrat äntligen får sin post från Ironforge, så att han inte blir kvar i dalen utan besked.",al={"varför behöver talin få det levererat","talin keeneyes motiv","varför skicka brevet till grelin"}},d47c3713={q="Varför ber Talin Keeneye dig att leverera brevet i stället för att ta det själv?",a="Talin Keeneye håller vakt längs vägen genom Coldridge Valley och spanar efter faror på stigarna och i den lokala faunan. Om han övergav sin post för att gå hela vägen ner till Grelin Whitebeards läger skulle passet lämnas obevakat. Därför är en förbipasserande resenär som du det självklara valet för att bära brevet resten av vägen.",al={"varför behöver talin mig","varför kan inte talin leverera brevet","varför jag åt talin"}}},fp="30,185,22.157.0,19.257.0,25.155.0,32.162.0,35.200.0,42.147.0,47.130.0,44.144.0"}
P.entries["quest:235"] = {n="The Ashenvale Hunt",s="Warcaller Gorlach skickar Horden norrut till Ashenvale för att delta i jakten. Rapportera till Senani Thunderheart vid Splintertree Post, där Horden flyttar fram sin gräns in i den uråldriga skogen.",h="Warcaller Gorlach skickar Horden norrut till Ashenvale för att delta i jakten.",kw={"ashenvale","the barrens","gorlach","jakt","orgrimmar","senani","splintertree","thunderheart"},ang={["class:Hunter"]="Som jägare finner du en prövningsplats i Ashenvales täta lövverk och bland dess farliga bestar när du svarar på Senani Thunderhearts kallelse.",["faction:Horde"]="Som medlem av Horden för du dess räckvidd bortom Durotar, in i resursrika men fientliga främmande länder.",["race:Tauren"]="Som tauren kan du under Senani Thunderhearts ledning föra din djupa vördnad för den stora jakten till den otämjda skogen."},sec={{t="Vildmarkens kallelse",b="Orgrimmar behöver timmer, kött och säkra handelsvägar för att fortsätta växa. Warcaller Gorlach förmedlar order från Hordens högsta ledning och skickar erfarna vandrare och nya äventyrare till pågående fälttåg. För dem som blir vuxna i Durotar och The Barrens är Ashenvale nästa prövning av skicklighet och överlevnadsförmåga."},{t="En förrädisk gränsmark",b="Norr om The Barrens har Ashenvale två fästen som tillhör Horden. Splintertree Post ligger i de östra skogarna, medan Zoram'gar Outpost ligger längs västkusten. Senani Thunderheart samordnar verksamheten från Splintertree Post och organiserar spårare och jägare som ska möta bestarna under lövverket och nattalvernas vaktposter som gör anspråk på skogen."}},faq={{q="Vem ger uppdraget och var hittar jag personen?",a="Warcaller Gorlach ger ordern i Orgrimmar, Hordens huvudstad. Han kallar dugliga äventyrare till fälttåg bortom Durotar.",al={"uppdragsgivare","var finns gorlach","vem ger ashenvale-jakten"}},{q="Var ligger Splintertree Post?",a="Splintertree Post ligger norr om The Barrens i östra Ashenvale, längs skogsvägen österut mot Azshara.",al={"splintertrees läge","var ligger splintertree post","hur tar man sig till splintertree"}},{q="Vem är Senani Thunderheart?",a="Senani Thunderheart är en erfaren tauren-spårare vid Splintertree Post. Hon leder jakten genom Ashenvale och bedömer äventyrare som vill delta i de lokala prövningarna.",al={"vem är senani","senani thunderhearts plats","inlämnings-npc"}},{q="Vad är syftet med jakten i Ashenvale?",a="Jakten säkrar vilt och värdefulla hudar och röjer undan toppredatorer som hotar patruller nära Splintertree Post och närliggande skogsavverkning.",al={"varför jaga i ashenvale","ashenvale-jaktens berättelse","hordes mål i ashenvale"}},{q="Vilka andra utposter har Horde i Ashenvale?",a="Horden håller också Zoram'gar Outpost vid Ashenvales yttersta västra kant, längs The Zoram Strand.",al={"hordes baser i ashenvale","zoram strand-utpost","utposter i ashenvale"}},{q="Innebär uppdraget strid?",a="Nej. Du reser från Orgrimmar genom The Barrens för att rapportera till Senani Thunderheart. Resan i sig kräver ingen strid.",al={"är det strid i uppdraget","måste jag slåss mot något","enkel inlämning"}}},fx={["70907bc1"]={q="Varför vill Warcaller Gorlach skicka äventyrare till Ashenvale?",a="Warcaller Gorlach är härold och rekryterare i Orgrimmar och kallar på ivriga krigare för att stärka Hordens fälttåg vid gränsen. Horden har skaffat sig ett fäste i Ashenvale med Splintertree Post och utposten vid The Zoram Strand, men det krävs en stadig ström av dugliga kämpar för att upprätthålla och försvara närvaron där. Genom att visa dig till Senani Thunderhearts jakt stärker Gorlach den norra gränsen och ger beprövade rekryter en chans att vinna ära och berömmelse för Horden.",al={"warcaller gorlachs motiv","varför skicka till ashenvale","varför gorlachs jakt"}}},fp="18,189,17.306.0,22.356.0,48.124.0,27.113.0,27.165.0,42.149.0,53.100.0,35.123.0"}
P.entries["quest:2359"] = {n="Klaven's Tower",s="Agent Kearnen håller uppsikt över Klaven's Tower från ett läger i Westfall. Märkliga leveranser och förändrade vakter tyder på ett hot inom Defias Brotherhood.",h="Agent Kearnen håller uppsikt över Klaven's Tower från ett läger i Westfall.",kw={"agent kearnen","defias brotherhood","duskwood chest","klaven mortwake","klaven's tower","mathias shaw","gifter","si:7","westfall","zanzil"},ang={["class:Rogue"]="Som en alliansskurk ställs du inför en hemlig infiltration som kräver smygande, fickstöld, låsdyrkning och att hitta en fiendes fysiska svaghet.",["faction:Alliance"]="Defias vid Klaven's Tower har gått samman med djungeltroll och mörk alkemi för att hota kungariket. De är mer än förbittrade murare.",["race:Human"]="Som mänsklig försvarare av Stormwind kan du bli förskräckt när du upptäcker att före detta landsmän har förvandlats till viljelösa odöda drönare i Westfall."},sec={{t="Spaning i Westfall",b="Nära floden vid Westfalls sydöstra gräns reser sig Klaven's Tower norr om Dagger Hills. Defias Brotherhood gör anspråk på stenspiran, även om dess mänskliga tjuvar och rövare är vanliga över slätterna. Agent Kearnen har bevakat den ensam i veckor och lagt märke till märkliga förändringar. En besynnerlig leverans kom nyligen direkt från Duskwoods skuggiga skogar. Monstruösa, vanställda vaktposter eskorterade den, olikt vanliga landsvägsrövare."},{t="Spiran och de taggiga vakterna",b="Klaven Mortwake styr tornet, där märkligt förändrade vaktposter andas tungt och ansträngt. En väldig zombie bland de hasande vakterna bär Defias Tower Key, och att ta den kräver tystnad och finess. Med nyckeln kan en agent ta sig förbi försvaret på marknivå, nå fästningens övre våningar och öppna den hänglåsta Duskwood Chest."},{t="Zanzils brygd",b="Klaven Mortwakes privata dagbok knyter samman Defias, Venture Company och djungeltrollen i Stranglethorn. I skrifterna står det att häxdoktorn Zanzil upptäckte ett alkemiskt gift som kan väcka viljelösa, lydiga odöda drönare. För Master Mathias Shaw och SI:7 avslöjar upptäckten Defias växande ambitioner. Dess agenter behöver goda kunskaper om gifter."}},faq={{q="Var ligger Klaven's Tower?",a="Klaven's Tower står vid Westfalls sydöstra gräns, nära floden och norr om Dagger Hills. Defias Brotherhood håller den befästa spiran.",al={"klavens tower plats","var ligger klavens tower","defias torn plats westfall"}},{q="Vem är Agent Kearnen?",a="Agent Kearnen arbetar för Stormwinds underrättelsetjänst, SI:7. I hemlighet har hon bevakat Klaven's Tower från ett närbeläget läger i flera veckor, följt märkliga leveranser och planerat en infiltration.",al={"agent kearnen","vem ger uppdraget klaven's tower","vem är skurken i westfall"}},{q="Vad gör vakterna vid Klaven's Tower ovanliga?",a="Tornets vaktposter är förändrade odöda, olikt Defias vanliga mänskliga banditer. En exotisk alkemisk brygd som skeppades in i Westfall gjorde dem till viljelösa arbetare.",al={"varför är vakterna zombier","klaven towers vakter","vad är tornvakterna"}},{q="Hur fick Defias odöda tjänare?",a="Defias fick en specialiserad giftbrygd från Zanzil, en häxdoktor bland djungeltrollen i Stranglethorn Vale. Giftet kom genom affärer med Venture Company och förvandlar levande varelser till lydiga drönare.",al={"hur fick defias zombier","varför har defias odöda","zanzils koppling till defias"}},{q="Vem är Klaven Mortwake?",a="Klaven Mortwake är en högt uppsatt tillsynsman för Defias vid tornet. Han övervakade mörka leveranser från Duskwood och förde en privat dagbok om deras illavarslande alkemi.",al={"klaven mortwake bakgrund","vem är klaven mortwake","klaven"}},{q="Varför bryr sig Mathias Shaw om den återfunna dagboken?",a="Master Mathias Shaw behöver användbar information om Defias allianser och farliga utländska agenter. Uppgiften om att Zanzils troll kan skapa odöda med gift varnar SI:7 för ett allvarligt hot mot Stormwind, så myndigheten måste utbilda sina agenter i giftlära.",al={"varför vill mathias shaw ha dagboken","si7 zanzils gift","mathias shaw klaven"}}},fx={af44437f={q="Varför vill Agent Kearnen att det här blir gjort?",a="Agent Kearnen har bevakat Klaven's Tower i flera veckor och följt Defias verksamhet. När en kuslig leverans anlände från Duskwood, bevakad av omänskliga varelser, förstod hon att brödraskapet dolde något farligt. Hennes uppdrag för SI:7 är övervakning och underrättelseinhämtning. Om hon avslöjar vad som är låst i kistan får hon veta vilken ondskefull plan Defias smider mitt framför näsan på Stormwind.",al={"kearnens motiv","varför behöver agent kearnen detta","kearnens anledning"}},["043ff283"]={q="Vad ska Defias Tower Key användas till?",a="Defias Tower Key ger tillträde till det tungt befästa fästet och kistan från Duskwood som finns där inne. Nyckeln bärs av ett av de groteska, taggiga vidunder som patrullerar utanför. Den är ditt enda sätt att kringgå Defias lås och undersöka vad deras märkliga allierade har smugglat in i Westfall.",al={"defias tower key","vad låser upp klavens torn","tornnyckelns användning"}},d5d17d25={q="Vad är Klaven Mortwake's Journal?",a="Den här dagboken ligger inlåst i kistan från Duskwood högst upp i tornet och innehåller Klaven Mortwakes anteckningar och hemligheter. Den beskriver hur Defias Brotherhood samarbetade med utomstående krafter för att brygga vidriga hopkok. Där avslöjas det att märkliga drycker från Zanzils troll kan framkalla ett tillstånd av levande död och skapa viljelösa drönare.",al={"klaven mortwakes dagbok","klavens dagbok","vad står i dagboken"}},["738a266c"]={q="Varför skickar Agent Kearnen dig i stället för att gå själv?",a="Agent Kearnen är en spejare för SI:7 vars främsta uppdrag är långvarig spaning. Om hon röjde sin täckmantel genom att ta sig in i en befäst utpost som kryllar av onaturliga vakter skulle hon äventyra sin position och varna Defias innan SI:7 får veta vad de planerar. Hon behöver en skicklig agent som kan smita förbi vakterna, säkra underrättelserna och lämna dem direkt till Mathias Shaw.",al={"varför jag vid klavens torn","varför tar inte kearnen sig in","varför skicka mig"}}},fp="14,146,22.434.0,30.342.1,19.366.2,32.145.0,21.189.0,48.164.1,41.214.1,23.160.0,55.252.1"}
P.entries["quest:237"] = {n="In Defense of the King's Lands",s="Det här militära uppdraget ber Alliansens äventyrare att hejda ett trogganfall i södra Loch Modan åt Mountaineer Gravelgaw. Dvärgarnas reguljära styrkor är upptagna i avlägsna allianskampanjer, så lokala utposter måste förlita sig på frivilliga för att rensa bort farliga Stonesplinter Skullthumpers och Seers innan Valley of Kings blir övermannad.",h="Det här militära uppdraget ber Alliansens äventyrare att hejda ett trogganfall i södra Loch Modan åt...",kw={"gravelgaw","ironforge","loch modan","mountaineer","seer","skullthumper","stonesplinter","troggar","valley of kings"},ang={["faction:Alliance"]="Uppdraget blottlägger de höga kostnaderna för Alliansens krig och visar hur försvaret av avlägsna områden har gjort medlemsfolkens hemländer sårbara för inhemska hot.",["race:Dwarf"]="För en dvärg är det personligt att försvara Valley of Kings. Marken hedrar Ironforges största härskare, och det svider att se troggfötter vanhelga den medan ens släkt blöder på avlägsna slagfält."},sec={{t="Ett tunt försvar",b="Mountaineers som är stationerade längs det södra passet mot Dun Morogh är farligt underbemannade. King Magni Bronzebeard har skickat en stor del av dvärgarnas militära styrka till Alliansens bredare front, så utposter som Valley of Kings vakttorn saknar reguljärt infanteri. Mountaineer Gravelgaw förlitar sig på frivilliga utifrån för aggressiva räder in i Stonesplinter Valley, där de håller inkräktarna från underjorden stången medan de lokala garnisonerna väntar på förstärkningar som kanske aldrig kommer."},{t="Stonesplinter-shamaner och slagskämpar",b="Stonesplinter-troggarna är inga tanklösa bestar som irrar omkring utan mål. Deras krigarskaror samordnar sig med råstyrka och primitiv elementarmagi. Gravelgaw siktar in sig på stammens erfarna krigare, Skullthumpers, och dess mystiska ledare, Seers. När dessa befälhavare i främsta ledet slås ut tappar stammen farten, dess södra läger hamnar i oordning och ett massanfall mot vägen till Ironforge kan förhindras."},{t="Mörka bud från fronten",b="När du rapporterar att uppdraget lyckats delar Gravelgaw med sig av dystra nyheter: de utlovade dvärgförstärkningarna kommer inte. Stora förluster på Alliansens avlägsna front har tömt Ironforges reserver, så Loch Modan är helt beroende av lokala mountaineers och kringresande legosoldater för att skydda rikets hjärtland."}},faq={{q="Var finns Mountaineer Gravelgaw?",a="Mountaineer Gravelgaw är stationerad i det södra vakttornet längs vägen genom Valley of Kings. Där bevakar hon passet mellan Loch Modan och Dun Morogh.",al={"gravelgaws plats","var finns gravelgaw","lämna in till gravelgaw"}},{q="Varför är dvärgarnas Mountaineers så underbemannade?",a="King Magni Bronzebeard har skickat huvuddelen av Ironforges stående armé till Alliansens bredare fronter i andra länder. Medan förlusterna växer på andra håll lämnas gränsposter som de i Loch Modan med en minimal besättning som måste förlita sig på kringresande frivilliga.",al={"varför finns inga dvärgvakter","var finns förstärkningarna","ironforges armé i loch modan"}},{q="Var hittar man Stonesplinter Skullthumpers och Seers?",a="De samlas främst i de södra lägren i Stonesplinter Valley, öster om Valley of Kings. En mindre grupp av dem hemsöker också den nordligaste ön i The Loch.",al={"stonesplinter skullthumpers plats","stonesplinter seers plats","var finns troggarna"}},{q="Varför är Skullthumpers och Seers särskilda mål?",a="Skullthumpers är Stonesplinter-stammens främsta anfallstrupper, medan Seers brukar primitiv magi och leder de mindre troggarna. Om båda grupperna slås ut förlorar invasionsstyrkan både sin råstyrka och sin magiska samordning.",al={"varför döda seers","varför skullthumpers","troggmål"}},{q="Vart skickar Gravelgaw dig härnäst?",a="Gravelgaw hänvisar dig till Mountaineer Wallbang, som är stationerad i det södra vakttornet i Valley of Kings, för att hjälpa till med nästa del av dalens försvar.",al={"nästa uppdrag gravelgaw","vem är wallbang","efter in defense of the king's lands"}}},fx={c78d8208={q="Varför vill Mountaineer Gravelgaw att det här blir gjort?",a="Mountaineer Gravelgaw försöker vinna dyrbar tid åt Loch Modans försvarare. Stonesplinter-troggerna tränger obevekligt in i den södra dalen, samtidigt som dvärgtrupper desperat behövs på avlägsna slagfält där Alliansen strider. Genom att decimera invasionsstyrkan hoppas han hålla de södra passen säkra tills förstärkningar kan anlända från Ironforge.",al={"varför döda trogger","gravelgaws motiv","in defense of the kings lands motiv"}}},fp="30,199,14.366.0,34.347.0,27.248.1,39.150.0,48.213.0,61.184.0,48.179.0,35.130.1"}
P.entries["quest:2378"] = {n="Find the Shattered Hand",s="I Orgrimmar väntar Shattered Hand på en lovande Forsaken-skurk från Tirisfal Glades. Deathstalkers skickar novisen över havet till Durotar för att lära sig klanens specialiserade konster.",h="I Orgrimmar väntar Shattered Hand på en lovande Forsaken-skurk från Tirisfal Glades.",kw={"cleft of shadow","deathstalkers","mennet carkad","orgrimmar","skurkens uppdrag","shattered hand","shenthul"},ang={["class:Rogue"]="Som skurk går du från lokal träning vidare in i Hordes större kriminella nätverk och underrättelseverksamhet, och möter tränarna i Kalimdors undre värld.",["faction:Horde"]="Som medlem av Horde får du se samarbetet mellan Orgrimmars och Undercitys hemliga tjänster, bortom frontlinjens fotsoldater och schamaner.",["race:Undead"]="Som ung Forsaken-skurk lämnar du kvar de lokala resterna av Scourge i Lordaeron och ansluter dig till Hordes hjärtland i Durotar."},sec={{t="En skuggornas liga",b="Mennet Carkad har sett en skurk bevisa sitt värde i Tirisfal Glades. Forsaken tränar sin egen hemliga orden, Deathstalkers, och deras allians med Horde öppnar en väg till mörkare konster. Han hänvisar lovande skurkar till Shattered Hand i Orgrimmar, där Lordaerons odöda agenter förenas med Kalimdors orchiska lönnmördare."},{t="In i Cleft of Shadow",b="Resan slutar under Orgrimmar i Cleft of Shadow, där häxmästare, skurkar och demonbindare verkar utom synhåll. Där väntar Shenthul, en tränare i Shattered Hand. Den kärve trollet bedömer den nyanlända odöda agenten med hård skepsis. Gott rykte räcker inte för honom; han vill se om sändebudet verkligen är listigt eller har slösat bort resan över Great Sea."}},faq={{q="Vem ger uppdraget Find the Shattered Hand?",a="Mennet Carkad, en tränare för Deathstalkers i Rogues' Quarter i Undercity, skickar iväg dig när du har bevisat dina grundläggande färdigheter i Tirisfal Glades.",al={"vem startar find the shattered hand","mennet carkads uppdrag","vem skickar mig till orgrimmar"}},{q="Var finns Shenthul?",a="Shenthul finns i Cleft of Shadow, den mörka klyftan under Orgrimmars centrala gångar.",al={"hitta shenthul","shenthuls plats","var finns shenthul i orgrimmar"}},{q="Vilken relation har Deathstalkers till Shattered Hand?",a="Deathstalkers är Forsakens underrättelsenätverk och lönnmördarkår, medan Shattered Hand fyller en liknande roll för Horde i Orgrimmar. De är formella allierade som delar avancerad träning och hemliga uppdrag inom Horde.",al={"deathstalkers och shattered hand","forsaken-skurkar och orciska skurkar","varför skickas jag till orgrimmar"}},{q="Varför kallar Shenthul mig oinspirerande?",a="Shenthul kallar dig oinspirerande eftersom Shattered Hand värdesätter fysisk uthållighet och hänsynslös list. Han förolämpar nykomlingar för att knäcka deras stolthet och pröva om de klarar hård lönnmördarträning.",al={"shenthuls dialog","varför är shenthul elak","shenthuls avslutningstext"}},{q="Vad händer när jag når fram till Shenthul?",a="Shenthul låter dig arbeta med Zando'zan och skickar dig sedan söderut mot Ratchet för fältuppdrag i The Barrens.",al={"vad händer efter find the shattered hand","nästa uppdrag efter shenthul","shattered hands uppdragskedja"}},{q="Kan skurkar som inte är Forsaken få det här uppdraget?",a="Nej. Deathstalkers ger den här versionen till Forsaken-skurkar. Orch- och trollskurkar i Durotar får en motsvarande övergång som heter 'To Orgrimmar!'.",al={"orcisk skurk find the shattered hand","trollversion","alternativet to orgrimmar"}}},fx={aa6bb2de={q="Varför vill Mennet Carkad att jag ska bege mig till Orgrimmar?",a="Mennet Carkad inser att du har tjänat Deathstalkers väl och visat fallenhet för smygande och svek, men att du för tillfället har nått gränsen för hur mycket du kan utvecklas i Undercity. För att vässa ditt dödliga hantverk ytterligare vill han att du beger dig ut i den större Horden. Genom att skicka dig till Shattered Hand i Orgrimmar drar Mennet nytta av en allians mellan de två lönnmördarkårerna. Därmed får du avancerad handledning av veteraner bland orciska skurkar, som kan lära dig tekniker som inte finns i Lordaerons skuggor.",al={"varför skicka mig till orgrimmar","mennet carkads motiv","varför hitta shattered hand"}}},fp="23,191,19.344.0,24.383.0,44.141.0,26.88.0,74.251.0,38.209.0,37.114.0,39.148.0"}
P.entries["quest:2379"] = {n="Zando'zan",s="I Orgrimmars Cleft of Shadow börjar lovande skurkar träna med Shattered Hand. Tränaren Shenthul skickar sin utvalda adept till Zando'zan för att ansluta sig till Hordens hemliga led.",h="I Orgrimmars Cleft of Shadow börjar lovande skurkar träna med Shattered Hand.",kw={"cleft of shadow","dyrka lås","orgrimmar","rogue","shattered hand","shenthul","smyga","wrenix","zando'zan"},ang={["class:Rogue"]="Som skurk ansluter du dig till Shattered Hands hemliga led och går från en otränad knivkämpe till en erkänd Horde-operatör.",["faction:Horde"]="Shattered Hand sköter Hordens spionage och hemliga verksamhet och skyddar den mot osynliga hot, samtidigt som krigshövdingen talar om ära och frontalangrepp."},sec={{t="En vandring in i skuggorna",b="Orgrimmars härskare vet att rå styrka inte kan vinna varje krig. Under staden finns Shattered Hand i Cleft of Shadow, ett hemligt gille som sköter spionage, sabotage och stöld åt Horden. När skurkarnas tränare Shenthul ser potential hos en adept skickar han denne till Zando'zan för specialiserad träning som operatör."},{t="Bevisa sitt värde",b="Zando'zan visar inte respekt för varje oerfaren skurk som kommer in i grottan. Mötet med honom markerar en formell invigning i de finare hemliga konsterna, med början i smygande, list och stöld. Hans träning överbryggar klyftan mellan råbarkade ficktjuvar från gatan och organiserade underrättelseoperatörer, och förbereder skurkar för uppdrag ute i fält bortom huvudstadens röda kanjonväggar."}},faq={{q="Vem är Zando'zan?",a="Zando'zan är skurkarnas tränare och Shattered Hands kontaktperson i Orgrimmars Cleft of Shadow. Han bedömer nya rekryter och lär ut praktisk smygteknik, inbrott och operativt hantverk.",al={"zandozan","vem är zando'zan","zando'zan cleft of shadow"}},{q="Varför skickar Shenthul rogues till Zando'zan?",a="Shenthul skickar lovande skurkar till Zando'zan när de behöver specialiserad träning som operatörer i Shattered Hand. Zando'zan leder lektioner i inbrott och låsmanipulation för hemliga fältuppdrag.",al={"varför pratar jag med zando'zan","shenthul zando'zan","uppdragets syfte"}},{q="Vad är Shattered Hand i Orgrimmar?",a="Shattered Hand började som en brutal orcisk klan från Draenor, känd för rituell självstympning, och utvecklades till Hordens hemliga underrättelse- och lönnmördararm. Dess medlemmar verkar i Orgrimmars skuggor och sköter spionage, gift och spaning.",al={"vad är shattered hand","shattered hand orgrimmar","horderogues shattered hand"}},{q="Vart leder den här träningskedjan härnäst?",a="När du presenterar dig för Zando'zan skickar han dig till Ratchet vid The Barrens kust för att rådfråga Wrenix, en goblinkontakt, och inleda praktiska fältövningar i låsdyrkning.",al={"nästa uppdrag","vad händer efter zando'zan","wrenix i ratchet"}},{q="Var hittar jag Zando'zan?",a="Zando'zan verkar i Cleft of Shadow, ett djupt nätverk av grottor under Orgrimmars mitt. Häxmästare, skuggapräster och skurkarnas operatörer samlas där, långt från dagsljuset.",al={"zando'zans plats","var är zando'zan","hur hittar jag zando'zan"}},{q="Varför ber Zando'zan om ursäkt när han träffar mig?",a="Zando'zan kanske tvivlade på ditt mod innan du kom. När han ser att du är redo att träna erkänner han ditt engagemang och tar tillbaka sin första skepsis.",al={"varför ber zando'zan om ursäkt","avslutningsdialog zando'zan"}}},fx={["1d4b3aab"]={q="Varför överlåter Shenthul den här träningen åt dig i stället för åt en annan skurk?",a="Shenthul ser din råa beslutsamhet, men vet att ren iver inte räcker för att överleva Hordens hemliga strider. Du har visat att du förtjänar att gå vidare från grundläggande gatukonster, men för att verkligen tjäna Shattered Hand måste du formas till en hängiven agent. Shenthul skickar just dig eftersom ditt vägval och din potential har fångat gillets vakande blick.",al={"varför jag shenthul","varför skickar zandozan mig","varför är jag utvald"}}},fp="9,185,23.327.0,19.393.0,17.180.0,47.198.0,40.256.0,41.165.1,27.172.0,45.155.0"}
P.entries["quest:2380"] = {n="To Orgrimmar!",s="Kaplak skickar en ung rogue från Razor Hill till Orgrimmar. Där ska du hitta Shenthul i The Cleft of Shadow och ta dig in i Shattered Hands nätverk.",h="Kaplak skickar en ung rogue från Razor Hill till Orgrimmar.",kw={"cleft of shadow","kaplak","razor hill","rogue","shattered hand","shenthul","to orgrimmar"},ang={["class:Rogue"]="Som rogue tar du dig in i huvudstadens hemliga nätverk under Shenthuls uppsikt. Uppdragen handlar nu om gifter, stöld och svek bortom gränsens skärmytslingar.",["faction:Horde"]="Som medlem av Horde märker du spänningen mellan Thralls hedervärda nya väg och de äldre klanorganisationer som lever vidare under Orgrimmar."},sec={{t="En kallelse till skuggorna",b="Kaplak skickar dig norrut från Razor Hill till Orgrimmar. Dina gryende färdigheter har fångat mer framstående uppdragsgivares uppmärksamhet, även om de ännu är outvecklade. Durotars röda klippor ligger bakom dig när du beger dig mot huvudstaden."},{t="Under Thralls vakande öga",b="Shenthul tar emot dig i The Cleft of Shadow under Orgrimmar. Han följer krigsöverste Thralls politiska reformer med oro. Shattered Hand kan inte skydda sina intressen enbart med råstyrka eller öppet trots; för att överleva och bevara sitt inflytande är gillet beroende av tålamod, list och svek."}},faq={{q="Vem skickar iväg mig på det här uppdraget?",a="Kaplak, en rogue-tränare i Razor Hill, skickar iväg dig när dina färdigheter väcker överordnades uppmärksamhet i Orgrimmar.",al={"uppdragsgivare","vem ger uppdraget to orgrimmar","kaplaks uppdrag"}},{q="Var hittar jag Shenthul?",a="Du hittar Shenthul i The Cleft of Shadow, ett underjordiskt distrikt under Orgrimmar där rogues, warlocks och andra utstötta samlas.",al={"shenthuls plats","var finns shenthul","shenthul i cleft of shadow"}},{q="Vad har Shattered Hand för agenda i Orgrimmar?",a="Shattered Hand är ett underrättelse- och lönnmördargille inom Horde. Shenthul är misstänksam mot Thralls hedervärda reformer, och gillet förlitar sig på smygande för att bevara sitt inflytande och överleva.",al={"shattered hands motiv","varför shattered hand i orgrimmar","shattered hand och thrall"}},{q="Varför skickas jag iväg just nu?",a="Dina grundläggande spaningsuppdrag och skärmytslingar har visat att du är kapabel, så du får allt fler formella uppgifter inom gillet. De börjar med låsdyrkning och hemligt fältarbete i huvudstaden.",al={"rogue-uppdrag på nivå 16","varför bege sig till orgrimmar nu","kallelse till rogue-träning"}},{q="Skiljer sig det här uppdraget från ”Find the Shattered Hand”?",a="Båda leder rogues till Shenthul i Orgrimmar. Vilket uppdrag du får beror på var du tränar eller tar emot order, och båda för dig vidare i samma träningskedja.",al={"find the shattered hand eller to orgrimmar","alternativt introduktionsuppdrag"}},{q="Vad händer när jag rapporterar till Shenthul?",a="Shenthul prövar din förmåga och skickar dig vidare i kedjan. Du träffar kontakter som Zando'zan och tar sedan dig an hemliga uppdrag med goblinkontakter i Ratchet.",al={"nästa uppdrag efter to orgrimmar","vad ger shenthul"}}},fx={a9995c5c={q="Varför vill Kaplak att jag ska bege mig till Orgrimmar?",a="Kaplak följer direkta order från högre ort. Han vet att du är långt ifrån en sann mästare på smygande, men dina spirande talanger har fångat Shenthuls egen uppmärksamhet. Shattered Hand behöver listiga agenter som tränats för dess hemliga syften, och Kaplaks uppgift är att leda lovande skurkar som du in i huvudstadens djupare skuggor, där din verkliga träning kan börja.",al={"varför skickar kaplak mig","kaplaks motiv","varför bege sig till orgrimmar"}}},fp="13,151,24.223.0,27.304.1,27.113.0,25.134.0,49.198.0,47.188.0,54.150.0,41.169.0"}
P.entries["quest:2381"] = {n="Plundering the Plunderers",s="Wrenix the Wretched skickar nya Shattered Hand-rövare mot Southsea Freebooters nära Ratchet. Ombord på Tide Razor möter de pirater, låsta kassaskrin och en farlig väktare innan de gör anspråk på Southsea Treasure.",h="Wrenix the Wretched skickar nya Shattered Hand-rövare mot Southsea Freebooters nära Ratchet.",kw={"e.c.a.c.","låsdyrkning","plundring av plundrarna","polly","ratchet","southsea freebooters","southsea treasure","thistle tea","tide razor","wrenix the wretched"},ang={["class:Rogue"]="Som rövare lär du dig att dyrka upp lås under press och får Thistle Tea, en uppskattad brygd bland agenter som tjänar Horden.",["faction:Horde"]="Shattered Hand använder goblinkontakter i Ratchet för att sätta blivande agenter på prov mot Southsea Freebooters, som hotar The Barrens kust.",["profession:Cooking"]="Som rövare med matlagningsintresse kan du förtjäna Thistle Tea, en örtbrygd som uppskattas för sin förmåga att återställa energi."},sec={{t="Ett prov på smygande och stål",b="Wrenix the Wretched, en goblinkontakt i Ratchet, sätter blivande Shattered Hand-agenter på prov. Han skickar rövare söderut längs The Barrens kust till en vik där Tide Razor ligger för ankar, bemannad av Southsea Freebooters. De måste gå ombord utan att bli sedda, ta sig in i piraternas näste där ficktjuvar tränar, dyrka upp kassaskrinen i lastrummet och återvända med bytet."},{t="Polly och mojängen",b="Wrenix varnar för att tidigare tjuvar kommit tillbaka till honom i bitar. En vild papegoja vid namn Polly vaktar fartygets nedersta lastrum. För att hjälpa en rövare att möta fågeln tillhandahåller Wrenix en experimentell E.C.A.C. Kasta den på Polly efter att du dyrkat upp piraternas kassaskrin. Manicken förvirrar och försvagar fågeln, vilket gör striden möjlig att vinna."}},faq={{q="Vem är Wrenix the Wretched?",a="Wrenix the Wretched är en goblinrövare som fungerar som kontakt i Ratchet. Han samarbetar med agenter knutna till Orgrimmars Shattered Hand och skickar nya tjuvar in på piratterritorium för att öva på att dyrka upp lås och återta stulet byte.",al={"wrenix","vem är wrenix","goblinuppdrag för skurk i ratchet"}},{q="Var ligger Tide Razor?",a="Tide Razor ligger för ankar söder om Ratchet längs The Barrens östra kust, i en vik som tillhör Southsea Freebooters. Fartyget är en bas och träningsplats för piraterna.",al={"tide razors plats","var ligger piratskeppet","var finns southsea-piraterna"}},{q="Vad är E.C.A.C. och hur använder jag den?",a="E.C.A.C. är en experimentell goblinmanick som Wrenix delar ut från sin Gizmotronic Apparatus. Använd den mot Polly, den jättelika papegoja som vaktar Southsea Treasure i Tide Razors lastrum, så försvagas fågeln och kan besegras.",al={"ecac","vad är ecac","hur besegrar man polly"}},{q="Varför är området för låsdyrkning på skeppet viktigt?",a="Tide Razors andra däck är Southsea-piraternas träningsrum. Där kan rövare öva på att dyrka upp kassaskrin ute på fältet innan de försöker med det större skrinet nedanför.",al={"låsdyrkningsövning","träning på fotsoldatskeppet","dyrka upp kassaskrin i barrens"}},{q="Varför är uppdraget så viktigt för skurkar?",a="När du genomför kuppen bevisar du ditt värde för Shattered Hands nätverk. Wrenix ger dig Thistle Tea som din andel, en brygd som snabbt återställer en rövares stridsenergi.",al={"skurkuppdrag thistle tea","varför göra plundring av plundrarna","belöning för skurkuppdrag"}},{q="Vem är Polly?",a="Polly är en vildsint papegoja som vaktar Tide Razors nedre lastrum åt Southsea Freebooters. Utan goblinteknik som försvagar fågeln är den dödlig för oerfarna infiltratörer.",al={"polly","jättepapegoja","tide razor-boss"}}},fx={d00111f9={q="Varför vill Wrenix the Wretched ha Southsea-skatten?",a="Wrenix är en slug goblintjuv och fixare som verkar från Ratchet och vill åt Southsea Freebooters olagliga skattkista för en rejäl vinst. Tidigare försök att plundra piraternas skepp slutade katastrofalt, och fem andra skurkar dödades och styckades. Genom att skicka dig för att ta dig ombord och hämta bytet får Wrenix en lukrativ belöning samtidigt som han prövar din förmåga mot skurkarna som stal det först.",al={"wrenix motiv","varför stjäla southsea-skatten","varför vill wrenix få detta gjort"}},abe44597={q="Varför behöver Wrenix dig i stället för att anlita vakter eller göra det själv?",a="Att stjäla från Southsea Freebooters är ett känsligt och olagligt uppdrag som inte kan utföras med rå styrka eller Ratchets neutrala vakter. Piraterna tränar egna tjuvar ombord på Tide Razor, så det krävs någon skicklig på smygande och låsdyrkning för att ta sig in i lastrummet utan att upptäckas. Eftersom Wrenix är en goblin som verkar utanför vanliga handelsavtal föredrar han att anlita en duglig agent som går att offra, i stället för att riskera sitt eget skinn.",al={"varför jag wrenix","varför skicka en skurk","varför hämtar inte wrenix skatten själv"}}},fp="25,224,27.362.0,19.325.1,27.216.0,32.163.0,40.232.0,52.168.0,40.176.0,13.187.0"}
P.entries["quest:2382"] = {n="Wrenix of Ratchet",s="I Orgrimmar lockar Wrenix of Ratchet hordens skurkar till en goblinhamn långt söderut. Zando'zan skickar dem för att hjälpa Wrenix the Wretched, en skum goblin i Ratchet.",h="I Orgrimmar lockar Wrenix of Ratchet hordens skurkar till en goblinhamn långt söderut.",kw={"ratchet","rogue","shattered hand","the barrens","thrall","wrenix","zando'zan"},ang={["class:Rogue"]="Som hordens skurk lämnar du Orgrimmars trygghet och ger dig in på neutralt piratterritorium som ett viktigt steg i din träning.",["faction:Horde"]="Som medlem av horden vet du att Shattered Hand håller ögon och öron öppna bortom Durotars gränser. Orden förlitar sig ofta på neutrala hamnar som Ratchet för känsliga uppdrag."},sec={{t="En profet i skuggorna",b="I Orgrimmars Cleft of Shadow håller skurkarnas gille till i vindlande håligheter, mestadels utom synhåll. Zando'zan, en troll som talar i vilda utläggningar, hälsar operatörer med olycksbådande profetior. Hans syner visar hur hövding Thrall fälls av gift och klinga. Han förklarar inte profetian, utan skickar snabbt agenter söderut till hamnstaden Ratchet i The Barrens."},{t="Ratchets problemlösare",b="Ratchet ligger vid The Barrens kust, öster om The Crossroads. Skurkar, legosoldater och uppfinnare samlas i den neutrala hamnen, där Wrenix the Wretched bor. Wrenix har föga tålamod med Zando'zans excentriska sätt. Han säger att trollens tidigare rekryter mötte en dyster död i bukten, bland dess hungriga rovdjur."}},faq={{q="Vem skickar dig till Ratchet?",a="Zando'zan, en troll från Shattered Hand i Orgrimmars Cleft of Shadow, skickar dig söderut efter att ha hasplat ur sig märkliga syner.",al={"vem ger uppdraget","uppdragsgivare","zandozan"}},{q="Vem är Wrenix the Wretched?",a="Wrenix the Wretched är en goblinkontakt i Ratchet. Han sköter hemliga uppdrag och mekaniska förnödenheter åt skurkar i hela The Barrens.",al={"vem är wrenix","wrenix ratchet","wrenix identitet"}},{q="Vad hände med agenterna som skickades före mig?",a="Wrenix säger att de fem agenter som Zando'zan skickade före dig misslyckades med sina uppdrag och blev hajmat utanför Ratchets kust.",al={"tidigare rogues","hajmat","andra rekryter"}},{q="Vad menade Zando'zan när han pratade om Thrall?",a="Zando'zan säger att han såg Thrall fällas av en förgiftad dolk i ryggen, men avbryter sig sedan och byter ämne.",al={"thralls profetia","thrall förgiftad","zandozan thralls syn"}},{q="Var ligger Ratchet?",a="Ratchet ligger på den östra kusten av The Barrens, rakt öster om The Crossroads. Vägar söderut från Southfury River förbinder orten med Durotar.",al={"var ligger ratchet","hitta ratchet","ratchets läge"}},{q="Vad händer efter mötet med Wrenix?",a="När du hälsar på Wrenix ger han dig uppdraget 'Plundering the Plunderers': att infiltrera Southsea Freebooters längs kusten söder om Ratchet.",al={"nästa uppdrag","efter wrenix","fortsättning i ratchet"}}},fx={["17a3bd65"]={q="Varför skickar Zando'zan dig till Wrenix?",a="Zando'zan är skakad av febriga domedagsvisioner och förutser gift och en förrädisk dolk riktad mot krigshövding Thralls rygg. Den excentriske trollen försöker desperat motverka dessa osedda hot i skuggorna och förlitar sig på kontakter utanför staden, som Wrenix the Wretched i Ratchet, för hemliga uppdrag och specialutrustning.",al={"varför skickas jag till wrenix","zandozans motiv","varför besöka wrenix"}},["2311cb82"]={q="Varför skickar Zando'zan dig i stället för att sköta det själv?",a="Zando'zan håller sig gömd i skuggorna vid Orgrimmars Cleft of Shadow, där han vakar över mörka omen och mumlar om sina konspirationsvisioner. Hans oberäkneliga sätt och rädsla för att ha ”sagt för mycket” hindrar honom från att verka öppet ute på fältet, så han förlitar sig på dugliga skurkar som sina diskreta händer utanför stadsmurarna.",al={"varför skicka mig","varför behöver zando'zan mig","varför går han inte själv"}}},fp="17,172,24.370.0,24.317.0,25.124.0,27.129.0,47.121.0,50.121.0,25.150.0,37.136.1"}
P.entries["quest:239"] = {n="Westbrook Garrison Needs Help!",s="Marshal Dughan skickar tillgängliga äventyrare västerut till Westbrook Garrison, utposten vid gränsen mellan Elwynn Forest och Westfall. Stormwinds armé är utspridd över kungariket, medan Deputy Rainer och hans vakter pressas allt hårdare av Riverpaw-gnoller och kringströvande tjuvar utan regelbundna förstärkningar.",h="Marshal Dughan skickar tillgängliga äventyrare västerut till Westbrook Garrison, utposten vid gränsen mellan...",kw={"deputy rainer","elwynn forest","gnoller","goldshire","marshal dughan","riverpaw","westbrook garrison"},ang={["faction:Alliance"]="Som frivillig i Alliansen tar du på dig reguljära soldaters uppgifter och hjälper till att hindra kärnområdena från att störta ner i fullständigt kaos.",["race:Human"]="Som människa från Stormwind ser du ett oroande tecken på kungarikets försummelse. Kronans försvar har försvagats sedan kungen försvann."},sec={{t="En utsatt gräns",b="Westbrook Garrison bevakar den västra utkanten av Elwynn Forest, där den bebodda skogen möter Westfalls oroliga slätter. Gnollkrigarskaror och banditer blir allt djärvare längs vattendragen och vägarna västerut, och den lilla garnisonen har bett om fler soldater. Marshal Dughan och Goldshires styre har inga Stormwind-soldater att avvara. Lokala befälhavare måste anlita kringresande legosoldater och äventyrare."},{t="Hotet på andra sidan bäcken",b="Deputy Rainer och hans män kämpar mot Riverpaw-gnollerna, vars plundringståg trakasserar resenärer och gårdar i närheten. Flokken håller till i gränslandet mellan Elwynn och Westfall. Med Stormwind upptaget av politiska och militära bekymmer tränger gnollerna allt längre in i bebodda områden. Westbrook Garrison skyddar mot deras obehindrade framryckning in i skogens hjärta."}},faq={{q="Varför kan Stormwind inte skicka regelbundna soldater till Westbrook Garrison?",a="Stormwinds stående armé är utspridd längs flera gränser. Eftersom kung Varian Wrynn är försvunnen och riket plågas av inre stridigheter har högsta befälet vägrat, eller inte kunnat, skicka regelbundna soldater till utposter på landsbygden. Stadsmarskalkar som Dughan måste förlita sig på frivilliga frilansare.",al={"varför inga stormwind-trupper","varför skicka äventyrare","var finns stormwinds armé"}},{q="Var ligger Westbrook Garrison?",a="Westbrook Garrison ligger vid Elwynn Forests västra gräns. Följ huvudvägen västerut från Goldshire, förbi den lilla bäcken. Det befästa tornet står på din högra sida, strax före gränsen till Westfall.",al={"westbrook garrisons läge","hur tar man sig till westbrook","var finns deputy rainer"}},{q="Vilka hot plågar garnisonen?",a="Deputy Rainer utsätts för upprepade räder av Riverpaw-gnoller, samtidigt som tjuvar och banditer blir allt aktivare i gränslandet mellan Westfall och Elwynn Forest.",al={"vad angriper westbrook","varför behöver rainer hjälp","vem angriper westbrook garrison"}},{q="Vem är Deputy Rainer?",a="Deputy Rainer är Stormwind-officeren som för befälet vid Westbrook Garrison. Han måste hålla den västra gränsen och förlita sig på civila frivilliga och legosoldater, eftersom officiella militära förstärkningar är sällsynta.",al={"rainers historia","deputy rainer","vem är rainer"}},{q="Vad händer efter att du har rapporterat till Deputy Rainer?",a="Deputy Rainer värvar dig till kampen mot de lokala Riverpaw-gnollerna. Han utlyser en belöning för deras halsband för att minska deras antal och skydda gränsvägen.",al={"what comes next","westbrooks uppdragskedja","rain ers uppdrag"}},{q="Varför tränger gnollerna in i Elwynn Forest?",a="Riverpaw-gnollerna har läger längs floderna som skiljer Elwynn och Westfall åt. Med färre soldater längs gränsen har de blivit djärva nog att plundra handelsvägar och närma sig gårdarna längre in i Elwynn.",al={"riverpaw-gnoller i elwynn","varför är gnollerna här","gnollproblemet"}}},fx={["76645dec"]={q="Varför vill Marshal Dughan att du ska bege dig till Westbrook Garrison?",a="Marshal Dughan ansvarar för att upprätthålla ordning och säkerhet i Elwynn Forest från Goldshire, men hans resurser är hårt ansträngda. Westbrook Garrison bevakar kungarikets västra gräns, och Deputy Rainer har skickat brådskande besked om ökad banditverksamhet och gnoller som tränger in. Eftersom han inte har reguljära trupper att skicka som förstärkning måste Dughan förlita sig på självständiga äventyrare som svarar på utpostens vädjan om hjälp innan den västra gränsen helt faller.",al={"varför skickas jag till westbrook garrison","marshal dughans motiv","varför behöver westbrook garrison hjälp"}}},fp="30,367,25.395.0,27.357.0,64.289.0,36.195.0,40.157.0,21.205.0,46.153.0,46.211.0"}
P.entries["quest:2399"] = {n="The Sprouted Fronds",s="Efter Denalans botaniska experiment vid Lake Al'Ameth slår den planterade fronden rot och börjar gro. Denna stillsamma stund visar att skörden lyckats och ökar förståelsen för Teldrassils märkliga och livsviktiga flora. Resenärer som granskar trädgårdslanden kan själva se hur snabbt den växer.",h="Efter Denalans botaniska experiment vid Lake Al'Ameth slår den planterade fronden rot och börjar gro.",kw={"denalan","örtmedicin","odlingslåda","frön","shimmering frond","grodda fronder","teldrassil","wellspring lake"},ang={["class:Druid"]="Druider som betraktar Denalans odlingslåda kan uppskatta naturens stillsamma balans och se livet frodas under omsorgsfull skötsel, trots farorna som växer i Teldrassil.",["profession:Herbalism"]="Denalans forskning speglar det praktiska hantverket att samla in och studera Teldrassils unika växtlighet och visar hur snabbt lokala frön anpassar sig till omhändertagen jord.",["race:NightElf"]="Att vårda den nygrodda floran speglar kaldoreiernas ansvar att vaka över och vårda livet som slår rot i deras unga världsträd."},sec={{t="En trädgård vid Lake Al'Ameth",b="Undangömd nära Lake Al'Ameth ägnar sig botanisten Denalan åt att katalogisera Teldrassils säregna växtliv. Efter att ha planterat en mystisk skimrande frond ger jorden snabbt resultat. I odlingslådan han sköter skjuter märkliga, darrande fronder upp ur den bördiga myllan, redo att samlas in och undersökas."},{t="Världsträdets märkliga flora",b="Teldrassil är ungt, vidsträckt och fullt av snabb naturlig utveckling som både fascinerar och oroar nattalvernas örtmästare. De skimrande fronderna och deras grodda utlöpare visar hur snabbt livet får fäste på det stora trädets grenar och antyder den kraftfulla men oförutsägbara livskraft som genomsyrar öns jord."}},faq={{q="Vad är de grodda fronderna?",a="Det är växterna som grodde efter att Denalan planterat en skimrande frond vid sitt läger intill sjön. De har vuxit från den fronden, som hittades på en annan plats i Teldrassil, och darrar av energi när de är redo att skördas.",al={"grodda fronder","vad är det här för växter","denalans fronder"}},{q="Var ligger Denalans trädgård?",a="Denalan har sin trädgård och sitt forskningsläger längs den östra kanten av Lake Al'Ameth, sydost om Dolanaar i Teldrassil.",al={"denalans plats","var är denalan","trädgård vid wellspring lake"}},{q="Varför planterar Denalan dessa fronder?",a="Denalan studerar Teldrassils växtlivs märkliga och snabba tillväxtmönster. Genom att plantera frön i jord under kontrollerade förhållanden undersöker han deras egenskaper och testar om de har användbara läkande eller örtmedicinska egenskaper.",al={"varför plantera fronder","denalans experiment","frondernas syfte"}},{q="Är de grodda fronderna farliga?",a="Nej. Till skillnad från en del fördärvad eller fientlig flora på andra håll bland Teldrassils grenar är dessa grodda fronder ofarliga botaniska exemplar som bara väntar på att plockas.",al={"är fronder farliga","angriper fronder","är växten skadlig"}},{q="Vad kommer före det här uppdraget?",a="Äventyrare hittar först en skimrande frond ute i Teldrassils vildmark och tar den till Denalan, som planterar den i sin odlingslåda i hopp om att den ska slå rot.",al={"förkunskapskrav för grodda fronder","vilket uppdrag kommer först"}},{q="Varför darrar fronderna?",a="Fronderna darrar medan de väntar på att bli plockade. Källtexten förklarar inte vad som orsakar rörelsen.",al={"darrande fronder","varför skakar de"}}},fp="19,140,25.220.0,35.275.0,29.185.0,34.120.0,36.172.0,34.141.0,29.150.0,26.78.0"}
P.entries["quest:24"] = {n="Shadumbra's Head",s="Det här uppdraget är ett bevis på segern över Shadumbra, en ökänd och våldsam nightsaber som jagar längs Ashenvales västra stigar. När du för tillbaka bestens avhuggna huvud till Senani Thunderheart vid Splintertree Post fullbordar du ett viktigt prov i Ashenvale Hunt och säkrar färdvägarna mot The Zoram Strand.",h="Det här uppdraget är ett bevis på segern över Shadumbra, en ökänd och våldsam nightsaber som jagar längs...",kw={"ashenvale hunt","nightsaber","senani thunderheart","shadumbra","splintertree post","trofé","the zoram strand"},ang={["class:Hunter"]="Att spåra upp och besegra en svårfångad nightsaber som Shadumbra är ett typiskt prov på skytte, tålamod och överlevnad i tät skogsterräng.",["faction:Horde"]="Splintertree Post är fortfarande ett isolerat Horde-fäste. När lokala hot som Shadumbra undanröjs hålls viktiga försörjningsleder till The Zoram Strand öppna.",["race:Tauren"]="För tauren hedrar jakten på ett odjur av Shadumbras kaliber Jordmodern och hennes naturliga ordning. Den prövar jägarens skicklighet mot ett topprovdjur och skyddar samtidigt stamfränderna på vägen."},sec={{t="Ett hot på västvägen",b="Shadumbra är inget vanligt rovdjur bland Ashenvales höga träd. Den väldiga nightsabern jagade i vildmarken väster om Splintertree Post och fällde Horde-spejare och kurirer på väg mot The Zoram Strand. Hennes snabbhet, smygförmåga och ursinne gjorde det farligt att färdas till fots. Splintertrees försvarare blev därför oroliga varje gång patruller begav sig västerut."},{t="Jaktens bevis",b="Som en del av Ashenvale Hunt utmanar taurenjägaren Senani Thunderheart Horde-mästare att spåra upp och fälla skogens största rovdjur. Att visa upp Shadumbras huvud är mer än en dyster uppvisning i skicklighet. Det är ett obestridligt bevis på att vägarna har blivit säkrare och att jägaren har bemästrat en av Kalimdors farligaste inhemska jägare."}},faq={{q="Vem var Shadumbra?",a="Shadumbra var en ovanligt våldsam nightsaber som strövade i skogarna väster om Splintertree Post. Hon överföll resenärer på den långa färden mot kusten och ansågs vara ett av Ashenvales farligaste lokala rovdjur.",al={"vad är shadumbra","shadumbras bakgrund","vem är katten"}},{q="Varför vill Senani Thunderheart ha huvudet?",a="Senani Thunderheart leder Ashenvale Hunt vid Splintertree Post. Huvudet är både en traditionell trofé från en imponerande jakt och ett bevis på att hotet mot resenärer västerut har undanröjts.",al={"varför ta med huvudet","senani thunderheart trofé","bevis på ashenvale hunt"}},{q="Hur passar det in i Ashenvale Hunt?",a="Det är ett av de viktigaste proven som inleds när du antar Ashenvale Hunt. Om du dödar Shadumbra och skogens andra stora bestar, som Ursangous och Sharptalon, får du till slut erkännande och uppdraget The Hunt Completed.",al={"vad är ashenvale hunt","jaktuppdragskedja","nästa jaktuppdrag"}},{q="Varför är det viktigt för Horde att röja undan besten?",a="Splintertree Post är beroende av spejare och kurirer som färdas västerut till Hordes läger Zoram'gar Outpost vid The Zoram Strand. Shadumbras rovdjursinstinkter utgjorde ett ständigt hot mot Horde-fotsoldater som tog sig genom den otämjda skogen.",al={"varför bryr sig horde","fara på vägen till zoram strand","säkerhet vid splintertree post"}},{q="Var finns Shadumbra?",a="Shadumbra jagar i skogarna väster om Splintertree Post, bland träden mellan vägen och de uråldriga night elf-ruinerna som ligger utspridda i centrala och västra Ashenvale.",al={"shadumbras plats","var finns shadumbra","hitta shadumbra"}},{q="Är Shadumbra allierad med night elves?",a="Nej. Night elves tämjer och vördar ofta nightsabers, men Shadumbra är en vild och förvildad skräck från skogen. Hon följer enbart sina råa rovdjursinstinkter och hotar alla som korsar hennes revir.",al={"är shadumbra ett husdjur","sentinels husdjur","shadumbra och night elves"}}},fp="16,217,28.225.0,17.292.0,18.196.0,43.178.0,44.200.0,50.189.0,29.171.0,41.171.0"}
P.entries["quest:240"] = {n="Return to Jitters",s="Return to Jitters avslutar Chef Gruals matärende i Duskwood. Efter att ha tillagat sina ökända ”krabbkakor” av de kladdiga benen från skogens giftspindlar skickar Grual dig tillbaka till den utsvultna, skräckslagna eremiten vid Raven Hill. Måltiden stillar till slut Jitters desperata hunger.",h="Return to Jitters avslutar Chef Gruals matärende i Duskwood.",kw={"chef grual","darkshire","duskwood","dusky crab cakes","kurrande mage","jitters","scarlet raven tavern"},ang={["faction:Alliance"]="Den knappa och ovanliga kosten i Darkshire visar hur avskuren staden är från Stormwinds större försörjningsleder. Därför får lokalbefolkningen förlita sig på vad som än kryper fram ur skuggorna.",["profession:Cooking"]="Chef Gruals förmåga att förvandla kladdiga ben från giftspindlar till aptitliga kakor visar prov på den bistra uppfinningsrikedom som krävs av kockar i gränslandet."},sec={{t="En tvivelaktig delikatess",b="Duskwood har ont om vanliga boskapsdjur och havsdjur, så Chef Grual på Scarlet Raven Tavern får improvisera med vad den fördärvade skogen erbjuder. Hans berömda ”Dusky Crab Cakes” innehåller inget riktigt krabbkött alls, utan görs i stället av kladdiga ben från giftspindlar som kryper genom skogen. Grual ser det som påhittig matlagning, men den med känslig mage kan bli förskräckt."},{t="Att lugna Jitters",b="Jitters tillbringar dagarna hopkrupen vid Raven Hill, helt uppslukad av skräck och lamslagen av de fasor som drev honom ut ur skogen. Han är svag av rädsla och vågar inte jaga eller samla mat själv, och tom mage gör bara hans oro värre. De varma kakorna ger den darrande luffaren ett sällsynt ögonblick av lättnad. Han är alldeles för hungrig för att undra vilken sorts ”krabba” Chef Grual använde."}},faq={{q="Vad innehåller Dusky Crab Cakes?",a="Det finns inga krabbor i Duskwood. Chef Grual gör sina specialkakor av kladdiga ben från lokala giftspindlar och kryddar dem så att de liknar traditionella skaldjurskakor.",al={"ingredienser i krabbkakor","vad innehåller dusky crab cakes","är det riktig krabba"}},{q="Vet Jitters att kakorna är gjorda av spindelgegga?",a="Chef Grual håller sin matlagningshemlighet för sig själv, och Jitters är alldeles för utsvulten och skräckslagen för att fråga om receptet. Han äter dem ivrigt utan att ana varifrån de egentligen kommer.",al={"vet jitters om det","vet jitters om spindlarna"}},{q="Varför kunde Jitters inte skaffa mat själv?",a="Jitters är helt överväldigad av rädsla efter sina möten i Duskwoods vilda skogar. Paniken lamslår honom, så han vägrar gå långt från sitt gömställe vid Raven Hill och förlitar sig på medkännande resenärer som ger honom mat.",al={"varför svälter jitters","varför jagar jitters inte"}},{q="Vem är Chef Grual?",a="Chef Grual är kocken på Scarlet Raven Tavern i Darkshire. Eftersom skuggor och bestar isolerar staden använder han alla ovanliga ingredienser som samlare kommer med för att hålla den lokala krogen med mat.",al={"chef gruals roll","kock i darkshire"}},{q="Var börjar den här uppdragskedjan?",a="Ärendet börjar när Jitters vid Raven Hill ber om hjälp med sin kurrande mage i ”Jitters' Growling Gut”. Därefter jagar du giftspindlar åt Chef Grual och återvänder hit med den färdiga måltiden.",al={"hur startar man jitters matuppdrag","start på jitters uppdragskedja"}},{q="Återhämtar sig Jitters efter att ha ätit?",a="Måltiden stillar hans fysiska hunger och ger dig hans innerliga tacksamhet, men mat botar inte hans djupt rotade skräck. Han förblir orolig och hemsökt av skogens mörka hemligheter.",al={"blir jitters frisk","hjälper mat jitters"}}},fx={deba9bdd={q="Varför vill Chef Grual att krabbkakorna levereras till Jitters?",a="Chef Grual sköter köket på Scarlet Raven Tavern i Darkshire och är stolt över att uppfylla beställningar, även märkliga sådana som tillagas av lokala spindelinnälvor. Jitters svälter i den farliga skymningen vid Raven Hill och är för rädd för att själv ta sig in till staden. Efter att ha lagat sina särskilda ”krabbkakor” à la Grual anförtror kocken dem åt dig, så att Jitters får sin beställning och den stackars kraken får mat.",al={"varför leverera krabbkakor","gruals motiv jitters","varför skicka mat till jitters"}}},fp="17,113,18.349.0,24.317.0,32.141.0,51.125.0,38.171.0,18.189.0,34.182.0,34.172.0"}
P.entries["quest:243"] = {n="Into the Field",s="Apothecary Zinge skickar dig till Tanaris öken med ett fälttestkit för att testa vävnad från basilisks, scorpids och hyenor. Det modifierade kitet behöver också en kraftkälla som trollerna i Gadgetzan har, så Zinge hänvisar dig till Chief Engineer Bilgewhizzle där.",h="Apothecary Zinge skickar dig till Tanaris öken med ett fälttestkit för att testa vävnad från basilisks...",kw={"apotekare","basilisk","bilgewhizzle","gadgetzan","hyena","kraftkälla","scorpid","tanaris","testkit","zinge"},sec={{t="Vävnad i öknen",b="Apothecary Zinge vill att vävnaden från öknens basilisks, scorpids och hyenor testas. Du samlar prover och kör dem genom testkitet du bär med dig, men en stor del av proverna kommer att misslyckas. Åtta godtagbara prover av varje sorts varelse behövs, och Zinge ber dig återvända först när du har lyckats."},{t="En kraftkälla i Gadgetzan",b="Det modifierade kitet måste användas med en kraftkälla av en sort som trollerna i Gadgetzan har. Zinge skickar dig till Chief Engineer Bilgewhizzle i Gadgetzan för att få tag på en."},{t="Ingenting är gratis",b="Bilgewhizzle känner väl till kraftkällorna av modellen 4711-FTZ. De driver vanligtvis vattenbrunnarna, och tack vare de vidriga nomaderna finns det just nu mer än tillräckligt många. Bilgewhizzle ordnar en åt dig, oavsett vilket skändligt experiment du försöker dölja, men inte gratis, för i Gadgetzan är ingenting gratis."}},faq={{q="Vem skickar dig till Tanaris för den här forskningen?",a="Apothecary Zinge, som ger dig ett fälttestkit och vill att vävnad från öknens varelser testas.",al={"vem startar in i fältet","vem ger uppdraget in i fältet","uppdragsgivare för in i fältet"}},{q="Varför behöver du träffa Chief Engineer Bilgewhizzle?",a="Det modifierade testkitet behöver en kraftkälla av en sort som trollerna i Gadgetzan har, och Bilgewhizzle är den du ska tala med för att få tag på en.",al={"bilgewhizzles roll","varför besöka bilgewhizzle","testkitets kraftkälla"}},{q="Vilka bestar ska testas?",a="Basilisks, scorpids och hyenor i Tanaris öken. Åtta godtagbara prover av varje sort behövs.",al={"bestar att testa","varelsetyper för in i fältet","vävnadsprover tanaris"}}},fp="14,266,20.341.0,27.164.0,15.304.1,43.102.0,51.147.0,38.99.0"}
P.entries["quest:2438"] = {n="The Emerald Dreamcatcher",s="Tallonkai Swiftroot i Dolanaar ber äventyrare att hämta en kär familjeklenod från hans övergivna hem i Starbreeze Village. The Emerald Dreamcatcher, som druidskötaren Gaerolas Talvethren gav honom, lämnades kvar när fördärvade Gnarlpine-furbolgerna intog den fridfulla byn. Genom att återta amuletten hindrar du dess milda naturmagi från att hamna i orätta händer.",h="Tallonkai Swiftroot i Dolanaar ber äventyrare att hämta en kär familjeklenod från hans övergivna hem i...",kw={"ban'ethil barrow den","dolanaar","emerald dream","emerald dreamcatcher","furbolg","gaerolas talvethren","gnarlpine","starbreeze village","tallonkai swiftroot","teldrassil"},ang={["class:Druid"]="Amuletten är ett verk av Gaerolas Talvethren, väktaren som vårdar dina sovande fränder i Ban'ethil Barrow Den. Att återta den är därför en fråga om druidisk heder.",["faction:Alliance"]="Genom att hjälpa de fördrivna Kaldorei i Dolanaar bidrar du till stabiliteten i området medan Teldrassil kämpar mot det utbredda fördärvet bland furbolgstammarna.",["race:NightElf"]="Starbreeze var en gång en fridfull tillflyktsort för ditt folk. Genom att hjälpa Tallonkai att återta sitt kulturarv slår du ett litet slag mot vansinnet som griper omkring sig bland Teldrassils vilda djur."},sec={{t="En druidisk talisman",b="Emerald Dreamcatcher är mycket mer än en prydnadssak. Amuletten, en gåva från Gaerolas Talvethren, den ärade väktaren för de sovande druiderna i Ban'ethil Barrow Den, skapades för att kanalisera Emerald Dreams fridfulla strömmar. Genom att dra till sig denna rena andliga energi skänker drömfångaren frid och lycka åt sin bärare. Sådana föremål är ytterst sällsynta och ges endast till några få betrodda, vars liv är sammanflätade med skogens förvaltning."},{t="Fly från Starbreeze Village",b="Fram till nyligen var Starbreeze Village en fridfull by bland Teldrassils grenar. Det stilla livet tog slut när traktens Gnarlpine-furbolger föll offer för ett våldsamt vansinne och drev bort nattalverna från deras förfäders hem. Under den skräckfyllda och förvirrade evakueringen tvingades Tallonkai lämna sin käraste ägodel gömd i byrålådan i byns sydöstra del, utan möjlighet att hämta den själv."},{t="Fördärvets hot",b="Att lämna en källa till Emerald Dream-magi mitt i en ockuperad by medför stora risker. Gnarlpine-furbolgerna har visat sig mottagliga för mörka krafter, och en artefakt som pulserar av Dreamens energi kan lätt fördärvas eller användas som vapen. Om du hämtar drömfångaren oskadd återför du en del av Starbreezes kulturarv till Tallonkai innan furbolgerna eller andra vidriga invånare kan vanhelga dess kvarvarande magi."}},faq={{q="Vad är Emerald Dreamcatcher?",a="Det är en sällsynt amulett som Gaerolas Talvethren gav till Tallonkai. Gaerolas är väktare för druiderna i Ban'ethil Barrow Den. Drömfångaren drar till sig energi från Emerald Dream och skänker tur och andlig harmoni åt den som bär den.",al={"vad är drömfångaren","drömfångarens bakgrund","emerald dreamcatcher"}},{q="Varför lämnades drömfångaren kvar i Starbreeze Village?",a="Starbreeze Village blev snabbt översvämmat när traktens Gnarlpine-furbolger föll in i ett våldsamt, fördärvat raseri. Tallonkai Swiftroot tvingades fly för sitt liv till Dolanaar och lämnade den dyrbara familjeklenoden gömd i byrålådan i sitt sovrum.",al={"varför lämnades den kvar","byrån i starbreeze village","tallonkais byrå"}},{q="Vem är Tallonkai Swiftroot?",a="Tallonkai är en nattalv på flykt som för närvarande bor i Dolanaar. Efter att ha undkommit Starbreeze Villages fall söker han modiga resenärer som vågar sig tillbaka till de ockuperade ruinerna för att rädda hans familjeklenoder och skydda druidiska reliker.",al={"vem är tallonkai","tallonkai swiftroot"}},{q="Vem skapade drömfångaren?",a="Tallonkai säger bara att den var en gåva från Gaerolas Talvethren, väktaren som vakar över de sovande druiderna i Ban'ethil Barrow Den. Det sägs aldrig vem som faktiskt skapade den.",al={"vem skapade den","gaerolas talvethren drömfångare","gaerolas"}},{q="Var i Starbreeze Village finns drömfångaren?",a="Den ligger i Tallonkai personliga byrå, som står i det sydöstligaste huset i Starbreeze Village, där fientliga Gnarlpine-furbolger nu stryker omkring i stort antal.",al={"var står byrån","byråns plats i starbreeze","hitta drömfångaren"}},{q="Vad händer efter att drömfångaren återlämnas?",a="När Tallonkai undersöker den återfunna amuletten upptäcker han att dess smaragd saknas. Den har stulits av Gnarlpine-ledaren Ferocitas the Dream Eater, vilket leder direkt till jakten på honom.",al={"fortsättning på uppdraget","nästa uppdrag efter drömfångaren"}}},fx={["1ded4259"]={q="Varför vill Tallonkai Swiftroot ha tillbaka Emerald Dreamcatcher?",a="Emerald Dreamcatcher är en sällsynt och djupt personlig skatt. Den gavs till Tallonkai av Gaerolas Talvethren, druidernas väktare i Ban'ethil Barrow Den, och bär på stark magi från The Emerald Dream som skänker tur. När Starbreeze Village föll för de korrumperade Gnarlpine-furbolgarna tvingades Tallonkai lämna den bakom sig. Han fruktar att den heliga reliken ska vanhelgas eller förstöras av de härjande furbolgarna om den blir kvar i hans övergivna hem.",al={"varför vill tallonkai ha dreamcatcher","tallonkais motiv","varför hämta tillbaka emerald dreamcatcher"}}},fp="24,347,18.362.0,26.316.0,24.371.1,33.254.0,59.190.0,27.212.0,26.167.0,56.159.0,48.181.1"}
P.entries["quest:244"] = {n="Encroaching Gnolls",s="Encroaching Gnolls är ett uppdrag för Alliansen som varnar Lakeshires stadsvakt för gnoller som stryker farligt nära gränsen till Elwynn. Guard Parker upptäcker läger som samlas längs gränspasset och skickar resenärer vidare för att varna Deputy Feldon. Nyheten bekräftar Lakeshires växande oro för att bestfolket hotar att skära av Redridge helt.",h="Encroaching Gnolls är ett uppdrag för Alliansen som varnar Lakeshires stadsvakt för gnoller som stryker...",kw={"assessing the threat","deputy feldon","gränsen till elwynn","encroaching gnolls","guard parker","lakeshire","redridge"},ang={["faction:Alliance"]="Lakeshires isolering hotar Alliansens östfront, vilket gör gränsunderrättelser viktiga för resenärer och förnödenhetskonvojer.",["race:Human"]="Att bestfolk tränger fram inom synhåll från Elwynn Forest visar hur sårbara rikets kärnområden har blivit när kungen är försvunnen."},sec={{t="Ögon vid gränsen",b="Vägen som förbinder Elwynn Forest med Redridge Mountains borde vara en av rikets säkraste leder, men Stormwinds uttunnade styrkor lämnar den knappt försvarad. Guard Parker är stationerad längs den västra gränsstigen för att hålla uppsikt över rörelser. Han ser till att grusvägen hålls farbar för förnödenhetsvagnar, men hans spaningsrundor norrut och österut visar att gnollkrigarskaror har ryckt fram från klipporna och slagit läger oroväckande nära vägen."},{t="En stad under belägring",b="När Deputy Feldon får larmet nära bron i Lakeshire inser han att situationen är värre än väntat. Gnollerna i Redridge plundrar inte bara stadens utkanter; deras framskjutna närvaro nära gränsen till Elwynn antyder att de kan omringa Lakeshire och tränga in i rikets hjärtland. Stormwind ignorerar vädjandena om förstärkningar, så Lakeshires vakt är illa rustad att hantera ett hot från två håll."}},faq={{q="Vem inleder det här uppdraget?",a="Guard Parker erbjuder uppdraget längs vägen i västra Redridge Mountains, nära gränsövergången till Elwynn Forest.",al={"uppdragsgivare","var börjar uppdraget","guard parker plats"}},{q="Var hittar jag Deputy Feldon?",a="Deputy Feldon är stationerad i Lakeshire och patrullerar området strax söder om stadens stora stenbro.",al={"feldons plats","vem är deputy feldon","plats för inlämning"}},{q="Varför är gnollerna ett problem på vägen?",a="Vägen till Elwynn Forest är Lakeshires enda säkra landförbindelse med resten av riket. Om gnollerna tar de västra sluttningarna blir staden i praktiken avskuren från förnödenheter och flyktvägar.",al={"varför gnollerna spelar roll","gnollproblem i redridge","fara på vägen"}},{q="Varför skickar inte Stormwind hjälp till Lakeshire?",a="Kung Varian Wrynn är försvunnen och riket pressas av oroligheter. Highlord Bolvar och hovet har därför vägrat att skicka kungliga trupper till Redridge, så Lakeshires försvar vilar helt på lokala deputerade och frivilliga.",al={"var är stormwinds vakter","inga förstärkningar","försvaret av lakeshire"}},{q="Vad händer efter att jag rapporterat om gnollerna?",a="Deputy Feldon ber dig att följa upp rapporten genom att spana närmare på gnollernas läger i uppdraget Assessing the Threat, för att ta reda på hur många de egentligen är.",al={"nästa uppdrag","fortsättning på uppdragskedjan"}},{q="Vilka gnollflockar tränger fram här?",a="Gnollerna i Redridge, som samlas i kullarna som Redridge Gnoll Pack, har blivit allt djärvare och mer samordnade i takt med att människornas kontroll över området försvagas.",al={"vilka gnoller","gnollklaner i redridge"}}},fx={e50462f9={q="Varför vill Guard Parker att det här ska göras?",a="Guard Parker har fått i uppdrag att säkra den här vägsträckan in mot Redridge Mountains, men han har upptäckt fientliga gnolläger som samlas strax norr och österut. Han befarar ett nära förestående anfall som kan övermanna hans patrull och stänga passet. Därför behöver han omedelbart få myndigheterna i Lakeshire underrättade innan gnollerna slår till mot vägen eller rycker fram mot Elwynn.",al={"guard parkers motiv","varför varna lakeshire","varför skickar parker dig"}},be5d12a2={q="Varför skickar Guard Parker dig i stället för att själv bege sig dit?",a="Parker har stränga order om att hålla vakt och försvara vägen mellan Elwynn Forest och Redridge. Om han lämnar sin post för att skynda tillbaka till staden står gränsen helt oskyddad mot de lurande flockarna. En resande som är på väg mot Lakeshire är hans bästa chans att snabbt få fram varningen utan att överge sin uppgift.",al={"varför skicka mig","varför går parker inte själv","varför kan guard parker inte rapportera"}}},fp="18,239,18.365.0,18.371.0,22.120.0,31.100.0,40.176.0,45.209.0,40.125.0,39.148.0"}
P.entries["quest:245"] = {n="Eight-Legged Menaces",s="Åttabenta hot är ett miliskontrakt utfärdat av Watcher Dodds i Duskwood. När aggressiva giftspindlar har tagit över den västra gränsen förlitar sig den underbemannade Night Watch på kringvandrande äventyrare för att tunna ut kullen innan fler vakter fastnar i deras nät.",h="Åttabenta hot är ett miliskontrakt utfärdat av Watcher Dodds i Duskwood.",kw={"darkshire","duskwood","åttabenta hot","night watch","små giftspindlar","spindlar","watcher dodds"},ang={["class:Hunter"]="Duskwoods giftspindlar är våldsamma bestar som kräver försiktigt fotarbete och förberedelser med motgift för att jagas effektivt.",["faction:Alliance"]="Night Watch står helt ensam utan hjälp från House of Nobles. Allt stöd som resande från Alliance kan ge är avgörande för att hålla vägarna öppna."},sec={{t="En belägrad gräns",b="Längs vägen i väster mellan Westfall och Duskwood övergår den täta trädkronan i snåriga buskage, insnärjda i spindelväv. Små giftspindlar svärmar nu i snåren och hotar resande samtidigt som de tränger in på Night Watchs bräckliga försvarslinjer."},{t="Night Watchs börda",b="Watcher Dodds är stationerad långt från tryggheten i Darkshire och lider desperat brist på soldater. Commander Althea Ebonlocke kan inte avvara förstärkningar för att säkra avlägsna utposter när odöda och worgen pressar mot själva staden. Isolerad har Dodds redan sett kamrater falla offer för spindlarna och upptäckt män som hänger upp och ner i trädkronorna medan det förlamande giftet långsamt löser upp dem inför måltiden."}},faq={{q="Vem erbjuder uppdraget?",a="Watcher Dodds, en medlem av Night Watch som är posterad vid ett litet läger i Duskwood, erbjuder uppdraget till resande som kan rensa bort spindlarna.",al={"uppdragsgivare","vem ger uppdraget åttabenta hot","watcher dodds"}},{q="Varför kan inte Night Watch hantera spindlarna själva?",a="Commander Althea Ebonlocke måste samla sin lilla garnison nära Darkshire för att slå tillbaka obevekliga angrepp från odöda. Dodds har inte manskapet som krävs för att angripa de angripna gränsbon utan att överge sin post.",al={"varför behövs hjälp","varför tillkalla äventyrare","brist på milis i darkshire"}},{q="Var finns spindlarna?",a="Små giftspindlar har stora bon i Duskwoods västra skogar och lurar i snåren strax intill huvudvägen från Westfall.",al={"spindlarnas plats","var finns små giftspindlar","spindelskog"}},{q="Vad gör spindlarna så farliga för vakterna?",a="Förutom att de är så många har de ett kraftfullt gift som förlamar och löser upp kött. Night Watchs män blir hjälplösa när de fastnar och hängs upp bland grenarna som lättfångade byten.",al={"spindelgift","spindlarnas offer","spindeloffer"}},{q="Är det här de enda spindlarna i Duskwood?",a="Nej. De små giftspindlarna är bara de mindre ungarna. Djupare inne i skogen finns mycket större och dödligare exemplar som utgör ett ännu allvarligare hot mot resande.",al={"andra spindlar i duskwood","spindelarter","giftspindlar"}},{q="Varför har insekts- och spindelbeståndet vuxit så kraftigt?",a="Den utbredda magiska korruptionen som täcker Duskwood har förvridit den inhemska faunan och gjort den aggressivare, större och dödligare i hela den fördärvade skogen.",al={"varför så många spindlar","duskwoods korruption av naturen","spindlarnas ursprung"}}},fx={["19037cd1"]={q="Varför vill Watcher Dodds att spindlarna ska utrotas?",a="Pygmy Venom Web Spiders har tagit över Duskwoods västra gräns, och Night Watch har för få mannar för att ta itu med dem. Watcher Dodds har redan förlorat flera av sina män till deras gift och nät, och Commander Ebonlocke kan inte avvara soldater så långt från Darkshire.",al={"varför döda pygmy venom web spiders","dodds motiv för spindlarna","varför vill dodds ha det här gjort"}},["3807547d"]={q="Vad är Pygmy Venom Web Spiders?",a="Pygmy Venom Web Spiders är aggressivt revirhävdande spindeldjur som hemsöker Duskwoods västra gränstrakter. De är mindre än de fullvuxna, monstruösa spindlarna längre in i skogen, men jagar i svärmar, fångar oförsiktiga resenärer i nästen av nät och producerar ett kraftigt gift som kan smälta bort bytesdjurets kött inifrån.",al={"pygmy venom web spiders","vilka jagar vi","spindlarna i västra duskwood"}}},fp="20,168,20.213.0,29.344.0,22.105.0,56.180.0,32.105.0,51.148.0,39.137.0,63.133.0"}
P.entries["quest:2458"] = {n="Deep Cover",s="Shenthul skickar en lovande Horde-rogu e till The Sludge Fen för att kontakta en agent som gömmer sig bland Venture Company. Shattered Hand har ägnat ett år åt att placera Taskmaster Fizzule inne på företagets borrfält, där han håller uppsikt över deras planer.",h="Shenthul skickar en lovande Horde-rogu e till The Sludge Fen för att kontakta en agent som gömmer sig bland...",kw={"skurk i barrens","deep cover","signalpistol","shattered hand","shenthul","the sludge fen","taskmaster fizzule","venture company"},ang={["class:Rogue"]="Som Horde-rogue tar du ett steg från att spana på gatorna mot betrodda uppdrag ute i fält, där du samordnar i hemlighet.",["faction:Horde"]="Som medlem av Horde ser du hur Venture Companys skogsavverkning och borrning hotar Hordes landområden och resurser i The Barrens."},sec={{t="En spion bland profitörerna",b="Shattered Hand skyddar Orgrimmars intressen genom hemlig underrättelseverksamhet och lönnmord. I ett år arbetade dess medlemmar på att placera en agent bland Venture Companys folk. Taskmaster Fizzule fick en plats vid deras borrutpost norr om The Sludge Fen, bland företagets legosoldater."},{t="Tecken och signaler",b="Fizzule måste behålla sitt hårda rykte för att tillfredsställa Venture Companys förmän. En oväntad besökare kan utlösa en attack. Rogues som når hans torn måste avfyra två signalbloss med signalpistolen inom synhåll, närma sig tyst och ge Shattered Hands hemliga hälsning. Då kan Fizzule berätta vad han har lärt sig om företagets växande planer."}},faq={{q="Vem är Taskmaster Fizzule?",a="Taskmaster Fizzule är en Shattered Hand-agent placerad inom Venture Company norr om The Sludge Fen. Han ägnade ett år åt att skaffa sig inflytande bland dess legosoldater medan han höll uppsikt över deras arbete och skickade underrättelser till Orgrimmar.",al={"fizzule","vem är fizzule","taskmaster fizzules identitet"}},{q="Varför anfaller Fizzule om du inte signalerar korrekt?",a="Fizzule upprätthåller det hårda uppträdande som förväntas av en arbetsledare hos Venture Company. Utan signalen med två bloss och Shattered Hands hälsning ser han en främling som närmar sig som en fientlig inkräktare eller rivaliserande agent och anfaller för att skydda sin täckmantel.",al={"varför anfaller fizzule","fizzule fientlig","fizzule dödar mig"}},{q="Var ligger Venture Companys torn?",a="Venture Companys torn blickar ut över borrfälten norr om The Sludge Fen, i norra The Barrens.",al={"fizzules plats","tornets plats","var ligger sludge fen-tornet"}},{q="Varför spionerar horden på Venture Company?",a="Shattered Hand spionerar på Venture Company eftersom dess vårdslösa utvinning, exploatering och våld hotar Kalimdor. Nya underrättelser pekade på en omfattande plan i The Barrens, så Shenthul kallade på sin kontakt.",al={"varför spionera på venture company","hot från venture company"}},{q="Vad händer efter att du fått kontakt med Fizzule?",a="Efter kontakten skickar Fizzule roguen till det närliggande Venture Company-tornet för att döda dess invånare, däribland Grand Foreman Puzik Gallywix, och hämta Zanzil's Altered Mixture som bevis på sitt värde för gillet.",al={"vad händer efter deep cover","efter fizzule"}},{q="Vad är Shattered Hand?",a="Shattered Hand är ett nätverk av rogues, spioner och lönnmördare med bas i Orgrimmars Cleft of Shadow. Det var en gång en ökänd klan på Draenor och samlar nu i hemlighet underrättelser åt Horde.",al={"shattered hand","vilka är shattered hand"}}},fx={aa88dce8={q="Varför skickar Shenthul dig för att ta kontakt i stället för att själv bege sig dit?",a="Shenthul är en instruktör som samordnar skurkarnas uppdrag från Orgrimmars skuggor, medan Taskmaster Fizzule är djupt förklädd bakom fiendens linjer vid The Sludge Fen. Att infiltrera en aktiv bas tillhörande Venture Company kräver en smidig fältagent som kan smita förbi vakter och obemärkt ge signal till en infiltratör, utan att väcka de företagsanställda legoknektarnas uppmärksamhet eller äventyra hela Shattered Hand-nätverket.",al={"varför skicka mig","varför behöver shenthul mig","varför går han inte själv"}}},fp="10,240,22.297.0,17.366.0,26.220.0,58.239.0,43.102.0,47.223.0,47.214.1,27.190.0"}
P.entries["quest:2459"] = {n="Ferocitas the Dream Eater",s="Ferocitas the Dream Eater är ett alliansuppdrag som Tallonkai Swiftroot ger i Dolanaar. När han har återfått sin skadade arvegodsdrömfångare upptäcker Tallonkai att dess kraftfulla smaragdkärna har slitits loss av Gnarlpine-furbolger norr om Starbreeze Village. Äventyrare skickas för att döda de korrumperade mystikerna och återta den stulna ädelstenen från deras ledare, Ferocitas.",h="Ferocitas the Dream Eater är ett alliansuppdrag som Tallonkai Swiftroot ger i Dolanaar.",kw={"dolanaar","drömätaren","emerald dreamcatcher","ferocitas","gnarlpine-mystikerna","starbreeze village","tallonkai swiftroot","tallonkai's jewel","teldrassil"},ang={["class:Druid"]="Drömfångare är kraftfulla föremål knutna till The Emerald Dream. När en korrumperad furbol vanhelgar en kräver det en snabb och naturlig vedergällning.",["race:NightElf"]="Gnarlpine var en gång allierade med Kaldorei, vilket gör korrumperingen av deras mystiker och stölden av heliga talismaner till en gripande tragedi för varje nattalv som försvarar Teldrassil."},sec={{t="Ett vanhelgat arvegods",b="När Tallonkai Swiftroot undersökte drömfångaren som återfunnits i den korrumperade vildmarken, gick lättnaden snabbt över i bestörtning. Den heliga artefakten hade vandaliserats och dess lysande smaragdprydnad slitits loss från den flätade ramen. Bland nattalverna gick ryktet att en grupp Gnarlpine-mystiker norr om Starbreeze Village hade fallit under inflytande av en furbolgledare vid namn Ferocitas the Dream Eater, som fräckt bar en strålande grön sten runt halsen. Tallonkai visste att den heliga ädelstenen var värdelös och vanhelgad i varelsens klor och skickade försvarare för att ta tillbaka den."},{t="Mystikerna måste rensas ut",b="Gnarlpine-furbolgerna som levde i Teldrassils norra trakter var en gång fredliga grannar, men den växande korrumpering som sipprade in i världsträdet drev dem in i raseri och vansinne. Deras mystiker, som en gång utövade harmoniska naturriter, började hämta kraft ur förvrängda magiska energier. Genom att spåra upp Ferocitas och kämpa sig igenom följet av mystiker som vaktar hans skogsgömställe återställer resenärerna balansen i skogen och återfår Tallonkai's Jewel, så att drömfångaren äntligen kan bli hel igen."}},faq={{q="Var hittar jag Ferocitas the Dream Eater?",a="Ferocitas the Dream Eater finns i skogen norr om Starbreeze Village på Teldrassil, omgiven av korrumperade Gnarlpine-mystiker och andra faror i skogen.",al={"ferocitas plats","var finns ferocitas","hitta drömätaren"}},{q="Vem är Ferocitas?",a="Ferocitas är en Gnarlpine-furbolgledare som befaller en grupp korrumperade Gnarlpine-mystiker norr om Starbreeze Village. Han tog smaragden från Tallonkai Swiftroots drömfångare och gjorde ett enkelt halsband av den.",al={"vem är ferocitas","ferocitas bakgrund","vad är drömätaren"}},{q="Varför vill Tallonkai Swiftroot ha tillbaka ädelstenen?",a="Den saknade smaragden är drömfångarens främsta kraftkälla. Utan den kan talismanen inte repareras eller kanalisera The Emerald Dreams beskyddande energier.",al={"varför tallonkai vill ha ädelstenen","tallonkai ädelstenens syfte"}},{q="Kan Gnarlpine verkligen använda smaragdens magi?",a="Nej. Enligt Tallonkai Swiftroot är smaragdens magiska egenskaper helt värdelösa för varelser som Ferocitas och Gnarlpine-mystikerna, som bara åtrådde den som en lysande prydnad.",al={"kan gnarlpine använda drömfångaren","använder ferocitas smaragden"}},{q="Vad händer efter det här uppdraget?",a="Det här uppdraget är det sista kapitlet i kedjan med två delar, som började med The Emerald Dreamcatcher. När du har lämnat ädelstenen till Tallonkai i Dolanaar kan han äntligen reparera sitt arvegods.",al={"uppdrag efter ferocitas","nästa drömfångaruppdrag"}},{q="Varför är Gnarlpine-mystikerna fientliga?",a="Precis som mycket av djurlivet och furbolgstammarna på Teldrassil har Gnarlpine fallit offer för en märklig korrumpering som förvrider grenarna på det nyplanterade världsträdet, förvanskar deras sinnen och gör dem aggressiva.",al={"varför är furbolgerna galna","gnarlpine-korrumpering"}}},fx={["80c83c66"]={q="Vad är Tallonkai's Jewel till för?",a="Den saknade smaragden är den skadade drömfångaren Tallonkai Swiftroots viktiga fokus. Utan den kan talismanen inte fungera, och han behöver få tillbaka stenen oskadd för att äntligen kunna laga den heliga skyddsamuletten.",al={"vad är tallonkai's jewel","tallonkai jewel syfte","vad används den saknade smaragden till"}}},fp="25,258,18.540.0,19.478.0,42.147.0,17.194.0,49.161.0,51.140.0,30.170.0,38.197.0"}
P.entries["quest:246"] = {n="Assessing the Threat",s="Assessing the Threat är en försvarsoperation på spaning som Deputy Feldon beställt i Lakeshire. Med den lokala garnisonen hårt ansträngd och utan förstärkningar från Stormwind anlitas äventyrare för att decimera gnollflockar som tränger fram längs den södra vägen och bedöma hur stort hotet växer sig.",h="Assessing the Threat är en försvarsoperation på spaning som Deputy Feldon beställt i Lakeshire.",kw={"bedömning","feldon","gnoller","lakeshire","mongrel","poacher","spaning","redridge","hot"},ang={["class:Warrior"]="Deputy Feldon begär aktiv stridsspaning där en beväpnad kämpe prövas genom att ta sig in i befästa fiendeläger och slå ut deras förtrupp.",["faction:Alliance"]="Redridge visar sprickorna i Alliansens hjärtland, där försummade gränsbyar måste anlita fristående hjältar för att överleva medan huvudstaden vänder bort blicken.",["race:Human"]="För mänskliga försvarare är skyddet av Lakeshire personligt. Gränsbygdens familjer får bära följderna av den politiska handlingsförlamningen i Stormwind Keep."},sec={{t="En pressad gränsbygd",b="Staden Lakeshire kämpar för sin överlevnad på flera fronter. Blackrock-orkernas krigarskaror kommer ner från höjderna, samtidigt som aggressiva gnollflockar härjar i dalarna. Därför kan de lokala försvararna inte avvara soldater till vanliga spaningspatruller. När de första rapporterna bekräftade att gnoller trängde in över gränsen vände sig Deputy Feldon till utomstående hjälp. I stället för att skicka vanliga stadsvakter ut i vildmarken betalar staden kringresande hjältar för att pröva fiendens styrka på plats."},{t="Spaning med våld",b="Uppdraget skickar spejare längs Redridges södra väg, in bland lägren tillhörande Redridge Mongrels och Poachers. Det här är en underrättelseoperation där fienden nöts ner: förtruppens spejare röjs undan, försörjningslinjer störs och det bedöms om flockarna bara är kringströvande asätare eller en organiserad militär närvaro som hotar bosättningen. De blodiga skärmytslingarna ger Feldon konkreta siffror som behövs för att planera Lakeshires ansträngda försvar."}},faq={{q="Varför skickar Deputy Feldon äventyrare i stället för stadsvakter?",a="Lakeshires garnison har kritisk personalbrist. Inga förstärkningar kommer från Stormwind City, och fientliga styrkor pressar på från alla håll. Stadsvakten kan därför inte avvara soldaterna som krävs för långa patruller längs den södra vägen.",al={"varför anlita äventyrare","var är vakterna","vaktbrist i lakeshire"}},{q="Var finns gnollerna under uppdraget?",a="Redridge Mongrels och Poachers har utspridda krigsläger längs den södra vägen och i Redridge Mountains låga utlöpare, söder om Lakeshire och nära gränspassen.",al={"var finns redridge mongrels","gnollernas platser i redridge","gnoller vid södra vägen"}},{q="Vad är det strategiska syftet med att decimera gnollerna?",a="Operationen har två syften: den driver tillbaka förtruppens spejare som tränger fram mot vägen, och den ger förstahandsunderrättelser om Redridge-gnollernas antal, vapen och disciplin.",al={"varför döda gnoller","syftet med hotbedömningen","lakeshires försvar"}},{q="Hjälper Stormwind City till med gnollhotet?",a="Nej. Stormwind House of Nobles och regentrådet har hållit inne med reguljärt militärt stöd till avlägsna områden som Redridge. Därför måste lokala myndigheter som Magistrate Solomon och Deputy Feldon förlita sig på avlönade legosoldater.",al={"förstärkningar från stormwind","varför hjälper inte stormwind","stormwinds armé i lakeshire"}},{q="Vad gör Deputy Feldon med din rapport?",a="Deputy Feldon bedömer flockarnas styrka och uthållighet och bekräftar att de södra gnollerna utgör ett allvarligt militärt hot, inte bara isolerade bestar. Sedan ber han dig hjälpa andra av stadens ledare att stärka försvaret.",al={"feldons reaktion","vad händer efter assessing the threat","lämna in rapporten"}},{q="Hur hänger det här uppdraget ihop med det föregående?",a="Det är den direkta uppföljaren till Encroaching Gnolls. Efter att du först larmat garnisonen om gnollernas rörelser gav Feldon dig i uppdrag att genomföra den här stridspatrullen för att bedöma hur allvarligt intrånget egentligen är.",al={"koppling till uppdragskedjan","uppföljning till encroaching gnolls","förutsättningsuppdrag"}}},fx={["6de7b21c"]={q="Vilka Redridge-gnoller ska du utrota?",a="Du skickas mot Redridge Mongrels och Poachers, som slagit läger längs den södra vägen. De här vildsinta gnollerna samlas längs stadens livsnerv, trakasserar resenärer, stryper försörjningslederna och tränger farligt nära själva Lakeshire, samtidigt som stadens försvar är hårt ansträngt.",al={"redridge mongrels och poachers","vilka är gnollerna i redridge","gnollhotet i redridge"}}},fp="20,203,19.351.0,23.356.0,63.218.0,46.162.0,54.174.0,47.219.0,44.223.0,46.160.0"}
P.entries["quest:2460"] = {n="The Shattered Salute",s="I Orgrimmars Cleft of Shadow lär Shenthul nya skurkar en tyst signal. The Shattered Hand använder den för att säkert känna igen sina agenter ute på fältet.",h="I Orgrimmars Cleft of Shadow lär Shenthul nya skurkar en tyst signal.",kw={"cleft of shadow","hemlig","djup täckmantel","orgrimmar","rogue","shattered hand","shattered salute","shenthul"},ang={["class:Rogue"]="Som hordskurk lär du dig The Shattered Hands hemliga signaler och går från vanlig ficktjuv till betrodd agent i Orgrimmars underrättelsenätverk.",["faction:Horde"]="Som medlem av horden tjänar du under krigshövding Thrall, som leder med heder. Horden förlitar sig också på The Shattered Hands hemliga metoder för att stoppa hot innan de når ytan."},sec={{t="Tecken och skuggor",b="I Orgrimmars Cleft of Shadow arbetar The Shattered Hand i hemlighet som Thralls hordes underrättelse- och lönnmördargren. Dess agenter kan inte använda fanor eller militära tecken under farliga, hemliga uppdrag. Shenthul lär nyinvigda skurkar The Shattered Salute, en tyst gest som låter allierade känna igen varandra."},{t="Förberedelser för fältet",b="För Shenthuls skurkar är det viktigt yrkeskunnande, inte en ceremoni, att lära sig hälsningen. Agenter som skickas ut i fara eller för att infiltrera rivaliserande fraktioner måste kunna bekräfta kontakter utan att varna förbipasserande eller mål. Innan Shenthul anförtro dem hemligt fältarbete förväntar han sig att de känner igen och besvarar gesten utan att tveka."}},faq={{q="Vad är syftet med The Shattered Salute?",a="The Shattered Salute låter agenter från The Shattered Hand känna igen varandra, även under djup täckmantel eller på fientligt territorium, utan att avslöja sina band för utomstående.",al={"varför måste jag kunna hälsningen","syftet med shattered salute","vad gör hälsningen"}},{q="Vem lär ut The Shattered Salute?",a="Shenthul, en skurkstränare stationerad djupt inne i Orgrimmars Cleft of Shadow, lär ut hälsningen.",al={"vem ger uppdraget","vem är shenthul","var lär jag mig hälsningen"}},{q="Vilken organisation använder den här gesten?",a="The Shattered Hand använder gesten. Ordens orciska skurkar, spioner och lönnmördare tjänar Thralls hord från Orgrimmars skuggor.",al={"shattered hand-klanen","vilka är shattered hand","vilket gille använder den här"}},{q="Varför måste man lära sig hälsningen innan man ger sig ut på fältet?",a="Agenter på infiltrationsuppdrag använder hälsningen för att kontakta allierade under täckmantel utan att röja sin täckmantel eller missta en fiende för en allierad.",al={"varför öva på hälsningen","krävs hälsningen"}},{q="Var äger träningen rum?",a="Träningen äger rum i Cleft of Shadow, ett underjordiskt distrikt under Orgrimmar där skurkar, häxmästare och andra som utövar förbjudna konster samlas utom allmänhetens insyn.",al={"hälsningens plats","var finns shenthul"}},{q="Vilket uppdrag följer efter att man har bemästrat hälsningen?",a="När Shenthul är nöjd med en agents skicklighet ger han dem uppdrag under djup täckmantel. Uppdraget prövar deras förmåga att använda signalen för att kontakta agenter ute på fältet.",al={"what comes next","nästa uppdrag efter hälsningen","uppdrag under djup täckmantel"}}},fp="20,149,17.321.0,25.325.0,44.154.0,33.96.0,36.132.0,65.138.0,36.186.0,51.179.0"}
P.entries["quest:247"] = {n="The Hunt Completed",s="The Hunt Completed är höjdpunkten i Senani Thunderhearts prövningar med stora bestar i Ashenvale. Genom att fälla Ursangous, Shadumbra och Sharptalon visar en Horde-mästare sin styrka, uthållighet och urkraft i en omstridd skog.",h="The Hunt Completed är höjdpunkten i Senani Thunderhearts prövningar med stora bestar i Ashenvale.",kw={"ashenvale","bestar","jakt","rovdjur","senani","shadumbra","sharptalon","thunderheart","trofé","ursangous"},ang={["class:Hunter"]="Att besegra tre toppredatorer i Ashenvale är det ultimata provet på spårning och skytte. Det bevisar att dina instinkter kan mäta sig med vilddjuren själva.",["faction:Horde"]="Att tämja Ashenvales bestar bidrar till att säkra Hordes fotfäste i en farlig och fientlig skog full av rovdjur och Alliance-vakter.",["race:Tauren"]="För Shu'halo är jakten på Ursangous, Shadumbra och Sharptalon ett urgammalt prov på respekt, balans och stolthet över förfäderna."},sec={{t="Ett jägarprov",b="Senani Thunderheart, som är stationerad bland Hordes styrkor i Ashenvale, prövar resenärer inte bara genom deras lojalitet mot krigshövdingen, utan också genom deras förmåga att överleva i vildmarken. Ashenvale-jakten riktar in sig på tre legendariska rovdjur som smyger under de gamla trädens grenar: björnen Ursangous, katten Shadumbra och den vildsinta hippogryfen Sharptalon. Att fälla alla tre och säkra deras troféer bevisar att jägarblod flödar i utmanarens ådror."},{t="Hedra förfäderna",b="För tauren är jakten en helig handling som handlar om balans och respekt, även mitt under ett pågående krig. Genom att övervinna Ashenvales främsta fasor hedrar jägaren landets andar och vinner Thunderhearts förfäders välsignelser. Jakten avslutas med ett formellt erkännande och en ynnestgåva, vilket befäster mästarens rykte i hela skogen."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Uppdraget avslutas hos Senani Thunderheart, en taurenjägare stationerad med Horde i Ashenvales uråldriga skogar.",al={"uppdragsgivare","var lämnar man in uppdraget","senani thunderhearts plats"}},{q="Vad krävs för att klara jakten?",a="Du måste döda tre toppredatorer som strövar omkring i Ashenvale och lämna bevis på att de är döda: tassen från björnen Ursangous, huvudet från nattsabeln Shadumbra och klon från hippogryfen Sharptalon.",al={"vilka bestar ska dödas","förkunskapskrav","vilka djur"}},{q="Varför vill Senani Thunderheart att dessa bestar dödas?",a="Jakten är ett prov på styrka och uthållighet. Att fälla så mäktiga bestar visar att en resenär har det rätta hjärtat och instinkten hos ett rovdjur som kan överleva i Ashenvales förrädiska vildmark.",al={"varför jaga dem","senanis motiv","jaktens syfte"}},{q="Vilken kulturell betydelse har jakten för Horde?",a="För tauren som Senani Thunderheart är det en hedervärd tradition att pröva sin styrka mot mäktiga bestar, en tradition som vädjar till andar och förfäder. Den visar att man behärskar vildmarken utan att vanära sig genom hänsynslöshet.",al={"tauren-jaktens historia","kulturell betydelse","varför jagar tauren bestar"}},{q="Erkänns prövningen av hela Horde?",a="Ja. När du klarar jakten räknas du som en beprövad jägare i ögonen på Horde-styrkorna i Ashenvale. Du vinner förfädernas välsignelser och dina kamraters respekt.",al={"erkännande från horde","är det officiellt","hordens erkännande"}},{q="Vilka tre bestar jagas i Ashenvale?",a="Målen är Ursangous, den stora björnen, Shadumbra, den smygande nattsabeln, och Sharptalon, den dödliga hippogryfen.",al={"de tre bestarna","jaktmål","namngivna djur"}}},fx={ded238b8={q="Vilka bestar fick du i uppdrag att döda under jakten i Ashenvale?",a="Prövningen krävde att du spårade upp och fällde tre av Ashenvales våldsammaste rovdjur: den uråldriga björnen Ursangous, den svårfångade nattsabeln Shadumbra och den vildsinta hippogryfen Sharptalon. De här vilddjuren härskade över skogens trädkronor och snår, utgjorde allvarliga hot mot resenärer och var det ultimata provet på styrka, tålamod och jaktförmåga i den otämjda vildmarken.",al={"vilka bestar dödade jag","jaktmålen i ashenvale","vilka bestar jagades i hunt completed"}}},fp="18,194,16.381.0,22.347.0,49.90.0,47.126.0,53.178.0,59.205.0,45.150.0,54.104.0"}
P.entries["quest:2478"] = {n="Mission: Possible But Not Probable",s="I norra The Barrens ställs hordens skurkar inför en utpost från Venture Company som sätter deras smygande, fickstölder och stridskonst på prov. De infiltrerar ett oljetorn, dödar Grand Foreman Puzik Gallywix och tar med sig en kraftfull kemisk brygd till Shattered Hand.",h="I norra The Barrens ställs hordens skurkar inför en utpost från Venture Company som sätter deras smygande...",kw={"the barrens","fizzule","låsdyrkning","gifter","puzik gallywix","shattered hand","shenthul","silixiz","the sludge fen","zanzil"},ang={["class:Rogue"]="Som skurk lär du dig praktiska färdigheter i låsdyrkning, fickstöld och att utnyttja svagheter. De färdigheterna öppnar vägen till Shattered Hands dödliga knep och gifter.",["faction:Horde"]="Shattered Hand verkar i skuggorna i Orgrimmar och håller uppsikt över farliga inkräktare från företag, som Venture Company, medan de exploaterar The Barrens."},sec={{t="Infiltration av Venture Co.",b="Norr om oljeriggarna vid The Sludge Fen håller Venture Company ett avskilt borrtorn. Taskmaster Fizzule, en agent från Shattered Hand som utger sig för att vara arbetsledare hos Venture Company, beordrar skurkarna att förlita sig på undre världens knep i stället för ett öppet angrepp. Han ber dem stjäla nyckeln från Foreman Silixiz och behålla den åt honom. Sedan tar de sig upp förbi arbetare och vaktposter som förändrats av tornets experiment."},{t="En kemisk katastrof",b="Ett experimentellt ämne som kallas Zanzil's Altered Mixture har förändrat tornets invånare. Giftet försvagar vakterna och gör dem sårbara för snabba hugg, blödande attacker och plötsliga bakhåll. Det har också gjort anläggningen instabil. På toppen vaktar Grand Foreman Puzik Gallywix en låst kista med brygden."},{t="Pliktens pris",b="Ångorna från den förändrade blandningen läcker ut när skurken öppnar Gallywix låsta kista. De bryter smygandet, dränerar livskraften och orsakar ett försvagande tillstånd som varar länge. I Orgrimmar tar Shenthul, Shattered Hands mentor, emot Gallywix huvud och det kemiska provet. Han sörjer Fizzules utsatta läge och skickar den döende agenten för att söka botemedel."}},faq={{q="Var ligger Venture Co.-tornet?",a="Venture Companys torn står i norra The Barrens, strax norr om borranläggningen vid The Sludge Fen. Fientliga arbetare från Venture Company omringar det, och Taskmaster Fizzule gömmer sig nära ett träd strax österut.",al={"var ligger venture co.-tornet","var ligger gallywix torn","tornet vid sludge fen"}},{q="Hur får man tag i nyckeln till tornet?",a="Foreman Silixiz bär på tornets nyckel och strövar omkring på marken utanför dess bas. Stjäl den från honom medan du är dold; om du dödar honom får du inte nyckeln.",al={"silixiz tornnyckel","hur får man tornnyckeln","var finns nyckeln"}},{q="Vad är Zanzil's Altered Mixture?",a="Zanzil's Altered Mixture är en alkemisk brygd baserad på formlerna från den ökände trollhäxdoktorn Zanzil. Venture Company kom över den, och dess instabila ångor förgiftade tornets arbetare och gjorde dem sjuka, muterade och sårbara för skurkarnas stridskonster.",al={"zanzils blandning","vad är giftet","förändrad blandning"}},{q="Varför kan jag inte smyga efter att ha öppnat låsboxen?",a="När du öppnar Gallywix låsta kista frigörs koncentrerade ångor från den förändrade blandningen. Det giftiga tillståndet varar i flera dagar, försvagar dina attribut och bryter ditt smygande tills en erfaren apotekare botar dig.",al={"zanzils beröring","förgiftad efter kistan","kan inte smyga som skurk på uppdrag","sjudagarsgift"}},{q="Vem är Taskmaster Fizzule?",a="Taskmaster Fizzule är en agent från Shattered Hand, hordens skurkorganisation, som arbetar djupt under täckmantel. Den mörka järndvärgen utger sig för att vara en hänsynslös arbetsledare hos Venture Company i The Barrens och leder rekryter i sabotage mot företagets tillgångar utan att röja sig själv.",al={"fizzule","vem gav uppdraget","fizzules bakgrund"}},{q="Vem är Grand Foreman Puzik Gallywix?",a="Grand Foreman Puzik Gallywix är den goblinska förman som styr Venture Companys torn nära The Sludge Fen. Han vaktar det stulna förrådet med Zanzils brygd tills agenter från Shattered Hand dödar honom.",al={"puzik gallywix","är gallywix i the barrens","arbetsledaren gallywix"}}},fx={["78e0c22c"]={q="Vad används Cache of Zanzil's Altered Mixture till?",a="Inlåst högst upp i tornet, i Gallywix personliga kista, finns det återstående lagret av den märkliga, försvagande brygd som framställts enligt Zanzils formler. The Shattered Hand behöver att du hämtar blandningen så att dess giftiga och muterande egenskaper kan studeras och säkert hållas under kontroll av skuggmästare i Orgrimmar.",al={"cache med zanzils förändrade blandning","zanzils blandningscache","varför hämta blandningen"}},["07291131"]={q="Varför skickas du efter Grand Foreman Puzik Gallywix och arbetarna i tornet?",a="Du skickas för att rensa ut den korrumperade Venture Company-personalen i tornet i norra Barrens. Under ledning av Grand Foreman Puzik Gallywix hanterade gruppen Zanzils giftiga ämne fel, vilket förvandlade arbetarna till muterade vidunder och utsatte regionen för fara. Genom att döda utkikarna, patrullerna, arbetarna och Gallywix själv slår du ut deras industriella fäste som breder ut sig.",al={"vilka slåss du mot i tornet","mål i venture company-tornet","varför döda gallywix"}},fa60081f={q="Varför behöver Fizzule din hjälp i stället för att rensa tornet själv?",a="Fizzule upprätthåller en osäker identitet som infiltratör och förman hos Venture Company. Om han öppet infiltrerade tornet, dödade förmän eller plundrade Gallywix låsta kista skulle hans täckmantel genast röjas. Som utomstående agent för The Shattered Hand har du den dödliga smygförmåga som krävs för att rensa anläggningen utan att avslöja hans roll.",al={"varför jag, fizzule","varför behöver fizzule hjälp","varför rensar fizzule inte tornet"}},["2a5cd36a"]={q="Varför vill Taskmaster Fizzule att Venture Co.-tornet ska förstöras?",a="Taskmaster Fizzule arbetar djupt under täckmantel för Shattered Hand och har bevittnat hur Venture Company experimenterar med ett flyktigt, muterande gift. Nu när den förorenade blandningen har korrumperat och försvagat alla i tornet ser Fizzule en möjlighet att slå ut hela verksamheten, undanröja Grand Foreman Gallywix ledarskap och säkra den dödliga blandningen åt Orgrimmar innan den sprider sig okontrollerat.",al={"fizzules motiv","varför döda gallywix fizzule","varför anfalla venture co.-tornet"}},f260e633={q="Varför vill Shenthul ha Gallywix's Head?",a="Att skilja huvudet från Grand Foreman Puzik Gallywix kropp ger ett obestridligt bevis på hans död och på att Venture Companys hierarki i tornet har upplösts. När du visar upp det för Shenthul i Cleft of Shadow bekräftar du att den främsta tillsyningsmannen bakom verksamheten i området har eliminerats för gott.",al={"gallywix head syfte","varför ta gallywix head","vad används gallywix head till"}},["53be2ad7"]={q="Vad används Silixiz's Tower Key till?",a="Foreman Silixiz bär nyckeln utanför tornet. Fizzule ber dig stjäla och behålla den eftersom han kanske behöver den senare. Att återfå den är ett av uppdragets mål.",al={"silixiz tower key","vad nyckeln till tornet är till för","varför stjäla nyckeln till tornet"}}},fp="34,228,31.395.0,22.320.1,17.367.2,39.210.0,39.156.0,33.271.0,53.210.1,26.259.0,36.199.0"}
P.entries["quest:2479"] = {n="Hinott's Assistance",s="I Orgrimmar söker förgiftade rövare Hinotts hjälp innan Zanzil's Mixture tar deras liv. Giftet kom från en infiltration i The Barrens, och Serge Hinott i Tarren Mill kan erbjuda ett botemedel och lära ut hur man brygger gifter.",h="I Orgrimmar söker förgiftade rövare Hinotts hjälp innan Zanzil's Mixture tar deras liv.",kw={"hillsbrad foothills","hinott's assistance","skurkarnas giftuppdrag","serge hinott","shenthul","tarren mill","zeppelinare till undercity","zanzil","zanzil's mixture"},ang={["class:Rogue"]="Som rövare ställs du inför en övergångsrit som prövar din uthållighet och öppnar vägen till att tillverka dina egna gifter.",["faction:Horde"]="Som medlem av Horde får du se hur orc- och trollrövare från Kalimdor samarbetar praktiskt med Forsakens alkemiska kunskaper i Lordaeron."},sec={{t="Ett giftigt dilemma",b="En våghalsig infiltration av Venture Company's torn norr om The Sludge Fen lämnar rövare förgiftade av Zanzil's Mixture. Giftet gör deras reflexer långsammare och hotar deras liv. Shenthul, rövartränaren i Orgrimmar, vet att lokala botemedel inte kan hjälpa. Han skickar den förgiftade rövaren över havet till Eastern Kingdoms för vård."},{t="Resan till Tarren Mill",b="Jakten på ett botemedel leder söderut genom Lordaeron till Tarren Mill, en by i Hillsbrad Foothills. Serge Hinott bor där och är apotekare, känd för sin fascination för starka brygder. Vanliga helare ryggar tillbaka för Zanzil's gift, men Hinott behandlar den dödliga blandningen med yrkesmässig förtjusning. Han kan dissekera den motbjudande brygden och lära värdiga rövare att brygga sina egna gifter."}},faq={{q="Varför måste jag träffa Serge Hinott?",a="Serge Hinott är apotekare i Tarren Mill och specialiserar sig på sällsynta gifter och deras motgifter. Vanliga helare kan inte rena kroppen från Zanzil's Mixture, så Hinott är den du kan vända dig till för att analysera den, rädda ditt liv och lära dig att brygga gifter.",al={"varför hinott","vem botar giftet","serge hinotts roll"}},{q="Var ligger Tarren Mill?",a="Tarren Mill är en Forsaken-bosättning i norra Hillsbrad Foothills. Från Orgrimmar tar du zeppelinaren till Undercity i Tirisfal Glades, reser söderut genom Silverpine Forest och svänger sedan österut längs vägen in i Hillsbrad.",al={"var ligger tarren mill","hur tar jag mig till tarren mill","var finns hinott"}},{q="Hur blev jag förgiftad från början?",a="Du blev smittad under det hemliga uppdraget Mission: Possible But Not Probable vid Venture Company's torn norr om The Sludge Fen i The Barrens. När du öppnade den hårt bevakade kistan utsattes du för Zanzil's Mixture, vilket gav dig ett långvarigt och försvagande lidande.",al={"hur fick jag zanzils gift","mission possible gift","varför är jag förgiftad"}},{q="Vad händer när Serge Hinott får provet?",a="När Serge Hinott får provet undersöker han dess egenskaper och bereder ett motgift som renar din kropp. När han har botat giftet delar han med sig av sin kunskap, så att rövare kan lära sig att brygga och använda sina egna gifter.",al={"uppföljning på hinott-uppdraget","blir jag botad","efter hinott's assistance"}},{q="Vem är Shenthul, och varför skickade han iväg mig?",a="Shenthul är rövartränare för Shattered Hand i Cleft of Shadow i Orgrimmar. Han övervakade ditt skicklighetsprov i The Barrens och insåg att Zanzil's Mixture låg bortom Orgrimmars medicinska kunskaper, så han skickade dig till en specialist i Hillsbrad.",al={"vem är shenthul","shenthul i orgrimmar","varför skickade tränaren iväg mig"}},{q="Kan någon annan klass slutföra det här uppdraget?",a="Nej. Den här träningen är en del av rövarnas tradition och lär ut grunderna i att brygga gifter och botemedel.",al={"uppdrag endast för skurkar","kan krigare göra hinott's assistance"}}},fp="19,233,19.332.0,22.383.0,34.240.0,29.226.0,42.279.0,52.221.1,44.250.0,40.108.0"}
P.entries["quest:248"] = {n="Looking Further",s="Looking Further är ett alliansuppdrag i spionage, lett av magikern Theocritus genom en förtrollad förbindelse. För att undersöka spänningarna mellan den avfällige magikern Morganth och Blackrock-orcherna måste du infiltrera vakttornet intill Stonewatch Keep och placera en förtrollad glyf i en obemärkt behållare.",h="Looking Further är ett alliansuppdrag i spionage, lett av magikern Theocritus genom en förtrollad förbindelse.",kw={"tom kruka","glyph of azora","looking further","morganth","gammal lejonstaty","stonewatch","stonewatch keep","theocritus","tower of ilgalar"},ang={["class:Mage"]="Theocritus förlitar sig på avancerad skådandemagi på långt håll genom Glyph of Azora. Det visar hur Azoras magiker upprättar magisk övervakning i fientliga områden.",["faction:Alliance"]="Stonewatch Keep är fortfarande Blackrock-klanens främsta fäste i Redridge. Underrättelser om deras inbördes strid med Morganth är avgörande för att försvara Lakeshire."},sec={{t="En spricka i Redridge",b="Från sin helgedom i Elwynn Forest håller magikern Theocritus vaksam uppsikt över östra Redridge med hjälp av spådomsmagi. När han bevakar Tower of Ilgalar upptäcker han plötslig osämja mellan den upproriske mänsklige häxmästaren Morganth och Blackrock-orcherna som befäst sig i Stonewatch Keep. I stället för att samarbeta mot kungariket Stormwind ligger dessa fientliga grupper i konflikt om en okänd belöning, vilket får Theocritus att ingripa innan maktbalansen rubbas."},{t="Ögat över Stonewatch",b="För att tränga igenom Stonewatch Keeps försvar behöver Theocritus en andra magisk förankringspunkt. Han befaller äventyrarna att bestiga det intakta vakttornet intill den ruinerade fästningen. Där, bland garnisonens bråte, blir en tom kruka som orcherna kastat bort ett perfekt, alldagligt gömställe. När Glyph of Azora har fästs inuti kärlet kan Theocritus telepatiskt söka igenom sinnena i Stonewatch och ta reda på vad som drev Morganth och Blackrock-orcherna isär."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Uppdraget ges av Theocritus, Azoras magiker, som talar genom den gamla lejonstatyn i Redridge Mountains efter att du slutfört hans föregående uppdrag.",al={"vem ger uppdraget","uppdragsgivare","gammal lejonstaty"}},{q="Varför spionerar Theocritus på Stonewatch Keep?",a="Theocritus upptäckte en växande fientlighet mellan Morganth, den avfällige mörke magikern i Tower of Ilgalar, och Blackrock-orcherna som ockuperar Stonewatch Keep. Han vill ta reda på vad som utlöste deras konflikt.",al={"varför spionera på orcher","theocritus syfte","varför stonewatch"}},{q="Var finns behållaren?",a="Behållaren är en tom kruka som står ovanpå tunnor högst upp i det intakta vakttornet, alldeles intill huvudingången till Stonewatch Keep.",al={"den tomma krukans plats","var placera glyfen","var ligger vakttornet"}},{q="Vad gör Glyph of Azora?",a="Den fungerar som ett magiskt fokus för skådande och spådom och låter Theocritus bevaka omgivningen på avstånd och tränga in i sinnena hos Blackrock-orcherna inne i fästningen.",al={"glyph of azoras syfte","vad gör glyfen"}},{q="Vad händer när glyfen har placerats?",a="När Theocritus har skådat konfliktens ursprung ger han dig i uppdrag att jaga Morganth i Tower of Ilgalar och hämta hans Pendant of Shadow.",al={"nästa uppdrag","vad händer sedan","uppföljning till looking further"}},{q="Varför använda en tom kruka?",a="En magisk spionruna behöver ett oansenligt kärl så att vakterna inte upptäcker eller förstör den. Den övergivna, illaluktande spritkrukan som lämnats bortglömd på tunnorna är ett perfekt gömställe.",al={"varför krukan","den tomma krukans bakgrund"}}},fx={["3912e7be"]={q="Vem ska jag spionera på vid Stonewatch Keep?",a="Du spionerar på Blackrock-orcherna som har tagit över Stonewatch Keep. Från sin utsiktspunkt har magikern Theocritus upptäckt att en konflikt håller på att blossa upp mellan dessa fientliga orcher och den mörke trollkarlen Morganth vid Tower of Ilgalar. När du placerar glyfen kan magikern undersöka sinnena hos dem som befinner sig i Stonewatch och ta reda på den verkliga orsaken till motsättningarna.",al={"vem finns i stonewatch keep","mål i stonewatch keep","mål för looking further"}},["6347ef38"]={q="Varför behöver Theocritus en äventyrare som placerar glyfen?",a="Theocritus är bunden till Tower of Azora och kanaliserar sin magi genom förtrollade reliker som Old Lion Statue för att bevaka hot i hela Redridge. Stonewatch Keep vimlar av farliga Blackrock-orcher, och för att infiltrera fästet krävs någon som kan kämpa sig till tornet utan att bli upptäckt, snarare än en ensam, sårbar magiker som lämnar sin post.",al={"varför skickas jag på looking further","varför gör inte theocritus det","varför jag vid stonewatch"}}},fp="15,241,18.418.0,21.425.1,29.129.0,44.201.0,31.114.0,32.182.0,38.141.1,21.170.0"}
P.entries["quest:2480"] = {n="Hinott's Assistance",s="Hinott's Assistance fullbordar en hordskurks resa för att övervinna Zanzil's dödliga krypande gift. Den drabbade agenten söker upp apotekaren Serge Hinott i Tarren Mill och får ett motgift samt grundläggande utbildning i alkemisk giftkonst.",h="Hinott's Assistance fullbordar en hordskurks resa för att övervinna Zanzil's dödliga krypande gift.",kw={"motgift","botemedel","hillsbrad","hinott","gifter","skurkens uppdrag","serge hinott","tarren mill","zanzil"},ang={["class:Rogue"]="Denna övergångsrit botar den försvagande åkomma du drabbades av under din invigning och låser upp kunskapen du behöver för att tillreda taktiska gifter.",["faction:Horde"]="Förfallen alkemi är oumbärlig för hordens smygande agenter och omvandlar exotiska djungeltrollgifter till grundläggande fältkunskap.",["race:Undead"]="Apotekaren Hinott visar hur Royal Apothecary Society hyser en distanserad, vetenskaplig beundran för alla gifter som vittnar om genuint hantverk, oavsett ursprung."},sec={{t="Ett giftmästerverk",b="Efter att ha drabbats av ett våldsamt, sinnesförändrande gift under ett uppdrag i The Barrens skickas hordskurkar norrut till Tarren Mill för att rådfråga Serge Hinott. Hinott är en Förfallen kemist med ett enda fokus och visar professionell vördnad för giftet som djungeltrollet i exil Zanzil kokat ihop. Han bryr sig inte om trollens identitet eller härkomst, men berömmer öppet brygdens förödande verkan och vill studera hur den fungerar innan han tillverkar ett motgift."},{t="Motgiftet och hantverket",b="För att ta fram botemedlet behöver Hinott bara tid att isolera de verksamma ämnena. Den färdiga brygden hejdar den krypande galenskapen, även om kemisten medger att han inte kan få bort den kvardröjande stanken. När de befriats från det förlamande giftet går skurkarna från offer till utövare och använder Hinotts insikter om Zanzil's verk för att lära sig tillreda egna taktiska gifter."}},faq={{q="Vad händer under Hinott's Assistance?",a="Du behöver bara vänta en liten stund i Tarren Mill medan Serge Hinott tillreder motgiftet. När han är klar kan du prata med honom, ta botemedlet och rena dig från Zanzil's gift.",al={"vad gör jag här","hinott hjälp genomgång","hur slutför jag uppdraget"}},{q="Vem är Serge Hinott?",a="Serge Hinott är en Förfallen alkemist och giftexpert som finns i Tarren Mill i Hillsbrad Foothills. Han delar med sig av sitt specialiserade hantverk till hordskurkar som vill bota ovanliga åkommor och lära sig hur man tillreder gifter.",al={"serge hinott bakgrund","vem är hinott","apotekare i tarren mill"}},{q="Varför är Serge Hinott imponerad av giftet?",a="Hinott ser Zanzil's formel som ett alkemiskt mästerverk tack vare blandningen av krypande galenskap och fysisk försvagning. Även när han arbetar på att neutralisera giftet berömmer han öppet hantverket bakom en så förödande brygd.",al={"zanzils gift reaktion","varför gillar hinott giftet"}},{q="Vad är den kvardröjande lukten som Hinott nämner?",a="Zanzil's Mixture har en stickande, kvalmig lukt som tränger in i offrets porer. Hinotts motgift hejdar giftets spridning och klarnar sinnet, men neutraliserar inte genast den motbjudande stank som dröjer sig kvar.",al={"varför luktar jag","galenskapens lukt","uppdragslukt"}},{q="Vad får man för belöning när uppdraget slutförs?",a="När uppdraget är klart försvinner den ihållande försvagningen som du fick under skurkens klassuppdragsserie, och du kan lära dig färdigheten Rogue Poisons så att du kan brygga egna försvagande gifter.",al={"vad får skurkar","hinotts assistance belöning"}},{q="Var lämnar man in uppdraget?",a="Uppdraget börjar och slutförs hos Serge Hinott i Tarren Mill, som ligger i norra Hillsbrad Foothills.",al={"var finns hinott","plats för inlämning"}}},fp="19,140,19.364.0,26.305.1,40.152.0,20.172.0,44.188.0,44.173.0,45.147.0,30.113.0"}
P.entries["quest:249"] = {n="Morganth",s="Morganth är slutpunkten på magikern Theocritus långa undersökning av en ondskefull rival i Redridge. Äventyrarna får i uppdrag att stoppa en mörk häxmästare som söker en forntida relik med fruktansvärd kraft. De måste ta sig in i Tower of Ilgalar och sätta stopp för hans planer.",h="Morganth är slutpunkten på magikern Theocritus långa undersökning av en ondskefull rival i Redridge.",kw={"elwynn","morganth","pendant of shadow","redridge","scythe of elune","theocritus","tower of azora","tower of ilgalar"},ang={["class:Mage"]="Theocritus står för den flitiga, lärda traditionen bland mänskliga magiker som vakar från höga torn för att skydda riket mot magiker som gått sin egen väg.",["class:Warlock"]="Morganth står för faran med tygellösa ambitioner inom kaosmagi och skuggmagi. Hans öde visar att jakten på reliker som Scythe of Elune leder till ett snabbt fall.",["faction:Alliance"]="När Morganth besegras skyddas Stormwinds utsatta östra gränser och Redridge-regionen hindras från att sjunka ner i mörk trolldom.",["race:NightElf"]="Viskningar om att Scythe of Elune finns i mänskliga händer borde oroa kaldorei djupt, eftersom relikens namn berör heliga och nyckfulla mysterier."},sec={{t="En väktare bortom gränsen",b="Från sin helgedom i Tower of Azora, i östra Elwynn Forest, höll magikern Theocritus sitt vaksamma skådande öga riktat mot Redridges klippor. Det han såg bekräftade hans värsta farhågor: häxmästaren Morganth, som höll till i Tower of Ilgalar, sökte aktivt efter den legendariska Scythe of Elune. När Theocritus insåg att häxmästaren stod på tröskeln till att få denna mörka makt, kallade han på djärva mästare från Alliansen. De måste ingripa innan Morganths skugga föll över hela kungariket Stormwind."},{t="Storma tornspiran",b="Tower of Ilgalar reser sig högt över Redridge-bäckenet, angripet av gnoller och förvridna mystiska energier. Morganth väntade på toppen, beväpnad med skuggmagi och med sin forskning i tryggt förvar. För att konfrontera häxmästaren måste du ta dig upp genom fientlig terräng, fälla magikern och ta hans Pendant of Shadow som obestridligt bevis på att tornspiran fallit och hotet är undanröjt."},{t="Liebladets kvardröjande skugga",b="Morganths nederlag undanröjer ett omedelbart och katastrofalt hot mot Stormwind, men hans jakt på Scythe of Elune visar hur långt relikens mörka legend sträcker sig. Theocritus drar en lättnadens suck när han får Pendant of Shadow, men den forntida liebladets verkliga plats och den förödelse den kan vålla förblir ett oroande mysterium i de kringliggande provinserna."}},faq={{q="Vem är Morganth?",a="Morganth är en mäktig häxmästare som gått sin egen väg och håller till på toppen av Tower of Ilgalar i Redridge Mountains. Han har ägnat sin tid åt att studera mörka konster och söka efter Scythe of Elune, en relik som kan utöva förödande magi.",al={"morganths identitet","vem är morganth","morganths bakgrund"}},{q="Var ligger Tower of Ilgalar?",a="Tower of Ilgalar ligger i östra Redridge Mountains, bortom Stonewatch Keep, där Shadowhide-gnoller slår läger runt dess fot.",al={"tower of ilgalar plats","var ligger morganths torn","tornet i redridge"}},{q="Varför vill Theocritus att Morganth ska dö?",a="Med sina skådande besvärjelser fick Theocritus veta att Morganth jagade Scythe of Elune och fruktade att häxmästaren var nära att få tag i den. En sådan mörk kraft skulle utgöra ett katastrofalt hot mot Redridge och det närliggande kungariket Stormwind.",al={"theocritus motiv","varför döda morganth","theocritus skäl till uppdraget"}},{q="Vad är Scythe of Elune?",a="Scythe of Elune är en relik höljd i mysterium. Theocritus förklarar inte dess krafter, men han fruktar att om Morganth har hittat den kommer Redridge och kungariket Stormwind snart att känna häxmästarens mörka makt.",al={"scythe of elune bakgrund","vad är lien","varför är lien farlig"}},{q="Vad är Pendant of Shadow?",a="Pendant of Shadow är Morganths magiska talisman. Den fungerar både som fokus för hans mörka konster och som avgörande bevis på hans nederlag när den återförs till Theocritus i Tower of Azora.",al={"pendant of shadow","morganths hängsmycke","bevis på morganths död"}},{q="Vilken uppdragskedja leder fram till det här?",a="Det här uppdraget avslutar en kedja på fyra delar som börjar med ”Theocritus' Retrieval” i Elwynn Forest, följt av ”A Watchful Eye” och ”Looking Further”. De innebär att hämta verktyg och upprätta skådande för att hålla uppsikt över Morganths torn.",al={"morganths uppdragskedja","förutsättningar för morganth","hur låser man upp morganth"}}},fx={["23819dbd"]={q="Varför skickar Theocritus dig att möta Morganth i stället för att gå själv?",a="Theocritus medger helt öppet att han inte är beredd att mäta sina magiska krafter direkt med Morganths. Han vakar över gränsen från Tower of Azora och samordnar försvaret mot skuggmagi, men ett anfall mot själva Tower of Ilgalar kräver en djärv och kapabel äventyrare som vågar tränga in i häxmästarens fäste innan Morganths mörka ambitioner hotar hela Stormwind.",al={"varför skicka mig","varför slåss inte theocritus mot morganth","varför inte theocritus"}}},fp="8,293,27.510.0,18.392.0,29.391.1,16.235.0,30.136.0,39.245.0,28.217.0,30.192.0,34.236.0"}
P.entries["quest:2498"] = {n="Return to Denalan",s="Return to Denalan är ett uppdrag för Alliansen som förbinder botanikerna som undersöker korruptionen i Teldrassil. Efter att ha studerat de mossiga tumörerna som drabbat traktens timberlings skickar Rellian Greenspyre dig söderut igen till Lake Al'Ameth för att hjälpa Denalan med en oroande ny upptäckt.",h="Return to Denalan är ett uppdrag för Alliansen som förbinder botanikerna som undersöker korruptionen i...",kw={"denalan","dolanaar","lake al'ameth","oakenscowl","rellian greenspyre","teldrassil","timberlings","tumörer"},ang={["class:Druid"]="Att undersöka onaturliga tumörer på skogens andar går rakt till kärnan i Cenarionorden uppdrag att upprätthålla naturens balans och rena bort lömska fördärv.",["race:NightElf"]="Timberlings är levande uttryck för Teldrassils livskraft. Att hjälpa Denalan är en del av den heliga plikten att läka den växande korruption som hotar ditt folks nya hem."},sec={{t="Ett budskap mellan grenarna",b="Medan Rellian Greenspyre undersöker de märkliga mossiga tumörer som drabbat Teldrassils timberlings får han ett brådskande meddelande från sin kollega Denalan. Denalan håller till vid Lake Al'Ameths stilla vatten och tror att han äntligen har ringat in orsaken till dessa onaturliga utväxter på skogens naturandar. Rellian inser hur allvarligt läget är och skickar genast dig söderut igen för att hjälpa till."},{t="Hotet vid sjön",b="Denalans forskning vid Lake Al'Ameth är avgörande för att förstå de sjukdomar som sprider sig över det unga världsträdet. Det som började som en undersökning av korrumperat växtliv och sjuka timberlings trappas snabbt upp till en direkt konfrontation med de fördärvade varelser som förgiftar grenarna, med den korrumperade timberlingen Oakenscowl som första mål."}},faq={{q="Vem är Denalan?",a="Denalan är en Night Elf-forskare och naturkännare som håller till vid Lake Al'Ameth i södra Teldrassil. Han ägnar sin tid åt att studera öns växtlighet, märkliga mutationer hos plantor och de onaturliga plågor som sprider sig bland traktens timberlings.",al={"denalan-lore","vem är denalan","denalan lake al'ameth"}},{q="Varför skickar Rellian Greenspyre dig tillbaka till Lake Al'Ameth?",a="Rellian får veta att Denalan har upptäckt den troliga grundorsaken till tumörerna som korrumperar timberlings. Eftersom läget snabbt förvärras och utgör en allt större fara för skogen skickar Rellian dig för att hjälpa till ute i fält omedelbart.",al={"varför gå till denalan","rellian greenspyres uppdrag"}},{q="Vad är det för tumörer som drabbar timberlings?",a="Timberlings är fredliga naturandar som föds ur öns växtlighet, men en utbredd korruption som slår rot i Teldrassil får märkliga mossiga utväxter att växa på dem. Tumörerna gör varelserna fientliga och vansinniga.",al={"timberlingtumörer","varför har timberlings tumörer","mossiga tumörer"}},{q="Var hittar jag Denalan?",a="Denalan har sitt läger vid Lake Al'Ameths stränder, strax söder om Dolanaar i Teldrassils södra skogar.",al={"denalans plats","var är denalan"}},{q="Vad händer när du når Denalan?",a="Denalan välkomnar din hjälp och säger att han har upptäckt något oroande. Han berättar vad du ska göra härnäst när du når hans läger.",al={"what comes next","uppföljning oakenscowl"}},{q="Hur knyter det här ärendet samman Rellian och Denalan?",a="Ärendet knyter samman Rellian Greenspyres forskning om timberlings i Darnassus med Denalans läger vid Lake Al'Ameth. Du för Rellians undersökning av tumörerna vidare till Denalans nya upptäckt om deras orsak.",al={"varför skickar rellian mig till denalan","syftet med return to denalan"}}},fp="17,218,27.357.0,22.221.1,15.214.0,59.238.0,47.214.0,25.109.0,37.128.1,49.198.0"}
P.entries["quest:2499"] = {n="Oakenscowl",s="Denalan ber äventyrare att göra slut på Oakenscowl, en mäktig timberling som förvanskats av en väldig utväxt. Den vansinniga varelsen bor i en grotta längs Lake Al'Ameths södra strand och sprider nu fördärv bland traktens vilda djur.",h="Denalan ber äventyrare att göra slut på Oakenscowl, en mäktig timberling som förvanskats av en väldig utväxt.",kw={"fördärv","denalan","gargantuan tumor","lake al'ameth","mossiga tumörer","oakenscowl","teldrassil","timberling"},ang={["class:Druid"]="Att se en väktare bland timberlings fördärvad av märkliga tumörer påminner druiderna plågsamt om att Teldrassils växande ekosystem är svårt sjukt.",["profession:Herbalism"]="Örtalchemister som hjälper Denalan ser med egna ögon hur växtlighet kan förvridas till elakartat, mossigt fördärv av en osynlig röta.",["race:NightElf"]="Oakenscowls tragiska fall slår mot hjärtat av nattalvernas samhälle och hotar Lake Al'Ameth, strax söder om Dolanaar."},sec={{t="En fallen väktare",b="Oakenscowl var en gång en mäktig ledare bland timberlings, skogsandarna som vårdar Teldrassils frodiga grenar. Tragiskt nog gör fördärvet som sprider sig genom världsträdet ingen åtskillnad mellan enkelt vilt och uråldriga väktare. En väldig tumör som sväller på hans bark har drivit honom till vansinne. Oakenscowl har blivit en källa till fördärv i stället för en vårdare av växtligheten."},{t="Renar Lake Al'Ameth",b="Oakenscowl lurar i en grotta vid Lake Al'Ameths södra strand. Hans giftiga närvaro förgiftar aktivt vattnet och skogens djur i närheten. Denalan kan inte möta besten ensam och vill få den dödad, inte av illvilja utan för att barmhärtigt undanröja fördärvets källa och studera den märkliga, övervuxna tumören som plågar sjöns andar."}},faq={{q="Vad är Oakenscowl?",a="Oakenscowl är en väldig timberling, en skogsande knuten till Teldrassils växtlighet. Han betraktades en gång som en ädel ledare bland de sina, innan han föll offer för en elakartad utväxt.",al={"vem är oakenscowl","oakenscowls bakgrund","vad är oakenscowl för slags varelse"}},{q="Varför måste Oakenscowl dödas?",a="Oakenscowl plågas av en väldig tumör som har förvridit hans sinne och gjort honom våldsamt aggressiv. Hans närvaro i grottan vid Lake Al'Ameth sprider aktivt det märkliga fördärvet till timberlings och djur i närheten.",al={"varför döda oakenscowl","oakenscowl fientlig"}},{q="Var bor Oakenscowl?",a="Oakenscowl bor djupt inne i en grotta vid Lake Al'Ameths södra strand i södra Teldrassil.",al={"oakenscowls plats","var ligger oakenscowls grotta"}},{q="Vem är Denalan och varför studerar han tumören?",a="Denalan är en örtalchemist och naturforskare som bor på Lake Al'Ameths östra strand. Han studerar världsträdets växter och djur och försöker förstå och bota den märkliga röta som angriper traktens timberlings.",al={"vem ger uppdraget om oakenscowl","denalan oakenscowl"}},{q="Vad orsakade tumören på Oakenscowl?",a="Tumören är ett symtom på en djupare, lömsk sjukdom som sprider sig genom Teldrassils jord och rötter och fördärvar naturandar inifrån.",al={"varför har timberlings tumörer","fördärvets källa"}},{q="Går Oakenscowl inte längre att rädda?",a="När äventyrarna möter honom har sjukdomen gått för långt. Tumören har förvridit varelsen fullständigt, så Denalan har inget annat val än att be om att den ska avlivas av barmhärtighet.",al={"kan oakenscowl botas","bota oakenscowl"}}},fx={a853a20e={q="Vad behöver Denalan Gargantuan Tumor till?",a="Denalan behöver Gargantuan Tumor för att studera den onaturliga åkomma som förgiftar Teldrassils timbers. Som naturforskare vid Lake Al'Ameth har han sett hur varelserna faller offer för vansinne och korruption. Oakenscowl hade den största utväxt han någonsin sett, och genom att undersöka ett så extremt exemplar får Denalan sin bästa chans att förstå sjukdomen som plågar traktens djurliv.",al={"varför gargantuan tumor","syftet med gargantuan tumor","användning av gargantuan tumor"}},["47d0c5c8"]={q="Varför behöver Denalan din hjälp mot Oakenscowl?",a="Denalan är en isolerad forskare och ört läkare, inte en krigare som kan slåss mot en enorm, korrumperad timber i dess lya. Han erkände att han inte ens vågade närma sig besten när han spanade på den södra stranden. Eftersom du redan visat vad du går för genom att samla mossiga tumörer och hjälpa till med hans arbete, litar han på att du undanröjer hotet mot hans hem vid sjön.",al={"varför jag, denalan","varför skicka en äventyrare efter oakenscowl","varför kan inte denalan slåss mot oakenscowl"}}},fp="10,186,17.306.0,21.276.0,19.154.0,33.168.0,29.92.0,48.206.0,36.123.0,28.164.0"}
P.entries["quest:25"] = {n="Stonetalon Standstill",s="Stonetalon Standstill är ett uppdrag åt Horde från Mastok Wrilehiss vid Splintertree Post, där du ska säkra den viktiga passagen mot Stonetalon Mountains. Förorenade vattenelementaler i Mystral Lake har stoppat transporterna med förnödenheter. Därför ska Horde rensa ut de fientliga andarna och spana från ett alviskt lusthus med utsikt över närliggande Alliance-rörelser.",h="Stonetalon Standstill är ett uppdrag åt Horde från Mastok Wrilehiss vid Splintertree Post, där du ska säkra...",kw={"förorenad vattenelemental","lusthus","mastok wrilehiss","mystral lake","splintertree post","stonetalon standstill","the talondeep path","tideress"},ang={["class:Shaman"]="Mystral Lakes förvridna vattenelementaler visar att en djup obalans bland elementen håller på att slå rot i Ashenvales uråldriga skogar.",["faction:Horde"]="Splintertree Post kan inte klara sig utan öppna försörjningsleder. Att säkra The Talondeep Path är avgörande för att upprätthålla kommunikation och handel med Stonetalon.",["race:Orc"]="Hordes krigare är beroende av timret och stigarna i Ashenvale för att försörja sina bosättningar. Därför kan störningar i bergens försörjningsleder inte accepteras."},sec={{t="En blockerad försörjningsled",b="För att Horde ska behålla sitt fotfäste i Ashenvale måste timmer, förnödenheter och budbärare ständigt färdas mellan skogen och Stonetalon Mountains toppar. The Talondeep Path är denna viktiga pulsåder och löper förbi Mystral Lakes västra strand. När fientliga elementaler plötsligt väckte vattnet till våldsamt liv upphörde all trafik. Transportkaravaner attackerades av rasande vattenandar, och Mastok Wrilehiss kräver snabba åtgärder innan försörjningslinjerna kollapsar helt."},{t="De förgiftade vattnen",b="Mystral Lake är inte längre en fridfull tillflyktsort i skogen. Elementalerna som driver genom dess djup har blivit förorenade, aggressiva och oberäkneliga. De angriper urskillningslöst alla som försöker färdas längs stigarna runt sjön. För att återställa en viss trygghet måste du rensa ut dessa vattenbestar och bryta den mäktigare anden Tideress herravälde. Men föroreningens ursprung är fortfarande en illavarslande gåta, mitt i den större oron som råder i Ashenvales heliga lundar."},{t="Ögon på andra sidan sjön",b="Horde ser en strategisk möjlighet på Mystral Lakes centrala ö, utöver att kuva sjöns arga andar. På den lilla ön står ett uråldrigt Night Elf-lusthus med fri sikt över sjön mot Silverwind Refuge, en närliggande bosättning för Night Elf. Genom att spana på byggnaden kan Hordes spejare bedöma om ruinerna kan användas som en främre utkikspost. Då kan befälhavarna vid Splintertree hålla noga uppsikt över sina rivaler i Kalimdor utan att bli upptäckta."}},faq={{q="Vad orsakar stoppet nära Stonetalon?",a="Förorenade vattenelementaler i Mystral Lake har blivit våldsamma och attackerar resande längs den närliggande The Talondeep Path. Angreppen har stoppat transporterna med förnödenheter mellan Ashenvale och Stonetalon Mountains.",al={"varför har transporterna stoppats","the talondeep path blockerad","vad stoppade försörjningsleden"}},{q="Vem beordrar att elementalerna ska rensas ut?",a="Mastok Wrilehiss, en ork stationerad vid Splintertree Post i östra Ashenvale, ger order om uppdraget att återställa Hordes handelsleder och undersöka Alliances position.",al={"vem ger uppdraget stonetalon standstill","mastok wrilehiss uppdrag","vem är mastok"}},{q="Varför spana på lusthuset mitt i Mystral Lake?",a="Lusthuset ger utsikt över sjön från en upphöjd plats och vetter direkt mot det närliggande Alliance-lägret. Mastok vill undersöka om det kan användas som en dold utkikspost för att bevaka fiendens rörelser.",al={"varför spana på lusthuset","lusthusets syfte i mystral lake","lusthus som utkikspost"}},{q="Vad är The Talondeep Path?",a="The Talondeep Path är den huvudsakliga bergsstigen från Ashenvales sydvästra delar till Stonetalon Mountains. Den löper precis förbi Mystral Lakes västra strand.",al={"the talondeep paths läge","vägen till stonetalon","stonetalonvägen"}},{q="Varför är vattenelementalerna i Mystral Lake förorenade?",a="Mörka energier och den utbredda oron i Ashenvale har rubbat den naturliga balansen. Det har drivit Mystral Lakes andar till vansinne och gjort deras vanligtvis fridfulla vatten fientliga mot främlingar.",al={"varför är elementalerna förorenade","vattnet i mystral lake förorenat","de förorenade elementalerna ursprung"}},{q="Vilken Alliance-utpost bevakas från lusthuset?",a="Från lusthuset ser man Silverwind Refuge, en Night Elf-bosättning strax norr om sjön. Den vaktas av Sentinels som försvarar Ashenvale mot Hordes timmeravverkning.",al={"vilken alliance-bas ligger nära mystral lake","alliance-utpost i ashenvale"}}},fx={["46f9d708"]={q="Vad slåss du mot vid Mystral Lake?",a="Du skickas för att förgöra de besudlade vattenelementalerna i Mystral Lake, liksom Tideress. Sjöns vatten har vaknat till liv och angriper aggressivt alla som färdas längs vägen i närheten.",al={"mål vid mystral lake","vem skickas du att slåss mot","vad dödar du i stonetalon standstill"}}},fp="21,241,21.352.0,20.329.0,21.306.0,47.204.0,34.135.0,51.221.0,27.148.0,54.146.0,56.171.0"}
P.entries["quest:250"] = {n="A Dark Threat Looms",s="Chief Engineer Hinderweir VII fruktar att Stonewrought Dam står näst på listan över Dark Iron-dvärgarnas mål efter attackerna i Wetlands. Eftersom större delen av dammens försvarsstyrka har omplacerats skickas äventyrare för att undersöka Dark Iron-sabotörer som håller till kring den östra rampen.",h="Chief Engineer Hinderweir VII fruktar att Stonewrought Dam står näst på listan över Dark Iron-dvärgarnas mål...",kw={"dark iron","dun modr","hinderweir","loch modan","sabotörer","stonewrought dam","misstänkt tunna","thandol span"},ang={["faction:Alliance"]="När arméerna vid frontlinjerna är utspridda över kontinenten måste rekryter från Alliance rycka in för att skydda viktiga försörjningsknutpunkter och regional infrastruktur bakom fronten.",["profession:Engineering"]="Ingenjörer kan uppskatta både dammens hisnande skala och den lömska fara som sabotörer utgör när de använder flyktiga kemiska sprängämnen mot bärande fundament.",["race:Dwarf"]="Stonewrought Dam är ett mästerverk av dvärgarnas hantverk och stolthet. Att se den hotas av förrädiska släktingar ur Dark Iron gör undersökningen till en fråga om rikets försvar."},sec={{t="Ett sårbart underverk",b="Stonewrought Dam är ett av Ironforges främsta ingenjörsverk och håller Loch Modans väldiga vattenmassor tillbaka. Men på grund av de pågående konflikterna i Khaz Modan och bortom har mycket av dammens bevakning omplacerats till Alliance Front. Bristen på trupper lämnar Chief Engineer Hinderweir VII och hans lilla besättning nästan försvarslösa mot samordnade angrepp, samtidigt som fiendens aktivitet kryper allt närmare den väldiga anläggningen."},{t="Ekon från norr",b="Hinderweirs oro har sin grund i den senaste tidens förödelse längs den norra gränsen. Dark Iron-dvärgar slog till med dödlig samordning i Wetlands, saboterade den strategiskt viktiga Thandol Span och plundrade fästningsstaden Dun Modr. När Hinderweir ser Dark Iron-sabotörer, som är kända sedan tidigare, smyga nära dammens östra ramp förstår han mönstret: den utbrytargruppen har nu siktet inställt på att rasera nästa livsviktiga förbindelse för The Loch."},{t="Den misstänkta tunnan",b="En spaning längs de nedre vallarna bekräftar ingenjörens värsta farhågor. Bland klipporna där sabotörerna samlades står en obevakad, misstänkt tunna fylld med ett flyktigt pulver som luktar märkligt. Den är ett tydligt bevis på att Dark Iron aktivt förbereder sprängningar för att knäcka Stonewrought Dams grund."}},faq={{q="Varför oroar sig Chief Engineer Hinderweir för dammen?",a="Dark Iron-styrkor ödelade nyligen de norra garnisonerna genom att skada Thandol Span och plundra Dun Modr. När Hinderweir såg Dark Iron-sabotörer smyga längs Stonewrought Dams östra ramp blev han övertygad om att dammen står näst på deras lista.",al={"varför orolig hinderweir","hot mot stonewrought dam","varför attackera dammen"}},{q="Vart tog dammens garnison vägen?",a="Större delen av säkerhetsstyrkorna vid Stonewrought Dam, däribland Hinderweirs främste inspektör, omplacerades för att stödja den bredare Alliance Front. Därför är den viktiga anläggningen glest försvarad.",al={"varför finns inga vakter vid dammen","dammens säkerhetsstyrka","var är soldaterna"}},{q="Vad hittar du vid den östra rampen?",a="Nära den östra rampen där Dark Iron-sabotörerna sågs hittar utredarna en misstänkt tunna fylld med ett pulver som luktar märkligt. Det bekräftar att Dark Iron placerar ut sprängämnen för att sabotera anläggningen.",al={"vad är ledtråden","ledtråd misstänkt tunna","vad gör sabotörerna"}},{q="Vilken strategisk betydelse har Stonewrought Dam?",a="Stonewrought Dam reglerar vattenreservoaren i Loch Modan. Om dammen brister skulle vattenmassorna orsaka enorm förödelse nedströms i Wetlands och samtidigt tömma hjärtat av dvärgarnas territorium på vatten.",al={"varför förstöra dammen","vad händer om dammen brister","dammens bakgrund"}},{q="Vad var attacken mot Dun Modr som Hinderweir nämnde?",a="Dun Modr var en befäst dvärgpost i norra Wetlands, nära Thandol Span. Dark Iron-infiltratörer övermannade staden och slog till mot närliggande Thandol Span, vilket kapade viktiga landvägar för förnödenheter.",al={"attacken mot dun modr","vad hände vid dun modr","förstörelsen av thandol span"}},{q="Vilka Dark Iron-dvärgar siktar in sig på Loch Modan?",a="Dark Iron-klanen har länge varit bittra rivaler till Bronzebeard-dvärgarna, ända sedan War of the Three Hammers. Från Blackrock Mountain och Searing Gorge saboterar de ofta Bronzebeards infrastruktur och gränsförsvar.",al={"vilka är dark iron","dark iron-sabotörernas motiv","varför hatar dark iron ironforge"}}},fx={f99be494={q="Varför finns Dark Iron-sabotörer vid Stonewrought Dam?",a="Efter sina attacker mot Thandol Span och staden Dun Modr i norr har Dark Iron-dvärgar smugit söderut in i Loch Modan. Chief Engineer Hinderweir upptäckte deras sabotörer när de smög omkring vid Stonewrought Dams östra ramp och misstänker att de tänker sabotera den väldiga dammen härnäst.",al={"dark iron-sabotörer vid dammen","varför är dark irons vid dammen","dark iron-sabotörer i loch modan"}}},fp="19,188,19.259.0,21.221.0,19.194.1,55.196.0,32.161.0,37.160.1,59.148.0,56.196.0,51.230.0"}
P.entries["quest:251"] = {n="Translate Abercrombie's Note",s="Översätt Abercrombies anteckning är ett Alliance-uppdrag i Darkshire där en äventyrare ska bära ett oläsligt brev till stadens lärde. Lord Ello Ebonlocke kan inte tyda eremitens meddelande och förlitar sig i stället på Sirra Von'Indis kunskap om ovanliga skriftspråk. Uppdraget markerar ögonblicket då Darkshires ledare börjar granska eremitens märkliga brev närmare.",h="Översätt Abercrombies anteckning är ett Alliance-uppdrag i Darkshire där en äventyrare ska bära ett oläsligt...",kw={"abercrombie","kod","darkshire","duskwood","ello ebonlocke","eremit","sirra von'indi","översättning"},ang={["class:Mage"]="Magiker som är bekanta med ovanliga dialekter och magiska avskrifter kommer att uppskatta Sirra Von'Indis roll som Darkshires lokale expert på esoteriska skriftspråk.",["faction:Alliance"]="För Alliance-hjältar som hjälper Duskwood visar detta ärende hur sårbart och isolerat Darkshires styre känner sig mitt i det omgivande mörkret."},sec={{t="Ett obegripligt meddelande",b="När Abercrombie skickar ett förseglat brev till borgmästare Ello Ebonlocke väntar sig stadens ledare en egensinnig vädjan eller bittra ramsor från eremiten vid kyrkogården. I stället är pergamentet täckt av märkliga, kryptiska tecken som inte liknar vanlig Common-skrift. Borgmästare Ebonlocke saknar lärdom nog att tyda uråldriga eller esoteriska språk, men avfärdar inte brevet utan vidare. Även galna eremiter kan utgöra en fara i Duskwood."},{t="Darkshires lärde",b="För att knäcka koden hänvisar Ebonlocke resenärerna över torget till Sirra Von'Indi. Sirra är Darkshires lärde inom esoterisk kunskap och är väl bevandrad i forntida konster och bortglömda tungomål. Sirra hånar visserligen Abercrombies förstånd och skämtar om att den som bor intill en hemsökt kyrkogård måste ha ruttnat i huvudet, men tar pergamentet på tillräckligt stort allvar för att påbörja det mödosamma arbetet med att skriva av det."},{t="En glimt av eremitens sinne",b="När brevet lämnas över sätts en dyster uppenbarelse för staden i rörelse. Abercrombie har tidigare verkat vara en skröplig, tillbakadragen gammal man som ber om förnödenheter och skydd mot gastar. Hans kodade brev till borgmästaren tyder däremot på en långt mörkare intelligens och en annalkande uppgörelse som Darkshire är illa rustat att möta."}},faq={{q="Varför kan inte borgmästare Ebonlocke läsa anteckningen själv?",a="Brevet från Abercrombie är skrivet med ett ovanligt skriftspråk eller i en uråldrig kod. Borgmästare Ello Ebonlocke är administratör och adelsman, inte språkvetare, så han skickar det till Sirra Von'Indi, Darkshires lokale expert på forntida konster och mystiska tungomål.",al={"varför kan ello inte läsa anteckningen","översätta ebonlockes brev","varför behövs en översättare"}},{q="Vem är Sirra Von'Indi?",a="Sirra Von'Indi är en lärd invånare i Darkshire. Han är känd för sin expertis inom ovanliga språk, historia och forntida konster och är stadens självklara lärde när mystiska texter eller reliker dyker upp i de mörka skogarna.",al={"vem är sirra von indi","vem är översättaren","darkshires lärde"}},{q="Var bor Abercrombie?",a="Abercrombie bor i en fallfärdig koja strax nordost om Raven Hill Cemetery i västra Duskwood, omgiven av rastlösa odöda och rovdjur.",al={"var finns abercrombie","eremitens plats","abercrombie duskwood"}},{q="Hur reagerar Sirra på Abercrombies anteckning?",a="Sirra tvivlar öppet på Abercrombies förstånd och säger att den som vill bo intill en kyrkogård måste ha ruttnat i huvudet. Trots det går han med på att undersöka brevet och börjar översätta dess esoteriska skrift.",al={"vad tycker sirra om abercrombie","sirra von indis dialog"}},{q="Vad händer efter att man gett anteckningen till Sirra?",a="Sirra Von'Indi ber äventyraren vänta medan han arbetar med avskriften. När han är klar måste det översatta brevet bäras tillbaka till Lord Ello Ebonlocke.",al={"nästa uppdrag efter översätt anteckningen","vad händer efter översätt abercrombies anteckning"}},{q="Varför skrev Abercrombie till borgmästare Ebonlocke?",a="Abercrombies anteckning till borgmästaren är skriven med ett skriftspråk som Ello inte kan läsa. Vad eremiten faktiskt skrev blir känt först när Sirra Von'Indi har översatt det.",al={"varför skickade abercrombie ett brev","eremitens anteckning syfte"}}},fp="28,178,25.367.0,24.337.0,32.207.1,48.143.0,22.179.0,28.142.0,47.176.0,44.137.1,45.119.1"}
P.entries["quest:2518"] = {n="Tears of the Moon",s="Tears of the Moon är ett högtidligt uppdrag från Priestess A'moora i Temple of the Moon. Lady Sathrah, den stora spindeln som en gång var älskad av gudinnan Elune, har blivit vansinnig. Nu söker The Sisterhood of Elune ett nådigt slut för henne och vill återfå hennes heliga spinnorgan.",h="Tears of the Moon är ett högtidligt uppdrag från Priestess A'moora i Temple of the Moon.",kw={"darnassus","elune","lady sathrah","priestess a'moora","silvery spinnerets","tears of the moon","teldrassil","temple of the moon","wellspring lake"},ang={["class:Druid"]="Druider ser Sathrahs plötsliga vildhet och plåga som ännu ett oroande tecken på Teldrassils obalans. Att återställa hennes ande är därför en ekologisk nödvändighet.",["class:Priest"]="Prästerna i The Sisterhood of Elune vet att barmhärtighet ibland kräver ett sorgset hugg. Det fullbordas med en rituell offergåva som återför en fördärvad själ till Gudinnans famn.",["race:NightElf"]="För kaldorei är det smärtsamt att tvingas döda Sathrah. Det påminner dem om att fördärvet i Teldrassils vildmark inte skonar vare sig det enkla djuret eller Elunes heliga följeslagare."},sec={{t="En älskad varelses fall",b="I den fridfulla Temple of the Moon i Darnassus sörjer Priestess A'moora Lady Sathrahs tragiska öde. Förr hyllades Sathrah som en välsignad varelse av Elune. Hon vävde fina silvertrådar under natthimlen och fångade kvällsdimman som lade sig över Teldrassils grenar. Den skimrande dagg som samlades i hennes nät hade mirakulösa läkande egenskaper. The Sisterhood of Elune samlade och bevarade den omsorgsfullt för sina heliga riter."},{t="Nåd för Sathrah",b="Liksom många av varelserna på det unga världsträdet har Lady Sathrah nyligen fallit offer för en överväldigande galenskap. Hennes förvridning hotar både resande och hennes egna okläckta kullar i norr, nära Wellspring Lake. Eftersom de inte kan rena henne medan hon strövar omkring våldsam och ursinnig, har The Sisterhood beslutat att det enda barmhärtiga valet är att göra slut på hennes lidande. Prästinnorna tänker hämta hennes silverglänsande spinnorgan och viga hennes kvarlevor åt Elunes altare. De ber Mångudinnan skänka henne frid och en ren återfödelse."}},faq={{q="Vem är Lady Sathrah?",a="Lady Sathrah är en ståtlig, uråldrig spindel från Teldrassil. Hon vördas traditionellt som älskad av Elune och var känd för att väva silverglänsande nät som fångade nattdimma med starkt läkande kraft.",al={"lady sathrah bakgrund","vem är lady sathrah","sathrahs bakgrund","sathrah spindel"}},{q="Varför måste Lady Sathrah dödas?",a="Hon dukade under för en smygande galenskap som har smittat Teldrassils vilda djur. När hon blev våldsamt oberäknelig och ett hot mot både sin avkomma och andra, beslöt prästinnorna att det var barmhärtigast att döda henne.",al={"varför döda sathrah","kan sathrah räddas","varför är sathrah aggressiv"}},{q="Var hittar man Lady Sathrah?",a="Lady Sathrah har sitt näste i Teldrassils norra vildmark, nära Wellspring Lakes stränder.",al={"lady sathrahs plats","var finns sathrah","hitta sathrah"}},{q="Vad användes Lady Sathrahs nät till?",a="Hennes nät fångade kvällsdimman och bildade en kraftfull, silverglänsande dagg med välkända läkande krafter. The Sisterhood of Elune förvarade den i Temple of the Moon.",al={"tears of the moon betydelse","sathrahs nät användning","silverglänsande dagg bakgrund"}},{q="Vem ger uppdraget Tears of the Moon?",a="Priestess A'moora, en tjänare i Temple of the Moon i Darnassus, ger uppdraget till betrodda äventyrare från Alliansen.",al={"vem ger tears of the moon","uppdragsgivare för tears of the moon","priestess amoora"}},{q="Vad gör prästinnorna med Sathrahs spinnorgan?",a="De frambär dem till Elune vid templets altare som en vigning. De ber gudinnan ta emot Sathrahs ande, välsigna henne och låta henne återfödas i fridfull harmoni.",al={"vad händer med spinnorganen","spinnorganens syfte","offer till elune"}}},fp="17,220,25.355.0,17.507.1,20.161.0,40.175.0,28.81.0,39.144.0,38.115.0,55.174.0"}
P.entries["quest:2519"] = {n="The Temple of the Moon",s="Temple of the Moon är ett introduktionsuppdrag i Darnassus där Sister Aquinne ber äventyrare söka upp Priestess A'moora. The Sisterhood of Elune behöver hjälp med en urgammal varelse som lider bland Teldrassils grenar. Det inleder en högtidlig barmhärtighetsritual.",h="Temple of the Moon är ett introduktionsuppdrag i Darnassus där Sister Aquinne ber äventyrare söka upp...",kw={"darnassus","elune","priestess a'moora","sathrah","sister aquinne","the sisterhood of elune","the temple gardens","temple of the moon"},ang={["class:Druid"]="Druider bekymrar sig djupt över varje stor varelse i vildmarken som är i nöd. Därför är kallelsen från Temple Gardens en brådskande fråga om naturens harmoni.",["class:Priest"]="Präster som rör sig på Darnassus marker dras naturligt till The Sisterhoods arbete och hjälper sina medtjänare i det gudomliga med läkandets och barmhärtighetens riter.",["race:NightElf"]="För nattalver är svaret på Sister Aquinnes vädjan en del av plikten att skydda Teldrassils heliga ekosystem och följa Elunes prästerskaps vägledning."},sec={{t="En vädjan i trädgårdarna",b="När resenärer vandrar bland vattnen och de skuggiga dungarna i The Temple Gardens möter de Sister Aquinne, en hängiven tjänare åt Elune. Hon anar att de är kapabla och ber dem om hjälp för sin orden. En vördnadsvärd skogsvarelse lider, och systrarna kan inte hantera saken på egen hand."},{t="Till måntemplet",b="Sister Aquinne hänvisar aspiranterna till det storslagna Temple of the Moon, strax åt sydost. Där samordnar Priestess A'moora ritualerna och det praktiska arbete som krävs för att ta hand om Teldrassils plågade djurliv. Hon förbereder sympatiska bundsförvanter på en sorglig barmhärtighetsgärning."}},faq={{q="Vem inleder uppdraget Temple of the Moon?",a="Sister Aquinne inleder uppdraget. Du hittar henne utomhus i området Temple Gardens i Darnassus.",al={"uppdragsgivare till temple of the moon","var får man uppdraget temple of the moon","vem ger temple of the moon"}},{q="Var finns Priestess A'moora?",a="Priestess A'moora finns inne i det storslagna Temple of the Moon, strax sydost om Temple Gardens i Darnassus.",al={"var finns priestess amoora","hitta amoora","priestess a'mooras plats"}},{q="Vilken varelse behöver hjälp?",a="Det gäller Sathrah, en vördad spindel från Teldrassil vars öde leder till en barmhärtighetsritual under prästerskapets ledning.",al={"vilken varelse behöver hjälp","vem är skogsvarelsen","vad handlar uppdragskedjan om"}},{q="Måste man göra det här uppdraget för att fortsätta kedjan?",a="Nej. Temple of the Moon är ett valfritt vägvisaruppdrag. Du kan prata direkt med Priestess A'moora inne i templet och utföra ritualuppgifterna utan att först besöka Sister Aquinne.",al={"måste man göra temple of the moon","kan jag hoppa över temple of the moon","vägvisaruppdraget temple of the moon"}},{q="Vilket uppdrag följer efter det här?",a="Priestess A'moora erbjuder uppdraget Tears of the Moon. Hon ber dig göra slut på Lady Sathrahs lidande och hämta hennes silvriga spinntrådar.",al={"nästa uppdrag efter temple of the moon","fortsättningsuppdrag till temple of the moon","what comes next"}},{q="Varför ber The Sisterhood of Elune utomstående om hjälp?",a="Förödelsen som dröjer sig kvar i Teldrassils växt- och djurliv tänjer på The Sisterhoods krafter. Därför tvingas prästinnorna rekrytera dugliga resenärer som respekterar naturen och gudinnan.",al={"varför be utomstående om hjälp","varför behöver prästerskapet hjälp","sister aquinnes motiv"}}},fx={e3d31678={q="Varför skickar Sister Aquinne dig till Priestess A'moora?",a="Sister Aquinne förstår att en vördnadsvärd varelse i Teldrassils skogar lider och är i desperat behov av hjälp, men saken kräver prästinnornas vägledning. Eftersom en känslig och svår uppgift väntar hänvisar hon dugliga resenärer till Priestess A'moora i Temple of the Moon, där de får ordentliga instruktioner om hur de ska ingripa.",al={"varför sister aquinne vill detta","varför skicka till temple of the moon","sister aquinnes syfte"}}},fp="22,183,21.193.0,20.230.0,44.99.0,35.102.0,37.122.0,46.184.0,34.127.0,57.158.0"}
P.entries["quest:252"] = {n="Translation to Ello",s="Translation to Ello är ett avgörande uppdrag i Abercrombies berättelse i Duskwood. Efter att ha bett Sirra Von'Indi tyda eremitens gåtfulla skrifter får äventyraren i uppdrag att överlämna det översatta pergamentet direkt till Lord Ello Ebonlocke i Darkshire.",h="Translation to Ello är ett avgörande uppdrag i Abercrombies berättelse i Duskwood.",kw={"abercrombie","darkshire","ello ebonlocke","raven hill","sirra von'indi","translation to ello"},ang={["faction:Alliance"]="För Alliansens förkämpar blir detta en smärtsam läxa om Duskwoods förräderi: felplacerad tillit till skogen kan utsätta en hel bosättning av oskyldiga invånare för fara."},sec={{t="En sen insikt",b="I flera dagar lät den åldrade eremiten Abercrombie resenärer springa ärenden åt honom runt om i Duskwood, under förevändning att han knappt orkade överleva. Han bad om tråd, konserverade reagenser och personliga tillhörigheter. Först när Sirra Von'Indi till slut tyder hans privata pergament kommer sanningen fram: den vänlige gamle mannen är en galen balsamerare, och delarna som samlats in användes för att skapa ett fasansfullt hämndvapen riktat rakt mot Darkshire."},{t="Vägen till Darkshire",b="När Lord Ello Ebonlocke får det översatta brevet förlorar borgmästaren all färg i ansiktet. Oavsett vilka ädla motiv som fick en äventyrare att hjälpa till, gjorde de sista leveranserna att Abercrombie kunde färdigställa sitt monstruösa verk, Stitches. När brevet överlämnas börjar vidundret marschera rakt österut längs vägen från Raven Hill Cemetery och slaktar alla patruller från Night Watch som står i dess väg."}},faq={{q="Vad står det i det översatta brevet?",a="Sirra fruktar att Abercrombie har gjort något outsägligt. Det översatta brevet måste snarast föras till Lord Ello Ebonlocke, som kan bedöma faran för Darkshire.",al={"vad står det i brevet","abercrombies brevtext","vad översattes"}},{q="Vem är Sirra Von'Indi?",a="Sirra Von'Indi är en lärd person som bor i Darkshire. Hans språkliga och analytiska kunnande låter honom tyda de gåtfulla anteckningar och brev som Abercrombie lämnat efter sig, när andra inte kan läsa hans skrift.",al={"vem är sirra","sirra von indi bakgrund"}},{q="Varför klandrar Lord Ello spelaren?",a="Lord Ellos reaktion avslöjas när han läser det översatta brevet. Undersökningen går ut på att du ska föra honom varningen så snabbt som möjligt.",al={"varför är ello arg","orsakade jag stitches","ellos reaktion"}},{q="Vad händer direkt efter att uppdraget slutförts?",a="Överlämna det översatta brevet till Lord Ello Ebonlocke i Darkshire. Hans reaktion och faran som brevet varnar för avslöjas när han läser det.",al={"vad utlöser stitches","dyker stitches upp","stitches-händelsen"}},{q="Vart tar Stitches vägen efter detta?",a="Stitches förknippas med vägen mellan Raven Hill Cemetery och Darkshire. Hans roll i Abercrombies plan avslöjas under undersökningen.",al={"stitches väg","vart marscherar stitches"}},{q="Vilket uppdrag kommer härnäst?",a="Efter att brevet har överlämnats skickar Lord Ello äventyrare vidare på uppdraget 'Bride of the Embalmer'.",al={"nästa uppdrag","efter translation to ello"}}},fx={["203575b3"]={q="Varför vill Sirra Von'Indi att brevet levereras till Ello?",a="När Sirra dechiffrerade brevet insåg han att Abercrombie har gjort något outsägligt och släppt lös en monstruös undergång som redan lufsar mot Darkshire. Han skickar dig för att genast varna Lord Ello Ebonlocke, så att stadens ledning kan förbereda sig på katastrofen innan den når portarna.",al={"varför skicka brev till ello","sirra von'indis motiv","varför leverera den översatta lappen"}},["4e225af8"]={q="Varför skickar Sirra dig för att varna Lord Ello i stället för att gå själv?",a="Det var du som ursprungligen fick i uppdrag av Lord Ello att dechiffrera Abercrombies misstänkta skrifter, och det var du som först bar det märkliga brevet till Sirra. Ett monstruöst hot är redan på väg och varje sekund räknas, så det snabbaste sättet att få varningen till borgmästaren är att skicka den kapabla äventyraren som står framför honom.",al={"varför jag för translation to ello","varför går inte sirra till ello","varför skicka spelaren till ello"}}},fp="19,263,21.435.1,21.418.1,41.169.2,22.206.0,36.145.2,53.137.2,34.149.2,22.110.1"}
P.entries["quest:2520"] = {n="Sathrah's Sacrifice",s="Sathrah's Sacrifice avslutar en dyster ritual i Temple of the Moon i Darnassus. Med Lady Sathrahs kvarlevor anförtrodda åt sig offrar spelarna den fallna varelsens spinnkörtlar i Elunes heliga vatten för att rena hennes själ från fördärv och låta hennes ande vila.",h="Sathrah's Sacrifice avslutar en dyster ritual i Temple of the Moon i Darnassus.",kw={"a'moora","darnassus","elune","fontän","lady sathrah","rening","sathrah","spinnkörtlar","teldrassil","temple of the moon"},ang={["class:Druid"]="Druider som sörjer sjukdomen som plågar Teldrassil finner tröst i vetskapen om att fallna djur kan återföras till naturens kretslopp genom rening.",["class:Priest"]="Präster som vandrar i Temple of the Moon ser med egna ögon hur Elunes heliga ljus och vatten kan hela andar som slitits sönder av galenskap och fördärv.",["race:NightElf"]="För nattalverna speglar riten deras högtidliga plikt gentemot Kalimdors växt- och djurliv: även när varelser måste dödas hedras och renas deras andar genom Elunes nåd."},sec={{t="Renande heliga vatten",b="Efter den tragiska dödandet av Lady Sathrah ger Priestess A'moora de invigda en sista andlig plikt. Den väldiga spindeln hade fallit offer för den mörka galenskap som sprider sig över Teldrassil och förvandlat hennes en gång fridfulla natur till tanklös aggression. Prästerskapet i Elune ser inte hennes död som en enkel avlivning, utan söker frälsa hennes fallna väsen. När hennes silverglänsande spinnkörtlar läggs i den centrala fontänen i Temple of the Moon sköljer det invigda vattnet bort fördärvet och befriar henne."},{t="Sathrahs förnyelse",b="Offret till Elune skapar omedelbart en andlig gemenskap. När spinnkörtlarna nuddar den månupplysta dammen stiger Lady Sathrahs eteriska gestalt upp ur djupet, fridfull och renad från plågan som drev henne till vansinne. The Sisterhood of Elune ser ritualen som en nödvändig frälsning. Även om förlusten av den väldiga varelsen känns djupt, lär nattalvernas teologi att hon en dag kan återfödas med en ofördärvad ande genom denna heliga rening."}},faq={{q="Vem var Lady Sathrah?",a="Lady Sathrah var en väldig spindel som levde på Teldrassil och dukade under för det krypande fördärv som drabbade världsträdets djurliv. Fördärvet drev henne till vansinne, och hon måste dödas så att hennes kvarlevor kunde helgas.",al={"lady sathrah","vem är sathrah","vad är sathrah"}},{q="Var offras det?",a="Offret läggs i den heliga fontänen mitt i Temple of the Moon, The Sisterhood of Elunes centrala helgedom i Darnassus.",al={"var lägger jag offret","fontänens plats","tempelfontänen"}},{q="Vad händer när du lägger spinnkörtlarna i fontänen?",a="När de silverglänsande spinnkörtlarna läggs i det välsignade vattnet visar sig Sathrahs renade ande en kort stund i dammen. Hon går fritt och fridfullt som ett tecken på att Elune har tagit emot offret.",al={"vad händer vid fontänen","sathrahs ande i fontänen"}},{q="Varför måste Lady Sathrah dö?",a="Förgiftningen av hennes sinne hade gått för långt för att kunna botas medan hon levde. Priestess A'moora och The Sisterhood trodde att det enda sättet att rädda hennes själ var att göra slut på hennes lidande och rena hennes kvarlevor i Elunes heliga vatten.",al={"varför döda sathrah","kunde sathrah räddas","sathrahs galenskap"}},{q="Vem ger uppdraget Sathrah's Sacrifice?",a="Uppdraget ges och avslutas av Priestess A'moora, som tjänar i Temple of the Moon i Darnassus med utsikt över den centrala salen.",al={"uppdragsgivare","var lämnar jag in uppdraget","amoora plats"}},{q="Vilken tro ligger till grund för nattalvernas ritual?",a="Nattalverna tror att själar som renats av Moder Måne kan återfödas i naturen med renade och förnyade andar, fria från fördärvets kvardröjande fläck.",al={"nattalvers återfödelse","elunes rening","berättelser om återfödelse"}}},fx={f4be164d={q="Varför vill Priestess A'moora att det här ska göras?",a="Priestess A'moora vill låta Lady Sathrah få vila i frid och rena bort korruptionen som plågade den en gång ädla varelsen. När Sathrahs spinnvårtor placeras i Temple of the Moons heliga vatten kan Elunes nåd rena den kvarvarande orenhet som drev den stora spindeln till vansinne. Då kan hennes ande återlösas och så småningom återfödas på nytt.",al={"amooras motiv","varför utföra offret","varför vill amoora ha sathrahs offer"}}},fp="19,217,28.471.0,22.346.1,21.217.0,31.143.0,59.177.1,33.225.0,40.132.0,54.137.0"}
P.entries["quest:253"] = {n="Bride of the Embalmer",s="\"Bride of the Embalmer\" är ett farligt uppdrag från Lord Ello Ebonlocke i Darkshire. Efter att ha pusslat ihop den oroande sanningen om den legendariske Embalmer skickar stadens ledning dig till Duskwoods hemsökta kyrkogårdar för att finna hans återuppväckta hustrus grav. Genom att slita alkemistens levande hjärta ur Elizas förbannade kvarlevor hoppas du beröva honom hans oheliga kraft.",h="\"Bride of the Embalmer\" är ett farligt uppdrag från Lord Ello Ebonlocke i Darkshire.",kw={"alkemist","bride of the embalmer","darkshire","duskwood","eliza","ello ebonlocke","embalmer's heart","grav","embalmer"},ang={["class:Paladin"]="Paladiner ser Elizas hemska återupplivning som en skymf mot Ljuset och naturens lagar. De renar gärna det människoätande odjuret och kapar nekromantikerns hädiska livlina.",["class:Priest"]="Präster ser tragedin bakom den sörjande änkling som fallit för mörka konster, men vet att Elizas kött hungrande hån mot livet måste få en slutgiltig, helig vila.",["faction:Alliance"]="Med Night Watch hårt ansatt i kampen mot Duskwoods vilda fasor måste en Alliance-mästare rycka in och försvara Darkshire mot denna uråldriga, krypande galenskap."},sec={{t="En godnattsaga blir verklighet",b="I åratal berättade föräldrar i Duskwood sagan om Embalmer för sina skrämda barn. Enligt folksagan var han en gång en vänlig alkemist vars sinne krossades när hans älskade hustru Eliza dog en tragisk död. I sin desperation att överlista döden tog han till mörk trolldom och utförde det yttersta offret: han skar ut sitt eget bultande hjärta och placerade det i sin hustrus bröst. Lord Ello Ebonlocke avfärdade länge detta som ren byfolklore, men nya avslöjanden har visat att Embalmer vandrar bland dem och att hans hemska verk ruttnar under kyrkogårdens jord."},{t="Den återuppväckta bruden",b="Ritualen lyckades återge Eliza liv, men mörk nekromanti kräver alltid ett fruktansvärt pris. Återupplivad av den stulna livsgnistan förvandlades Eliza till ett glupskt vidunder, förbannat med en omättlig hunger efter levande människokött. Förskräckt och ovillig att förgöra sin skapelse tvingades Embalmer gömma undan sin brud i en enslig grav. Han besökte henne i hemlighet medan han smidde planer på fler illdåd. För att oskadliggöra nekromantikern skickar Lord Ebonlocke modiga själar att gräva upp Eliza, fälla det köttätande odjuret och återta det alltjämt bultande organ som upprätthåller hans mörka konst."},{t="Darkshires skydd",b="När du sliter det bultande hjärtat ur Elizas förruttnade bröst och bär det tillbaka till Darkshire drar Lord Ebonlocke en lättnadens suck. Stadens borgmästare tänker inte bara förstöra det, utan vända alkemistens mörka konst mot honom. Han tror att den uråldriga magi som dröjer kvar i hjärtat kan bli en skyddsamulett över Darkshire och värna den hårt prövade staden mot den försvagade Embalmers vrede, ifall han fortfarande kan framkalla den som hämnd."}},faq={{q="Vem är Embalmer?",a="Embalmer var från början en alkemist i Duskwood som blev galen efter att hans hustru Eliza dog. Han tog till nekromantisk konst, skar ut sitt eget levande hjärta och lade det i Elizas lik för att återuppväcka henne. Då förvandlades han själv till ett svårfångat monster.",al={"embalmers bakgrund","vem är embalmer","embalmers historia"}},{q="Varför begravdes Eliza om hon återupplivades?",a="Alkemisten lyckades återuppliva Eliza med hjälp av sitt eget hjärta, men den mörka magin förbannade henne med en omättlig hunger efter levande människokött. Eftersom han varken kunde hålla henne trygg bland folk eller stilla hennes vilda aptit, tvingades han hålla henne begravd på en kyrkogård.",al={"varför är eliza begravd","elizas grav","varför hålla eliza i en grav"}},{q="Varför vill Lord Ebonlocke ha Embalmer's Heart?",a="Enligt berättelsen som Ello återger är hjärtat källan till Embalmers kraft. Han ber dig hämta det från Elizas grav medan det ännu bultar, eftersom han tror att det kommer att bryta den kraften.",al={"varför hämta hjärtat","vad embalmers hjärta gör"}},{q="Var börjar den här uppdragskedjan?",a="Uppdraget följer direkt på \"Translation to Ello\", där gamla brev och efterforskningar lämnas till Lord Ello Ebonlocke och bevisar att Embalmer, som förekommer i lokala godnattsagor, är verklig och farlig.",al={"förutsättning för uppdraget","hur får man bride of the embalmer","förberedande uppdrag till embalmer"}},{q="Besegrar hjärtat Embalmer för gott?",a="Ello tror att hjärtat kommer att bryta Embalmers kraft. Resultatet av uppdraget avslöjas när du återvänder till Darkshire.",al={"är embalmer död","dödar detta embalmer"}},{q="Vem ger uppdraget?",a="Lord Ello Ebonlocke, Darkshires borgmästare och ledare, ger dig uppdraget i Darkshire Town Hall efter att ha fått veta den kusliga sanningen bakom stadens folklore.",al={"uppdragsgivare","vem startar bride of the embalmer"}}},fx={a9aedc81={q="Varför vill Lord Ello Ebonlocke att Elizas grav ska störas?",a="Lord Ello Ebonlocke vill bryta Embalmers makt innan den galne alkemisten drar olycka över Darkshire. Embalmer lade sin egen mörka magi och sitt hjärta på att återuppliva sin avlidna hustru Eliza. Genom att hämta hjärtat medan det fortfarande slår tänker Ebonlocke försvaga vidundrets övernaturliga kraft och använda den kvarvarande skyddsmagin som en sköld för staden.",al={"varför vill ello att det görs","ebonlockes motiv för bride of the embalmer","varför hitta elizas grav"}},b836fb1b={q="Vem är Eliza, och varför ligger hon begravd i Raven Hill?",a="Eliza är Embalmers återupplivade brud och vilar i en försummad grav på Raven Hills kyrkogård. Hennes make, som drevs till vansinne av sorg, placerade sitt eget hjärta i hennes lik för att väcka henne till liv. Ritualen lyckades, men förbannade henne med en omättlig hunger efter levande människokött. Han tvingades därför hålla henne instängd i graven tills han kunde hitta ett sätt att försörja henne.",al={"vem är eliza","mål för bride of the embalmer","varför är eliza begravd"}}},fp="21,202,26.438.0,21.471.1,17.386.2,20.206.0,53.202.0,50.175.0,34.190.0,58.120.1,21.152.0"}
P.entries["quest:254"] = {n="Digging Through the Dirt",s="Digging Through the Dirt markerar den kusliga höjdpunkten i jakten på Embalmerns försvunna hjärta i Duskwood. Djupt inne i den rovlystna tystnaden på Raven Hill Cemetery döljer en omrörd jordhög en begravd fasa som vägrar förbli död.",h="Digging Through the Dirt markerar den kusliga höjdpunkten i jakten på Embalmerns försvunna hjärta i Duskwood.",kw={"abercrombie","embalmers brud","kista","gräva genom jorden","duskwood","eliza","elizas gravjord","embalmers hjärta","raven hill cemetery"},ang={["class:Paladin"]="Att störa färska gravar strider mot den Heliga Ljusets alla begravningsriter, men att släppa ut och förgöra djävulskapet som fångats därinne är en nödvändig reningshandling.",["class:Priest"]="Ljudet av klor som krafsar och tänder som gnisslar under vigd jord är en skymf mot den fridfulla vila som Ljuset lovat de döda i Duskwood.",["faction:Alliance"]="Night Watch kämpar ständigt mot skräcken som väller ut från Raven Hill. Att hitta de begravda fasor som Embalmer gömt är avgörande för Darkshires säkerhet."},sec={{t="En störd grav",b="Bland de oräkneliga väderbitna gravstenarna på Raven Hill Cemetery ligger en fläck nyligen uppgrävd, löst packad jord märkt med namnet Eliza. Många gravar i Duskwood har skändats av asätare eller förvildade gastkramare, men den här jorden har lagts med avsikt. När du gräver genom matjorden blottas det splittrade träet i en begravd kista, som förseglar kvarlevorna som Embalmer ville gömma undan dagsljuset."},{t="Krafsandet därinne",b="Under det splittrade träet vilar inget lik. Mot locket kan du känna frenetiska vibrationer – långa, klösta fingrars febrila krafsande och det ihåliga klapprandet från ruttnande käkar. Abercrombies makabra experiment, Eliza, rör sig våldsamt i sitt fängelse av furu. Embalmers försvunna hjärta slår i hennes bröst medan hon väntar på oförsiktiga händer som ska öppna graven."}},faq={{q="Vad är begravt i Elizas grav?",a="Begravd under jorden finns en kista som innehåller Eliza, ett odött vidunder skapat av Embalmer. Hon har förseglats under jord med Embalmers eget hjärta placerat i bröstet.",al={"vad finns i graven","vem är eliza","innehållet i elizas grav"}},{q="Var ligger graven?",a="Elizas grav ligger på Raven Hill Cemetery i västra Duskwood, bland de många hemsökta kryptorna och kringströvande odöda.",al={"var ligger elizas grav","elizas gravplats","var finns gravjorden"}},{q="Varför måste du gräva dig ner i kistan?",a="Du måste gräva i graven för att möta Eliza och återta Embalmers hjärta, så att utredningen av Embalmers förvridna planer kan slutföras.",al={"varför gräva i graven","syftet med grävandet","varför öppna kistan"}},{q="Vad händer när kistan öppnas?",a="När kistan öppnas släpps Eliza ut ur sitt grunda fängelse, och du tvingas förgöra den klösande, glupska gastkramaren för att hämta hjärtat som låsts in med henne.",al={"vad händer sedan","öppnad kista","öppna elizas kista"}},{q="Vem lade Eliza i graven?",a="Embalmer lade henne där och dolde sin fasansfulla skapelse på Raven Hills vidsträckta begravningsplats, tillsammans med sitt älskade hjärta.",al={"vem begravde eliza","vem lade henne där"}},{q="Är Eliza en vanlig gastkrämare?",a="Eliza är Embalmers egen avlidna hustru, återupplivad med hans mörka magi och med hans hjärta placerat i sitt bröst. Hon är mycket starkare och mer målmedveten än de viljelösa gastkramarna som strövar längs Duskwoods vägar.",al={"vilket slags monster är eliza","är eliza en gastkrämare"}}},fp="24,149,17.335.0,21.319.1,32.118.1,28.105.0,39.112.1,39.124.1,28.104.1,27.175.1"}
P.entries["quest:2541"] = {n="The Sleeping Druid",s="Djupt inne i Ban'ethil Barrow Den står nattalven Oben Rageclaw inför en svår magisk kris. Fientliga Gnarlpine-furbolgschamaner har skilt hans drömmande själ från hans kropp och med mörka förtrollningar väckt hans kött till liv som en våldsam väktare.",h="Djupt inne i Ban'ethil Barrow Den står nattalven Oben Rageclaw inför en svår magisk kris.",kw={"ban'ethil barrow den","gravkammare","emerald dream","gnarlpine","oben rageclaw","shaman voodoo charm","teldrassil","den sovande druiden"},ang={["class:Druid"]="För druider är Obens situation en vaken mardröm. Att få sin kropp kapad medan man förenas med Emerald Dream kränker själva grunden för druidernas slummer.",["race:NightElf"]="Skändningen av Ban'ethil Barrow Den visar hur långt Gnarlpine-furbolgerna har fallit från sin forntida samhörighet med Kaldorei."},sec={{t="En störd slummer",b="Nattalvdruider går in i gravkamrar över hela Kalimdor för att förenas med naturen genom århundraden av slummer. De vandrar i Emerald Dream medan deras dödliga kroppar vilar tryggt i stennischer. Men fördärvet som plågar Teldrassil har drivit den lokala Gnarlpine-stammen av furbolger till desperata våldsdåd. I Ban'ethil Barrow Den fann Gnarlpine-schamaner ett sätt att störa Oben Rageclaws heliga vila och slita hans levande själ från den sovande kroppen."},{t="Voodoo och fördärv",b="I stället för att döda Oben använde Gnarlpine-schamanerna en ondskefull talisman, Shaman Voodoo Charm, för att med våld väcka hans tomma skal till liv. Obens fördrivna själ är hjälplöst fångad i Emerald Dream och kan bara se på medan hans kropp strövar genom gångarna och blint angriper alla som går in i gravkammaren. För att bryta förtrollningen och hitta ett sätt att återställa kroppen ber hans andliga skepnad äventyrare hämta en av Gnarpines amuletter för undersökning."}},faq={{q="Vem är Oben Rageclaw?",a="Oben Rageclaw är en nattalvdruid som gick in i helig slummer i Ban'ethil Barrow Den för att förenas med Emerald Dream. Fientliga Gnarlpine-furbolger tog över hans kropp och lämnade hans själ fördriven.",al={"oben rageclaw","vem är den sovande druiden","sovande nattalv i gravkammare"}},{q="Varför angriper Obens kropp folk?",a="Gnarlpine-schamaner utförde en ritual som skilde Obens medvetande från hans kött. De väckte hans tomma kropp till liv med mörk magi, så att den skulle vakta gravkammarens djup och angripa inkräktare.",al={"varför är oben fientlig","varför anfaller oben","oben rageclaws kropp anfaller"}},{q="Vad är Shaman Voodoo Charm?",a="Det är en förtrollad kraftkälla som Gnarlpine-schamanerna bär i Ban'ethil Barrow Den. De använder dess mörka kraft för att slita sovande druiders själar ur deras kroppar och väcka deras fysiska skal till liv.",al={"schamanamulett","voodoo charm teldrassil","vad är shaman voodoo charm"}},{q="Var befinner sig Obens sanna själ under uppdraget?",a="Obens medvetande är fångat i Emerald Dream och vandrar där, oförmöget att återvända till sin dödliga kropp. Han kan bara tala med den vakna världen som en skimrande ande nära sin viloplats.",al={"var är oben","var finns obens själ","emerald dream oben"}},{q="Varför är furbolgerna i Ban'ethil Barrow Den fientliga?",a="Den växande smittan och galenskapen som fördärvar Teldrassils djurliv och skogar har drabbat Gnarlpine-stammen. Därför vänder de sig mot sina tidigare nattalvallierade och skändar heliga druidplatser.",al={"varför är gnarlpine galna","furbolgfördärv teldrassil","varför är furbolger aggressiva"}},{q="Kan Obens kropp räddas utan att dödas?",a="Att undersöka Shaman Voodoo Charm är Obens första hopp om att bryta ritualen. Genom att granska de vidriga förtrollningarna som binder hans kött hoppas han förstå magin och hitta ett sätt att lösa krisen.",al={"rädda oben rageclaw","kan oben räddas","bota oben"}}},fx={["08a1a718"]={q="Varför vill Oben Rageclaw ha amuletten?",a="Gnarlpine-furbolgschamaner har lyckats slita Oben Rageclaws ande från hans sovande kropp. Hans kringvandrande kropp har väckts till liv av deras mörka magi och angriper våldsamt alla som går in i Ban'ethil Barrow Den, medan hans sanna medvetande förblir fångat i The Emerald Dream. Oben vill ha en amulett så att han kan undersöka dess vidriga förtrollning och försöka hitta ett sätt att bryta furbolgernas grepp om hans kropp.",al={"oben rageclaws motiv","varför vill oben ha amuletten","varför hjälpa oben rageclaw"}},["21a70b6c"]={q="Varför är Gnarlpine-schamanerna i Ban'ethil Barrow Den?",a="Gnarlpine-stammen har intagit den heliga Ban'ethil Barrow Den och utnyttjar de sovande Night Elf-druidernas utsatthet. Deras schamaner har börjat utföra vidriga ritualer för att skilja druidernas andar från deras kroppar. De tar kontroll över kropparna och använder dem som våldsamma vaktposter för att skydda sitt nyockuperade underjordiska område.",al={"varför är gnarlpine-schamaner här","gnarlpine i barrow den","vilka är gnarlpine-schamanerna"}},["2131a103"]={q="Varför behöver Oben att du hämtar amuletten?",a="Oben är helt oförmögen att handla på egen hand. Hans ande har slitits loss från den vakna världen och är fångad i The Emerald Dream, medan hans fysiska kropp är en marionett som Gnarlpine-schamanerna styr. Utan en fysisk gestalt eller egen handlingsförmåga är han helt beroende av en äventyrare utifrån som möter furbolgerna och för amuletten till hans ande.",al={"varför behöver oben mig","varför kan oben inte hämta amuletten själv","varför jag på obens uppdrag"}}},fp="18,185,19.395.0,21.363.1,21.205.0,36.151.0,32.208.0,45.162.0,53.169.0,44.197.0"}
P.entries["quest:255"] = {n="Mercenaries",s="Mercenaries är ett kontrakt med belöning, utfärdat av Magistrate Bluntnose i Thelsamar, för att rensa bort de framryckande Mo'grosh-ogrerna i nordöstra Loch Modan. Eftersom militära förstärkningar från Ironforge har fastnat i månader av byråkratiska förseningar tvingas magistraten anlita äventyrare på genomresa för att skydda dalens utsatta bosättningar, utgrävningar och den livsviktiga Stonewrought Dam.",h="Mercenaries är ett kontrakt med belöning, utfärdat av Magistrate Bluntnose i Thelsamar, för att rensa bort de...",kw={"loch modan","magistrate bluntnose","legosoldater","mo'grosh","ogre","stonewrought dam","thelsamar"},ang={["faction:Alliance"]="Loch Modan utgör en viktig korridor mellan Khaz Modan och de norra rikena. Om området faller i kaos under ogreangrepp hotas Alliansens försörjningslinjer genom hela Eastern Kingdoms.",["race:Dwarf"]="Att se dvärgisk ingenjörskonsts kronjuvel, Stonewrought Dam, stå obevakad på grund av Ironforges byråkrati gör Bluntnoses upprop personligt för varje bergsman eller resenär från huvudstaden."},sec={{t="Ironforges långsamma kvarnar",b="Thelsamar känner av den dvärgiska byråkratins konsekvenser. Det tog hela två månader för Ironforge att ens lova en handfull soldater till Loch Modans lokala försvar, och ytterligare två månader innan trupperna ska anlända. Stadsvakterna är redan hårt pressade, så Magistrate Bluntnose har inte råd att vänta fyra månader medan fientliga styrkor samlas precis utanför dalens gränser."},{t="Hotet i bergen",b="Mo'grosh-ogrerna har befäst ett läger i kullarna nordöst om sjön. Deras växande närvaro hotar inte bara staden Thelsamar, utan även Ironband Excavation Site och själva Stonewrought Dam. Om dammen angrips eller skadas skulle förödelsen nedströms bli katastrofal. Eftersom det saknas officiella bergstrupper har Bluntnose vänt sig till frilansande legosoldater för att decimera ogrehorderna och ge dalen tid att stå emot både ogres och troggs."}},faq={{q="Varför anlitar Magistrate Bluntnose legosoldater i stället för att använda vakterna?",a="Ironforge har varit plågsamt långsamt med att svara på Loch Modans vädjanden om hjälp. Det tog två månader för senaten att godkänna att skicka ens en handfull soldater, och ytterligare två månader innan de faktiskt anländer. Bluntnose står inför omedelbara hot mot Thelsamar, dammen och lokala utgrävningar och har inget annat val än att betala fristående äventyrare.",al={"varför anlita legosoldater","thelsamars vakter","hjälp från ironforge"}},{q="Var finns Mo'grosh-ogrerna?",a="Mo'grosh-ogrerna håller till i Mo'grosh Stronghold, bland de karga klipporna och kullarna nordöst om Loch Modans stora sjö.",al={"ogreernas plats","var finns mogrosh","mogrosh-lägret"}},{q="Varför anses Stonewrought Dam vara i fara?",a="Stonewrought Dam reglerar hela sjön och är en arkitektonisk juvel bland dvärgarna. Med ett militärt försvar som i praktiken saknas och Mo'grosh-ogrerna i ett läger i närheten fruktar Bluntnose att en samordnad räd skulle kunna skada eller sabotera den väldiga konstruktionen och utlösa katastrofala översvämningar.",al={"varför skydda dammen","ogres och dammen"}},{q="Vilka andra hot möter Thelsamar utöver ogres?",a="Troggs har strömmat fram över hela sjöområdet från underjordiska ruiner och utgrävningar. Bluntnose ser dem som ett enormt hot, men den närliggande ogrehärens råstyrka tvingar honom att anlita kämpar för att driva tillbaka Mo'grosh, så att stadsvakten kan koncentrera sig på troggarnas angrepp.",al={"andra hot i loch modan","troggarnas hot"}}},fx={bfea2c9c={q="Varför vill Magistrate Bluntnose att Mo'grosh-ogrerna dödas?",a="Magistrate Bluntnose fruktar för Thelsamars och den omkringliggande regionens överlevnad. Mo'grosh-ogrerna har byggt ett starkt läger nordost om sjön, vilket gör staden, den lokala utgrävningsplatsen och Stonewrought Dam sårbara för ett förödande anfall medan Ironforge dröjer med att skicka försvarstrupper. Genom att driva tillbaka og be hoppas han undanröja ett överhängande hot och frigöra lokal uppmärksamhet så att den utbredda trogginvasionen kan hanteras.",al={"magistrate bluntnoses motiv","varför döda mogrosh-ogrerna","varför vill bluntnose ha legosoldater"}},["5f9f9ec0"]={q="Vilka är Mo'grosh-ogrerna som hotar Loch Modan?",a="Mo'grosh är en brutal ogreklan som har trängt in i nordöstra Loch Modan och lagt beslag på de karga kullarna bortom sjön. Deras hejdukar och råskinn visar upp en väldig fysisk styrka alldeles intill sårbart dvärgterritorium. Deras växande närvaro utgör ett omedelbart fysiskt hot mot resande, Stonewrought Dam och närliggande dvärgbosättningar, och de utnyttjar regionens uttänjda försvar.",al={"vilka är mogrosh","mogrosh-ogrer i loch modan","vad är mogrosh-ogrerna"}}},fp="11,262,23.274.0,23.420.0,71.330.0,37.118.0,49.268.0,59.258.0"}
P.entries["quest:256"] = {n="WANTED: Chok'sul",s="En belöning utlyst i Thelsamar av Magistrate Bluntnose kräver att Chok'sul dödas, en ogrehövding som hotar nordöstra Loch Modan. Han tros organisera attackerna mot lokala bosättningar och viktig infrastruktur. Om du tar med hans huvud får du en rejäl belöning av stadens ledning.",h="En belöning utlyst i Thelsamar av Magistrate Bluntnose kräver att Chok'sul dödas, en ogrehövding som hotar...",kw={"bluntnose","belöning","chok'sul","choksul","loch modan","ogre","stonewrought dam","thelsamar"},ang={["faction:Alliance"]="Loch Modan är en viktig jordbruks- och försörjningsled in i Dun Morogh, så stabiliteten kring Thelsamar är avgörande för Alliansens militära insatser.",["profession:Engineering"]="Stonewrought Dam är ett av de främsta verken inom dvärgisk samhällsbyggnadskonst. Ingen ansvarsfull hantverkare kan tänka sig att låta brutala ogres skada den.",["race:Dwarf"]="Att försvara Stonewrought Dam och de omgivande arkeologiska utgrävningarna handlar direkt om dvärgarnas stolthet, arv och säkerheten i Ironforges suveräna landområden."},sec={{t="Ett hot mot Loch Modan",b="Troggar och vilda djur sätter ständigt Loch Modans gränser på prov, men organiserade ogres är en upptrappning som de lokala dvärgiska bergsjägarna inte kan ignorera. De här bestarna har slagit läger i dalens karga nordöstra delar och ägnar sig åt mer än enkel plundring. Enligt lokala spejare och stadens myndigheter är deras räder målmedvetna, ihärdiga och farliga."},{t="Priset för Chok'suls huvud",b="Magistrate Bluntnose i Thelsamar pekade ut Chok'sul som hjärnan bakom våldet mot staden, den närbelägna dvärgiska utgrävningsplatsen och själva Stonewrought Dam. Av rädsla för katastrofala skador på dalens främsta ingenjörsverk och förlust av civila liv utlyste magistraten en belöning för ogrehövdingen: död på vilket sätt som helst, med hans avhuggna huvud som bevis."}},faq={{q="Vem utlyste belöningen för Chok'sul?",a="Magistrate Bluntnose, Thelsamars främsta stadstjänsteman, utfärdade officiellt ordern på stadens vägnar för att skydda trakten mot organiserade räder.",al={"vem vill se chok'sul död","vem utlyste belöningen för chok'sul","efterlyst i thelsamar"}},{q="Varför är Chok'sul ett så prioriterat mål?",a="Chok'sul tros samordna ogreangreppen mot Thelsamar, Ironforges arkeologiska utgrävningar och Stonewrought Dam. Målen hotar både dvärgarnas liv och rikets viktiga infrastruktur.",al={"varför döda chok'sul","vad gjorde chok'sul","chok'suls hot"}},{q="Var kan Chok'sul hittas?",a="Han finns i ogrelägret bland de karga kullarna i Loch Modans nordöstra hörn.",al={"chok'suls plats","var finns chok'sul","ogreläger i loch modan"}},{q="Vilket bevis kräver Magistrate Bluntnose?",a="Du måste ta Chok'suls avhuggna huvud direkt till Magistrate Bluntnose i Thelsamar för att få belöningen och Ironforges tacksamhet.",al={"chok'suls huvud","bevis för belöning","lämna in chok'sul"}},{q="Varför skulle ogres angripa Stonewrought Dam?",a="Stonewrought Dam håller tillbaka Loch Modans enorma sjö och är ett kronverk inom dvärgisk ingenjörskonst. Om dammen saboteras översvämmas våtmarkerna och dvärgarnas försörjningsleder ödeläggs, vilket gör den till ett viktigt taktiskt mål för fientliga styrkor.",al={"varför angripa dammen","stonewrought dam under attack"}},{q="Finns det andra ogres som samarbetar med Chok'sul?",a="Ja, Chok'sul leder ett ogreläger i kullarna nordost om sjön och styr räderna över de omgivande områdena.",al={"chok'suls klan","ogres i loch modan","chok'suls följeslagare"}}},fx={["761222eb"]={q="Vem är Chok'sul?",a="Chok'sul är ett ogre-råskinn som har tagit befälet över ogrelägret i nordöstra Loch Modan. Han tros vara den listige samordnaren bakom de samordnade räderna mot Thelsamar, Stonewrought Dam och den lokala dvärgarnas utgrävningsplats. Han utgör det största organiserade hotet mot dalens säkerhet.",al={"vem är choksul","choksuls mål","om choksul"}}},fp="16,180,20.280.0,28.306.0,34.138.0,55.180.0,28.103.0,45.143.0,44.216.0,44.123.0"}
P.entries["quest:2561"] = {n="Druid of the Claw",s="Djupt inne i gravkamrarna på Teldrassil ber Oben Rageclaws vålnad om en tragisk befrielse. Fördärvade furbolger har lagt en mörk förtrollning över hans kropp, så du måste förinta hans själlösa skal och bryta bandet så att hans ande kan återvända till The Emerald Dream.",h="Djupt inne i gravkamrarna på Teldrassil ber Oben Rageclaws vålnad om en tragisk befrielse.",kw={"ban'ethil","druid of the claw","emerald dream","gnarlpine","oben rageclaw","teldrassil","den sovande druiden","voodoo charm"},ang={["class:Druid"]="Att se en sovande Druid of the Claw skändas av fördärvade furbolger är en isande påminnelse om farorna med att lämna sin fysiska kropp utan tillsyn medan man samtalar med The Emerald Dream.",["race:NightElf"]="Teldrassil skulle vara en fristad för nattalverna, men den snabba fördärvningen av inhemska furbolger som Gnarlpine utgör ett omedelbart hot, även inne i deras heliga gravkamrar."},sec={{t="En avskild ande",b="När Oben Rageclaw vilade i gravkamrarna under Teldrassil drabbades han av ett fruktansvärt öde. De fördärvade Gnarlpine-furbolgerna utsatte hans sovande kropp för en vidrig voodoo-förtrollning som skilde hans ande från hans dödliga kropp. Obens ande är fångad i The Emerald Dream och dröjer kvar i närheten, oförmögen att finna ro eller återta sin kropp."},{t="Nåd för kroppen",b="När man undersökte Gnarlpines voodooamulet uppdagades den bistra sanningen: Obens kropp står helt under furbolgernas kontroll. För att bryta förtrollningen måste en äventyrare gå in i den närbelägna kammaren, fälla Oben Rageclaws tanklösa, fientliga hylsa och använda furbolgernas amulett över hans kvarlevor för att slutligen krossa magin som binder hans själ."}},faq={{q="Varför måste jag döda Oben Rageclaw?",a="Gnarlpine-furbolgerna lade en mäktig voodoo-förtrollning över Oben medan han sov och gjorde hans kropp till en själlös marionett. Eftersom hans kött helt står under deras kontroll är det enda sättet att bryta förtrollningen och befria hans kvarvarande ande att förstöra hans kropp.",al={"varför döda oben","döda sovande druid","oben rageclaws kropp"}},{q="Vad används Voodoo Charm till?",a="Amuletten är nyckeln till förtrollningen som kontrollerar Oben. När du har dödat hans fördärvade, själlösa kropp upplöser amuletten den mörka magi som håller hans ande fången, om du aktiverar den över hans fallna kvarlevor.",al={"voodooamulet användning","hur använder man voodooamulet","gnarlpine-amulett oben"}},{q="Vart tar Oben vägen efter det här uppdraget?",a="När hans kropp har dödats och förtrollningen brutits befrias Oben Rageclaws ande från de dödligas värld. Äntligen kan han färdas till The Emerald Dream och vila i frid.",al={"obens öde","vad händer med oben rageclaw","överlever oben"}},{q="Varför använder Gnarlpine voodoomagi?",a="Gnarlpine-furbolgerna har sjunkit djupt ner i fördärv och vansinne. De har vänt sig från sina förfäders harmoni och börjat ägna sig åt vidrig trolldom och enkel mörk magi för att kuva varelserna och de sovande druiderna omkring sig.",al={"furbolgers voodoo","gnarlpines voodoomagi","varför har furbolger amuletter"}},{q="Vem var Oben Rageclaw?",a="Oben var en nattalv, en Druid of the Claw, som gick in i en helig sömn i Teldrassils gravkamrar och samtalade med The Emerald Dream. Gnarlpine-furbolgerna störde hans vila och förslavade hans dödliga kropp.",al={"vem är oben","obens bakgrund","oben rageclaws bakgrund"}},{q="Talar Obens ande fortfarande med mig medan hans kropp lever?",a="Ja. Den mörka förtrollningen skilde Obens själ från hans kropp. Hans ande visade sig som ett spöke nära ingången till kammaren, helt oförmögen att kontrollera eller återvända till det förtrollade, tomma skalet därinne.",al={"obens spöke och kropp","två oben","varför är oben på två platser"}}},fx={bff893ba={q="Vem är målet jag skickas mot i Ban'ethil Barrow Den?",a="Du skickas för att förgöra Oben Rageclaws själlösa kropp. Hans ande dröjer sig kvar utanför, men hans sovande dödliga kropp har hamnat under en kraftfull förtrollning som Gnarlpine-furbolgarna inne i Ban'ethil Barrow Den använder. Utan sin själ lyder höljet nu deras fördärvade herravälde.",al={"vem ska jag döda","obens mål","obens själlösa kropp"}},["6e4ee394"]={q="Varför behöver Oben Rageclaw mig i stället för att göra det själv?",a="Oben är just nu en eterisk ande, helt avskild från sin dödliga kropp. Han är fångad som en vålnad utanför gravkammaren och saknar fysisk gestalt för att konfrontera sitt förtrollade hölje eller använda Voodoo Charm, som behövs för att bryta magin. Djupt inne i gravkammaren, utom räckhåll för nattalvernas väktare, är du den enda som kan ingripa.",al={"varför behöver oben mig","varför kan oben inte döda sin kropp","varför jag, oben rageclaw"}}},fp="17,211,16.299.0,19.214.1,36.212.0,34.159.0,36.153.1,41.195.0,22.193.0,61.168.0"}
P.entries["quest:257"] = {n="A Hunter's Boast",s="A Hunter's Boast är en tidsbegränsad jaktutmaning som Daryl the Youngling ger vid The Farstrider Lodge i Loch Modan. Den unge, arrogante människan vill skryta med sin påstådda skicklighet och utmanar äventyrare att spåra upp och fälla sex bergsgamar innan hans femtonminuterstimer går ut.",h="A Hunter's Boast är en tidsbegränsad jaktutmaning som Daryl the Youngling ger vid The Farstrider Lodge i Loch...",kw={"a hunter's boast","daryl the bold","daryl the youngling","the farstrider lodge","jaktutmaning","loch modan","bergsgamar","tidsbegränsat uppdrag"},ang={["class:Hunter"]="För skyttar och spårare är Daryls tävling en rolig chans att överträffa en skrytsam nybörjare på hans hemmaplan och få en pålitlig båge eller ett gevär.",["faction:Alliance"]="The Farstrider Lodge är en viktig utpost för Alliansen längs Loch Modans sydöstra vägar. Där erbjuds skydd och jakter planeras i de karga dalarna.",["race:Dwarf"]="Dvärgar som är vana vid lodgens erfarna jägare känner igen den unge människans poserande som tomt skryt, som bäst bemöts med stillsam skicklighet."},sec={{t="En ung skytt med högmod",b="The Farstrider Lodge är samlingsplats för några av Khaz Modans skickligaste spårare och skyttar, men alla där har inte veteranernas ödmjukhet. Daryl the Youngling, som gärna kallar sig ”Daryl the Bold”, avfärdar snabbt kringvandrande äventyrare. Övertygad om att utomstående gröngölingar inte kan mäta sig med hans jaktförmåga slår han vad på ett kaxigt sätt: fäll ett halvdussin lokala bergsgamar inom en kvart, eller erkänn dig besegrad."},{t="Färre asätare",b="Bergsgamar kretsar över Loch Modans klippor och sluttningar, där de letar efter matrester och jagar mindre djur. De är farliga i flock, men fungerar främst som ett grundläggande prov på en jägares snabbhet, tålamod och pricksäkerhet. Den som fäller det begärda bytet inom den strikta tidsgränsen får snabbt Daryls uppblåsta stolthet att sjunka. Motvilligt lämnar han då ifrån sig ett av sina distansvapen, vilket bäddar för fler jaktutmaningar."}},faq={{q="Var äger jaktutmaningen rum?",a="Uppdraget börjar vid The Farstrider Lodge, i den sydöstra vildmarken i Loch Modan. Bergsgamarna du ska jaga strövar omkring bland närliggande klippor och öppna höjdryggar i området.",al={"uppdragsplats","var finns daryl","var finns gamarna"}},{q="Vem är Daryl the Youngling?",a="Daryl the Youngling är en ambitiös, skrytsam ung människa som bor vid The Farstrider Lodge. Han kallar sig ”Daryl the Bold” och tycker om att håna resenärer och locka in dem i tidsbegränsade jaktprov för att bevisa sin inbillade överlägsenhet.",al={"vem är daryl","daryl the bold bakgrund","daryl vid farstrider"}},{q="Varför finns det en tidsgräns för jakten?",a="Kvartsfristen är en del av Daryls vad. Han tror att det är långt bortom en vanlig äventyrares förmåga att fälla vilda gamar under tidspress.",al={"varför femton minuter","timer på uppdraget","tidsbegränsat prov"}},{q="Vad händer när man klarat Daryls utmaning?",a="Daryl blir chockad över din framgång men vägrar erkänna sig besegrad på riktigt. Han håller vadet genom att erbjuda ett vapen och erbjuder genast en ny jaktuppgift, A Hunter's Challenge, där målet är större vilt.",al={"what comes next","fortsättning på skrytet","jägaruppdragskedja"}},{q="Varför jaga just bergsgamar?",a="Flockar av bergsgamar häckar kring Loch Modans klippiga sluttningar. De är snabba flygande mål, perfekta för att pröva om en bågskytt eller gevärsskytt har verklig fältdisciplin.",al={"varför gamar","gammarnas syfte","gamar i loch modan"}},{q="Hänger uppdraget ihop med The Farstrider Lodges övriga uppgifter?",a="Ja. Daryls prov leder direkt vidare till en längre serie jakter för lodgen, som kulminerar i spårningen av Ol' Sooty, björnen som gav Daryl hans ärr. Det ingår i Vyrin Swiftwinds plan att ge den skrytsamma ynglingen igen.",al={"vyrins koppling","lodgeberättelse","farstriders berättelse"}}},fx={["4c8cb4f1"]={q="Varför utmanar Daryl the Youngling dig att jaga gamar?",a="Daryl har mycket höga tankar om sin egen förmåga och vill visa upp sig. Han kallar sig ”Daryl the Bold”, ser ner på resande som passerar The Farstrider Lodge och räknar med att du ska misslyckas. Han satsar sitt eget jaktvapen i ett vad med en hård tidsgräns på femton minuter, bara för att bevisa att en utomstående inte kan mäta sig med hans skicklighet.",al={"varför vill daryl få detta gjort","daryls motiv","varför jaktutmaning från daryl"}},["3b45bb0a"]={q="Varför jagar inte Daryl gamarna själv?",a="Daryl ber inte om hjälp och vill inte minska antalet gamar för att skydda någon. Han erbjuder ett skrytsamt vad om en jaktutmaning. Han anser uppgiften vara under sin värdighet och tror att en oprövad äventyrare inte kan fälla sex fåglar på femton minuter. Då kan han skryta när du oundvikligen misslyckas.",al={"varför jag, daryl","varför jagar inte daryl gamar","varför frågar daryl mig"}}},fp="16,134,28.214.0,23.220.0,45.141.0,27.179.0,38.131.0,45.163.1,40.127.0,62.171.1"}
P.entries["quest:258"] = {n="A Hunter's Challenge",s="A Hunter's Challenge är ett tidsbegränsat jaktprov som den stöddige människan Daryl the Youngling utfärdar vid The Farstrider Lodge i sydöstra Loch Modan. Irriterad över att han inte lyckas förringa din tidigare bedrift slår Daryl vad om skjortan han har på sig: du kan inte spåra upp och fälla fem åldrade bergsgaltar på tolv minuter. Provet sätter en äventyrares snabbhet på prov mot höglandets oländiga terräng och farliga djurliv.",h="A Hunter's Challenge är ett tidsbegränsat jaktprov som den stöddige människan Daryl the Youngling utfärdar...",kw={"galt","coldridge","daryl","åldrad bergsgalt","the farstrider lodge","jakt","loch modan","youngling"},ang={["class:Hunter"]="För spårningsexperter är jakten på fem åldrade bergsgaltar genom höglandets snår inom en snäv tidsgräns ett klassiskt prov på att hantera villebråd och fälla det snabbt.",["faction:Alliance"]="The Farstrider Lodge är en viktig samlingsplats för Alliansens skogvaktare som skyddar Loch Modans östra gräns mot vilddjur och hot från höglandet.",["race:Dwarf"]="Alla dvärgar som växt upp i Coldridge Valley känner genast igen Daryls jämförelse, men hans nedlåtande attityd är svårare att stå ut med."},sec={{t="En ynglings skryt",b="Daryl the Youngling bor bland de erfarna jägarna vid The Farstrider Lodge, men han saknar deras stillsamma tålamod. I stället kompenserar Daryl för sin ringa ålder med skryt och överdrivna jakthistorier, däribland långrandiga berättelser om hur han fick sitt ”berömda” ärr. Han vägrar erkänna att någon annan är skicklig, förvränger ständigt sina jägarvänners namn och hittar på hårda prov som ska förödmjuka nykomlingar och återställa hans uppblåsta anseende bland lodgens invånare."},{t="Jakten i höglandet",b="Till skillnad från de enklare vildsvinen i Coldridge Valley, där unga dvärgspanare först lär sig sitt yrke, är de åldrade bergsgaltarna som strövar bland klipporna och sluttningarna i Loch Modan massiva, tjockhudade och farliga när de provoceras. Daryl ger jägare bara tolv minuter att hitta, fälla och bekräfta att de dödat fem sådana bestar. Om du hinner avsluta jakten tvingas den högljudda ynglingen dra sig undan generat och låtsas inte minnas det storslagna vad han så lättvindigt ingick."}},faq={{q="Vem är Daryl the Youngling?",a="Daryl är en ung, skrytsam mänsklig jägare som bor vid The Farstrider Lodge i sydöstra Loch Modan. Han vill desperat verka lika skräckinjagande som de äldre veteranerna omkring sig och pratar oupphörligen om sin egen skicklighet, hittar på storslagna historier och utmanar förbipasserande äventyrare på svåra jaktprov.",al={"vem är daryl","daryl the youngling bakgrund","daryl vid farstrider lodge"}},{q="Var finns de åldrade bergsgaltarna?",a="Åldrade bergsgaltar strövar i kullarna, ängarna och bergsryggarna kring The Farstrider Lodge och i de södra och östra delarna av Loch Modan. Du kan hitta dem på bete i det böljande höglandet mellan lodgen och den centrala sjön.",al={"plats för åldrade bergsgaltar","var hittar man galtar","område för galtjakt"}},{q="Varför är jakten tidsbegränsad?",a="Daryl begränsar jakten till tolv minuter eftersom han är säker på att du kommer att misslyckas. Med en snäv tidsgräns hoppas han förödmjuka dig och bevisa att dina tidigare jaktbedrifter bara berodde på nybörjartur.",al={"varför tolv minuter","varför är det tidsbegränsat","tidsgräns för jägarutmaning"}},{q="Vad slog Daryl vad om?",a="När Daryl förklarade provet lovade han självsäkert att ge dig skjortan han hade på sig om du lyckades fälla de fem åldrade bergsgaltarna i tid. När du sedan återvänder triumferande låtsas han förstås snabbt att han inte minns något sådant vad.",al={"daryls vad","skjortan han har på sig","vad slog daryl vad om"}},{q="Hur skiljer sig dessa från galtarna i Coldridge Valley?",a="Daryl påpekar särskilt att de här åldrade bergsgaltarna är mycket tåligare och mer aggressiva än de mindre vildsvin som nybörjardvärgar jagar i Coldridge Valley. De fullvuxna galtarna i Loch Modan har tjockare skinn och farliga betar som slipats mot höglandets granit.",al={"galtar i coldridge mot bergsgaltar","jämförelse med coldridge"}},{q="Vart leder den här jaktkedjan sedan?",a="När du tystat Daryls skryt genom att klara hans utmaning riktas uppmärksamheten vid lodgen mot allvarligare saker. Det leder till en konfrontation med den farliga åldrade björnen Ol' Sooty i uppdraget Vyrin's Revenge.",al={"vilket uppdrag kommer härnäst","efter a hunter's challenge","jaktuppdragskedja"}}},fx={["4ae04a68"]={q="Vad är gamla bergsvildsvin?",a="Gamla bergsvildsvin är härdade, tåliga bestar som hör hemma bland klipporna och kullarna kring Loch Modan. Till skillnad från de mindre vildsvin som strövar omkring på platser som Coldridge Valley är de här djuren betydligt segare och farligare att tränga in i ett hörn. Daryl pekar särskilt ut dem för att pressa dina spårnings- och stridsfärdigheter till det yttersta. Han räknar med att du misslyckas innan tiden går ut.",al={"gamla bergsvildsvin i loch modan","varför gamla vildsvin","vilka är vildsvinen"}},["33153764"]={q="Varför skickar Daryl ut dig på den här jakten i stället för att jaga själv?",a="Daryl the Youngling föredrar att hålla hov på The Farstrider Lodge och återberätta storslagna historier om hur han fick sitt berömda ärr, i stället för att släpa sig ut i vildmarken igen. Han är övertygad om sin egen överlägsna skicklighet och utfärdar de här allt svårare prövningarna enbart för att sätta dig på plats och bevara sin självutnämnda prestige bland jägarna.",al={"varför jagar inte daryl själv","varför behöver daryl mig","varför jagar inte daryl"}}},fp="20,188,15.446.0,17.327.0,27.255.0,43.198.0,23.188.0,24.165.0,48.217.0,40.191.1"}
P.entries["quest:26"] = {n="A Lesson to Learn",s="”A Lesson to Learn” är en tidig övergångsrit för alliansdruider som tränar i Darnassus. Mathrengyl Bearwalker ger uppdraget och skickar noviserna till den heliga fristaden Moonglade, där de börjar bemästra sin vattenform.",h="”A Lesson to Learn” är en tidig övergångsrit för alliansdruider som tränar i Darnassus.",kw={"a lesson to learn","vattenform","darnassus","dendrite starblaze","druiduppdrag","mathrengyl bearwalker","moonglade","nighthaven"},ang={["class:Druid"]="Det här uppdraget är en viktig milstolpe i en druids träning och öppnar vägen till att ta del av Cenarius gåvor under vågorna.",["race:NightElf"]="För kaldorei från Darnassus är det en vördad tradition att hörsamma Cenarion Circles kallelse i Moonglade. Den knyter dem till deras uråldriga läromästare."},sec={{t="Vildmarkens kallelse",b="Mathrengyl Bearwalker vakar över unga nattalvdruider som övar sin konst bland Darnassus trädkronor. När en novis visar ett starkt band till naturen och viljan att axla större ansvar, ber Mathrengyl dem förbereda sig för nästa stora disciplin: att bemästra vattnet. Cenarius gåvor kräver intensiv koncentration, och förmågan att färdas under vatten utan att drunkna kräver direkt kontakt med Cenarion Circles äldste."},{t="Resan till Nighthaven",b="För att gå vidare måste novisen lämna Darnassus och resa till Moonglade, den uråldriga helgedomen vid foten av Mount Hyjal. I den fridfulla bosättningen Nighthaven väntar Dendrite Starblaze. Som en av Circles äldste mentorer bedömer Starblaze om unga skepnadsskiftare är redo för prövningarna som krävs för att låsa upp vattenformen. Han varnar dem för att mästerskap över vattnet kräver både fysisk uthållighet och mental styrka."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Mathrengyl Bearwalker, druidtränaren i Cenarion Enclave i Darnassus, ger dig uppdraget när du har kommit tillräckligt långt i dina tidiga druidkonster.",al={"uppdragsgivare","vem ger uppdraget a lesson to learn","vem startar det här"}},{q="Vad är syftet med det här uppdraget?",a="Det är första steget för druider som vill förtjäna sin vattenform. Det kallar novisen till Moonglade för att få undervisning och prövningar av den äldre Dendrite Starblaze.",al={"varför göra uppdraget","introduktion till vattenformen","vad får jag"}},{q="Var finns Dendrite Starblaze?",a="Dendrite Starblaze bor i byn Nighthaven, vid Lake Elune'aras norra strand i Moonglade.",al={"dendrites plats","var finns dendrite starblaze","hitta dendrite"}},{q="Hur tar sig druider till Moonglade för det här uppdraget?",a="Druider har en andlig samhörighet som låter dem teleportera direkt till Moonglades heliga lund med förmågan Teleport: Moonglade, utan att behöva färdas landvägen.",al={"hur tar jag mig till moonglade","ta sig till nighthaven"}},{q="Vad händer efter att jag har talat med Dendrite Starblaze?",a="När ditt möte med Dendrite Starblaze är över ger han dig genast uppdraget Trial of the Lake, som prövar din uthållighet och ditt sinne under vattnet.",al={"nästa uppdrag","vad händer sedan","efter a lesson to learn"}}},fx={["67389e7a"]={q="Varför skickar Mathrengyl Bearwalker dig till Moonglade?",a="Mathrengyl Bearwalker har följt din utveckling och tror att du är redo att fördjupa din samhörighet med det vilda. Djurens aspekter som Cenarius skänkt kräver djupare undervisning än vanlig träning kan ge. För att lära dig hemligheterna bakom vattenbehärskning hänvisar han dig till Dendrite Starblaze och Cenarion Circle i Nighthaven, där uråldriga druidiska prövningar övervakas.",al={"varför skickar mathrengyl dig","mathrengyl bearwalkers motiv","varför åka till moonglade"}}},fp="17,189,20.376.0,21.333.0,27.137.0,34.135.0,36.94.0,45.112.0,48.146.0"}
P.entries["quest:2605"] = {n="The Thirsty Goblin",s="Marin Noggenfogger i Gadgetzan plågas av törst. Ryktet säger att daggsamlarna i kaktusträdgården sydväst lagrar vatten i särskilda körtlar, och Marin hoppas att en av dem kan bli en dryck som äntligen släcker törsten.",h="Marin Noggenfogger i Gadgetzan plågas av törst.",kw={"kaktusträdgård","daggsamlare","daggkörtel","gadgetzan","marin noggenfogger","tanaris","thistleshrub valley"},sec={{t="En drickbar körtel",b="Marin har hört talas om märkliga varelser som kallas daggsamlare. De lever sydväst om Gadgetzan och lagrar vatten i särskilda körtlar. Marin tror att en välfylld körtel kan bli början på en dryck som för alltid gör slut på törsten. Du ombeds hitta kaktusträdgården där de lever och ta med en tillbaka."}},faq={{q="Vem skickar dig på jakt efter daggkörteln?",a="Marin Noggenfogger i staden Gadgetzan ber dig hitta en välfylld daggkörtel som kan bota en fruktansvärd törst.",al={"uppdragsgivare för törstig goblin","vem startar törstig goblin","marin noggenfogger"}},{q="Var håller daggsamlarna till?",a="De lever i kaktusträdgården i Thistleshrub Valley, sydväst om Gadgetzan i Tanaris.",al={"daggsamlarens plats","var hittar man daggkörtel","kaktusträdgårdens plats"}},{q="Vilken varelse bär på den välfyllda daggkörteln?",a="Körtlarna kommer från Thistleshrub Dew Collectors, varelser som sägs lagra vatten i särskilda körtlar.",al={"vad släpper välfylld daggkörtel","daggsamlarvarelse"}},{q="Vad händer härnäst i kedjan?",a="Kedjan fortsätter med In Good Taste.",al={"fortsättning på törstig goblin","nästa uppdrag efter törstig goblin"}}},fp="18,235,22.289.0,40.107.0,37.89.0,42.102.0,29.40.0"}
P.entries["quest:2606"] = {n="In Good Taste",s="Marin Noggenfogger tycker att Thistleshrub Dew smakar hemskt, men bestämmer sig ändå för att inte ge upp. Du skickas till Sprinkle, en vän till Marin i Gadgetzan, med daggen i handen.",h="Marin Noggenfogger tycker att Thistleshrub Dew smakar hemskt, men bestämmer sig ändå för att inte ge upp.",kw={"gadgetzan","in good taste","marin noggenfogger","sprinkle","tanaris","thistleshrub dew"},sec={{t="En kock till en dålig brygd",b="Marin smakar på daggen och tycker att den är hemsk, men bestämmer sig ändå för att inte ge upp idén. I stället får du daggen och skickas till Sprinkle, en vän i Gadgetzan som Marin kallar en utmärkt kock. Du ska berätta för henne vad som pågår och att drycken behöver bli lättare att få ner. Marin vill också att den ska ha lite sting."}},faq={{q="Var passar det här steget in i kedjan?",a="Det följer efter The Thirsty Goblin, och Sprinkle's Secret Ingredient kommer efter det.",al={"vilket uppdrag kommer före det här","vad kommer härnäst i kedjan","uppdragskedjans ordning"}},{q="Varför vill Marin Noggenfogger att daggen ska tas till Sprinkle?",a="Marin tyckte att daggen var hemsk att dricka. Marin kallar Sprinkle en utmärkt kock och hoppas att hon kan göra den lättare att få ner, med lite sting.",al={"varför sprinkle","vad vill marin ha sprinkle till","vem är sprinkle"}},{q="Var hittar man Sprinkle?",a="Sprinkle finns i Gadgetzan, samma stad som Marin Noggenfogger.",al={"sprinkles plats","var finns sprinkle","hitta sprinkle"}}},fp="13,180,21.326.0,38.79.0,59.138.0,28.62.0"}
P.entries["quest:261"] = {n="Down the Scarlet Path",s="Brother Anton från Scarlet Crusade vid Nijel's Point säger att hans orden ligger i krig med Scourge, en ondska som fördärvar folket och smittar landet. Han ber dig bevisa din trohet genom att döda trettio odöda ravagers i Valley of Bones.",h="Brother Anton från Scarlet Crusade vid Nijel's Point säger att hans orden ligger i krig med Scourge, en...",kw={"brother anton","desolace","down the scarlet path","nijel's point","scarlet crusade","scourge","odöd ravager","valley of bones"},sec={{t="Bevis på trohet",b="Brother Anton talar rakt på sak. Han säger att Scourge måste stoppas innan den slukar landet och drar världen in i mörkret, och att Scarlet Crusade har svurit att kämpa mot den. Om du står med dem vill han att du visar ditt mod och din trohet genom att döda trettio odöda ravagers. De finns söder om Anton, i Valley of Bones. Klarar du det kommer Crusade att välkomna dig."}},faq={{q="Vem ber dig döda de odöda ravagers?",a="Brother Anton från Scarlet Crusade vid Nijel's Point.",al={"vem ger down the scarlet path","brother anton uppdrag","scarlet crusade npc i desolace"}},{q="Var finns de odöda ravagers?",a="Valley of Bones, söder om Nijel's Point i Desolace.",al={"odöd ravager plats","var ligger valley of bones","ravagers i desolace"}},{q="Varför vill Brother Anton att ravagers dödas?",a="Han säger att Crusade ligger i krig med Scourge, en ondska som fördärvar folket och smittar landet, och vill att du bevisar din trohet.",al={"varför döda odöda ravagers","brother anton motiv","scarlet crusades anledning"}},{q="Hur många ravagers måste dödas?",a="Trettio.",al={"hur många ravagers","antal ravagers"}},{q="Vad kommer före detta?",a="Ditt möte med Brother Anton kommer först.",al={"föregående uppdrag","förutsättning för down the scarlet path"}}},fp="21,251,19.386.0,44.55.0,36.56.0,51.145.0,36.7.0,23.44.0"}
P.entries["quest:262"] = {n="The Shadowy Figure",s="Plågad av minnet av sin familjs massaker ber eremiten Sven Yorgen dig ta reda på vem den mystiska främlingen var som sågs smyga nära hans gård den ödesdigra natten. Med endast en gåtfull bok som hittats bland ruinerna till hjälp måste du rådfråga invånarna i Darkshire för att följa främlingens spår.",h="Plågad av minnet av sin familjs massaker ber eremiten Sven Yorgen dig ta reda på vem den mystiska främlingen...",kw={"bok","darkshire","duskwood","madame eva","skuggig gestalt","sven yorgen","svens läger"},ang={["class:Priest"]="Undersökningen av Madame Evas spådom belyser den tunna slöjan mellan andlig klärvoajans, skuggmagi och osynliga psykiska avtryck som dröjer kvar på vardagliga föremål.",["faction:Alliance"]="Darkshires brist på stöd från Stormwind tvingar stadens traumatiserade gränsbor och lokala siare att helt förlita sig på kringvandrande hjältar från Alliansen när de utreder dödliga illdåd i Duskwood."},sec={{t="Ekon av en massaker",b="Sven Yorgen lever gömd bland Duskwoods ödsliga kullar, knäckt av den fasansfulla slakten på sin familj. Först lade han skulden på de mystiska svarta ryttarna som terroriserar skogarna, men ett annat minne plågar honom fortfarande: en tyst, skuggig gestalt som smög omkring i närheten den natt då massakern ägde rum. Sven är desperat efter svar och anförtror dig den enda fysiska ledtråden från gårdens ruiner, en märklig bok som lämnades kvar på den plundrade gården."},{t="Spådom i staden",b="Utan några direkta spår att följa i den farliga vildmarken leder spåret österut, tillbaka till Darkshire. Sven hoppas att någon bland de vidskepliga invånarna känner igen den märkliga boken. Darkshire har sin beskärda del av underligheter och medier, framför allt Madame Eva, vars ockulta sinnen och spådomar låter henne se bortom det vanliga och läsa de andliga avtryck som dröjer kvar vid mystiska reliker."},{t="Främmande spår",b="När du visar boken för Madame Eva framträder svaga men omisskännliga psykiska avtryck. Svens brinnande hämndbegär har nyligen satt sina spår på sidorna, men den underliggande auran tillhör någon helt annan. Eva spår att den ursprungliga ägaren inte alls var bosatt i Darkshire eller Duskwood, vilket bekräftar att en främling besökte gården innan blodbadet började."}},faq={{q="Vem är Sven Yorgen?",a="Sven Yorgen är en förkrossad bonde som drivits i landsflykt till Duskwoods västra kullar. Efter att svarta ryttare angrep hans gård och slaktade hela hans familj förföljde han dem ut i vildmarken, uppslukad av sorg och en desperat törst efter hämnd på de skyldiga.",al={"vem är sven","svens bakgrund","sven yorgen"}},{q="Vad är boken från Svens gård?",a="Boken är ett fysiskt föremål som hittades bland jord och bråte från Svens förstörda gård. Den tillhörde en svårfångad åskådare som sågs smyga i skuggorna under attacken mot hans familj.",al={"vad är det här för bok","boken från svens gård","mystisk bok"}},{q="Varför ta boken till Madame Eva?",a="Madame Eva är Darkshires siare och spåkvinna. Vanliga stadsbor kan inte utläsa mycket ur en omärkt bok, men Eva använder sina klärvoajanta förmågor för att läsa psykiska avtryck som lämnats kvar av den som tidigare ägde eller bar föremålet.",al={"varför madame eva","vem läser boken","mystiker i darkshire"}},{q="Vad får Madame Eva veta av boken?",a="Madame Eva känner det starka känslomässiga avtryck av hämnd som Sven nyligen lämnat efter sig när han hanterade boken. Under det upptäcker hon dock svaga spår som tyder på att den ursprungliga ägaren var en främling, inte någon från Darkshire.",al={"vad säger eva","bokens ägare","spådomens resultat"}},{q="Vart leder utredningen härnäst?",a="När Madame Eva får veta att ägaren var en främling skickar hon dig att söka bland andra uppteckningar och på olika platser i Darkshire, efter någon som minns en obekant resenär som passar in på gestaltens beskrivning.",al={"vad händer sedan","uppdrag efter boken","vem är den skuggiga gestalten"}}},fx={d371091b={q="Varför vill Sven Yorgen att det här ska göras?",a="Sven är uppslukad av sorg och ett desperat behov av svar. Natten då hans familj slaktades på gården såg han en mystisk gestalt som lurade i skuggorna. Han tror att det är hans enda chans att få veta sanningen bakom massakern och skipa rättvisa att ta reda på vem den skuggande figuren är.",al={"varför vill sven hitta den skuggiga figuren","sven yorgens motiv","varför hitta bokens ägare"}},["35559963"]={q="Varför ber Sven Yorgen dig i stället för Night Watch?",a="Sven är en isolerad, traumatiserad eremit som håller sig gömd i Duskwoods vildmarker, långt från Darkshire. Du har redan visat prov på din uppfinningsrikedom genom att hitta den förstörda dagboken på hans ödelagda gård. Det har övertygat honom om att du har den beslutsamhet och list som krävs för att lösa mysteriet när ingen annan vill försöka.",al={"varför ber inte sven night watch","varför behöver sven min hjälp","varför jag, sven yorgen"}}},fp="18,175,21.344.0,26.310.0,15.276.1,19.232.0,38.201.0,32.230.0,41.186.1,40.199.1"}
P.entries["quest:2622"] = {n="The Missing Orders",s="Dispatch Commander Ruag blir irriterad när du frågar om de saknade orderna och hävdar att de vidarebefordrades. Ruag säger att soldaterna som bar dem överfölls av murlocer och att bara en överlevde. Hen skickar dig till Bengor.",h="Dispatch Commander Ruag blir irriterad när du frågar om de saknade orderna och hävdar att de...",kw={"överfall","bengor","dispatch commander ruag","saknade order","murloc","swamp of sorrows"},sec={{t="Ruags redogörelse",b="Ruag tar illa upp av frågan och hävdar att orderna vidarebefordrades. Soldaterna som skickades med dem blev, enligt Ruag, överfallna och brutalt misshandlade av murlocer, och bara en överlevde, om det ens kan kallas att leva. Den överlevande kan knappt tala, kan inte gå och får mat genom en slang. För att få veta vad som blev av orderna ska du enligt Ruag tala med Bengor, som finns någonstans här i närheten. Ruag varnar dig också för att lägga näsan i blöt, så att den inte blir avbiten."},{t="Bengors stapplande ord",b="När du hittar Bengor kommer bara lösryckta ord fram, och bland dem uppfattar du orden sumppratare."}},faq={{q="Vem skickade orderna som försvann?",a="Dispatch Commander Ruag säger att orderna vidarebefordrades med soldaterna som skickades iväg och blir defensiv när du frågar vad som hände med dem.",al={"vem gav orderna som saknas","vem tappade bort orderna"}},{q="Vad hände med soldaterna som bar orderna?",a="Enligt Dispatch Commander Ruag överföll och misshandlade murlocer dem brutalt, och bara en överlevde.",al={"vad hände med kurirerna","hur försvann orderna"}},{q="Vem är Bengor?",a="Bengor är den enda överlevande från överfallet. Han kan knappt tala, kan inte gå och får mat genom en slang.",al={"vem är den överlevande","bengors historia"}},{q="Var kan Bengor hittas?",a="Dispatch Commander Ruag säger bara att Bengor finns någonstans här i närheten.",al={"bengors plats","var är bengor"}}},fp="18,216,14.454.0,22.109.1,38.132.0,50.98.0,14.101.0,26.71.0"}
P.entries["quest:2623"] = {n="The Swamp Talker",s="Bengor kan knappt tala, men lyckas berätta vad som hände med orderna. Befälhavaren för kurirerna gav honom dem, och på vägen till Blasted Lands överfölls gruppen av många murlocer. En av dem, som kallades Swamp Talker, tog orderna ur hans händer. De måste återtas och föras till Fallen Hero of the Horde.",h="Bengor kan knappt tala, men lyckas berätta vad som hände med orderna.",kw={"bengor","blasted lands","fallen hero of the horde","murloc","swamp of sorrows","swamp talker","warchief's orders"},sec={{t="Bengors osammanhängande berättelse",b="Bengor berättar att befälhavaren för kurirerna gav honom orderna och att gruppen var på väg till Blasted Lands när många murlocer överföll dem. En av murlocerna, som kallades Swamp Talker, tog orderna ur hans händer medan ett spjut drevs in i hans skalle. Bengor får fram ett ord om en grotta i öster innan han svimmar. Orderna måste återtas och föras till Fallen Hero of the Horde."},{t="Fallen Heros uppgörelse",b="Fallen Hero of the Horde finner att det är värre än han föreställt sig. Nitton av Herons män hade kunnat besparas lidande om Heron inte hade handlat så irrationellt. Maktlös att ingripa ber Heron dig att hjälpa männen."}},faq={{q="Vem stal Warchief's Orders?",a="En murloc vid namn Swamp Talker tog orderna ur Bengors händer under överfallet.",al={"vem tog orderna","vem är swamp talker","vem stal orderna"}},{q="Vart tog Swamp Talker vägen?",a="Bengors avtagande ord nämner en grotta i öster.",al={"var finns swamp talker","swamp talkers plats","var finns murlocgrottan"}},{q="Vart var Bengor och hans enhet på väg?",a="De var på väg till Blasted Lands med order från befälhavaren för kurirerna när murlocer överföll dem.",al={"bengors destination","vart var bengor på väg","bengors enhets mål"}},{q="Till vem ska orderna återlämnas?",a="De måste föras till Fallen Hero of the Horde.",al={"vem ska ha warchief's orders","var lämnar jag in orderna","lämna in swamp talker-uppdraget"}}},fp="16,317,23.392.0,27.213.1,32.82.0,30.49.0,39.121.0,38.53.0"}
P.entries["quest:263"] = {n="In Defense of the King's Lands",s="Det här uppdraget skildrar hur Ironforges Mountaineers trappar upp kampen mot trogginvasionen i södra Loch Modan. Från Southern Guard Tower skickar Mountaineer Wallbang erfarna rekryter in i Stonesplinter Valley för att röja undan farliga troggschamaner och bonesnappers vid fronten. Klarar du prövningen vinner du Wallbangs fulla förtroende och får träffa garnisonens befälhavande kapten.",h="Det här uppdraget skildrar hur Ironforges Mountaineers trappar upp kampen mot trogginvasionen i södra Loch...",kw={"bonesnapper","ironforge","loch modan","magni","mountaineer","schaman","stonesplinter","trogg","wallbang"},ang={["class:Shaman"]="När du möter Stonesplinter-troggarnas råa trollkarlar får du en oförfinad och vild inblick i jordmagi förvriden av brutala instinkter.",["faction:Alliance"]="När du hjälper Southern Guard Tower säkrar du viktiga handels- och färdvägar som förbinder Dun Morogh med de östra våtmarkerna och kungariket Stormwind.",["race:Dwarf"]="För en dvärg är det en fråga om att försvara hemmet att svara på Wallbangs kallelse och skydda hemmen i Loch Modan medan dina fränders stående arméer skickats utomlands."},sec={{t="En tunn dvärgalinje",b="Loch Modans försvar är pressat till bristningsgränsen. Dvärgarnas reguljära reserver har kallats till avlägsna fronter runtom Azeroth, så lokala utposter som Southern Guard Tower saknar folk. Mountaineer Wallbang och hans få kamrater utsätts för ständig press från Stonesplinter-klanen och måste förlita sig på tillresta Alliance-resenärer för att hålla det södra passet."},{t="Slå mot Stonesplinter-förtruppen",b="I stället för att plocka bort enstaka spejare slår den här kampanjen djupare in i Stonesplinter-hierarkin. Troggarnas bonesnappers står för klanens brutala råstyrka, medan deras primitiva schamaner väver jordmagi för att samla sina fränder. När du eliminerar tjugo sådana högvärdiga mål hejdar du deras intrång i låglandet och bidrar direkt till King Magni Bronzebeards försvar av riket."}},faq={{q="Vem är Mountaineer Wallbang?",a="Mountaineer Wallbang är en dvärg från Ironforge, stationerad vid Southern Guard Tower i Loch Modan. Han har i uppgift att hålla uppsikt över troggarnas spridning från bergen och samordna milisens insatser för att säkra den södra huvudvägen.",al={"wallbang","vem är wallbang","mountaineer wallbangs bakgrund"}},{q="Varför ber Mountaineers resenärer om hjälp?",a="Ironforges militära reserver har kallats bort till viktigare stridsfronter i riket och bortom dess gränser. Omplaceringen lämnar gränsutposter som Loch Modans södra vakttorn farligt underbemannade inför lokala hot.",al={"varför behöver dvärgar hjälp","var finns ironforges vakter","varför finns inga reserver"}},{q="Var finns de här troggarna?",a="De håller främst till i Stonesplinter Valley, bland de karga kullarna sydväst om The Loch. Mindre grupper av schamaner och bonesnappers hemsöker även de norra öarna ute i sjön.",al={"var finns stonesplinter-troggar","var finns stonesplinter-schamaner","var ligger stonesplinter valley"}},{q="Varför är Stonesplinter-klanen ett hot?",a="Troggar förökar sig snabbt och översvämmar bebodda områden med väldiga svärmar underifrån. Stonesplinter-klanen brukar rå elementmagi genom sina schamaner och förlitar sig på ursinniga bonesnappers som sliter sig igenom dvärgarnas spejare. Därmed hotar de närliggande bosättningar och handelsvägar.",al={"varför är troggar farliga","stonesplinter-hotet"}},{q="Vad gör Mountaineer Wallbang efter uppdraget?",a="När Wallbang är övertygad om att du bevisat dig som kämpe i King Magnis tjänst skickar han dig till Captain Rugelfuss för fler strategiska order om försvaret av Loch Modan.",al={"vad händer efter wallbang","vem är kaptenen"}},{q="Vem styr Ironforge under den här krisen?",a="King Magni Bronzebeard styr dvärgarnas rike från High Seat i Ironforge. Alla insatser för att skydda Loch Modan görs i hans namn och till försvar av hans landområden.",al={"vem är dvärgarnas kung","kung av ironforge"}}},fx={["20cd043f"]={q="Varför vill Mountaineer Wallbang att de här troggarna dödas?",a="Troggproblemet i Loch Modan blir allt värre och hotar säkerheten i Ironforges suveräna territorium. Mountaineer-reserverna har kallats bort till avlägsna fronter, så Wallbang och hans kamrater i det södra vakttornet står utan förstärkningar. Han måste decimera troggarnas led för att skydda dalen och hålla stånd i kungens namn.",al={"varför döda stonesplinter-troggar","wallbangs motiv","varför vill wallbang ha troggarna döda"}},c0ccff20={q="Vilka är Stonesplinter Shaman och Bonesnappers?",a="De är specialiserade förtrupper från Stonesplinter-troggklanen som tränger in i Loch Modan. Bonesnappers fungerar som klanens brutala, hårt slående hejdukar, medan deras shamaner kanaliserar rå, ursprunglig magi. Tillsammans utgör de kärnan i styrkan som driver troggarna upp ur djupen och in i dvärgarnas land.",al={"stonesplinter-shamaner","stonesplinter-bonesnapper","vilka är troggmålen"}}},fp="30,305,19.346.0,36.308.0,28.214.0,51.201.0,31.186.0,43.218.0,50.174.0,39.159.0"}
P.entries["quest:264"] = {n="Until Death Do Us Part",s="Until Death Do Us Part är ett bittert och personligt uppdrag som leder till The Sepulcher i Silverpine Forest. Clarice Foster, en Forsaken som bor i The Pools of Vision under Thunder Bluff, skickar äventyrare för att lägga hennes minnessmycke på hennes avlidne make Yurivs grav. Uppdraget blottlägger de smärtsamma sprickor i människors liv som fanatism och krig orsakar medan pesten lade Lordaeron öde.",h="Until Death Do Us Part är ett bittert och personligt uppdrag som leder till The Sepulcher i Silverpine Forest.",kw={"clarice foster","korståg","forsaken","smycke","the sepulcher","silverpine","grav","yuriv"},ang={["class:Priest"]="Uppdraget målar upp en dyster bild av tron och visar hur hängivenhet åt Ljuset kan slita sönder familjer och skapa en bitterhet som dröjer kvar hos dem som lämnats bakom.",["faction:Horde"]="Genom att hjälpa Clarice får Hordens mästare en inblick i de personliga tragedier och den långlivade bitterhet som håller Forsaken samman i Silverpine Forest.",["race:Undead"]="För Forsaken förkroppsligar Clarices lidande de levandes hyckleri: heliga krigare lämnade sina familjer att gå under i religiös iver, och deras förvandlade överlevare fick bära minnenas börda."},sec={{t="Ett bittert minne",b="Clarice Foster hyser inga varma känslor för minnena av sitt dödliga äktenskap. När Lordaeron föll övergav hennes make Yuriv henne och deras barn för att ge sig ut på ett korståg mot det växande hotet från de odöda. Han förklarade att tjänsten åt det Heliga Ljuset gick före allt. Till slut räddade hans hängivenhet varken hans familj eller honom själv. Nu när Clarice återuppstått som odöd och Yuriv ruttnar under en vanvårdad gravsten vill hon bara göra sig av med den sista påtagliga påminnelsen om hans brutna löften."},{t="Den försummade graven",b="Yurivs grav ligger på kyrkogården kring The Sepulcher, märkt av djupa hugg, täckt av skräp och övervuxen av ogräs. När Clarice's Pendant läggs på den uthuggna bilden av hans händer uppstår ingen mäktig magi och ingen andlig försoning. Ädelstenen mattas bara, och en kall, tyst vindpust sveper över gravarna. Det blir ett bistert vittnesmål om den bitterhet som ännu lever kvar bland Lorderaons fallna folk."}},faq={{q="Vem var Yuriv?",a="Yuriv var Clarice Fosters dödlige make. Medan han levde lämnade han henne och deras barn för att strida mot Scourge i det Heliga Ljusets namn och satte korståget före familjen.",al={"vem är yuriv","yurivs bakgrund","clarices make"}},{q="Varför hatar Clarice sin avlidne make så mycket?",a="Clarice väntade natt efter natt på Yuriv medan han satte sina religiösa plikter främst. Till slut misslyckades hans korståg med att skydda dem. Han dog i en försummad grav, medan hon förbannades till att återuppstå som det odöda monster han hade kämpat mot.",al={"varför är clarice arg","clarice fosters bakgrund"}},{q="Vad händer när du återlämnar smycket?",a="När smycket läggs på de uthuggna stenbilderna av Yurivs händer mattas ädelstenen märkbart. En hård, sval vind sveper över The Sepulcher och lämnar den vanvårdade graven i kall, tyst övergivenhet.",al={"smycke på graven","slutet på until death do us part"}},{q="Var ligger Yurivs grav?",a="Yurivs gravsten finns på kyrkogården vid The Sepulcher, Forsakens fäste i norra Silverpine Forest.",al={"var ligger yurivs grav","yurivs gravplats"}},{q="Varför är Yurivs grav så skadad?",a="Graven är full av huggmärken och skräp och har vuxit igen av ogräs. Forsaken som bor vid The Sepulcher känner ingen sympati eller vördnad för en korsfarare som dog när han stred mot deras folk.",al={"varför är graven vanvårdad","vanvårdad grav"}},{q="Överlevde Clarices barn?",a="Clarice berättar att Yuriv övergav barnen tillsammans med henne, men det framgår inte vad som sedan hände dem. Med tanke på Lorderaons totala förödelse är det troligt att de gick ett tragiskt öde till mötes.",al={"vad hände med barnen","clarices barn"}}},fp="22,265,17.408.0,19.333.0,14.166.0,47.191.0,41.178.1,30.104.0,32.174.0,31.149.0"}
P.entries["quest:2641"] = {n="Sprinkle's Secret Ingredient",s="När Marin Noggenfoggers brygd visar sig vara vidrig erbjuder Sprinkle i Gadgetzan sig att göra den drickbar med sin hemliga ingrediens, en svamp som kallas Violet Tragan. Den växer under vatten i en liten sjö i The Hinterlands.",h="När Marin Noggenfoggers brygd visar sig vara vidrig erbjuder Sprinkle i Gadgetzan sig att göra den drickbar...",kw={"gadgetzan","the hinterlands","svamp","noggenfogger","sprinkle","tanaris","violet tragan"},sec={{t="En kocks hemlighet",b="Sprinkle berättar om sin barndom, då hennes syster stod för all matlagning och resultatet var svårt att få ner. Sedan hittade hon en svamp, Violet Tragan, sin ”hemliga” ingrediens, och den fick varje rätt att smaka underbart. Hon ska använda den för att göra Marins vidriga brygd drickbar."},{t="Under vattenytan",b="Svampen finns i The Hinterlands, i en liten sjö där. Valorwind Lake ligger strax söder om vägen som korsar zonen. Violet Tragan växer bara under vatten, så du måste dyka under ytan och samla in den innan du återvänder till Sprinkle i Gadgetzan."}},faq={{q="Vem är Sprinkle?",a="Sprinkle är kock i Gadgetzan och vän med Marin Noggenfogger, som skickade dig till henne med en illa smakande brygd.",al={"vem är sprinkle","sprinkle gadgetzan","uppdragsgivare för sprinkles hemliga ingrediens"}},{q="Vad är Violet Tragan?",a="Det är en svamp som Sprinkle hittade som barn och kallar sin hemliga ingrediens. Hon säger att den får allt att smaka gott.",al={"violet tragan","vad är violet tragan","svamp som hemlig ingrediens"}},{q="Var finns Violet Tragan?",a="Bara under vatten i en liten sjö i The Hinterlands. Valorwind Lake ligger strax söder om vägen som korsar zonen.",al={"var finns violet tragan","var hittar man den hemliga ingrediensen","violet tragan plats"}},{q="Hur hänger det ihop med Marin Noggenfogger?",a="Marins brygd smakade hemskt, så Sprinkle vill använda Violet Tragan för att göra den ätbar.",al={"varför behöver sprinkle den här","koppling till marin noggenfogger","noggenfoggers uppdragskedja"}}},fp="28,215,15.292.0,15.272.0,16.112.0,26.115.0,37.112.0,44.99.0"}
P.entries["quest:265"] = {n="The Shadowy Search Continues",s="Efter Madame Evas spådom leder utredningen från hennes salong till Clerk Daltry i Darkshire. Fokus ligger på att spåra ursprunget till journalen som hittades i ruinerna av Sven Yorgens plundrade gård.",h="Efter Madame Evas spådom leder utredningen från hennes salong till Clerk Daltry i Darkshire.",kw={"bok","clerk daltry","darkshire","duskwood","journal","madame eva","skuggig gestalt","sven yorgen"},ang={["class:Rogue"]="Att spåra ett nervöst mål genom staden med hjälp av köpregister och köpmäns iakttagelser är klassiskt utredningsarbete.",["faction:Alliance"]="Att avslöja vilka som försåg nekromantikerna i Duskwood med hjälp och stöd är avgörande för att skydda Darkshire och skipa rättvisa åt de slaktade nybyggarna vid gränslandet."},sec={{t="Spåra inbindningen",b="Efter att ha undersökt den smutsfläckade journalen som räddades efter tragedin på Svens gård insåg Madame Eva att dess författare var en främling, men att själva boken kom från Darkshire. Clerk Daltry säljer ofta blanka liggare och böcker till resande lärda, magiker och arkivhållare. Genom att följa handeln på orten söker utredarna en vanlig pappersledtråd som kan avslöja en annars svårfångad och ondskefull inkräktare i Duskwoods dystra skogsdungar."},{t="En nervös köpare",b="När Clerk Daltry granskar boken minns han affären tydligt, trots alla handlingar som passerar genom Darkshires stadshus. För ungefär en månad sedan köpte en nervös och hemlighetsfull resenär den blanka boken utan att uppge sitt namn. Kundens skärrade sätt och ständiga blickar över axeln gjorde ett tydligt intryck på skrivaren och bekräftade att den skuggiga gestalten som Sven skymtade hade rört sig öppet bland Darkshires invånare."}},faq={{q="Var kom den mystiska boken ifrån?",a="Madame Eva säger att författaren är främling i Darkshire, men att boken köptes i staden. Clerk Daltry säljer blanka böcker och kanske minns köparen.",al={"bokens ursprung","vem sålde boken","bokens källa"}},{q="Varför skickar Madame Eva dig till Clerk Daltry?",a="Madame Eva känner igen bokens fysiska inbindning och material som sådant som köpts lokalt i staden. Clerk Daltry sköter försäljningen av blanka liggare och journaler till ortsbor och resande lärda.",al={"varför daltry","kopplingen mellan eva och daltry","vem gjorde boken"}},{q="Vad minns Clerk Daltry om köparen?",a="Daltry minns dem som köpt böcker av honom under de senaste månaderna. Om du visar honom boken kan han undersöka vem som köpte den.",al={"vem köpte boken","beskrivning av köparen","den skuggiga gestaltens utseende"}},{q="Hur hänger det ihop med Svens gård?",a="Boken räddades från Sven Yorgens förstörda gård i södra Duskwood. Den lämnades kvar under den mordiska räden som utplånade hans familj.",al={"kopplingen till sven","varför letar vi","sven yorgen"}},{q="Vart leder utredningen härnäst?",a="Eftersom den nervösa främlingen tillbringade tid i staden fortsätter sökandet på Darkshires värdshus, Scarlet Raven Tavern, för att se om någon såg var han bodde eller vem han talade med.",al={"vad händer härnäst","efter daltry","nästa ledtråd"}},{q="Är Clerk Daltry i fara?",a="Daltry hjälper till att identifiera en köpare utifrån sin vanliga bokförsäljning. Det finns inget i det här samtalet som tyder på att han själv är hotad.",al={"är clerk daltry i fara","är daltry säker"}}},fx={["9bf6b406"]={q="Varför hjälper Madame Eva till med sökandet?",a="Madame Eva är Darkshires siare och rådgivare och håller uppsikt över de skuggiga omen som hemsöker Duskwood. När du visade henne den jordfläckiga boken från Svens förstörda gård kände hon att någon hämndlysten nyligen hade hanterat den, medan svaga intryck från dess ursprungliga ägare visade att han var främling i Darkshire. Hon kunde också se att själva boken hade köpts i staden. Därför skickar hon dig att fråga stadsborna, i hopp om att de kan knyta boken till dess ägare.",al={"varför hjälper madame eva","madame evas motiv","varför bryr sig madame eva om boken"}}},fp="28,175,19.314.0,15.355.1,40.150.0,45.168.0,48.90.0,37.143.0,39.144.1,26.126.0"}
P.entries["quest:266"] = {n="Inquire at the Inn",s="Inquire at the Inn är ett alliansuppdrag i Darkshire som fortsätter undersökningen av den mystiske främlingen med koppling till Sven Yorgens förstörda gård. På uppdrag av Clerk Daltry tar äventyrare med sig en återfunnen dagbok till Scarlet Raven Tavern för att fråga Tavernkeep Smitts vem som bodde där.",h="Inquire at the Inn är ett alliansuppdrag i Darkshire som fortsätter undersökningen av den mystiske främlingen...",kw={"clerk daltry","darkshire","duskwood","inquire at the inn","raven hill","scarlet raven","skuggfigur","sven yorgen","tavernkeep smitts"},ang={["class:Rogue"]="Att spåra en paranoid flykting från rykten på en taverna till ödsliga ruiner passar en fältagents utredningsmetoder perfekt.",["faction:Alliance"]="Genom att undersöka hot inne i Darkshire hjälper du till att skydda en av Alliansens mest utsatta och isolerade gränsbyar i södra Eastern Kingdoms."},sec={{t="Ett spår på Scarlet Raven",b="När Clerk Daltry har undersökt den slitna boken från Sven Yorgens gård föreslår han att en främling som besökte Darkshire nästan säkert passerade genom den lokala tavernan. Scarlet Raven Tavern ligger på andra sidan staden och är Darkshires enda samlingslokal och härbärge, vilket gör den till det rimligaste stället att leta efter tillfälliga besökare."},{t="Den paranoida gästen",b="När Tavernkeep Smitts får se boken bekräftas Daltrys misstanke. Smitts känner genast igen den och minns en gäst som hyrde ett rum i flera dagar och tillbringade kvällarna med att skriva frenetiskt vid bardisken. Enligt värden flydde gästen från Darkshire i skräck, övertygad om att en osynlig förföljare jagade honom utan uppehåll. Han tog vägen västerut, längs den dystra vägen mot Raven Hill."}},faq={{q="Vem skickar dig till värdshuset?",a="Clerk Daltry, stadens arkivarie i Darkshires stadshus, lämnar tillbaka dagboken och föreslår att du frågar på det lokala värdshuset om någon känner igen dess ägare.",al={"vem ger uppdraget","uppdragsgivare","var börjar inquire at the inn"}},{q="Vad är det för bok du bär på?",a="Det är den slitna dagboken som hämtades från Sven Yorgens förstörda gård i södra Duskwood. Den tros ha tillhört den skuggfigur som sågs stryka omkring i området.",al={"vad är boken","boken från svens gård","dagbok"}},{q="Vem driver Scarlet Raven Tavern?",a="Tavernkeep Smitts sköter Scarlet Raven Tavern, serverar drycker och hyr ut rum till de resande som fortfarande vågar ta sig in i Duskwood.",al={"vem är tavernans värd","värdshusvärd i darkshire","vem är smitts"}},{q="Vad avslöjar Tavernkeep Smitts om gästen?",a="Smitts minns att dagbokens ägare hyrde ett rum i några dagar och tillbringade nätterna med att dricka och skriva. Sedan flydde resenären västerut i panik och mumlade om att något skräckinjagande jagade honom.",al={"vad sa smitts","vad hände med skuggfiguren","vad vet värdshusvärden"}},{q="Vart flydde skuggfiguren?",a="Han skyndade västerut från Darkshire för att hitta ett gömställe. Det pekar sökarna mot den övergivna bosättningen och den vidsträckta kyrkogården i Raven Hill.",al={"vart tog han vägen","var är skuggfiguren","vart härnäst"}},{q="Vilket uppdrag följer efter Inquire at the Inn?",a="Tavernkeep Smitts ber dig följa främlingens spår västerut i uppdraget \"Finding the Shadowy Figure\".",al={"nästa uppdrag","vad kommer efter inquire at the inn","uppdraget som följer"}}},fx={["5b964541"]={q="Varför vill Clerk Daltry att du frågar på värdshuset?",a="Clerk Daltry för stadens register över Darkshire, men hans liggare kan inte redogöra för mystiska vandrare som smyger genom skuggorna. Han vet att du spårar den svårfångade gestalten med koppling till de hemska händelserna på Svens gård och hänvisar dig till Scarlet Raven Tavern. I en misstänksam stad som Darkshire skulle värdshusvärden ha lagt märke till varje främling som stannade för en drink eller en säng.",al={"varför skickar daltry dig till värdshuset","daltrys motiv gällande värdshuset","varför fråga på scarlet raven inn"}}},fp="18,161,27.319.0,18.286.1,25.161.0,34.148.0,34.127.0,51.172.0,34.71.0,38.95.0"}
P.entries["quest:2661"] = {n="Delivery for Marin",s="Sprinkle i Gadgetzan ger dig Violet Powder att ta med till Marin Noggenfogger, och påminner dig om att Marin är skyldig henne en gentjänst.",h="Sprinkle i Gadgetzan ger dig Violet Powder att ta med till Marin Noggenfogger, och påminner dig om att Marin...",kw={"gadgetzan","marin noggenfogger","noggenfoggerelixir","sprinkle","tanaris","violet powder"},sec={{t="En leverans i staden",b="Med Violet Tragan i handen ger Sprinkle dig Violet Powder att ta med till Marin Noggenfogger, som också är i Gadgetzan. Du ska säga till Marin att hon är skyldig en gentjänst."}},faq={{q="Vem skickar dig till Marin Noggenfogger?",a="Sprinkle i Gadgetzan ger dig Violet Powder när du har hämtat Violet Tragan åt henne.",al={"vem ger leveransen till marin","uppdragets uppdragsgivare för leveransen till marin","sprinkles leverans"}},{q="Vilket föremål ska du leverera?",a="Violet Powder, som Sprinkle ger dig att ta med till Marin Noggenfogger.",al={"vad tar du med till marin","marins leveransföremål","vilket pulver är det"}},{q="Var finns Marin Noggenfogger?",a="I Gadgetzan, samma stad som Sprinkle.",al={"marin noggenfoggers plats","var finns marin","hitta marin noggenfogger"}},{q="Vilket meddelande vill Sprinkle att du framför till Marin?",a="Hon vill att du säger till Marin att han är skyldig henne en gentjänst.",al={"sprinkles meddelande","vad säger sprinkle till marin","sprinkles gentjänst"}}},fp="18,132,15.176.0,36.90.0,29.71.0,36.40.0,48.46.0"}
P.entries["quest:2662"] = {n="Noggenfogger Elixir",s="Marin Noggenfogger i Gadgetzan tar Violet Powder för att blanda det i daggen och ber dig komma tillbaka om en liten stund, när hans fantastiska elixir är fulländat.",h="Marin Noggenfogger i Gadgetzan tar Violet Powder för att blanda det i daggen och ber dig komma tillbaka om en...",kw={"dagg","gadgetzan","goblin","marin noggenfogger","noggenfogger elixir","pulver","sprinkle","tanaris"},sec={{t="Blandar elixiret",b="Marin, som har daggen och nu också pulvret, sätter igång med att blanda det ena med det andra. Du ska vänta en liten stund och sedan prata med Marin igen, då Noggenfogger Elixir bör vara klart."},{t="Marins besked",b="När Marin är klar räcker han dig en dryck och förklarar att den är underbar. Marin skryter om miljonerna som elixiret kommer att inbringa, ber dig ställa dig åt sidan så att du inte står i vägen för affärerna och skrattar bort Sprinkles påstående om en gentjänst som ett skämt."}},faq={{q="Vem erbjuder det här uppdraget?",a="Marin Noggenfogger i Gadgetzan.",al={"uppdragsgivare för noggenfogger","vem ger noggenfogger elixir","marin noggenfogger-uppdrag"}},{q="Vad hände före det här steget?",a="Det följer efter Delivery for Marin. Före det kom The Thirsty Goblin, In Good Taste och Sprinkle's Secret Ingredient.",al={"förkunskapskrav för noggenfogger elixir","föregående uppdrag för marin","vad kommer före noggenfogger elixir"}},{q="Vilka ingredienser blandar Marin här?",a="Marin blandar Violet Powder från Sprinkle med daggen.",al={"ingredienser i noggenfogger","vad blandar marin","vad finns i elixiret"}}},fp="19,161,17.191.0,15.233.1,22.33.0,27.115.0,41.57.0"}
P.entries["quest:267"] = {n="The Trogg Threat",s="Hotet från troggs är ett Alliance-uppdrag som Captain Rugelfuss ger vid Southern Gate i Loch Modan. När den lokala Ironforge Reserve kallats bort för att stödja Alliance-frontlinjerna har de försvarande trupperna svårt att stå emot de fientliga troggstammarna i kullarna. Äventyrare får i uppdrag att decimera troggarna och återvända med deras stentänder för att lätta trycket på bergspasset.",h="Hotet från troggs är ett Alliance-uppdrag som Captain Rugelfuss ger vid Southern Gate i Loch Modan.",kw={"captain rugelfuss","ironforge reserve","khaz modan","loch modan","magni bronzebeard","southern gate","trogg","trogg stone tooth"},ang={["faction:Alliance"]="Uppdraget visar hur Alliance åtaganden i avlägsna länder har tömt lokala garnisoner som den i Loch Modan på deras försvarsreserver.",["race:Dwarf"]="För dvärgar är det en direkt plikt mot Khaz Modan att decimera troggarna nära Southern Gate. Det ger dem dessutom beröm från King Magni Bronzebeard själv."},sec={{t="En utarmad gräns",b="Försvarslinjen som skyddar den södra infarten till Loch Modan är i ett prekärt läge. De ordinarie dvärgiska bergssoldaterna och Ironforge Reserve-regementena har skickats för att förstärka Alliance-krigsfronter på andra håll. Kvar vid södra vakttornet är Captain Rugelfuss och en liten garnison. Rugelfuss har strikta order att inte överge porten och kan därför inte inleda en offensiv i högländerna, vilket gör närliggande bosättare och resenärer sårbara för bakhåll."},{t="Hålla stånd mot strömmen",b="Troggs i de kringliggande klippbranterna utgör ett allt större hot mot Khaz Modan. Om de lämnas i fred växer de snabbt i antal och hotar att ta över dvärgiska utposter. För att vinna tid och minska hotet kallar Rugelfuss på kringvandrande äventyrare. De ska anfalla troggarna direkt i deras hålor på sluttningarna och visa upp avhuggna stentänder som bevis på dådet."}},faq={{q="Vem är Captain Rugelfuss?",a="Captain Rugelfuss är en officer i dvärgarnas militär, stationerad vid vakttornet vid Southern Gate i Loch Modan. Hans uppgift är att säkra passet mot intrång, trots den allvarliga bristen på garnisonssoldater.",al={"captain rugelfuss","vem ger uppdraget om troggotet","rugelfuss"}},{q="Varför är Southern Gate underbemannad?",a="Ironforge Reserve har mobiliserats och omplacerats för att strida vid Alliance-frontlinjerna långt borta. Bara ett litet regemente finns kvar vid porten. De måste hålla sin försvarspost och kan inte genomföra motangrepp.",al={"varför finns det inga vakter","ironforge reserve saknas","var är dvärgsoldaterna"}},{q="Vad är troggstentänder?",a="Troggs har naturligt förstenade, stenlika tänder som vittnar om deras underjordiska ursprung i jorden. Captain Rugelfuss kräver dem som otvetydiga fysiska bevis på att troggs har dödats.",al={"trogg stone tooth","stentänder","varför troggtänder"}},{q="Var finns troggarna?",a="Troggarna håller till i de klippiga kullarna, ravinerna och utgrävningsplatserna längs vägen nära Southern Gate i Loch Modan.",al={"var hittar man troggs","troggarnas platser i loch modan","var finns troggs för uppdraget"}},{q="Varför är troggarna ett så stort hot just nu?",a="Troggs förökar sig snabbt, är våldsamt territoriella och invaderar bebodda områden när garnisoner skickas bort. Utan aktiva insatser för att decimera dem hotar de att blockera passen mellan Loch Modan och grannområdena.",al={"varför är troggs farliga","troggproblemet","vad vill troggs"}},{q="Hur hjälper uppdraget King Magni Bronzebeard?",a="King Magni Bronzebeard ansvarar för säkerheten i hela Khaz Modan. Genom att minska troggarnas antal medan Ironforge-arméerna strider långt borta skyddar äventyrare rikets inre försörjningsleder och utsatta gränsbosättningar.",al={"magni bronzebeards koppling","bryr sig magni","varför hjälpa ironforge"}}},fx={["5b5ee45d"]={q="Varför vill Captain Rugelfuss att det här ska göras?",a="När Ironforge-reserven skickats till Alliansens front saknar Captain Rugelfuss manskap för att säkra området. Hans regemente är fast vid det södra vakttornet och håller stånd mot en möjlig invasion. Om troggarna som samlas i de närliggande kullarna lämnas åt sig själva kan de lätt övermanna utposten och ta över Loch Modan.",al={"rugelfuss motiv","varför slåss mot troggar","captain rugelfuss syfte"}},ba878bae={q="Varför kryllar kullarna nära Southern Gate av troggar?",a="Troggarna har dykt upp i dvärgarnas länder och tränger aggressivt in på bosättningar och färdvägar. De har funnit kullarna runtomkring lämpliga för en invasion och strövar längs åsarna nära Southern Gate, redo att slå till mot sårbara försvar som försvagats av den pågående bristen på soldater.",al={"vilka är troggarna","troggmål","varför är troggarna här"}}},fp="16,241,19.279.0,17.283.0,25.170.0,38.173.0,27.184.0,29.111.0,43.196.0,58.204.0"}
P.entries["quest:268"] = {n="Return to Sven",s="Det här uppdraget markerar ögonblicket då Sven Yorgen äntligen får veta sanningen bakom den brutala massakern på hans familj vid The Yorgen Farmstead. Efter att ha spårat upp den förrymde Jitters återvänder du till Svens avskilda läger i utkanten av Westfall med den kringströvandes färdigställda dagbok. Dagboken lovar svar på frågorna som har hemsökt Sven sedan attacken.",h="Det här uppdraget markerar ögonblicket då Sven Yorgen äntligen får veta sanningen bakom den brutala massakern...",kw={"dark riders","duskwood","forlorn rowe","jitters","jitters' completed journal","morbent fel","sven yorgen","the yorgen farmstead"},ang={["class:Paladin"]="Att hjälpa Sven avslöja krafterna bakom mordet på hans familj är en helig plikt: att skydda oskyldiga och skipa rättvisa.",["faction:Alliance"]="Den tragiska undergången för The Yorgen Farmstead är en tydlig påminnelse om Stormwinds fullständiga misslyckande med att skydda Duskwoods gränsbosättningar från de annalkande skuggorna."},sec={{t="En feg bekännelse",b="När Sven Yorgens gård angreps flydde Jitters i skräck in i skogen och lämnade bara efter sig en ofullständig dagbok bland de döda. Skräckslagen inför Svens vrede och hemsökt av det han bevittnat gömde sig Jitters djupt inne i Duskwood. När du konfronterar honom räcker han villigt över sin färdigställda dagbok och hoppas desperat att hela berättelsen om attacken ska skona honom från att möta den hämndlystne bonden personligen."},{t="Avslöja Dark Riders",b="När Sven läser Jitters färdiga berättelse faller de fasansfulla bitarna äntligen på plats. Massakern på hans gård var ingen slumpmässig anstormning av odöda eller attack från vilda bestar; den utfördes av de gåtfulla Dark Riders, som sökte efter en artefakt. Sven minns dessutom att han sett samma huvtäckta gestalter möta nekromantikern Morbent Fel i hemlighet nära Forlorn Rowe. Jitters dagbok förvandlar Svens blinda sorg till en riktad jakt på hämnd mot den mörke trollkarlen."}},faq={{q="Varför är Jitters så rädd för Sven Yorgen?",a="Jitters flydde från Svens gård och fasar för att möta den sörjande bondens vrede. Han ber dig överlämna dagboken så att Sven kan läsa hans berättelse.",al={"varför är jitters rädd","jitters rädd för sven","vad gjorde jitters"}},{q="Vad finns i Jitters färdigställda dagbok?",a="Den innehåller Jitters fullständiga berättelse om händelserna på Svens gård. Sven måste läsa den för att förstå vad som hände med hans familj.",al={"vad står det i dagboken","jitters färdigställda dagbok berättelse"}},{q="Vilka är Dark Riders som Sven nämner?",a="Dark Riders är mystiska, huvtäckta gestalter som strövar omkring i Duskwood. De är hänsynslösa och dödliga och kom till skogen för att outtröttligt söka efter mäktiga magiska reliker. Döden och förödelsen följer i deras spår.",al={"vilka är dark riders","ryttare i duskwood","svarta ryttare"}},{q="Hur har Morbent Fel koppling till attacken på Svens gård?",a="Morbent Fel är en mäktig nekromantiker i västra Duskwood. Hans koppling till attacken avslöjas genom Svens undersökning och Jitters dagbok.",al={"morbent fels koppling","varför morbent fel","vem är morbent fel"}},{q="Var hittar man Sven Yorgen?",a="Sven har lämnat sin förstörda gård och bor nu i ett litet, spänt läger intill kullarna i nordvästra Duskwood, nära gränsövergången till Westfall.",al={"var är sven","sven yorgens plats","svens läger"}},{q="Vad händer när man ger Sven dagboken?",a="Sven läser Jitters fullständiga berättelse och ber dig bevisa din stridsförmåga i nästa uppdrag, Proving Your Worth.",al={"nästa uppdrag efter return to sven","nästa uppdrag i svens uppdragskedja"}}},fx={ba46c9da={q="Varför behöver Jitters dig att lämna över dagboken i stället för att göra det själv?",a="Jitters är helt uppslukad av rädsla. Han gömde sig osedd i Svens lada medan Svens familj slaktades och flydde sedan utan sin halvfärdiga dagbok. I stället för att riskera att möta Svens vrede personligen lämnar han gärna över sin färdigställda dagbok till dig, så att sanningen om vad som egentligen hände kommer fram.",al={"varför skickar jitters mig","varför kan jitters inte prata med sven","varför lämna över jitters dagbok"}}},fp="14,161,21.336.0,25.409.1,43.138.0,38.144.1,42.144.0,58.137.1,31.140.0,43.96.1"}
P.entries["quest:269"] = {n="Seeking Wisdom",s="I Stormwind söker Sven Yorgen helig vägledning för Duskwood. Han skickar Jitters' Completed Journal till Bishop Farthing i Cathedral of Light och hoppas att biskopen kan avslöja hur Morbent Fels sköld ska förstöras.",h="I Stormwind söker Sven Yorgen helig vägledning för Duskwood.",kw={"bishop farthing","cathedral of light","darkshire","duskwood","jitters","morbent fel","seeking wisdom","stormwind","sven yorgen"},ang={["class:Paladin"]="Som paladin prövas Silver Hands plikt att skydda de bortglömda och driva ut nekromanti när du bär vädjanden om helig hjälp från de övergivna gränstrakterna till Cathedral of Light.",["class:Priest"]="Som präst ger Bishop Farthing vägledning om hur mörka skydd fördärvar kropp och själ. Skuggmagi kräver fokuserad helgelse såväl som klingan.",["faction:Alliance"]="Som Alliance-resenär blottar färden klyftan mellan Stormwind Citys bevakade marmorsalar och Duskwoods övergivna städer, som inte får något stöd från garnisonen."},sec={{t="En vädjan från skuggorna",b="Duskwood plågas av kvardröjande förbannelser och glupska odöda, medan Stormwinds kungliga hov blir alltmer likgiltigt. Sven Yorgen, en förkrossad överlevare i ett läger nära gränsen, vet att vanlig styrka inte kan tränga igenom Morbent Fels mörka skydd. Med Jitters samlade journal ber Sven dig söka kyrkans råd. Vägen norrut leder till Cathedral of Light."},{t="Råd i katedralen",b="Bishop Farthing lyssnar till Duskwoods vädjan i Stormwinds katedral. Jitters redogörelse bekräftar Morbent Fels fruktansvärda makt: vidrig trolldom skyddar nekromantikern mot vanliga slag. Mod ensamt kan inte övervinna skyddet. För att besegra honom måste ett förtrollat heligt föremål hittas."}},faq={{q="Varför skickar Sven dig till Bishop Farthing i stället för till King Anduin?",a="Sven litar på Bishop Farthing, en medkännande och lärd man inom det heliga ljuset som förstår mörk magi. Stormwinds adel och armé har i stort sett lämnat Darkshire och de omgivande trakterna åt sitt öde under det politiska dödläget, så Sven väntar sig inga soldater från officiellt håll.",al={"varför farthing","varför inte stormwinds adel","stormwind ignorerade duskwood"}},{q="Vad är Jitters journal, och varför behöver biskopen den?",a="Jitters skrev ned vad som hände kring attacken mot Svens gård. Sven skickar den färdiga redogörelsen till Bishop Farthing så att han kan ge råd åt äventyraren som förbereder sig på att möta Morbent Fel.",al={"vad är jitters journal","varför jitters journal","jitters färdiga journal"}},{q="Vem är Morbent Fel?",a="Morbent Fel är en mäktig nekromantiker som setts vid Forlorn Rowe i Duskwood. Han befaller horder av skelett och skyddar sig med kraftfulla skydd som avvärjer vanliga vapen.",al={"vem är morbent fel","morbent fels bakgrund"}},{q="Var finns Bishop Farthing?",a="Bishop Farthing håller till i Cathedral of Light, den storslagna människokatedralen i stadsdelen Cathedral Square i Stormwind City.",al={"var finns farthing","farthings plats","bishop farthing karta"}},{q="Vad händer när Bishop Farthing har läst journalen?",a="Bishop Farthing förklarar att vanliga slag inte kan skada Morbent Fel. Han visar dig mot en helgad relik som kan skingra nekromantikerns skydd och inleder sökandet efter Doomed Fleet.",al={"vad händer efter seeking wisdom","uppföljning till seeking wisdom","efter seeking wisdom"}},{q="Var håller Sven Yorgen till i Duskwood?",a="Sven Yorgen tar skydd i ett litet läger i nordvästra Duskwood, nära flodgränsen, söder om Elwynn Forest och väster om det hemsökta Raven Hill Cemetery.",al={"var finns sven","sven yorgens plats","svens läger"}}},fx={["12ed4f38"]={q="Varför behöver Sven Yorgen dig för att lämna över dagboken?",a="Sven håller ut ensam i Duskwood, uppslukad av hämnd och sorg medan han överlever i ett läger omgivet av fasor. Stormwind har övergett Darkshire och de kringliggande länderna åt sig själva, så inga kungliga vakter kan hjälpa honom. Sven kan inte lämna Duskwood obevakat och har inte heller möjlighet att ensam bryta Morbent Fels mörka trolldom. Du har visat din styrka mot de lokala hoten och är hans enda pålitliga hopp om att föra Jitters avslöjande sanning till någon med vishet och helig kraft nog att hjälpa.",al={"varför jag, sven","varför skicka spelaren till bishop farthing","varför åker inte sven till stormwind"}}},fp="14,177,23.345.0,24.281.1,65.291.0,57.173.0,19.184.0,33.123.0,53.193.1,40.161.0"}
P.entries["quest:27"] = {n="A Lesson to Learn",s="A Lesson to Learn är en övergångsrit för unga tauren-druider som är redo att ta makten över vattnet i sin tjänst. Turak Runetotem ger uppdraget på Thunder Bluffs höjder och skickar eleverna till Nighthaven i Moonglade för att inleda sina prövningar under Cenarion Circles vägledning.",h="A Lesson to Learn är en övergångsrit för unga tauren-druider som är redo att ta makten över vattnet i sin...",kw={"aquatic form","cenarion circle","dendrite starblaze","elder rise","lesson to learn","moonglade","nighthaven","thunder bluff","turak runetotem"},ang={["class:Druid"]="Den här riten markerar övergången från överlevnad på land till verklig elementär mångsidighet och öppnar vägen till att bemästra andning och rörelse under vatten.",["faction:Horde"]="Trots sin lojalitet mot Horde måste tauren-druider respektera Moonglades heliga neutralitet och vandra sida vid sida med nattalver under Cenarius gemensamma trädkrona.",["race:Tauren"]="Uppdraget visar det starka bandet mellan Thunder Bluffs tauren-druider och det större Cenarion-brödraskapet i Moonglade."},sec={{t="Djupens mästerskap",b="När en druid har fått rå fysisk styrka genom björnen riktas studierna mot anpassningsförmåga. Azeroths vattenvägar rymmer faror för resenärer som håller sig på land, och kräver en form lämpad för kalla djup och tryckande strömmar. Turak Runetotem håller sina elever under noggrann uppsikt och väljer bara dem som visat sin hängivenhet till naturen innan han skickar dem norrut för att studera vattenformen."},{t="Vägen till Nighthaven",b="Eftersom vattenförvandling kräver djup andlig insikt måste de invigda söka vägledning utanför Mulgore. Turak ber sina elever resa till Moonglade, den heliga fristaden under Mount Hyjal. Där, i Nighthavens fridfulla tillflykt, välkomnar Cenarion Circles uråldriga nattalvsmentorer sina tauren-bröder och -systrar och överbryggar fraktionskonflikter för att bevara Cenarius gemensamma läror."},{t="De två prövningarna",b="Att nå Dendrite Starblaze i Nighthaven är bara början. Nattalvsäldsten varnar för att mästerskap över vattnet inte kan ges bort, utan måste förtjänas genom prövningar. Han säger att två hårda prov väntar: ett som testar uthållighet och självbehärskning under arbete i vattentryck, och ett annat som kräver djup andlig förståelse för själva vattenformen."}},faq={{q="Vem ger uppdraget A Lesson to Learn?",a="Uppdraget ges av Turak Runetotem, druidtränaren som håller till på Elder Rise i Thunder Bluff. När en invigd har fått tillräcklig erfarenhet skickar han dem för att söka avancerad träning.",al={"vem startar a lesson to learn","var får jag a lesson to learn","turak runetotem uppdrag"}},{q="Vart måste jag gå för att slutföra uppdraget?",a="Du måste resa till byn Nighthaven, som ligger inbäddad i Moonglades heliga skog, och tala med Dendrite Starblaze från Cenarion Circle.",al={"var lämnar jag in a lesson to learn","dendrite starblaze plats","var ligger nighthaven"}},{q="Vilken förmåga leder den här uppdragskedjan till?",a="Det här uppdraget är det första steget i uppdragskedjan som belönar druider med Aquatic Form, vilket ger snabb simning under vatten och förmågan att andas under ytan utan tidsgräns.",al={"vilken form ger detta","aquatic form uppdrag","varför göra detta uppdrag"}},{q="Varför går tauren-druider till en nattalv för att få träning?",a="Cenarion Circle är ett neutralt brödraskap som ägnar sig åt Cenarius och naturens bevarande. I Moonglade läggs de politiska spänningarna mellan Horde och Alliance åt sidan, så att nattalver och tauren kan lära sig de heliga konsterna tillsammans.",al={"varför moonglade","varför dendrite starblaze","cenarion circle tauren"}},{q="Vilka prövningar talar Dendrite Starblaze om?",a="Dendrite förklarar att du måste klara två särskilda utmaningar: en som prövar din fysiska självbehärskning när du arbetar under vattentryck, och en annan som prövar din andliga beslutsamhet att förstå själva formen.",al={"vilka är de två prövningarna","dendrites prov","vattenformens prövningar"}},{q="Hur tar sig en druid till Moonglade vid det här laget?",a="Druider har ett medfött andligt band som ger dem besvärjelsen Teleport: Moonglade. Den låter dem förflytta sig direkt från var som helst i Azeroth till den fridfulla byn Nighthaven.",al={"hur tar man sig till moonglade","teleport till moonglade","ta sig till nighthaven"}}},fx={["055244fc"]={q="Varför måste jag själv genomgå den här träningen?",a="Förmågan att skifta skepnad är inget som kan ges eller utföras av någon annan. Varje druid måste själv bevisa sin andliga styrka och fysiska uthållighet inför Cenarion Circle för att ta emot Cenarius välsignelse och förtjäna den akvatiska aspekten.",al={"varför måste jag göra prövningarna","varför skicka mig till moonglade","varför jag i en läxa att lära"}},b1c6f6a1={q="Varför skickar Turak Runetotem mig till Moonglade?",a="Turak Runetotem har följt din utveckling som naturens beskyddare och tror att du är redo att gå vidare på din druidiska väg. Han skickar dig till Moonglade så att du kan samtala med Cenarion Circle och lära dig den djuraspekt som Cenarius skänkt, den som ger makt över vattnet.",al={"varför skickar turak mig","turak runetetotems motiv","varför en läxa att lära"}}},fp="17,180,21.270.0,22.322.0,15.286.0,38.155.0,39.95.0,43.116.0,52.206.0,45.172.0,47.132.0"}
P.entries["quest:270"] = {n="The Doomed Fleet",s="The Doomed Fleet är en färd norrut som Bishop Farthing skickar från Cathedral of Light i Stormwind. För att finna ett sätt att besegra den mäktige nekromantikern Morbent Fel skickas hjältar genom Khaz Modan till de drunknade vraken utanför Wetlands kust.",h="The Doomed Fleet är en färd norrut som Bishop Farthing skickar från Cathedral of Light i Stormwind.",kw={"bishop farthing","the doomed fleet","glorin steelbrow","kul tiras","lightforge iron","menethil harbor","morbent fel","tredje flottan","wetlands"},ang={["class:Paladin"]="Att söka helig metall för att slå ned en ohelig nekromantiker visar paladinens uppgift: att rena mörkret med vapen välsignade av Ljuset.",["class:Priest"]="Genom att följa Bishop Farthings vägledning får präster direkt tillgång till kyrkans uråldriga kunskap om välsignade reliker och helgade malmer.",["faction:Alliance"]="Det här uppdraget visar hur långt Alliansens nätverk sträcker sig och knyter samman isolerade människobyar i söder med dvärghamnar och uråldriga sjövägar.",["profession:Blacksmithing"]="Smeder uppskattar säkert den sällsynta historien om Lightforge Iron, en metall genomsyrad av tro som kräver mästerligt hantverk för att formas."},sec={{t="Ett vapen av helig sanning",b="Vanligt stål har visat sig verkningslöst mot de mörka skydd som omger Morbent Fel vid hans tillhåll på Forlorn Rowe. För att tränga igenom sådana nekromantiska försvar säger Bishop Farthing åt äventyrarna att de måste smida ett vapen bundet till det heliga Ljuset. Nyckelkomponenten är Lightforge Iron, en sällsynt och välsignad metall vars slag bär helig sanning och skär igenom trolldomsskydd som vanliga klingor inte rår på."},{t="Tredje flottans vrak",b="Tyvärr finns det inget förråd av Lightforge Iron i belägrade Duskwood. Farthing minns att Kul Tiras tredje flotta för många år sedan förliste längs Wetlands förrädiska kust, norr om Ironforge. Ombord på en av de sjunkna galeonerna fanns en last av den dyrbara malmen. Äventyrarna måste resa hela vägen till Menethil Harbor för att rådfråga Glorin Steelbrow, en dvärgkontakt som känner träskmarkerna och deras skeppsvrak bäst."}},faq={{q="Varför måste jag resa hela vägen till Wetlands?",a="Morbent Fels mörka förtrollningar skyddar honom mot vanliga angrepp. Bishop Farthing vet att bara ett vapen smitt av heligt Lightforge Iron kan skingra skydden, och den enda kända lasten finns bland Kul Tiras tredje flottas vrak utanför Menethil Harbor.",al={"varför resa till wetlands","varför menethil harbor","resa till wetlands"}},{q="Vem är Morbent Fel?",a="Morbent Fel är en illavarslande nekromantiker som bor på Forlorn Rowe i Duskwood. Hans trolldom har drivit på en stor del av de odödas uppror som plågar trakten, så hans nederlag är avgörande för Darkshires överlevnad.",al={"morbent fel identitet","vem är nekromantikern","nekromantiker i duskwood"}},{q="Vem är Glorin Steelbrow?",a="Glorin Steelbrow är en dvärg stationerad vid Menethil Harbor i Wetlands. Han är en allierad till Church of the Holy Light och har djup kunskap om kusten, skeppsvraken och bärgningsarbetet i träskmarkerna.",al={"vem är steelbrow","steelbrows roll"}},{q="Vad är Lightforge Iron?",a="Lightforge Iron är en särskilt välsignad metall som prästerskapet värdesätter högt. Vapen smidda av den slår med helig kraft och kan skingra eller genomborra mörka sköldar och nekromantiska förbannelser som vanligt järn inte rår på.",al={"vad gör lightforge iron","lightforge-metall","välsignat järn"}},{q="Vad hände med Kul Tiras tredje flotta?",a="För många år sedan förliste Kul Tiras tredje flotta längs Wetlands karga, sumpiga kust. Skroven ligger fortfarande under vatten utanför kusten, med förlorad last ombord och drunknade sjömän och vattenlevande rovdjur som försvarar dem.",al={"tredje flottans öde","kul tiras skepp i wetlands","hur sjönk skeppen"}},{q="Blir det någon strid direkt i det här uppdraget?",a="Den här delen av uppdraget är helt och hållet ett kuriruppdrag. Det kräver en lång resa från Duskwood, genom kungariket Stormwind och Khaz Modan, ända till Menethil Harbor för att ta kontakt med Glorin Steelbrow.",al={"blir det strid","bara ett reseuppdrag"}}},fx={ade8f412={q="Varför skickar Bishop Farthing dig på det här uppdraget?",a="Bishop Farthing vet att nekromantikern Morbent Fel utgör ett dödligt hot mot Duskwood och inte kan besegras med vanliga medel. För att besegra en sådan mörk kraft behöver du ett vapen välsignat med helig kraft och smitt av heligt Lightforge-järn. Eftersom järnet gick förlorat till havs med Kul Tiras tredje flotta skickar Farthing dig norrut till Menethil Harbor för att rådfråga sin dvärgiske bekant Glorin Steelbrow, i hopp om att återta den sjunkna metallen.",al={"varför vill bishop farthing ha lightforge-järn","farthings motiv med den dödsdömda flottan","varför hitta den dödsdömda flottan"}},a631378f={q="Varför kan inte Bishop Farthing eller Night Watch själva ta hand om Morbent Fel?",a="Night Watch är farligt hårt anstridda bara med att hålla Duskwoods gränser från att falla samman under tyngden av tanklösa odöda, worgen och spindlar. Bishop Farthing måste sköta sina plikter vid Cathedral of Light i Stormwind, och varken han eller den lokala milisen har tid eller manskap över för en lång färd genom kontinenten till Wetlands. Som självständig resenär har du friheten och beslutsamheten att söka efter det förlorade järnet och möta nekromantikern direkt.",al={"varför skickas jag på den dödsdömda flottan","varför ger sig inte night watch av","varför behöver bishop farthing mig"}}},fp="16,181,22.267.0,28.354.0,52.244.0,19.198.0,24.176.0,24.197.0,46.194.0,48.159.0"}
P.entries["quest:272"] = {n="Trial of the Sea Lion",s="Trial of the Sea Lion är en helig rit som druider genomgår i Moonglade på vägen mot att bemästra Aquatic Form. De invigda får i uppgift att återfinna två utspridda halvor av ett hängsmycke, som förkroppsligar sjölejonets smidighet och uthållighet, och sedan förena dem vid Shrine of Remulos. Genom att skapa det fullständiga Pendant of the Sea Lion bevisar druiden sin samklang med vattnet och förbereder sig på att kanalisera varelsens ande.",h="Trial of the Sea Lion är en helig rit som druider genomgår i Moonglade på vägen mot att bemästra Aquatic Form.",kw={"aquatic form","dendrite starblaze","half pendant of aquatic agility","half pendant of aquatic endurance","moonglade","nighthaven","pendant of the sea lion","shrine of remulos","trial of the sea lion"},ang={["class:Druid"]="Denna prövning är en övergångsrit enbart för druider. Den testar deras andliga mognad och balans innan de får umgås med vattenandar och anta sjölejonets skepnad.",["race:NightElf"]="Som sedan länge Moonglades och Cenarion Circles väktare vördar night elf-druiderna Dendrite Starblazes läror och den heliga marken kring Shrine of Remulos.",["race:Tauren"]="För tauren-druider som nyligen välkomnats till Cenarion Circle stärker prövningen i Moonglade deras gemenskap med naturandar och fördjupar banden till deras night elf-mentorer."},sec={{t="Vägen till Aquatic Form",b="För att kunna färdas i Azeroths djupa vatten måste druider som är under utbildning genomgå prövningar för att stämma sig med naturen i Moonglades heliga lund. Trial of the Sea Lion är den andra av dessa viktiga riter, efter tidigare förberedelser i deras andliga träning. Under ledning av Dendrite Starblaze i byn Nighthaven utmanar prövningen druiderna att förstå hur två olika egenskaper, graciös snabbhet och seg uthållighet, måste hållas i balans. Utan att förstå båda sidorna av sjölejonets natur kan en invigd inte hoppas kunna bemästra dess form eller stå emot farorna i havets djup."},{t="Smidighet och uthållighet",b="Prövningens fysiska och andliga kärna är att sätta samman Pendant of the Sea Lion av två åtskilda halvor. Den ena halvan kanaliserar sjölejonets smidighet och återspeglar dess förmåga att glida obehindrat genom strida strömmar. Den andra halvan hämtar kraft från varelsens gränslösa uthållighet och står för styrkan som krävs för att dyka länge i iskallt vatten utan att ge vika. De invigda måste rådfråga Moonglades invånare för att få ledtrådar om var de utspridda relikerna finns runt om i världen. På så sätt visar de både sin uppfinningsrikedom och sin vilja att söka vägledning i sin heliga fristad."},{t="Shrine of Remulos",b="När båda relikerna har säkrats måste den invigde föra dem nära Shrine of Remulos för att återförena dem till en enda talisman. Väktarens helgedom erbjuder de lugna och kraftfulla energier som krävs för att förena smidighetens och uthållighetens skilda krafter. När den återställda Pendant of the Sea Lion överlämnas till Dendrite Starblaze i Nighthaven är prövningen fullbordad. Med detta tecken i sin hand visar druiden att den är redo att anta sjölejonets skepnad och slutligen väcka sin vattenform."}},faq={{q="Vad är Trial of the Sea Lion?",a="Trial of the Sea Lion är ett avgörande druiduppdrag i Moonglade som prövar den invigdes förståelse för vattenlevande liv. Druiden måste hitta två separata halvor av ett hängsmycke som står för smidighet och uthållighet, sätta samman dem vid Shrine of Remulos och överlämna den färdiga talismanen till Dendrite Starblaze. Att klara prövningen är ett nödvändigt steg mot att låsa upp druidens Aquatic Form.",al={"uppdraget trial of the sea lion","vad är trial of the sea lion","sjölejonets prövning"}},{q="Vem ger uppdraget Trial of the Sea Lion?",a="Väktaren Tajarri vid Shrine of Remulos i Moonglade ger prövningen. De invigda söker vägledning hos lokalbefolkningen, förenar halvorna nära helgedomen och tar sedan den färdiga Pendant of the Sea Lion till Dendrite Starblaze, en night elf-druid i byn Nighthaven.",al={"vem ger trial of the sea lion","var börjar trial of the sea lion","uppdragsgivare för trial of the sea lion"}},{q="Vad står de två halvorna av hängsmycket för?",a="De två halvorna av hängsmycket står för de dubbla egenskaper som kännetecknar sjölejonets skepnad: smidighet och uthållighet. Den ena halvan förkroppsligar den graciösa snabbhet som krävs för att glida smidigt genom djupt vatten, medan den andra står för uthålligheten och motståndskraften som behövs för långa färder under ytan. Druider måste respektera och förkroppsliga båda egenskaperna i lika hög grad för att bemästra sina skepnadskonster.",al={"vad är halvorna av hängsmycket","halvorna av hängsmyckets betydelse","halvorna för smidighet och uthållighet"}},{q="Var finns halvorna av hängsmycket?",a="För att få veta var Half Pendant of Aquatic Agility och Half Pendant of Aquatic Endurance finns gömda måste de invigda tala med Moonglades invånare. De lokala druiderna och byborna ger viktiga ledtrådar om de avlägsna vatten där halvorna gick förlorade eller gömdes.",al={"hur hittar man halvorna av hängsmycket","var hittar man halvorna av hängsmycket","var finns halvorna av pendant of the sea lion"}},{q="Var sätter man samman Pendant of the Sea Lion?",a="Halvorna kan inte sättas samman var som helst. De måste förenas alldeles intill Shrine of Remulos i Moonglade. Den heliga kraften från väktaren Remulos helgedom ger den andliga resonans som krävs för att förena smidighetens och uthållighetens krafter till en enda fungerande talisman.",al={"hur förenar man halvorna av hängsmycket","var förenar man halvorna av hängsmycket","var finns pendant vid shrine of remulos"}},{q="Varför måste druider balansera smidighet och uthållighet?",a="Enligt Dendrite Starblaze fungerar varken smidighet eller uthållighet effektivt på egen hand under vattnet. Den som rör sig snabbt utan uthållighet blir snabbt utmattad, medan den som orkar länge utan snabbhet blir hjälplös mot starka strömmar. Att förena båda egenskaperna är avgörande för alla druider som vill förkroppsliga sjölejonets ande fullt ut.",al={"varför smidighet och uthållighet","sjölejonets egenskaper för druider","sjölejonets prövning betydelse"}},{q="Vad får man när prövningen är avklarad?",a="När Trial of the Sea Lion är avklarad får du den återställda Pendant of the Sea Lion och genomför den viktiga prövning som krävs för att få Aquatic Form. Genom att visa att den invigde behärskar lärdomarna om smidighet och uthållighet lägger den grunden för att kunna skifta skepnad till en varelse som kan andas och simma snabbt under vattnet.",al={"vad får man från trial of the sea lion","belöning från sjölejonets prövning","ger detta aquatic form"}}},fp="21,210,24.398.0,21.373.0,21.372.0,34.228.0,42.224.0,41.281.0,37.254.0,50.144.0,46.274.0,39.259.0"}
P.entries["quest:273"] = {n="Resupplying the Excavation",s="Resupplying the Excavation är ett Alliance-uppdrag i Loch Modan där äventyrare söker efter en krutleverans avsedd för Ironband's Excavation Site. Jern Hornhelm skickar ut resenären för att hinna ikapp packlaget, vars rutt följer Lochs strand.",h="Resupplying the Excavation är ett Alliance-uppdrag i Loch Modan där äventyrare söker efter en krutleverans...",kw={"sprängkrut","huldar","ironband","jern hornhelm","loch modan","miran","resupplying the excavation","saean","thelsamar"},ang={["profession:Mining"]="Det är farligt nog att frakta explosivt sprängkrut över oländig terräng utan förräderi. Den här leveransen är avgörande för utgrävarna i söder.",["race:Dwarf"]="För Bronzebeard-dvärgarna hjälper skyddet av sprängkrutsleveransen till att hålla Ironbands arbete försörjt trots farorna på vägarna i Loch Modan."},sec={{t="Tung last längs stranden",b="Ironband's Excavation Site i södra Loch Modan behöver en jämn tillförsel av sprängkrut för att ta sig igenom den hårda berggrunden. Efter att sprängkrut levererats till Thelsamar ordnade den lokala kvartermästaren Jern Hornhelm så att tre dvärgar, Huldar, Miran och Saean, skulle frakta de explosiva tunnorna söderut längs vägen vid sjön. Den tunga lasten gjorde att följet rörde sig långsamt, vilket gav resenärer i Thelsamar en chans att hinna ikapp och hjälpa till längs vägen."},{t="Förräderi i skuggorna",b="När du hinner ikapp packvagnen längs den södra vägen möts du av kaos i stället för en vanlig leverans. Dark Iron-dvärgar har överfallit lasten. De försöker aktivt sabotera Bronzebeard-expeditionens arkeologiska arbete. Än värre än själva räden var det bittra förräderi som avslöjades: Saean, en arbetare som Huldar hade litat på och arbetat med i nästan ett år, visade sig sympatisera med Dark Iron och ha hjälpt till att organisera överfallet."}},faq={{q="Vem ger uppdraget Resupplying the Excavation?",a="Jern Hornhelm ger dig uppdraget i Thelsamar efter att du lämnat sprängkrutet till honom. Han ber dig följa vägen söderut längs Loch för att hinna ikapp försörjningslaget.",al={"vem ger resupplying the excavation","vem startar resupplying the excavation","var börjar resupplying the excavation"}},{q="Var hittar man Huldar och vagnen?",a="Huldar och vagnen finns söder om Thelsamar, längs vägen som följer Lochs västra och södra strand mot Ironband's Excavation Site.",al={"hitta huldar","huldars plats","var finns vagnen i loch modan"}},{q="Varför skickas sprängkrut till Ironband?",a="Prospector Ironband och hans lag gräver efter forntida reliker vid utgrävningsplatsen i söder. De behöver sprängkrut för att slå sönder tung sten och spränga sig igenom lager under marken.",al={"varför behöver ironband krut","ironbands sprängkrut","varför sprängkrut till utgrävningen"}},{q="Vem överföll Huldars vagn?",a="Jern räknar med att försörjningslaget följer den vanliga vägen söder om Thelsamar, längs Loch. Vad som har hänt med vagnen avslöjas när du når Huldar.",al={"vem anföll vagnen","vagnöverfall i loch modan","vem anföll huldar"}},{q="Vilken roll spelade Saean i attacken?",a="Saean färdas med Huldar och Miran för att transportera de tunga tunnorna med sprängkrut. Hans roll i händelserna längs vägen avslöjas när du hinner ikapp laget.",al={"vem är saean","saeans förräderi","vad gjorde saean"}},{q="Vilket uppdrag kommer efter att du hittat Huldar?",a="När du talar med Huldar är den här delen av resan avklarad. Hans berättelse om leveransen ger dig nästa ledtråd.",al={"uppdrag efter resupplying the excavation","uppdrag efter huldar"}}},fx={["72005fbc"]={q="Varför skickar Jern Hornhelm dig efter Huldar?",a="Jern Hornhelm inser att du kom fram för att leverera sprängpulver strax efter att Huldar och hans besättning gav sig av med den tunga vagnen mot Ironband's Excavation. Eftersom vagnen är tungt lastad med tunnor vet Jern att de färdas långsamt längs den södra vägen som följer Loch. Han skickar dig i förväg för att hinna ikapp dem, så att du kan hjälpa till med den viktiga leveransen.",al={"jern hornhelms motiv","varför hinna ikapp huldar","varför skickar jern dig"}}},fp="26,172,29.342.0,24.247.1,48.162.0,40.143.0,42.169.0,28.140.1,39.141.1,43.119.1"}
P.entries["quest:274"] = {n="A Dark Threat Looms",s="Efter att misstänkt pulver upptäckts vid Stonewrought Dam identifierar Ashlan Stonesmirk i Dun Modr ämnet som instabilt Seaforium. Pulvret kan orsaka katastrofal förödelse om det kommer i kontakt med vatten och utgör en omedelbar fara för trakten och det närbelägna dvärgariket. Stonesmirk tillverkar en desarmerande kolloid och skickar bud till Chief Engineer Hinderweir VII för att avvärja katastrofen.",h="Efter att misstänkt pulver upptäckts vid Stonewrought Dam identifierar Ashlan Stonesmirk i Dun Modr ämnet som...",kw={"ashlan stonesmirk","sprängpulver","chief engineer hinderweir vii","ett mörkt hot tornar upp sig","disarming colloid","ironforge","seaforium","wetlands"},ang={["faction:Alliance"]="Alliansens försvarare måste agera snabbt för att hjälpa Chief Engineer Hinderweir VII och säkra låglandet innan fiendens sabotörer krossar strategisk infrastruktur.",["profession:Engineering"]="Ingenjörer känner igen Seaforium som en ytterst kraftfull och flyktig förening som kräver varsam hantering och precisa kemiska motåtgärder för att undvika massiva tryckvågor.",["race:Dwarf"]="För dvärgarna i Khaz Modan är tanken på sabotörer med explosivt, flyktigt Seaforium nära porten till Dun Morogh och Ironforge ett existentiellt hot."},sec={{t="Ett flyktigt fynd",b="När Ashlan Stonesmirk undersöker proverna från Stonewrought Dam känner hon genast igen Seaforiums typiska silverkristaller och tydliga lukt. Seaforium är inert i torra förhållanden, men reagerar våldsamt med fukt – en skrämmande insikt när dammen håller tillbaka vattnet i Loch Modan. Ashlan varnar för att en okontrollerad explosion från en sådan förening kan spränga Ironforge ut ur berget."},{t="En kamp mot klockan",b="För att motverka det flyktiga sprängämnet tillverkar Stonesmirk en särskild desarmerande kolloid. Reaktionen kan neutraliseras med en specifik kemisk blandning: kolloiden tillsammans med Lurker Venom, krossad Mo'grosh Crystal och tårar från en crocolisk. Tiden är knapp, och Chief Engineer Hinderweir VII måste varnas genast innan fukt utlöser katastrofen."}},faq={{q="Vilket slags sprängämne hittades vid dammen?",a="Ashlan Stonesmirk identifierar det mystiska ämnet som Seaforium-pulver, som känns igen på sina tydliga silverkristaller och sin skarpa kemiska lukt.",al={"vad är det här för pulver","vad är pulvret","seaforium-pulver"}},{q="Varför är Seaforium så farligt här?",a="Seaforium är relativt ofarligt så länge det hålls torrt, men utlöser en katastrofal explosion när det kommer i kontakt med vatten. Därför är Stonewrought Dam, som håller tillbaka vattnet i Loch Modan, en ytterst farlig plats för ämnet.",al={"varför är seaforium farligt","vad får seaforium att explodera"}},{q="Vem är Ashlan Stonesmirk?",a="Ashlan Stonesmirk är en dvärgisk specialist i Alliansen som bor i Wetlands och har den ingenjörskunskap och kemiska expertis som krävs för att analysera mystiska pulver och tillverka neutraliseringsmedel.",al={"vem är ashlan","ashlan stonesmirks identitet"}},{q="Vem är Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII ansvarar för tekniska frågor och försvarsfrågor i trakten. Han arbetar från Stonewrought Dam i Loch Modan med att underhålla och skydda dvärgarnas infrastruktur.",al={"vem är hinderweir","chief engineer hinderweir"}},{q="Hur kan Seaforium neutraliseras?",a="För att desarmera den kemiska reaktionen måste Ashlans desarmerande kolloid blandas med tre sällsynta lokala ingredienser: Lurker Venom, en krossad Mo'grosh Crystal och en Crocolisk Tear.",al={"hur desarmerar man seaforium","recept för att desarmera seaforium","recept på desarmerande kolloid"}},{q="Vilken fara hotar Ironforge?",a="Ashlan varnar för att en okontrollerad detonation av sprängämnet i de omgivande bergsområdena kan orsaka förödande seismiska skador och spränga Ironforge rakt ut ur berget.",al={"är ironforge i fara","hur hotas ironforge"}}},fx={["7e9e3f07"]={q="Varför vill Ashlan Stonesmirk att det här blir gjort?",a="Ashlan insåg att det mystiska ämnet inte är vanligt sprängpulver, utan instabilt Seaforium. När Seaforium kommer i kontakt med vatten kan dess explosiva kraft få hela berg att rasa. Ashlan måste genast varna Chief Engineer Hinderweir VII, så att dvärgarnas ingenjörer hinner förbereda en neutraliserande lösning innan den flyktiga blandningen detonerar.",al={"varför skickar ashlan dig","ashlans motiv","varför varna hinderweir"}}},fp="19,208,20.261.0,16.261.1,44.122.0,35.210.0,25.179.0,37.163.0,37.142.0,32.148.0"}
P.entries["quest:2741"] = {n="The Super Egg-O-Matic",s="Curgle Cranklehops senaste uppfinning är en imponerande maskin, och den hostar och hackar vilt när du kommer fram till kontrollpanelen. Hippogryphägg placeras i den.",h="Curgle Cranklehops senaste uppfinning är en imponerande maskin, och den hostar och hackar vilt när du kommer...",kw={"curgle cranklehop","egg-o-matic","eggometer","feralas","hippogryphägg","tanaris"},sec={{t="En maskin av Curgle Cranklehop",b="Curgle Cranklehops senaste uppfinning är en imponerande syn. När du går fram till kontrollpanelen hostar och hackar den vilt. Den är byggd för att ta emot ett hippogryphägg, och äggen finns i bergen i södra Feralas, kring Ruins of Isildien."},{t="Vad maskinen gör",b="Lägg ett hippogryphägg i maskinen, så svarar den med en serie pip och märkliga mekaniska ljud. Dess Eggometer väger och mäter ägget och förpackar det sedan, allt på nolltid. Resultatet är en Egg Crate, som innehåller ett ägg av något slag."}},faq={{q="Vem byggde Super Egg-O-Matic?",a="Curgle Cranklehop, som har skapat sin senaste uppfinning.",al={"vem gjorde egg-o-matic","egg-o-matics skapare","curgle cranklehop uppfinning"}},{q="Vad behöver maskinen för att fungera?",a="Ett hippogryphägg, som du lägger i maskinen.",al={"vad ska jag ge egg-o-matic","föremål som egg-o-matic behöver","maskin för hippogryphägg"}},{q="Var hittar du hippogryphägg?",a="Uppe i bergen i södra Feralas, kring Ruins of Isildien.",al={"hippogryphägg plats","var hittar man hippogryphägg","var finns äggen i feralas"}}},fp="21,158,30.256.0,21.259.1,32.48.0,38.51.0,34.70.0"}
P.entries["quest:2742"] = {n="Rin'ji is Trapped!",s="Rin'ji, en troll, har tappat en yxa och tagits till fånga i Quel'Danil Lodge. Rin'ji ber om hjälp att fly och nämner en hemlighet vid Overlook Cliffs.",h="Rin'ji, en troll, har tappat en yxa och tagits till fånga i Quel'Danil Lodge.",kw={"fånge","eskort","the hinterlands","overlook cliffs","quel'danil","rin'ji","tavla"},sec={{t="En bön om att fly",b="Rin'ji hålls fången i Quel'Danil Lodge och är mycket rädd. Yxan är borta, och Rin'ji ber förbipasserande om hjälp att komma undan. Rin'ji vet att många ogillar troll, men erbjuder något i gengäld till den som hjälper. En hemlighet finns gömd vid Overlook Cliffs."},{t="Vid flyktens slut",b="Där väntar en trolltavla täckt av märkliga tecken. Inget av det som står skrivet går att tyda."}},faq={{q="Vem är Rin'ji?",a="Rin'ji är en troll som tappade en yxa och tillfångatogs i Quel'Danil Lodge i The Hinterlands. Rin'ji talar om sig själv i tredje person och ber om hjälp att fly.",al={"rinji","vem är trollet i quel'danil","vem är rin'ji"}},{q="Var hålls Rin'ji fången?",a="Rin'ji hålls fången i Quel'Danil Lodge i The Hinterlands.",al={"var är rin'ji","rinjis plats","quel'danil-bur"}},{q="Vad erbjuder Rin'ji i utbyte mot hjälp?",a="Rin'ji har något åt den som hjälper och säger att en hemlighet är gömd vid The Overlook.",al={"vad är rin'jis hemlighet","rinjis belöning","vad finns vid overlook cliffs"}}},fp="18,239,17.269.0,24.103.1,14.165.0,29.54.0,32.92.0"}
P.entries["quest:2745"] = {n="Infiltrating the Castle",s="Ostmästaren och underrättelsemäklaren Elling Trias skickar dig till Stormwinds kungliga säte, Stormwind Keep. Ditt mål är att möta hans kollega Tyrion, som i flera veckor har bevakat den korrupte adelsmannen Lord Gregor Lescovar från borgens trädgårdar.",h="Ostmästaren och underrättelsemäklaren Elling Trias skickar dig till Stormwinds kungliga säte, Stormwind Keep.",kw={"ostbutik","defias","elling trias","infiltrera borgen","lescovar","stormwind keep","tyrion"},ang={["class:Rogue"]="Att infiltrera den mänskliga adelns säte för att hjälpa två erfarna underjordiska agenter visar vilken lågmäld men dödlig yrkesskicklighet som krävs för att skydda Stormwind från skuggorna i det egna hovet.",["faction:Alliance"]="Med King Varian försvunnen har kungariket inte råd med förräderi i sin högsta lagstiftande kammare. Att röja konspiratörer i Keep är avgörande för att hålla riket stabilt.",["race:Gnome"]="Att se Tyrion bedriva en intensiv, långvarig hemlig spaningsoperation i Stormwind Keep visar att gnomisk uppfinningsrikedom sträcker sig långt bortom maskiner och in i spionage med mycket på spel."},sec={{t="En fråga utanför lagen",b="När du tar med dina upptäckter till Elling Trias i hans ostbutik i Trade District inser han genast hur allvarligt Defias-hotet inne i rikets styre är. Lagliga vägar räcker inte för att avslöja eller straffa någon som Lord Gregor Lescovar, med så djupa rötter och så starkt beskydd. Trias erbjuder en farlig väg framåt: att skipa rättvisa utanför lagen innanför murarna till Stormwind Keep och för alltid kapa konspirationens band."},{t="Ögon bland buskarna",b="Trias arbetar inte ensam i de höga salarna. I flera veckor har en agent vid namn Tyrion, en slug gnom skicklig på att hålla sig dold, spanat på borgens gårdar och kungliga trädgårdar. Tyrion har följt Lescovars rörelser och noterat vilka som besöker hans gemak och när förrädaren möter sina hemliga kontakter inom Defias. Att nå Tyrion utan att väcka Royal Guards misstankar är nästa avgörande länk i kedjan."},{t="Förräderi vid hovet",b="Att en högt uppsatt adelsman som Lescovar samarbetar direkt med Defias-mördare som Marzon the Silent Blade visar hur rutten Stormwinds politiska kärna har blivit sedan King Varian Wrynn försvann. Hovets adelsmän manipulerar händelserna inifrån, medan laglösa pressar rikets gränser från Westfall och Redridge Mountains. Ett angrepp mot Lescovar är ett försök att skära bort en varande cancersvulst innan kungariket faller samman helt."}},faq={{q="Varför vill Elling Trias att det här ska skötas utanför lagen?",a="Lord Lescovar har enormt inflytande och stor rikedom i House of Nobles. Vanliga rättsliga anklagelser mot en högt uppsatt lord utan obestridliga, politiskt förödande bevis skulle troligen leda till att bevisen tystades ner och visselblåsarna avrättades. Trias förstår att direkt, hemlig handling är det enda säkra sättet att oskadliggöra hotet.",al={"varför utanför lagen","trias rättvisa utanför lagen","varför vigilant"}},{q="Var gömmer sig Tyrion?",a="Tyrion håller sig gömd i Stormwind Keeps kungliga trädgårdar, strax till vänster om gården när du har gått genom huvudporten. Han ligger på lur i buskarna för att hålla Lord Lescovars gemak under uppsikt utan att larma vakterna.",al={"var är tyrion","hitta tyrion","tyrions plats"}},{q="Vem är Tyrion?",a="Tyrion är en hemlig agent och betrodd medarbetare till Elling Trias. I flera veckor har han spanat på Stormwind Keep för att bevaka Lord Gregor Lescovar och kartlägga hans hemliga kontakter inom Defias.",al={"vem är tyrion","tyrion gnom","trias vän"}},{q="Vem är Lord Lescovar?",a="Lord Gregor Lescovar är en framstående adelsman från Stormwind som i hemlighet samarbetar med Defias Brotherhood. Han är deras högt placerade infiltratör och saboterar kungariket inifrån det kungliga hovet.",al={"lord lescovar","vem är lescovar","lescovar defias"}},{q="Vem är Marzon?",a="Marzon, känd som the Silent Blade, är en elitmördare inom Defias som samarbetar direkt med Lord Lescovar för att samordna attacker och mord åt Brotherhood.",al={"marzon","marzon the silent blade","the silent blade"}},{q="Varför oroar sig Tyrion för sitt rykte?",a="Utöver risken att röja sin täckmantel under hemlig spaning klagar Tyrion sarkastiskt över hur misstänkt och opassande det verkar när tungt beväpnade äventyrare håller till bredvid honom bland de kungliga buskarna, mitt framför näsan på borgens vakter.",al={"tyrion gömmer sig i buskarna","rykte bland buskarna"}}},fx={ae2213ef={q="Vem skickas du efter i Stormwind Castle?",a="Elling Trias skickar dig för att ta itu med Lord Gregor Lescovar och hans bundsförvant Marzon. Lescovar är en adelsman som verkar mitt inne i Stormwind Keep och misstänks ha förrädiska band, medan Marzon företräder de farliga sammansvurna utanför slottets murar. Trias och hans kontakt Tyrion vill att båda männen oskadliggörs innan deras planer kan hota riket.",al={"vem är målet","vem är målet i infiltrera slottet","vilka är lescovar och marzon"}},["7d59c2b3"]={q="Varför skickar Elling Trias dig i stället för att använda Stormwinds stadsvakt?",a="Lord Lescovar är en högt uppsatt adelsman i Stormwind Keep, så en officiell anklagelse är politiskt omöjlig utan obestridliga bevis. Stadsvakten lyder under hovet, där adeln har inflytande, och om myndigheterna underrättas skulle Lescovar troligen varnas eller ärendet begravas i byråkrati. Trias förlitar sig på en självständig äventyrare som kan smyga in, möta Tyrion och skipa rättvisa utan att varna de sammansvurna.",al={"varför skicka mig","varför inte säga till vakterna","varför inte stormwinds vakter"}}},fp="23,152,24.337.0,21.349.0,20.354.1,56.312.0,23.203.0,14.185.0,21.183.0,14.162.1,43.223.0"}
P.entries["quest:2746"] = {n="Items of Some Consequence",s="Tyrion samlar siden och äpplen åt en spion i Stormwind Keep. Agenten behöver materialet för att förklä Spybot och skicka den förbi kungens vakter för att avlyssna Lord Lescovar.",h="Tyrion samlar siden och äpplen åt en spion i Stormwind Keep.",kw={"clara","elling trias","infiltrera borgen","lord lescovar","sidentyg","spybot","stormwind keep","the attack","tyrion"},ang={["class:Rogue"]="Som Rogue vet du hur agenter som Tyrion och Elling Trias använder okonventionell övervakning, med underrättelsearbete som sker under näsan på adeln.",["faction:Alliance"]="Som medlem av Alliance hjälper du till att skydda den unge King Anduin och Highlord Bolvar Fordragon genom att avslöja korrupta adelsmän som konspirerar med laglösa inne i Stormwind Keep.",["profession:Tailoring"]="Som Tailor vet du att fint siden kan användas till hemliga planer såväl som högtidsklänningar."},sec={{t="En allt snävare tidsplan",b="Elling Trias har tidigarelagt operationen mot Lord Gregor Lescovar. Osthandlaren misstänker att Lescovars planer i Stormwind Keep hotar riket. I borgens trädgårdar går Tyrion med på den snävare tidsplanen, men säger att förklädnaden kräver noggranna förberedelser."},{t="Förklädnadens konst",b="Tyrion planerar att skicka Spybot, en liten mekanisk apparat, förbi borgvakterna för att nå Lescovar inne i borgen. En märklig kvinnlig förklädnad bör väcka mindre misstankar. För att ordna den samlar du äpplen i lagom storlek från Claras fruktträdgård strax utanför stadsmurarna, samt sidenbuntar till marionettens kläder."},{t="Förräderiet avslöjas",b="Tyrion började bevaka Lord Lescovar efter misstänkta spår som knöt adelsmannen till kulten Twilight's Hammer. Nu avslöjar han att Lescovar också samarbetar med konspiratörer i Defias Brotherhood. När förräderiet avslöjats kan Lescovar inte längre stanna vid det kungliga hovet, och Tyrions övervakning blir en fälla riktad mot kungarikets hjärta."}},faq={{q="Varför behöver Tyrion äpplen och siden?",a="Tyrion behöver äpplen och siden för att förklä Spybot till en kvinna så att den kan passera kungens vakter i Stormwind Keep. Sidenet blir kläder, och äpplena ger förklädnaden den form som behövs.",al={"varför äpplen","vad ska äpplena användas till","tyrions förklädnadsmaterial","spybots förklädnad"}},{q="Vem arbetar Tyrion åt?",a="Tyrion samarbetar med Elling Trias, en osthandlare i Trade District som driver sitt eget nätverk av kontakter i Stormwind. Trias säger att operationen bara indirekt gör Mathias Shaw och SI:7 en tjänst.",al={"vem rapporterar tyrion till","tyrions lojalitet","elling trias tyrion"}},{q="Var hittar jag Claras äpplen?",a="Claras fruktträdgård ligger strax utanför Stormwinds stadsportar i norra Elwynn Forest. Du kan plocka färska äpplen runt gården.",al={"claras gård plats","var finns claras äpplen","färska äpplen stormwind"}},{q="Vad misstänkte Tyrion ursprungligen att Lord Lescovar gjorde?",a="Tyrion och Trias misstänkte först att Lord Lescovar hade band till kulten Twilight's Hammer. Senare avslöjade de hans samarbete med Defias Brotherhood, ett grövre förräderi och ett överhängande hot mot kronan.",al={"lescovar twilight hammer","varför utreddes lescovar","tyrion lescovar historia"}},{q="Vad är nästa steg efter att ha lämnat över föremålen?",a="När Spybot har utrustats och skickats in i borgen får du i uppdrag att konfrontera och undanröja konspiratörerna i 'The Attack!'.",al={"vad händer härnäst","efter items of some consequence","nästa uppdrag efter items of some consequence"}},{q="Varför använda en mekanisk spionbot i stället för att smyga in själv?",a="Kungens vakter i Stormwind Keep granskar alla som går in i tronrummet och de privata gårdarna. Förklädd till prästinna kan Spybot passera dem, tala med Lescovar och locka ut honom i trädgården för att träffa Marzon, där ingen känd agent skulle kunna komma nära.",al={"varför använda spybot","varför inte smyga in själv","säkerheten i stormwind keep"}}},fx={["7ec9a91a"]={q="Varför vill Tyrion störta Lord Lescovar?",a="Tyrion och hans bundsförvant Elling Trias har följt efter Lord Lescovar i flera veckor, eftersom de misstänker att han har omstörtande band. De började undersöka ett möjligt samband med kultister i Twilight's Hammer, men upptäckten att Lescovar aktivt konspirerar med Defias Brotherhood gör honom till ett omedelbart och allvarligt hot mot Stormwind. Tyrion tänker avslöja och oskadliggöra honom innan hans förräderi sliter staden i stycken.",al={"varför stoppa lescovar","tyrions motiv","varför utreda lescovar"}},["73f45f0b"]={q="Varför behöver Tyrion hjälp av en utomstående i stället för stadsvakten?",a="Lord Lescovar är en adelsman i Stormwind Keep, så en öppen anklagelse eller direkt ingripande från vakten är omöjligt utan obestridliga bevis. Stormwinds myndigheter kan inte agera på misstankar mot en högt uppsatt adelsman. Tyrion verkar i skuggorna på Master Trias uppdrag och behöver en självständig agent som kan skaffa hemliga förnödenheter och till sist själv ta hand om den farliga, dolda konfrontationen.",al={"varför inte stadsvakten","varför behöver tyrion mig","varför lita på en äventyrare"}}},fp="25,175,21.275.0,23.313.0,18.324.1,43.180.0,26.195.0,31.126.0,58.208.1,51.132.1,62.252.0"}
P.entries["quest:2747"] = {n="An Extraordinary Egg",s="Curgle Cranklehop har sällan sett ett ägg från Feralas i så utomordentligt skick. Sådana ägg är de allra sällsyntaste.",h="Curgle Cranklehop har sällan sett ett ägg från Feralas i så utomordentligt skick.",kw={"curgle cranklehop","extraordinary egg","feralas","super egg-o-matic","tanaris"},sec={{t="En sällsynthet från Feralas",b="Curgle Cranklehop säger att mycket få ägg från Feralas är i utomordentligt skick och att de är de allra sällsyntaste. Ett sådant ägg är vad Curgle letar efter."}},faq={{q="Vem letar efter ett Extraordinary Egg?",a="Curgle Cranklehop, som är uppfinnaren av Super Egg-O-Matic.",al={"vem startar extraordinary egg","vem ger uppdraget extraordinary egg","curgle cranklehop ägg"}},{q="Varifrån kommer dessa extraordinära ägg?",a="De hämtas från Feralas, men mycket få anländer i utomordentligt skick.",al={"plats för extraordinary egg","var hittar man extraordinary egg","ägg från feralas"}},{q="Vad kommer före den här efterlysningen?",a="Den följer efter The Super Egg-O-Matic.",al={"förutsättning för extraordinary egg","uppdragskedja för extraordinary egg","föregående uppdrag för extraordinary egg"}}},fp="20,110,21.174.0,40.64.0,44.76.0,31.33.0"}
P.entries["quest:2748"] = {n="A Fine Egg",s="Curgle Cranklehop talar om Fine Egg, som kan kläckas fri från Gordunni-ogres onda besvärjelser.",h="Curgle Cranklehop talar om Fine Egg, som kan kläckas fri från Gordunni-ogres onda besvärjelser.",kw={"curgle cranklehop","darnassus","fine egg","gordunni","ogrebesvärjelser","super egg-o-matic","tanaris"},sec={{t="Vad som gör det fint",b="Curgle Cranklehop beskriver Fine Egg som ett ägg med god chans att kläckas utan att påverkas av Gordunni-ogres onda besvärjelser, om förhållandena är idealiska."},{t="Vad Curgle gör härnäst",b="Curgle tar ägget och planerar att skicka det till Darnassus, där man hoppas att det snart ska kläckas."}},faq={{q="Vad gör att ett ägg räknas som ett fint ägg?",a="Under idealiska förhållanden kan det kläckas fritt från ondskan som Gordunni-ogres besvärjelser för med sig.",al={"vad är fine egg","fine egg-lore","varför fine egg"}},{q="Vad hände före det här steget?",a="Det följer efter The Super Egg-O-Matic.",al={"förutsättning för fine egg","föregående uppdrag fine egg"}}},fp="10,122,18.163.0,21.98.1,40.90.0,27.33.0"}
P.entries["quest:2749"] = {n="An Ordinary Egg",s="Curgle Cranklehop arbetar med vanliga hippogryphägg, och ungefär hälften kläcks. Curgle sköter om dem och hoppas på tur.",h="Curgle Cranklehop arbetar med vanliga hippogryphägg, och ungefär hälften kläcks.",kw={"curgle cranklehop","feralas","hippogryph","ordinary egg","tanaris","the super egg-o-matic"},sec={{t="Hälften så stor chans",b="Ett vanligt hippogryphägg kläcks bara ungefär hälften av gångerna. Curgle Cranklehop gör sitt bästa för att ta hand om varje ägg, och med lite tur kläcks det."}},faq={{q="Vem är Curgle Cranklehop?",a="Curgle Cranklehop har uppfunnit Super Egg-O-Matic och arbetar med hippogryphäggen som finns i Feralas.",al={"vem är curgle","curgle cranklehop"}},{q="Vad händer med det vanliga hippogryphägget?",a="Curgle sköter om det och hoppas på tur, eftersom bara ungefär hälften av sådana ägg kläcks.",al={"vad gör curgle med ägget","chans att ägget kläcks"}},{q="Var kommer de här äggen ifrån?",a="Från Feralas.",al={"var hittar jag ägget","vanligt äggs plats"}},{q="Vad hände före det här steget?",a="Det följer efter The Super Egg-O-Matic.",al={"föregående uppdrag","vilket är det föregående uppdraget"}}},fp="15,141,13.149.0,25.112.0,44.77.0,30.13.0,27.33.0"}
P.entries["quest:275"] = {n="Blisters on The Land",s="Blisters on The Land är ett uppdrag för Alliansen som Rethiel the Greenwarden ger längs Wetlands östra åsar. Den ensamma träskväktaren anar en onaturlig sjukdom i träsket och ber resenärer döda de sjuka Fen Creepers som stryker längs vattenvägarna. Genom att ge dessa stapplande växtmonster frid försöker Rethiel hejda träskets stigande feber.",h="Blisters on The Land är ett uppdrag för Alliansen som Rethiel the Greenwarden ger längs Wetlands östra åsar.",kw={"blisters on the land","fen creepers","greenwarden","träskmarker","rethiel","kärren i wetlands","wetlands"},ang={["class:Druid"]="Rethiels uppdrag speglar direkt druidernas plikt att läka naturen och rena bort upprörda elementarsår, så att jorden kan återfå sin balans.",["class:Shaman"]="Fen Creepers är förvridna uttryck för jord och vatten, så att förgöra dem blir ett sätt att stilla de osämjiga elementarandeandarna.",["race:NightElf"]="Att hitta en ensam träskväktare som samarbetar med Stormwind i Eastern Kingdoms visar att även landets egna andar söker hjälp för att vårda sargad mark."},sec={{t="En ruttnande träskmark",b="Från sin glänta bland våtmarkerna vakar Rethiel the Greenwarden över Wetlands fuktiga vidder. Träsket har aldrig varit gästvänligt, men på sistone har en onaturlig sjukdom börjat sprida sig genom dyn. Rethiel uppfattar åkomman som en feber som växer i själva jorden och får den vilda naturen att förvridas till tanklösa, stapplande vidunder."},{t="Rena Fen",b="Det främsta tecknet på förruttnelsen är Fen Creepers, ruttnande elementarmassor av träskväxter som stapplar längs vattenvägarna. Rethiel beskriver dem som sjuka blåsor som sväller upp på landets yta. Eftersom deras plågade existens bara sprider oro genom träsket ber Greenwarden förbipasserande allierade att förgöra dem, så att deras trassliga rester kan sjunka tillbaka i leran utan att vålla skada."}},faq={{q="Vem är Rethiel the Greenwarden?",a="Rethiel the Greenwarden är ett träskodjur som bor i Greenwarden's Grove i östra Wetlands. Den ägnar sig åt att vårda träskmarkernas naturliga balans och försöker lindra landets plågor och hejda förvriden elementartillväxt.",al={"vem är rethiel","rethiel the greenwarden bakgrund","vem ger uppdraget blisters on the land"}},{q="Vad är Fen Creepers?",a="Fen Creepers är fientliga växt- och träskelementarer som strövar längs Wetlands vattenvägar. De ser ut som väldiga, stapplande massor av levande slingerväxter, lera och ruttnande träskflora.",al={"fen creepers","vad är en fen creeper","fen creepers i wetlands"}},{q="Varför vill Rethiel att Fen Creepers ska förgöras?",a="Rethiel ser Fen Creepers som febriga, sjuka uttryck för träskets växande sjukdom. Den tror att om de förgörs kan deras kroppar lösas upp och sjunka tillbaka i jorden, så att det upprörda landet får ro.",al={"varför döda fen creepers","varför blisters on the land"}},{q="Vad orsakar förruttnelsen i Wetlands?",a="Rethiel medger att den inte helt vet vad som får förruttnelsen att växa i Wetlands. Den känner bara landets gråtande nöd och behandlar symptomen genom att lugna elementarisk oro där den blossar upp.",al={"varför är wetlands sjukt","orsaken till sjukdomen i wetlands"}},{q="Var i Wetlands finns Fen Creepers?",a="Fen Creepers strövar längs de fuktiga vattenvägarna, leriga stränderna och centrala kanalerna som korsar Wetlands, särskilt nära de djupare kärren väster om Greenwarden's Grove.",al={"fen creepers platser","var hittar man fen creepers"}},{q="Har det här uppdraget samband med andra uppgifter åt Rethiel?",a="Ja. Blisters on The Land följer på Rethiels oro över att Mosshide-gnollerna bränner Wetlands träd i Fire Taboo och är en del av dess fortsatta försök att skydda träskets balans.",al={"greenwardens uppdragskedja","rethiels uppdrag"}}},fp="20,178,19.249.0,17.281.0,31.211.0,22.169.0,49.184.0,42.149.0,45.143.0,51.148.0"}
P.entries["quest:2750"] = {n="A Bad Egg",s="Curgle Cranklehop berättar om äggen som inte går att rädda och aldrig kommer att kläckas.",h="Curgle Cranklehop berättar om äggen som inte går att rädda och aldrig kommer att kläckas.",kw={"bad egg","curgle cranklehop","feralas","super egg-o-matic","tanaris"},sec={{t="Ett ägg som inte går att rädda",b="Vissa hippogrypägg går inte att rädda, och ett dåligt ägg är ett som aldrig kommer att kläckas. Det är Curgle Cranklehop som tar hand om sådana ägg."},{t="Vad händer med det?",b="Curgle tar ägget så att det tas om hand på rätt sätt. Alla ägg går inte att rädda, säger Curgle, och du ska inte tappa modet utan försöka igen med ett annat ägg från Feralas."}},faq={{q="Vem tar emot Bad Egg?",a="Curgle Cranklehop.",al={"vem ska jag ge bad egg till","curgle cranklehop ägg","vem tar bad egg"}},{q="Går ägget att rädda?",a="Nej. Ett Bad Egg går inte att rädda och kommer aldrig att kläckas.",al={"kan bad egg kläckas","kommer bad egg kläckas","rädda bad egg"}},{q="Vad kom före det här?",a="Det följer efter The Super Egg-O-Matic.",al={"föregående uppdrag","förkunskapskrav","förkunskapskrav för bad egg"}}},fp="9,82,20.131.0,18.176.1,24.18.0,21.63.0,22.33.0"}
P.entries["quest:2751"] = {n="Barbaric Battlements",s="I Orgrimmar söker Orokk Omosh någon som kan föra familjens smideskonst vidare. Han saknar arvingar och ber en blivande smed visa stadig hand med brons innan han delar med sig av sina kunskaper.",h="I Orgrimmar söker Orokk Omosh någon som kan föra familjens smideskonst vidare.",kw={"barbaric battlements","smide","brons","arv","omosh","orgrimmar","orokk omosh"},ang={["faction:Horde"]="Som medlem av Horde delar du Omosh-familjens övertygelse om att metallarbete ska prövas i strid och fläckas av fiendens blod.",["profession:Blacksmithing"]="Som smed i Horde når du en milstolpe på vägen från grundläggande brons- och koppararbete till mer avancerade rustningstraditioner."},sec={{t="Omoshsläktens sista led",b="Orokk Omosh arbetar vid städet i Orgrimmar, tyngd av sin familjs förflutna. I tjugo generationer har Omosh-släkten format malm till vapen och rustningar åt Horde. Orokk saknar släkt och kan inte få barn, och han ser sig själv som ett misslyckande för släkten. När familjens hantverk riskerar att dö ut lägger han släktstoltheten åt sidan och söker en lärling som kan föra smedjetraditionerna vidare."},{t="Ett prov i metall och tand",b="Orokk delar inte sina hemligheter med en oprövad smed. Han ber om två mönstrade bronsarmringar, två stora bronssvärd och två vassa rovdjursklor som bevis på grundläggande skicklighet vid städet. För honom är smide ingen tom lyx: den högsta äran är rustningar och stål fläckade av fiendens blod. Om du uppfyller hans krav kan den gamle smeden övertygas om att Omosh-arvet kan leva vidare genom en lärling, och ge dig chansen att lära dig mer om hantverket."}},faq={{q="Vem är Orokk Omosh?",a="Orokk Omosh är en mästersmed i Orgrimmar och den tjugonde generationen i Omosh-släkten. Utan släkt eller arvingar söker han någon utifrån som kan hålla klanens smideskunskaper vid liv.",al={"orokk omosh","vem är orokk","omosh smed"}},{q="Varför behöver Orokk lära upp någon annan?",a="Orokk har ingen kvarvarande släkt och kan inte få barn. Han behöver en lärling som ärver verkstadens ritningar och tekniker, annars tar tjugo generationers smideskunskap slut med honom.",al={"varför lärling","orokks arvinge","varför dör omoshsläktens arv ut"}},{q="Vilka föremål krävs för att bevisa sin skicklighet för Orokk?",a="Orokk ber om två mönstrade bronsarmringar, två stora bronssvärd och två vassa klor från våldsamma rovdjur.",al={"vad behöver jag till barbaric battlements","föremål till barbaric battlements","lämna in barbaric battlements"}},{q="Vad händer när du har slutfört Barbaric Battlements?",a="När du har bevisat dina grundläggande kunskaper i brons fortsätter Orokk din träning med On Iron Pauldrons, där du går vidare till tyngre järnsmide och avancerade plåtrustningar.",al={"nästa uppdrag","uppdragskedjan efter barbaric battlements","vad kommer sedan"}}},fx={["2a7cea14"]={q="Varför behöver Orokk Patterned Bronze Bracers, Bronze Greatswords och Sharp Claws?",a="Orokk Omosh söker en värdig lärling som kan föra familjens heliga smidestradition vidare. I stället för att använda vapnen kräver han Patterned Bronze Bracers, Bronze Greatswords och Sharp Claws som ett färdighetsprov. Om du kommer med de fint smidda bronsföremålen och råa troféer från bestar visar du att du har den disciplin, hantverksskicklighet och råstyrka som krävs för att lära dig klan Omoshs hemliga recept.",al={"vad ska föremålen användas till","varför patterned bronze bracers","varför bronze greatswords och sharp claws"}}},fp="20,181,25.399.0,25.440.0,19.183.0,42.191.0,53.124.0,49.166.0"}
P.entries["quest:2753"] = {n="Trampled Under Foot",s="I Orgrimmars Valley of Honor sätter Orokk Omosh smeder på ett avancerat smidesprov. Att smida rustning av grönt järn prövar deras uthållighet och lär dem tillverka tunga järnstövlar, medan Omosh-blodslinjens hemliga tekniker står på spel.",h="I Orgrimmars Valley of Honor sätter Orokk Omosh smeder på ett avancerat smidesprov.",kw={"rustningssmide","smide","gorokk","grön järn","orgrimmar","orokk omosh","trampled under foot","valley of honor"},ang={["faction:Horde"]="Orokks lektioner lär ut hållbara mönster för järnrustningar, utformade för den brutala strid som föredras på hordens krigsfronter.",["profession:Blacksmithing"]="För en pansarsmed i horden är det här provet ett stort steg. Det kräver omfattande järnsmältning och förberedelser av grönt färgämne för att få exklusiva stövelritningar."},sec={{t="Omoshs prövningar",b="Orokk Omosh tränar pansarsmeder i Orgrimmar genom hårda fysiska prövningar. Han ser metallarbete som mer än att hetta upp malm och forma den; arbetet hedrar hans förfäders klan och prövar en smeds uthållighet. Det här är det tredje provet i hans serie, och upprepad tillverkning av härdad rustning av grönt järn ska bygga muskler och disciplin."},{t="Hövding Gorokks arv",b="Smeder som kommer med den efterfrågade utrustningen av grönt järn får sällsynt beröm av den kärve pansarsmeden Orokk. Han jämför en hantverkare som uthärdar arbetet med sin farfar, Chief Gorokk of Omosh. I utbyte mot rustningen lär Orokk ut den nedärvda ritningen för stadiga järnstövlar, gjorda så att hordens krigare kan krossa sina fiender under hälarna."}},faq={{q="Vem erbjuder uppdraget Trampled Under Foot?",a="Orokk Omosh, en pansarsmed av orc-folket i Orgrimmars Valley of Honor, erbjuder provet.",al={"uppdragsgivare","vem ger trampled under foot","orokk omosh plats"}},{q="Vad kräver Orokk Omosh för den här prövningen?",a="Orokk kräver fyra Green Iron Helms, fyra Green Iron Bracers och två Green Iron Leggings. Dessa delar prövar och bevisar smedens skicklighet i hantverket med grönt järn.",al={"lämna in trampled under foot","vilka föremål behövs","material som behövs"}},{q="Vad ligger bakom Omoshs träningskedja?",a="Orokk Omosh utsätter unga smeder för utmattande fysiskt arbete för att upprätthålla sina förfäders krigiska arv. Han tror att slitsamt pansarsmide bygger styrkan som krävs för att tillverka utrustning som står emot brutalt krig.",al={"varför låter orokk dig tillverka rustning","omosh-klanens historia"}},{q="Vem är Chief Gorokk of Omosh?",a="Chief Gorokk of Omosh är Orokk Omoshs farfar. Orokk hedrar sin farfars krigiska skicklighet och jämför smeder som uthärdar hans tunga smidesprov med hövdingen.",al={"chief gorokk","orokks farfar"}},{q="Vilket uppdrag kommer före Trampled Under Foot?",a="On Iron Pauldrons kommer före det här provet i Orokk Omoshs serie av utmaningar i pansarsmide.",al={"förutsättningsuppdrag","föregående uppdrag i kedjan"}},{q="Vilket uppdrag kommer efter Trampled Under Foot?",a="Efter det här provet erbjuder Orokk Omosh Horns of Frenzy. Joys of Omosh avslutar serien efter de två återstående lektionerna.",al={"nästa uppdrag","vad kommer efter trampled under foot"}}},fx={["454b7030"]={q="Varför vill Orokk Omosh att du smider de här föremålen av grönt järn?",a="Orokk Omosh lär dig sin släkts brutala smidestraditioner. Han anser att sanna krigare och smeder måste uthärda plågsamt arbete för att smida utrustning värdig namnet Omosh. Genom att låta dig hamra ut flera hjälmar, armskenor och benskenor av tungt grönt järn prövar han både din fysiska uthållighet och ditt hantverk. På så sätt förbereder han dig på att lära dig smida stridståliga stövlar.",al={"orokk omoshs motiv","varför smida grönt järn","varför vill orokk ha det här"}},["9ced7653"]={q="Vad ska Green Iron Helm användas till?",a="Green Iron Helms är en del av Orokk Omoshs hårda prov på hantverksskicklighet och uthållighet. De smälts och hamras fram av dina egna händer och visar smeden att du har den noggranna metallurgiska kunskap och råa fysiska uthållighet som krävs för att tillverka tung stridsutrustning enligt Omoshtraditionen.",al={"green iron helms syfte","varför green iron helm","användning av green iron helm"}},ae72eea8={q="Vad ska Green Iron Bracers användas till?",a="De här armskenorna visar att du kan smida stadiga och pålitliga skydd för armar och ben under Orokk Omoshs skoningslösa ledning. Om du lämnar över fyra välgjorda par bevisar du att din smideskonst kan utrusta krigare för de brutala strider som väntar.",al={"green iron bracers syfte","varför green iron bracers","användning av green iron bracers"}},["9872ef5a"]={q="Vad ska Green Iron Leggings användas till?",a="Benskenorna kräver stora mängder bearbetat järn och disciplinerat smidesarbete. Om du lämnar över två välgjorda par visar du Orokk att du är värdig att ärva hemligheterna bakom kraftfulla pansarstövlar och följa i hans förfader Chief Gorokks fotspår.",al={"green iron leggings syfte","varför green iron leggings","användning av green iron leggings"}},f314d286={q="Varför behöver Orokk Omosh dig i stället för att smida själv?",a="Orokk söker inte efter en rustningsleverans åt sig själv. Han prövar och undervisar dig. Som lärare i klanens urgamla tekniker kräver han att dina muskler ska värka över städet för att bevisa ditt engagemang innan han delar Omoshs ritningar med dig.",al={"varför jag, orokk","varför behöver orokk mig","varför smider han det inte själv"}}},fp="19,241,19.331.0,22.336.0,41.80.0,45.168.0,49.208.0,29.173.0,40.88.0,60.116.0"}
P.entries["quest:2755"] = {n="Joys of Omosh",s="Efter en äventyrares stora hjälp delar Orokk Omosh med sig av en familjetradition i Orgrimmar. Den erfarne smeden avfärdar sina tårar som sot och utför sedan Omosh glädjedans för att föra vidare en ovanlig del av familjens arv.",h="Efter en äventyrares stora hjälp delar Orokk Omosh med sig av en familjetradition i Orgrimmar.",kw={"smed","glädjedans","joys of omosh","orgrimmar","orokk omosh","sot i ögat","valley of honor"},ang={["faction:Horde"]="I Valley of Honor i Orgrimmar möts kampstolthet, Orokks tårfyllda glädje och livliga dans bland stålets klang.",["profession:Blacksmithing"]="För en smed ger Orokks sentimentala familjedans en humoristisk och ömsint inblick i en erfaren hantverkares liv bortom smedjan."},sec={{t="En sotfläckad tår",b="Nära den glödheta smedjan i Orgrimmar är Orokk Omosh känd för sina tunga hammarslag, inte för tårar. Den bastanta smeden har fått stor hjälp av dig, och vänligheten överväldigar honom. Envis som han är skyller han på en sotflaga i ögat i stället för att erkänna att han gråter."},{t="Omosh-traditionen",b="Innan ni skiljs åt säger Orokk att han måste dela en sista hemlighet från familjen Omosh. Han utför den kraftfulla och utmattande Omosh glädjedans för sin lärling och lär sedan lärlingen att slå med en järnnäve."}},faq={{q="Vem är Orokk Omosh?",a="Orokk Omosh är en orksmed i Valley of Honor i Orgrimmar. Han är innerligt stolt över familjens hantverk och släktlinje och håller liv i traditionerna vid sidan av smidet.",al={"vem är orokk","orokk omoshs bakgrund","orokk smed"}},{q="Varför gråter Orokk?",a="Orokk säger att sot från smedjan har fastnat i ögat, men din hjälp har rört honom djupt. Han har hittat någon som förtjänar att få ta del av familjens traditioner.",al={"varför gråter orokk","är orokk ledsen","sot i ögat"}},{q="Vad är Omosh-glädjedansen?",a="Omosh glädjedans är en kraftfull dans som gått i arv inom Orokks familj. Den gör honom ordentligt trött, och det var mycket länge sedan han övade på den.",al={"omosh-dansen","glädjedans","vad är dansen"}},{q="Var utspelar sig uppdraget?",a="Det hela utspelar sig i Orgrimmar, vid smedjan i Valley of Honor där Orokk Omosh arbetar med metallen.",al={"uppdragets plats","var finns joys of omosh","orgrimmars smedja"}},{q="Vad lär Orokk dig?",a="Orokk lär dig Omosh glädjedans och lovar att föra vidare kunskapen om järnnäven, vilket knyter samman smeden och äventyraren.",al={"omosh-belöning","vad lär jag mig","järnnäve"}},{q="Kan alliansspelare delta i uppdraget?",a="Nej. Orokk Omosh är allierad med Horde och bor innanför Orgrimmars befästa murar, så bara äventyrare från Horde kan träffa honom där.",al={"alliansen joys of omosh","är uppdraget bara för horde"}}},fx={["371650ab"]={q="Varför vill Orokk Omosh lära dig glädjens dans?",a="Orokk är överväldigad av tacksamhet för din hjälp och vill föra sin släkts sista, noga bevarade tradition vidare. Genom att lära dig Omoshs glädjedans känner han att hans arv hedras och att han äntligen kan dö som en lycklig orch.",al={"varför lära ut dansen","orokk omoshs motiv","varför vill orokk ha det här"}}},fp="13,226,19.262.0,19.211.0,19.173.0,20.149.0,31.157.0,33.117.0,26.129.0,47.132.0"}
P.entries["quest:276"] = {n="Tramping Paws",s="Tramping Paws är ett uppdrag för Alliansen som ges av Rethiel the Greenwarden i Greenwarden's Grove i Wetlands. Den växande Mosshide-gnollstammen nära Gate of Algaz oroar beskyddaren av kärrdjuren, som ger äventyrare i uppdrag att minska deras antal innan deras eldar och trampande tassar förstör kärret.",h="Tramping Paws är ett uppdrag för Alliansen som ges av Rethiel the Greenwarden i Greenwarden's Grove i...",kw={"algaz","gnoller","greenwarden","blandrashundar","mosshide","rethiel","tramping paws","wetlands"},ang={["class:Druid"]="Rethiels uppdrag speglar direkt Cenarionordenens uppdrag att upprätthålla ekologisk jämvikt genom att gallra onaturligt snabbt växande bestånd, så att kärret inte kollapsar.",["race:Dwarf"]="När gnollerna svärmar precis utanför Gate of Algaz bevarar du inte bara våtmarken genom att gallra ut dem, utan säkrar också den viktiga vägen mellan Ironforge och Menethil Harbor.",["race:NightElf"]="Nattalverna har urgamla band till naturens vilda andar, så Rethiels vädjan om att läka kärret känns som en välbekant och hedervärd plikt."},sec={{t="Ett växande hot i träsket",b="I många år levde Mosshide-gnollerna i Wetlands utan att helt rubba den naturliga ordningen. På senare tid har dock flockarna vuxit explosionsartat söderut mot passet vid Dun Algaz. Deras tunga stövlar och tassavtryck trampar ner sällsynta kärrväxter, och deras primitiva skogsavverkning skövlar viktiga dungar för att hålla lägereldarna brinnande. Om flockarna lämnas åt sitt öde hotar de att försämra det känsliga kärrlandskapets ekologi."},{t="Greenwardens dom",b="Rethiel the Greenwarden vakar över kärret med blicken fäst vid balansen snarare än civilisationen. För Greenwarden är problemet inte att gnoller finns, utan att deras okontrollerade antal överstiger vad Wetlands kan försörja. Genom att minska antalet Mosshide-gnoller och blandrashundar till hanterliga nivåer hjälper äventyrare till att bevara våtmarkerna och vinner motvilligt gillande från en uråldrig väktare av vildmarken."}},faq={{q="Vem är Rethiel the Greenwarden?",a="Rethiel är ett kärrdjur som bor i Wetlands längs vägen mellan Ironforges gränser och Arathi. Det har vigt sig åt att bevara kärret, övervakar markens hälsa och ger resenärer i uppdrag att hålla destruktiva bestånd i schack.",al={"rethiels bakgrund","vem ger tramping paws","greenwarden wetlands"}},{q="Varför är Mosshide-gnollerna ett problem nu?",a="Mosshide-flocken levde en gång sida vid sida med kärret utan att orsaka långvarig skada, men den senaste tidens befolkningsboom har lett till omfattande skogsskövling för ved och vitt spridd nedtrampning av känsliga kärrväxter.",al={"varför döda gnoller i wetlands","hotet från mosshide-gnollerna"}},{q="Var orsakar gnollerna den här skadan?",a="Mosshide-gnollerna och blandrashundarna samlas i stora antal i södra Wetlands, särskilt nära dvärgarnas pass Dun Algaz.",al={"var finns mosshide-gnollerna","tramping paws plats"}},{q="Vad händer när gnollerna har gallrats ut?",a="När flockarna har tunnats ut undersöker Rethiel orsaken till deras ovanliga aktivitet och bränsleförbrukning närmare och skickar äventyrare på uppföljningsuppdraget \"Fire Taboo\".",al={"nästa uppdrag efter tramping paws","uppföljning till tramping paws"}},{q="Varför nämner Rethiel att dess tro har satts på prov?",a="Rethiel berättar att dess tro på ert folk har prövats tidigare, och att det betraktar dödliga och deras snabba expansion med försiktighet. När du hjälper till att skydda den vilda våtmarken visar du att dödliga äventyrare kan vårda naturen i stället för att exploatera den.",al={"rethiels dialog","tron har prövats tidigare"}}},fx={["24db34f0"]={q="Vilka är Mosshide-kobolderna som du skickas ut för att jaga?",a="Mosshide är en koboldklan från Wetlands. I generationer levde de här i fred med naturen, men deras snabbt växande antal kalhugger nu våtmarkerna. Deras tunga tassar trampar ner kärrmarkens ömtåliga växter, medan deras yxor fäller alltför mycket virke till matlagning och lägereldar. Det rubbar det lokala ekosystemet helt ur balans.",al={"mosshide-kobolder","vilka är mosshide","mosshide-slynglar"}}},fp="13,197,21.320.0,26.287.0,31.233.0,42.194.0,41.125.0,36.135.1,49.215.0"}
P.entries["quest:2766"] = {n="Find OOX-22/FE!",s="Du stöter på en märklig, äggformad apparat av metall. En röst inifrån presenterar sig som Oglethorpe Obnoticus, vars målsökande robot har kraschat. Du ombeds ta med fyren till maskinen, som ligger i en grotta nära Feral Scar Vale.",h="Du stöter på en märklig, äggformad apparat av metall.",kw={"nödfyr","feral scar vale","feralas","målsökande robot","mekanisk kyckling","oglethorpe obnoticus","oox-22/fe"},sec={{t="En röst i ägget",b="När du vrider på en ratt öppnas metallägget och vecklar ut sig till en gnomisk robotapparat, och en sprakande röst talar inifrån. Oglethorpe Obnoticus säger att hans målsökande robot har kraschat och lovar betalning om du hittar den. Fyren ska föras till roboten, och Oglethorpe har räknat ut var den ligger: i en grotta nära Feral Scar Vale."},{t="Vad grottan döljer",b="I grottan hittar du vrakdelar som ser ut att komma från en robotkyckling. Oglethorpes röst bekräftar att det är hans målsökande robot och säger att den måste få en starthjälp innan den flyger till Booty Bay för reparation. När du placerar fyren inuti vaknar roboten till med ett surr, och då kommer Oglethorpes röst från själva roboten."}},faq={{q="Vem talar genom nödfyren?",a="Oglethorpe Obnoticus. Hans målsökande robot har kraschat, och han ber dig ta med fyren till den.",al={"vem byggde fyren","vem talar","vem är oglethorpe"}},{q="Vart leder fyren dig?",a="Oglethorpe har räknat ut robotens koordinater. Den ligger i en grotta vid Feral Scar Vale i Feralas.",al={"var finns roboten","målsökande robotens plats","vart ska fyren föras"}},{q="Vad är fyren?",a="En märklig, äggformad apparat av metall. När du vrider på en ratt öppnas den och vecklar ut sig till en gnomisk robotapparat, och en röst talar inifrån.",al={"vad är ägget","vad är oox-22/fe","nödfyr"}},{q="Vad kommer efter det här steget?",a="Rädda OOX-22/FE! följer.",al={"nästa uppdrag","vad följer efter find oox-22/fe","efter grottan"}}},fp="15,243,18.333.0,19.307.1,44.94.0,38.101.0,19.142.0,27.26.0"}
P.entries["quest:2767"] = {n="Rescue OOX-22/FE!",s="När du hittar målsökningsroboten OOX-22/FE i Feral Scar Vale hör du återigen gnomenas röst spraka ur den. Roboten ska eskorteras till bryggan vid The Forgotten Coast, och därefter vill Oglethorpe Obnoticus tala med dig i Booty Bay.",h="När du hittar målsökningsroboten OOX-22/FE i Feral Scar Vale hör du återigen gnomenas röst spraka ur den.",kw={"booty bay","feral scar vale","feralas","the forgotten coast","målsökningsrobot","oglethorpe obnoticus","oox-22/fe","robothöna"},sec={{t="En säker plats för avfärd",b="Gnomens röst säger att OOX-22/FE behöver en öppen och säker plats där en lång start kan påbörjas. Roboten har inbyggd kamouflagefunktion, men Oglethorpe Obnoticus behöver tid för att få den att fungera igen. Oglethorpe föreslår bryggan vid The Forgotten Coast, där det finns gott om tid att få igång allt, så du ska leda roboten dit från platsen där den står."},{t="Därefter till Booty Bay",b="När roboten väl är tryggt framme vid bryggan vill Oglethorpe Obnoticus att du kommer och pratar med honom i Booty Bay."}},faq={{q="Vart ska OOX-22/FE ta sig?",a="Bryggan längs The Forgotten Coast. Den eskorteras dit från Feral Scar Vale, där du hittade den.",al={"vart ska jag ta hönan","oox-22/fe destination","eskortväg för hönan i feralas"}},{q="Vem är Oglethorpe Obnoticus?",a="En mästerlig uppfinnare vars serie av målsökningsrobotar omfattar OOX-22/FE. Oglethorpe talar genom roboten och finns i Booty Bay.",al={"vem byggde robothönan","vem är oglethorpe obnoticus","hönans uppfinnare"}},{q="Varför måste roboten ta sig till bryggan?",a="En lång start kräver en öppen och säker plats, och Oglethorpe säger att bryggan är tillräckligt lång för att få igång allt. Robotens inbyggda kamouflagefunktion behöver tid innan den fungerar igen.",al={"varför eskortera oox-22","varför gå till bryggan"}},{q="Var ska jag rapportera efteråt?",a="När roboten väl är tryggt framme vid bryggan ska du tala med Oglethorpe Obnoticus i Booty Bay.",al={"var finns oglethorpe","inlämningsplats","vem ska jag prata med efteråt"}}},fp="17,243,24.337.0,21.99.0,32.98.0,28.126.0,42.175.0,29.81.0"}
P.entries["quest:277"] = {n="Fire Taboo",s="Fire Taboo är ett uppdrag från Rethiel the Greenwarden längs Wetlands sumpiga vägar. Plågad av den lokala skogens lidande skickar träskbesten resenärer för att ta Mosshide-gnollernas Crude Flint, som de använder för att tända eld på levande trä. Genom att beröva gnollerna elden hoppas Rethiel rädda träskets urgamla grenar från att förtäras.",h="Fire Taboo är ett uppdrag från Rethiel the Greenwarden längs Wetlands sumpiga vägar.",kw={"crude flint","fire taboo","gnoller","greenwarden","levande trä","mosshide","rethiel","wetlands"},ang={["class:Druid"]="Som vildmarkens väktare delar druider Rethiels vördnadsfulla band till träden och förstår den onaturliga smärtan när levande trä utsätts för gnollernas eldstäder.",["faction:Alliance"]="Mosshide-gnollerna hotar resenärer som passerar genom Wetlands. När du hjälper de lokala andarna bidrar du till att säkra handelsvägarna mellan Dun Morogh och Arathi.",["race:NightElf"]="Nattalver kan känna igen en besläktad beskyddare av levande träd i Rethiel, en träskbest som känner Wetlands lidande."},sec={{t="En Greenwardens vånda",b="Rethiel the Greenwarden vakar över vildmarken i Wetlands och har ett djupt andligt band till träskets träd. I ett träsk hör förruttnelse och förnyelse till naturens kretslopp, men den avsiktliga förstörelsen av träden går rakt in i Rethiels själ. För en levande ande i träsket är det en plåga att höra levande grenar jämra sig när de huggs ner och kastas i härdeldar, något Rethiel inte längre kan uthärda i tystnad."},{t="Släck Mosshide-gnollernas eld",b="Mosshide-flocken härjar i våtmarkerna för att få värme och utöka sitt territorium. De fäller gröna träd i stället för att samla död ved som fallit till marken. För att hejda deras utbredning utan ett långvarigt utnötningskrig riktar Rethiel in sig på deras viktigaste redskap för förstörelsen: Crude Flint, som de starkare gnollerna bär. När Rethiel berövar flocken redskapen för att göra upp eld kan de inte längre bränna det fällda virket. Rethiel krossar själv varje insamlad sten och kastar stoftet i havet, så att gnistorna aldrig mer kan sätta skogen i brand."}},faq={{q="Vem är Rethiel the Greenwarden?",a="Rethiel the Greenwarden är en träskbest som bor i Wetlands. Rethiel är djupt förbunden med de lokala trädens och växternas livskraft och vill skydda det sargade träsket från Mosshide-gnollernas härjningar.",al={"vem är rethiel","rethiel the greenwarden historia","vem ger fire taboo"}},{q="Varför vill Rethiel ha Crude Flint i stället för att döda gnollernas ledare?",a="Rethiel ser bränningen av levande trä som en oförlåtlig kränkning. Genom att ta flinten hindrar Rethiel direkt gnollerna från att tända eldar som förtär våtmarkens träd. Det slår mot deras läger och sätter stopp för förstörelsen av levande trä.",al={"varför flint","varför ta flinten","vad används crude flint till"}},{q="Vad händer med flinten när den lämnas in?",a="Rethiel krossar Crude Flint i bitar och kastar resterna i havet, så att de aldrig mer kan slås mot varandra för att skapa en gnista mot levande trä.",al={"vad gör hon med flinten","förstöra flinten"}},{q="Vilka gnoller bär på flinten?",a="De starkare i Mosshide-flocken bär Crude Flint. De mindre Mosshide-gnollerna och de svagare blandrashundarna får inte förtroendet att hantera elddon och bär dem därför inte.",al={"vem släpper flint","vilka gnoller har crude flint"}},{q="Varför hugger Mosshide-gnollerna ner träd?",a="Mosshide-gnollerna hugger ner levande träd för att få bränsle till sina lägereldar och värma sig i det fuktiga träsket, i stället för att använda torrt, nedfallet virke.",al={"varför hugger gnollerna ner träd","mosshide fäller träd"}},{q="Vad händer efter att flinten har samlats in?",a="När du har berövat gnollerna elden skickar Rethiel dig för att ta itu med en annan plåga som drabbar kärrmarkerna i uppföljningsuppdraget Blisters on The Land.",al={"vilket uppdrag kommer efter fire taboo","nästa uppdrag efter flinten"}}},fx={e3ab03fe={q="Varför vill Rethiel the Greenwarden att det här blir gjort?",a="Som en beskyddare knuten till landet och naturen känner Rethiel starkt av Wetlands lidande. Mosshide-kobolderna hugger ner levande träd och eldar upp dem för att hålla värmen, vilket vållar vildmarken smärta. Genom att ta flintorna från kobolderna hoppas Rethiel kunna stoppa skogsförstörelsen och hindra dem från att elda med levande trä.",al={"rethiels motiv","varför ta flintorna","varför avskyr rethiel eld"}},b6cb9238={q="Vad ska Crude Flint användas till?",a="Mosshide-kobolderna bär på grova flintor som enkla verktyg för att slå gnistor och göra upp eld. Utan dem kan de inte elda med det levande trä de fäller i Wetlands. Rethiel kräver att du samlar in flintorna så att han kan krossa dem och kasta resterna i havet. Då berövar han kobolderna möjligheten att tända brasor.",al={"crude flints användning","vad är crude flints","varför har kobolder flinta"}},["25034295"]={q="Vilka är Mosshide-kobolderna som du skickas emot?",a="Du ställs mot Mosshide-kobolderna, en våldsam klan av hyenamänniskor som härjar i Wetlands. De har spridit sig över våtmarkerna, byggt läger och aggressivt huggit ner urgamla träd för att göra upp eld och ta mark i besittning. Det förstör den naturliga balansen som Rethiel skyddar och för med sig elände.",al={"mosshide i wetlands","vilka är kobolderna","mosshide-kobolder"}}},fp="10,232,23.270.0,27.390.0,31.177.0,72.184.0,51.117.0,30.145.0,41.129.0,43.166.1"}
P.entries["quest:278"] = {n="A Dark Threat Looms",s="Det här uppdraget är ett avgörande steg för att försvara Stonewrought Dam mot en misstänkt plan från Dark Iron. Chief Engineer Hinderweir VII ber äventyrare samla sällsynta kemiska och organiska ingredienser från hela Loch Modan för att blanda en desarmerande lösning. Utan dessa beståndsdelar kan försvararna inte oskadliggöra sprängämnena under det väldiga stenbygget.",h="Det här uppdraget är ett avgörande steg för att försvara Stonewrought Dam mot en misstänkt plan från Dark...",kw={"crocolisk tear","dark iron","hinderweir","loch modan","lurker venom","mo'grosh crystal","stonewrought dam"},ang={["faction:Alliance"]="Om hotet mot dammen inte oskadliggörs blir följden en katastrof: viktiga landbaserade försörjningsleder mellan Ironforge och de nordliga kungadömena kapas.",["profession:Engineering"]="Ingenjörer kan uppskatta Hinderweirs påhittighet när han tar fram ett kemiskt motmedel som kan stabilisera flyktiga sprängladdningar ute i fält.",["race:Dwarf"]="För dvärgarna i Khaz Modan är det en livsviktig plikt att stoppa Dark Irons sabotage vid Stonewrought Dam och skydda deras förfäders land och arkitektoniska triumfer."},sec={{t="Ett flyktigt recept",b="För att motverka de flyktiga sprängblandningar som Dark Iron-sabotörer använder förlitar sig Chief Engineer Hinderweir VII på ett okonventionellt kemiskt neutraliseringsmedel. I stället för vanligt vatten eller fuktande sand krävs en kraftfull blandning av gift från inhemska Forest Lurker, en tår från krokilisken som lever i The Loch och en Mo'grosh Crystal för att neutralisera Dark Irons sprängpulver. Varje beståndsdel bidrar med unika reaktiva egenskaper som behövs för att göra dvärgarnas sprängladdningar helt verkningslösa."},{t="En farlig insamling",b="För att säkra ingredienserna måste äventyrarna ta sig till de mest fientliga delarna av Loch Modan. Spindlarna och krokilisken vid The Loch utgör vanliga naturliga faror, men för att få tag på en Mo'grosh Crystal måste man våga sig in i ogrefästet i de nordöstra kullarna. Mo'grosh-ogrerna vaktar dessa sällsynta, utvunna mineralformationer svartsjukt. Den som vill skydda dammen måste därför kämpa sig igenom deras läger för att få ett prov."}},faq={{q="Varför behöver Engineer Hinderweir just de här ingredienserna?",a="Chief Engineer Hinderweir VII blandar en särskild neutraliserande förening för att desarmera Dark Iron-sprängämnen. Det frätande lurkergiftet, krokiliskernas sekret och de magiska mineralerna i Mo'grosh Crystals ger de exakta kemiska reaktioner som krävs för att göra sabotörernas avancerade sprängladdningar verkningslösa.",al={"varför spindelgift","varför krokilisktår","ingredienser till desarmeringsblandning"}},{q="Var kommer Mo'grosh Crystals ifrån?",a="Mo'grosh-ogrerna som håller till i Loch Modans nordöstra kullar bryter och samlar på kristallerna. Ogrerna betraktar dem som sällsynta och värdefulla, så för att få tag på en måste man ta sig in på deras välbevakade område.",al={"var finns kristaller","plats för mogroshkristall","vem har kristallen"}},{q="Vilket mörkt hot hemsöker Loch Modan?",a="Hotet kommer från Dark Iron-dvärgar som infiltrerat området och vill förstöra Stonewrought Dam. Om detta väldiga tekniska underverk rivs kommer våtmarkerna nedanför att översvämmas, alliansens försörjningslinjer att skäras av och regionen att ödeläggas.",al={"vilket mörkt hot","vem angriper dammen","berättelsen om det mörka hotet"}},{q="Vem är Chief Engineer Hinderweir VII?",a="Han är chefsingenjören bland dvärgarna och ansvarar för Stonewrought Dams drift och skick. Han leder både det strukturella underhållet och det lokala försvaret mot sabotage.",al={"vem är hinderweir","chief engineer hinderweir"}},{q="Var hittar man de inhemska varelserna?",a="Forest Lurker-spindlar strövar omkring i den skogsklädda vildmarken runt dalen, medan krokilisker lever i och kring stränderna vid The Loch.",al={"var finns lurkers","krokiliskarnas plats","var hittar man spindlar"}},{q="Varför samlar inte vakterna från Ironforge in föremålen själva?",a="Bergsvakterna och de lokala vakterna är hårt upptagna med att försvara städer som Thelsamar och hålla utkik efter Dark Iron-spejare. Specialiserade insamlingsuppdrag och räder in i ogreterritorium överlåts regelbundet åt dugliga resande äventyrare.",al={"varför hjälpa hinderweir","var finns vakterna från ironforge"}}},fx={["0370975a"]={q="Varför vill Chief Engineer Hinderweir VII att de här föremålen samlas in?",a="Chief Engineer Hinderweir VII fruktar ett nära förestående angrepp från Dark Iron-dvärgar mot Stonewrought Dam. För att motverka eventuella sprängningsförsök behöver han att du samlar in flyktiga och specialiserade reagenser: Lurker Venom, en Crocolisk Tear och en sällsynt Mo'grosh Crystal. Då kan han brygga en neutraliserande blandning som desarmerar fiendens sprängämnen innan Loch Modan ödeläggs.",al={"varför vill hinderweir få det här gjort","varför samla reagenser åt hinderweir","hinderweirs motiv med det mörka hotet"}}},fp="19,199,17.237.0,18.259.0,58.232.0,37.145.0,44.167.0,37.179.0,44.116.0,61.193.0"}
P.entries["quest:2781"] = {n="WANTED: Caliph Scorpidsting",s="Gadgetzan Water Company utfäster en belöning för Caliph Scorpidsting, som leder Wastewander-banditerna. Bevis på hans död lämnas till Chief Engineer Bilgewhizzle i Gadgetzan.",h="Gadgetzan Water Company utfäster en belöning för Caliph Scorpidsting, som leder Wastewander-banditerna.",kw={"belöning","caliph scorpidsting","chief engineer bilgewhizzle","gadgetzan","gadgetzan water company","steamwheedle port","tanaris","wastewander"},sec={{t="Företagets anklagelser",b="Efterlysningar i Gadgetzan och Steamwheedle Port utlovar en hög belöning från Gadgetzan Water Company för Caliph Scorpidsting, som leder Wastewander-banditerna. Han anklagas för att ha mördat företagets anställda, stulit dess resurser och lagt beslag på dess egendom. Bevis på hans död ska lämnas till Chief Engineer Bilgewhizzle i Gadgetzan."},{t="Vad Water Company hoppas på",b="Chief Engineer Bilgewhizzle kallar Scorpidstings död rättvisa och ett hårt slag mot Wastewanders, som ingenjören kallar vidriga nomader och ockupanter. Förhoppningen är att det äntligen ska få dem att lämna Gadgetzans vattenbrunnar, och belöningen betalas ut på företagets vägnar."}},faq={{q="Vem är Caliph Scorpidsting?",a="Han leder Wastewander-banditerna och är efterlyst av Gadgetzan Water Company.",al={"caliph scorpidsting berättelse","vem leder wastewanders","scorpidsting"}},{q="Varför vill Gadgetzan Water Company se honom död?",a="Företaget anklagar honom för att ha mördat dess anställda, stulit dess resurser och lagt beslag på dess egendom.",al={"varför belöning för scorpidsting","caliph scorpidstings brott","gadgetzan water company fiende"}},{q="Vem betalar belöningen för Caliph Scorpidsting?",a="Chief Engineer Bilgewhizzle från Gadgetzan Water Company tar emot bevis på Scorpidstings död i Gadgetzan.",al={"vem lämnar in scorpidsting","var lämnar man in caliphs huvud","bilgewhizzle belöning"}},{q="Var finns efterlysningarna?",a="I Gadgetzan och i Steamwheedle Port.",al={"caliph efterlysning plats","var hämtar man caliphs belöning","scorpidsting efterlysning"}}},fp="27,170,21.360.0,32.284.1,27.72.0,51.100.0,44.110.0,37.38.0"}
P.entries["quest:2782"] = {n="Rin'ji's Secret",s="Efter att ha hjälpt Rin'ji bär du på en tavla med Witherbark-trollens märken, som ingen ännu har kunnat läsa. Oran Snakewrithe, som studerar Witherbark, kanske kan tyda den och bor i Magic Quarter i Undercity.",h="Efter att ha hjälpt Rin'ji bär du på en tavla med Witherbark-trollens märken, som ingen ännu har kunnat läsa.",kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","tavla","undercity","witherbark"},sec={{t="En tavla ingen kan läsa",b="Witherbark-trollens märken täcker tavlan, och vad Rin'jis hemlighet egentligen är förblir ett mysterium. Den kan vara värd mycket, eller ingenting alls, eftersom ett Witherbark-troll i knipa förmodligen skulle göra vad som helst för att ta sig ur den."},{t="En lärd i Undercity",b="Oran Snakewrithe är en välkänd kännare av Witherbark-trollen och sägs bo i Magic Quarter i Undercity. Oran kanske kan läsa tavlan."}},faq={{q="Varifrån kommer tavlan?",a="Det är hemligheten som Rin'ji gömde vid Overlook Cliffs. Du hittade den efter att ha hjälpt Rin'ji att fly från Quel'Danil Lodge.",al={"rinjis tavlas ursprung","hur får jag tag på tavlan"}},{q="Vem kan läsa märkena på tavlan?",a="Oran Snakewrithe, en lärd som känner Witherbark-trollen väl, kanske kan tyda den.",al={"vem kan tyda tavlan","vem läser witherbark-märken"}},{q="Var finns Oran Snakewrithe?",a="Oran sägs bo i Magic Quarter i Undercity.",al={"oran snakewrithe plats","var finns oran"}},{q="Är tavlan värdefull?",a="Det går inte att säga. Den kan vara värd mycket eller ingenting, eftersom ett Witherbark-troll i nöd kanske skulle försöka vad som helst för att ta sig ur knipan.",al={"vad är rinjis hemlighet","tavlans betydelse"}}},fp="15,227,24.201.0,26.160.0,32.123.0,40.91.0,34.72.0,23.146.0"}
P.entries["quest:280"] = {n="A Dark Threat Looms",s="Ett desperat nöduppdrag från Chief Engineer Hinderweir VII ska förhindra att Stonewrought Dam förstörs. Dark Iron-sabotörer har placerat en explosiv Seaforium-laddning djupt under vattenytan, redo att spränga ett av dvärgarnas kungarikets största ingenjörsunder.",h="Ett desperat nöduppdrag från Chief Engineer Hinderweir VII ska förhindra att Stonewrought Dam förstörs.",kw={"damm","dark iron","desarmering","sprängämne","hinderweir","insurgenter","tunna","seaforium","stonewrought"},ang={["faction:Alliance"]="Om Stonewrought Dam förstörs ödeläggs viktiga transportleder som förbinder Khaz Modan med de nordliga alliansområdena.",["profession:Engineering"]="Att arbeta direkt med Seaforium och särskilda desarmeringskemikalier visar hur avancerad sprängteknik och kemi för att oskadliggöra sprängämnen kan användas när insatserna är så höga.",["race:Dwarf"]="Stonewrought Dam är ett bestående monument över dvärgarnas arkitektur och stolthet. Att skydda den från Dark Iron-svek är av yttersta vikt för varje son och dotter av Ironforge.",["race:Gnome"]="Gnomiska sinnen kan uppskatta både den sofistikerade kemin bakom Hinderweirs neutralisator och den fruktansvärda förödelse som ett Seaforium-genombrott skulle orsaka dvärgarnas ingenjörsverk."},sec={{t="Sabotage under ytan",b="Chief Engineer Hinderweir VII fick syn på Dark Iron Insurgents som simmade mot Stonewrought Dams grund med en massiv tunna explosivt Seaforium. Eftersom inga Mountaineers fanns i närheten för att ingripa kunde infiltratörerna fästa sprängladdningen direkt mot dammens undervattensgrund. Ett brott skulle släppa ut hela sjöns vattenmassa över låglandet nedanför, orsaka katastrofala översvämningar och slå hårt mot dvärgarnas handel och resor i hela regionen."},{t="En flyktig neutralisator",b="Hinderweir blandar snabbt reaktiva ingredienser till en desarmeringsblandning och skickar en modig dykare rakt mot den nedsänkta bomben. För att neutralisera Seaforium måste du skruva loss tunnan under vattnet och röra ner den kemiska lösningen direkt i sprängpulvret. Blandningen stoppar nedräkningen med ett mjukt fräsande under vattnet och stabiliserar laddningen innan explosionen kan slita sönder murverket."}},faq={{q="Vad är målet med det här uppdraget?",a="Du måste dyka ner under Loch Modans vatten till Stonewrought Dams grund, hitta tunnan med Seaforium och röra ner Chief Engineer Hinderweirs desarmeringsblandning för att neutralisera sprängladdningen.",al={"uppdragsmål","vad ska jag göra här","a dark threat looms mål 6"}},{q="Vem placerade sprängtunnan?",a="Dark Iron Insurgents smög sig tidigare under dagen ner i Loch Modans vatten. De utnyttjade att de lokala Mountaineers var frånvarande och placerade en Seaforium-laddning direkt mot dammens undervattenssida.",al={"vem placerade bomben här","vem placerade seaforium","a dark threat looms skyldiga"}},{q="Vad händer om dammen förstörs?",a="Stonewrought Dam håller tillbaka den väldiga sjön Loch Modan. Om dammen sprängdes skulle miljontals liter vatten översvämma Wetlands och de omgivande dalarna och svepa bort vägar, städer och liv.",al={"varför rädda dammen","vad händer om bomben exploderar","insatser vid dammexplosion"}},{q="Vem blandade ihop desarmeringsblandningen?",a="Chief Engineer Hinderweir VII tillredde den kemiska neutralisatorn av insamlade reagenser. Blandningen kan neutralisera Seaforium-laddningen utan att utlösa en oavsiktlig detonation.",al={"vem gjorde blandningen","hinderweirs roll","vem gjorde kemikalien"}},{q="Var finns sprängtunnan?",a="Tunnan ligger under vattnet mot Stonewrought Dams djupa undervattensgrund, på den södra sidan som vetter mot sjön.",al={"var är bomben","tunnans plats","pulvertunna under vatten"}},{q="Vilket slags sprängämne användes?",a="Dark Iron-sabotörerna använde Seaforium, ett kraftfullt och flyktigt sprängämne, packat i en förseglad, vattentät tunna.",al={"vad består bomben av","bombtyp","vilket sprängämne"}}},fx={["8859d649"]={q="Varför vill Chief Engineer Hinderweir VII att det här görs?",a="Som chefsingenjör med ansvar för Stonewrought Dam tar Hinderweir personligt ansvar för dammens strukturella hållfasthet. Dark Iron-upprorsmakare har placerat en kraftfull Seaforium-sprängladdning vid själva fundamentet. Om dammen brister kommer den förödande flodvågen från Loch att dränka dalarna nedanför och förstöra ett av dvärgfolkets största arkitektoniska underverk.",al={"varför bryr sig hinderweir","hinderweirs motiv","varför stoppa explosionen"}},["34eba16d"]={q="Varför behöver Chief Engineer Hinderweir VII dig i stället för Mountaineers?",a="När Dark Iron-sabotörerna närmade sig fanns inga Mountaineers i närheten som kunde hejda dem, och tiden är knapp. Laddningen kan detonera när som helst, och Hinderweir var tvungen att stanna kvar för att snabbt brygga desarmeringsblandningen av råvarorna. Du är den enda som kan dyka ner och oskadliggöra sprängladdningen genast.",al={"varför kan inte vakterna göra det här","varför jag åt hinderweir","var är mountaineers"}}},fp="19,157,28.331.0,22.322.1,31.185.0,30.196.0,37.151.0,36.155.0,35.103.0,32.98.0"}
P.entries["quest:282"] = {n="Senir's Observations",s="Efter att ha samlat in viktiga uppgifter om hoten i Coldridge Valley låter Grelin Whitebeard dig föra hans fynd till brodern Senir Whitebeard i Kharanos. Men för att lämna den skyddade dalen måste du ta dig genom en tunnel som nyligen översvämmats av fientliga troggs och vaktas av Mountaineer Thalos.",h="Efter att ha samlat in viktiga uppgifter om hoten i Coldridge Valley låter Grelin Whitebeard dig föra hans...",kw={"anvilmar","coldridge valley","grelin whitebeard","grelin's report","kharanos","mountaineer thalos","senir whitebeard","troggs","tunnel"},ang={["faction:Alliance"]="Säkra passager mellan dvärgarnas dalar är avgörande för Ironforges försvar och för att hålla Alliansens kurirer trygga.",["race:Dwarf"]="För dvärgarnas bergsvandrare och rekryter markerar färden genom den östra tunneln den första officiella utplaceringen utanför utbildningsområdet i Coldridge Valley.",["race:Gnome"]="Som gnomiska flyktingar bland Bronzebeards erbjuder den här försändelsen en väg från den första tillflyktsorten mot de större problem som plågar Dun Morogh."},sec={{t="Bud åt Whitebeard-bröderna",b="Grelin Whitebeard lade ner mycket arbete på att dokumentera trollaktiviteten kring Coldridge Valley. När hans journal stals och sedan återfanns stod det klart att uppgifterna var alltför viktiga för att anförtros åt en oerfaren lärling. För att undvika mellanhänder väljer Grelin en erfaren äventyrare som kan föra rapporten direkt till brodern Senir Whitebeard, som leder verksamheten utanför dalen i Kharanos."},{t="Den blockerade vägen till Kharanos",b="Att lämna Coldridge Valley är inte längre en enkel färd längs huvudvägen. Den östra tunneln som förbinder dalen med den vidsträckta, snötäckta platån i Dun Morogh har våldsamt tagits över av grävande troggs. För att hindra oförsiktiga civila från att hamna i en dödsfälla har vakten från Ironforge placerat Mountaineer Thalos strax utanför passagen. Bara resande med brådskande, officiella ärenden får passera vaktposten och trotsa den underjordiska prövningen."}},faq={{q="Vem ska Grelin skicka rapporten till?",a="Rapporten är adresserad till Senir Whitebeard, Grelin bror, som är stationerad bortom bergen i Kharanos och bedömer regionala angelägenheter.",al={"vem får rapporten","senir whitebeard","rapportens mottagare"}},{q="Varför kan inte Grelins lärling leverera rapporten?",a="Grelin tänkte först skicka sin lärling, men efter de senaste problemen med Frostmane-trollen som stal hans journal ansåg han att uppgifterna var för viktiga för att anförtros åt oerfarna händer.",al={"varför inte lärlingen","grelins lärling"}},{q="Varför är tunneln ut ur Coldridge Valley bevakad?",a="Tunneln som förbinder Coldridge Valley med resten av Dun Morogh har helt tagits över av troggs. Mountaineer Thalos är stationerad vid ingången för att skydda civila tills vägen kan röjas.",al={"varför vaktar thalos","tunneln blockerad","varför är tunneln stängd"}},{q="Var finns Mountaineer Thalos?",a="Thalos är stationerad öster om Anvilmar och håller vakt alldeles intill ingången till tunneln som leder ut ur Coldridge Valley mot Kharanos.",al={"thalos plats","var är thalos","hitta mountaineer thalos"}},{q="Vad ger dig tillstånd att passera genom tunneln full av troggs?",a="Mountaineer Thalos släpper inte in vanliga resande i tunneln, men en brådskande försändelse från Grelin Whitebeard visar att ditt ärende är så viktigt att resan är värd risken.",al={"passera genom tunneln","tillstånd för tunneln"}},{q="Vad händer när du har talat med Mountaineer Thalos?",a="Thalos varnar dig och ger råd om hur du tar dig genom den farliga underjordiska vägen innan han ger dig klartecken att fortsätta österut mot Kharanos.",al={"nästa steg","vad händer efter thalos"}}},fx={ba85e128={q="Varför vill Grelin Whitebeard att rapporten levereras?",a="Grelin Whitebeard har dokumenterat den växande Frostmane-trollaktiviteten och hoten i Coldridge Valley. Hans bror, Senir Whitebeard, är stationerad i Kharanos och samlar underrättelser om större problem runt om i Dun Morogh. Det är avgörande att rapporten når Senir säkert, så att regionens försvar kan samordnas, särskilt nu när Frostmane närmar sig dvärgbosättningarna.",al={"varför skicka grelins rapport","grelin whitebeards motiv","varför leverera senirs observationer"}}},fp="20,178,29.308.0,28.232.0,37.123.0,49.145.0,50.153.0,36.108.0,58.90.0,52.120.0"}
P.entries["quest:2821"] = {n="The Mark of Quality",s="I Feathermoon Stronghold kompromissar läderarbetaren Pratt McGrubben aldrig med kvaliteten. Pratt har hittat tjocka yetiskinn och vill ha en bunt med tio.",h="I Feathermoon Stronghold kompromissar läderarbetaren Pratt McGrubben aldrig med kvaliteten.",kw={"feathermoon stronghold","feral scar vale","feralas","the forgotten coast","pratt mcgrubben","kvalitetsmärket","tjockt yetiskinn","yetier"},sec={{t="Pratts filosofi",b="Pratt McGrubben kompromissar aldrig med läderarbetet: bara det allra bästa duger. När Pratt letade efter fina material hittade Pratt tjocka yetiskinn. Yetierna hör hemma i Feralas, och många finns runt Feral Scar Vale, strax inåt land från The Forgotten Coast."},{t="Erbjudandet",b="För en bunt med tio skinn låter Pratt dig välja en av lädervarorna Pratt har tillverkat. Ta med dem tillbaka till Feathermoon Stronghold."},{t="Pratts tankar om skinnen",b="Pratt frågar om du stannade till för att känna på skinnens struktur. Om de behandlas rätt kan de visa sig vara hårdare än järn, och få känner till dem. Med stor kunskap om garvningslösningar hoppas Pratt kunna skapa föremål som bär ett verkligt kvalitetsmärke."}},faq={{q="Vem efterfrågar skinnen?",a="Pratt McGrubben, en läderarbetare i Feathermoon Stronghold.",al={"uppdragsgivare","pratt mcgrubben","vem ger kvalitetsmärket"}},{q="Var hittar man yetierna?",a="Yetierna hör hemma i Feralas, och många finns runt Feral Scar Vale, strax inåt land från The Forgotten Coast.",al={"yetiernas plats","var finns yetier","feral scar vale"}},{q="Hur många skinn vill Pratt ha?",a="Tio stycken, som en bunt.",al={"hur många yetiskinn","antal skinn"}},{q="Vad får jag för skinnen?",a="Pratt erbjuder dig att välja bland lädervarorna Pratt har tillverkat i utbyte mot bunten.",al={"vad ger pratt","betalning för kvalitetsmärket"}}},fp="19,157,18.249.0,9.138.0,29.254.1,28.59.0,29.107.0,31.26.0,28.91.0"}
P.entries["quest:2822"] = {n="The Mark of Quality",s="I Camp Mojache anser läderarbetaren Jangdor Swiftstrider att kvalitet aldrig får kompromissas. Jangdor har hittat tjocka yetiskinn och vill ha en bunt med tio.",h="I Camp Mojache anser läderarbetaren Jangdor Swiftstrider att kvalitet aldrig får kompromissas.",kw={"camp mojache","feral scar vale","feralas","the forgotten coast","jangdor swiftstrider","läderarbete","tjockt yetiskinn","yeti"},sec={{t="En fråga om stolthet",b="Jangdor Swiftstrider är stolt över sitt läderarbete och säger att kvalitet aldrig får kompromissas. På sistone har Jangdor upptäckt tjocka yetiskinn. Yetier hör hemma i Feralas och finns ofta väster om Camp Mojache i Feral Scar Vale, strax innanför The Forgotten Coast."},{t="Erbjudandet",b="För en bunt med tio skinn låter Jangdor dig välja en av lädervarorna som Jangdor har tillverkat. Ta med dem tillbaka till Camp Mojache."},{t="Jangdors tankar om skinnen",b="Jangdor säger att skinnen, efter en särskild behandling, håller lika bra som järn. Det krävs många försök för att hitta rätt garvblandning, men Jangdor är säker på att skinnen kommer att höja kvalitetsnivån ännu mer än förut."}},faq={{q="Vem vill ha skinnen?",a="Jangdor Swiftstrider, en läderarbetare i Camp Mojache i Feralas.",al={"vem ger uppdraget","uppdragsgivare kvalitetsmärket","var finns jangdor"}},{q="Var finns yetierna?",a="Yetier hör hemma i Feralas. Många finns väster om Camp Mojache i Feral Scar Vale, strax innanför The Forgotten Coast.",al={"var finns yetierna","plats för yetiskinn","var ligger feral scar vale"}},{q="Hur många skinn behövs?",a="Tio stycken, som en bunt.",al={"hur många yetiskinn","antal yetiskinn","krav för kvalitetsmärket"}},{q="Vad får jag för skinnen?",a="Jangdor erbjuder dig att välja bland lädervarorna Jangdor har tillverkat i utbyte mot bunten.",al={"vad ger jangdor","betalning för kvalitetsmärket"}}},fp="19,164,17.273.0,9.129.0,31.220.1,28.65.0,29.127.0,28.26.0,28.92.0"}
P.entries["quest:283"] = {n="A Dark Threat Looms",s="A Dark Threat Looms är ett brådskande uppdrag att skydda Loch Modan från katastrof. Alliansens äventyrare ska använda en neutraliserande kemikalie på en utplacerad sprängladdning innan Stonewrought Dam drabbas av förödande skador.",h="A Dark Threat Looms är ett brådskande uppdrag att skydda Loch Modan från katastrof.",kw={"dark iron","disarming mixture","sprängladdning","hinderweir","loch modan","sabotage","stonewrought dam"},ang={["faction:Alliance"]="Genom att hindra dammen från att brista bevaras viktiga landförbindelser mellan Ironforge och de nordliga länderna Arathi och Lordaeron.",["profession:Engineering"]="Att oskadliggöra en instabil spränganordning mitt i ett kolossalt samhällsbygge visar hur viktiga motåtgärder och sprängämnesteori är.",["race:Dwarf"]="Stonewrought Dam är en krönande bedrift inom dvärgarnas stenhantverk. Att skydda den bevarar Ironforges stolthet och trygghet mot Dark Irons illvilja."},sec={{t="Katastrofen avvärjd",b="Den väldiga Stonewrought Dam håller tillbaka The Lochs enorma vattenmassor och reser sig över lågländerna i Wetlands nedanför. När Dark Iron-sabotörer lyckades placera en sprängladdning i dammen hotades hela dalen av förödelse. Disarming Mixture får den flyktiga tunnan att fräsa ut utan fara och avvärjer det omedelbara hotet mot dvärgarnas ingenjörskonst och otaliga liv nedströms."},{t="Hinderweirs lättnad",b="När Chief Engineer Hinderweir VII får rapporten känner Ironforges tillsynsmän på platsen en enorm lättnad. Hinderweir hyllar ingripandet som en stor seger för kungariket Ironforge och Alliansen. Ändå är Dark Irons infiltration så djupt in i Khaz Modan en bister påminnelse om att deras bittra kusiner fortfarande är obevekliga i sin önskan att förstöra Ironforges verk."}},faq={{q="Vad var målet med den här uppdragskedjan?",a="Uppdragskedjan handlar om att avslöja och stoppa en sabotagekomplott från Dark Iron-dvärgar, som planerar att spränga Stonewrought Dam.",al={"sammanfattning av a dark threat looms","stonewrought dam uppdragsmål","varför oskadliggöra bomben"}},{q="Vem placerade sprängladdningen?",a="Dark Iron-dvärgarnas sabotörer placerade sprängtunnan inuti Stonewrought Dam i ett försök att förstöra den väldiga konstruktionen.",al={"vem placerade bomben här","vem attackerade dammen","dark irons dam"}},{q="Vem är Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII är dvärgarnas tillsynsman med ansvar för underhåll, drift och försvar av Stonewrought Dam i Loch Modan.",al={"vem är hinderweir","hinderweirs historia","ingenjör vid dammen"}},{q="Vad skulle ha hänt om dammen brast?",a="Om Stonewrought Dam brast skulle Loch Modans väldiga vattenmagasin tömmas våldsamt, översvämma Wetlands nedströms och svepa bort vägar, bosättningar och viktiga transportleder.",al={"vad händer om dammen förstörs","följder av att dammen brister","damexplosion"}},{q="Hur oskadliggjordes sprängladdningen?",a="En särskilt framtagen Disarming Mixture hälldes över sprängladdningen och fick kruttunnan att fräsa ut säkert innan den kunde detonera.",al={"hur stoppades bomben","disarming mixture","hur oskadliggör man sprängladdningen"}},{q="Är Stonewrought Dam säker nu?",a="Den omedelbara detonationen förhindrades och dammen räddades, men Hinderweir påpekar att försvaret bara är säkert för tillfället, eftersom Dark Iron-agenter fortsätter att hota regionen.",al={"är dammen säker","är dark iron borta","är dammen säker för alltid"}}},fp="19,157,19.331.0,19.282.1,38.115.0,33.96.0,37.143.0,42.169.0,31.137.1,33.176.1"}
P.entries["quest:2844"] = {n="The Giant Guardian",s="Rockbiter, en jätte, skulle hålla ett öga på sin lilla vän Shay, en Night Elf-flicka, men på något sätt kom hon undan. Orolig och osäker på vad han ska göra ber han dig leta efter henne.",h="Rockbiter, en jätte, skulle hålla ett öga på sin lilla vän Shay, en Night Elf-flicka, men på något sätt kom...",kw={"feralas","jätteväktare","vilsekommen flicka","rockbiter","ruiner","shay","shay leafrunner"},sec={{t="Borta när han vände ryggen till",b="Rockbiter skulle ta hand om Shay. Senast han såg henne promenerade de genom ruinerna strax norr om där han står. Allt var bra tills han vände sig om och upptäckte att hon var borta. Han vet inte vad han ska göra, men han vet att dina ben går mycket snabbare än hans, så han ber dig leta efter henne."},{t="När du hittar henne",b="Shay är glad över att bli hittad. Hon erkänner att hon gått vilse, men kan ändå inte låta bli att påpeka vilken vacker plats det här är."}},faq={{q="Vem letar Rockbiter efter?",a="En liten Night Elf-flicka som heter Shay, hans vän som han skulle hålla ett öga på.",al={"vem är shay","vem är den försvunna flickan","vem gick vilse"}},{q="Var sågs Shay senast?",a="Rockbiter säger att de promenerade genom ruinerna strax norr om där han står när hon försvann.",al={"vart tog shay vägen","senaste platsen hon sågs","var ligger ruinerna"}},{q="Varför ber Rockbiter någon annan att leta?",a="Han är orolig och osäker på vad han ska göra, och tror att dina ben går mycket snabbare än hans.",al={"varför kan rockbiter inte leta","varför skicka en äventyrare"}}},fp="18,187,30.319.0,17.116.1,29.89.0,25.98.0,46.94.0"}
P.entries["quest:2845"] = {n="Wandering Shay",s="När du hittar Shay Leafrunner ber hon dig hjälpa henne tillbaka till sin vän Rockbiter. Hon erkänner att hon alltid vandrar iväg när det finns något att se, men hon har en klocka vars ljud får henne att springa tillbaka.",h="När du hittar Shay Leafrunner ber hon dig hjälpa henne tillbaka till sin vän Rockbiter.",kw={"eskort","feralas","jätteväktaren","rockbiter","shay leafrunner","shays klocka"},sec={{t="En lättdistraherad flicka",b="Shay vill hitta tillbaka till Rockbiter, som skulle hålla uppsikt över henne. Hon erkänner att hon brukar vandra iväg då och då, eftersom det finns så mycket att se och hon blir distraherad."},{t="Klockan i kistan",b="Shay säger att en sak alltid fångar hennes uppmärksamhet. I en kista bredvid henne ligger en klocka som hon håller kär, och hon älskar dess ljud. Hon lovar att om hon vandrar iväg får du henne att springa tillbaka genom att ringa i den. Du får bära klockan, och hon hoppas att du tar henne till Rockbiters läger."}},faq={{q="Till vem försöker Shay Leafrunner ta sig tillbaka?",a="Till sin vän Rockbiter, som skulle hålla uppsikt över henne. Du ska ta henne till hans läger.",al={"vem är rockbiter","shays vän","vart går shay"}},{q="Varför vandrar Shay iväg?",a="Hon säger att det finns så mycket att se att hon blir distraherad.",al={"varför är shay vilse","hur gick shay vilse","varför vandrade shay iväg"}},{q="Hur hindrar jag Shay från att gå vilse?",a="Shays klocka ligger i en kista bredvid henne. Hon älskar ljudet och lovar att om hon vandrar iväg får du henne att springa tillbaka genom att ringa i den.",al={"hur styr man shay","shays klocka","vad gör klockan"}},{q="Vad kommer före det här?",a="Det följer efter The Giant Guardian, där Rockbiter skickar dig för att leta efter Shay.",al={"föregående uppdrag","jätteväktaren","vad leder till wandering shay"}}},fp="14,202,24.194.0,21.285.0,45.88.0,25.66.0,33.133.0,23.77.0"}
P.entries["quest:2862"] = {n="War on the Woodpaw",s="I Camp Mojache kallar Hadoken Swiftstrider gnollerna ett ständigt hot mot själva lägret, och anfallen har blivit allt hätskare på sistone. Hadoken ber dig samla in tio Woodpaw Gnoll Manes för att minska deras antal.",h="I Camp Mojache kallar Hadoken Swiftstrider gnollerna ett ständigt hot mot själva lägret, och anfallen har...",kw={"blixtanfall","camp mojache","feralas","gnoller","hadoken swiftstrider","manar","woodpaw"},sec={{t="Ett hot mot lägret",b="För Hadoken spelar det ingen roll om gnollerna hör hemma i Feralas. Om lägret inte står fast, varnar han, kommer det att drivas bort från hela regionen. Eftersom anfallen mot lägret blivit allt hätskare vill han minska deras antal och erbjuder generös betalning för tio Woodpaw Gnoll Manes."},{t="Hadokens svar",b="Hadoken kallar manarna en bra början. Han har bett andra om samma sak; många har kämpat mot gnollerna förut, och tidigare insatser höll dem tillbaka. På sistone har gnollerna mycket oftare trängt norrut in i området där lägret har inflytande, och deras anfall har blivit vilda, nästan desperata. Hadoken säger att han har en plan som kanske kan lösa problemet."}},faq={{q="Vem erbjuder denna belöning i Feralas?",a="Hadoken Swiftstrider i Camp Mojache.",al={"vem ger uppdraget war on the woodpaw","var lämnar man in war on the woodpaw","uppdragsgivare war on the woodpaw"}},{q="Varför riktar Camp Mojache in sig på Woodpaw-gnollerna?",a="Hadoken ser dem som ett ständigt hot mot lägret, med allt hätskare anfall, och fruktar att lägret kommer att drivas bort från hela regionen om det inte står fast.",al={"varför slåss mot woodpaw","woodpaw-problemet","varför anfaller gnollerna"}},{q="Vilket bevis kräver Hadoken Swiftstrider?",a="Tio Woodpaw Gnoll Manes.",al={"vilka föremål behövs till war on the woodpaw","woodpaw-uppdragsföremål","vad ska jag ta med till hadoken"}}},fp="18,202,20.301.0,18.345.1,34.37.0,49.170.0,45.24.0"}
P.entries["quest:2863"] = {n="Alpha Strike",s="Hadoken Swiftstrider har en plan för att bryta dödläget med Woodpaw-gnollerna: fälla flera av deras ledare, som kallar sig Alphas, efter varandra. Hadoken vill att du utför planen.",h="Hadoken Swiftstrider har en plan för att bryta dödläget med Woodpaw-gnollerna: fälla flera av deras ledare...",kw={"alpha strike","feralas","gnoller","hadoken swiftstrider","woodpaw","woodpaw-alpha"},sec={{t="Fem Alphas på en timme",b="Hadoken resonerar att om gnollernas ledare, som kallar sig Alphas, faller en efter en, kommer deras led förmodligen att hamna i kaos. Det kan också visa att Horden kan och kommer att förgöra dem. Du ska göra som Hadoken vill: fäll fem Alphas inom en timme, annars består dödläget."},{t="Efteråt",b="Hadoken räknar med att färre gnoller och dödade ledare får gnollerna att tveka innan de stormar lägret. Men problemen är inte över. Hadoken vill ta reda på vad som har drivit gnollerna till sådan frenesi, och göra det innan de samlar sig igen."}},faq={{q="Vem ger det här uppdraget?",a="Hadoken Swiftstrider, som hanterar dödläget mot Woodpaw-gnollerna för Horden.",al={"vem ger alpha strike","hadoken swiftstrider","uppdragsgivare"}},{q="Varför är tidsgränsen en timme?",a="Planen fungerar bara om Alphas faller i snabb följd, eftersom det bör kasta gnollernas led i kaos. Fem måste falla inom en timme.",al={"varför en timme","varför i snabb följd","alpha strike tidsgräns"}},{q="Vad är Alphas?",a="De är ledare bland Woodpaw-gnollerna, som kallar sig Alphas.",al={"woodpaw-alphas","gnoll-alphas","vilka är målen"}},{q="Hur många Alphas måste jag döda?",a="Fem, alla inom en timme, innan du återvänder till Hadoken Swiftstrider.",al={"hur många alphas","antal alphas"}}},fp="12,213,22.306.0,10.244.1,21.97.0,23.150.0,20.70.0,28.68.0"}
P.entries["quest:2866"] = {n="The Ruins of Solarsal",s="Shandris Feathermoon berättar att Ruins of Solarsal i söder nu kryllar av Hatecrest naga. Du får i uppdrag att gå genom ruinerna och lägga märke till allt som verkar avvikande.",h="Shandris Feathermoon berättar att Ruins of Solarsal i söder nu kryllar av Hatecrest naga.",kw={"feathermoon stronghold","feralas","lusthus","glyfer","hatecrest","naga","shandris feathermoon","solarsal"},sec={{t="Naga bland de gamla stenarna",b="Ruins of Solarsal är mycket äldre än vår tid. Shandris säger att de först undersökte platsen, inte fann något av betydelse och lät den vara. Men alldeles nyligen har Hatecrest naga tagit över den i oroväckande antal. Först såg det ut som upptakten till ett angrepp, ett hot som fortfarande är möjligt, men Shandris tror att något annat kan vara på gång. Du ska gå genom ruinerna och lägga märke till allt som verkar avvikande."},{t="Det som sticker ut",b="När du ser dig omkring vid lusthuset märker du att det skiljer sig från stenverket runtomkring. Det är uppenbart nyare. Små glyfer löper längs sidorna i ett återkommande mönster, men ingen vet var de kommer ifrån eller vad de betyder. Stenen känns varm när du rör vid den."}},faq={{q="Var ligger Ruins of Solarsal?",a="De ligger söder om Shandris Feathermoon.",al={"ruins of solarsal plats","var ligger solarsal","var hittar man solarsal"}},{q="Varför oroar sig Shandris Feathermoon för ruinerna?",a="Hatecrest naga har nyligen intagit ruinerna i oroväckande antal. Först såg det ut som förberedelser för ett angrepp, och det är fortfarande möjligt, men Shandris tror att något annat kan vara på gång.",al={"varför skickas jag till solarsal","shandris feathermoon solarsal anledning","varför undersöka solarsal"}},{q="Vad var Ruins of Solarsal innan naga anlände?",a="Ruinerna är mycket äldre än vår tid. Shandris säger att de först undersöktes, att inget av betydelse hittades och att de sedan lämnades i fred.",al={"solarsals historia","vad är solarsal"}},{q="Vilka naga finns i ruinerna?",a="Hatecrest naga.",al={"vem finns vid solarsal","solarsals fiender","naga-stam i solarsal"}}},fp="21,195,22.435.0,15.268.1,32.46.0,54.201.0,56.135.0,28.19.0"}
P.entries["quest:2867"] = {n="Return to Feathermoon Stronghold",s="Ditt sökande ledde dig till ett märkligt lusthus mitt i Ruins of Solarsal. Nu är det dags att återvända till Feathermoon Stronghold och berätta om det för general Shandris Feathermoon.",h="Ditt sökande ledde dig till ett märkligt lusthus mitt i Ruins of Solarsal.",kw={"feathermoon stronghold","feralas","hatecrest","naga","ruins of solarsal","shandris feathermoon","lusthuset i solarsal"},sec={{t="Med rapporten hem",b="General Shandris Feathermoon väntar i Feathermoon Stronghold på att höra om det märkliga lusthuset du upptäckte i ruinerna. Ta dig tillbaka till fästet med dina fynd."},{t="När du återvänder",b="Shandris anser att din rapport om lusthuset är oroande. Även om naga aldrig hade för avsikt att anfalla, är det ett dåligt tecken att de stannar kvar inför framryckningen in i Feralas. Fästet behöver verkligen mer hjälp mot Hatecrest naga, och Shandris erbjuder dig fler uppgifter om du är villig."}},faq={{q="Vem ska jag rapportera till efter ruinerna?",a="General Shandris Feathermoon i Feathermoon Stronghold.",al={"vem ska jag lämna det här till","vem vill ha rapporten","var lämnar jag in return to feathermoon stronghold"}},{q="Vad ska jag rapportera?",a="Om det märkliga lusthuset mitt i Ruins of Solarsal.",al={"vad ska jag berätta för shandris","vad hittades i solarsal"}},{q="Vad kommer före det här?",a="Det följer på The Ruins of Solarsal, där Shandris skickade dig för att utforska ruinerna och undersöka naga där.",al={"föregående uppdrag","vad leder hit"}}},fp="32,180,24.192.0,14.279.1,35.56.0,21.69.0,23.108.0"}
P.entries["quest:2869"] = {n="Against the Hatecrest",s="Latronicus Moonspear vid Feathermoon Stronghold vill möta Hatecrest-nagorna direkt i stället för att vänta på dem. Han ber dig om tio Hatecrest Scales i gott skick.",h="Latronicus Moonspear vid Feathermoon Stronghold vill möta Hatecrest-nagorna direkt i stället för att vänta på...",kw={"against the hatecrest","feathermoon stronghold","feralas","hatecrest","hatecrest-nagafjäll","latronicus moonspear","nagor","sardor isle"},sec={{t="Agera innan det är för sent",b="Vad nagorna än har i görningen utgår Latronicus Moonspear från att de förr eller senare kommer att försöka ta ön för egen del, och att man måste agera offensivt innan det är för sent. Han vill ha tio Hatecrest Scales i gott skick och förväntar sig att du själv tar reda på hur du får tag på dem. Han räknar med att det försvagar nagornas närvaro på Sardor Isle och att det blir ditt första möte med nagorna i strid."},{t="Fred och plikt",b="Latronicus är tydlig med att nattalver inte är krigshetsare och värnar om fred och harmoni. Det betyder inte att de låter sina egna intressen stå oskyddade, säger han, och att skydda dem är hans plikt gentemot General Feathermoon och fästet."},{t="Efteråt",b="Latronicus säger att fjällen är mer än godtagbara och tänker skicka dem till Pratt, ifall något användbart kan tillverkas av dem. Han har också något annat du ska göra."}},faq={{q="Vem ger uppdraget och var?",a="Latronicus Moonspear vid Feathermoon Stronghold ber om fjällen och tar emot dem.",al={"vem startar against the hatecrest","latronicus moonspears plats","var lämnar man in against the hatecrest"}},{q="Varför vill Latronicus Moonspear ha Hatecrest-fjäll?",a="Han utgår från att nagorna förr eller senare kommer att försöka säkra Sardor Isle och vill att man agerar offensivt först. Att samla in fjäll innebär att försvaga dem där.",al={"varför döda hatecrest","vad hatecrest-fjäll används till","varför samla in nagafjäll"}},{q="Hur många fjäll behövs?",a="Tio Hatecrest Scales i gott skick.",al={"hur många fjäll","antal fjäll"}},{q="Var finns Hatecrest-nagorna?",a="Latronicus talar om en närvaro av nagor på Sardor Isle.",al={"hatecrests plats","var hittar man hatecrest","nagor på sardor isle"}}},fp="21,170,28.398.0,14.241.0,10.189.1,31.92.0,52.148.0,27.40.0,35.52.0"}
P.entries["quest:287"] = {n="Frostmane Hold",s="Frostmane Hold är ett spaningsuppdrag för Alliansen som Senir Whitebeard ger dig i Kharanos. Efter att ha spårat de fientliga Frostmane-trollen till deras hårt bevakade grottfäste nära Iceflow Lake anlitar Senir äventyrslystna spejare. De ska våga sig in, döda deras huvudjägare och samla in viktig information till hans spaningsrapporter.",h="Frostmane Hold är ett spaningsuppdrag för Alliansen som Senir Whitebeard ger dig i Kharanos.",kw={"brewnall village","dun morogh","frostmane headhunter","frostmane hold","istroll","iceflow lake","kharanos","senir whitebeard","the reports"},ang={["faction:Alliance"]="När Dun Morogh är säkrat kan bergsvägarna mellan Ironforge och grannrikena hållas fria från fientliga stamöverfall.",["race:Dwarf"]="Frostmane-trollen utmanar Ironforges herravälde över Dun Moroghs snöiga bergstoppar. Att spana in deras främsta grottfäste är avgörande för rikets försvar.",["race:Gnome"]="Efter Gnomeregans fall har gnomer bosatt sig runtom i Dun Morogh och Kharanos. Om Frostmane-trollens angrepp hejdas hålls de bräckliga försörjningslederna för flyktingar säkra."},sec={{t="En spejare på efterkälken",b="Bergsbestigaren och spejaren Senir Whitebeard är stationerad i Kharanos och har fått i uppdrag att hålla uppsikt över hotet från Frostmane-trollen i Dun Morogh. Han lyckades spåra de aggressiva stammarna till deras främsta grottboplats sydväst om Brewnall Village, men mängden beväpnade troll fick honom att tveka. Senir vill inte gå in ensam och ligger långt efter med sina officiella rapporter. Därför anlitar han äventyrare på genomresa för att utforska de isiga grottgångarna åt honom."},{t="In i grottan",b="Fästet är uthugget i de västra bergstopparna med utsikt över Iceflow Lake. Det är en iskall skans fylld av fientliga istroll. För att slutföra Senirs uppdrag måste spejarna kämpa sig djupt in genom gångarna under jord, slå ut de vildsinta Frostmane Headhunters som håller till längs avsatserna och kartlägga grottans inre. Överlever du utforskningen får Senir den viktiga information han behöver för att färdigställa sina resultat åt Ironforges militära befälhavare."}},faq={{q="Var ligger Frostmane Hold?",a="Frostmane Hold är en grotta sydväst om Brewnall Village, längst västerut i Dun Morogh. Från Kharanos följer du vägen norrut till bron. Följ den frusna floden västerut förbi Iceflow Lake till Brewnall Village och fortsätt sedan sydväst upp i bergen.",al={"hitta frostmane hold","var ligger grottan","frostmane holds plats"}},{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är en dvärgspejare som är stationerad utanför Thunderbrew Distillery i Kharanos. Han håller uppsikt över hot i Dun Morogh och sammanställer underrättelserapporter om de aggressiva Frostmane-trollen.",al={"senir whitebeard","vem ger uppdraget","uppdragsgivare i kharanos"}},{q="Varför utforskade inte Senir fästet själv?",a="Senir spanade vid ingången och upptäckte var stammen samlades, men grottan vimlade av så många beväpnade troll att han var rädd för att gå in ensam. Han oroar sig för sin säkerhet och har redan missat sina tidsfrister för spaningen, så han överlåter det farliga uppdraget åt dugliga äventyrare.",al={"varför är senir rädd","varför gick inte senir dit"}},{q="Vilka är Frostmane-trollen?",a="Frostmane är en ursprunglig stam av istroll som hör hemma bland Dun Moroghs snöiga bergskammar. De är bittra fiender till Ironforges dvärgar och gnomer och plundrar ofta handelsvägar, läger och bosättningar från gömda läger runtom i regionen.",al={"frostmane","troll i dun morogh","dun moroghs troll"}},{q="Vad händer när spaningen av fästet är klar?",a="När du återvänder med information om fästets utformning och hur många av deras huvudjägare som stupat färdigställer Senir sin rapport. Sedan ber han dig genast att leverera de brådskande dokumenten till sina överordnade i Dun Morogh.",al={"nästa uppdrag","vad händer efter frostmane hold","uppdraget the reports"}},{q="Hur långt in i grottan måste du gå?",a="Du måste ta dig långt förbi ingången och in i de inre kamrarna tills grottans utformning har kartlagts och fem Frostmane Headhunters har dödats. Då har grottans djup undersökts grundligt.",al={"utforska hela frostmane hold","utlösare för grottutforskning"}}},fx={["889a57f0"]={q="Varför vill Senir Whitebeard att Frostmane Hold utforskas?",a="Senir Whitebeard arbetar med underrättelserapporter om de växande hoten i Dun Morogh. Han har hamnat efter med spaningen och behöver förstahandsinformation om Frostmane-trollens läger för att slutföra sin bedömning åt Ironforge-befälet innan hans överordnade märker något.",al={"varför vill senir få det här gjort","senir whitebeards motiv","varför spana på frostmane hold"}},["860fac70"]={q="Varför skickas du mot Frostmane Headhunters?",a="Frostmane Headhunters utgör det militanta försvaret av Frostmane Hold, de djupa grottorna sydväst om Brewnall Village där de fördrivna trollen har samlats i stora styrkor. Om du dödar dem tunnas deras patruller ut och vägen öppnas för en ordentlig spaning av grottans djup.",al={"vilka är frostmane headhunters","varför döda headhunters","frostmane headhunters uppgift"}}},fp="14,214,23.234.0,20.334.0,32.263.0,24.184.0,42.249.0,29.225.0,52.176.1,41.175.0"}
P.entries["quest:2870"] = {n="Against Lord Shalzaru",s="Latronicus Moonspear vid Feathermoon Stronghold berättar att spejare har identifierat en av de grymmare naga-ättpredatorerna, Lord Shalzaru. Han ber dig stoppa Shalzaru och hämta reliken som naga-herren grävde fram.",h="Latronicus Moonspear vid Feathermoon Stronghold berättar att spejare har identifierat en av de grymmare...",kw={"feathermoon stronghold","feralas","hatecrest","isle of dread","latronicus moonspear","lord shalzaru","mysterious relic","naga","shalzaru"},sec={{t="Nagas befälsordning",b="Nya spejarrapporter har gett Latronicus Moonspear en tydlig bild av hur naga leds. Ättpredatorer finns bland deras led, och det är de som ger order. En av de grymmare är Lord Shalzaru."},{t="En märklig relik",b="Spejare rapporterar att Shalzaru själv grävde fram en märklig relik medan naga grävde i en grotta på Isle of Dread, på andra sidan vattnet och söder om huvudruinerna. Latronicus vill att utgrävningen upphör genom att Shalzaru röjs ur vägen, och vill att Mysterious Relic förs till honom vid Feathermoon Stronghold så att den kan undersökas."},{t="När det är gjort",b="Latronicus tror att Shalzarus fall kommer att lämna naga i oordning ett tag, kanske för gott, och att hotet nu är bättre under kontroll än någonsin tidigare. Sedan har han ytterligare en sak att be dig om."}},faq={{q="Vem är Lord Shalzaru?",a="En av de grymmare naga-ättpredatorerna, identifierad av spejare. Ättpredatorer finns bland nagas led och ger order.",al={"shalzaru","vem är shalzaru","lord shalzaru bakgrund"}},{q="Var finns Lord Shalzaru?",a="Spejare har lokaliserat utgrävningen till en grotta på Isle of Dread, på andra sidan vattnet och söder om huvudruinerna.",al={"var finns shalzaru","shalzarus grottas plats","hitta shalzaru"}},{q="Vad är reliken?",a="En märklig relik som Shalzaru själv grävde fram medan naga grävde. Latronicus vill att den förs till honom så att den kan undersökas.",al={"mysterious relic feralas","vad är reliken","shalzaru relik"}},{q="Var ska jag lämna reliken?",a="Till Latronicus Moonspear i Feathermoon Stronghold.",al={"vem ska ha reliken","lämna in shalzaru"}}},fp="21,219,25.203.0,12.327.0,15.214.1,21.106.0,31.96.0,18.130.0,29.50.0"}
P.entries["quest:2871"] = {n="Delivering the Relic",s="Latronicus Moonspear ber dig bära Mysterious Relic till hans fru, Vestia Moonspear, vid Feathermoon Stronghold. Han kan inte begripa vad föremålet är och hoppas att hon kan säga det.",h="Latronicus Moonspear ber dig bära Mysterious Relic till hans fru, Vestia Moonspear, vid Feathermoon...",kw={"lämna över reliken","feathermoon stronghold","feralas","latronicus moonspear","mysterious relic","vestia moonspear"},sec={{t="En forskares blick",b="Latronicus Moonspear kunde inte begripa föremålet, trots att han hade slagit vad om saken. Hans fru Vestia, säger han, är en uppskattad prästinna i deras samhälle och en av de lärdaste forskarna man kan hitta. Om någon kan lista ut vad reliken är, så är det hon, och de måste få veta. Hon är bara en kort promenad bort och studerar säkert för fullt."},{t="Vestias första intryck",b="Vestia känner till dig som den som har hjälpt General Feathermoon och Latro mot nagorna. Med reliken i händerna bedömer hon vid första anblicken att den inte verkar höra hemma bland ruinerna där den hittades, och att den inte heller är av nagornas slag, utan något mycket mer främmande. Det kommer att ta tid att undersöka den, och när hon är klar kanske hon ber om din hjälp om du är i närheten."}},faq={{q="Vem är Vestia Moonspear?",a="Latronicus Moonspears fru. Latronicus kallar henne en uppskattad prästinna i deras samhälle och en lika lärd forskare som någon annan. Hon finns vid Feathermoon Stronghold.",al={"vestia moonspear","vem är vestia","latros fru"}},{q="Varifrån kommer Mysterious Relic?",a="Det är reliken som Lord Shalzaru upptäckte när nagorna grävde i en grotta på Isle of Dread.",al={"varifrån kom reliken","relikens ursprung","mysterious relics källa"}},{q="Vad vet Latronicus Moonspear om reliken?",a="Inte mycket. Han säger att han inte kunde begripa föremålet, och därför vill han att hans fru ska undersöka det.",al={"vad vet latronicus","latros föremål"}},{q="Vart ska jag ta reliken?",a="Till Vestia Moonspear vid Feathermoon Stronghold. Latronicus säger att hon är alldeles runt hörnet.",al={"vem ska få reliken","vart ska reliken lämnas"}}},fp="20,196,15.344.0,19.362.1,24.153.0,42.98.0,52.109.0,26.91.0"}
P.entries["quest:2872"] = {n="Stoley's Debt",s="\"Sea Wolf\" MacKinley har slagit vad med sin gamle vän Stoley, som sköter baren i Steamwheedle Port, om vems rom som är starkast. Stoley verkar försöka slingra sig, så MacKinley ber dig gå och prata med honom.",h="\"Sea Wolf\" MacKinley har slagit vad med sin gamle vän Stoley, som sköter baren i Steamwheedle Port, om vems...",kw={"bilgerom","booty bay","mackinley","rom","steamwheedle port","stoley","tanaris","vad"},sec={{t="En fråga om rom och pengar",b="Stoley är skyldig \"Sea Wolf\" MacKinley en mycket speciell flaska rom. Stoley skröt om att rommen i Steamwheedle Port är starkare än allt i Booty Bay och sa att skulden skulle fördubblas om MacKinley smakade på den och inte höll med. Nu tror MacKinley att Stoley har tappat modet att lämna över flaskan, men MacKinley backar aldrig från ett vad. Du ombeds gå och prata med Stoley i baren i Steamwheedle Port."},{t="Stoleys svar",b="Stoley är inte rädd för att lämna över Steamwheedle Bilge Rum, säger han. Problemet är att det inte finns någon rom kvar att ge bort."}},faq={{q="Vem är \"Sea Wolf\" MacKinley?",a="En vän till Stoley som har slagit vad med honom om vems rom som är starkast. Han nämner Booty Bay som platsen att jämföra den med.",al={"vem är mackinley","sea wolf mackinley","vem ger stoleys skuld"}},{q="Var finns Stoley?",a="Stoley är bartendern i Steamwheedle Port i Tanaris.",al={"var finns stoley","stoleys plats","hitta stoley"}},{q="Vad slog Stoley vad med MacKinley om?",a="Stoley skröt om att rommen i Steamwheedle Port slår allt i Booty Bay. Om MacKinley smakade på den och inte höll med, skulle Stoley fördubbla pengarna han är skyldig honom.",al={"vad går vadet ut på","vilket vad","stoleys vad"}}},fp="13,202,24.414.0,15.120.1,28.127.0,24.54.0,40.157.0"}
P.entries["quest:2873"] = {n="Stoley's Shipment",s="Stoley har fått slut på rom och är skyldig en vän pengar efter ett vad. Captain Cuergo stal den senaste lasten och förvarar den i piratstaden med murar i söder, så Stoley ber dig hämta tillbaka den.",h="Stoley har fått slut på rom och är skyldig en vän pengar efter ett vad.",kw={"cuergo","lost rigger cove","mackinley","rom","last","steamwheedle port","stoley","tanaris"},sec={{t="En stulen last",b="Stoley har inget kvar av rommen han lovade \"Sea Wolf\" MacKinley från Booty Bay för att reglera deras vad. Captain Cuergo stal den senaste lasten och har gömt den i piratstaden med murar i söder, Lost Rigger Cove. Stoley ber dig hitta rommen och lämna tillbaka den, så att han kan visa att Kalimdors drycker är mycket bättre än allt som serveras i Booty Bay."},{t="Där den förvaras",b="Inne i piratstaden står rommen i lådor på husets övre våning i nordväst."}},faq={{q="Vem är Stoley?",a="Stoley finns i Steamwheedle Port i Tanaris och är skyldig \"Sea Wolf\" MacKinley i Booty Bay rom för att reglera ett vad.",al={"stoley","vem lämnar stoleys last","stoley tanaris"}},{q="Varför vill Stoley ha tillbaka lasten?",a="Captain Cuergo stal hans senaste romlast. Stoley behöver den för att reglera ett vad med MacKinley och bevisa att Kalimdors sprit är bättre än Booty Bays.",al={"varför rom","stoleys motiv","vad är stoleys last"}},{q="Var gömde piraterna rommen?",a="I piratstaden med murar i söder, Lost Rigger Cove, i lådor på övervåningen i huset längst i nordväst.",al={"var finns stoleys rom","var finns lasten","rom i lost rigger cove"}},{q="Vem är Captain Cuergo?",a="Han stal Stoleys senaste romlast och förvarar den i piratstaden med murar i söder.",al={"cuergo","captain cuergo"}},{q="Var passar det här steget in i kedjan?",a="Det följer på Stoley's Debt.",al={"stoleys last kedja","vad kommer efter stoley's debt"}},{q="Vem är \"Sea Wolf\" MacKinley?",a="Han finns i Booty Bay och slog vad med Stoley om vems rom som är bäst.",al={"sea wolf mackinley","mackinley booty bay"}}},fp="17,187,17.354.0,16.96.0,14.109.0,39.148.0,35.113.0,22.100.0,38.25.0,28.73.0"}
P.entries["quest:2874"] = {n="Deliver to MacKinley",s="Stoley ger dig en flaska Steamwheedle bilgerom åt MacKinley, Booty Bays \"Sea Wolf\", så att MacKinley ska sluta tro på Booty Bays sprit.",h="Stoley ger dig en flaska Steamwheedle bilgerom åt MacKinley, Booty Bays \"Sea Wolf\", så att MacKinley ska...",kw={"booty bay","mackinley","sea wolf mackinley","steamwheedle bilgerom","stoley","stoley's debt","stoley's shipment","tanaris"},sec={{t="En flaska att ta med",b="Efter hjälpen med lasten ger Stoley dig en flaska Steamwheedle bilgerom. Du ska ta den till MacKinley i Booty Bay, så att han äntligen kan släppa sina tokiga föreställningar om spriten där."},{t="MacKinleys dom",b="MacKinley smakar på rommen och kan inte tro hur hemsk den är, till sin stora förtjusning. Stoley höll sitt löfte om bilgerommen, så han behöver inte betala pengarna han är skyldig. MacKinley säger att den är tjock som grus och bränner som lava."}},faq={{q="Vem ger dig flaskan?",a="Stoley i Steamwheedle Port.",al={"vem startar deliver to mackinley","uppdragsgivare för deliver to mackinley"}},{q="Vem tar emot romflaskan?",a="\"Sea Wolf\" MacKinley i Booty Bay.",al={"vart ska jag ta flaskan","vem får rommen","mackinleys plats"}},{q="Vilken sorts alkohol ska levereras?",a="En flaska Steamwheedle bilgerom.",al={"vilken rom är det","vilken sprit ger stoley"}},{q="Var passar det här steget in i kedjan?",a="Det följer efter Stoley's Debt och Stoley's Shipment.",al={"vad kommer före deliver to mackinley","uppdragskedjan deliver to mackinley"}}},fp="20,155,17.216.0,19.224.1,25.29.0,31.35.0,40.35.0,38.47.0"}
P.entries["quest:2875"] = {n="WANTED: Andre Firebeard",s="En efterlysning i Gadgetzan och Steamwheedle Port pekar ut piraten Andre Firebeard, anklagad för brott mot Steamwheedle och Gadgetzan. Hans huvud, överlämnat till Security Chief Bilgewhizzle i Steamwheedle Port, räknas som ett bindande kontrakt.",h="En efterlysning i Gadgetzan och Steamwheedle Port pekar ut piraten Andre Firebeard, anklagad för brott mot...",kw={"andre firebeard","bilgewhizzle","gadgetzan","piratläger","steamwheedle port","tanaris","efterlysning"},sec={{t="Dekretet",b="Efterlysningen kallar Andre Firebeard en avskyvärd pirat, anklagad för brott mot Steamwheedle och Gadgetzan. Det styrande rådet har beslutat att den som läser den får använda dödligt våld för att fånga Andre och dem som hjälper honom. Han finns i piratlägret en bit söderut längs kusten från Steamwheedle Port, där han står vid en lägereld innanför murarna."},{t="Huvudet som ställföreträdare",b="Ett ytterligare dekret säger att om Andre är död eller på annat sätt inte kan närvara när förhandlingen äger rum, kan hans huvud företräda honom. Överlämnat till Security Chief Bilgewhizzle i Steamwheedle Port räknas det som ett bindande kontrakt."},{t="Betalningsvillkor",b="Bilgewhizzle är nöjd med att Andre trots allt kommer att ställas inför rätta. Betalningen utfärdas när du skriver under, och Bilgewhizzle avfärdar det finstilta som harmlöst och tillägger att det är för litet för att kunna läsas med något förstoringsglas."}},faq={{q="Vem är Andre Firebeard?",a="En pirat som anklagas för brott mot Steamwheedle och Gadgetzan.",al={"andre firebeard","vem är andre","firebeard tanaris"}},{q="Var finns efterlysningen?",a="I Gadgetzan och vid Steamwheedle Port.",al={"var hämtar man uppdraget","efterlysningens plats","efterlysning på andre firebeard"}},{q="Var finns Andre Firebeard?",a="Vid en lägereld innanför murarna i piratlägret, en bit söderut längs kusten från Steamwheedle Port.",al={"firebeards plats","var finns firebeard","hitta andre firebeard"}},{q="Vem tar emot huvudet när Andre har omhändertagits?",a="Security Chief Bilgewhizzle i Steamwheedle Port.",al={"vem lämnar jag in firebeard till","bilgewhizzles plats","var lämnar man in firebeards huvud"}},{q="Varför krävs hans huvud?",a="Ett dekret låter det företräda honom om han är död eller på annat sätt inte kan närvara när förhandlingen äger rum.",al={"varför hans huvud","huvudet som ställföreträdare","ställföreträdare vid rättegång"}}},fp="23,277,10.363.0,17.224.0,16.216.1,23.62.0,37.38.0,33.105.0,47.50.0,25.101.0"}
P.entries["quest:2876"] = {n="Ship Schedules",s="En skriftrulle redovisar fartyg som seglar mellan Steamwheedle Port och Booty Bay, med markeringar vid vissa resor. Den bör lämnas till en myndighetsperson i Steamwheedle Port.",h="En skriftrulle redovisar fartyg som seglar mellan Steamwheedle Port och Booty Bay, med markeringar vid vissa...",kw={"bilgewhizzle","booty bay","pirater","fartygens tidtabeller","steamwheedle port","tanaris"},sec={{t="Skriftrullen",b="Skriftrullen listar frakterna som seglar mellan Steamwheedle Port och Booty Bay, både de som redan gått och de som ska gå, tillsammans med fartygens namn. Vissa resor är markerade med ett stort X, och andra har anteckningar om byte att ta eller en hård strid. Den är avsedd för någon med myndighet i Steamwheedle Port."},{t="Hamnens reaktion",b="Security Chief Bilgewhizzle finner att datumen och tiderna i tidtabellen stämmer och oroar sig för vad en piratkapten skulle kunna göra med den. När du berättar att du tog den från en pirat kallar Bilgewhizzle det oroande nyheter, tackar dig och är glad att piraten är död."}},faq={{q="Vad står det i tidtabellen?",a="Fartygens namn och tiderna för resor mellan Steamwheedle Port och Booty Bay, både tidigare och kommande, med stora X vid vissa resor och anteckningar om byte eller en hård strid vid andra.",al={"vad står det i fartygens tidtabell","text i fartygens tidtabell","fraktanteckningar"}},{q="Vem behöver se det här dokumentet?",a="Någon med myndighet i Steamwheedle Port. Security Chief Bilgewhizzle är den som tar emot det.",al={"vem ska jag lämna tidtabellen till","lämna in fartygens tidtabell","vart ska tidtabellen"}}},fp="14,165,10.312.0,19.257.1,32.190.0,31.95.0"}
P.entries["quest:2877"] = {n="Skulk Rock Clean-up",s="Fraggar Thundermantle från Aerie Peak vill ha ett röjarlag till området kring Skulk Rock, som Horden övergav och som nu är fullt av grönt slem och jadefärgade oozes. Wildhammarna har planer för området när det väl är rensat.",h="Fraggar Thundermantle från Aerie Peak vill ha ett röjarlag till området kring Skulk Rock, som Horden övergav...",kw={"aerie peak","fraggar thundermantle","grönt slem","the hinterlands","jade ooze","skulk rock","wildhammer"},sec={{t="En fråga om territorium",b="Wildhammarna minns det förflutna bättre än sina bröder i Ironforge, och Fraggar Thundermantle säger att man blir vänner här genom att smutsa ner händerna. Horden övergav sina ställningar kring Skulk Rock i The Hinterlands, och otäckt grönt slem och jadefärgade oozes har sedan dess tagit över dem. Wildhammarna har planer för marken, men först måste en öppning röjas i angreppet."},{t="Röj marken",b="Döda tio gröna slem och tio jadefärgade oozes. Därefter väntar Fraggar vid Aerie Peak på rapporten."}},faq={{q="Vem är Fraggar Thundermantle?",a="Fraggar Thundermantle är en Wildhammer vid Aerie Peak i The Hinterlands som vill få Skulk Rock rensat.",al={"vem ger uppdraget att röja skulk rock","fraggar thundermantle"}},{q="Varför vill Wildhammarna att Skulk Rock röjs?",a="Horden övergav sina ställningar kring Skulk Rock, och grönt slem och jadefärgade oozes har tagit över dem. Wildhammarna har planer för området, men behöver först ett röjarlag.",al={"varför döda oozes","wildhammarnas planer för skulk rock"}},{q="Vilka varelser håller till vid Skulk Rock?",a="Grönt slem och jadefärgade oozes har tagit över de gamla Horde-ställningarna där.",al={"fiender vid skulk rock","vad finns vid skulk rock"}},{q="Varför nämner Fraggar Ironforge?",a="Fraggar säger att Wildhammarna minns det förflutna bättre än sina bröder i Ironforge och att man blir vänner här genom att smutsa ner händerna.",al={"skillnad mellan wildhammarna och ironforge","fraggar och ironforge"}}},fp="19,222,21.380.0,19.114.0,29.104.0,47.169.0,35.72.0,36.145.0"}
P.entries["quest:2879"] = {n="The Stave of Equinex",s="Troyas Moonbreeze tror att hans stav kan vara Stave of Equinex, en nyckel till ett monument i Ruins of Ravenwind. För att ta reda på det ska du samla in essensen från fyra lågor som fortfarande brinner bland ruinerna.",h="Troyas Moonbreeze tror att hans stav kan vara Stave of Equinex, en nyckel till ett monument i Ruins of...",kw={"byltan","dream bough","equinex monolith","feralas","imbel","lahassa","ruins of ravenwind","samha","stave of equinex","troyas moonbreeze"},sec={{t="En nyckel till monoliten",b="När du återvänder till Troyas Moonbreeze säger han att hans stav kan vara Stave of Equinex, som faktiskt är en nyckel till Equinex Monolith. Monoliten står i Ruins of Ravenwind. Bland ruinerna brinner fortfarande fyra lågor, som heter Samha, Imbel, Byltan och Lahassa. Var och en ger en essens, och vid monoliten ska du använda alla fyra för att ladda staven med kraft. Om det verkligen är Stave of Equinex öppnas monoliten och lämnar ifrån sig en helig artefakt."},{t="Vid stenen",b="Den laddade staven är nästan omöjlig att hålla i, och dess kraft mullrar genom dig. Du sträcker dig mot monolitens kalla yta, och en liten dörr öppnas så att du kan ta det som finns därinne. Ljusstrålar strömmar ut runt stenen."}},faq={{q="Var finns Equinex Monolith?",a="Väster om Dream Bough på fastlandet, i ruinerna vid Ravenwind.",al={"equinex monolith plats","var finns monoliten","hitta equinex monolith"}},{q="Vilka är de fyra lågorna jag behöver?",a="Samha, Imbel, Byltan och Lahassa, lågor som fortfarande brinner i Ruins of Ravenwind. Du samlar in essensen från var och en.",al={"fyra lågor","lågornas namn feralas","ravenwinds lågor"}},{q="Vad är Stave of Equinex till för?",a="Troyas Moonbreeze säger att den är en nyckel till att låsa upp Equinex Monolith, där en helig artefakt finns.",al={"vad gör staven","stave of equinex syfte","varför ladda staven"}},{q="Var ska jag ladda staven med kraft?",a="Stå vid Equinex Monolith och använd de fyra lågornas essenser.",al={"var använda essenserna","plats att ladda staven"}}},fp="20,203,22.463.0,12.229.1,38.64.0,32.115.0,33.101.0,30.78.0"}
P.entries["quest:288"] = {n="The Third Fleet",s="Utanför Deepwater Tavern i Menethil Harbor dränker First Mate Fitzsimmons sina minnen i dvärgarnas mjöd. Han är den enda överlevande från Kul Tiras tredje flotta, en stolt sjöstyrka som förintades utanför Wetlands kust av röda drakar förslavade av orcher under det andra kriget.",h="Utanför Deepwater Tavern i Menethil Harbor dränker First Mate Fitzsimmons sina minnen i dvärgarnas mjöd.",kw={"deepwater tavern","doomed fleet","dragonmaw","fitzsimmons","kul tiras","menethil harbor","röda drakar","tredje flottan","wave mistress","wetlands"},ang={["faction:Alliance"]="När Fitzsimmons berättar om Wave Mistress undergång påminns alliansens försvarare om de kvardröjande ärr som hordens drakryttare lämnade efter sig i Khaz Modan.",["race:Dwarf"]="Grim Batol kastade sin skugga över hela Khaz Modan, och drakarna som föddes i dess djup härjade i dvärgarnas länder och bland människornas allierade.",["race:Human"]="Tredje flottans undergång är en bitter påminnelse om de katastrofala sjöslag som Kul Tiras och alliansen utkämpade mot Dragonmaw."},sec={{t="En sjömans sorg",b="First Mate Fitzsimmons tillbringar dagarna hopsjunken utanför Deepwater Tavern i Menethil Harbor, där han försöker lindra en ändlös baksmälla och minnen han inte kan skaka av sig. En gång var han officer ombord på Wave Mistress, ett linjeskepp under Kul Tiras sjöfartsbanner. Nu byter han sina mörka minnen mot kannor med dvärgarnas mjöd. Den som köper honom ännu en drink får höra ett ögonvittnesskildring av en av det andra krigets mest förödande massakrer till sjöss."},{t="Eld över vågorna",b="Under det andra kriget seglade tredje flottan längs Khaz Modans stränder när katastrofen slog till från skyn. Dragonmaw-klanen hade kuvat den röda drakflykten vid Grim Batol och släppte lös drakeld över de intet ont anande krigsfartygen. Fitzsimmons minns hur hjälplösa träskrov brann under väldiga eldpelare och drog hela besättningar ner i djupet. Fitzsimmons ensam överlevde och spolades i land. Hans stupade bröder blev kvar i den vattengrav som nu kallas Doomed Fleet."}},faq={{q="Vem är First Mate Fitzsimmons?",a="Han är en gammal sjöman som dricker bort sitt trauma utanför Deepwater Tavern i Menethil Harbor. Förr var han styrman på krigsfartyget Wave Mistress från Kul Tiras. Han är den enda kända överlevande från tredje flottans undergång.",al={"fitzsimmons","vem är den berusade sjömannen","fitzsimmons värdshus"}},{q="Vad hände med tredje flottan?",a="Kul Tiras tredje flotta överfölls och förintades utanför Wetlands kust under det andra kriget. Orcher från Dragonmaw-klanen red på drakar och regnade eld från skyn, så att flottans skepp och sjömän sjönk till havsbotten.",al={"tredje flottans öde","hur sjönk flottan","kul tiras sänkta skepp"}},{q="Varför anföll drakarna människornas skepp?",a="Under det andra kriget förslavade Dragonmaw-klanen den röda draken Alexstrasza med Demon Soul vid närbelägna Grim Batol. De röda drakarna bands av mörk trolldom och tvingades tjäna horden som monstruösa riddjur och belägringsvapen.",al={"dragonmaws drakar","röda drakar wetlands","varför rider orcher på drakar"}},{q="Var sjönk skeppen egentligen?",a="De förkolnade vraken ligger under vatten utanför Wetlands västra kust, norr om Menethil Harbor. Det är en tragisk havssträcka som nu går under namnet Doomed Fleet.",al={"var finns doomed fleet","skeppsvrakens plats wetlands","tredje flottans vrak"}},{q="Vilken dryck vill Fitzsimmons ha?",a="Han behöver en kanna dvärgarnas mjöd för att lätta på tungbanden och hålla sin sprängande baksmälla stången. Den kan köpas direkt av värdshusvärden inne på Deepwater Tavern.",al={"fitzsimmons mjöd","vad vill fitzsimmons ha","kanna mjöd"}},{q="Vilket rike tjänade tredje flottan?",a="Flottan tillhörde Kul Tiras, örikets sjöfartsrike vars mäktiga flotta utgjorde ryggraden i alliansens sjöstridskrafter under det andra kriget.",al={"är tredje flottan i stormwind","kul tiras flotta","vem ägde wave mistress"}}},fx={["03818f34"]={q="Varför vill First Mate Fitzsimmons ha något att dricka?",a="Fitzsimmons är den ende överlevande efter en fruktansvärd massaker. Han hemsöks av sin flottas undergång i lågorna och plågas av en våldsam baksmälla. Huvudet bultar så hårt att han inte står ut med att återberätta tragedin med The Third Fleet utan starkt att dricka som dämpar smärtan och får honom att tala. En kanna mjöd är det enda som får honom att öppna munnen.",al={"fitzsimmons motiv","varför vill fitzsimmons ha mjöd","varför hjälpa fitzsimmons"}},["53fbd504"]={q="Varför behöver Fitzsimmons att du hämtar mjödet?",a="Fitzsimmons är en nedbruten och utfattig överlevare som vältrar sig i självömkan och plågor precis utanför värdshuset. Han plågas av en bultande baksmälla och har troligen gjort av med sina sista kopparslantar. Han orkar varken ta sig till baren eller har råd, så han får be förbipasserande äventyrare om hjälp.",al={"varför kan inte fitzsimmons köpa sin egen dryck","varför be mig hämta mjöd","fitzsimmons, varför jag"}}},fp="15,204,16.415.0,19.454.0,30.233.0,33.194.0,39.218.0,34.141.0,33.148.0,38.144.0"}
P.entries["quest:2880"] = {n="Troll Necklace Bounty",s="Fraggar Thundermantle från Aerie Peak hävdar att Wildhammers inte lyder under någon allians och bedömer folk efter deras handlingar. Fem stam-halsband från troll i Hinterlands skulle vara en bra början för dig.",h="Fraggar Thundermantle från Aerie Peak hävdar att Wildhammers inte lyder under någon allians och bedömer folk...",kw={"aerie peak","belöning","fraggar thundermantle","hinterlands","trollens stamhalsband","troll","wildhammer"},sec={{t="Vinna Wildhammers aktning",b="Fraggar Thundermantle har ingen nytta av prat och vill göra klart att Wildhammers är självständiga. Den som hoppas få vänner bland dem måste först bevisa sitt värde. Troll som strövar omkring på Hinterlands sluttningar bär ibland stamhalsband, och fem sådana som lämnas till Fraggar i Aerie Peak skulle vara en bra början."}},faq={{q="Varför vill Fraggar Thundermantle ha trollhalsband?",a="Fraggar bedömer folk efter deras handlingar, inte prat, och säger att fem halsband skulle vara en bra början för den som söker vänskap med Wildhammers.",al={"varför trollhalsband","syftet med trollhalsbandsbelöningen","varför vill fraggar ha halsband"}},{q="Är Wildhammers en del av Alliansen?",a="Fraggar står fast vid att de inte är det. Wildhammers är självständiga och bedömer folk efter deras dåd och handlingar.",al={"är wildhammers med i alliansen","är aerie peak med i alliansen","wildhammers lojalitet"}},{q="Var hittar man trollens stamhalsband?",a="Det sägs att troll som strövar omkring på Hinterlands sluttningar bär sådana då och då.",al={"var hittar man trollens stamhalsband","trollhalsbandets plats","hur får man tag på trollhalsband"}},{q="Vem ska jag lämna halsbanden till?",a="Fem halsband ska lämnas till Fraggar Thundermantle i Aerie Peak.",al={"vem får trollhalsbanden","lämna in till fraggar thundermantle","var finns fraggar thundermantle"}}},fp="21,196,25.328.0,52.135.0,41.105.0,42.77.0,33.57.0"}
P.entries["quest:2881"] = {n="Troll Necklace Bounty",s="Fraggar Thundermantle, en Wildhammer, har redan en gång tagit emot trollstammarnas halsband från dig genom den här belöningen. Erbjudandet gäller fortfarande, så länge du lämnar in fem åt gången.",h="Fraggar Thundermantle, en Wildhammer, har redan en gång tagit emot trollstammarnas halsband från dig genom...",kw={"fraggar thundermantle","inlandet","stamhalsband","troll necklace bounty","troll","wildhammer"},sec={{t="Ett stående erbjudande",b="Fraggar påminner dig om att den första överlämningen är avklarad, men tar gärna emot fler trollstammarnas halsband när du hittar dem och väljer att lämna in dem. Fraggar säger att de som kämpar för Wildhammers kommer att finna att Wildhammers är redo att kämpa för dem i gengäld. Fraggar räknar bara en omgång om den innehåller fem halsband."},{t="Fraggars uppskattning",b="När du lämnar in halsbanden blir Fraggar tydligt nöjd och tar emot dem som bevis på att du är beredd att smutsa ner händerna. Fraggar säger att Wildhammers värdesätter den inställningen."}},faq={{q="Vem vill ha trollstammarnas halsband?",a="Fraggar Thundermantle, som talar för Wildhammers.",al={"vem ger den här belöningen","fraggar thundermantles roll","vem tar emot halsbanden"}},{q="Hur många trollstammars halsband behövs?",a="Fem åt gången. Fraggar säger att det krävs fem för att de ska räknas.",al={"antal halsband","hur många halsband","krav för belöningen"}},{q="Varför samlar Fraggar Thundermantle på de här halsbanden?",a="Fraggar ser dem som ett tecken på villighet att kämpa för Wildhammers och säger att de som gör det kommer att finna att Wildhammers är villiga att kämpa för dem.",al={"varför trollhalsband","wildhammers motiv","belöningens syfte"}},{q="Vad föregick den här belöningen?",a="Den första Troll Necklace Bounty, som du redan slutfört åt Fraggar Thundermantle.",al={"förutsättningsuppdrag","föregående steg","tidigare belöning"}}},fp="21,179,16.328.0,18.169.1,37.60.0,43.63.0,55.149.0,29.87.0"}
P.entries["quest:289"] = {n="The Cursed Crew",s="First Mate Fitzsimmons, den enda överlevande från Kul Tiras tredje flotta, ber om nåd för sina förlorade bröders räkning. Bundna av en mörk relik som gömts ombord på deras sjunkna skepp utanför Wetlands kust vandrar de drunknade sjömännen och marinsoldaterna rastlöst bland vraken som odöda.",h="First Mate Fitzsimmons, den enda överlevande från Kul Tiras tredje flotta, ber om nåd för sina förlorade...",kw={"förbannad besättning","förbannad marinsoldat","förbannad sjöman","fitzsimmons","kul tiras","menethil","snellig","snusdosa","tredje flottan","wetlands"},ang={["class:Paladin"]="Tredje flottans sjömän var oskyldiga män som snärjts av en vanhelig relik. När de får vila renas den gudlösa skändningen och ljus förs till mörka vatten.",["faction:Alliance"]="Kul Tiras har länge försett Grand Alliance med de främsta sjömännen. Att låta deras plågade andar få ro är en allvarsam hedersplikt för varje äventyrare i alliansen.",["race:Human"]="Mänskliga resande känner samhörighet med dessa fallna sjömän och känner igen de gemensamma sjötraditionerna i kungariket Kul Tiras."},sec={{t="En rastlös flotta",b="När Kul Tiras tredje flotta förliste längs de karga stränderna norr om Menethil Harbor tog tragedin inte slut under vågorna. First Mate Fitzsimmons lyckades ta sig levande i land, men hans besättningskamrater mötte ett öde långt värre än döden. En mystisk och fruktansvärd skatt, gömd djupt inne i ett av skroven, släppte lös en kuslig trolldom över de döende sjömännen. Den band deras själar till de sjöpinade timren och vägrade dem gravens frid."},{t="Nåd genom klingan",b="Fitzsimmons, som dröjer sig kvar på värdshusen i Menethil Harbor, hemsöks fortfarande av sina forna skeppskamraters nattliga jämmer och rop. Han tror att deras vandrande lik kan få ro om de fälls. Därför skickar han äventyrare in i de ruttnande, dränkta skroven för att slå ner de förbannade sjömännen, de erfarna marinsoldaterna och hans forne jämlike First Mate Snellig. De ska också hämta Snelligs personliga snusdosa som ett bistert bevis på att hans vän äntligen fått vila i frid."}},faq={{q="Vem var First Mate Snellig?",a="First Mate Snellig tjänstgjorde ombord på Kul Tiras olycksdrabbade tredje flotta tillsammans med First Mate Fitzsimmons. När flottan förliste utanför Wetlands nordkust drunknade Snellig med resten av besättningen, men den illvilliga reliken ombord på skeppen återuppväckte honom. Nu hemsöker han det översvämmade lastrummet i ett av vraken som ett odött vidunder.",al={"snellig","förste styrman snellig","vem är snellig"}},{q="Varför är sjömännen och marinsoldaterna förbannade?",a="Enligt Fitzsimmons hade ett av flottans fartyg en dold, ondskefull skatt ombord. När skeppen förliste längs kusten band artefaktens mörka krafter den drunknade besättningens andar till de ruttnande skroven. Själarna hindrades från att gå vidare och dömdes till odödlig plåga.",al={"varför är de odöda","tredje flottans förbannelse","orsaken till de förbannade sjömännen"}},{q="Var ligger de sjunkna skeppen?",a="Den tredje flottans förstörda skrov ligger under vatten utanför norra Wetlands kust, norr om Menethil Harbor. Den förbannade besättningen stryker omkring både på de översvämmade däcken och i vattnet runtomkring. Snellig själv lurar inuti det spruckna skrovet på det södra fartyget.",al={"var ligger skeppen","vrakens plats","var är snellig"}},{q="Varför vill Fitzsimmons ha Snelligs snusdosa?",a="Snusdosan var ett personligt minne som First Mate Snellig ägde i livet. När den återlämnas till Fitzsimmons blir den ett påtagligt bevis på att hans förbannade kamrat äntligen befriats från sitt ruttnande fängelse under vågorna.",al={"snelligs snusdosa","snusdosa","varför snusdosan"}},{q="Vem är First Mate Fitzsimmons?",a="Fitzsimmons är en sjöman från Kul Tiras och den enda kända överlevande från tredje flottan. Sorg och skuld har knäckt honom. Han stannar i Menethil Harbor, hemsökt av mardrömmar om sina drunknade bröder och söker desperat efter resande som kan göra slut på deras lidande.",al={"fitzsimmons","first mate fitzsimmons"}},{q="Bryter det verkligen förbannelsen att döda besättningen?",a="När sjömännen och marinsoldaterna fälls får deras rastlösa andar tillfällig ro, men förtrollningen bryts inte helt. Förbannelsens källa är fortfarande knuten till den mystiska relik som gömts bland vraken.",al={"är förbannelsen hävd","tar detta slut på förbannelsen"}}},fx={["8e82e35b"]={q="Varför vill First Mate Fitzsimmons att den förbannade besättningen dödas?",a="Fitzsimmons hemsöks av vetskapen om att han är den enda levande överlevaren från The Third Fleet. I sömnen plågas han av sina drunknade skeppskamraters ödesmättade jämmer. Deras själar är bundna till de ruttnande skroven av en mörk skatt. Han hoppas att deras vandrande lik ska få ro, så att deras skrik tystnar och den fruktansvärda förbannelsen börjar hävas.",al={"varför döda besättningen","fitzsimmons motiv","varför vill fitzsimmons det här"}},["7d36941a"]={q="Varför behöver Fitzsimmons dig i stället för att gå själv?",a="Fitzsimmons är en gammal, nedbruten sjöman, märkt av traumat efter att ha överlevt skeppsbrottet som tog hela hans flotta. Han dränker sina sorger på värdshuset och saknar både styrkan och modet att själv möta sina återuppväckta forna kamrater. Därför förlitar han sig på dugliga äventyrare som vågar bege sig ut till vraken.",al={"varför behöver fitzsimmons mig","varför kan inte fitzsimmons gå","varför inte vakterna i menethil"}}},fp="15,294,16.359.0,18.469.1,27.294.0,39.281.0,35.222.0,45.184.0,30.231.0,47.198.1"}
P.entries["quest:29"] = {n="Trial of the Lake",s="Trial of the Lake är en utmaning på tid i Moonglade som prövar en novis smidighet och snabbhet. Du måste dyka ner i Lake Elune'ara, hämta en instabil Shrine Bauble och skynda den till Shrine of Remulos innan den förmultnar. Klarar du det får du erkännande av väktaren Tajarri och hedrar Cenarion Circles hängivenhet åt balansen.",h="Trial of the Lake är en utmaning på tid i Moonglade som prövar en novis smidighet och snabbhet.",kw={"cenarion circle","lake elune'ara","moonglade","remulos","shrine bauble","shrine of remulos","tajarri","trial of the lake"},ang={["class:Druid"]="Prövningen sätter druidernas nödvändiga snabbhet och anpassningsförmåga på prov och fungerar som en övergångsrit till ära för väktaren Remulos i Moonglade."},sec={{t="Ett smidighetsprov",b="Trial of the Lake är en inledande rit som övervakas av Moonglades väktare. Du får i uppdrag att dyka ner i Lake Elune'ara lugna vatten och hämta en skör Shrine Bauble från sjöbottnen. Eftersom baublen snabbt förmultnar när den rubbas från sin plats kräver prövningen god kroppslig smidighet, skarpa sinnen och snabba rörelser för att bära den över land innan dess magi falnar."},{t="En hyllning till väktaren",b="När du har hämtat baublen måste du skynda till Shrine of Remulos i nordvästra Moonglade. Monumentet är en bestående hyllning till väktaren Remulos, som vägleder Cenarion Circle i arbetet med att bevara naturen och världens balans. När du aktiverar baublen vid helgedomen visar du ceremoniell vördnad för dess betydelse inom Circle. Där hälsar den betrodda väktaren Tajarri de noviser som klarar prövningens tidsgräns och konkurrens."}},faq={{q="Vad är Trial of the Lake?",a="Trial of the Lake är ett prov på smidighet och fokus i Moonglade. Du dyker ner i Lake Elune'ara kalla djup, hämtar en Shrine Bauble som håller på att förmultna och skyndar den genom fristaden till Shrine of Remulos innan dess energi försvinner.",al={"vad är trial of the lake","syftet med trial of the lake","vad är det här uppdraget"}},{q="Var ligger Shrine of Remulos?",a="Shrine of Remulos ligger i nordvästra Moonglade. Helgedomen är tillägnad väktaren Remulos och hans vägledning av Cenarion Circle, och vaktas och underhålls av väktaren Tajarri.",al={"var ligger shrine of remulos","helgedomens plats","remulos helgedom moonglade"}},{q="Vem är Tajarri?",a="Tajarri är en av Moonglades betrodda väktare och ansvarar för Shrine of Remulos. Hon övervakar Trial of the Lake och välkomnar noviser som för baublen till helgedomen som en hyllning.",al={"vem är tajarri","tajarri moonglade","helgedomens väktare tajarri"}},{q="Vad är en Shrine Bauble?",a="En Shrine Bauble är en relik som hämtas från bottnen av Lake Elune'ara. Den förmultnar snabbt när den tas upp ur vattnet, så du måste skynda dig för att aktivera den vid Shrine of Remulos som en hyllning.",al={"vad är shrine bauble","varför förmultnar baublen","shrine baubles syfte"}},{q="Varför hedras väktaren Remulos vid helgedomen?",a="Väktaren Remulos är en vördad lundväktare som vägleder Cenarion Circle i arbetet med att bevara naturen och upprätthålla balansen. Helgedomen i nordvästra Moonglade är en bestående hyllning till hans ledarskap och principer.",al={"vem är väktaren remulos","remulos bakgrund","varför hedra remulos"}},{q="Vad betyder det att offra baublen vid helgedomen?",a="När du aktiverar baublen vid Shrine of Remulos hyllar du den heliga balans som Cenarion Circle upprätthåller och erkänner helgedomens bestående andliga betydelse i Moonglade.",al={"vad gör det att använda baublen","varför aktivera baublen vid helgedomen"}}},fp="17,295,19.299.0,21.340.0,30.252.0,39.157.0,15.173.0,24.216.0,45.199.0,52.184.0"}
P.entries["quest:290"] = {n="Lifting the Curse",s="First Mate Fitzsimmons tror att en mörk artefakt ombord på deras förlista skepp Intrepid ligger bakom förbannelsen som binder hans rastlösa fallna besättningskamrater. För att befria dem måste en äventyrare möta kapten Halyndors spöke, ta nyckeln till kassaskrinet och hämta reliken från det översvämmade skrovet.",h="First Mate Fitzsimmons tror att en mörk artefakt ombord på deras förlista skepp Intrepid ligger bakom...",kw={"kapten halyndor","fitzsimmons","glorin steelbrow","intrepid","häva förbannelsen","menethil harbor","kassaskrin","tredje flottan","wetlands"},ang={["class:Priest"]="För att lösa andliga plågor och rena besmittade reliker krävs andlig auktoritet. Därför överlåter Fitzsimmons den slutliga reningen av kassaskrinets innehåll åt prästerskapet.",["faction:Alliance"]="Tredje flottans sjömän tjänade Alliansen i livet, och det är en hedersplikt för Alliansens förkämpar på väg genom Menethil Harbor att ge deras plågade själar ro."},sec={{t="En kaptens börda",b="First Mate Fitzsimmons överlevde Tredje flottans tragiska öde, men minnet av hans kamrater hemsöker honom både när han är vaken och i drömmarna. Han är övertygad om att den odödlighet som håller hans skeppskamrater i sitt grepp hänger samman med ett mystiskt, ondskefullt föremål som är inlåst i kassaskrinet på hans gamla skepp Intrepid. Vraket vaktas av kapten Halyndors spöklika kvarlevor, som även efter döden envist skyddar nyckeln till skeppets djupaste hemligheter."},{t="Lås upp djupen",b="Utanför Wetlands dimhöljda nordkust ligger Tredje flottans splittrade vrak. I Intrepids översvämmade skrov finns skeppets låsta kassaskrin, med reliken som ligger bakom besättningens elände. För att återta den måste du besegra Halyndors plågade spöke på däck, säkra den rostiga nyckeln och ta dig genom det översvämmade inre för att hämta den mörka artefakten, så att heliga händer kan rena den."}},faq={{q="Vilket skepp letar du efter under det här uppdraget?",a="Du letar efter Intrepid, Tredje flottans sjunkna skepp utanför Wetlands nordvästra kust.",al={"vilket skepp","intrepids skeppsvrak","var finns kassaskrinet"}},{q="Vem är kapten Halyndor?",a="Kapten Halyndor var befälhavare på Intrepid. Efter sin död hemsöker hans rastlösa ande däcket på det förstörda skeppet och klamrar sig envist fast vid nyckeln till skeppets kassaskrin.",al={"vem är halyndor","kapten halyndors bakgrund"}},{q="Varför vill First Mate Fitzsimmons att kassaskrinet ska öppnas?",a="Fitzsimmons tror att ett förbannat föremål i kassaskrinet plågar hans sjömäns andar och håller dem fångna. Att öppna skrinet är det enda sättet att hämta artefakten och rena den.",al={"fitzsimmons mål","varför öppna kassaskrinet","uppdragets syfte"}},{q="Var finns Intrepids kassaskrin?",a="Kassaskrinet ligger under vatten i Intrepids nedre skrov. Du når det genom en öppning i sidan av det förlista skeppet under vågorna.",al={"kassaskrinets plats","var finns kistan","hur hittar man kassaskrinet"}},{q="Vem kan rena det förbannade föremålet när du hämtat det?",a="Fitzsimmons ber äventyrare ta det återfunna föremålet till den dvärgaprästen Glorin Steelbrow i Menethil Harbor, så att han kan rena dess onda smitta.",al={"vem renar reliken","vem är glorin steelbrow","vart ska det förbannade föremålet tas"}},{q="Vad orsakade skeppsbrottet från början?",a="Under Andra kriget attackerades Tredje flottan av röda drakar som kontrollerades av orcher. Skeppen brändes och sänktes utanför Wetlands kust; skatten ombord håller nu de drunknade besättningarna från att få ro.",al={"hur sjönk tredje flottan","orsaken till tredje flottans vrak"}}},fx={["336b08f7"]={q="Vad används Intrepid Strongbox Key till?",a="Nyckeln tillhörde Captain Halyndor och behövs för att låsa upp Intrepids kassaskrin i vraket. Därinne finns det förbannade föremål som fördärvade sjömännen i The Third Fleet. Det måste återtas innan det kan renas.",al={"intrepid strongbox key","vad öppnar nyckeln","varför behöver jag nyckeln"}},["1f8e42a3"]={q="Varför skickar First Mate Fitzsimmons dig i stället för att gå själv?",a="Fitzsimmons är djupt traumatiserad och hemsöks av drömmar om sin döda besättning och tidigare befälhavare. Skuldkänslor och rädsla gör att han inte klarar av att möta vraket efter Intrepid eller Captain Halyndors hämndlystna vålnad.",al={"fitzsimmons, varför jag","varför kan inte fitzsimmons göra det","varför behöver fitzsimmons dig"}}},fp="17,210,18.311.0,20.336.1,46.101.0,24.126.0,58.165.0,42.122.0,55.126.0,45.193.0"}
P.entries["quest:2902"] = {n="Woodpaw Investigation",s="Hadoken Swiftstrider är säker på att Woodpaw-gnollerna följer någon nedskriven strategi. Han skickar dig till gnollernas läger söder om Camp Mojache för att leta efter något som liknar stridsplaner.",h="Hadoken Swiftstrider är säker på att Woodpaw-gnollerna följer någon nedskriven strategi.",kw={"stridskarta","stridsplaner","camp mojache","feralas","gnoller","hadoken swiftstrider","woodpaw"},sec={{t="En jakt på planer",b="Det här kommer efter Alpha Strike. Hadoken har liten respekt för gnollernas intelligens, men han är säker på att de för någon sorts bok över sin strategi, eftersom deras senaste angrepp är alltför väl samordnade för att vara improviserade. Om han fick se planerna skulle han bättre förstå vad som fått dem så uppjagade. Han skickar dig tillbaka till Woodpaw för att hitta något som liknar stridsplaner och ta med det till honom."},{t="Vad kartan visar",b="Kartan är verkligen det Hadoken ville ha. Pilar löper över den och kan visa truppförflyttningar, men de flesta går söderut, bort från Camp Mojache i norr. På ett annat ställe på kartan finns en teckning av vad du tror är en stor insekt, med streck under den, kanske en räkning av gnollernas förluster till okända insekter."}},faq={{q="Vem skickar dig för att undersöka Woodpaw-gnollerna?",a="Hadoken Swiftstrider i Camp Mojache.",al={"vem ger woodpaw investigation","uppdragsgivare woodpaw investigation"}},{q="Varför tror Hadoken att gnollerna har stridsplaner?",a="Deras angrepp har varit alltför väl samordnade för att vara improviserade, så Hadoken räknar med att det finns en nedskriven strategi som kan visa vad som gjort dem så uppjagade.",al={"varför har gnoller planer","woodpaws strategi"}},{q="Var finns stridsplanerna?",a="I gnollernas läger söder om Camp Mojache.",al={"var finns woodpaws planer","var hittar man woodpaws stridskarta"}},{q="Vad kom före Woodpaw Investigation?",a="Alpha Strike är steget precis före den här efterforskningen.",al={"föregående uppdrag woodpaw investigation","förkunskapsuppdrag för woodpaw-kedjan"}}},fp="21,176,18.372.0,18.296.1,48.37.0,54.146.0,35.41.0,39.61.0"}
P.entries["quest:2903"] = {n="The Battle Plans",s="Du har gnollernas stridsplaner. Nu återstår bara att ta dem tillbaka till Hadoken Swiftstrider i Camp Mojache, där han eller någon annan kanske kan lista ut vad gnollerna är ute efter.",h="Du har gnollernas stridsplaner.",kw={"stridsplaner","camp mojache","feralas","gnoller","hadoken swiftstrider","woodpaw"},sec={{t="Tillbaka till Camp Mojache",b="Efter Woodpaw Investigation har du Woodpaws stridsplaner, och det enda som återstår är att lämna tillbaka dem till Hadoken Swiftstrider i lägret. Hadoken letar efter konkreta bevis på gnollernas avsikter."},{t="Hadokens tolkning",b="Hadoken säger att det här är precis vad de behövde. Det mesta av klottret är obegripligt för honom, men han har sett tillräckligt många stridsplaner för att förstå läget: gnollerna strider på två fronter. Den ena är lägret, men huvuddelen av deras styrka riktas mot en fiende i söder. Han anar att något större ligger bakom alltihop och tycker att det är dags att ta reda på vem den andra fienden är."}},faq={{q="Vart ska stridsplanerna lämnas?",a="Till Hadoken Swiftstrider i Camp Mojache.",al={"vem får planerna","var lämnar man stridsplanerna","inlämning av stridsplanerna"}},{q="Vad hände före det här steget?",a="Woodpaw Investigation, sökandet efter gnollernas planer.",al={"föregående uppdrag","vad leder fram till stridsplanerna","förkunskapsuppdrag för stridsplanerna"}},{q="Varifrån kommer stridsplanerna?",a="Det är gnollernas egna planer, som hittades i gnollernas läger söder om Camp Mojache under Woodpaw Investigation.",al={"vem gjorde kartan","vilka gnoller gjorde planerna","stridsplanernas ursprung i woodpaw"}}},fp="16,178,20.206.0,17.351.1,39.40.0,27.56.0,37.112.0"}
P.entries["quest:2904"] = {n="A Fine Mess",s="Djupt inne i Gnomeregans bestrålade ruiner ligger en skadad goblin vid namn Kernobee, omgiven av trogger efter ett bakhåll från Dark Iron-dvärgar. Räddningen avslöjar oroande uppgifter om Dark Irons inblandning i borrmaskiner under jorden, som måste föras hela vägen till Booty Bay.",h="Djupt inne i Gnomeregans bestrålade ruiner ligger en skadad goblin vid namn Kernobee, omgiven av trogger...",kw={"booty bay","clockwerk run","dark iron","gnomeregan","kernobee","scooty","superrigg","tinkerwiz","trogger"},ang={["faction:Alliance"]="Avslöjandet av Dark Irons samröre inom Dun Moroghs gränser bekräftar att kejsar Thaurissans agenter aktivt saboterar Alliansens återuppbyggnadsarbete i Gnomeregan.",["profession:Engineering"]="Upptäckten att Dark Irons mekaniker bygger en enorm superrigg väcker omedelbar oro hos alla ingenjörer som följer avancerad utrustning för arbete under jord.",["race:Gnome"]="Att rädda en instängd överlevare ur Gnomeregans förorenade djup är en hedersplikt, särskilt när man möter den samlade illviljan hos Dark Iron-infiltratörer och vilda trogger."},sec={{t="En slagen överlevare",b="När äventyrare tar sig genom de farliga inre kamrarna i Gnomeregan hittar de Kernobee strandsatt i sovsalsområdet. Goblinen är svårt misshandlad och omtöcknad. Han överlevde att tillfångatas av Dark Iron-dvärgar, som lämnade honom att dö bland de vilda troggerna. Att hitta ett vänligt ansikte är hans enda chans att överleva färden tillbaka genom de förorenade gångarna."},{t="Intriger under jorden",b="Kernobee bär på viktig information om mörka krafter som verkar under Dun Morogh. Han avslöjar att Dark Iron-klanen aktivt har deltagit i bygget av en enorm superrigg. Medan Kernobee flyr över havet till Ratchet för att varna gobliningenjören Tinkerwiz om det annalkande hotet, skickar han sin räddare söderut till Booty Bay för att underrätta gobliningenjören Scooty."}},faq={{q="Vem är Kernobee?",a="Kernobee är en goblin som begav sig djupt in i Gnomeregans ruiner. Dark Iron-dvärgar överföll honom, slog honom nästan till döds och lämnade honom åt troggerna innan han blev räddad.",al={"kernobee","vem är kernobee"}},{q="Vart ska Kernobee eskorteras?",a="Kernobee måste tryggt ledas genom de fientliga salarna tillbaka mot säkerheten vid utgången Clockwerk Run och de övre entrégångarna i den fallna staden.",al={"vart ska jag ta kernobee","eskortmål","utgången clockwerk run"}},{q="Varför var Dark Iron-dvärgarna inblandade?",a="Dark Iron-dvärgarna har smitt planer under jord och hjälpt till att utforma och bygga en enorm superriggsborr. Kernobee upptäckte planen innan dvärgarna överföll honom.",al={"varför dark iron","dark irons superrigg","dark iron i gnomeregan"}},{q="Vart tar Kernobee vägen efter flykten?",a="När han nått säkerheten beger sig Kernobee över havet till Ratchet i The Barrens för att varna mekanikern Tinkerwiz om Dark Irons inblandning i borriggen under jorden.",al={"vart tog kernobee vägen","kernobee i ratchet","varning till tinkerwiz"}},{q="Varför måste du rapportera till Scooty i Booty Bay?",a="Scooty är en gobliningenjör stationerad i Booty Bay. Han samarbetar med Tinkerwiz och samordnar verksamhet med högteknologisk utrustning för arbete under jord och transpondernätverk.",al={"varför scooty","lämna uppdrag i booty bay","scootys koppling"}},{q="Hur hänger det här ihop med Mekgineer Thermaplugg?",a="Scooty känner till hotet från Mekgineer Thermaplugg i Gnomeregan. Genom att hjälpa Kernobee ger du stöd och förnödenheter åt äventyrare som tänker återvända och konfrontera den förrädiske Mekgineer.",al={"koppling till thermaplugg","strida mot thermaplugg"}}},fx={["73352f2e"]={q="Varför måste Kernobee eskorteras ut?",a="Kernobee överfölls, misshandlades nästan till döds av Dark Iron-dvärgar och lämnades i en sovsal som översvämmats av fientliga troggs. Han är skadad och fångad långt inne i Gnomeregans ruiner och kan inte ta sig till utgången på egen hand. Dessutom bär han på viktiga underrättelser: han upptäckte att Dark Iron-klanen är direkt inblandad i bygget av en enorm borrigg. Att komma ut levande är hans enda chans att ta sig till Ratchet och varna sin bundsförvant Tinkerwiz innan maskineriet ställer till med ännu större skada.",al={"varför hjälpa kernobee","kernobees motiv","varför behöver kernobee hjälp"}},["9976ada5"]={q="Varför kan Kernobee inte ta sig ut ur Gnomeregan på egen hand?",a="Kernobee är knappt vid medvetande när du hittar honom. Hans fångvaktare från Dark Iron har misshandlat honom svårt och sedan kastat honom bland troggs. Han är blåslagen, obeväpnad och nära döden. Utan en duglig äventyrare som skyddar honom har han ingen chans mot de bestrålade mutanterna, de förrymda konstruktionerna och de vilda troggs som patrullerar Clockwerk Run.",al={"varför behöver kernobee dig","varför kan inte kernobee slåss","varför jag åt kernobee"}}},fp="11,166,19.204.0,20.250.1,16.147.0,32.119.0,40.149.0,38.164.1,43.127.0,46.191.0"}
P.entries["quest:291"] = {n="The Reports",s="Ta med Senir Whitebeards rapport om Frostmane-trollen från Kharanos till Senator Barin Redstone i Ironforge. Senir varnar för att senatorn är tvär och ber dig att inte nämna vem som hjälpte till att samla in informationen.",h="Ta med Senir Whitebeards rapport om Frostmane-trollen från Kharanos till Senator Barin Redstone i Ironforge.",kw={"barin redstone","dvärgarnas senat","frostmane","high seat","ironforge","kharanos","magni bronzebeard","senir whitebeard","rapporterna"},ang={["faction:Alliance"]="Leveransen ger en tidig inblick i Ironforges samhällsstruktur och den politiska byråkrati som formar Alliansens inrikespolitik i Dun Morogh.",["race:Dwarf"]="För dvärgar innebär det att gå in i High Seat för att leverera rapporten en första inblick i den känsliga maktbalansen mellan King Magni Bronzebeards krona och den parlamentariska makten hos dvärgarnas senat."},sec={{t="En rapport till huvudstaden",b="Efter en djärv spaning djupt inne i Frostmane Hold skriver Senir Whitebeard en brådskande rapport om det växande trollhotet mot Dun Morogh. Bergsjägaren är stationerad i Kharanos och behöver ett bud som kan leverera underrättelserna direkt till Senator Barin Redstone i Ironforge. För att värna sitt anseende inför myndigheterna råder Whitebeard glatt sitt bud att inte nämna vem som faktiskt utförde det farliga arbetet bland de snöiga klipporna."},{t="Konflikt i High Seat",b="När dokumentet lämnas till Senator Redstone i det kungliga hovet väcker det omedelbar vrede. I stället för att tacka för informationen om fientliga trollrörelser blir den tväre senatorn upprörd över att King Magni Bronzebeards personliga auktoritet åberopas för att sanktionera Whitebeards verksamhet. Leveransen blottlägger en pågående maktkamp i Ironforges maktens salar och visar hur djupt senaten ogillar exekutiva dekret och fältinitiativ utan godkännande som genomförs i kungens namn."}},faq={{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är en dvärgisk bergsjägare stationerad nära Kharanos i Dun Morogh. Han ansvarar för spaning och militär rekognosering mot Frostmane-trollstammarna som tränger in på dvärgarnas bosättningar.",al={"senir whitebeard","vem lämnar rapporterna","whitebeard kharanos"}},{q="Vem är Senator Barin Redstone?",a="Barin Redstone är en tvär, aristokratisk dvärgisk senator som bor i Ironforges tronrum nära King Magni Bronzebeard. Han värnar lagstiftarnas makt och blir lätt irriterad på vanliga besökare med framställningar.",al={"barin redstone","vem är senatorn","redstone ironforge"}},{q="Varför är Senator Redstone arg över rapporten?",a="Senir varnar för att Redstone har ett tvärt sinnelag. Senatorns reaktion på rapporten blir känd när du levererar den.",al={"varför är redstone arg","varför skriker senatorn","senaten mot magni"}},{q="Varför ber Senir Whitebeard dig att hålla din hjälp hemlig?",a="Whitebeard vill att hans överordnade i Ironforge ska tro att han själv planerade och genomförde den mödosamma fältspaningen. Det stärker hans anseende, i stället för att erkänna att en kringresande äventyrare utförde uppdraget.",al={"varför tar senir åt sig äran","whitebeard tog åt sig äran","senirs hemlighet"}},{q="Var levereras rapporten?",a="Rapporten levereras till Senator Barin Redstone i Ironforges High Seat, den stora salen där King Magni Bronzebeard håller hov.",al={"var lämnar man in rapporterna","var finns barin redstone","lämna in rapporterna"}},{q="Vad avslöjar uppdraget om Ironforges politik?",a="Leveransen introducerar Ironforges senat och ämbetsmännen som tar emot rapporter från gränstrakterna. Redstones reaktion ger en närmare inblick i dess politik.",al={"ironforges politiska historia","dvärgarnas senat historia","magni mot senaten"}}},fx={bde96c47={q="Varför behöver Senir Whitebeard att du levererar rapporten i stället för att göra det själv?",a="Senir Whitebeard är fortfarande stationerad ute i Dun Morogh för att leda fältoperationer mot lokala hot som Frostmane-trollen. Än viktigare är att han vill att senaten och hans överordnade ska tro att han arbetar outtröttligt vid fronten. Därför överlåter han kurirsysslorna och det obehagliga mötet med en grinig senator åt en förbrukningsbar resenär.",al={"varför skicka mig med rapporten","varför levererar inte senir rapporten","varför jag med rapporterna"}}},fp="11,163,25.197.0,25.281.1,24.190.0,30.157.0,47.110.1,55.190.0,30.139.0,53.163.1"}
P.entries["quest:292"] = {n="The Eye of Paleth",s="I det här uppdraget återfinner en äventyrare en svartnad, pulserande ädelsten kallad Cursed Eye of Paleth i det översvämmade vraket efter Intrepid. På den hemsökte sjömannen Fitzsimmons begäran måste den illvilliga artefakten föras till Menethil Harbor, så att dvärgprästen Glorin Steelbrow kan utröna hur dess förbannelse ska renas bort.",h="I det här uppdraget återfinner en äventyrare en svartnad, pulserande ädelsten kallad Cursed Eye of Paleth i...",kw={"cursed eye of paleth","eye of paleth","fitzsimmons","glorin steelbrow","intrepid","menethil harbor","third fleet","wetlands"},ang={["class:Priest"]="Att hantera besmittelsen av en helig artefakt som Eye of Paleth gör den här undersökningen direkt relevant för präster inom Holy Light.",["faction:Alliance"]="Third Fleet var en expedition från Alliance vars undergång gjorde Menethil Harbor sårbart. Att återfinna dess kvarlevor hjälper de överlevande att få ett avslut efter sina förlorade kamrater.",["race:Dwarf"]="Att hitta förlorade artefakter utanför Khaz Modans kust berör dvärgarnas hängivenhet till att återta dolda reliker, med hjälp av präster från Ironforge som Glorin Steelbrow."},sec={{t="En fördärvad relik",b="Under Baradin Bays förrädiska vatten, i den låsta kassaskrinet ombord på det sjunkna fartyget Intrepid, finns ingen vanlig skatt. Skrinet innehåller en svartnad klotformad sten som pulserar med ett oroande sken: ett Eye of Paleth. I stället för att utstråla heligt ljus har just den här stenen förvridits till en källa till lidande, starkt knuten till de rastlösa andarna och den undergång som drabbade sjömännen i Third Fleet."},{t="På jakt efter prästerskapet",b="Eftersom sådan mörk magi övergår vanlig bärgning förs artefakten direkt i land till Menethil Harbor. Där undersöker Glorin Steelbrow, en dvärgpräst inom Holy Light, anomalin. Han blir häpen över att en sådan helig tingest någonsin fanns i Third Fleets ägo, men känner genast igen dess onaturliga besmittelse och börjar förbereda de riter som krävs för att häva dess mörka inflytande."}},faq={{q="Vad är Eye of Paleth?",a="Eye of Paleth är en uråldrig och mäktig helig ädelsten. Den förknippas vanligtvis med heliga krafter, men det här exemplaret fanns ombord på det sjunkna fartyget Intrepid från Third Fleet och har blivit förvridet och förbannat. Det utstrålar mörk magi.",al={"eye of paleths bakgrund","vad är paleth","cursed eye of paleth"}},{q="Var återfanns Eye?",a="Det återfanns i ett låst kassaskrin ombord på det översvämmade vraket efter Intrepid, strax utanför Wetlands dimhöljda kust.",al={"var hittar jag eye","eye of paleths plats","intrepids kassaskrin"}},{q="Varför bryr sig Glorin Steelbrow om artefakten?",a="Glorin Steelbrow är en dvärgpräst stationerad i Menethil Harbor. Som utövare av Holy Light har han den heliga kunskap som krävs för att känna igen uråldriga reliker och inleda de riter som behövs för att bryta onda förbannelser.",al={"vem är glorin steelbrow","varför steelbrow"}},{q="Hur känner Fitzsimmons till Eye?",a="Fitzsimmons överlevde katastrofen med Third Fleet och hemsöks fortfarande av den. Traumatiserad och i skydd på Menethils värdshus kände han till den mörka relik som låg gömd i vraket och plågade hans fallna besättningskamrater.",al={"fitzsimmons koppling","varför skickade fitzsimmons mig"}},{q="Varför är Eye förbannat?",a="Dess exakta fördärv är fortfarande knutet till den övernaturliga undergången och de rastlösa odöda som hemsöker Third Fleets skeppsvrak. Artefakten sög åt sig mörka energier under eller efter katastrofen som sänkte flottan till havets botten.",al={"varför är den förbannad","eye-förbannelsens ursprung"}},{q="Vad händer när jag lämnar Eye till Glorin?",a="Glorin undersöker den förbannade ädelstenen och inser att den inte kan lämnas i sitt fördärvade skick. Han ber äventyraren rena reliken från dess fördärvliga inflytande.",al={"nästa uppdrag","vad ska jag göra med eye"}}},fp="17,197,16.289.0,22.247.1,26.197.0,28.117.0,50.174.0,40.202.0,22.220.0,44.131.1"}
P.entries["quest:2922"] = {n="Save Techbot's Brain!",s="Tinkmaster Overspark skickar ut alliansens äventyrare för att hämta Techbots minneskärna från Gnomeregans bestrålade ruiner. Den en gång hjälpsamma mekaniska assistenten fick en allvarlig hjärnpolarisering när staden föll och började löpa amok. Overspark hoppas att kärnan ska låta honom häva skadan och återställa sin älskade skapelse.",h="Tinkmaster Overspark skickar ut alliansens äventyrare för att hämta Techbots minneskärna från Gnomeregans...",kw={"gnomeregan","minneskärna","negatronisk","overspark","positronisk","techbot","tinker town"},ang={["faction:Alliance"]="Att återvinna värdefull förlorad teknik från Gnomeregans förorenade utkanter är avgörande för att hjälpa de gnomiska flyktingarna som söker skydd i Ironforge.",["profession:Engineering"]="Techbots processor gick från positronisk till negatronisk. Det är en varnande berättelse för uppfinnare som arbetar med mycket komplexa beräkningsmatriser.",["race:Gnome"]="För gnomiska ingenjörer står Techbot för den tragiska följdskadan av att förlora sin hemstad och visar att även deras främsta intellektuella bedrifter kan förvridas av katastrofen."},sec={{t="Ett omvänt sinne",b="Före katastrofen som ödelade Gnomeregan var Techbot ett under av gnomisk uppfinningsrikedom. Tinkmaster Overspark konstruerade automaten, som hjälpte forskare med mängder av inbyggda manicker och ett encyklopediskt arkiv av teknisk kunskap. Men varken kaoset under trogginvasionen eller utsläppet av giftig strålning skonade maskinen. En elektrisk stöt träffade Techbots känsliga inre konstruktion och polariserade dess positroniska hjärna fullständigt till ett instabilt negatroniskt tillstånd."},{t="Räddningsinsats",b="Techbot är fast i Gnomeregans förorenade korridorer och strövar nu omkring i ett maniskt raseriutbrott och angriper alla den ser. Trots det våldsamma felet vägrar Overspark att avskriva sin uppskattade assistent som skrot. Han rekryterar dugliga operatörer för att spåra upp den rasande automaten, ta ut minneskärnan ur metallhöljet och föra den säkert till Ironforge, så att Tinkmaster kan häva polariseringen och reparera Techbots sinne."}},faq={{q="Vem är Techbot?",a="Techbot är en mekanisk assistent som uppfanns av Tinkmaster Overspark. Före Gnomeregans fall hjälpte den Tinkmaster och hans medarbetare med sin enorma kunskapsdatabas och sina inbyggda manicker.",al={"vad är techbot","techbots bakgrund","overspark techbot"}},{q="Varför blev Techbot fientlig?",a="När Gnomeregan föll träffades Techbots positroniska hjärna av en elektrisk gnista. Stöten vände dess neurala inriktning till ett negatroniskt tillstånd och förvandlade dess hjälpsamma personlighet till ett ursinnigt raseriutbrott.",al={"varför är techbot arg","vad hände med techbot","techbots polarisering"}},{q="Var hittar man Techbot?",a="Techbot strövar omkring i Gnomeregans yttre korridorer och samlingshallar, strax bortom gränslinjerna där de förvisade gnomerna och dvärgarnas expeditionsstyrkor håller till.",al={"var finns techbot","techbots plats","hitta techbot"}},{q="Vem ger det här uppdraget?",a="Tinkmaster Overspark erbjuder uppdraget från Tinker Town i Ironforge, där han övervakar räddnings- och forskningsarbetet på översteuppfinnaren Gelbin Mekkatorques uppdrag.",al={"vem startar save techbots brain","var finns overspark"}},{q="Går det verkligen att reparera Techbot?",a="Tinkmaster Overspark tror att Techbots minneskärna kan hjälpa honom att hitta den exakta orsaken till den negatroniska polariseringen och återställa automaten till funktionsdugligt skick.",al={"är techbot reparerad","går det att reparera techbot","överlever techbot"}},{q="Vad händer när man lämnar tillbaka minneskärnan?",a="När Overspark får kärnan börjar han genast förbereda sig på att demontera och konfigurera om de omvända kretsarna, men att hitta rätt verktyg i hans överfulla verkstad visar sig vara en utmaning i sig.",al={"slutet på techbot-uppdraget","lämna in techbots kärna"}}},fx={e9c625cc={q="Varför vill Tinkmaster Overspark att Techbots hjärna räddas?",a="Techbot är Tinkmaster Oversparks stolta skapelse. En gång tjänade den honom och hans uppfinnarkollegor med ett enormt kunskapsarkiv och praktiska manicker. När Gnomeregan föll fick automaten en elektrisk stöt som polariserade dess positronhjärna till ett negatroniskt tillstånd och drev den till vansinne. Overspark vägrar överge sin skapelse och hoppas att en undersökning av kärnan ska hjälpa honom att åtgärda skadan och återställa sin assistent.",al={"oversparks motiv","varför rädda techbot","varför vill overspark ha techbot"}},["6f8a4042"]={q="Vad används Techbot's Memory Core till?",a="Minneskärnan innehåller Techbots digitaliserade sinne och samlade kunskap. Eftersom automatens positronhjärna inverterades när Gnomeregan föll är det enda sättet att undersöka polaritetsförskjutningen och försöka programmera om eller bygga upp den mekaniska assistenten att ta ut den här komponenten.",al={"techbots minneskärna","vad används minneskärnan till"}}},fp="21,341,15.420.0,17.407.0,15.180.0,31.187.0,27.146.0,21.136.0,30.153.0,45.182.1"}
P.entries["quest:2923"] = {n="Tinkmaster Overspark",s="Det här ärendet leder alliansens äventyrare i Stormwind till Tinker Town i Ironforge, där Tinkmaster Overspark sörjer ett tragiskt haveri. Brother Sarno meddelar att Oversparks mekaniska skapelse, Techbot, har löpt amok bland de bestrålade ruinerna av Gnomeregan. Att ta sig till Tinkmaster är första steget mot att återfinna den vilsegångna konstruktionens minneskärna.",h="Det här ärendet leder alliansens äventyrare i Stormwind till Tinker Town i Ironforge, där Tinkmaster...",kw={"gnomeregan","ironforge","overspark","sarno","techbot","tinker town","tinkmaster"},ang={["faction:Alliance"]="När du hjälper de fördrivna gnomiska flyktingarna i Tinker Town stärks de viktiga banden mellan Stormwind och dvärgarnas och gnomernas riken.",["profession:Engineering"]="Oversparks skapelser är den gnomiska uppfinningsrikedomens spets, så varje tillfälle att undersöka hans förrymda konstruktioner blir lärorikt.",["race:Gnome"]="Varje räddad skapelse och återfunnen minneskärna bevarar en del av ditt fallna hemland innan strålning och troggar förstör det helt."},sec={{t="En vädjan från katedralen",b="Brother Sarno, som tar hand om resenärer i Stormwind City, berättar om ett olyckligt dilemma som växer bland de gnomiska flyktingarna. Tinkmaster Overspark, en av de briljanta hjärnorna bakom Gnomeregans underverk, är förtvivlad över att Techbot har korrumperats. Den en gång hjälpsamma mekaniska tjänaren tjänade mekanikerna troget innan staden föll i ruiner."},{t="Till Tinker Town",b="Uppdraget skickar hjälpsamma själar med Deeprun Tram till Tinker Town, det livliga gnomiska kvarteret i Ironforge. Där söker Overspark desperat efter äventyrare som vågar sig tillbaka in i Gnomeregans bestrålade hallar för att rädda det som återstår av Techbots förmågor innan konstruktionen orsakar irreparabel skada."}},faq={{q="Vem är Tinkmaster Overspark?",a="Tinkmaster Overspark är en gnomisk ingenjör och tränare i gnomisk ingenjörskonst. Han håller för närvarande till i Tinker Town i Ironforge och arbetar outtröttligt med att samordna återtagandet och rädda gnomisk teknologi som kommit på villovägar från deras förstörda huvudstad.",al={"overspark","vem är overspark","tinkmaster overspark"}},{q="Vem ger uppdraget?",a="Brother Sarno, en mänsklig präst i Stormwind City, ger äventyrarna det här uppdraget för att leda dem till de gnomer i Ironforge som behöver hjälp.",al={"uppdragsgivare","var får man uppdraget från tinkmaster overspark"}},{q="Vad är Techbot?",a="Techbot är en mekanisk skapelse som Tinkmaster Overspark konstruerat. Den var tidigare ett hjälpsamt och vänligt verktyg för gnomiska ingenjörer, men efter Gnomeregans katastrofala fall gick den sönder och löpte amok i den bestrålade staden.",al={"techbot","vad hände med techbot"}},{q="Var finns Tinkmaster Overspark?",a="Overspark håller till i Tinker Town, det gnomiska kvarteret i Ironforges östra distrikt. Där omges han av andra flyktingar som är mekaniker och av experimentella maskiner.",al={"oversparks plats","var är overspark"}},{q="Vad händer när du talat med Overspark?",a="När du rapporterar till Overspark erbjuder han uppdraget 'Save Techbot's Brain!' och ber dig bege dig till Gnomeregan för att avaktivera Techbot och hämta dess minneskärna så att den kan återställas.",al={"nästa uppdrag","rädda techbots hjärna"}},{q="Varför bryr sig Alliansen om en uppfinnares trasiga maskin?",a="Förutom medkänslan med de fördrivna gnomerna utgör kringströvande, förrymda automater i Gnomeregan ett omedelbart hot mot expeditioner som försöker återta den underjordiska huvudstaden eller skydda Dun Moroghs gränser.",al={"varför bry sig om techbot","techbots betydelse"}}},fx={["9c70ad2e"]={q="Varför skickar Brother Sarno dig till Tinkmaster Overspark?",a="Brother Sarno minns Techbot som en hjälpsam och mild automat som troget tjänade gnomerna innan Gnomeregan föll i kaos. Den helige mannen bekymras av att höra att Overspark är förtvivlad över att hans skapelse har gått sönder. Sarno hoppas att maskinen fortfarande kan räddas, i stället för att lämnas att förfalla eller förstöras, och hänvisar därför hjälpsamma äventyrare till Tinker Town så att den bedrövade tinkmästaren kan få den hjälp han så desperat behöver.",al={"varför bryr sig brother sarno","brother sarnos motiv","varför skicka mig till overspark"}}},fp="20,235,25.293.0,14.259.0,28.211.0,22.91.0,16.197.0,40.151.0,41.136.0,63.172.0"}
P.entries["quest:2924"] = {n="Essential Artificials",s="Essential Artificials är ett uppdrag för Alliansen som Klockmort Spannerspan erbjuder i Tinker Town i Ironforge. Äventyrarna måste utforska de bestrålade ruinerna av Gnomeregan och återfinna viktiga universalreservdelar som övergavs under den desperata evakueringen.",h="Essential Artificials är ett uppdrag för Alliansen som Klockmort Spannerspan erbjuder i Tinker Town i...",kw={"artificial extrapolator","essential artificials","gnomeregan","gnomisk ingenjörskonst","ironforge","klockmort spannerspan","tinker town"},ang={["faction:Alliance"]="När du hjälper de landsflyktiga gnomerna att återta sin förlorade teknik stärker du Alliansens tekniska grundval i Ironforge.",["profession:Engineering"]="Varje ingenjör förstår plågan i att sakna en enda universell komponent. När du återfinner apparaterna får du se hur sofistikerat hantverket i Gnomeregan var före stadens fall.",["race:Gnome"]="Att återta komponenterna handlar om nationell stolthet och teknisk kontinuitet. Landsflykten i Ironforge får inte sätta stopp för gnomernas uppfinningsrikedom."},sec={{t="Glömda under flykten",b="När trogginvasionen övermannade Gnomeregan och giftig strålning fyllde dess korridorer kunde de flyende gnomerna bara ta med sig det de hade närmast till hands. Bland de otaliga underverk som lämnades kvar fanns förråd av Essential Artificial, specialiserade mekaniska komponenter som nästan passar universellt och som värderas högt av uppfinnare och hantverkare. Mästermekanikern Klockmort Spannerspan arbetar nu i Tinker Town i Ironforge, men hans banbrytande nya experiment har stannat av utan dem."},{t="På jakt efter extrapolatorer",b="De viktiga apparaterna förvaras i tunga, ångdrivna lagringsenheter som kallas artificial extrapolators, djupt inne i den fallna staden. För att bärga dem måste du trotsa bestrålade salar där muterade lepragnomer, felande försvarsautomater och vilda troggs stryker omkring. När Klockmort får tillbaka ett förråd med tolv komponenter kan han återuppta sitt viktiga arbete och driva gnomernas innovation framåt trots deras landsflykt."}},faq={{q="Vad är Essential Artificial?",a="Essential Artificial är en mekanisk komponent som utvecklats av gnomiska ingenjörer och passar nästan universellt. Uppfinnare och smeder värdesätter den högt. Den är en viktig byggsten i invecklade manicker och avancerade experimentmaskiner.",al={"vad är essential artificial","essential artificial","vad är det"}},{q="Vem ger uppdraget Essential Artificials?",a="Uppdraget ges av Klockmort Spannerspan, en gnomisk ingenjör i Tinker Town i Ironforge.",al={"uppdragsgivare","vem startar uppdraget","var hittar jag essential artificial"}},{q="Var hittar man Essential Artificial i Gnomeregan?",a="De förvaras djupt inne i Gnomeregan, i behållare som kallas artificial extrapolators. De liknar höga, ångdrivna skåp och finns utspridda i de nedre salarna.",al={"var finns de","plats för extrapolatorer","hur hittar man artificial"}},{q="Varför lämnades de kvar i Gnomeregan?",a="Under den plötsliga trogginvasionen och den efterföljande radioaktiva katastrofen flydde gnomerna från sin huvudstad i ren panik. I evakueringens kaos lämnades lager av dessa viktiga komponenter kvar i verkstäderna längre ner.",al={"varför lämnades de kvar","varför finns de i gnomeregan","artificials bakgrundshistoria"}},{q="Vad behöver Klockmort dem till?",a="Klockmort Spannerspan behöver ett stort förråd av dessa universella komponenter för en serie nya, komplicerade experiment som han planerar att utföra i sin verkstad i Ironforge.",al={"varför vill klockmort ha dem","klockmorts plan"}},{q="Måste man ha gjort Klockmort's Essentials innan man tar det här uppdraget?",a="Leveransuppdraget Klockmort's Essentials introducerar Klockmort och visar dig till hans verkstad, men det är inget absolut krav för att ta uppdraget Essential Artificials.",al={"förkunskapskrav","förkrav","krävs klockmort's essentials"}}},fx={["41f0ee2b"]={q="Varför behöver Klockmort hjälp av äventyrare utifrån för att ta sig in i Gnomeregan?",a="Gnomeregan är inte längre en fungerande stad. Den är en dödlig, bestrålad krigszon som svämmar över av troggs och vettlösa spetälska gnomer. Gnomiska uppfinnare som Klockmort Spannerspan är forskare, inte frontsoldater, och de överlevande gnomerna i Tinker Town är flyktingar som lever på dvärgarnas gästfrihet, inte en invasionsarmé. För att ta sig in i stadens djupaste och farligaste delar krävs erfarna äventyrare som kan kämpa sig igenom horder av fientliga mutanter och nå förvaringsbehållarna.",al={"varför skicka mig","varför äventyrare","varför kan inte klockmort hämta dem"}}},fp="21,215,23.375.0,25.343.0,32.217.0,42.94.0,56.169.0,40.160.0,34.109.0,60.136.0"}
P.entries["quest:2925"] = {n="Klockmort's Essentials",s="Klockmort's Essentials är en kallelse med brådskande bud från nattalven Mathiel till hans gnomvän Klockmort Spannerspan. Mathiel kan inte lämna sina plikter för att resa till Dun Morogh, så han ber förbipasserande alliansresenärer att svara på Klockmorts vädjan om hjälp i Ironforge. Kallelsen leder äventyrarna till Tinkertown, där de förbereder sig för en farlig färd in i Gnomeregans bestrålade salar.",h="Klockmort's Essentials är en kallelse med brådskande bud från nattalven Mathiel till hans gnomvän Klockmort...",kw={"essential artificials","gnomeregan","ironforge","klockmort spannerspan","klockmort's essentials","spetälskegnomer","mathiel","tinkertown"},ang={["faction:Alliance"]="Det här uppdraget förbinder alliansens avlägsna territorier och knyter samman nattalvernas land med dvärgarnas bergssalar i Ironforge i ett gemensamt försvar.",["race:Gnome"]="För gnomer hjälper varje ärende som leder äventyrare till Tinkertown den desperata och pågående kampen för att återta deras förlorade hem, Gnomeregan."},sec={{t="En kallelse över kontinenterna",b="Bud färdas långt även i oroliga tider. När Klockmort Spannerspan behövde modiga bundsförvanter för ett uppdrag i Gnomeregan, vände han sig över havet till sin nattalvsbekant Mathiel. Mathiel är bunden till sin egen post och kan inte själv resa till bergariket, men han vägrar lämna sin väns vädjan obesvarad. I stället ber han dugliga alliansäventyrare som besöker honom på Warrior's Terrace i Darnassus att göra resan till Dun Morogh åt honom."},{t="Vägen till Tinkertown",b="Klockmort Spannerspan håller till i Tinkertown, Ironforges livliga flyktingdistrikt där fördrivna gnomer har samlats sedan deras underjordiska stad föll i katastrofen. Bland kugghjulens surr och ångmolnen utarbetar Klockmort planer på att hämta viktig maskinutrustning som lämnats kvar i Gnomeregans förorenade gångar. Om du följer Mathiels hänvisning kommer du direkt till Klockmorts verkstad och hjälper honom i arbetet med att återta staden."}},faq={{q="Vem ger uppdraget Klockmort's Essentials?",a="Uppdraget erbjuds av Mathiel, en nattalv som har fått bud från sin gnomvän Klockmort Spannerspan. Mathiel kan inte själv resa till Ironforge, så han ber betrodda alliansäventyrare att resa i hans ställe.",al={"uppdragsgivare","vem startar klockmort essentials","mathiels uppdrag"}},{q="Var hittar jag Klockmort Spannerspan?",a="Klockmort Spannerspan finns i Tinkertown, gnomernas kvarter i Ironforge. Han håller till bland verkstäderna och flyktingarnas utrustning som gnomerna satte upp efter att ha drivits bort från sitt förlorade hem.",al={"var finns klockmort","klockmorts plats","klockmort spannerspan ironforge"}},{q="Varför behöver Klockmort hjälp i Gnomeregan?",a="Gnomeregan översvämmades och bestrålades av giftigt nedfall, och nu kryllar staden av troggar, vansinniga spetälskegnomer och automater som löpt amok. Klockmort behöver djärva äventyrare som vågar trotsa farorna och hämta viktiga mekaniska delar från ruinerna.",al={"vad vill klockmort","varför uppdrag i gnomeregan","klockmorts syfte"}},{q="Krävs det här uppdraget för att komma in i Gnomeregan?",a="Nej, det här uppdraget är ett valfritt vägvisaruppdrag som leder dig från Mathiel direkt till Klockmort Spannerspan. Du kan prata med Klockmort i Ironforge och ta emot hans grottuppdrag direkt, även utan Mathiels introduktion.",al={"är uppdraget obligatoriskt","förutsättning för gnomeregan","kan jag hoppa över klockmort essentials"}},{q="Vilket uppdrag följer efter Klockmort's Essentials?",a="När du talar med Klockmort Spannerspan slutförs det här ärendet, och du får genast uppdraget Essential Artificials, som leder äventyrarna djupt in i Gnomeregans grotta.",al={"nästa uppdrag","fortsättningsuppdrag","uppföljning på essential artificials"}},{q="Varför är Mathiel intresserad av att hjälpa en gnom i Ironforge?",a="Mathiel och Klockmort har varit nära vänner länge. Mathiel är stationerad långt borta och kan inte lämna sin nuvarande post, men oron för vännen får honom att söka någon pålitlig som kan hjälpa till.",al={"mathiels koppling","varför bryr sig mathiel","mathiel och klockmort"}}},fx={b4ad922f={q="Varför ber Mathiel dig att åka i stället för att åka själv?",a="Mathiel är bunden av sin plikt att stanna på sin post i Darnassus och kan inte resa över havet till Dun Morogh. Han längtar efter att hjälpa sin vän Klockmort direkt, men måste förlita sig på en duglig äventyrare på väg mot Ironforge för att svara på uppmaningen i hans ställe.",al={"varför kan inte mathiel åka","varför skicka mig, mathiel","varför hjälper inte mathiel klockmort"}}},fp="22,166,24.294.0,22.296.0,43.175.0,38.152.0,43.184.0,43.150.0,42.121.0,58.162.0"}
P.entries["quest:2926"] = {n="Gnogaine",s="Gnogaine är ett alliansuppdrag som Ozzie Togglevolt erbjuder i Kharanos. I ett excentriskt försök att framställa ett botemedel mot spetälskegnomer – eller kanske brygga en ovanligt stark dryck – skickar Ozzie äventyrare mot Gnomeregan för att samla radioaktivt nedfall från lysande troggar.",h="Gnogaine är ett alliansuppdrag som Ozzie Togglevolt erbjuder i Kharanos.",kw={"gnoarn","gnogaine","gnomeregan","grönt sken","bestrålad trogg","kharanos","spetälskegnom","ozzie togglevolt","flaska","strålning"},ang={["faction:Alliance"]="Föroreningen som läcker ut från Gnomeregan hotar hela Dun Morogh. Därför är varje försök att förstå eller neutralisera nedfallet avgörande för regionens säkerhet.",["profession:Engineering"]="Hanteringen av radioaktivt avrinning direkt från källan med blyskyddade flaskor visar hur gnomisk fältforskning brukar gå till när riskerna är höga.",["race:Gnome"]="För de landsförvisade gnomerna är önskan att hitta ett botemedel åt sina bestrålade släktingar så stark att även Ozzies närmast vansinniga experiment är värda att pröva."},sec={{t="Ett botemedel eller en cocktail",b="Ända sedan Gnomeregans fall har flyktingar som Gnoarn varit helt inriktade på att utrota trogginvasionen och häva den radioaktiva åkomma som förvandlade deras släktingar. Ozzie Togglevolt och hans partner Razzle Sprysprocket väljer en mindre ortodox väg från sin verkstad i Kharanos. Ozzie påstår att de försöker hitta ett botemedel mot spetälskegnomer, men medger öppet att deras experimentella formel lika gärna kan bli ett recept på ovanligt stark rom."},{t="Samla det gröna skenet",b="För att förfina sin blandning behöver uppfinnarna rå giftig rest direkt från katastrofens epicentrum. Ozzie utrustar äventyrare med en blyflaska för insamling och skickar dem mot Gnomeregans raserade tunnlar. Där lyser kringströvande bestrålade inkräktare och plundrare – troggar genomsyrade av läckande avfall – med den sjuka gröna energi som behövs för att fylla flaskan."},{t="Hår och stora förhoppningar",b="När hela flaskan är fylld med grönt sken dröjer det inte länge innan Ozzie förbereder ett försök på en levande varelse. Han hoppas kunna återställa förstånd och hälsa hos en tillfångatagen spetälskegnom, men uppfinnaren har också egna förhoppningar på brygden och tror att nedfallsblandningen kanske kan bota hans skallighet."}},faq={{q="Vem erbjuder uppdraget Gnogaine?",a="Uppdraget ges av Ozzie Togglevolt, en uppfinnargnom som håller till i Kharanos i Dun Morogh.",al={"vem ger gnogaine","uppdragsgivare för gnogaine","ozzie togglevolts uppdrag"}},{q="Vad behöver jag samla in till uppdraget?",a="Använd en Empty Leaden Collection Phial på lysande, bestrålade troggar – närmare bestämt Irradiated Invaders eller Irradiated Pillagers – i de yttre gångarna som leder till Gnomeregan. Fortsätt tills flaskan är fylld med radioaktivt nedfall.",al={"gnogaines mål","vad ska jag samla in till gnogaine","full leaden collection phial"}},{q="Var hittar jag de bestrålade troggarna?",a="De finns i de yttre ingångsgrottorna och slingrande gångarna som leder till Gnomeregans instansportal. Du kan slutföra uppgiften utan att gå in i själva grottan.",al={"var finns bestrålade troggar","gnogaines troggplats","plats för irradiated invader"}},{q="Måste jag slutföra 'The Day After' innan jag tar det här uppdraget?",a="Nej. 'The Day After' har visserligen en berättelsemässig koppling till situationen i Kharanos och leder fram till den, men Ozzie erbjuder 'Gnogaine' oberoende av det uppdraget.",al={"krävs the day after","förutsättning för gnogaine"}},{q="Vad försöker Ozzie åstadkomma med det radioaktiva nedfallet?",a="Ozzie säger att han och Razzle försöker skapa ett botemedel mot spetälskegnomer, men medger att blandningen kanske bara blir stark rom. I hemlighet hoppas han också att den ska ge honom håret tillbaka.",al={"varför vill ozzie ha strålning","vad är gnogaine till för"}},{q="Vilket uppdrag följer efter Gnogaine?",a="När du lämnar in den fyllda flaskan får du direkt uppdraget 'The Only Cure is More Green Glow', som kräver att du tar dig djupare in i själva Gnomeregan.",al={"fortsättning på gnogaine","vad kommer efter gnogaine"}}},fx={["28ada800"]={q="Vad används Full Leaden Collection Phial till?",a="Flaskan är blyinklädd för att säkert förvara och transportera det farliga, glödande radioaktiva nedfallet som utvinns ur troggs kring Gnomeregan. Ozzie Togglevolt och Razzle Sprysprocket behöver den koncentrerade radioaktiva materien som en livsviktig ingrediens i sin experimentella brygd. De hoppas att den ska bota deras sjuka lepragnomfånge, brygga en osedvanligt stark rom eller kanske få Ozzies hår att växa ut igen.",al={"vad full leaden collection phial används till","varför blyflaskan","syftet med full leaden collection phial"}},dfd2dab8={q="Vad är de bestrålade troggsen i Gnomeregan?",a="Troggsen vällde ursprungligen upp ur djupen under Gnomeregan och översvämmade den tekniska stadens underverk. I ett desperat försök att utrota invasionen dränkte High Tinker Mekkatorque och hans rådgivare de nedre gångarna i giftig strålning. Många troggs dog inte, utan överlevde och muterade till våldsamma, bestrålade inkräktare och plundrare som nu strålar med ett sjukligt grönt sken.",al={"bestrålade inkräktare","bestrålade plundrare","varför troggs är bestrålade"}}},fp="8,183,20.360.0,19.298.0,19.200.1,30.65.0,41.146.0,39.164.0,63.128.0,64.118.0,28.95.0"}
P.entries["quest:2927"] = {n="The Day After",s="The Day After är ett uppdrag för Alliansen som knyter samman de överlevande i Ironforge med forskare i Dun Morogh. Gnoarn sörjer det katastrofala strålningsläckaget som kostade honom hans legendariska hår och hans hemland, och skickar äventyrare för att hjälpa Ozzie Togglevolt i Kharanos att hitta en lösning.",h="The Day After är ett uppdrag för Alliansen som knyter samman de överlevande i Ironforge med forskare i Dun...",kw={"gnoarn","gnomfrisyr","gnomeregan","kharanos","ozzie togglevolt","strålningsläckage","the day after","troggs"},ang={["faction:Alliance"]="Alliansens hjältar hjälper Dun Moroghs gnomiska tänkare att begränsa den märkliga biokemiska katastrof som hotar bergslandet.",["profession:Engineering"]="Ozzie Togglevolts arbete visar hur gnomiska uppfinnare tar sig an skenande tekniska katastrofer genom försök och misstag.",["race:Gnome"]="För gnomer fångar Gnoarns märkliga klagan den blandning av djup tragedi, excentrisk stolthet och bitter hämndlystnad som varje flykting från deras underbara huvudstad känner."},sec={{t="En tragisk förlust",b="Gnomeregans fall drabbade varje överlevande djupt personligen, och Gnoarn är inget undantag. Som flykting i Tinker Town i Ironforge sörjer Gnoarn inte bara det mekaniska underland som trogg-invaderarna stal, utan också sin älskade gnomfrisyr, en ståtlig man som försvann på ett ögonblick när en våg av giftigt nedfall träffade honom. Driven av kvarvarande vrede mot troggs och ett desperat hopp om att återta staden hänvisar han medkännande resenärer till kolleger som kanske fortfarande har den vetenskapliga skicklighet som krävs för att rädda det som återstår."},{t="Vägen till Kharanos",b="I stället för att ge efter för förtvivlan hänvisar Gnoarn Alliansens hjältar till Kharanos, där uppfinningsrika sinnen har börjat ta itu med nedfallet. Främst bland dem är Ozzie Togglevolt, som arbetar tillsammans med sin partner Razzle Sprysprocket. Ozzie minns katastrofens fasansfulla ögonblick tydligt och berättar hur Gnoarns lockar föll av i tussar medan vansinne och hämndtörst tog över. Nu, i den snötäckta stadens relativa trygghet, använder Ozzie sitt tekniska geni för att analysera föroreningen i hopp om att hitta ett motgift."}},faq={{q="Vem är Gnoarn?",a="Gnoarn är en gnomisk flykting som finns i Tinker Town i Ironforge. Han är djupt bitter över trogg-invasionen och stadens katastrof med radioaktiva utsläpp, och är särskilt traumatiserad av att plötsligt ha förlorat sin en gång så stolta gnomfrisyr.",al={"gnoarn","skallig gnom","vem ger uppdraget the day after"}},{q="Varför skickar Gnoarn dig till Ozzie Togglevolt?",a="Gnoarn tror att det fortfarande kan finnas hopp om att rädda Gnomeregan. Ozzie Togglevolt och hans partner Razzle är stationerade i Kharanos, där de forskar på den giftiga strålning som dröjer sig kvar i staden och försöker utveckla ett botemedel.",al={"varför gå till ozzie","ozzie togglevolt uppdrag","ingenjör i kharanos"}},{q="Vad hände med Gnomeregan?",a="Under en omfattande invasion av barbariska troggs från underjorden övertalades övermekanikern Gelbin Mekkatorque att släppa ut radioaktivt giftavfall i de nedre salarna för att utrota dem. Planen slutade i tragedi: otaliga gnomer muterade eller dog, och den tekniska staden blev obeboelig utan att troggs utplånades.",al={"vad hände med gnomeregan","varför är gnomeregan bestrålat","trogg-invasion"}},{q="Vart leder uppdragskedjan efter att du nått Ozzie?",a="När du rapporterar till Ozzie låser du upp uppdraget 'Gnogaine', där Ozzie ber dig samla radioaktivt nedfall direkt från de bestrålade troggs utanför Gnomeregan för att testa experimentella neutraliserande blandningar.",al={"fortsättning på the day after","vad kommer efter the day after","nästa uppdrag"}}},fx={b3abdd6a={q="Varför vill Gnoarn att det här ska göras?",a="Gnoarn drivs av personlig vrede och envist hopp. Det radioaktiva nedfallet som ödelade Gnomeregan berövade honom också hans stolthet och glädje: den enda gnomfrisyren i hela Azeroth. Han är bitter över sin skallighet och brinner av hämndlystnad mot de invaderande troggsen, men vägrar ge upp sitt hem. Han tror att det fortfarande finns en chans att vända katastrofen och återta staden om han leder dugliga äventyrare till Ozzie Togglevolt.",al={"gnoarns motiv","varför hjälpa gnoarn","varför gnoarn bryr sig"}}},fp="13,196,13.310.0,20.381.0,14.200.0,45.194.0,42.273.0,54.170.0"}
P.entries["quest:2928"] = {n="Gyrodrillmatic Excavationators",s="Djupt inne i Dwarven District i Stormwind förbereder Shoni the Shilent en flotta av massiva tunnelmaskiner för färd till Dun Morogh. På grund av brist på mekaniska delar skickar hon äventyrare till de bestrålade ruinerna av Gnomeregan för att samla hela kugghjul och inälvor från felande automater.",h="Djupt inne i Dwarven District i Stormwind förbereder Shoni the Shilent en flotta av massiva tunnelmaskiner...",kw={"dun morogh","dwarven district","excavationators","gnomeregan","gnomisk ingenjörskonst","gyrodrillmatic","robo-mechanical guts","shoni the shilent"},ang={["faction:Alliance"]="Genom att stödja gnomernas grävarbete från Stormwind stärks banden mellan människornas värdar och de landsflyktiga överlevande som försöker återta sitt arv.",["profession:Engineering"]="Att ta ur högprecisa urverksdelar från fallna servitörer i Gnomeregan ger en praktisk lektion i avancerad gnomisk konstruktion och reparation av tunga maskiner.",["race:Gnome"]="Varje bärgad komponent för Shonis underjordiska flotta närmare att bli verklighet och håller drömmen om återtagande och industriell återhämtning vid liv i Stormwind."},sec={{t="En flotta som behöver inälvor",b="I Dwarven District i Stormwind arbetar gnomiska ingenjörer outtröttligt för att stödja sina fördrivna fränder. En av dem är Shoni the Shilent, som leder ett ambitiöst underjordiskt projekt: en flotta gyrodrillmatic excavationators på väg till Dun Morogh. Projektet har kört fast på grund av en kritisk brist på komponenter som behövs för att få de massiva grävmaskinerna i drift."},{t="Bärgning i den fallna staden",b="I stället för att tillverka nya delar från grunden vänder sig Shoni direkt till källan för gnomisk högteknologi: den förlorade staden Gnomeregan. Ruinerna och de omgivande tunnlarna kryllar av felande försvarsrobotar, mekaniska vaktposter och urverksarbetare som strövar fritt. Äventyrare skickas dit för att plocka isär de förrymda maskinerna och frakta tillbaka två dussin buntar Robo-Mechanical Guts till människornas länder."},{t="Ett monumentalt arbete",b="De två dussinen mekaniska inälvor ger tillräckligt med skrot för att laga exakt en excavationator. Med nästan fyrahundra maskiner kvar i flottan är Shonis dröm om storskaliga underjordiska transporter fortfarande ett monumentalt och plågsamt långsamt projekt. Ändå innebär varje fungerande maskin ett litet steg mot att återta mark som gick förlorad när Gnomeregan föll."}},faq={{q="Vad är en gyrodrillmatic excavationator?",a="Det är tunga gnomiska tunnelriggar eller mullvadsmaskiner som är byggda för grävning och transport under jord. Shoni the Shilent försöker sätta ihop en hel flotta för att flytta människor eller förnödenheter till Dun Morogh.",al={"gyrodrillmatic excavationators","vad är en excavationator","gnomisk borrmaskin"}},{q="Vem är Shoni the Shilent?",a="Shoni är en gnomisk ingenjör stationerad i Dwarven District i Stormwind. Trots sitt tillnamn är hon frispråkig och krävande, och fast besluten att reparera hundratals mekaniska grävmaskiner.",al={"shoni the shilent","shoni","vem är shoni"}},{q="Varför behöver Shoni delar från just Gnomeregan?",a="Gnomeregan är fullt av hundratals vansinniga automater, urverksservitörer och försvarsmekanismer. När staden föll bröts de vanliga försörjningskedjorna för tillverkning, så de förrymda robotarna är den rikaste tillgängliga källan till kompatibla gnomiska reservdelar.",al={"varför delar från gnomeregan","varför robotinälvor","bärgning i gnomeregan"}},{q="Var hittar man Robo-Mechanical Guts?",a="De användbara inälvorna kan bärgas från mekaniska vaktposter, urverkskonstruktioner och andra fientliga varelser som vandrar i Gnomeregans korridorer, både inne i den förstörda anläggningen och längs de övre tunnelinfartsvägarna.",al={"robo-mechanical guts","var hittar man inälvor","mekaniska inälvor gnomeregan"}},{q="Är Shonis flotta färdig när en maskin har lagats?",a="Nej. Två dussin mekaniska inälvor räcker bara för att reparera en enda borrmaskin. När Shoni tar emot dem påpekar hon att hon fortfarande har 398 excavationators kvar att reparera.",al={"hur många excavationators","shonis flottas storlek","hur många borrmaskiner"}},{q="Varför förbereds en grävflotta för Dun Morogh?",a="Dun Morogh är gnomernas förfäders hem och platsen för deras fallna huvudstad. Tunga tunnelriggar kan användas för att gräva, röja undan bråte och stödja arbetet i de snötäckta bergsområdena.",al={"flotta till dun morogh","varför dun morogh","grävmaskinernas syfte"}}},fx={b2dc5b24={q="Vad används Robo-Mechanical Guts till?",a="Shoni the Shilent behöver dem som återvunna innerdelar för att reparera sin flotta av gyrodrillmatic excavationators. Den avancerade ingenjörskonsten bakom dessa underjordiska tunnelfordon kräver precisionskugghjul, ledningar och ställdon som är svåra att tillverka från grunden i Stormwind. Genom att plocka fungerande delar ur de självstyrande urverksmaskiner som strövar omkring i Gnomeregan kan hon rädda de reservdelar som behövs för att få hennes stillastående borriggar i drift igen.",al={"vad robo-mechanical guts används till","användning av robo-mechanical guts","vad shoni använder delarna till"}},["1cb24930"]={q="Vad slåss du mot inne i Gnomeregan åt Shoni?",a="Du skickas för att slå ut de förrymda robotarna och mekanismerna som vandrar omkring i Gnomeregans bestrålade salar och utkanter. När trogginvasionen och det radioaktiva nedfallet fick den underjordiska gnomiska huvudstaden på fall, började oräkneliga automatiserade försvarssystem och nyttomaskiner att fungera fel och blev fientliga mot främlingar. Shoni ser dessa övergivna, kringströvande automater inte bara som faror, utan som en hel skrotplats att ta till vara på.",al={"vem jag slåss mot åt shoni","mål i gnomeregan för delarna","vilka maskiner har delarna"}},["33a01105"]={q="Varför behöver Shoni att du samlar in delarna i stället för att göra det själv?",a="Shoni är en ingenjör som är stationerad i Dwarven District i Stormwind. Hon har fullt upp med att underhålla maskiner och övervaka monteringen av en enorm grävflotta. Att ge sig djupt in i en bestrålad ruin full av troggs och dödliga urverksvakter kräver en beväpnad äventyrare som är villig att kämpa sig genom farliga gångar. Hon stannar kvar för att granska fynden och reparera riggarna när delarna anländer.",al={"varför skicka mig efter delarna","varför går shoni inte själv","varför jag åt shoni"}}},fp="30,178,23.289.0,26.332.0,24.290.0,40.208.0,25.146.0,55.250.0,41.172.0,45.115.0,57.182.0"}
P.entries["quest:293"] = {n="Cleansing the Eye",s="Cleansing the Eye är ett Alliance-uppdrag som leder äventyrare från de dimmiga Wetlands söderut till människornas huvudstad Stormwind. Efter att ha återfunnit den förbannade klotformade reliken Eye of Paleth måste de söka hjälp hos Archbishop Benedictus för att rena den från dess kvardröjande besmittelse.",h="Cleansing the Eye är ett Alliance-uppdrag som leder äventyrare från de dimmiga Wetlands söderut till...",kw={"archbishop benedictus","cathedral of light","rena eye","cursed eye of paleth","eye of paleth","glorin steelbrow","stormwind","wetlands"},ang={["class:Paladin"]="Paladiner ser det som en högtidlig plikt att återta heliga reliker från mörka träskmarker. De betraktar Eye:s fördärv som en kränkning som måste renas i Stormwinds heliga salar.",["class:Priest"]="För präster inom Holy Light visar hanteringen av Cursed Eye of Paleth hur tragiskt lätt heliga verk kan fördärvas av förtvivlan. Det understryker vikten av Archbishop Benedictus renande ingripande.",["faction:Alliance"]="Uppdraget lyfter fram samarbetet mellan dvärgarnas utposter i Wetlands och Stormwinds andliga ledarskap och knyter samman rikena genom en gemensam tro."},sec={{t="En besmittad relik",b="Eye of Paleth, som återfunnits i träskmarkerna, lyser inte med helig klarhet. I stället är den dränkt i en oroande skugga och bär på den kvarvarande sorgen och traumat från den fruktansvärda tragedi som utspelade sig där den gick förlorad. Dvärgen Glorin Steelbrow känner igen klotets kraft, men medger att han saknar den gudomliga konsten som krävs för att häva en så svår förbannelse."},{t="Färd till katedralen",b="Eftersom Eyes of Paleth ursprungligen skapades av mänskliga präster inom Holy Light är det bara deras högsta orden som besitter kunskapen att upphäva vanhelgandet. Glorin skickar äventyrarna till kungariket Stormwind för att överlämna det förmörkade klotet till Archbishop Benedictus, ledaren för Church of the Holy Light. Benedictus inser den enorma fara en orenad relik utgör och tar på sig att återställa dess heliga sken."}},faq={{q="Vad är Eye of Paleth?",a="Eyes of Paleth är heliga klot som skapats av mänskliga präster för att lysa med heligt sken. När de är obefläckade samverkar deras kraft med Holy Light, men om de fördärvas blir deras omgivande energier instabila och farliga.",al={"eye of paleths historia","vad är det här för klot","vad är eye of paleth"}},{q="Varför kan inte Glorin Steelbrow rena Eye själv?",a="Glorin Steelbrow är en dvärg stationerad i Wetlands som saknar den särskilda liturgiska kunskap som krävs för att driva bort en så mörk förbannelse. Eftersom reliken skapades av mänskliga präster inom Holy Light krävs en auktoritet från just den traditionen för att häva dess fördärv.",al={"varför skickas jag till stormwind","glorin rening","varför benedictus"}},{q="Vem är Archbishop Benedictus?",a="Archbishop Benedictus är den vördnadsvärde ledaren för Church of the Holy Light och bor i den storslagna Cathedral of Light i Stormwind. Han är en central andlig vägledare för Alliance.",al={"vem är benedictus","archbishop benedictus","ärkebiskop i stormwind"}},{q="Varför beskrivs Eye som besudlad eller sorgsen?",a="Enligt Archbishop Benedictus bevittnade klotet en enorm tragedi i Wetlands och sög med tiden åt sig all den plågan. Den kvarvarande sorgen förvandlades till en fördärvande förbannelse som förvrängde relikens inneboende kraft.",al={"varför är den förbannad","eye of paleths tragedi","cursed eye of paleth"}},{q="Vad händer när Benedictus får klotet?",a="Benedictus går med på att utföra en reningsritual. Han varnar för att Eyes of Paleth är avsedda att lysa klart och att en sådan besmittad artefakt utgör en allvarlig andlig och fysisk fara för dem som befinner sig i närheten.",al={"renar benedictus den","vad händer med eye of paleth"}},{q="Var ligger Cathedral of Light?",a="Cathedral of Light dominerar Cathedral Square i den norra delen av Stormwind City. Archbishop Benedictus står vid huvudaltaret, mitt i helgedomen.",al={"var ligger cathedral of light","cathedral of light plats","hitta benedictus"}}},fx={["6f168d84"]={q="Varför vill Glorin Steelbrow att Eye of Paleth ska renas?",a="Glorin förstår att den förbannade Eye of Paleth är en oerhört farlig helig relik. Den skapades av mänskliga präster inom Holy Light för att lysa klart, men dess magi blir farlig och korrumperande när den besudlas av tragedi och mörk kraft. Dvärgiskt hantverk och hans egna förmågor kan inte häva en sådan andlig åkomma, så han kräver att den förs till Stormwind innan dess fördärv skadar dig eller omgivningarna ytterligare.",al={"varför rena eye of paleth","glorin steelbrows motiv","varför skicka ögat till stormwind"}}},fp="17,203,15.267.0,24.379.0,26.194.0,51.224.0,29.168.0,48.180.0,46.160.0,40.167.0"}
P.entries["quest:2930"] = {n="Data Rescue",s="När gnomerna evakuerade sin bestrålade huvudstad lämnades omfattande arkiv med ovärderlig teknisk kunskap och dokumentation kvar. Master Mechanic Castpipe i Ironforge rekryterar djärva agenter för att infiltrera Gnomeregan och hämta ett säkerhetsklassat Prismatic Punch Card. Genom flera lager av datoriserad behörighetskontroll måste kurirerna slå sig fram genom terminaler med allt starkare försvar, djupt inne i den förstörda staden.",h="När gnomerna evakuerade sin bestrålade huvudstad lämnades omfattande arkiv med ovärderlig teknisk kunskap och...",kw={"castpipe","data rescue","engineering labs","gnomeregan","matrix punchograph","prismatic punch card","hålkort","tinker town","train depot"},ang={["faction:Alliance"]="Om du hjälper Castpipe med bärgningen stöder du den fördrivna gnomiska regeringen i Ironforge och stärker enheten och den tekniska förmågan inom Grand Alliance.",["profession:Engineering"]="Matrix Punchograph-nätverket visar automatiserad datalagring när den är som bäst. Det demonstrerar de avancerade algoritmer för behörighetskontroll som Tinkers' Court har utvecklat.",["race:Gnome"]="Att hämta data från Gnomeregan innebär att återta ett stulet arv. Varje hålkort du räddar bevarar din fallna stads uppfinningsrikedom, så att den inte går förlorad till troggs och strålning."},sec={{t="Förlorade arkiv under jord",b="Gnomeregans plötsliga fall till troggs och dödlig strålning tvingade gnomerna att överge århundraden av avancerad forskning, ritningar och kommunala loggar. I de tekniska korridorerna står Matrix Punchograph-terminaler utspridda. Dessa automatiserade datahubbar hanterar säkerhetsbehörigheter och fillagring. För landsflyktiga ledare som Master Mechanic Castpipe är återställandet av dessa hålkodade arkiv från de förstörda djupen en av flyktingarnas högsta prioriteringar i Tinker Town."},{t="En hierarki av hål",b="Gnomernas datapro tokoll kräver noggrann behörighetskontroll innan åtkomst till centrala stordatorer beviljas. För att använda systemet måste du börja med ett enkelt White Punch Card, som du hittar bland bråten utanför de inre portarna. Om du sätter in det i en Matrix Punchograph 3005-A i Train Depot får du ett Yellow-kort. Ta det sedan till Dormitorys 3005-B-terminal för en Blue-uppgradering, vidare till modell 3005-C för ett Red-kort och slutligen ner till Engineering Labs för att koda det eftertraktade Prismatic Punch Card."},{t="Gnomisk humor i binär form",b="Castpipe ser uppdraget som en fråga om akut samhällsansvar, men hålkorten innehåller binära dataströmmar som avslöjar Gnomeregans datorgillens excentriska och respektlösa sinnelag. Bland verkliga tekniska data omvandlas hålmönstren till skämtsamma repliker, absurda klagomål på arbetsplatsen och grova skämt om att High Tinker Gelbin Mekkatorque bär nattalviska underkläder. Det visar att gnomingenjörer aldrig kunde motstå ett practical joke, ens mitt i den högteknologiska infrastrukturen."}},faq={{q="Vad är Prismatic Punch Card?",a="Prismatic Punch Card är det högsta säkerhetskort som Gnomeregans automatiserade stordatorer känner igen. Det skapas genom att bearbeta ett Red Punch Card i terminalen Matrix Punchograph 3005-D, djupt inne i Engineering Labs.",al={"prismatiskt hålkort","vad är ett hålkort","gnomeregan hålkort"}},{q="Var börjar hålkortssekvensen?",a="Sekvensen börjar med ett enkelt White Punch Card, som du kan rädda från troggs och övergivna maskiner strax utanför instansens huvudingång, nära Train Depot.",al={"var hittar man white punch card","hur börjar man med hålkorten","första hålkortet"}},{q="Var finns Matrix Punchograph-terminalerna?",a="Modell 3005-A står utanför instansen i Train Depot. Modell 3005-B finns inne i Dormitory, bortom Clean Zone. Modell 3005-C står på gångbroarna längre fram, medan modell 3005-D finns på den nedre nivån i Engineering Labs.",al={"terminalernas platser","var finns punchograph-terminalerna","hålkortsmaskiner"}},{q="Vem är Master Mechanic Castpipe?",a="Master Mechanic Castpipe är en erfaren gnomingenjör som bor bland flyktingarna i Ironforges Tinker Town. I sin iver att rädda Gnomeregans intellektuella arv samordnar han spanings- och bärgningsuppdrag i den fallna huvudstaden.",al={"castpipe","vem ger data rescue","castpipes historia"}},{q="Vad finns egentligen på korten?",a="När hålkorten översätts från rå ASCII-binärdata innehåller de en blandning av gnomiskt ingenjörssnack, lättsamma skämt om regionala ledare som Thrall och Mekkatorque samt excentriska anteckningar, vid sidan av stadens viktiga beräkningsdata.",al={"kortens text","binäröversättning","vad säger den binära texten"}},{q="Kan hordespelare använda terminalerna?",a="Uppdraget erbjuds enbart till Alliansen av Master Mechanic Castpipe i Ironforge, men hålkortsterminalerna i grottan kan tekniskt sett användas av alla som har de nödvändiga korten.",al={"hordens data rescue","hordens hålkort","kan horden använda terminalerna"}}},fx={["0f0753b5"]={q="Varför vill Master Mechanic Castpipe att hålkortet hämtas?",a="När gnomerna evakuerade Gnomeregan under stadens fall lämnades berg av livsviktiga driftsuppgifter och tekniska data kvar i kaoset. Master Mechanic Castpipe anser att informationen i de högsäkerhetsklassade Matrix Punchograph-terminalerna är avgörande för gnomernas överlevnad och återuppbyggnad. Han insisterar på att de inte har råd att förlora den för gott.",al={"castpipes motiv","varför castpipe behöver hålkortet","varför rädda data"}}},fp="11,210,32.373.0,27.423.0,24.288.1,33.186.0,45.138.0,51.234.0,32.192.0,35.163.0,41.165.0"}
P.entries["quest:2931"] = {n="Castpipe's Task",s="Castpipe's Task är en kallelse från Alliansen som skickar dugliga äventyrare till Master Mechanic Castpipe i Ironforge. Castpipe samordnar farliga bärgningsuppdrag i de bestrålade ruinerna av Gnomeregan för att hämta viktiga mekaniska och tekniska dokument. Den fungerar som en officiell genomgång som leder legosoldater mot uppdrag för att hämta föremål djupt inne i den fallna staden.",h="Castpipe's Task är en kallelse från Alliansen som skickar dugliga äventyrare till Master Mechanic Castpipe i...",kw={"församling","castpipe","data rescue","gaxim","gnomeregan","ironforge","rustfizzle","tinkertown"},ang={["faction:Alliance"]="När du hjälper de fördrivna gnomiska allierade att säkra sina förlorade arkiv bidrar du till att stabilisera Tinkertown och stärka Alliansens samlade tekniska ställning.",["profession:Engineering"]="Datakärnorna i Gnomeregan rymmer beräkningsmästerverk och avancerade ritningar som saknar motstycke på Azeroth.",["race:Gnome"]="Varje bärgningsuppdrag bevarar en bit av ditt fallna hem från strålning och förstörelse. Castpipes uppdrag handlar därför om kulturens överlevnad."},sec={{t="En kallelse till Tinkertown",b="Efter Gnomeregans tragiska fall och efterföljande radioaktiva avspärrning tog de överlevande gnomerna sin tillflykt till Tinkertown i Ironforge. Deras storslagna hem är fortfarande översvämmat av troggs och bestrålade konstruktioner, men viktiga driftjournaler och mekaniska ritningar finns kvar djupt inne i stadens överlevande datornätverk. Master Mechanic Castpipe insåg att filerna kunde bli ovärderliga för att återta staden eller förstå vad som gått fel. Han började därför aktivt värva orädda utomstående som vågade sig in i de giftiga korridorerna."},{t="Församlingens stöd",b="Personer som Gaxim Rustfizzle från Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences sprider ordet om Castpipes företag. Castpipe är själv inte medlem i denna ansedda akademiska sammanslutning, men andra gnomer respekterar hans tekniska kunnande tillräckligt för att stödja insatsen. Rustfizzles egna beräkningar visar att sannolikheten för att Castpipes uppdrag har verkligt strategiskt värde är uppmuntrande åttiofyra procent. Det får resenärer att bege sig till Tinkertown för att få order."}},faq={{q="Vem är Master Mechanic Castpipe?",a="Master Mechanic Castpipe är en respekterad gnomisk ingenjör som håller till i Tinkertown i Ironforge. Han organiserar bärgningslag och dataåterhämtning i Gnomeregans underjordiska ruiner.",al={"castpipe","vem är castpipe","master mechanic castpipe"}},{q="Varför vill Castpipe ha data från Gnomeregan?",a="När Gnomeregan smittades och evakuerades lämnades stora mängder viktig teknisk kunskap, ritningar och interna systemloggar kvar i stordatorns minne. Att hämta den informationen är avgörande för de fördrivna gnomer som hoppas kunna bygga upp sitt hem på nytt.",al={"data från gnomeregan","varför hämta data","dokument från gnomeregan"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en gnomisk lärd med anknytning till Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Han företräder och förmedlar kontakter genom att vägleda dugliga äventyrare till Castpipes återhämtningsuppdrag.",al={"gaxim","rustfizzle"}},{q="Var hittar man Castpipe?",a="Master Mechanic Castpipe finns i Tinkertown, det gnomiska distriktet i den östra delen av dvärgarnas huvudstad Ironforge.",al={"castpipes plats","var finns castpipe"}},{q="Vad händer när man rapporterar till Castpipe?",a="När du rapporterar till Master Mechanic Castpipe får du direkt ett uppdrag i själva den fallna staden, Data Rescue. Där måste äventyrarna ta sig in i Gnomeregans förorenade inre och hämta hålkort och lagringsmedia.",al={"nästa uppdrag","what comes next","efter castpipe"}},{q="Vad är Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences är ett ansedd gnomiskt intellektuellt sällskap som ägnar sig åt ingående vetenskapliga, magiska och mekaniska studier. Medlemmar som Gaxim Rustfizzle använder noggrann sannolikhetsberäkning för att bedöma viktiga uppdrag.",al={"församlingen","enlightened assembly"}}},fx={["0652d792"]={q="Varför skickar Gaxim Rustfizzle dig till Master Mechanic Castpipe?",a="Gaxim Rustfizzle respekterar Master Mechanic Castpipes intellekt, även om Castpipe inte är medlem i Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Enligt Gaxims beräkningar är sannolikheten åttiofyra procent att den datahämtning Castpipe förbereder i Gnomeregan är verkligt viktig för gnomerna. Med så goda odds är Gaxim ivrig att leda dugliga äventyrare till Ironforge för att stödja återtagandet.",al={"varför gaxim skickar dig","gaxim rustfizzles motiv","varför tala med castpipe"}}},fp="15,157,20.417.0,20.356.0,32.167.0,44.217.0,24.190.0,28.111.0,41.184.0,81.231.0"}
P.entries["quest:2932"] = {n="Grim Message",s="Nimboya vill straffa Witherbark-trollen för att de förrådde Thrall, trots att de en gång var Horde-allierade. Nimboyas gädda ska bära Witherbark-skallar och resas i en Witherbark-by i The Hinterlands.",h="Nimboya vill straffa Witherbark-trollen för att de förrådde Thrall, trots att de en gång var Horde-allierade.",kw={"grim message","the hinterlands","hiri'watha","nimboya","tarren mill","thrall","witherbark","zun'watha"},sec={{t="En varning i blod",b="Witherbark-trollen stod en gång på Hordes sida, tills de förrådde Thrall. Nimboya ger dig en gädda och skickar dig långt norrut till The Hinterlands, nordost om Tarren Mill, byn som hålls av Forsaken. Jaga Witherbark-troll där och samla deras skallar. Res sedan gäddan i marken i Hiri'watha eller Zun'watha, två av deras mindre byar, så att de får lära sig vad deras handlingar kostar. Efteråt väntar Nimboya i Stranglethorn."}},faq={{q="Varför vill Nimboya straffa Witherbark-trollen?",a="Nimboya säger att de var Horde-allierade som vände sig mot Thrall, och att ett sådant förräderi inte får förbli ostraffat.",al={"varför angripa witherbark","witherbarks förräderi","orsaken till grim message"}},{q="Vart skickar Nimboya dig för att resa gäddan?",a="Antingen Hiri'watha eller Zun'watha, mindre Witherbark-byar i The Hinterlands.",al={"var resa gäddan","var finns nimboyas gädda","grim message plats"}},{q="Var ligger The Hinterlands i förhållande till Tarren Mill?",a="De ligger nordost om Tarren Mill, byn som hålls av Forsaken, och långt norr om Nimboya i Stranglethorn.",al={"the hinterlands läge","var ligger the hinterlands"}},{q="Vem ger uppdraget Grim Message?",a="Nimboya i Stranglethorn räcker över gäddan och väntar där på besked.",al={"vem ger grim message","vem är nimboya"}}},fp="12,213,18.440.0,54.111.0,46.78.0,43.115.0,23.72.0"}
P.entries["quest:2933"] = {n="Venom Bottles",s="Flaskor med ett motbjudande grönt gift finns i mängder i en Witherbark-by i The Hinterlands. Det stora antalet tyder på att Witherbarks värdesätter giftet högt, och en apotekare i närbelägna Tarren Mill kanske vill ha ett prov.",h="Flaskor med ett motbjudande grönt gift finns i mängder i en Witherbark-by i The Hinterlands.",kw={"apothecary lydon","spindelliknande varelse","hinterlands","tarren mill","trollgift","giftflaska","witherbark"},sec={{t="En giftig upptäckt",b="Flaskorna i Witherbark-byn innehåller ett motbjudande grönt gift. De är så många att Witherbarks måste anse att giftet är mycket viktigt. Ett prov kan tas med till en apotekare i Tarren Mill, som kanske vill undersöka det."},{t="Lydons dom",b="Apothecary Lydon, vars experiment alla har misslyckats den dagen, tar flaskan och förklarar att innehållet är gift från någon spindelliknande varelse. Lydon frågar varifrån det kommer."}},faq={{q="Var finns giftflaskorna?",a="De finns i stora mängder i en Witherbark-by i The Hinterlands.",al={"giftflaskornas plats","var hittar man giftflaskor","witherbark-gift"}},{q="Vem är intresserad av giftflaskorna?",a="Förslaget är att ta ett prov till en apotekare i Tarren Mill. Apothecary Lydon är den du ska träffa.",al={"vem vill ha giftet","var lämnar man in giftflaskan","apotekare i tarren mill"}},{q="Vad finns i flaskorna?",a="Ett motbjudande grönt gift. Med tanke på hur många flaskor de har verkar Witherbarks värdesätta det högt.",al={"vad är giftet","vad finns i flaskorna"}}},fp="13,193,17.218.0,15.177.1,34.70.0,39.107.0,23.98.0"}
P.entries["quest:2934"] = {n="Undamaged Venom Sac",s="Apothecary Lydon i Tarren Mill vill ha ett färskt prov av giftet som redan levererats och skickar dig efter spindlarna i The Hinterlands som ger det. Tiden är knapp, eftersom det måste komma fram färskt.",h="Apothecary Lydon i Tarren Mill vill ha ett färskt prov av giftet som redan levererats och skickar dig efter...",kw={"apothecary lydon","the hinterlands","shadra'alor","spindelgift","tarren mill","giftsäck"},sec={{t="Ett färskt prov",b="Efter Venom Bottles ber Apothecary Lydon om något färskare. Spindlarna som gav giftet måste finnas i The Hinterlands, och han vill ha en oskadad giftsäck från dem. Många strövar omkring nära trollstaden Shadra'Alor. Det finns ingen tid att förlora, för säcken måste vara färsk när den kommer fram. Lydon längtar efter att experimentera med den och har beställt flera små, förfärligt söta djur att testa den på."}},faq={{q="Vem ber om den oskadade giftsäcken?",a="Apothecary Lydon i Tarren Mill ber om den och väntar där på den.",al={"vem ger oskadad giftsäck","vem startar oskadad giftsäck","uppdragsgivare för oskadad giftsäck"}},{q="Var finns spindlarna?",a="I The Hinterlands, där det finns många spindlar nära trollstaden Shadra'Alor.",al={"spindlarnas plats","var finns spindlarna","var hittar man oskadad giftsäck"}},{q="Varför säger Apothecary Lydon att du inte får dröja?",a="Färskheten är avgörande, så Lydon vill att säcken levereras utan dröjsmål.",al={"varför är det tidsbegränsat","varför blir giftsäcken dålig","tidsgräns för oskadad giftsäck"}},{q="Vad kom före det här steget?",a="Det följer efter Venom Bottles, där ett giftprov från en Witherbark-by fördes till Lydon.",al={"föregående uppdrag","vilket uppdrag kommer före oskadad giftsäck","förutsättning för oskadad giftsäck"}}},fp="19,192,14.409.0,37.67.0,31.84.0,43.71.0,27.100.0"}
P.entries["quest:2935"] = {n="Consult Master Gadrin",s="Apothecary Lydon fann att giftet från broodguards var mindre potent än provet du först tog med, vilket tyder på en annan sorts spindel. Lydon skickar dig till Master Gadrin i Sen'jin Village i Durotar, som kanske vet mer.",h="Apothecary Lydon fann att giftet från broodguards var mindre potent än provet du först tog med, vilket tyder...",kw={"apothecary lydon","rådfråga master gadrin","durotar","the hinterlands","master gadrin","sen'jin village","gift","witherbark"},sec={{t="Jakten på styrka",b="Apothecary Lydon fann att giftet från broodguards var svagare än provet du först tog med, så det måste komma från en annan sorts spindel. Lydon vill ha ett färskt prov från den starkare sorten. Fråga en troll som känner Witherbark väl för att få veta var det kommer ifrån: Master Gadrin i Sen'jin Village i Durotar. Med lite tur kan Gadrin ange var giftet kommer ifrån."}},faq={{q="Varför skickar Apothecary Lydon dig till Master Gadrin?",a="Giftet från broodguards var svagare än det första provet, vilket tyder på en annan sorts spindel. Gadrin är en troll som känner Witherbark väl och kanske kan ange var giftet kommer ifrån.",al={"varför rådfråga gadrin","varför bege sig till sen'jin","lydon gadrin"}},{q="Var finns Master Gadrin?",a="Master Gadrin finns i Sen'jin Village i Durotar.",al={"var finns gadrin","master gadrins plats","hitta master gadrin"}},{q="Vad hände före den här resan?",a="Innan dess tog du med en oskadad giftblåsa från The Hinterlands till Apothecary Lydon.",al={"förkunskapskrav","vad hände före detta","föregående uppdrag"}}},fp="21,224,20.370.0,52.194.0,31.48.0,30.85.0"}
P.entries["quest:2937"] = {n="Summoning Shadra",s="Master Gadrin ger dig ett pergament att läsa vid Shadra'Alors altare, djupt inne i Witherbark-området i The Hinterlands, för att kalla fram spindelguden Shadra. Hennes gift ska sedan föras till Apothecary Lydon i Tarren Mill.",h="Master Gadrin ger dig ett pergament att läsa vid Shadra'Alors altare, djupt inne i Witherbark-området i The...",kw={"apothecary lydon","the hinterlands","master gadrin","shadra","shadra'alor","spindelgud","tarren mill","witherbark"},sec={{t="Spindelgudens kallelse",b="Gadrins pergament ska läsas vid Shadra'Alors altare, djupt inne i Witherbark-området i The Hinterlands. Då kallas spindelguden Shadra fram. Hon måste besegras där, och hennes gift föras till Apothecary Lydon i Tarren Mill."}},faq={{q="Vem ger dig pergamentet för att kalla fram Shadra?",a="Master Gadrin ger dig pergamentet.",al={"vem ger pergamentet för att kalla fram shadra","uppdragsgivare för att kalla fram shadra"}},{q="Var kallas Shadra fram?",a="I The Hinterlands, vid Shadra'Alors altare, långt inne i Witherbark-området.",al={"var kallar man fram shadra","shadra'alors altare plats","shadras plats"}},{q="Vem tar emot giftet när Shadra har besegrats?",a="Apothecary Lydon i Tarren Mill.",al={"vem lämnar jag giftet till","inlämning av uppdraget kalla fram shadra","apothecary lydons plats"}}},fp="16,222,22.240.0,44.38.0,25.77.0,47.33.0"}
P.entries["quest:2938"] = {n="Venom to the Undercity",s="Apothecary Lydon är mycket nöjd med giftet från Witherbarks spindelgud och vill skicka ett prov till Lydons överordnade, Faranell, vid Apothecarium i Undercity. Du får ett paket att ta med på resan.",h="Apothecary Lydon är mycket nöjd med giftet från Witherbarks spindelgud och vill skicka ett prov till Lydons...",kw={"apothecarium","apothecary lydon","faranells paket","master apothecary faranell","shadra","gift till undercity"},sec={{t="Ett kraftfullt fynd",b="Lydon har dödat nästan två dussin kaniner med en enda dos av giftet. Några av dem var mycket små, så deras motståndskraft var säkert låg, men det går inte att förneka att giftet är kraftfullt. Lydon är säker på att Faranell vill testa det själv och ger dig ett paket att ta med till Apothecarium i Undercity."}},faq={{q="Vem skickar paketet till Undercity?",a="Apothecary Lydon skickar det efter att ha testat giftet från Witherbarks spindelgud.",al={"vem ger gift till undercity","uppdragsgivare gift till undercity","vem startar gift till undercity"}},{q="Vem ska ta emot giftet i Undercity?",a="Master Apothecary Faranell, Lydons överordnade, vid Apothecarium i Undercity.",al={"vem får paketet","vart skickas giftet undercity","vem är faranell"}},{q="Hur kraftfullt var giftet under testet?",a="En enda dos räckte för att döda nästan två dussin kaniner, även om några var mycket unga och små.",al={"hur starkt är shadras gift","lydons kanintester"}},{q="Vad kommer före den här leveransen?",a="Den följer på Summoning Shadra, då giftet togs från spindelguden.",al={"föregående uppdrag gift till undercity","förutsättning gift till undercity"}}},fp="22,223,13.316.0,43.90.0,54.83.0,40.96.0,32.78.0"}
P.entries["quest:2939"] = {n="In Search of Knowledge",s="Troyas Moonbreeze hittade något som ser ut som en vanlig stav bland ruinerna i Feralas, men kan inte skaka av sig känslan av att det finns mer att upptäcka. Han skickar dig till sin kollega Daryn Lightwind i Rut'theran Village.",h="Troyas Moonbreeze hittade något som ser ut som en vanlig stav bland ruinerna i Feralas, men kan inte skaka av...",kw={"angelas","darnassus","daryn lightwind","feralas","ruiner","rut'theran village","stav","troyas moonbreeze"},sec={{t="En vanlig stav",b="Troyas Moonbreeze säger att ruinerna i Feralas är farliga, men har mycket att berätta om vad som har hänt där. För några dagar sedan, när han sökte igenom rasmassorna i söder, hittade han en stav som verkar vanlig, men han kan inte skaka av sig känslan av att det finns mer att upptäcka. Han och Angelas har plöjt igenom sina böcker utan att hitta något om den."},{t="En kollega i Darnassus",b="Troyas har en kollega i Darnassus som kanske kan säga vad staven är. Han ber dig att gå och tala med henne, Daryn Lightwind, i Rut'theran Village."},{t="Daryns svar",b="Daryn muttrar över att Troyas ständigt besvärar henne med vilda idéer om att han har hittat något viktigt. Enligt henne har ogres eller harpies som numera bor i ruinerna troligen fört bort allt som verkligen var värdefullt för länge sedan. Du får gärna leta runt, tillägger hon, även om hon tvivlar på att några böcker där kan vara till hjälp."}},faq={{q="Vem skickar dig till Daryn Lightwind?",a="Troyas Moonbreeze, som vill veta vad staven han hittade i ruinerna i Feralas egentligen är.",al={"vem inleder jakten på kunskap","uppdragsgivare"}},{q="Vad hittade Troyas?",a="En stav som verkar vanlig, hittad bland rasmassorna söder om platsen där Troyas arbetar. Han känner att det finns något mer med den.",al={"vad hittade troyas","stav i feralas"}},{q="Var finns Daryn Lightwind?",a="I Rut'theran Village. Troyas beskriver henne som en kollega i Darnassus.",al={"daryn lightwinds plats","var finns daryn"}},{q="Varför skickar Troyas dig till Daryn?",a="Han och Angelas kunde inte hitta något om staven i sina böcker, och Daryn kanske kan berätta vad den är.",al={"varför besöka daryn lightwind","varför darnassus"}}},fp="22,223,17.329.0,24.152.0,13.305.1,33.92.0,21.124.0,25.72.0,34.112.0"}
P.entries["quest:294"] = {n="Ormer's Revenge",s="Ormer's Revenge inleder Ormer Ironbraids hämndkampanj. Han är en upptäcktsresande som strandat högt ovanför Whelgar's Excavation Site i Wetlands. Efter att ha grävt fram forntida förstenade ben råkade dvärgarnas utgrävningsteam locka till sig flockar av glupska, fläckiga rovfåglar. De slaktade deras kamrater och fångade de överlevande på en klippavsats.",h="Ormer's Revenge inleder Ormer Ironbraids hämndkampanj.",kw={"mottled raptor","mottled screecher","ormer ironbraid","ormer's revenge","prospector whelgar","wetlands","whelgar's excavation site"},ang={["class:Hunter"]="De aggressiva, fläckiga rovfåglarna som stryker omkring på sluttningarna utanför platsen ger skickliga jägare chansen att studera hur farliga reptiler spårar byten i träskterräng.",["race:Dwarf"]="När man ser dvärgbröder falla under en arkeologisk expedition för Explorers' League blir röjningen av det rovfågelhärjade stenbrottet en handling av vördnad för förfäderna och rättmätig hämnd."},sec={{t="Framgrävda fasor",b="Whelgar's Excavation Site skulle bli en triumf för dvärgarnas arkeologi, där enorma förhistoriska lämningar blottades under Wetlands gyttja. I stället väckte de kolossala benen träskets inhemska rovfåglars uppmärksamhet. Flockar av fläckiga rovdjur drogs till störningen, svärmade över utgrävningsplatsen och överrumplade grävarna innan de slet sig igenom deras led."},{t="En bitter kamp",b="Bara en handfull dvärgar överlevde den första slakten. Ormer Ironbraid, Merrin Rockweaver och Prospector Whelgar lyckades ta sig upp på en klippavsats med utsikt över schaktet, men de hålls fortfarande fast där av aggressiva flockar nedanför. Driven av sorg och kokande ilska vägrar Ormer att bara gömma sig. Av plikt måste han vakta den skärrade Prospector och Merrin, så han tar hjälp av stridsdugliga resenärer för att tunna ut flockarna av Mottled Raptors och Mottled Screechers i området. Det är första steget i hans hämnd."}},faq={{q="Vad hände med grävarna här?",a="När dvärgarnas arkeologer grävde fram de jättelika benen i sänkan lockade oväsendet och doften till sig rovfågelflockarna från träsket. Rovdjuren översvämmade lägret, massakrerade större delen av besättningen och fångade de tre överlevande högst upp på klippavsatsen.",al={"varför är rovfåglarna här","massakern vid whelgar's excavation site","vad dödade dvärgarna"}},{q="Vem är Ormer Ironbraid?",a="Ormer är en av dvärggrävarna som överlevde och strandade vid Whelgar's Excavation Site. Han känner sig bunden av heder att stanna och skydda den skärrade Prospector Whelgar och Merrin Rockweaver, men hans främsta önskan är blodig hämnd på rovfåglarna som slaktade hans kamrater.",al={"vem är ormer","ormer ironbraids bakgrund"}},{q="Var kommer rovfåglarna ifrån?",a="Mottled Raptors och Mottled Screechers är rovdjur som hör hemma i Wetlands. De lurar längs de leriga sluttningarna och i träskmarkerna väster om utgrävningsavsatsen, liksom på stigarna upp mot grottorna vid utgrävningsplatsen.",al={"var finns mottled raptors","rovfåglarnas platser i wetlands"}},{q="Varför jagar inte Ormer rovfåglarna själv?",a="Även om Ormer gärna själv skulle fälla rovfåglar, måste han stå vakt över den skräckslagna Prospector Whelgar och Merrin så att deras tillflyktsort på klippavsatsen inte blir övermannad.",al={"varför slåss inte ormer","varför är ormer fast"}},{q="Tar det slut på Ormers agg när rovfåglarna gallras ut?",a="Nej. Att hugga ner de vanliga Mottled Raptors och Screechers är bara första steget i Ormers plan att hämnas sina stupade vänner. Hårdare slag mot rovfågelkullen väntar.",al={"är det här slutet på ormer's revenge","vad händer sedan med ormer"}},{q="Varför lockade benen till sig rovfåglarna?",a="Rovfåglarna i Wetlands är mycket revirhävdande och letar aggressivt efter as. Sprängningarna och utgrävningen av de forntida jättelämningarna rubbade sänkans naturliga balans och drog nyfikna, hungriga rovdjur rakt in i utgrävningslägrets hjärta.",al={"varför lockade benen till sig rovfåglar","dinosaurieben och rovfåglar"}}},fx={["87324e21"]={q="Varför vill Ormer Ironbraid att rovfåglarna dödas?",a="När dvärgteamet grävde fram forntida ben på utgrävningsplatsen svärmade glupska rovfåglar över området och slaktade Ormers arbetskamrater. Ormer, Merrin Rockweaver och Prospector Whelgar överlevde knappt angreppet och är fortfarande fast uppe på klipporna. Ormer brinner av sorg och vrede och vill hämnas sina fallna bröder och börja röja bort de våldsamma bestarna från utgrävningen.",al={"ormer ironbraids motiv","varför döda mottled raptors","varför ormer vill hämnas"}},["79eca2c5"]={q="Vad är Mottled Raptors och Screechers som du skickas efter?",a="Du skickas efter Mottled Raptors och Mottled Screechers som stryker omkring strax väster om utgrävningsklippan. Dessa aggressiva kräldjur hör hemma i Wetlands och svärmade över platsen så snart grävarna blottade enorma forntida ben. De massakrerade utgrävarna och lade området runt omkring under sitt herravälde som jaktmark.",al={"vem du slåss mot","mål: mottled screechers","mottled raptors i wetlands"}}},fp="15,252,17.286.0,14.376.0,37.221.0,23.229.0,33.196.0,43.176.0,46.176.0,49.197.0"}
P.entries["quest:2940"] = {n="Feralas: A History",s="Du hittar en bok som verkar ha legat orörd i evigheter, och den kan vara precis vad Troyas behöver. Den tillhör Daryn Lightwind, så du måste fråga om du får låna den.",h="Du hittar en bok som verkar ha legat orörd i evigheter, och den kan vara precis vad Troyas behöver.",kw={"bok","daryn lightwind","feralas","historia","in search of knowledge","berättelselore","troyas"},sec={{t="En bortglömd bok",b="Bokens pärmar är illa slitna och sidorna har gulnat. När du granskar den misstänker du att det kan vara vad Troyas letar efter. Du plockar upp den, men ångrar dig och bestämmer dig för att inte låna den utan att fråga. Den tillhör Daryn Lightwind, så du bör fråga henne först."},{t="Daryns svar",b="Daryn Lightwind funderar en stund. Hon låter dig låna Feralas: A History, men först efter att du gjort henne en tjänst."}},faq={{q="Vad är boken Feralas: A History?",a="En bok med slitna pärmar och gulnade sidor, som verkar ha legat oläst i evigheter. Den kan vara precis vad Troyas letar efter.",al={"vad är boken","boken feralas a history","troyas bok"}},{q="Vem äger boken?",a="Daryn Lightwind. Du bör fråga henne innan du lånar den.",al={"vem äger feralas a history","vem har boken","vem är daryn lightwind"}},{q="Vad kommer före detta?",a="Den följer efter In Search of Knowledge, där Troyas Moonbreeze skickade dig för att prata med Daryn Lightwind om hans stav.",al={"föregående uppdrag","vad var det senaste uppdraget","uppdragskedjan före detta"}}},fp="18,192,16.252.0,14.142.1,36.148.0,18.59.0,23.117.0"}
P.entries["quest:2941"] = {n="The Borrower",s="Daryn Lightwind är fascinerad av snapjaw-sköldpaddorna på stranden i The Hinterlands, särskilt en jättelik som heter Gammerita. Hennes forskning håller henne kvar, så hon ger dig ett brev att ta med till Curgle Cranklehop i Tanaris.",h="Daryn Lightwind är fascinerad av snapjaw-sköldpaddorna på stranden i The Hinterlands, särskilt en jättelik...",kw={"curgle cranklehop","daryn lightwind","gammerita","snapjaw","ögonblicksbild","super snapper fx","tanaris","the borrower"},sec={{t="En bild av Gammerita",b="Daryn Lightwind säger att hon har studerat många ämnen, och hennes senaste fascination är snapjaw-sköldpaddorna som lever längs stranden i The Hinterlands. En som hon särskilt vill se är en jättelik snapjaw-sköldpadda som kallas Gammerita. Hon skulle själv åka dit, men hennes forskning håller henne kvar här, så en bild av Gammerita vore det näst bästa."},{t="Brevet till Tanaris",b="Daryn ger dig ett brev till Curgle Cranklehop i Tanaris. Curgle har gjort en uppfinning åt Daryn som kan ta en bild, något som Daryn tror att Curgle kallar en ögonblicksbild."},{t="Curgles reaktion",b="Curgle tror att du är en av Daryns praktikanter och talar väl om Daryn som en kunnig historiker. Sedan går Curgle för att hämta Super Snapper FX, övertygad om att du kommer att älska den."}},faq={{q="Vem skickar dig till Tanaris?",a="Daryn Lightwind, som ger dig ett brev att ta med. Hennes forskning hindrar henne från att själv åka dit.",al={"uppdragsgivare","vem ger the borrower","daryn lightwind"}},{q="Vem är Curgle Cranklehop?",a="Någon i Tanaris som har gjort en uppfinning åt Daryn som kan ta en bild, något som Daryn tror kallas en ögonblicksbild.",al={"vem är curgle","var finns curgle cranklehop","curgle tanaris"}},{q="Varför vill Daryn ha en bild av Gammerita?",a="Daryn är fascinerad av snapjaw-sköldpaddorna längs stranden i The Hinterlands och vill särskilt se Gammerita. Forskningen hindrar Daryn från att åka dit, så en bild vore det näst bästa.",al={"gammerita snapjaw","varför gammerita","jättelik snapjaw"}},{q="Vad är Gammerita?",a="En jättelik snapjaw-sköldpadda på stranden i The Hinterlands.",al={"vem är gammerita","gammerita"}}},fp="12,229,22.320.0,21.171.0,17.176.1,25.92.0,25.125.0,43.176.0,18.48.0"}
P.entries["quest:2942"] = {n="The Morrow Stone",s="I samma stund som du tar artefakten från Equinex Monolith börjar kraften i Stave of Equinex att avta. Du ska föra tillbaka Sparkling Stone och staven till Troyas Moonbreeze vid Feathermoon Stronghold.",h="I samma stund som du tar artefakten från Equinex Monolith börjar kraften i Stave of Equinex att avta.",kw={"equinex monolith","feathermoon stronghold","feralas","morrow stone","sparkling stone","stave of equinex","troyas moonbreeze"},sec={{t="Tillbaka till Feathermoon Stronghold",b="När artefakten lämnar monoliten börjar stavens energi att avta. Troyas Moonbreeze vid Feathermoon Stronghold väntar ivrigt på att få höra vad du hittade, så ta med både Sparkling Stone och staven till honom."},{t="Troyas upptäckter",b="Troyas har läst sedan du gav dig av, och han kallar stenen Morrow Stone. Han är ännu inte säker på vad den är till för, men allt som gömts inuti monoliten på det sättet måste ha stor betydelse. Han fortsätter sina studier och hoppas att du står vid hans sida."}},faq={{q="Var börjar detta?",a="Vid Equinex Monolith, när artefakten har tagits därifrån.",al={"var får jag uppdraget","var börjar morrow stone","start vid equinex monolith"}},{q="Vem ska jag lämna stenen till?",a="Troyas Moonbreeze vid Feathermoon Stronghold. Ta med Stave of Equinex också.",al={"vem lämnar in morrow stone","var finns troyas moonbreeze","vem ska få sparkling stone"}},{q="Vad händer med Stave of Equinex?",a="Dess energi börjar avta så snart artefakten tas från monoliten.",al={"stave of equinex energi","vad händer med staven","varför förlorade staven sin kraft"}},{q="Vad kommer före detta?",a="Det följer efter The Stave of Equinex, där du laddade staven bredvid monoliten.",al={"föregående uppdrag","vilket uppdrag kommer före the morrow stone","förutsättningsuppdrag"}}},fp="16,213,30.204.0,17.267.1,22.66.0,28.77.0,37.77.0,23.86.0"}
P.entries["quest:2943"] = {n="Return to Troyas",s="Daryn Lightwind lämnar över sin bok, Feralas: A History, och ber dig ta hand om den. Den ska till Troyas Moonbreeze vid Feathermoon Stronghold, som säkert ser fram emot att du kommer tillbaka.",h="Daryn Lightwind lämnar över sin bok, Feralas: A History, och ber dig ta hand om den.",kw={"darnassus","daryn lightwind","feathermoon stronghold","feralas","feralas: a history","troyas moonbreeze"},sec={{t="En lånad bok",b="När du har Super Snapper FX bakom dig ger Daryn Lightwind dig sin bok och ber dig ta hand om den. Hon uppmanar dig att skynda dig, övertygad om att Troyas ser fram emot att du kommer tillbaka. Boken ska till Troyas Moonbreeze vid Feathermoon Stronghold."},{t="Troyas läser",b="Troyas blir glad när du kommer med boken. Han tittar på den, bläddrar igenom sidorna och utbrister att han tror att han har hittat den."}},faq={{q="Vad ska jag lämna över?",a="Daryn Lightwinds bok, Feralas: A History.",al={"vilken bok är det här","vad ska jag ta med till troyas","feralas a history-boken"}},{q="Var finns Troyas Moonbreeze?",a="Vid Feathermoon Stronghold.",al={"troyas plats","var finns troyas moonbreeze","vart ska jag gå"}},{q="Vem ger dig boken?",a="Daryn Lightwind, som ber dig ta hand om den.",al={"vem ger uppdraget","uppdragsgivare","daryn lightwind"}},{q="Vad hände före det här?",a="Den följer efter The Super Snapper FX.",al={"föregående uppdrag","vad gjorde jag nyss","uppdragskedjan före detta"}}},fp="16,182,15.245.0,12.116.1,21.43.0,27.26.0,23.49.0,22.32.0"}
P.entries["quest:2944"] = {n="The Super Snapper FX",s="Curgle Cranklehop har en ny kameraapparat redo, Super Snapper FX, och ger dig den att prova. Motivet är Gammerita, en varelse från The Hinterlands. Med bilden i handen tar du med den och apparaten till Daryn Lightwind i Rut'theran Village. Detta följer efter The Borrower.",h="Curgle Cranklehop har en ny kameraapparat redo, Super Snapper FX, och ger dig den att prova.",kw={"curgle cranklehop","daryn lightwind","gammerita","rut'theran village","bild","super snapper fx","the hinterlands"},sec={{t="En apparat att testa",b="Efter The Borrower visar Curgle Cranklehop dig Super Snapper FX, en ny uppfinning. Den är enkel att använda: rikta den mot det du vill fotografera och tryck på knappen. Curgle ger den till dig att prova."},{t="Motivet",b="Motivet är Gammerita, en varelse från The Hinterlands som du hade nämnt för Curgle. Curgle önskar dig lycka till med att hitta henne och tror att Daryn Lightwind kommer att uppskatta bilden. När du har den tar du bilden och apparaten till Daryn i Rut'theran Village."}},faq={{q="Vem ger dig Super Snapper FX?",a="Curgle Cranklehop ger dig apparaten, en ny uppfinning, så att du kan prova den.",al={"vem ger super snapper","curgle uppdragsgivare","var får man super snapper fx"}},{q="Vad ska jag fotografera med Super Snapper FX?",a="Gammerita, en varelse från The Hinterlands. Curgle önskar dig lycka till med att hitta henne.",al={"gammeritas plats","var finns gammerita","bild av gammerita"}},{q="Vem tar emot bilden?",a="Daryn Lightwind i Rut'theran Village. Du tar med både bilden och apparaten till henne.",al={"lämna in super snapper fx","vart ska bilden","vem är daryn lightwind"}},{q="Vad händer härnäst i kedjan?",a="Kedjan fortsätter med Return to Troyas.",al={"nästa uppdrag efter super snapper","vad följer efter super snapper fx"}}},fp="20,293,16.215.0,11.271.0,31.76.0,47.79.0,26.86.0,29.40.0"}
P.entries["quest:2945"] = {n="Grime-Encrusted Ring",s="Djupt inne i Gnomeregans bestrålade ruiner kan äventyrare hitta ett smycke täckt av giftigt avfall och hårdnad smuts från en inkräktare av Dark Iron-dvärgarna. För att ta reda på vad det är måste du använda Sparklematic 5200, en industriell rengöringsautomat i Dormitory-sektorn. När ringen har skrubbats ren avslöjar den personliga märkningar som leder till ett försök att återlämna eller göra om arvegodset.",h="Djupt inne i Gnomeregans bestrålade ruiner kan äventyrare hitta ett smycke täckt av giftigt avfall och...",kw={"clean zone","dark iron","dormitory","gnomeregan","grime-encrusted ring","return of the ring","sparklematic 5200"},ang={["profession:Engineering"]="Sparklematic 5200 är ett klassiskt exempel på egenartad gnomisk ingenjörskonst, där industriell lösningsmedelsskrubbning kombineras med automatisk presentinslagning.",["race:Dwarf"]="Att ringen finns hos en infiltrerande Dark Iron-dvärg antyder att det är byte som tagits från Ironforge eller från gnomiska offer under kaoset när Gnomeregan föll.",["race:Gnome"]="Till och med när deras stad gick under i katastrofen konstruerade gnomerna saneringsmaskiner som avslutade farliga industriella tvättcykler med en glad klocksignal och en rosett."},sec={{t="En relik under smutsen",b="Gnomeregans korridorer är fulla av giftigt slam, olja och radioaktivt nedfall, så det är inte konstigt att föremål som tappas i striderna blir täckta av ogenomtränglig smuts. Dark Iron-dvärgar som dödats under sin infiltration av staden bär ofta på kraftigt nedsmutsade småsaker, främst den här smutsiga ringen. Skorpan är alldeles för hård för vanlig handtvätt och döljer helt om metallen under är koppar, guld eller skräp."},{t="Sparklematic 5200",b="För att rengöra ringen måste du hitta Sparklematic 5200 i Clean Zone-dormitoriet. Maskinen är gnomisk ingenjörskonst när den är som mest härligt absurd: den tar emot mynt, skrubbar kraftigt nedsmutsade föremål våldsamt på insidan och spottar ut dem nyputsade och prydligt inslagna med en rosett. När det bestrålade smutslagret försvinner syns stadens sigill och ingraverade initialer på ringens insida, och en upphittad småsak blir början på ett försök till gottgörelse."}},faq={{q="Var hittar du Grime-Encrusted Ring?",a="Grime-Encrusted Ring kan hittas på liken efter Dark Iron-dvärgar inne i den belägrade grottan Gnomeregan.",al={"ringens byte","var droppar grime-encrusted ring","vem droppar grime-encrusted ring"}},{q="Hur rengör du ringen?",a="Ta ringen till Sparklematic 5200, som finns i Clean Zone-dormitoriet inne i Gnomeregan. När du lägger i ringen och betalar den angivna myntavgiften startar en intensiv automatisk skrubbning som avlägsnar den hårdnade smutsen.",al={"rengöra ring","hur rengör man grime-encrusted ring","var tvättar man ringen"}},{q="Vad händer när ringen har rengjorts?",a="Sparklematic lämnar ut en prydligt förpackad ask som innehåller en återställd ring med särskilda personliga gravyrer. Då börjar uppdraget Return of the Ring, som leder dig till att hitta ringens ursprungliga ägare.",al={"nästa uppdrag för grime-encrusted ring","vad gör jag med den rena ringen","resultat av sparklematic på ringen"}},{q="Kan Horde-spelare slutföra uppdraget?",a="Ja. Horde-äventyrare kan använda Sparklematic 5200 för att rengöra ringen. Senare steg i uppdragskedjan skiljer sig dock åt och leder till slut Horde-spelare till en ingenjör i Orgrimmar i stället för att återlämna den till Ironforge.",al={"är grime-encrusted ring bara för alliance","horde grime-encrusted ring","kan horde rengöra ringen"}},{q="Varför slås ringen in i en presentask efter rengöringen?",a="Sparklematic 5200 är byggd med typisk gnomisk lekfullhet. Förutom att skrubba bort slam och smuts med kraft är apparaten programmerad att automatiskt förpacka föremål och knyta en dekorativ rosett runt dem när behandlingen är klar.",al={"presentinslagen ring","varför presentask från sparklematic"}},{q="Finns det flera Sparklematic-maskiner?",a="Flera Sparklematic-enheter står längs väggen i Clean Zone-dormitoriet, men bara en fungerar som den ska för ringen: den till vänster när du kommer in via trappan, nära de vänligt sinnade gnomerna.",al={"vilken sparklematic","sparklematic 5200 platser"}}},fx={["5abd59ba"]={q="Varför behöver du rengöra Grime-Encrusted Ring?",a="När du bänder loss ringen från den fallna Dark Iron-dvärgen är den täckt av en tjock, hårdnad skorpa av radioaktivt slam och grottgegga. Under smutsen anar du ett skimmer från ädelmetall och en ädelsten, men den intorkade beläggningen gör den omöjlig att bära och granska. Det enda sättet att se dess verkliga hantverk och ta reda på om den har något värde eller syfte är att rengöra den.",al={"varför rengöra ringen","syftet med den smutsiga ringen","varför tvätta den smutsiga ringen"}},c5a1096d={q="Vad är Grime-Encrusted Ring?",a="Det verkar vara ett värdefullt smycke som en av de invaderande Dark Iron-dvärgarna bar med sig in i Gnomeregan. Irradierad industrismuts täcker det helt och döljer det fina metallarbetet och den infattade stenen. De blir synliga först när ringen körs genom Gnomeregans automatiserade rengöringsapparat, Sparklematic 5200.",al={"vad grime-encrusted ring är","historien bakom grime-encrusted ring","vad det är för slags ring"}}},fp="20,180,24.283.0,21.283.1,43.51.0,26.150.0,39.190.0,38.158.0,53.138.0,41.168.0"}
P.entries["quest:2947"] = {n="Return of the Ring",s="Efter att ha skurat bort lager av underjordiskt slam i Gnomeregans automatiska rengöringsapparat hittar en äventyrare en skinande guldring med Ironforges sigill och initialerna ”TdK”. Spåren leder till dvärgarnas huvudstads livliga hantverksgränder, där ringens excentriske skapare finns.",h="Efter att ha skurat bort lager av underjordiskt slam i Gnomeregans automatiska rengöringsapparat hittar en...",kw={"brilliant gold ring","dark iron","ironforges sigill","mystic ward","sparklematic","talvash del kissel","tdk"},ang={["faction:Alliance"]="Fyndet av artefakter märkta med Ironforges sigill hos Dark Iron-infiltratörer förstärker det växande hotet från kejsar Thaurissans agenter mot Alliansens hem i bergen.",["race:Gnome"]="Att återfinna förlorade hantverksföremål från den fallna staden ger en sällsynt inblick i det fredliga vardagshantverk som gnomer ägnade sig åt före Thermapluggs katastrof."},sec={{t="En skatt täckt av slam",b="Djupt inne i Gnomeregans bestrålade ruiner surrar uråldriga maskiner fortfarande trotsigt vidare under trogginvasionen. När en smutsig, ingrodd prydnad förs in i Sparklematic 5200 avlägsnas åratal av bestrålat giftigt smuts, och en polerad Brilliant Gold Ring blottas, pulserande av mystisk kraft. På ringens insida syns Ironforges tydliga sigill, intill tre prydligt graverade initialer: ”TdK”."},{t="Hantverkaren i Mystic Ward",b="Initialerna tillhör ingen mindre än Talvash del Kissel, en excentrisk gnomjuvelerare med verkstad i Ironforges Mystic Ward, där han ofta frenetiskt värjer sig mot inbillade inkasserare. Talvash känner genast igen hantverket som en av sina standardmodeller från tiden före fallet, från sin gamla butik i Gnomeregan. När han får veta att prydnaden hittades hos Dark Iron-infiltratörer blir hantverkaren djupt skakad, vilket antyder dunkla intriger under den förlorade teknologistaden."}},faq={{q="Vem gjorde ringen som hittades i Gnomeregan?",a="Initialerna ”TdK” tillhör Talvash del Kissel, en udda gnomjuvelerare som numera bor i Ironforges Mystic Ward. Innan Gnomeregan föll drev Talvash en juvelerarbutik i staden och smidde flera enkla magiska ringar av den modellen.",al={"vem gjorde ringen","ringens initialer tdk","vem är tdk"}},{q="Varifrån kom ringen ursprungligen?",a="Ringen upptäcktes som en smutsig, ingrodd prydnad djupt inne i Gnomeregan, buren av fientliga inkräktare som Dark Iron-dvärgarna. Efter en tur genom den automatiska Sparklematic 5200 återställdes dess gyllene glans och tillverkarens märkning.",al={"var hittades ringen","var kommer ringen ifrån"}},{q="Varför bar Dark Iron-dvärgar på Talvashs ring?",a="Talvash är inte helt säker, men han påpekar att hans hantverk från tiden före fallet på Dark Iron-infiltratörer lägger ytterligare ett misstänkt lager till konspirationerna kring Gnomeregans undergång. Ringen kom troligen från hans övergivna verkstad eller plundrades från någon som inte lyckades fly invasionen.",al={"varför har dark irons den","dark iron-ringens bakgrund"}},{q="Varför tror Talvash del Kissel att du är hans hyresvärd?",a="Talvash är ökänd för att vara nervös, excentrisk och ständigt sen med hyran i Ironforge. När främlingar närmar sig hans butik på ett aggressivt sätt antar han att de är utmätningsmän eller hyresvärdar som kommit för att kräva in hans förfallna skulder.",al={"varför är talvash paranoid","talvashs hyra"}},{q="Tillverkar Talvash förtrollade smycken?",a="Talvash försäkrar bestämt alla potentiella kunder om att han inte tillverkar förbannade föremål, även om hans nervösa, förebyggande nekanden brukar väcka fler frågor än de besvarar.",al={"är talvash förbannad","förbannade smycken ironforge"}},{q="Kan jag behålla ringen i stället för att lämna tillbaka den?",a="Prydnaden har magiska egenskaper i sig, men om du visar den för dess skapare kan Talvash undersöka den och erbjuda sig att förfina dess förtrollning ytterligare genom fortsatt arbete.",al={"behålla ringen","bör jag lämna tillbaka ringen"}}},fx={["8e194cce"]={q="Varför vill Sparklematic 5200 ha ringen tillbaka?",a="Det vill den inte. Sparklematic 5200 är en automatisk rengöringsapparat som bearbetar smutsiga fynd från Gnomeregans djup. Den rengör vad du än lägger i den och spottar ut det återställda föremålet. När maskinen lämnar ut den polerade Brilliant Gold Ring är det helt och hållet ditt val om du lämnar tillbaka den, efter att du upptäckt tillverkarens märke och Ironforge-sigillet präglat på insidan av ringen.",al={"varför lämna tillbaka ringen","sparklematic 5200s motiv","varför maskinen vill ha tillbaka ringen"}}},fp="18,314,24.408.0,30.489.1,38.253.0,40.239.0,51.293.0,55.225.0,33.178.0,49.188.0"}
P.entries["quest:2948"] = {n="Gnome Improvement",s="När en äventyrare ger honom en ring han en gång tillverkade, återfunnen i Gnomeregans radioaktiva djup, erbjuder Talvash del Kissel sig att uppgradera den om äventyraren skaffar materialet. I Ironforge, dvärgarnas huvudstad, har gnomhantverkaren det knapert. Han kombinerar silver, Moss Agate och ett intrikat gallerverk för att skapa ett betydligt finare smycke.",h="När en äventyrare ger honom en ring han en gång tillverkade, återfunnen i Gnomeregans radioaktiva djup...",kw={"brilliant gold ring","gnome improvement","gnomeregan","ironforge","moss agate","silver bar","talvash"},ang={["faction:Alliance"]="Uppdraget utspelar sig mellan Gnomeregan och Ironforge och stärker banden mellan Alliansens hjältar och flyktingarna från gnomernas fallna huvudstad.",["profession:Mining"]="Gruvarbetare bidrar med de viktiga råvarorna: smält silver och slipade Moss Agate som hittas i underjordiska fyndigheter. Materialen behövs för Talvashs juvelerararbete.",["race:Gnome"]="Uppdraget lyfter fram gnomhantverkarnas stolthet och motståndskraft. De vägrar att utföra undermåligt arbete även när de tvingats lämna sitt hemland och står utan råvaror."},sec={{t="En gnomhantverkare i exil",b="Talvash del Kissel är en av många gnomflyktingar som flydde från Gnomeregan efter stadens katastrofala fall till trogginvasionen och strålningen. Talvash bor i Mystic Ward i Ironforge och har det knapert, saknar material och är desperat att bevisa att hans talanger som mästerlig juvelerare och uppfinnare förblir intakta trots exilen."},{t="Uppgradera den gamla ringen",b="När en äventyrare visar Talvash en ring av hans egen enkla design från tiden före stadens fall, rengjord från smutsen av Sparklematic 5200, blir Talvash tacksam men ambitiös. Han låter inte en kund gå därifrån med vad han anser vara en föråldrad, enkel ring. I stället insisterar han på att förbättra den. Genom att lägga ett fint gallerverk av silver och Moss Agate över ringen skapar han ett förbättrat smycke som visar hur hans skicklighet i metall- och ädelstenshantverk utvecklas."}},faq={{q="Vem är Talvash del Kissel?",a="Talvash del Kissel är en skicklig gnomhantverkare och juvelerare som nu lever i exil i Ironforge. Före stadens fall drev han en liten juvelerarbutik i Gnomeregan. En av ringarna han tillverkade där kan återfinnas och tas med till honom i Mystic Ward.",al={"talvash","talvash del kissel","gnomjuvelerare ironforge"}},{q="Vad är ringens historia?",a="Grundringen är en av flera enkla ringar som Talvash tillverkade i sin gamla butik i Gnomeregan. Senare hittades den på en Dark Iron-dvärg i ruinerna. När äventyrare har hämtat den ur rengöringsmaskinen Sparklematic 5200 i den förstörda staden erbjuder Talvash sig att modernisera och smycka den enkla ringen till ett betydligt finare smycke.",al={"var kommer ringen ifrån","grime encrusted ring ursprung"}},{q="Varför ber Talvash spelaren skaffa reagenserna?",a="Precis som många gnomflyktingar som tvingats lämna Gnomeregan har Talvash det svårt ekonomiskt och har helt gjort slut på sina råvaror i Ironforge. Han saknar silver och Moss Agate för att själv utföra det fina gallerarbetet utan en sponsor.",al={"varför behöver jag silver och moss agate","varför har talvash inga material"}},{q="Var börjar den här uppdragskedjan?",a="Uppdragskedjan börjar i Gnomeregan-instansen. Hämta en Grime-Encrusted Ring från fiender, rengör den i maskinen Sparklematic 5200 och följ sedan de ingraverade initialerna ”TdK” till Talvash i Ironforge.",al={"hur startar jag gnome improvement","var börjar ringuppdragskedjan"}},{q="Är Talvash bitter över sin situation i Ironforge?",a="Han beklagar att han sitter fast i vad han kallar en orättvis ekonomisk knipa, men Talvash håller humöret uppe och är stolt över sitt yrke. Han är övertygad om att han blir känd i hela Azeroth för att tillverka de finaste smyckena när han väl kommer på fötter igen.",al={"talvashs bakgrund","talvashs personlighet"}},{q="Kan Horden göra det här uppdraget?",a="Nej. Horde-spelare kan rengöra Grime-Encrusted-föremål i Gnomeregan, men deras version av ringuppdraget leder dem till en annan kontakt, Nogg i Orgrimmar, i stället för Talvash i Ironforge.",al={"kan horden göra gnome improvement","hordens ringuppgradering"}}},fx={["2e3e2066"]={q="Vad används Silver Bar till?",a="Talvash behöver den förädlade metallen för att forma om din ursprungliga ring till ett mer utsmyckat smycke. Han använder silverstången för att smida ett detaljerat gallerverk direkt på ringen, vilket ger den enkla designen mycket större elegans och hållbarhet än hans tidiga hantverk hade.",al={"varför silver bar","talvash och silver bar","vad han behöver silver till"}},a02fa77a={q="Vad används Moss Agate till?",a="Moss Agate blir ringens dekorativa mittpunkt efter uppgraderingen. Talvash tänker infatta den polerade gröna ädelstenen i det nytillverkade silvergallerverket för att ge ringen mer stil och visa sin verkliga skicklighet som hantverkare. På så vis förvandlar han en enkel prydnad till ett betydligt imponerande verk.",al={"varför moss agate","talvash och moss agate","vad han behöver agat till"}}},fp="17,153,26.270.0,22.232.0,26.213.0,51.266.0,56.136.0,34.176.0,51.197.0,41.132.0"}
P.entries["quest:2949"] = {n="Return of the Ring",s="Efter att ha skurat bort smutsen från Gnomeregan i Sparklematic 5200 hittar en äventyrare en ring med Orgrimmars sigill och bokstäverna ”NOG” ingraverade. Spåren leder till Horde-huvudstaden och gobliningenjören Nogg, som har egna märkliga teorier om stadens fall.",h="Efter att ha skurat bort smutsen från Gnomeregan i Sparklematic 5200 hittar en äventyrare en ring med...",kw={"brilliant gold ring","dark iron","gnomeregan","nogg","orgrimmar","ringens återkomst","sparklematic 5200","valley of honor"},ang={["faction:Horde"]="Att hitta Hordes symboler djupt inne i Eastern Kingdoms främsta teknologiska huvudstad är ovanligt. Det lockar Horde-äventyrare från Khaz Modan raka vägen tillbaka till Valley of Honor.",["profession:Engineering"]="Gobliningenjörerna i Orgrimmar mäter sig ständigt mot gnomernas uppfinningsrikedom, och Nogg vill gärna plocka isär allt som hämtas från hjärtat av deras fallna teknologiska underverk."},sec={{t="Ett märkligt fynd",b="Gnomeregan är en Alliance-stad djupt inne i Khaz Modan, så fyndet av en ring med Orgrimmars officiella sigill är minst sagt oväntat. När den lilla prydnaden rengörs i gnomernas Sparklematic-anläggning lossnar det tjocka lagret av underjordisk sörja. Då blottas en stark magisk kraft och de delvis läsliga bokstäverna ”NOG”. Oavsett om den tillverkades i Kalimdor eller följde med på en olycksalig expedition har ringen tydliga kopplingar till Horde-huvudstaden."},{t="Gnomiska rivaler och mörka planer",b="När ringen förs tillbaka till Valley of Honor i Orgrimmar leder spåren direkt till Nogg, en ingenjör som snabbt förklarar att ringen inte är hans personliga smycke, men att dess ursprung väcker intressanta frågor. Gobliner har länge sett ner på gnomiska uppfinnare som excentriska rivaler. För Nogg tyder det faktum att Dark Iron-dvärgarna hade ringen i Gnomeregan på att gnomerna kan ha stulit och förändrat Dark Irons golemkonstruktioner. Det skulle ge Dark Irons skäl att hämnas, och Nogg tycker att spåret är värt att undersöka."}},faq={{q="Varför har en ring som hittades i Gnomeregan Orgrimmars sigill?",a="Det är fortfarande okänt exakt hur ringen hamnade i Gnomeregan, men den bars djupt in i ruinerna och återfanns av Dark Iron-dvärgar. Orgrimmars insignier knyter den till Hordes metallhantverkare och smeder i Durotar.",al={"varför orgrimmars sigill","hordering i gnomeregan","hur hamnade ringen där"}},{q="Vem är Nogg?",a="Nogg är en gobliningenjör i Valley of Honor i Orgrimmar. Han ansvarar för ingenjörsutrustning och maskiner, och hans namn stämmer med de slitna bokstäverna på den rengjorda ringen, bredvid Orgrimmars sigill.",al={"vem är nogg","nogg i orgrimmar","nogg-bokstäver på ringen"}},{q="Vad är Sparklematic 5200?",a="Sparklematic 5200 är ett automatiserat industriellt tvättsystem i Clean Zone i Gnomeregan. Det avlägsnar tjocka lager giftigt slam och strålning från föremål som släpas ut ur de förstörda korridorerna.",al={"vad är sparklematic","sparklematic 5200","cleanomatic"}},{q="Äger Nogg ringen?",a="Nej. När Nogg får se den rengjorda ringen undersöker han den och erkänner att den inte tillhör honom. Han känner dock igen hantverket och använder sina ingenjörskunskaper för att förbättra den åt äventyraren.",al={"är det noggs ring","tappade nogg sin ring","vem äger ringen"}},{q="Vad tror Nogg hände med Gnomeregan?",a="Nogg misstänker att gnomerna stal avancerade golemritningar från Dark Iron-klanen. Han resonerar att Dark Irons skulle vilja hämnas rejält och tycker att spåret är värt att undersöka.",al={"noggs teori om gnomeregan","vad hände med gnomeregan","varför dark iron-dvärgar"}},{q="Kan jag behålla ringen i stället för att lämna tillbaka den till Nogg?",a="Du väljer själv om du vill bära ringen direkt eller ta den till Orgrimmar. Om du tar den till Nogg får gobliningenjören undersöka hantverket och erbjuda ytterligare förbättringar.",al={"behålla brilliant gold ring","bör jag lämna tillbaka ringen","måste jag ge den till nogg"}}},fx={["9392e9ce"]={q="Varför vill Sparklematic 5200 ha ringen tillbaka?",a="Sparklematic 5200 har ingen egen vilja eller drivkraft. Det är bara en automatisk rengöringsapparat i Gnomeregan som skrubbar bort smuts från bärgade föremål och spottar ut det som kommer ut. När den har rengjort din smutsiga ring och lämnat ut den i en inslagen låda är dess uppgift klar. Det är enbart din egen nyfikenhet som får dig att leta efter initialerna inristade på insidan av ringen, när du upptäcker Orgrimmar-sigillet och de ofullständiga bokstäverna.",al={"sparklematics motiv","varför lämna tillbaka ringen till sparklematic","sparklematic 5200s mål"}}},fp="18,140,19.394.0,37.391.1,63.203.0,12.163.0,30.193.0,23.151.1,44.169.0,52.157.0"}
P.entries["quest:295"] = {n="Ormer's Revenge",s="Ormer's Revenge är ett alliansuppdrag som Ormer Ironbraid ger vid den förstörda utgrävningsplatsen Whelgar's Excavation Site i Wetlands. När de första spaningsraptorerna har gallrats ut kräver Ormer att de större Mottled Scytheclaws och Razormaws som drev bort hans expedition från utgrävningsgroparna slaktas.",h="Ormer's Revenge är ett alliansuppdrag som Ormer Ironbraid ger vid den förstörda utgrävningsplatsen Whelgar's...",kw={"dvärg","utgrävning","explorers league","mottled razormaw","mottled scytheclaw","ormer ironbraid","raptorer","wetlands","whelgar's excavation"},ang={["class:Hunter"]="De spräckliga raptorerna i Wetlands är våldsamt revirhävdande flockjägare och utgör en dödlig spårningsutmaning i de trånga, leriga skyttegravarna.",["faction:Alliance"]="När Whelgar's Excavation Site återtas blir verksamheten tryggare längs den östra vägen mellan Wetlands och Arathi Highlands.",["race:Dwarf"]="Ormers vrede speglar Explorers' Leagues starka stolthet. De vägrar låta vilddjur stoppa dvärgarnas försök att gräva fram sina förfäders historia för gott."},sec={{t="Jakten trappas upp",b="Ormer Ironbraids agg mot raptorerna som härjar vid Whelgar's Excavation Site är djupt personligt. Efter att ha gallrat ut de mindre ungarna som översvämmade det övre lägret riktar han dina klingor mot de vuxna rovdjuren som stryker omkring vid den nedre utgrävningen. Mottled Scytheclaws och Razormaws utgör det största hotet mot varje hopp om att återuppta det arkeologiska arbetet. De sliter sig igenom dvärgprospektörer och lämnar skyttegravarna fulla av krossade lådor och övergivna hackor."},{t="Blod i skyttegravarna",b="Utgrävningsgroparna har i praktiken blivit en raptorboplats. Medan Ormer grubblar på åsen med utsikt över utgrävningen skickar han kapabla äventyrare ner i leran för att gå till direkt angrepp mot de fullvuxna bestarna. Prospector Whelgar och hans besättning hoppas kunna rädda forntida reliker, men Ormer är helt uppslukad av hämnd. Han kräver att många Scytheclaws och Razormaws dödas innan han ens överväger att ta sig an platsens största skräck."}},faq={{q="Varför är Ormer så arg på raptorerna?",a="De spräckliga raptorerna svärmade våldsamt över Whelgar's Excavation Site och övermannade platsen. De drev bort dvärggruppen och slaktade alla som inte hann fly. Ormer Ironbraid tvingades lämna platsen och blev bitter. Han vägrar låta bestarna ta kontroll över utgrävningen utan att betala dyrt i blod.",al={"varför är ormer arg","orsaken till ormers hämnd","varför döda raptorer i wetlands"}},{q="Var finns Mottled Scytheclaws och Razormaws?",a="Båda raptorvarianterna stryker omkring i de nedre utgrävningsgravarna och jordvallarna vid Whelgar's Excavation Site, öster om Menethil Harbor och sydväst om Dun Modr i Wetlands.",al={"mottled scytheclaw plats","mottled razormaw plats","var hittar man ormers raptorer"}},{q="Vem är Ormer Ironbraid?",a="Ormer Ironbraid är en dvärg i Explorers' League som är stationerad vid Whelgar's Excavation Site. Efter att utgrävningen katastrofalt översvämmades av raptorer har han gjort det till sin personliga uppgift att utrota flocken som angriper deras arbete.",al={"vem är ormer","ormer ironbraid bakgrund"}},{q="Vad händer när raptorerna har gallrats ut?",a="När du har gallrat ut Scytheclaws och Razormaws riktar Ormer uppmärksamheten mot Sarltooth, den stora raptor som han tror leder den lokala flocken. Han ber dig göra slut på den främsta orsaken till raptorplågan.",al={"vad händer efter ormers hämnd","uppföljare till ormer's revenge","nästa uppdrag efter scytheclaws"}},{q="Har uppdraget samband med andra uppgifter vid utgrävningsplatsen?",a="Ja. När äventyrare jagar raptorer vid den nedre utgrävningen åt Ormer hjälper de ofta Prospector Whelgar och hans grupp med 'Uncovering the Past' genom att samla in fragment av jordiska artefakter som ligger utspridda i samma skyttegravar.",al={"uppdrag vid whelgar's excavation","samband med uncovering the past"}},{q="Varför grävde dvärgarna här från början?",a="Explorers' League från Ironforge anlade Whelgar's Excavation Site för att leta efter titanska reliker och avslöja dvärgarnas forntida historia. Arbetet avbröts när aggressiva vilddjur invaderade utgrävningen.",al={"varför gräva i wetlands","syftet med whelgar's excavation"}}},fx={["2ccf3294"]={q="Vad är Mottled Scytheclaws och Mottled Razormaws?",a="Dessa våldsamma rovfågelraser stryker omkring på de nedre nivåerna av Whelgar Excavation Site. De är kända för sin blodtörst och sina rakbladsvassa klor. De övermannade dvärggrävarna och drev bort dem från arbetsgroparna. Ormer skickar dig nu för att jaga de farligaste varianterna och bryta deras herravälde över ruinerna.",al={"vad scytheclaws och razormaws är","mottled scytheclaws","mottled razormaws","rovfåglar i wetlands"}},f1520877={q="Varför behöver Ormer att du jagar rovfåglarna i stället för att ta hand om dem själv?",a="Ormer och de överlevande prospektörerna har drivits upp på åsen ovanför utgrävningsplatsen. Utgrävningsteamet är splittrat eller dödat, så de har inte manskap nog att själva gå till motangrepp. De behöver dugliga äventyrare som är villiga att ge sig ner i de angripna groparna å deras vägnar.",al={"varför ormer behöver hjälp","varför ormer inte dödar rovfåglarna","varför jag åt ormer"}}},fp="15,200,19.351.0,21.347.0,39.256.0,54.188.0,23.214.0,41.196.1,62.208.0,53.217.0"}
P.entries["quest:2950"] = {n="Nogg's Ring Redo",s="I Orgrimmar arbetar Nogg med att förbättra en ring som hämtats från Gnomeregan. Han ber om sällsynta material och information om Dark Iron-dvärgar, ivrig att bevisa att goblinernas hantverk överträffar gnomernas konstruktioner.",h="I Orgrimmar arbetar Nogg med att förbättra en ring som hämtats från Gnomeregan.",kw={"brilliant gold ring","dark iron","gnomeregan","goblinteknik","moss agate","nogg","orgrimmar","silver bar"},ang={["faction:Horde"]="Som medlem av Horde kan du föra med dig teknologi från platser med anknytning till Alliance, som Gnomeregan, till Orgrimmars uppfinnare och ge Horde insyn i fiendens förmågor.",["profession:Engineering"]="Som ingenjör ser du rivaliteten mellan goblinernas uppfinningsrikedom och gnomernas manicker. Gobliner modifierar befintliga apparater hänsynslöst för att få ut så mycket som möjligt av dem.",["profession:Mining"]="Som gruvarbetare kan du hjälpa till att skaffa de värdefulla material Nogg behöver: en förädlad silverstång och en mossagat, utvunna genom gruvdrift och slipning av ädelstenar."},sec={{t="Goblinernas överlägsenhet",b="Du tar med en rengjord guldring från Gnomeregan till Noggs verkstad i Valley of Honor. Gobliningenjören kastar en blick på det anspråkslösa gnomiska hantverket och föreslår en byteshandel. Ta med råmaterial och en mindre summa, så lägger han till ett intrikat mönster av silver och mossagat runt ringen, avsett att förstärka magin i den."},{t="En dvärgisk vinkel",b="Noggs erbjudande handlar om mer än affärer. Rapporter om Dark Iron-dvärgar inne i den belägrade gnomstaden har fångat hans uppmärksamhet. För Nogg kan deras närvaro förklara hur gnomer plötsligt fått mekanisk skicklighet inom ett område som gobliner anser vara sitt eget. Din information ger dig en förbättrad ring och Noggs motvilliga respekt."}},faq={{q="Vem är Nogg?",a="Nogg är en gobliningenjör som arbetar i Orgrimmars Valley of Honor. Han samarbetar med andra uppfinnare i Drag och Valley of Honor och hanterar märkliga mekaniska artefakter och ritningar som hämtats från farliga expeditioner.",al={"vem är nogg","nogg orgrimmar","nogg npc"}},{q="Vilka material behövs för att smida om ringen?",a="Nogg ber om den ursprungliga Brilliant Gold Ring, en Silver Bar, en Moss Agate och trettio silvermynt för arbetet och verkstadskostnaderna.",al={"ringmaterial","noggs material","vad behöver nogg"}},{q="Varför är Nogg intresserad av Gnomeregan?",a="Gnomeregan har stort teknologiskt värde. Gobliner konkurrerar hårt med gnomer inom tekniska områden, och Nogg är nyfiken på rykten om att Dark Iron-dvärgar låg bakom de teknologiska avvikelserna i den fallna teknostaden.",al={"varför bryr sig nogg om gnomeregan","gobliners intresse för gnomeregan"}},{q="Vad gör Nogg egentligen med ringen?",a="Nogg bygger ett mönster av silver och mossagat runt guldringen. Stommen leder och stabiliserar förtrollningarna i ringen och gör den starkare än den ursprungliga gnomiska konstruktionen.",al={"ringens uppgraderingshistoria","vad ändras på ringen"}},{q="Var börjar den här uppdragskedjan?",a="Kedjan börjar djupt inne i Gnomeregan. Du hittar en Grime-Encrusted Ring på en Dark Iron-dvärg och rengör den med maskinen Sparklematic 5200.",al={"uppdragskedjans start","hur startar man noggs uppdrag","var börjar ringens uppdragskedja"}},{q="Varför misstänker Nogg Dark Iron-dvärgarna?",a="Gobliningenjörer misstror gnomisk innovation. Nogg misstänker att varje plötsligt språng i gnomernas mekaniska skicklighet beror på inblandning utifrån, särskilt från den listiga Dark Iron-klanen.",al={"varför dark iron-dvärgar","dark iron-dvärgarnas koppling"}}},fx={e11b7fb8={q="Varför vill Nogg smida om ringen?",a="Nogg gör inte anspråk på att äga ringen, men han är uppriktigt tacksam för informationen du kom tillbaka med om Dark Iron-dvärgarna i Gnomeregan. Som gobliningenjör kan han inte heller motstå att visa upp sitt överlägsna hantverk. Han vill bevisa att han kan överträffa gnomernas klumpiga arbete genom att förstärka deras design med ett mycket kraftfullare magiskt gallerverk.",al={"varför nogg erbjuder sig att göra om ringen","varför göra om ringen","noggs motiv för att göra om ringen"}},["63dec8fa"]={q="Vad används Silver Bar till i Nogg's Ring Redo?",a="Nogg använder silver tackan för att smida ett förfinat bärande gitter runt ringen. Denna fina metallstruktur fungerar som ett fysiskt hölje som behövs för att låsa fast ytterligare magiska förtrollningar utan att störa ringens befintliga kärna.",al={"vad används silver bar till","silver bar nogg","varför silver bar till ringredo"}},c138af81={q="Vad används Moss Agate till i Nogg's Ring Redo?",a="Moss Agate byggs in i det nya silvergitter som Nogg skapar åt din ring. Stenens inneboende mineralegenskaper hjälper till att leda och förstärka den slumrande magiska energin i föremålet och gör en enkel gnomisk prydnad till en mycket kraftfullare artefakt.",al={"vad används moss agate till","moss agate nogg","varför moss agate till ringredo"}}},fp="16,193,18.324.0,15.328.1,12.220.0,46.139.0,37.232.0,39.188.0,34.138.0,40.176.0"}
P.entries["quest:2951"] = {n="The Sparklematic 5200!",s="Djupt inne i ruinerna av Gnomeregan står Sparklematic 5200, en automatisk rengöringsmaskin som fortfarande fungerar mitt i kaoset. Lägg ett Grime-Encrusted Object från de underjordiska salarna i den och betala en symbolisk avgift, så kan äventyrare återställa bärgade prydnader, ädelstenar och skrot till skinande skick. Den är ett strålande bevis på den gnomiska ingenjörskonstens bestående uppfinningsrikedom och excentricitet.",h="Djupt inne i ruinerna av Gnomeregan står Sparklematic 5200, en automatisk rengöringsmaskin som fortfarande...",kw={"rengörare","gnom","gnomeregan","smutsbelagd","maskin","bärgning","sparklematic","sparklematic 5200","trogg"},ang={["faction:Alliance"]="För Alliansens bärgningsteam som trotsar Gnomegregans salar ger maskinen ett omedelbart sätt att rengöra bärgade reliker innan de bärs tillbaka till Ironforge.",["profession:Engineering"]="Ingenjörer kan uppskatta den robusta motorn och sorteringsarkitekturen som krävs för att rengöra och bearbeta okänt bråte utan att maskinen fastnar eller exploderar.",["race:Gnome"]="Maskinen speglar den klassiska gnomiska motståndskraften: även under en katastrofal evakuering av hemlandet fortsätter handeln och den skinande renligheten utan avbrott."},sec={{t="En fyr i smutsen",b="Mitt bland det radioaktiva nedfallet och de troggar som härjar i Gnomeregan håller en liten grupp överlevande gnomer en säker perimeter nära en enastående uppfinning: Sparklematic 5200. Den robusta apparaten är byggd för att skrubba bort den hårda underjordiska smutsen från bärgade värdesaker och lovar att få tillbaka den ”glansiga glansen”. Medan underjordiska bestar bankar på skotten står maskinen redo för kommersiell drift."},{t="Frenetisk drift",b="Rengöringsmekanismen är allt annat än varsam. När en äventyrare lägger in en smutsbelagd relik tillsammans med tre silvermynt går Sparklematic igång i ett våldsamt, malande raseri. Hela järnapparaten stönar, vibrerar och rycker från sida till sida medan den skrapar bort giftigt slam, bestrålat fett och stendamm. Några ögonblick senare stöter den ut det som låg begravt under smutsen, allt från dyrbara mineraler till mekaniska komponenter."}},faq={{q="Vad är Sparklematic 5200?",a="Sparklematic 5200 är en automatisk gnomisk rengöringsapparat som står i Gnomegregans säkra enklav. Den är konstruerad för att avlägsna envis radioaktivt fett, slam och smuts från föremål täckta av beläggningar, som återfunnits i den fallna staden.",al={"vad gör sparklematic 5200","sparklematic-maskin","rengöringsmaskin gnomeregan"}},{q="Vad behöver maskinen för att fungera?",a="För att använda Sparklematic krävs ett Grime-Encrusted Object, som hittas bland monstren och bråten i Gnomeregan, samt en avgift på tre silvermynt som läggs direkt i maskinens myntspringa.",al={"hur använder man sparklematic","sparklematic pris","vad lägger man i sparklematic"}},{q="Varför finns det en fungerande maskin mitt i en krigszon?",a="Den gnomiska civilisationen byggdes kring automatiserade lösningar som förenklar hushålls- och industrilivet. När trogginvasionen och de giftiga ventilerna ödelade staden drog sig överlevande gnomer tillbaka till befästa verkstäder, där maskiner som Sparklematic förblev intakta och strömförsörjda.",al={"varför finns sparklematic här","vem satte sparklematic i gnomeregan"}},{q="Vad kommer ut när ett smutsbelagt föremål rengjorts?",a="Maskinen lämnar tillbaka ditt bärgade föremål helt fritt från smuts och blottar användbara handelsvaror, hantverksstenar, ädelstenar eller reservdelar till ingenjörskonst som låg begravda under smutsen.",al={"vad får man från sparklematic","byte från sparklematic","belöningar från grime-encrusted object"}},{q="Kan jag använda Sparklematic 5200 mer än en gång?",a="Ja. Efter de första demonstrationskörningarna kan apparaten användas om och om igen genom fortsatta rengöringsuppdrag, så länge du tillhandahåller fler Grime-Encrusted Objects och silvermynt.",al={"kan sparklematic användas flera gånger","kan man rengöra flera smutsiga föremål","mer om sparklematic"}},{q="Varför skakar maskinen så våldsamt under rengöringen?",a="Smutsbeläggningen i Gnomeregan är tät, giftig och hårdnad. Maskinen använder kraftig omrörning i hög hastighet och invändiga skrubbare för att slita bort smutsen, vilket får hela chassit att rycka och stöna under drift.",al={"sparklematic skakar","är sparklematic trasig"}}},fx={["3b5f4e4c"]={q="Varför vill Sparklematic 5200 att det här ska göras?",a="Sparklematic 5200 är ingen kännande varelse, utan en automatiserad gnomisk apparat byggd för ett enda kommersiellt syfte: att rengöra smutsiga, ingrodda värdesaker åt betalande kunder. Som det står på mässingsskylten är den konstruerad för att skrubba rena förstörda, dyngtäckta reliker från de förorenade salarna i Gnomeregan för tre silvermynt. Den har inga egna avsikter utöver att följa sin programmering när den får rätt bränsle och mynt.",al={"varför vill sparklematic ha föremål","sparklematic 5200 syfte","varför mata sparklematic"}},["757f94ef"]={q="Vad är Grime-Encrusted Object till för?",a="Ett Grime-Encrusted Object är en oidentifierbar bit bärgad gnomisk teknologi, mineralmalm eller personlig prydnad som täckts av det giftiga slam och den strålning som flödar genom Gnomeregan. I sitt nedsmutsade skick är föremålet helt värdelöst och dess sanna natur förblir dold. När du matar in det i Sparklematic 5200 skuras det radioaktiva slammet och de frätande avlagringarna bort, så att värdefull utrustning, dyrbara ädelstenar eller metallskrot därunder kommer fram.",al={"vad är grime-encrusted object","grime-encrusted object syfte","varför spara grime-encrusted object"}}},fp="22,160,21.270.0,18.308.0,30.198.0,41.141.0,64.236.0,53.167.0,47.125.0,56.162.0"}
P.entries["quest:2952"] = {n="The Sparklematic 5200!",s="Djupt inne i Gnomeregans bestrålade salar står Sparklematic 5200, en automatisk rengöringsmaskin som skrubbar giftigt smuts från återvunnet skrot. Maskinen avlägsnar ingrodd smuts från nedsmutsade föremål och packar allt som räddas i en dekorativ presentask.",h="Djupt inne i Gnomeregans bestrålade salar står Sparklematic 5200, en automatisk rengöringsmaskin som skrubbar...",kw={"rengöring","maskin","dekontaminering","gnomeregan","smuts","sparklematic","glittraren"},ang={["profession:Engineering"]="Studier av Sparklematic ger en inblick i automatisk partikelrengöring och snabba förpackningsmekanismer konstruerade för att tåla kraftig omgivande strålning.",["race:Gnome"]="Sparklematic är en tydlig påminnelse om hemmet före fallet: till och med en industriell skurenhet måste plinga glatt och leverera slutprodukten inslagen som en födelsedagspresent."},sec={{t="Automatisk rengöring",b="Gnomisk ingenjörskonst sätter ofta effektivitet och lekfullhet lika högt. Sparklematic 5200 byggdes för att hantera giftigt och förorenat avfall och skura bort smuts och frätande rester genom automatiska cykler. När den har laddats och betalats rasslar maskinen igenom sin rengöringsrutin och ger sedan ifrån sig ett glatt pling. Därefter slår den prydligt in det som finns kvar i ett paket med rosett."},{t="Skatter i gyttjan",b="Sedan troggarnas fall av Gnomeregan och den efterföljande strålningskatastrofen har otaliga personliga tillhörigheter och tekniska rester täckts av industriell gyttja. Äventyrare som matar in smutsiga föremål i maskinen kan återfå förlorade ädelstenar, råmalm och sedan länge försvunna värdesaker som slukades när staden ventilerades."}},faq={{q="Vad gör Sparklematic 5200?",a="Sparklematic 5200 är en automatisk rengöringsmaskin inne i Gnomeregan. När du matar in ett smutsigt föremål och betalar en avgift i mynt tvättar den bort sörja, smuts och radioaktivt avfall och lämnar tillbaka det rengjorda innehållet i en liten presentask.",al={"vad är sparklematic 5200","hur sparklematic fungerar","sparklematics funktion"}},{q="Var finns Sparklematic 5200?",a="Maskinen finns i den fallna staden Gnomeregans inre korridorer, nära Clean Zone där överlevande och automatiska dekontamineringssystem en gång var i drift.",al={"sparklematics plats","var finns rengöringsmaskinen","hitta sparklematic"}},{q="Varför slår maskinen in föremål med en rosett?",a="Den programmerades med typisk gnomisk lekfullhet. Även efter att ha skrubbat bort farligt radioaktivt nedfall och giftig smuts från ett föremål utformade dess skapare slutcykeln så att det återställda föremålet packas som en trevlig present med prydlig rosett.",al={"varför presentask","sparklematic inslagen present","inslagen med rosett"}},{q="Kan Horde-äventyrare använda Sparklematic 5200?",a="Ja. Sparklematic 5200 är en helt automatisk apparat som inte bryr sig om fraktionstillhörighet. Så länge en besökare stoppar i mynt och smutsiga föremål kör maskinen sin cykel.",al={"horde sparklematic","kan horde rengöra smuts","är sparklematic neutral"}},{q="Kan jag använda Sparklematic flera gånger?",a="Ja. Efter den första körningen låser maskinen upp en återkommande uppgift som låter alla som hittar smutsiga föremål i grottan bearbeta dem om och om igen.",al={"kan sparklematic användas flera gånger","more sparklematic action","farma smutsiga föremål"}},{q="Vad händer efter det här uppdraget?",a="När du har slutfört den första rengöringen får du direkt tillgång till den återkommande rengöringscykeln More Sparklematic Action, så att du kan rengöra alla ytterligare smutsiga fynd du bär med dig.",al={"nästa uppdrag efter sparklematic","vad följer efter sparklematic 5200"}}},fx={["1a7da75f"]={q="Varför vill Sparklematic 5200 ha ingrodda föremål?",a="Sparklematic 5200 har inga personliga ambitioner – den är ett automatiserat underverk inom gnomisk ingenjörskonst, utformat för att rengöra och återställa bärgade varor. Den byggdes innan Gnomeregan föll, och dess programmerade funktion är att tvätta bort tjocka lager radioaktivt slam och skräp och förpacka det som blir kvar i ett prydligt inslaget paket åt användaren.",al={"varför vill sparklematic ha detta","sparklematic 5200 syfte","varför rengöra grime-encrusted objects"}}},fp="22,164,19.252.0,22.257.0,35.204.0,39.157.0,41.174.0,48.134.0,42.171.0,30.140.0"}
P.entries["quest:2953"] = {n="More Sparklematic Action",s="Djupt inne i Gnomeregans bestrålade ruiner står Sparklematic 5200, en automatisk rengöringsanordning som lämnades kvar när staden evakuerades. För några silvermynt skrubbar maskinen grundligt bort räddningsbara föremål från smutsen och det radioaktiva slammet som täcker den fallna huvudstaden.",h="Djupt inne i Gnomeregans bestrålade ruiner står Sparklematic 5200, en automatisk rengöringsanordning som...",kw={"automation","ren maskin","rengöring","gnomeregan","ingrodd smuts","sparklematic"},ang={["profession:Engineering"]="När du använder anordningen får du som ingenjör se robusta gnomiska lösningsmedelscykler och myntaktiverad automation på nära håll.",["race:Gnome"]="Sparklematic är ett bevis på gnomisk mekanisk uthållighet och fungerar pålitligt mitt bland de giftiga ruinerna av ditt hemland."},sec={{t="Automatisk återställning",b="Sparklematic 5200 är ett exempel på den sinnrika automatiserade infrastruktur som gnomer installerade i hela Gnomeregan före trogginvasionen och det efterföljande radioaktiva nedfallet. Trots att korridorerna är fulla av giftigt avfall och fientliga automater utför apparaten fortfarande sin exakta programmering när den får tre silvermynt och en smutsig artefakt."},{t="Underverk ur smutsen",b="När den aktiveras rycker Sparklematic våldsamt till medan den dränker och skrubbar den insatta reliken med kraftfulla gnomiska rengöringsmedel. När cykeln avslutas med en glatt klingande signal delar den ut en prydligt förpackad låda med det som räddats under frätande troggslem och giftig smuts."}},faq={{q="Vad är Sparklematic 5200?",a="Sparklematic 5200 är en automatisk gnomisk rengöringsanordning i Gnomeregan. Den avlägsnar frätande slam, smuts och radioaktivt skräp från återfunna föremål och gör dem till identifierbara fynd.",al={"sparklematic 5200","vad gör maskinen","gnomeregan rengöringsmaskin"}},{q="Varför tar maskinen betalt?",a="Sparklematic behöver tre silvermynt för att starta en rengöringscykel. Den exakta anledningen till att den tar betalt förklaras inte.",al={"varför betala silver","sparklematic pris"}},{q="Vilka slags föremål kan läggas i den?",a="Maskinen rengör särskilt smutsiga föremål och reliker som återfunnits från fallna trogger, korrumperade vaktposter och bestrålade fasor som strövar omkring i Gnomeregans tunnlar.",al={"grime-encrusted object","vilka föremål kan jag rengöra"}},{q="Är Sparklematic skyddad mot strålning?",a="De yttre tunnlarna är genomsyrade av radioaktivt avfall, men Sparklematic 5200 fungerar fortfarande och använder särskilda gnomiska rengöringsmedel för att skrubba bort farliga rester från föremål som förs in.",al={"sparklematic bestrålad","sparklematic förorening"}},{q="Kan båda fraktionerna använda Sparklematic 5200?",a="Ja. Sparklematic 5200 är en helt mekanisk och automatisk anläggning som fungerar neutralt. Den tar emot betalning och smutsiga föremål oavsett besökarens lojalitet.",al={"hord sparklematic","vem kan använda den"}},{q="Vem konstruerade Sparklematic?",a="Skaparens namn är inte känt. Sparklematic är en gnomisk rengöringsmaskin som fortfarande fungerar i Gnomeregan.",al={"sparklematics skapare","vem byggde sparklematic"}}},fx={["9d072b2b"]={q="Varför måste Sparklematic 5200 köras?",a="Sparklematic 5200 är en automatiserad gnomisk apparat med ett enda syfte: att skrubba bort tjockt underjordiskt smuts och industriella avlagringar från förorenad utrustning. Som maskin hyser den inga storslagna ambitioner eller dolda intressen; den väntar bara på rätt avgift och ingrodda föremål för att aktivera sina rengöringscykler och lämna ut återställda varor.",al={"varför köra sparklematic","sparklematics motiv","varför använda sparklematic 5200"}}},fp="24,191,21.313.0,21.282.0,30.201.0,34.103.0,40.158.0,40.180.0,44.149.0,30.100.0"}
P.entries["quest:2954"] = {n="The Stone Watcher",s="Du förde platinaskivorna ut till öknen i Tanaris, och Norgannons stenväktare har visat sig vid Uldum-piedestalen. Den vaktar ingången till Uldum-anläggningen och släpper bara in dem vars skivuppsättning innehåller Uldums plattor. Du ska ta reda på dess historia innan du går vidare.",h="Du förde platinaskivorna ut till öknen i Tanaris, och Norgannons stenväktare har visat sig vid...",kw={"skaparna","uldums plattor","platinaskivor","norgannons sten väktare","tanaris","uldaman","uldum","uldum-piedestalen"},sec={{t="En väktare vid piedestalen",b="Väktarens ankomst är precis den reaktion man hoppades på när du skickades ut i öknen i Tanaris med platinaskivorna. Den kallar sig en väktare av ingången och släpper inte in dig i Uldum-anläggningen om inte Uldums plattor redan har fogats samman med din skivuppsättning. Innan du går vidare ska du ta reda på historien bakom sten väktaren och sedan använda Uldum-piedestalen."},{t="Vad väktaren berättar",b="Sten väktaren ska på Skaparnas vägnar kontrollera vilka som får beträda Uldum-komplexet, och släpper bara in dem som visar upp rätt sekvensskivor. Uldums plattor är skivor som Skaparna tillverkat för att lagra data om deras verksamhet i Uldum. De är nästan lika stora som dina egna skivor, men märkningarna gäller Uldum i stället för Uldaman. Uldum är en forskningsanläggning där Skaparna arbetar med att förbättra Azeroths biosfär, och detaljer om deras arbete är tillgängliga för dem som har plattorna. Till sist lovar väktaren att dina skivor återlämnas när du har använt piedestalen, och att du får gå in i komplexet när plattorna ingår i din uppsättning."},{t="Mer från väktaren",b="Sten väktaren tillägger att Skaparna styr distributionen av dessa skivor till alla komplex i den här världen, och att Azeroth har planerats om för ett besök. Skaparna använder besök för att återupprätta kontrollen över sådda världar när krafter utifrån eller inifrån rubbar balansen i världarnas matrisdynamik, och det ska tas på allvar."}},faq={{q="Vem är Norgannons sten väktare?",a="En ingångsväktare vid Uldum-piedestalen ute i öknen i Tanaris, som avgör vilka som får komma in i Uldum-anläggningen.",al={"vad är sten väktaren","vem är väktaren vid uldum","sten väktarens identitet"}},{q="Varför nekar sten väktaren tillträde?",a="Man får bara komma in om Uldums plattor redan ingår i ens skivuppsättning, och dina innehåller dem ännu inte.",al={"varför kan jag inte gå in i uldum","uldums plattor saknas","nekas tillträde till uldum"}}},fp="17,277,26.403.0,25.672.1,21.369.2,38.128.0,38.119.0"}
P.entries["quest:296"] = {n="Ormer's Revenge",s="Ormer's Revenge är kulmen på Ormer Ironbraids kamp för att hämnas de dvärgiska utgrävare som slaktades vid Whelgar Excavation Site. Övertygad om att ett listigt best kallat Sarltooth ledde det brutala raptoranfallet skickar Ormer en äventyrare för att döda flockens ledare och ta dess klo som bevis.",h="Ormer's Revenge är kulmen på Ormer Ironbraids kamp för att hämnas de dvärgiska utgrävare som slaktades vid...",kw={"explorer's league","ormer ironbraid","raptorer","sarltooth","klo","wetlands","whelgar excavation site"},ang={["class:Hunter"]="Sarltooth är ett av The Wetlands främsta rovdjur. För att ta sig uppför höjden och fälla flockens ledare krävs god förmåga att spåra.",["faction:Alliance"]="Att säkra de dvärgiska expeditionerna i träskmarkerna hjälper Alliansens fästen mellan Ironforge och de norra länderna att stå kvar.",["race:Dwarf"]="För dvärgarna handlar hämnden för den slaktade Explorer's League-besättningen vid Whelgar Excavation Site om att hedra King Magni Bronzebeards fallna undersåtar."},sec={{t="Ett anfall mot flockens ledare",b="Efter slakten av Explorer's League-grävarna vid Whelgar Excavation Site betraktade Ormer Ironbraid de talrika raptorerna från sin höjd och lade märke till ett best som var större än de andra. Den ovanligt stora och våldsamma raptorn, som kallades Sarltooth, satt ovanför utgrävningen och styrde eller ledde flocken som drev bort dvärgarna. För Ormer var besten inte bara ett vilt djur, utan den som låg bakom anfallet mot King Magni Bronzebeards undersåtar."},{t="Rättvisa i våtmarkerna",b="Ormer kräver dödsstraff för massakern och instruerar äventyrare att klättra uppför de höga stigarna längs utgrävningsväggarna och göra slut på Sarltooth. Genom att hämta en av bestens mäktiga klor hämnas de fallna arbetarna, och ett hårt budskap sprids över träskmarkerna: attacker mot dvärgiska expeditioner kommer inte att lämnas obesvarade."}},faq={{q="Vem är Sarltooth?",a="Sarltooth är en stor, hotfull raptor som leder flocken vid Whelgar Excavation Site i The Wetlands. Ormer Ironbraid tror att han ledde anfallet där de dvärgiska grävarna massakrerades.",al={"vad är sarltooth","vem är raptorernas boss","sarltooths historia"}},{q="Var finns Sarltooth?",a="Sarltooth stryker längs en upphöjd stig som löper uppför den västra väggen i nordvästra hörnet av Whelgar Excavation Site.",al={"hitta sarltooth","var dyker sarltooth upp","sarltooths stig"}},{q="Varför vill Ormer döda Sarltooth i stället för att bara driva bort honom?",a="Ormer ser raptoranfallet som ett direkt brott mot King Magnis undersåtar. Eftersom oskyldiga dvärgar miste livet medan de utförde sitt arbete anser Ormer att endast döden kan hedra minnet av de fallna.",al={"ormers skäl för hämnden","varför döda sarltooth"}},{q="Vilka bevis kräver Ormer?",a="Ormer kräver en av Sarltooths klor som bekräftelse på att det väldiga rovdjuret verkligen har dödats.",al={"bevis på sarltooths död","sarltooths klo"}},{q="Vilka föll offer vid utgrävningsplatsen?",a="Dvärgiska arkeologer och arbetare som Explorer's League skickat för att gräva fram titanartefakter överrumplades och slaktades när raptorflockar vällde in över utgrävningen.",al={"vem dog vid whelgar","offren vid utgrävningsplatsen"}},{q="Är utgrävningsplatsen säker om Sarltooth dödas?",a="När Sarltooth dödas försvinner flockens farligaste hot och de fallna får sin hämnd, men raptorer kryllar fortfarande i schakten. Platsen är fortfarande farlig och till stor del övergiven.",al={"är whelgar säkert nu","vann ormer"}}},fp="15,246,27.406.0,23.296.0,17.190.0,27.109.0,68.194.0,30.90.0,44.193.0,50.181.0"}
P.entries["quest:2962"] = {n="The Only Cure is More Green Glow",s="Efter tidigare resultatlösa tester på troggar vid ytan ber Ozzie Togglevolt äventyrare att hämta ren, högpotent radioaktivt nedfall direkt inifrån Gnomeregan. Hans yttersta mål är att förstå den giftiga strålning som ödelade hans folk och skapa ett botemedel åt de drabbade spetälska gnomerna.",h="Efter tidigare resultatlösa tester på troggar vid ytan ber Ozzie Togglevolt äventyrare att hämta ren...",kw={"gnogaine","gnomeregan","hall of gears","kharanos","spetälsk gnom","ozzie togglevolt","strålning","radioaktivt nedfall"},ang={["faction:Alliance"]="För att stabilisera Dun Morogh och återta Gnomeregan måste man förstå de dödliga faror som fortfarande förgiftar tröskeln till Ironforge.",["profession:Engineering"]="Den flyktiga strålningen kräver kraftig blyavskärmning och precisa instrument, vilket visar de katastrofala följderna av bristande ingenjörskonst.",["race:Gnome"]="Varje gnom bär på sorgen över sitt förlorade hem. När man hjälper Ozzie att undersöka om den fruktansvärda mutationen går att häva berör man själva kärnan i deras hopp om att rädda sina fallna fränder."},sec={{t="Ett rent prov",b="Ozzie Togglevolts preliminära tester utanför staden misslyckades. De bestrålade troggarna som strövade omkring i Dun Morogh bar på för lite och för orena rester, så hans laboratorium i Kharanos hade fler frågor än svar. För att ta fram ett verkligt botemedel åt spetälska gnomer drar Togglevolt slutsatsen att vetenskaplig noggrannhet kräver ett färskt, koncentrerat prov direkt från stadens giftiga inre."},{t="Direkt från källan",b="För att få nedfall med tillräcklig styrka måste man våga sig in i själva Gnomeregan. De nedre djupen kring Hall of Gears och Clean Zone vimlar av bestrålade fasor, lurpassare och slemvarelser som skapades när radioaktivt avfall släpptes ut i en katastrof. Att samla upp detta instabila slem i en tung blyampull är farligt: nedfallet bryts snabbt ner, vilket gör det extremt flyktigt och brådskande att förvara."}},faq={{q="Varför behöver Ozzie radioaktivt nedfall?",a="Ozzie Togglevolt försöker framställa ett botemedel åt de spetälska gnomerna, vars sinnen och kroppar förstördes av nedfallet som släpptes ut när Gnomeregan föll. Han tror att förståelse för det outspädda giftet är första steget mot att vända dess fruktansvärda effekter.",al={"ozzie togglevolt botemedel","varför hämta grön glöd","botemedel åt spetälska gnomer"}},{q="Var hittar spelaren nedfallet?",a="Nedfallet måste samlas in från levande, bestrålade fasor, lurpassare och slemvarelser som finns i Gnomeregans djup, särskilt på de nedre våningarna kring Hall of Gears och bortom Clean Zone.",al={"var finns high potency radioactive fallout","nedfallets plats gnomeregan"}},{q="Varför avvisades proverna från troggarna vid ytan?",a="Troggarna som strövade omkring utanför Gnomeregan bar inte på tillräckligt koncentrerad smitta. Deras prover var för svaga och orena för att fungera som tillförlitligt forskningsmaterial i Ozzies botemedelsförsök.",al={"varför inte troggar","vad var fel med gnogaine"}},{q="Varför har nedfallet en tidsgräns?",a="Nedfallet är mycket instabilt och aktivt. Även i en blyampull bryts den flyktiga strålningen snabbt ner, så forskarna måste föra tillbaka den till laboratoriet i Kharanos innan den förlorar sin styrka.",al={"varför förlorar nedfallet sin styrka","nedfallets varaktighet"}},{q="Vilka är de spetälska gnomer som Ozzie hoppas kunna hjälpa?",a="Spetälska gnomer är tidigare invånare i Gnomeregan som blev instängda när strålningsventilerna öppnades för att bekämpa troggarna. I stället för att dö muterade de och blev sjuka, förvirrade överlevare som är fientliga mot sina tidigare fränder.",al={"spetälska gnomer bakgrund","vad är spetälska gnomer"}},{q="Vem ger uppdraget?",a="Uppdraget ges av Ozzie Togglevolt, en gnomforskare med bas i Kharanos i Dun Morogh, som arbetar för att gottgöra följderna av katastrofen i Gnomeregan.",al={"vem ger uppdraget","ozzie togglevolts plats"}}},fx={a4e93100={q="Vad används High Potency Radioactive Fallout till?",a="Ozzie Togglevolt behöver den koncentrerade strålningen för att studera den intensiva radioaktivitet som uppslukade Gnomeregan. Hans yttersta mål är att hitta ett botemedel för de spetälska gnomerna, hans förvandlade bröder och systrar vars sinnen och kroppar förvrängdes av katastrofen. Tidigare prover från ytan, som samlats in från kringströvande troggs, var för svaga och förorenade för att ge användbara vetenskapliga resultat, så han behöver kraftig, outspädd strålning direkt från varelserna i den förstörda staden.",al={"vad är radioaktivt nedfall till för","användning av high potency fallout","ozzies syfte med nedfallet"}},["089f8395"]={q="Vilka varelser jagar du inne i Gnomeregan?",a="Du skickas för att samla prover från de bestrålade slemmen, lurkarna och fasorna som frodas i Gnomeregan. Dessa usla slemvarelser och muterade varelser uppstod direkt efter det giftiga nedfall som frigjordes när staden föll och absorberade enorma mängder rått radioaktivt avfall. Eftersom de förkroppsligar strålningen i dess renaste och mest aktiva form ger rester som utvinns direkt ur dem den outspädda kraft Ozzie behöver för sin forskning.",al={"vad är bestrålade slem","vilka ska jag döda för nedfallet","gnomeregans nedfallsdjur"}}},fp="32,311,13.392.0,21.398.0,40.263.0,39.202.0,44.196.0,35.217.0,45.219.0,22.174.0"}
P.entries["quest:2969"] = {n="Freedom for All Creatures",s="Grimtotem-klanen fångar älvdrakar, och Kindal Moonweaver och Jer'kai vet inte varför. Kindal ber dig ta med starka vänner, öppna inhägnaden i Grimtotem-lägret med en nyckel och se till att älvdrakarna kommer levande därifrån. Kindal följer med dig; Jer'kai stannar kvar.",h="Grimtotem-klanen fångar älvdrakar, och Kindal Moonweaver och Jer'kai vet inte varför.",kw={"bambubur","elune","älvdrake","feralas","grimtotem compound","jer'kai","kindal moonweaver","sprite darter"},sec={{t="Drakar i inhägnaden",b="Kindal Moonweaver kallar Grimtotem-klanen smutsig för att den tar älvdrakar och säger att varken Kindal eller Jer'kai kan gissa vad de planerar, bara att de är ute efter något ont. De två är inte starka nog att slå sig in i lägret, så Kindal vänder sig till dig. Bamboo Cage Key öppnar inhägnaden, och Kindal vill att älvdrakarna ska fly med livet i behåll. Starka vänner vid din sida är välkomna."},{t="Kindals utkikspost",b="Kindal finns på avsatsen bakom Grimtotem Compound, ovanför vattnet. Dit kommer du via en stig uppför klippväggen. Kindal strider vid din sida genom lägret, medan Jer'kai stannar kvar."},{t="Efteråt",b="När älvdrakarna är fria tackar Kindal Elune. Faran är inte över: de frigivna drakarna kommer inte nödvändigtvis att förbli fria, så Kindal och Jer'kai tänker ta striden till Grimtotem. Kindal skickar dig för att tala med Jer'kai."}},faq={{q="Vem fångar älvdrakarna?",a="Grimtotem-klanen, enligt Kindal Moonweaver. Kindal och Jer'kai kan inte säga vad de vill med drakarna.",al={"vem fångade älvdrakarna","vem har älvdrakarna","grimtotems burar"}},{q="Var finns Kindal Moonweaver?",a="På en avsats bakom Grimtotem Compound, ovanför vattnet. En stig bakom ett träd klättrar uppför klippväggen. Gå till vänster om anläggningen för att hitta den.",al={"var finns kindal","kindal moonweaver plats","hur hittar man kindal moonweaver"}},{q="Följer Jer'kai med?",a="Nej. Jer'kai stannar kvar, medan Kindal följer med dig.",al={"hjälper jerkai","jerkais medverkan"}},{q="Vad behöver jag för att befria älvdrakarna?",a="Bamboo Cage Key, som Kindal ger dig, öppnar inhägnaden i Grimtotem-lägret. Kindal vill att du tar med starka vänner.",al={"bamboo cage key","hur befriar man älvdrakarna"}},{q="Vad följer efter det här uppdraget?",a="Doling Justice är nästa steg i kedjan.",al={"nästa uppdrag efter freedom for all creatures","vad händer efter att älvdrakarna räddats"}}},fp="25,273,18.402.0,16.184.0,9.231.1,36.115.0,27.141.0,24.53.0,42.123.0,24.45.0"}
P.entries["quest:297"] = {n="Gathering Idols",s="Gathering Idols är ett uppdrag från Magmar Fellhew om att hämta mystiska, uthuggna stenreliker från en utgrävningsplats som tagits över. De nyupptäckta avgudarna påverkar de lokala troggarna på ett märkligt sätt och driver dem till våldsamt raseri.",h="Gathering Idols är ett uppdrag från Magmar Fellhew om att hämta mystiska, uthuggna stenreliker från en...",kw={"ursinnig","uthuggna stenavgudar","utgrävning","gathering idols","magmar fellhew","ruiner","troggar"},ang={["faction:Alliance"]="Alliansens äventyrare hjälper dvärgexpeditioner att säkra farliga reliker innan vilda troggar ställer till med ännu mer kaos.",["race:Dwarf"]="Dvärgiska utgrävare tvingas återta uråldriga artefakter från trogginfekterade ruiner för att avslöja deras historiska hemligheter."},sec={{t="De nyupptäckta relikerna",b="Strax innan vilda troggar dök upp och tog över utgrävningsplatsen fann forskare ett stort förråd av märkliga, uthuggna stenavgudar. Den oväntade troggattacken tvingade expeditionen att fly från ruinerna innan någon ordentlig undersökning kunde börja. Nu håller de vilda varelserna de uråldriga relikerna i sina klor, strövar runt på platsen och hindrar alla fredliga återkomster."},{t="Ett vilt raseri",b="Troggarna verkar vara djupt påverkade av relikerna, inte bara stjäla dem. De märkliga ristningarna utövar en oroande kraft som driver varelserna till okontrollerat, ursinnigt raseri. För att förstå vad dessa artefakter egentligen är och stilla det våldsamma raseri som gripit området vill Magmar Fellhew ta avgudarna från troggarna och undersöka dem på säker plats."}},faq={{q="Vem är Magmar Fellhew?",a="Magmar Fellhew är en utgrävare som vill återta uthuggna stenavgudar som nyligen hittats på en utgrävningsplats innan troggar tog över området.",al={"vem är magmar fellhew","uppdragsgivare","magmar"}},{q="Vad är de uthuggna stenavgudarna?",a="De är mystiska, uthuggna stenreliker som hittats på en utgrävningsplats. De har en oroande kraft som driver troggar i närheten till ursinnigt raseri.",al={"vad är uthuggna stenavgudar","märkliga avgudar","utgrävda avgudar"}},{q="Varför blir troggarna ursinniga av avgudarna?",a="Avgudarna utövar ett märkligt, oförklarligt inflytande över troggarna, väcker ett vilt raseri och gör dem helt ursinniga när de har avgudarna i sin ägo.",al={"varför blir troggar ursinniga","avgudar gör troggar galna","troggarnas raseri"}},{q="Varför vill Magmar Fellhew att avgudarna samlas in?",a="Magmar Fellhew vill att avgudarna hämtas i säkerhet så att han kan undersöka deras ursprung och egenskaper, och ta bort dessa oberäkneliga artefakter från troggarnas klor.",al={"varför hämta avgudarna","syftet med att samla in avgudar","magmars undersökning"}},{q="Vad hände vid utgrävningsplatsen?",a="Troggar dök plötsligt upp inifrån utgrävningsplatsen strax efter att avgudarna upptäckts och drev bort utgrävarna från ruinerna.",al={"vem dök upp på platsen","trogginvasion","övertagen utgrävning"}},{q="Var finns avgudarna?",a="Troggarna som hemsöker utgrävningsplatsen bär på de uthuggna stenavgudarna, där relikerna ursprungligen hittades.",al={"var hittar man avgudar","vem har avgudarna","plats för uthuggna stenavgudar"}}},fp="15,126,20.301.0,15.306.0,22.108.0,32.144.0,44.124.0,49.142.0,37.132.0,26.97.0"}
P.entries["quest:2970"] = {n="Doling Justice",s="När Sprite Darter-fjärilarna har befriats tänker Jer'kai Moonweaver och Kindal föra kampen till Grimtotem-klanen. Jer'kai ber dig döda Grimtotem Naturalists, Raiders och Shamans och sedan återvända till Jer'kai. Detta följer efter Freedom for All Creatures.",h="När Sprite Darter-fjärilarna har befriats tänker Jer'kai Moonweaver och Kindal föra kampen till...",kw={"doling justice","feralas","grimtotem","jer'kai moonweaver","kindal moonweaver","naturalist","raider","shaman"},sec={{t="Kampen mot Grimtotem",b="Efter Freedom for All Creatures berättar Jer'kai Moonweaver att Kindal och Jer'kai nu ska slå tillbaka mot Grimtotem. Tillsammans kan de minska antalet taurer utan större risk för sig själva, men de tar gärna emot din hjälp. Du har sett lägret nedanför, och det finns fler i öster. Använd din egen taktik mot Grimtotem Naturalists, Raiders och Shamans, och återvänd sedan dit Jer'kai väntar."}},faq={{q="Vem ger uppdraget Doling Justice?",a="Jer'kai Moonweaver i Feralas, efter att Kindal har berättat vad de två tänker göra efter räddningen av Sprite Darter-fjärilarna.",al={"vem ger doling justice","uppdragsgivare doling justice","jer'kai moonweaver"}},{q="Vilka Grimtotem är måltavlor?",a="Grimtotem Naturalists, Grimtotem Raiders och Grimtotem Shamans bland taurerna i Grimtotem-klanen.",al={"vilka fiender ska jag döda","måltavlor för doling justice","grimtotem att döda"}},{q="Var finns Grimtotem-lägren?",a="Ett läger syns nedanför Jer'kai, och Jer'kai säger att det finns fler i öster.",al={"var finns grimtotem","grimtotem-lägrets plats","vart ska jag gå"}},{q="Vad kommer före Doling Justice?",a="Freedom for All Creatures, där du befriade Sprite Darter-fjärilarna från Grimtotem-lägret.",al={"föregående uppdrag","förkunskapskrav för doling justice","föregående steg"}}},fp="14,243,33.408.0,25.109.0,29.103.0,30.82.0,33.89.0"}
P.entries["quest:2972"] = {n="Doling Justice",s="Ute i vildmarken har Jer'kai Moonweaver och Kindal inte mycket att ge som tack, så Jer'kai räcker dig en signetring. Du ska ta den till översteprästinnan Tyrande Whisperwind vid Temple of the Moon i Darnassus. Den visar henne att de båda mår bra och styrker din berättelse. Detta följer på Doling Justice.",h="Ute i vildmarken har Jer'kai Moonweaver och Kindal inte mycket att ge som tack, så Jer'kai räcker dig en...",kw={"darnassus","feralas","jer'kai moonweaver","kindal moonweaver","signetring","teldrassil","temple of the moon","tyrande whisperwind"},sec={{t="En ring till översteprästinnan",b="Jer'kai Moonweaver och Kindal har inte mycket att erbjuda ute i Feralas vildmark, men de vill inte att du ska känna dig ouppskattad. Jer'kai räcker över en signetring och visar vägen till Darnassus, där översteprästinnan Tyrande Whisperwind väntar vid Temple of the Moon. Ringen visar henne att de båda mår bra och styrker berättelsen du ska framföra."},{t="Tyrandes svar",b="Tyrande är glad att du hjälpte drakfolket och en av hennes egna prästinnor, och säger att Jer'kai gjorde rätt i att skicka dig. Hon lovar att ringen ska återlämnas till Jer'kai. Spejare ska snart bege sig mot Feralas, och ringen blir ytterligare en sak för dem att undersöka."}},faq={{q="Vem ger dig signetringen?",a="Jer'kai Moonweaver i Feralas, som tack från Jer'kai och Kindal.",al={"vem startar uppdraget","uppdragsgivare"}},{q="Vart ska signetringen?",a="Till översteprästinnan Tyrande Whisperwind, som finns vid Temple of the Moon i Darnassus.",al={"var lämnar jag ringen","inlämningsplats","vem får jerkai moonweavers signetring"}},{q="Varför ger Jer'kai dig ringen?",a="Jer'kai och Kindal har inte mycket att ge i vildmarken. Ringen visar Tyrande att de mår bra och styrker din berättelse.",al={"signetringens syfte","varför jerkai signetring"}},{q="Vad följer härnäst i kedjan?",a="Kedjan fortsätter med An Orphan Looking For a Home.",al={"nästa uppdrag","vart går jag härnäst"}}},fp="14,331,29.351.0,16.273.1,26.66.0,30.84.0,35.131.0,29.52.0"}
P.entries["quest:2973"] = {n="A New Cloak's Sheen",s="Krueg Skullsplitter har kommit till Feralas med följeslagare, utsända av sina herrar i Orgrimmar. Krueg planerar en mantel åt livspartnern Korrin och ber dig om tio skimrande Sprite Darter Wings.",h="Krueg Skullsplitter har kommit till Feralas med följeslagare, utsända av sina herrar i Orgrimmar.",kw={"camp mojache","mantel","älvdrake","feralas","skimrande vingar","korrin","krueg skullsplitter","sprite darter"},sec={{t="En mantel åt Korrin",b="Krueg och följeslagarna kom till Feralas, utsända av sina herrar i Orgrimmar. Kruegs livspartner Korrin älskar nya kläder, så Krueg planerar en mantel prydd med älvdrakarnas skira vingar. Sprite darters med de vackra vingar Krueg vill ha lever väster om Camp Mojache, och Krueg ber dig om tio skimrande Sprite Darter Wings."},{t="Kruegs varning",b="Krueg varnar för att provocerade sprite darters är farliga. Krueg säger att du bör vara ännu försiktigare med nattalverna i närheten, som också brukar hålla till i skogarna."}},faq={{q="Vem är Krueg Skullsplitter?",a="Krueg Skullsplitter finns i Camp Mojache. Krueg kom till Feralas med följeslagare, utsända av sina herrar i Orgrimmar.",al={"vem är krueg","krueg skullsplitter historia","krueg i feralas"}},{q="Varför vill Krueg ha sprite darter-vingar?",a="Krueg planerar en mantel prydd med älvdrakvingar åt livspartnern Korrin, som älskar nya kläder.",al={"varför behövs darter-vingar","vad sprite darter-vingar används till","vad tillverkar krueg"}},{q="Var finns sprite darters?",a="Väster om Camp Mojache.",al={"var hittar man sprite darters","sprite darter-plats","var finns älvdrakar i feralas"}},{q="Vilka faror varnar Krueg för?",a="Krueg säger att provocerade sprite darters är farliga och att nattalverna i närheten, som också brukar hålla till i skogarna, kräver ännu större försiktighet.",al={"kruegs varningar","hot i skogen i feralas"}}},fp="19,191,18.338.0,15.156.0,27.119.0,40.98.0,37.21.0,35.140.0"}
P.entries["quest:2974"] = {n="A Grim Discovery",s="Krueg Skullsplitter i Camp Mojache blir förvånad när han får höra att du mött tauren i Feralas, och ännu mer när han får veta att de tillhör Grimtotem. Belgrom, en av Kruegs överordnade, har satt en belöning på deras huvuden. Krueg vill att du återvänder och tar med dig tjugo Grimtotem-horn.",h="Krueg Skullsplitter i Camp Mojache blir förvånad när han får höra att du mött tauren i Feralas, och ännu mer...",kw={"belgrom","camp mojache","feralas","grimtotem","horn","krueg skullsplitter"},sec={{t="Ryktet om Grimtotem",b="Du berättar för Krueg Skullsplitter om tauren du stötte på i området, och Krueg säger genast att de tillhör klanen Grimtotem. Belgrom, en av Kruegs överordnade, är mycket intresserad av deras sort och har satt en belöning på deras huvuden. Krueg säger att Grimtotem inte får underskattas och att de är onda. Du återvänder, dödar dem och tar med tjugo horn till Camp Mojache, så att det första slaget faller innan de hinner ödelägga byar eller lägga beslag på mark."},{t="Hornen överlämnade",b="Krueg bedömer hornen som goda och säger att du nu har hjälpt till två gånger. Belgrom får höra om det så snart Krueg är tillbaka i Orgrimmar."}},faq={{q="Vem ger uppdraget A Grim Discovery?",a="Krueg Skullsplitter i Camp Mojache, efter att du berättat för Krueg att du mött tauren i området.",al={"vem ger grim discovery","krueg skullsplitter-uppdrag","uppdragsgivare grim discovery"}},{q="Varför vill Krueg ha Grimtotem-horn?",a="Krueg kallar klanen Grimtotem ond och vill slå till mot dem innan de hinner ödelägga byar eller lägga beslag på mark. Belgrom, en av de överordnade i Orgrimmar, har också satt en belöning på dem.",al={"varför döda grimtotem","grimtotem-hot i feralas","varför grimtotem-horn"}},{q="Vem är Belgrom?",a="Krueg säger att Belgrom är en av de överordnade, som är intresserad av Grimtotem och har satt en belöning på dem.",al={"belgrom orgrimmar","vem är belgrom"}},{q="Hur många horn vill Krueg ha?",a="Tjugo Grimtotem-horn, som du tar med till Krueg i Camp Mojache. Krueg tar gärna emot hela högar om du kan ordna det.",al={"antal grimtotem-horn","hur många grimtotem-horn"}},{q="Vad följer efter A Grim Discovery?",a="Uppdragskedjan fortsätter med A Grim Discovery (2).",al={"nästa uppdrag grim discovery","grim discovery-uppdragskedja"}}},fp="16,261,21.438.0,19.126.1,27.90.0,36.176.0,15.106.0,31.107.0,30.44.0"}
P.entries["quest:2975"] = {n="The Ogres of Feralas",s="Rok Orhan i Camp Mojache vill driva tillbaka Gordunni-ogrerna innan de sprider sig längre in i Feralas. Följ floden norrut till deras utpost, där antalet ogres, ogre-magi och brutes ska minskas.",h="Rok Orhan i Camp Mojache vill driva tillbaka Gordunni-ogrerna innan de sprider sig längre in i Feralas.",kw={"brute","camp mojache","feralas","gordunni","ogre","ogre-mage","rok orhan"},sec={{t="Gordunnis märke",b="Rok Orhan påpekar att Gordunni-stammen av ogres är svår att missa här, eftersom deras blotta närvaro sätter ärr i landet. De måste drivas tillbaka innan de når längre in i Feralas. Deras utpost ligger längs floden norrut. Där fäller du tio Gordunni Ogres, tio Gordunni Ogre-Magi och fem Gordunni Brutes för att visa stammen att de inte är välkomna."}},faq={{q="Vem vill driva tillbaka Gordunni-ogrerna?",a="Rok Orhan i Camp Mojache.",al={"vem ger uppdraget","uppdragsgivare","rok orhan"}},{q="Varför vill Rok Orhan driva tillbaka Gordunni?",a="Rok Orhan säger att deras blotta närvaro sätter ärr i landet och att de måste stoppas innan de sprider sig längre in i Feralas.",al={"varför döda ogres","gordunnis motiv","varför slåss mot gordunni"}},{q="Var ligger Gordunni-utposten?",a="Följ floden norrut, säger Rok Orhan, så hittar du utposten där.",al={"ogre-utpostens plats","var finns ogres","gordunnis plats i feralas"}},{q="Vilka Gordunni ska dödas?",a="Tio Gordunni Ogres, tio Gordunni Ogre-Magi och fem Gordunni Brutes.",al={"hur många ogres","antal gordunni att döda"}},{q="Vad följer efter det här uppdraget?",a="Kedjan fortsätter med The Ogres of Feralas (2).",al={"nästa uppdrag ogres of feralas","ogres of feralas-uppdragskedja"}}},fp="20,210,24.356.0,41.26.0,49.116.0,30.76.0,29.68.0,24.48.0"}
P.entries["quest:2976"] = {n="A Grim Discovery",s="Krueg Skullsplitter medger att han nämnde en belöning och säger att den som utförde arbetet förtjänar den största delen. Hornen läggs i en låda som du får bära till Belgrom Rockmaul i Valley of Honor i Orgrimmar, som vill höra din berättelse. Detta följer på den första A Grim Discovery.",h="Krueg Skullsplitter medger att han nämnde en belöning och säger att den som utförde arbetet förtjänar den...",kw={"belgrom rockmaul","belöning","feralas","grimtotem","horn","krueg skullsplitter","orgrimmar","valley of honor"},sec={{t="Lådan med horn",b="Efter den första A Grim Discovery blir Krueg Skullsplitter förvånad, men medger sedan att han nämnde en belöning. Du utförde arbetet, så Krueg tycker att det inte är mer än rätt att du får den största delen. Hornen packas i en låda åt dig. Lådan ska till Belgrom Rockmaul i Valley of Honor, som vill höra vad du såg och kommer att se till att ditt hårda arbete lönar sig."},{t="Belgroms intresse",b="Belgrom Rockmaul blir slagen av nyheten om Grimtotem och frågar om du verkligen träffade dem under en jakt i Feralas. Belgroms gelikar vill höra berättelsen, så du ombeds berätta mer medan mynten räknas upp. Belgrom avslutar med att tacka för informationen."}},faq={{q="Vem ger dig den här delen av A Grim Discovery?",a="Krueg Skullsplitter, som låter lägga hornen i en låda åt dig.",al={"vem ger a grim discovery","krueg skullsplitter uppdrag","uppdragsgivare a grim discovery 2"}},{q="Vart ska lådan med Grimtotem-horn?",a="Till Belgrom Rockmaul, som väntar i Valley of Honor i Orgrimmar.",al={"var ska jag ta hornen","belgrom rockmaul plats","lämna in grim discovery 2"}},{q="Varför får du belöningen?",a="Krueg säger att du utförde arbetet, så det är rätt att du får den största delen av belöningen.",al={"varför grimtotem-horn","belöning grim discovery"}},{q="Vad vill Belgrom ha av dig?",a="Krueg säger att Belgrom gärna vill höra vad du såg och kommer att se till att ditt hårda arbete lönar sig.",al={"belgrom rockmaul grimtotem","varför bry sig om grimtotem i feralas"}},{q="Vad kommer före det här steget?",a="Den första A Grim Discovery, där du gav Krueg Grimtotem-horn.",al={"grim discovery-uppdragskedja","förutsättning för grim discovery 2","tidigare uppdrag"}}},fp="16,302,18.370.0,18.257.1,40.62.0,43.67.0,24.79.0,32.93.0,28.71.0"}
P.entries["quest:2978"] = {n="The Gordunni Scroll",s="En smutsig skriftrulle ligger i Gordunni Outpost, och när du plockar upp den ser du vad som verkar vara ett möte eller en ceremoni. Rok Orhan i Camp Mojache skulle vara intresserad av den och av vad den kan betyda för Gordunni.",h="En smutsig skriftrulle ligger i Gordunni Outpost, och när du plockar upp den ser du vad som verkar vara ett...",kw={"camp mojache","ceremoni","feralas","gordunni outpost","gordunni scroll","ogrer","rok orhan"},sec={{t="Den smutsiga skriftrullen",b="När du tar upp den smutsiga skriftrullen ser du att den tycks föreställa någon sorts samling eller ceremoni. Du tror att Rok Orhan i Camp Mojache skulle vilja se den och få veta vad den kan betyda för Gordunni."}},faq={{q="Vad föreställer Gordunni Scroll?",a="Den verkar föreställa någon sorts möte eller ceremoni.",al={"vad föreställer skriftrullen","innehållet i gordunni scroll","teckning på skriftrullen"}},{q="Vem vill ha Gordunni Scroll?",a="Rok Orhan i Camp Mojache.",al={"vem vill ha skriftrullen","var ska jag lämna skriftrullen","lämna in gordunni scroll"}},{q="Var hittar man Gordunni Scroll?",a="I Gordunni Outpost, där du kan plocka upp den.",al={"var finns gordunni scroll","gordunni scroll plats"}},{q="Vad följer efter Gordunni Scroll?",a="Uppdragskedjan fortsätter med Dark Ceremony.",al={"vad är nästa uppdrag","efter gordunni scroll","gordunni scroll uppdragskedja"}}},fp="19,206,17.210.0,35.50.0,30.27.0,35.50.0,33.37.0"}
P.entries["quest:2979"] = {n="Dark Ceremony",s="Efter Gordunni Scroll läser Rok Orhan på Camp Mojache den som planer på en mörk ceremoni ledd av Gordunni-häxmästarna. Rok Orhan vill att du tar en klot från en av dem för att få veta mer om ceremonin och Gordunnis magi.",h="Efter Gordunni Scroll läser Rok Orhan på Camp Mojache den som planer på en mörk ceremoni ledd av...",kw={"camp mojache","mörk ceremoni","feralas","gordunni","gordunni orb","häxmästare","rok orhan"},sec={{t="Planer på en mörk ceremoni",b="Rok Orhan har granskat Gordunni Scroll som du tog med dig och tolkar den som planerna för en mörk ceremoni. Såvitt Rok kan se är det Gordunni-häxmästarna som utför den. En häxmästare måste hittas och ett klot tas från honom. En magikers klot rymmer stor kraft och bör avslöja mer om ceremonin och magin som Gordunni brukar."},{t="När klotet överlämnas",b="När klotet väl är i din hand säger Rok Orhan att det kommer att berätta mer om Gordunni, och att kunskapen ska användas för att planera deras fall."}},faq={{q="Vem ger uppdraget Mörk ceremoni?",a="Rok Orhan på Camp Mojache, efter att du tagit med Gordunni Scroll.",al={"vem ger uppdraget mörk ceremoni","uppdragsgivare för mörk ceremoni"}},{q="Vem utför den mörka ceremonin?",a="Rok Orhan tyder av planerna att Gordunni-häxmästarna utför den.",al={"vem utför den mörka ceremonin","ledare för gordunniritualen"}},{q="Vilket klot vill Rok Orhan ha?",a="Ett klot taget från en av Gordunni-häxmästarna. En magikers klot rymmer stor kraft, och Rok Orhan hoppas att det ska lära honom mer om ceremonin och Gordunnis magi.",al={"varför hämta gordunni-klotet","syftet med gordunni-klotet"}},{q="Vad följer efter Mörk ceremoni?",a="Uppdragskedjan fortsätter med The Gordunni Orb.",al={"nästa uppdrag efter mörk ceremoni","uppdragskedjan mörk ceremoni"}}},fp="13,246,25.346.0,25.133.1,24.69.0,34.75.0,28.170.0,27.40.0"}
P.entries["quest:298"] = {n="Excavation Progress Report",s="Excavation Progress Report är ett Alliance-ärende från utgrävningarna i Loch Modan tillbaka till staden. Prospector Ironband ber en äventyrare att bära hans senaste rapporter från utgrävningen och en förnyad beställning av sprängämnen till Jern Hornhelm i Thelsamar.",h="Excavation Progress Report är ett Alliance-ärende från utgrävningarna i Loch Modan tillbaka till staden.",kw={"sprängpulver","excavation progress report","explorers' league","jern hornhelm","loch modan","prospector ironband","thelsamar","trogg"},ang={["faction:Alliance"]="Om försörjningsvägarna mellan Thelsamar och avlägsna utposter hålls öppna kan Alliance behålla ett fast grepp om bergen i Loch Modan.",["profession:Mining"]="Gruvarbetare vet alltför väl hur viktigt tillförlitligt sprängpulver är när man bryter igenom kompakt berg och gräver tunnlar genom forntida berglager.",["race:Dwarf"]="För äventyrare av dvärgafolket innebär hjälpen till Ironband att de värnar Explorers' Leagues viktiga historiska arbete och skyddar sina fränder från hungriga troggs."},sec={{t="En rapport till Thelsamar",b="Prospector Ironbands arkeologiska arbete i Loch Modan kräver ständigt logistiskt stöd från närliggande bosättningar. Utgrävning är ett ansträngande arbete som kräver hackor, arbetskraft och rikliga mängder sprängpulver för att ta sig igenom hårt berg. Ironband förlitar sig på budbärare som överlämnar hans regelbundna lägesrapporter och materialbeställningar till Jern Hornhelm, den lokala expeditionskontakten i Thelsamar."},{t="Saknad ammunition",b="När Hornhelm tar emot Ironbands rapport får han veta att utgrävningsplatsen utsätts för svåra angrepp från aggressiva troggs. Hornhelm håller med om att det är ett gott ändamål att förse dem med pulver för att spräcka sten eller spränga troggs, men Ironbands förnyade beställning väcker genast oro. Hornhelm hade skickat en stor leverans sprängpulver flera veckor tidigare, så han undrar vad som hänt med den saknade ammunitionen längs de karga bergsstigarna."}},faq={{q="Vem ger dig rapporten?",a="Prospector Ironband ger dig rapporten vid Ironband's Excavation Site, som ligger i de sydöstra kullarna i Loch Modan. Han övervakar den arkeologiska utgrävningen där.",al={"uppdragsgivare","vem startar excavation progress report","ironbands plats"}},{q="Vem är Jern Hornhelm?",a="Jern Hornhelm är en dvärgkontakt för Explorers' League som är stationerad i Thelsamar. Han samordnar lokal logistik och förnödenheter för arkeologiska expeditioner i Loch Modan.",al={"var finns jern hornhelm","vem ska ta emot rapporten","kontakt i thelsamar"}},{q="Varför behöver Prospector Ironband mer sprängpulver?",a="Ironband behöver uppenbarligen sprängpulver för att röja fast berg vid utgrävningen. Men utgrävningsplatsen kryllar av fientliga troggs, så sprängämnen är minst lika viktiga för försvaret.",al={"varför sprängpulver","vad behöver ironband pulvret till"}},{q="Vad hände med den tidigare leveransen av pulver?",a="Jern Hornhelm skickade en leverans sprängpulver för flera veckor sedan, men den kom aldrig fram till utgrävningen. Det mystiska försvinnandet tyder på problem längs försörjningsvägarna mellan Thelsamar och de avlägsna platserna.",al={"vart tog pulvret vägen","saknat sprängpulver"}},{q="Vad händer efter att du har lämnat över lägesrapporten?",a="Efter att ha gått igenom Ironbands svåra situation och det olösta problemet med det saknade pulvret ber Hornhelm dig att rapportera expeditionens läge till överordnade i Ironforge.",al={"nästa uppdrag","vad händer sedan","rapport till ironforge"}},{q="Varför angriper troggs utgrävningsplatsen?",a="Dvärgarnas utgrävningar blottlägger ofta underjordiska kammare och stör troggbon. Varelserna ser gruvarbetarna som inkräktare på sitt område och svärmar våldsamt kring alla som gräver i marken.",al={"orsak till troggs angrepp","varför troggs hatar ironband"}}},fx={["0b7d15ff"]={q="Varför behöver Prospector Ironband att du levererar rapporten?",a="Prospector Ironband och hans medutgrävare hålls fast vid utgrävningsplatsen av oupphörliga troggangrepp. Eftersom hela hans besättning är upptagen med att försvara sitt arkeologiska arbete och kämpa för att överleva kan Ironband inte avvara någon som tar vägen tillbaka till Thelsamar. En utomstående resenär som du kan snabbt och pålitligt föra hans ord genom den farliga vildmarken.",al={"varför skicka mig","varför går han inte själv","varför leverera rapporten"}}},fp="26,133,23.204.0,17.267.1,29.150.0,21.160.0,51.159.0,49.173.0,50.144.0,45.147.0"}
P.entries["quest:2980"] = {n="The Ogres of Feralas",s="Rok Orhan vid Camp Mojache skickar dig till High Wilderness, sydväst om lägret, när han sett att du är en sann kämpe. Där ska Gordunni-ogrer, långt starkare än förut, drivas tillbaka bland ruinerna efter nattalvernas byggnader. Detta följer på The Ogres of Feralas.",h="Rok Orhan vid Camp Mojache skickar dig till High Wilderness, sydväst om lägret, när han sett att du är en...",kw={"camp mojache","feralas","gordunni","high wilderness","maulers","rok orhan","shamans","warlocks"},sec={{t="Till High Wilderness",b="Rok Orhan bedömer att du har visat dig vara en sann kämpe och anförtror dig nästa del av arbetet. High Wilderness ligger sydväst om lägret, där övergivna, förstörda byggnader står på mark som nattalverna en gång ägde. Vissna träd och vanhelgad mark visar var Gordunni håller till. Rok varnar för att dessa ogres är långt starkare än de tidigare. Tio Gordunni Shamans, tio Gordunni Warlocks och fem Gordunni Maulers ska fällas."}},faq={{q="Vem skickar dig till High Wilderness?",a="Rok Orhan vid Camp Mojache.",al={"uppdragsgivare","rok orhan","vem startar detta"}},{q="Var finns dessa Gordunni?",a="I High Wilderness, sydväst om Camp Mojache, kring förstörda byggnader på mark som nattalverna en gång ägde. Vissna träd och vanhelgad mark visar platsen.",al={"var finns ogres","platsen high wilderness","ruinernas plats"}},{q="Vilka ogres måste dödas?",a="Tio Gordunni Shamans, tio Gordunni Warlocks och fem Gordunni Maulers.",al={"vem ska jag döda","ogremål","gordunni-typer"}},{q="Vad kommer före det här steget?",a="Det första The Ogres of Feralas, där Rok Orhan skickade dig mot ogres vid deras utpost i norr.",al={"förutsättning","föregående uppdrag","uppdragsordning"}}},fp="20,276,24.452.0,37.26.0,25.166.0,27.70.0,28.108.0"}
P.entries["quest:2982"] = {n="The High Wilderness",s="Angelas Moonbreeze och Troyas undersöker gamla ruiner i Feralas skogar, men på sistone beger sig Troyas ensam till High Wilderness, vilket oroar Angelas. Gordunni-ogrerna håller till där. Angelas hoppas att du gör ruinerna i sydost lite säkrare genom att decimera ogreflocken.",h="Angelas Moonbreeze och Troyas undersöker gamla ruiner i Feralas skogar, men på sistone beger sig Troyas ensam...",kw={"angelas moonbreeze","feralas","gordunni","gordunni brute","gordunni shaman","gordunni warlock","high wilderness","ogrer","troyas"},sec={{t="Oro för Troyas",b="Angelas Moonbreeze medger att arbetet är farligt, men Angelas och Troyas fortsätter att utforska ruinerna som ligger utspridda i Feralas skogar. På sistone beger sig Troyas ensam till High Wilderness, och Angelas oroar sig. Gordunni-ogrerna har tagit över området och ser ogärna att någon tar sig in på deras mark. Angelas hoppas att du beger dig till ruinerna sydost om här och decimerar några av dem, så att det blir säkrare för Troyas: åtta Gordunni Warlocks, åtta Gordunni Shamans och åtta Gordunni Brutes."},{t="Efteråt",b="När det är gjort är Angelas mycket tacksam och ber dig att inte nämna ett ord om det för Troyas."}},faq={{q="Vem ber dig rensa High Wilderness?",a="Angelas Moonbreeze, som undersöker ruinerna i Feralas tillsammans med Troyas.",al={"vem är angelas","angelas moonbreeze","vem ger uppdraget i high wilderness"}},{q="Varför vill Angelas att Gordunni-ogrerna ska decimeras?",a="Troyas har begett sig ensam till High Wilderness, och Angelas oroar sig. Gordunni-ogrerna har tagit över området och välkomnar inte besökare på sin mark.",al={"varför döda gordunni","varför döda ogres i high wilderness","angelas skäl"}},{q="Var ligger ruinen i High Wilderness?",a="Angelas pekar ut ruinerna i sydost.",al={"var ligger high wilderness","high wilderness plats","ruinerna i sydost"}},{q="Vilka Gordunni måste dödas?",a="Åtta Gordunni Warlocks, åtta Gordunni Shamans och åtta Gordunni Brutes.",al={"vem ska jag döda i high wilderness","gordunni-mål i high wilderness"}},{q="Vad sägs om Gordunnis magi?",a="Angelas varnar för att Gordunnis magi tycks härja marken under deras fötter och uppmanar dig att vara försiktig i deras närhet.",al={"gordunnis magi","ogres besvärjelser","vilken magi härjar"}}},fp="19,277,16.494.0,9.94.1,46.79.0,53.159.0,34.49.0,29.74.0,40.128.0"}
P.entries["quest:2985"] = {n="Call of Water",s="Swart skickar en schaman från Razor Hill för att söka upp Islen Waterseer vid The Barrens kust. Jord och eld har prövat novisen; nu kräver vattnet en annan sorts förståelse.",h="Swart skickar en schaman från Razor Hill för att söka upp Islen Waterseer vid The Barrens kust.",kw={"call of water","islen waterseer","ratchet","razor hill","shaman","southfury river","swart","the barrens","water totem"},ang={["class:Shaman"]="Som schaman vänder du dig från jord och eld mot vattnets läkande kraft och öppnar en andlig väg till läkande totemer.",["faction:Horde"]="Som schaman i Horden hänvisas du till Islen Waterseer vid The Barrens kust för att inleda din gemenskap med vattnet."},sec={{t="En förändring bland elementen",b="Swart, schamantränaren i Razor Hill, vägleder noviserna genom elementen. Jorden har lärt dem uthållighet, och elden har prövat deras kontroll. När en schaman bevisar att hen kan hantera lågan utan att uppslukas av den, bedömer Swart att hen är redo att söka vattnets lärdomar."},{t="Enstöringen vid The Merchant Coast",b="Islen Waterseer bor vid The Barrens kust, bortom Ratchet. För att nå henne färdas du söderut längs Southfury River in i The Barrens och fortsätter sedan österut till stranden nära kadavret av en enorm haj. Islen bor där vågorna möter land, avskild från tränarna i Durotars städer. Hon vägleder Horden i gemenskapen med vattnet."}},faq={{q="Vem ger det här uppdraget?",a="Swart, orkschamantränaren i Razor Hill, skickar dig vidare när du har bevisat din kontroll över jord och eld.",al={"uppdragsgivare","vem startar call of water","swart"}},{q="Var hittar jag Islen Waterseer?",a="Islen Waterseer bor på The Barrens östra kust, strax söder om Ratchet. Följ Southfury River söderut från Durotar, fortsätt sedan mot stranden och leta efter hennes läger intill en stor haj som spolats upp på land.",al={"var är islen","islens plats","hur hittar man islen waterseer"}},{q="Varför måste en shaman lära sig elementen i en viss ordning?",a="Schamantraditionen kräver att en novis steg för steg bygger upp andlig balans. Jorden förankrar själen, och elden härdar den inför vattnets skiftande natur.",al={"elementens ordning","varför vatten efter eld","shamanens utveckling"}},{q="Är uppdraget tillgängligt för andra klasser?",a="Nej. Endast schamaner söker vattenandarnas gunst och försöker frambringa sin Water Totem.",al={"kan andra än shamaner göra detta","är call of water bara för shamaner"}},{q="Vilket landmärke ska jag leta efter när jag söker efter Islen?",a="Leta efter en enorm haj som spolats upp på stranden söder om Ratchet. Islen bor intill den.",al={"haj som landmärke","hur hittar man islens läger","islen vid kusten"}},{q="Vad händer när jag kommer fram till Islen Waterseer?",a="Samtalet med Islen inleder vattnets prövningar. Schamanen måste färdas genom Kalimdor och Lordaeron, samla rena vattendroppar och konfrontera andar innan hen förtjänar totemen.",al={"nästa steg","vad gör islen","efter call of water"}}},fx={["80a0e7c7"]={q="Varför skickar Swart dig till Islen Waterseer?",a="Swart ser att du behärskar elden och att din andliga resa som shaman måste fortsätta. Han kan inte själv lära dig vattnets vägar – att bemästra det flödande, rena elementet kräver vägledning från Islen Waterseer, en hängiven äldre som bor längs The Barrens kust. Swart skickar dig vidare så att du kan möta vattnet och stärka ditt band till elementen.",al={"varför vill swart få detta gjort","swarts motiv","varför skicka mig till islen"}}},fp="13,178,23.275.0,33.324.0,21.109.0,33.204.0,57.149.0,41.93.0,57.86.0,44.176.1"}
P.entries["quest:2987"] = {n="Gordunni Cobalt",s="Orwin Gizzmick har just anlänt till Feralas och hört att Gordunni-ogrerna begraver intressanta mineraler. Orwin erbjuder en spade och ber dig bege dig till Gordunni Outpost, norr om Camp Mojache, och gräva upp tolv prover av Gordunni-kobolt genom att följa det blå skenet.",h="Orwin Gizzmick har just anlänt till Feralas och hört att Gordunni-ogrerna begraver intressanta mineraler.",kw={"camp mojache","kobolt","feralas","gizzmick","gordunni","gordunni outpost","ogrer","orwin","spade"},sec={{t="Begravda mineraler",b="Orwin Gizzmick har precis kommit till Feralas och hört att Gordunni-ogrerna har intressanta mineraler. Orwin vet inte vad ogreerna har i görningen, men de vaktar mineralerna noga och låter dem inte ligga framme. De begraver dem för att hindra sådana som Orwin från att få tag på dem. Orwin ger dig en spade. Gordunni Outpost ligger norr om lägret; ett blått sken visar var du ska gräva. Tolv prover av Gordunni-kobolt behövs."},{t="När kobolten har lämnats in",b="Orwin tänker ta med sig kobolten på fortsatta resor, säker på att någon kommer att betala dyrt för den, och ger dig något för besväret."}},faq={{q="Vem vill ha Gordunni-kobolt?",a="Orwin Gizzmick vid Camp Mojache, som just har anlänt till Feralas.",al={"vem startar gordunni-kobolt","orwin gizzmick-uppdrag","vem vill ha kobolt"}},{q="Var finns Gordunni-kobolten?",a="Begravd vid Gordunni Outpost, norr om Camp Mojache.",al={"gordunni-koboltens plats","var hittar man kobolt i feralas","var ligger gordunni outpost"}},{q="Hur upptäcker du den begravda kobolten?",a="Ett blått sken avslöjar platsen. Sedan gräver du.",al={"hur upptäcker man kobolt","hitta kobolt i feralas","blått sken i ogrejord"}},{q="Varför begraver ogreerna sin kobolt?",a="Orwin säger att ogreerna är väldigt rädda om den och begraver den för att hindra sådana som Orwin från att få tag på den. Orwin kan inte säga vad de ska ha den till.",al={"varför är kobolt begravd","varför begraver gordunni kobolt","begravd ogre-kobolt"}},{q="Hur mycket kobolt vill Orwin ha?",a="Tolv prover, uppgrävda med Orwins spade.",al={"antal kobolt","hur många gordunni-kobolt"}}},fp="15,273,15.431.0,28.147.1,26.65.0,29.54.0,34.50.0,35.144.0,32.43.0"}
P.entries["quest:2988"] = {n="Witherbark Cages",s="Gryphon Master Talonaxe berättar att Sharpbeak, Swiftwings arvinge och den mäktigaste gryphonen, har försvunnit och att trollen tros ha tagit den unga gryphonen. Du får i uppdrag att söka igenom burarna i de två Witherbark-trollbyarna efter tecken på Sharpbeak.",h="Gryphon Master Talonaxe berättar att Sharpbeak, Swiftwings arvinge och den mäktigaste gryphonen, har...",kw={"burar","gryphon","hinterlands","sharpbeak","swiftwing","talonaxe","troll","witherbark"},sec={{t="En försvunnen arvinge",b="Sharpbeak försvann för några dagar sedan när han jagade med sina föräldrar. Talonaxe och de andra tror att trollen tog honom, och du ombeds om hjälp. Tre burar i de två Witherbark-trollbyarna ska undersökas, och Talonaxe vill höra vad du hittar."},{t="Besked från byarna",b="Sharpbeak finns inte i Witherbark-byarna. Talonaxe tar emot beskedet med allvar. Den unga gryphonen är tänkt att leda nästa generation, och om han är förlorad kommer flottans styrka och anda att lida svårt."}},faq={{q="Vem är Sharpbeak?",a="Sharpbeak är arvinge till Swiftwing, som Talonaxe kallar den mäktigaste gryphonen. Han försvann för några dagar sedan när han jagade med sina föräldrar.",al={"sharpbeak","vem är gryphonen","swiftwings arvinge"}},{q="Varför misstänks Witherbark-trollen?",a="Talonaxe och de andra tror att trollen tog Sharpbeak, så burarna i Witherbark-byarna är första stället att leta på.",al={"varför trollen","witherbarks inblandning","vem tog sharpbeak"}},{q="Var ska jag leta efter Sharpbeak?",a="Leta i burarna i de två Witherbark-trollbyarna och kom sedan tillbaka och berätta för Gryphon Master Talonaxe vad du hittade.",al={"var finns burarna","witherbark-burarnas plats","var leta efter sharpbeak"}}},fp="16,176,14.270.0,22.200.1,17.152.0,40.133.0,32.122.0"}
P.entries["quest:2989"] = {n="The Altar of Zul",s="Witherbark-trollen har inte Sharpbeak, så Gryphon Master Talonaxe undrar om Vilebranch-trollen i stället tog den unga gripen. Du skickas till Altar of Zul, vid den västra gränsen av Vilebranchs område, för att leta efter honom.",h="Witherbark-trollen har inte Sharpbeak, så Gryphon Master Talonaxe undrar om Vilebranch-trollen i stället tog...",kw={"altar of zul","gryphon master talonaxe","the hinterlands","sharpbeak","vilebranch","witherbark"},sec={{t="En annan stam, ett nytt sökande",b="I Witherbark-trollens burar syntes inte ett spår av Sharpbeak. Talonaxe misstänker nu Vilebranch-trollen och skickar dig upp till Altar of Zul, vid den västra gränsen av deras område, för att leta efter gripungen där uppe. Talonaxe bävar inför tanken på vad Vilebranch kan göra med fången, om de har honom."},{t="Besked från altaret",b="Sharpbeak är inte vid altaret. Talonaxe kallar det både dåliga och goda nyheter: Vilebranch-trollen är kända för att utföra offer, så det är en lättnad att gripen inte hittades där. Talonaxe tackar dig för hjälpen och säger att ett större uppdrag väntar."}},faq={{q="Varför skickar Gryphon Master Talonaxe dig till Altar of Zul?",a="Witherbark-trollen har inte Sharpbeak, så Talonaxe tror att Vilebranch-trollen kan ha tagit honom.",al={"varför altar of zul","orsaken till altar of zul","varför gå till altar of zul"}},{q="Var ligger Altar of Zul?",a="Altar of Zul ligger vid den västra gränsen av Vilebranchs område i The Hinterlands. Du ska undersöka toppen.",al={"altar of zul plats","var ligger altar of zul"}},{q="Vem är Sharpbeak?",a="Sharpbeak är Swiftwings arvinge, gripungen som Talonaxe har letat efter sedan han försvann.",al={"vem är sharpbeak","sharpbeaks bakgrund"}},{q="Varför oroar sig Talonaxe för Vilebranch-trollen?",a="Talonaxe fruktar att ingen kan veta vad Vilebranch gör med Sharpbeak, om de har honom.",al={"varför är vilebranch farliga","vad gör vilebranch"}}},fp="16,235,29.312.0,19.269.1,62.105.0,34.113.0,17.103.0,52.99.0"}
P.entries["quest:299"] = {n="Uncovering the Past",s="Prospector Whelgar skickar äventyrare till Whelgar's Excavation Site i Wetlands för att återfinna fyra saknade delar av Goaz Stone.",h="Prospector Whelgar skickar äventyrare till Whelgar's Excavation Site i Wetlands för att återfinna fyra...",kw={"ados","goaz stone","golm","modr","neru","prospector whelgar","titaner","uncovering the past","wetlands","whelgar's excavation site"},ang={["faction:Alliance"]="När du hjälper League med utgrävningar i Wetlands stärker du Alliances närvaro och säkrar värdefull kunskap innan den hamnar i vilda eller fientliga händer.",["race:Dwarf"]="Explorers' League anser att varje återfunnen relik är viktig för att låsa upp dvärgarnas ursprung. Titan-inskriptionerna på Goaz Stone har en direkt koppling till det uråldriga arvet."},sec={{t="Den krossade stenen",b="Innan raptorerna svärmade över utgrävningen i Wetlands grävde Prospector Whelgar fram en viktig relik: Goaz Stone. De första försöken att tyda den uråldriga skriften gav fragmentariska hänvisningar till en ”gudomlig plan” och en ”ödesdiger profetia”. Tyvärr hade viktiga delar brutits loss på fyra olika ställen, och avgörande textstycken låg utspridda bland fossilerna i jorden."},{t="Ute på utgrävningen",b="För att återställa stenen måste du genomsöka den raptorinfekterade utgrävningen efter de fyra saknade fragmenten: Ados, Modr, Golm och Neru. De ligger begravda i lös jord och bland halvt utgrävda reliker som vaktas av aggressiva Razormaws och Scytheclaws. För att hitta alla delar måste du ta dig igenom träskmarkens toppredatorer."},{t="Fjättrade under jorden",b="När delarna åter satts ihop avslöjar Goaz Stone titanernas svårbegripliga och gåtfulla språk. När Whelgar översätter de återställda runorna hittar han en kuslig inskription: ”Old Gods... Chained Beneath the Land.” Tavlan är mer än en enkel historisk kuriositet. Den antyder titaniska strider vid världens gryning och mörka ondskor begravda under Azeroths jordskorpa."}},faq={{q="Vad är Goaz Stone?",a="Goaz Stone är en uråldrig Titan-relik som Prospector Whelgar upptäckte vid utgrävningen i Wetlands. Den bär kryptiska inskriptioner om kosmisk historia, en gudomlig plan och uråldriga väsen bundna djupt under jorden.",al={"goaz stone historia","vad är goaz-tavlan","tavelfragment wetlands"}},{q="Vem ger uppdraget Uncovering the Past?",a="Prospector Whelgar erbjuder uppdraget från sin utsiktsplats med vy över Whelgar's Excavation Site, öster om Menethil Harbor i Wetlands. Han tvingades bort från utgrävningen av vilda raptorer.",al={"vem startar uncovering the past","var får man uncovering the past"}},{q="Vilka fragment behövs för att återställa tavlan?",a="Du behöver fyra särskilda stenfragment: Ados, Modr, Golm och Neru. De ligger utspridda i jordhögar och gamla urnor över hela stenbrottet som kryllar av raptorer.",al={"vilka fragment","namn på tavelfragment","ados modr golm neru"}},{q="Varför kan inte Prospector Whelgar hämta fragmenten själv?",a="Whelgar är en ålderstigen dvärgsk lärd. När våldsamma raptorer plötsligt invaderade och tog över stenbrottet tvingades han retirera, och han är inte stark nog att ensam slå sig igenom flockarna.",al={"varför hämtar inte whelgar stenarna","varför ber whelgar dig"}},{q="Vad avslöjar de översatta Titan-runorna?",a="När de fyra saknade delarna satts på plats tyder Whelgar Titan-skriften och läser frasen: ”Old Gods... Chained Beneath the Land.” Detta antyder att uråldriga kosmiska väsen låstes in när Azeroth formades.",al={"vad står det på goaz stone","titanöversättning wetlands","old gods chained beneath the land"}},{q="Har uppdraget någon koppling till andra expeditioner i närheten?",a="Ja. Det kompletterar direkt Ormer Ironbraids uppdragskedja Ormer's Revenge, där äventyrare får i uppdrag att minska antalet raptorer i samma stenbrott.",al={"uppdrag nära utgrävningen","ormer ironbraids koppling","koppling till ormer's revenge"}}},fx={["2fe7ef8c"]={q="Varför vill Prospector Whelgar att tavelfragmenten återfinns?",a="Prospector Whelgar upptäckte en väldig relik kallad Goaz Stone strax innan rovfåglarna översvämmade utgrävningsplatsen. De översatta delarna av dess titaniska skrift talar olycksbådande om en ”gudomlig plan” och en ”dödsdömd profetia”, men inskriften avbryts plötsligt där fyra delar saknas. Whelgar fruktar att tiden är knapp och är desperat efter att sätta samman hela tavlan, så att han kan tyda resten av budskapet och avslöja hemligheterna begravda under utgrävningen.",al={"whelgars motiv","varför hitta fragmenten","varför behöver whelgar fragmenten"}},f38df7d0={q="Vad är fragmenten Ados, Modr, Golm och Neru?",a="Fragmenten Ados, Modr, Golm och Neru är de fyra saknade bitarna som brutits loss från Goaz Stone. Varje fragment innehåller en del av den forntida titaniska skrift som behövs för att fullborda inskriften. När de fogas tillbaka till huvudstenen kan Prospector Whelgar översätta hela texten och avslöja olycksbådande passager om forntida väsen som kedjats fast under jorden.",al={"vad är fragmenten","ados modr golm neru","tavelfragmentens betydelse"}}},fp="19,236,16.363.0,20.321.0,24.360.1,23.226.1,40.193.0,49.173.0,59.192.0,43.229.1,54.165.0"}
P.entries["quest:2990"] = {n="Thadius Grimshade",s="Gryphon Master Talonaxe ger dig en fjäder från gryphonungen Sharpbeaks bo. Du ska ta den till spåmannen Thadius Grimshade, som bor i magikertornet i Nethergarde Keep i Blasted Lands.",h="Gryphon Master Talonaxe ger dig en fjäder från gryphonungen Sharpbeaks bo.",kw={"aerie peak","blasted lands","spådom","gryphon","nethergarde keep","sharpbeak","talonaxe","thadius grimshade"},sec={{t="En vädjan till en spåman",b="För många år sedan lämnade Thadius Grimshade Aerie Peak för att söka mörkare kunskap, men Talonaxe säger att han fortfarande är en Wildhammer i hjärtat. Med lite tur kan spådomsmagi och fjädern från Sharpbeaks bo hjälpa Thadius att hitta gryphonungen. Talonaxe säger att Thadius finns i magikertornet i Nethergarde Keep i Blasted Lands."},{t="Spåmannens välkomnande",b="Thadius hälsar dig välkommen som någon som bär med sig en gåva. Han känner genast igen fjädern som tillhörande en ståtlig gryphon, ämnad för stora ting om den får växa upp oskadd. Sedan säger han åt dig att lyssna noga."}},faq={{q="Vem är Thadius Grimshade?",a="Thadius Grimshade är en spåman. Han lämnade Aerie Peak för många år sedan för att söka mörkare kunskap, men Talonaxe säger att han fortfarande är en Wildhammer i hjärtat.",al={"thadius grimshade berättelse","vem är thadius"}},{q="Varför behöver du Sharpbeaks fjäder?",a="Fjädern samlades in vid boet där Sharpbeak sover. Talonaxe hoppas att Thadius kan använda sin spådomsmagi på den för att hitta den unga gryphonen.",al={"varför sharpbeaks fjäder","fjäderns syfte"}},{q="Var finns Thadius Grimshade?",a="Thadius Grimshade bor i Blasted Lands, i magikertornet i Nethergarde Keep.",al={"thadius grimshade plats","var finns thadius"}}},fp="17,210,19.325.0,21.203.1,25.142.0,36.144.0,35.80.0"}
P.entries["quest:2992"] = {n="The Divination",s="Thadius Grimshade ber dig ge honom utrymme medan han utför en spådomsritual. Han tänker följa bandet mellan fjädern du tog med och dess ägare tills det leder honom till Sharpbeak.",h="Thadius Grimshade ber dig ge honom utrymme medan han utför en spådomsritual.",kw={"fjäder","grip","ritual","sharpbeak","thadius grimshade","spådomen"},sec={{t="En spådomsritual",b="Thadius följer bandet mellan Sharpbeaks fjäder och gripen som äger den, i hopp om att nå Sharpbeak själv. Han ber om tystnad och arbetsro. Han medger att det kanske inte går som planerat och varnar dig för att du då bör blunda."},{t="När ritualen är över",b="Ritualen lyckas. Thadius har skymtat Sharpbeak och kan berätta var du ska leta."}},faq={{q="Vad gör Thadius Grimshade i den här ritualen?",a="Thadius utför en spådomsritual. Han söker bandet mellan fjädern du tog med och Sharpbeak, och tänker följa det till Sharpbeak själv.",al={"vad är spådomen","grimshades ritual","hur hittar grimshade sharpbeak"}},{q="Vem är Sharpbeak?",a="Sharpbeak är gripungen vars fjäder du tog med till Thadius, och som Gryphon Master Talonaxe har försökt hitta.",al={"sharpbeak","vem är sharpbeak"}},{q="Är ritualen farlig?",a="Thadius varnar för att du bör blunda om ritualen inte går som planerat. Han ber dig ge honom arbetsro.",al={"är spådomen farlig","varför blunda","risk med spådom"}}},fp="14,192,22.247.0,20.90.1,47.150.0,17.126.0,24.140.0"}
P.entries["quest:2993"] = {n="Return to the Hinterlands",s="Thadius Grimshade berättar var Sharpbeak hålls fången: i en bur på en hög klippa, högst upp i Jintha'Alor i The Hinterlands. Vile Priestess Hexx, översteprästinna bland Vilebranch-trollen, har nyckeln. Du ska föra nyheten vidare till Gryphon Master Talonaxe.",h="Thadius Grimshade berättar var Sharpbeak hålls fången: i en bur på en hög klippa, högst upp i Jintha'Alor i...",kw={"gryphon master talonaxe","the hinterlands","jintha'alor","sharpbeak","thadius grimshade","vile priestess hexx","vilebranch"},sec={{t="Var Sharpbeak hålls fången",b="När Thadius har gjort sitt önskar han dig lycka till och berättar vad han fått veta. Sharpbeak sitter i en bur på en hög klippa, högst upp i Jintha'Alor i The Hinterlands. Vile Priestess Hexx, översteprästinna bland Vilebranch-trollen, har nyckeln till buren. Ta med beskedet till Gryphon Master Talonaxe."},{t="Talonaxes svar",b="Talonaxe frågar vad Thadius sa. När han får veta att Vilebranch-trollen har Sharpbeak tycker Talonaxe att det är outhärdligt och säger att en styrka måste samlas för att få tillbaka gripen."}},faq={{q="Vem avslöjar var Sharpbeak finns?",a="Thadius Grimshade, som utförde spådomsritualen och sedan berättade var Sharpbeak hålls fången.",al={"vem berättar var sharpbeak finns","vem avslöjar sharpbeaks plats","vem hittar sharpbeak"}},{q="Var hålls Sharpbeak fången?",a="Sharpbeak sitter i en bur på en hög klippa, högst upp i Jintha'Alor i The Hinterlands.",al={"var är sharpbeak","sharpbeaks burplats","sharpbeaks klippa"}},{q="Vem har nyckeln till Sharpbeaks bur?",a="Vile Priestess Hexx, översteprästinna bland Vilebranch-trollen, har nyckeln.",al={"sharpbeaks nyckel","vem har burens nyckel","vile priestess hexx nyckel"}},{q="Vart ska du lämna beskedet?",a="Ta det till Gryphon Master Talonaxe i The Hinterlands.",al={"vem ska jag återvända till","var lämnar jag in return to the hinterlands","gryphon master talonaxes plats"}},{q="Vad hände före den här resan?",a="Thadius Grimshade hade just utfört spådomsritualen för att hitta Sharpbeak.",al={"föregående uppdrag","vad ledde fram till return to the hinterlands","föregående steg"}}},fp="25,245,23.294.0,17.178.1,38.100.0,30.72.0,38.76.0,31.54.0,30.80.0"}
P.entries["quest:2994"] = {n="Saving Sharpbeak",s="Gryphon Master Talonaxe skickar dig till toppen av Jintha'Alor, mitt i Vilebranchs område. Vile Priestess Hexx har nyckeln till Sharpbeaks bur, och du ska ta den från henne och befria gripen.",h="Gryphon Master Talonaxe skickar dig till toppen av Jintha'Alor, mitt i Vilebranchs område.",kw={"aerie peak","gryphon master talonaxe","the hinterlands","jintha'alor","rädda sharpbeak","sharpbeak","vile priestess hexx","vilebranch"},sec={{t="Uppför Jintha'Alor",b="Efter Thadius Grimshades spådom och din rapport till Talonaxe står det klart hur Sharpbeak kan räddas. Jintha'Alor ligger mitt i Vilebranchs område, och du måste kämpa dig upp till toppen. Vile Priestess Hexx har nyckeln till Sharpbeaks bur. Ta den från henne, hitta sedan buren och rädda gripen."},{t="Talonaxes tack",b="Swiftwind och Keenclaw har redan tagit sitt barn hem och kan inte sluta pyssla om honom. Synen får Talonaxe att bli tårögd. Talonaxe säger att skulden aldrig kan återgäldas och att griparna och ryttarna från Aerie Peak länge kommer att sjunga ditt namn."}},faq={{q="Vem skickar dig för att rädda Sharpbeak?",a="Gryphon Master Talonaxe ber dig rädda Sharpbeak efter att spådomen avslöjat var gripen hålls fången.",al={"vem ger uppdraget rädda sharpbeak","uppdragsgivare för sharpbeak","var börjar jag rädda sharpbeak"}},{q="Var hålls Sharpbeak fången?",a="Sharpbeak sitter i en bur på toppen av Jintha'Alor, en plats i Vilebranchs område i The Hinterlands.",al={"var är sharpbeak","sharpbeaks plats","var finns sharpbeaks bur"}},{q="Vem har nyckeln till Sharpbeaks bur?",a="Vile Priestess Hexx har nyckeln som behövs för att öppna Sharpbeaks bur.",al={"vem släpper sharpbeaks nyckel","var finns hexx nyckel","vile priestess hexx nyckel"}}},fp="16,221,14.323.0,17.241.1,34.110.0,30.104.0,38.64.0"}
P.entries["quest:2996"] = {n="Seeking Strahad",s="I Orgrimmar skickar Gan'rul Bloodeye trollkarlar söderut till Ratchet för djupare träning. Där undervisar en mänsklig besvärjare i konster bortom grundläggande åkallning.",h="I Orgrimmar skickar Gan'rul Bloodeye trollkarlar söderut till Ratchet för djupare träning.",kw={"the barrens","cleft of shadow","felhunter-uppdrag","gan'rul bloodeye","ratchet","seeking strahad","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Som trollkarl närmar du dig mästerskap över demoner på mellannivå, och din beredskap att kuva den magiätande felhuntern sätts på prov.",["faction:Horde"]="Som medlem av Horde ser du hur trollkarlskovener verkar bortom Warchiefs formella diplomati: deras mästare skickar lärlingar till en ensam människa."},sec={{t="Lämna Orgrimmars skuggor",b="Gan'rul Bloodeye tränar unga trollkarlar i Cleft of Shadow, där de lär sig att befalla över Nether. När en lärling växer ur den undervisningen hänvisar Gan'rul dem bortom stadsmurarna. Mer oberäkneliga väsen kräver undervisning av någon med djupare kunskaper i mörk arkana."},{t="En okonventionell allians",b="Gan'rul skickar lärlingar till Strahad Farsan, en mänsklig magiker i ett torn ovanför Ratchets goblinhamn. Horde och människor kan vara fiender, men trollkarlar ser bortom vanliga lojaliteter till fraktioner. Makt, disciplin och ritualkunskap väger tyngre än härkomst. Strahad bedömer en lärling efter deras inre hat och förmåga att kuva, inte efter deras hudfärg."}},faq={{q="Varför skickar en orktrollkarl mig till en människa?",a="Trollkarlar värdesätter mörk kunskap högre än lojalitet mot sin ras. Gan'rul Bloodeye vet att Strahad Farsan har sällsynt skicklighet i avancerad demonologi, och en lärares kunskap väger tyngre än fraktionsgränser när man söker farliga väsen att åkalla.",al={"varför lära av en människa","mänsklig trollkarl strahad","varför strahad"}},{q="Var hittar jag Strahad Farsan?",a="Strahad Farsan bor på de höga klipporna ovanför Ratchet i The Barrens, utanför sitt torn med utsikt över goblinhamnen.",al={"strahads plats","var finns strahad","strahads torn ratchet"}},{q="Vilken kraft lär Strahad ut?",a="Strahad lär ut ritualerna för att binda en felhunter, en magiätande demon från Twisting Nether. Han studerar ockulta texter med trollkarlar och prövar sedan deras förmåga att förslava besten.",al={"vad låser strahad upp","vad får jag av strahad","belöning för seeking strahad"}},{q="Vem är Gan'rul Bloodeye?",a="Gan'rul Bloodeye är en framstående orcisk trollkarl och mentor i Cleft of Shadow under Orgrimmar. Han lär upp Horde-trollkarlar i grunderna i felmagi och åkallandet av mindre tjänare.",al={"vem är ganrul","gan'rul bloodeye","trollkarlslärare i orgrimmar"}},{q="Finns det något annat sätt att påbörja det här uppdraget?",a="Ja. Undead-trollkarlar får en liknande kallelse från Magic Quarter i Undercity, som hänvisar dem till samma mänskliga mentor ovanför Ratchet.",al={"seeking strahad undercity","övergivna söker strahad","undercity-versionen"}},{q="Är Ratchet farligt för hordens trollkarlar?",a="Ratchet styrs av Steamwheedle Cartel och förblir en neutral hamn. Håll fred och attackera inte resenärer i staden, så låter goblinbödlarna dig vara.",al={"är ratchet säkert","är vakterna i ratchet fientliga","neutral hamn"}}},fx={d843591e={q="Varför skickar Gan'rul Bloodeye dig till Strahad?",a="Gan'rul Bloodeye inser att dina mörka talanger har vuxit bortom hans undervisning i Orgrimmar. För att komma vidare på demonologins väg och bemästra mäktigare besvärjelser behöver du esoterisk kunskap som bara Strahad Farsan besitter. Gan'rul lägger sina rasfördomar åt sidan för att se till att du fördjupar ditt kunnande.",al={"varför skicka till strahad","gan'rul bloodeyes motiv","varför söka strahad"}}},fp="15,157,32.279.0,22.353.0,44.217.0,32.116.0,30.184.1,24.185.0,41.144.0,47.166.0"}
P.entries["quest:2997"] = {n="Tome of Divinity",s="Tome of Divinity är en första kallelse som kallar unga dvärgpaladiner från deras fälttjänst i Dun Morogh till bergsstaden Ironforge. Azar Stronghammer skickar dem till Tiza Battleforge högt uppe i Hall of Mysteries för vägledning. Där börjar formellt paladinens djupare prövningar i den Heliga Ljusets tjänst.",h="Tome of Divinity är en första kallelse som kallar unga dvärgpaladiner från deras fälttjänst i Dun Morogh till...",kw={"azar stronghammer","dun morogh","hall of mysteries","heliga ljuset","ironforge","mystic ward","paladin","återlösning","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Den här övergångsriten förenar praktisk militärtjänst i snön med den djupa andliga disciplin som förväntas av heliga krigare.",["faction:Alliance"]="Den gemensamma vördnaden för Ljuset förenar Khaz Modans dvärgfö rsvarare med deras mänskliga allierade i Lordaeron och Stormwind.",["race:Dwarf"]="Dvärgpaladiner förenar sitt folks robusta uthållighet med det Heliga Ljusets lära, med sin kärna i Ironforges Hall of Mysteries."},sec={{t="En kallelse till High Seat",b="Dvärgarnas lärlingar börjar sin träning med att skydda de snötäckta byarna och vägarna i Dun Morogh, men enbart stridsförmåga gör ingen till paladin. Azar Stronghammer märker när en försvarare är redo för djupare andlig vägledning. I stället för att fortsätta med vanliga stridsövningar skickar han lovande kandidater till hjärtat av Ironforge, där deras verkliga invigning börjar under stadens vördnadsvärda heliga äldste."},{t="Hall of Mysteries",b="Kallelsen leder lärlingen till Mystic Ward och vidare upp till de stilla kamrarna i Hall of Mysteries. Där står Tiza Battleforge, omgiven av heliga reliker och högtidliga studier. Som en av de mest respekterade dvärgmästarna inom Ljuset prövar hon om de nya paladinerna är redo att omfamna självuppoffring, barmhärtighet och de tunga moraliska plikterna som följer med deras heliga kall."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det är den inledande kallelsen som leder en dvärgpaladin från Dun Moroghs avlägsna träningsområden till Tiza Battleforge i Ironforge. Där börjar prövningarna som krävs för att förstå det Heliga Ljuset och förtjäna uppståndelsens kraft.",al={"varför behöver jag det här uppdraget","vad är tome of divinity till för","syftet med tome of divinity"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en erfaren dvärgpaladin och respekterad mentor som håller till en trappa upp i Ironforges Hall of Mysteries. Hon ansvarar för unga paladiners andliga undervisning och vägleder dem genom Tome of Divinitys heliga prövningar.",al={"vem är tiza","tiza battleforge bakgrund","vem är battleforge"}},{q="Var ligger Hall of Mysteries?",a="Hall of Mysteries ligger i Mystic Ward i västra Ironforge. Det är dvärgarnas huvudstads andliga och mystiska centrum, där präster, paladiner och magiker håller till.",al={"var ligger hall of mysteries","hitta hall of mysteries","hall of mysteries ironforge"}},{q="Vem skickar paladinen på det här ärendet?",a="Azar Stronghammer, en paladintränare i Dun Morogh, skickar lovande lärlingar till Ironforge när de har visat sin hängivenhet till att försvara de lokala dvär bosättningarna.",al={"vem startar tome of divinity","uppdragsgivare tome of divinity","azar stronghammer"}},{q="Varför måste dvärgpaladiner studera i Ironforge?",a="Fälttränare som Azar lär ut grundläggande stridskonster, men den Heliga Ljusets formella lära, heliga texter och äldste finns i Hall of Mysteries. Avancerade riter och andliga läror måste studeras direkt under erfarna mentorer som Tiza Battleforge.",al={"varför åka till ironforge","varför träna i ironforge"}},{q="Vad händer efter att man talat med Tiza Battleforge?",a="Samtalet med Tiza inleder dvärgarnas verkliga prövningar i Tome of Divinity. Paladinen måste visa sin hängivenhet, medkänsla och vilja att offra sig i Ljuset tjänst.",al={"what comes next","nästa uppdrag efter tome of divinity","vad ger tiza mig"}}},fx={d775d5e6={q="Varför vill Azar Stronghammer att du besöker Ironforge?",a="Azar Stronghammer inser att din tid som lärling, där du hjälpt till i Dun Morogh, närmar sig sitt slut. För att verkligen tjäna som den Heliga Ljusets förkämpe behöver du djupare undervisning i dess mysterier, principer och plikter. Han hänvisar dig till Ironforge, eftersom Tiza Battleforge har fått i uppdrag att pröva och vägleda lovande unga paladiner mot deras rätta kall.",al={"varför skickar azar dig","azar stronghammers motiv","varför besöka tiza battleforge"}},a7a63213={q="Varför skickar Azar Stronghammer just dig?",a="Det här är inget ärende som en stadsvakt eller en erfaren veteran kan utföra åt dig. Det markerar dina personliga framsteg som paladin. Azar skickar dig till Tiza Battleforge eftersom du själv måste besvara Ljusets kallelse, bevisa din hängivenhet till dess dygder och ta på dig de bördor som väntar en helig krigare.",al={"varför skicka mig","varför azar skickar dig","varför paladinspelaren"}}},fp="16,213,23.242.0,21.221.0,34.225.0,24.203.0,39.169.0,37.164.0,45.238.0,50.157.0"}
P.entries["quest:2998"] = {n="Tome of Divinity",s="En kallelse med Tome of Divinity kallar lovande paladiner från Elwynn till Stormwind. När du svarar på Brother Wilhelms kallelse börjar de heliga prövningar som krävs för att bemästra återuppståndelse genom det Heliga ljuset.",h="En kallelse med Tome of Divinity kallar lovande paladiner från Elwynn till Stormwind.",kw={"brother wilhelm","cathedral of light","duthorian rall","goldshire","paladin","upprättelse","stormwind","tome of divinity"},ang={["class:Paladin"]="Dina mentorer erkänner formellt dina bedrifter och skickar dig inför Silver Hands högsta befälhavare, vilket markerar en övergångsrit för paladiner.",["faction:Alliance"]="Stormwinds rekrytering och prövning av heliga krigare hjälper Alliansen att behålla hängivna frontlinjehelande krigare och stridande genom oroliga tider.",["race:Human"]="Din resa från lantliga Elwynn Forest till den storslagna Cathedral of Light knyter dig till kungadömets djupaste andliga och militära institutioner."},sec={{t="En kallelse till huvudstaden",b="Nybörjarpaladiner i Elwynn Forest ägnar sina första dagar åt att hjälpa lokalbefolkningen och pröva sin styrka mot vargar, Defias-banditer och kobolder. När en aspirant visar stridsdisciplin och hängivenhet till det Heliga ljuset skickar mentorer som Brother Wilhelm en personlig kallelse. Paladinernas ledare lägger märke till lovande elever och ber dem lämna de lokala kapellen bakom sig och bege sig direkt till kungadömets andliga hjärta."},{t="Cathedral of Light",b="I Cathedral Square är Stormwinds Cathedral of Light kungadömets främsta helgedom för prästerskapet och Knights of the Silver Hand. Duthorian Rall bor där och övervakar dem som svurit orden trohet. Under de höga välvda taken ger högt uppsatta paladiner varje aspirant formella prövningar ur Tome of Divinity. Utmaningarna prövar medkänsla, uthållighet och viljan att offra sig."}},faq={{q="Vem skickar mig till Stormwind för det här uppdraget?",a="Brother Wilhelm, paladintränaren nära Lion's Pride Inn i Goldshire, skickar dig till Stormwind när du har visat prov på lovande förmåga och styrka i fält.",al={"uppdragsgivare","vem ger uppdraget","brother wilhelm"}},{q="Var hittar jag Duthorian Rall?",a="Duthorian Rall bor inne i Cathedral of Light i Cathedral Square, i nordvästra Stormwind City. Han tillbringar större delen av dagarna med att träna paladiner under dess ståtliga hallar.",al={"duthorian rall plats","var finns duthorian rall","paladinmästare plats"}},{q="Varför är den här kallelsen så viktig för paladiner?",a="När du infinner dig hos Duthorian Rall markerar det övergången från grundläggande stridsträning till djup helig gemenskap. Prövningarna i Tome of Divinity börjar där och ger dig till sist den heliga kraften att kalla fallna allierade tillbaka från döden genom Ljuset.",al={"varför göra uppdraget","uppdragets betydelse","paladinprövning"}},{q="Får paladiner som inte är människor exakt det här uppdraget?",a="Brother Wilhelms kallelse från Elwynn Forest är avsedd för mänskliga paladiner. Dvärgpaladiner får en motsvarande kallelse från sina egna tränare i Dun Morogh att besöka Ironforge.",al={"dvärgpaladin","kan dvärgar göra detta","är uppdraget bara för människor"}},{q="Vad händer efter att jag har infunnit mig hos Duthorian Rall?",a="När du hälsar på Duthorian Rall välkomnar han dig till Stormwind och ger dig genast prövningarna i Tome of Divinity, som utmanar din medkänsla och hängivenhet till att försvara de svaga.",al={"nästa uppdrag","vad händer sedan","nästa steg i tome of divinity"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en av de mest inflytelserika paladinerna i Stormwind och bland Knights of the Silver Hand. Han undervisar nya generationer heliga krigare i huvudstaden.",al={"vem är duthorian","duthorian rall bakgrund"}}},fx={["69ec335a"]={q="Varför skickar Brother Wilhelm dig till Duthorian Rall?",a="Brother Wilhelm hyser stor respekt för Duthorian Rall, en av ordens mest inflytelserika paladiner. Han har hört Duthorian tala väl om dina insatser och nämna att du är redo att sättas på prov, och vill helt enkelt se till att du tar vara på möjligheten. Att vägleda lovande noviser till fördjupad undervisning är hans plikt och stolthet som mentor i Goldshire.",al={"varför skickar wilhelm mig","brother wilhelms motiv","varför tala med duthorian rall"}}},fp="16,205,24.425.0,22.397.0,41.155.0,32.168.0,46.251.0,47.171.0,47.177.0,22.164.0"}
P.entries["quest:2999"] = {n="Tome of Divinity",s="Tome of Divinity är ett övergångsuppdrag för unga dvärgpaladiner i Dun Morogh. Brandur Ironhammer, paladintränaren i Ironforges Hall of Mysteries, skickar en novis uppför trappan för att tala med den ansedda paladintränaren Tiza Battleforge. Uppdraget markerar steget från grundläggande stridsträning till Holy Lights djupare andliga plikter och heliga eder.",h="Tome of Divinity är ett övergångsuppdrag för unga dvärgpaladiner i Dun Morogh.",kw={"brandur ironhammer","hall of mystics","ironforge","paladin","redemption","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Uppdraget markerar ögonblicket då en novis går från hård stridsövning till Holy Lights djupa andliga bördor och förbereder sig för prövningarna som ger kraften Redemption.",["race:Dwarf"]="Dvärgpaladiner förenar Holy Lights hängivenhet med Khaz Modans djupa traditioner av plikt och broderskap och hör kallelsen i Ironforges salar inne i berget."},sec={{t="Kallelsen till High Seat",b="Novisa paladiner tillbringar sina första dagar med att försvara Anvilmar och Kharanos mot troggs och frosttroll, men så småningom kräver deras plikter större hängivenhet. Brandur Ironhammer inser att en novis har visat prov på stridsdisciplin och råder henne eller honom att ta en paus från arbetet i de snöiga passen och söka vägledning en trappa upp i hans egen Hall of Mysteries i Ironforge. Där vakar äldre paladiner över ordens andliga mognad."},{t="Vägledning från Tiza Battleforge",b="Tiza Battleforge är en av de mest vördnadsvärda paladinerna bland Ironforges dvärgar. Det är hennes uppgift att undervisa noviser om Lightens verkliga bördor och gå bortom enkel svärdsfäktning och hammarsvingande för att lära ut medkänsla, rättvisa och självuppoffring. När du söker upp henne inleds den formella studien av Tome of Divinity, en helig process som ska ge en paladin förmågan att återuppväcka de stupade."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget leder unga dvärgpaladiner från deras tränare Brandur Ironhammer till den äldre paladinen Tiza Battleforge i Ironforge. Det är det första steget mot prövningarna som krävs för att studera Tome of Divinity och få kraften att återuppväcka de döda genom andlig kraft.",al={"vad gör det här uppdraget","början på tome of divinity","varför göra det här uppdraget"}},{q="Vem är Brandur Ironhammer?",a="Brandur Ironhammer är en dvärgpaladintränare som håller till i Hall of Mysteries i Ironforges Mystic Ward. Han ansvarar för de unga paladinerna där och skickar lovande noviser uppför trappan till Tiza Battleforge när de är redo för större heliga plikter.",al={"vem ger uppdraget","brandurs roll","brandur ironhammer bakgrund"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en respekterad veteranpaladin som finns en trappa upp i Hall of Mysteries i Ironforge. Hon vägleder yngre paladiner i vad Holy Light verkligen kräver av dem utöver stridsförmåga.",al={"var finns tiza","tiza battleforges roll","vem är tiza"}},{q="Vart leder uppdraget härnäst?",a="När du talar med Tiza Battleforge inleds de särskilda prövningarna i Tome of Divinity. Uppgifterna prövar en paladins hängivenhet, barmhärtighet och vilja att skydda och återställa liv i Lightens tjänst.",al={"nästa uppdrag","vad händer sedan","tome of divinity uppdragskedja"}},{q="Varför måste dvärgpaladiner söka upp Tome of Divinity?",a="För att kunna använda miraklet att återföra en fallen allierad till livet måste en paladin förstå sann osjälviskhet och andlig plikt. Tome of Divinity vägleder noviser genom de formella lektioner och trosprövningar som krävs för att kanalisera sådan mäktig helig kraft.",al={"varför tome of divinity","paladin återuppväckningsuppdrag bakgrund","redemption dvärg"}},{q="Får människor samma undervisning i Ironforge?",a="Mänskliga paladiner genomgår en motsvarande resa i Cathedral of Light i Stormwind i stället för i Ironforge. Den här särskilda kallelsen från Brandur Ironhammer till Tiza Battleforge är avsedd för dvärgar som tränar i Ironforge.",al={"kan människor göra detta","är det bara för dvärgar","människors tome of divinity"}}},fx={["1a85ab42"]={q="Varför skickar Brandur Ironhammer dig till Tiza Battleforge?",a="Brandur Ironhammer inser att din träning i Dun Morogh har förberett dig för större ansvar inom orden. I stället för att låta dig fastna i lokala bekymmer vill han att du går vidare i ditt kall. Bland dvärgpaladiner vördas Tiza Battleforge som en mentor som vägleder yngre noviser när de är redo att lära sig vad det Heliga Ljuset verkligen kräver av dem.",al={"varför skickar brandur dig","brandur ironhammers motiv","varför tala med tiza battleforge"}},["264c72ef"]={q="Varför måste du själv tala med Tiza i stället för att Brandur sköter det?",a="En paladins väg är djupt personlig och kan inte vandras genom ombud. Brandur Ironhammer kan vägleda dig i din tidiga stridsträning, men för att utvecklas andligt måste du själv infinna dig inför dina äldste. Tiza Battleforge måste bedöma din hängivenhet och beslutsamhet med egna ögon innan hon kan anförtro dig heliga läror som Tome of Divinity.",al={"varför jag tome of divinity","varför måste jag gå till tiza","varför går inte brandur"}}},fp="16,184,25.261.0,30.253.0,34.221.0,26.233.0,24.169.0,32.174.0,56.207.0,53.169.0"}
P.entries["quest:3000"] = {n="Tome of Divinity",s="Det här uppdraget leder dvärgpaladiner på resa tillbaka hem till Ironforge för att fortsätta sin heliga kallelse. Lord Grayson Shadowbreaker i Stormwind erbjuder uppdraget och visar de unga hjältarna till Tiza Battleforge, en av de mest respekterade lärarna i Hall of Mysteries. Hemkomsten markerar början på deras formella prövningar med Tome of Divinity.",h="Det här uppdraget leder dvärgpaladiner på resa tillbaka hem till Ironforge för att fortsätta sin heliga...",kw={"dvärgpaladin","hall of mysteries","ironforge","lord grayson shadowbreaker","mystic ward","återlösning","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Det här är en viktig övergångsrit för dvärgpaladiner och inleder deras väg mot att studera Tome of Divinity och bemästra gåvan att återuppväcka döda.",["faction:Alliance"]="Den gemensamma utbildningen och ömsesidiga respekten mellan Stormwinds paladiner och Ironforges mentorer visar den nära andliga alliansen mellan dvärgar och människor.",["race:Dwarf"]="Det här uppdraget knyter samman dina äventyr i människornas länder med din plikt mot Khaz Modan och kallar dig tillbaka till förfädernas hemvist i Ironforge för att tränas av dina egna äldste."},sec={{t="En kallelse hem",b="Dvärgpaladiner hjälper ofta kungariket Stormwind och färdas genom människornas områden, men deras andliga och militära rötter finns kvar i Khaz Modan. Lord Grayson Shadowbreaker märker när en dvärgs utbildning ute i fält har kommit tillräckligt långt och råder då dvärgen att återvända till Ironforges hjärta. Där vakar det egna folket över de djupa andliga plikter som förväntas av en fullvärdig riddare av Silverhanden."},{t="Hall of Mysteries",b="När paladinen återvänder till bergshuvudstaden hänvisas hen till Mystic Ward. Högt upp i Hall of Mysteries finns Tiza Battleforge. Hon är en vördad mentor för den yngre generationen dvärgpaladiner och förbereder dem på att bära den Heliga Ljusets börda genom de heliga prövningar som finns nedtecknade i Tome of Divinity."}},faq={{q="Varför skickar Lord Grayson Shadowbreaker mig tillbaka till Ironforge?",a="Lord Grayson inser att du har visat vad du går för ute i fält, men unga dvärgpaladiner förväntas lära sig den Heliga Ljusets djupare läror och genomgå dess prövningar under Tiza Battleforges ledning, direkt från sitt eget folk.",al={"varför åka till ironforge","varför skickar grayson iväg mig","varför besöka tiza"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en av Ironforges mest respekterade dvärgpaladiner. Hon håller till på övervåningen i Hall of Mysteries, där hon vägleder blivande paladiner och övervakar prövningarna som sätter deras hängivenhet till Ljuset på prov.",al={"tiza battleforge","vem är tiza","paladintränaren tiza"}},{q="Var hittar jag Tiza Battleforge?",a="Hon finns inne i Hall of Mysteries i Mystic Ward i Ironforge. Gå uppför trappan i helgedomen för att hitta henne.",al={"var finns tiza","tiza battleforges plats","hur hittar jag tiza"}},{q="Vad är Tome of Divinity?",a="Tome of Divinity innehåller de heliga lärorna och krävande prövningar som paladiner måste genomgå för att bemästra den Heliga Ljuset, särskilt kraften att återuppväcka döda och den osjälviska hängivenheten till fallna allierade.",al={"tome of divinity betydelse","vad är tome of divinity","paladinbok"}},{q="Kan människopaladiner göra den här versionen av uppdraget?",a="Nej. Den här kallelsen skickar särskilt dvärgpaladiner tillbaka till sina hemlandslärare, medan människopaladiner genomgår sina prövningar direkt under Lord Grayson Shadowbreaker och Duthorian Rall i Stormwind.",al={"kan människor göra det här","är uppdraget bara för dvärgar"}},{q="Vad händer när jag har rapporterat till Tiza Battleforge?",a="När du har presenterat dig för Tiza ger hon dig dina formella dvärgprövningar genom Tome of Divinity, där hon prövar om du är redo att använda Ljusets återlösande kraft.",al={"what comes next","nästa uppdrag efter tome of divinity","efter att ha pratat med tiza"}}},fx={c5356bb5={q="Varför väljer Lord Grayson Shadowbreaker mig till detta?",a="Lord Grayson ser din växande potential som paladin, men respekterar ditt folks särskilda traditioner. I stället för att undervisa dig helt inom Cathedral of Light i Stormwind vet han att unga dvärgpaladiner måste stå stadigt i sina egna äldstes läror. Han skickar dig hem eftersom det är dags för din nästa heliga rit, och Tiza Battleforge är den vördnadsvärda mentor som vägleder dvärgar genom detta andliga steg.",al={"varför jag tome of divinity","varför skickar grayson mig","varför dvärgpaladin"}}},fp="16,201,14.310.0,21.262.0,62.178.0,24.159.0,34.92.0,29.156.0,48.174.0,49.176.0"}
P.entries["quest:3001"] = {n="Seeking Strahad",s="Carendin Halgar skickar hordens häxmästare över Stora havet för att söka upp Strahad Farsan. Ovanför Ratchet erbjuder en mänsklig trollkarl en väg bortom grundläggande skuggmagi och mot den svåra konsten att åkalla en felhunter.",h="Carendin Halgar skickar hordens häxmästare över Stora havet för att söka upp Strahad Farsan.",kw={"the barrens","carendin halgar","felhunter","ratchet","seeking strahad","strahad farsan","tome of the cabal","undercity","krigsmagiker"},ang={["class:Warlock"]="Som häxmästare markerar detta en övergångsrit kring din trettionde kraftcirkel. Du lämnar bindningarna av mindre imps och voidwalkers bakom dig och vänder dig mot att befalla den rovgiriga felhuntern.",["faction:Horde"]="Som häxmästare i horden lägger du din vanliga fientlighet mot människor åt sidan och reser till neutrala Ratchet för att lära dig av en levande trollkarl.",["race:Undead"]="Som odöd är du en av de Fördömdas lärjungar som Carendin Halgar skickar från Undercity. Hans val visar att även Sylvanas lojala anhängare använder levande mästare för att utöka sin arsenal."},sec={{t="En mästare på andra sidan havet",b="Carendin Halgar, en tränare för de Fördömdas häxmästare i Undercitys Magic Quarter, vet när en lärling vuxit ifrån grundläggande undervisning. Han skickar sina elever bortom Lordaerons ruiner för att hitta Strahad Farsan. Halgar varnar för att Strahad är en levande människa, men ingen vekling, och säger åt dem att inte behandla honom som en fiende. För häxmästare korsar jakten på demoniskt mästerskap ofta gränser mellan folkslag och fraktioner."},{t="The Overlook vid Ratchet",b="Strahad håller till på klipporna ovanför Ratchet, goblinernas hamn i The Barrens. Nära ett vakttorn av sten blickar han ner på sjömännen, legoknektarna och köpmännen nedanför, vars saliga okunskap om Twisting Nether roar honom. Hordens häxmästare som når fram till honom kan bära misstro och pyrande hat i blicken. Strahad accepterar den råa illviljan som bränsle att forma till mörk auktoritet."}},faq={{q="Varför skickar en krigsmagiker från Undercity mig till en människa?",a="Häxmästare lägger ofta fraktionsmotsättningar åt sidan för att söka sällsynt och mäktig mörk kunskap. Carendin Halgar säger att Strahad Farsan har särskild behärskning av större demoniska åkallelser som Halgar inte kan lära ut. I jakten på demonisk kraft är en lärares kunskap viktigare än dennes härkomst.",al={"varför mänsklig tränare","varför skicka till en människa","carendin skickar till strahad"}},{q="Var befinner sig Strahad Farsan egentligen?",a="Strahad Farsan finns i The Barrens, på de höga klipporna ovanför goblinernas hamn Ratchet. Han står nära ett stentorn med utsikt över bukten och de livliga hamndockorna.",al={"strahads plats","var är strahad","hur hittar man strahad"}},{q="Vilken sorts kraft lär Strahad ut?",a="Strahad vägleder erfarna häxmästare genom de komplicerade ritualerna för att binda mäktigare demoner från Twisting Nether. Hans undervisning leder fram till de farliga prövningarna i att åkalla och befalla en felhunter.",al={"vad lär strahad ut","vad är uppdraget till för","felhunter-uppdrag"}},{q="Är Strahad allierad med Alliance?",a="Trots att Strahad är människa håller han till i goblinernas neutrala område i Ratchet och är inte ansluten till Grand Alliance. Han är en självständig utövare som fritt lär ut till horden och alliansens häxmästare som klarar hans undervisning.",al={"är strahad med i alliance","strahads fraktion","är strahad vänligt sinnad"}},{q="Vad händer när jag når Strahad?",a="När du anländer prövar Strahad din beslutsamhet och skickar dig att återfinna de utspridda fragmenten och komponenterna till Tome of the Cabal. Du söker vida omkring efter ritualen för att åkalla en felhunter.",al={"vad händer efter strahad","tome of the cabal","nästa uppdrag"}},{q="Varför välkomnar Strahad hat hos sina elever?",a="Demonisk magi livnär sig på starka känslor, dominans och viljestyrka. Hat kan fokuseras och tyglas, så att en åkallare kan binda kaotiska varelser från Nether innan de slukar någon som saknar självbehärskning.",al={"varför gillar strahad hat","hat i din blick"}}},fx={c0e56201={q="Varför skickar Carendin dig i stället för att själv bege sig dit?",a="Carendin Halgar tjänstgör som en kriglockementor i Undercity och vägleder noviser så långt hans undervisning räcker. Du har gått bortom de grundläggande konster han lär ut till nybörjare och visat dig redo för mäktigare besvärjelser. Det här är ingen diplomatisk resa, utan ett övergångsprov för din egen utveckling. Han skickar dig för att söka upp Strahad Farsan eftersom det är ditt eget herravälde över mörk magi som måste prövas och fördjupas.",al={"varför skicka mig för att söka strahad","varför går inte carendin själv","varför behöver carendin mig"}}},fp="15,203,23.389.0,23.379.0,50.293.0,40.162.0,38.207.0,36.229.0,36.207.0,48.209.0"}
P.entries["quest:3002"] = {n="The Gordunni Orb",s="Rok Orhan känner fienden väl, men är krigare och kan inte säga vad Gordunni Orb är kapabel till. Han känner till en magiker i Orgrimmar som kan berätta mer. Du får bära klotet till Uthel'nay, vid Darkbriar Lodge i Orgrimmar. Detta följer efter Dark Ceremony.",h="Rok Orhan känner fienden väl, men är krigare och kan inte säga vad Gordunni Orb är kapabel till.",kw={"darkbriar lodge","feralas","gordunni","gordunni orb","orgrimmar","rok orhan","uthel'nay"},sec={{t="Bortom en krigares kunskap",b="Efter Dark Ceremony håller Rok Orhan i klotet, men medger att han är krigare och inte kan säga vad det kan göra. Han känner till en magiker i Orgrimmar som kan berätta mer och skickar iväg dig med klotet för att hitta Uthel'nay vid Darkbriar Lodge."},{t="Uthel'nays dom",b="Uthel'nay tycker att klotet är fascinerande. Det är mycket kraftfullt, säger Uthel'nay, men också mycket farligt."}},faq={{q="Vem skickar dig till Uthel'nay?",a="Rok Orhan, när du väl har fått klotet som Dark Ceremony skickade dig att hämta.",al={"gordunni orb uppdragskedja","uppföljning till dark ceremony","förutsättningar för gordunni orb"}},{q="Varför undersöker Rok Orhan inte klotet?",a="Rok Orhan är krigare och kan inte säga vad klotet kan göra, men känner till en magiker i Orgrimmar som kan berätta mer.",al={"varför skicka klotet till orgrimmar","varför rok orhan lämnar ifrån sig klotet","varför uthel'nay"}},{q="Var finns Uthel'nay?",a="I Darkbriar Lodge i Orgrimmar.",al={"uthel'nays plats","var finns uthelnay","darkbriar lodge plats"}},{q="Vad kommer före The Gordunni Orb?",a="Dark Ceremony, där Rok Orhan skickade dig för att ta ett klot från en Gordunni magikerfurste.",al={"förutsättning för gordunni orb","föregående uppdrag till gordunni orb"}}},fp="16,252,28.248.0,19.98.1,27.65.0,39.116.0,19.36.0,35.84.0"}
P.entries["quest:301"] = {n="Report to Ironforge",s="Det här ärendet för en äventyrare från Thelsamar i Loch Modan till hjärtat av Ironforge med viktiga uppdateringar från Ironband's Excavation Site. När rapporten om utgrävningens framsteg lämnas till Prospector Stormpike i Assembly of Explorers inleds en utredning om saknat sprängkrut och arkeologiska utgrävningar som stannat av vid fotbergen.",h="Det här ärendet för en äventyrare från Thelsamar i Loch Modan till hjärtat av Ironforge med viktiga...",kw={"sprängkrut","explorers' league","ironband's compound","jern hornhelm","loch modan","prospector stormpike","rapport till ironforge","thelsamar"},ang={["faction:Alliance"]="Uppdraget visar hur långt Alliansens logistik når och knyter samman avlägsna forskningsläger i bergsdalarna med den militära och lärda ledningen i Ironforge.",["race:Dwarf"]="För dvärgar är det en välbekant övergångsrit i huvudstadens salar att navigera Explorers' Leagues byråkrati och hantera Stormpike-klanens legendariska humör."},sec={{t="En kurir åt ligan",b="Arkeologiska expeditioner i hela Khaz Modan är starkt beroende av finansiering, förnödenheter och tillsyn från Explorers' League. När Prospector Ironband's utgrävningsplats i södra Loch Modan får slut på sprängämnen kan hans överordnade inte bara beställa mer lokalt. Jern Hornhelm på värdshuset i Thelsamar anförtror en äventyrare uppgiften att bära Ironband's skriftliga rapport över bergspassen direkt till Prospector Stormpike vid ligans högkvarter."},{t="Stormpikes humör",b="Prospector Stormpike förkroppsligar den rättframma, hetlevrade beslutsamhet som kännetecknar hans klan. Han är stationerad i det storslagna biblioteket och Hall of Explorers i Ironforge och förväntar sig snabba, konkreta resultat från ligans utgrävningar. När Stormpike tar emot meddelandet blir han rasande över att Ironband inte redogör för en stor leverans sprängkrut som skickades för flera veckor sedan. Det visar att försörjningslinjerna i Loch Modan har drabbats av ett farligt avbrott."}},faq={{q="Varför måste rapporten hela vägen till Ironforge?",a="Explorers' League styr strikt fördelningen av värdefulla resurser som sprängkrut. Fältutgrävningar kan inte beställa farliga sprängämnen utan formellt tillstånd från seniora prospektörer vid högkvarteret i Hall of Explorers.",al={"varför åka till ironforge","varför lämna rapporten till stormpike","orsaken till rapporten i ironforge"}},{q="Vem är Prospector Stormpike?",a="Han är en högt uppsatt tjänsteman inom Explorers' League och har sin bas i Ironforge. Han tillhör den stolta Stormpike-klanen och är ökänd för sitt hetlevrade humör och sin otålighet med utgrävningar som står stilla och inventarier som saknas.",al={"vem är stormpike","prospector stormpikes bakgrund"}},{q="Vart tog Ironband's ursprungliga sprängkrut vägen?",a="En leverans sprängkrut skickades iväg flera veckor tidigare, men Ironband nämner inte att han någonsin tagit emot den. Det väcker genast farhågor om att troggar eller banditer överföll transportvagnen längs vägarna i Loch Modan.",al={"vad hände med sprängkrutet","saknat sprängkrut","var finns krutet"}},{q="Var hittar du Prospector Stormpike i Ironforge?",a="Prospector Stormpike finns i Assembly of Explorers, som också kallas biblioteket eller Hall of Explorers, i Ironforges nordöstra flygel.",al={"stormpikes plats","var är stormpike","assembly of explorers plats"}},{q="Vem ger dig rapporten i Thelsamar?",a="Jern Hornhelm, som håller till på Stoutlager Inn i Thelsamar, fungerar som förbindelselänk och samordnar rapporter och kommunikation mellan Ironband's avlägsna läger och stadens ledning.",al={"vem inleder rapport till ironforge","jern hornhelms roll"}},{q="Vad händer efter att Stormpike läst rapporten?",a="Stormpike är rasande över den oredovisade ammunitionen och de uteblivna framstegen. Han beordrar dig att ordna en ny leverans sprängkrut och föra den direkt tillbaka till Prospector Ironband.",al={"what comes next","nästa uppdrag efter rapport till ironforge"}}},fx={["601d3943"]={q="Varför vill Jern Hornhelm att rapporten skickas till Ironforge?",a="Prospector Ironbands utgrävning i Loch Modan har stannat av eftersom arbetslaget har fått slut på sprängpulver. Jern Hornhelm kan inte ensam begära in fler förnödenheter; han behöver formellt godkännande från Explorers' Leagues högkvarter i Ironforge. Att leverera lägesrapporten till Prospector Stormpike är det enda administrativa sättet att säkra en ny pulversändning och hålla utgrävningen igång.",al={"varför skicka rapport","jern hornhelms motiv","varför vill jern ha sprängpulver"}},["499fe615"]={q="Varför skickar Jern Hornhelm dig i stället för att själv åka?",a="Jern Hornhelm har fullt upp med logistiken i Thelsamar och med att stödja de lokala utgrävningarna. Dessutom är Prospector Stormpike ökänd för sitt häftiga humör när förseningar och motgångar uppstår. Genom att anförtro uppdraget åt ett utbytbart bud som får möta Stormpikes vrede slipper Jern sina överordnades direkta ilska och kan fokusera på arbetet här.",al={"varför skicka mig","varför åker han inte själv","varför behöver hornhelm mig"}}},fp="19,191,24.427.0,20.376.1,57.193.0,28.209.0,45.173.0,52.154.0,38.164.0,46.201.1"}
P.entries["quest:302"] = {n="Powder to Ironband",s="Powder to Ironband är ett leveransuppdrag för Alliansen som knyter ihop Explorer's Leagues högkvarter i Ironforge med Loch Modan. Efter att Prospector Stormpike gett sitt officiella godkännande skickas äventyrare till Thelsamar för att övervaka en viktig leverans av sprängkrut till Ironbands utgrävning.",h="Powder to Ironband är ett leveransuppdrag för Alliansen som knyter ihop Explorer's Leagues högkvarter i...",kw={"explorers league","huldar","ironforge","jern hornhelm","loch modan","powder to ironband","prospector stormpike","thelsamar"},ang={["faction:Alliance"]="Det är avgörande för Alliansens sammanhållning mellan Ironforge och de östra gränstrakterna att hålla Loch Modans färdvägar säkra.",["profession:Mining"]="Sprängkrut är ett oumbärligt verktyg i dvärgarnas hantverk, lika användbart för gruvarbetare som för utgrävare som vill spräcka den djupaste berggrunden.",["race:Dwarf"]="För dvärgar handlar det inte bara om logistik att säkra krut till utgrävningen. Det hjälper dem i det heliga arbetet med att avslöja sitt folks mystiska ursprung."},sec={{t="Byråkrati och sprängkrut",b="Arkeologiska utgrävningar i Khaz Modans berg kräver tung utrustning. När Prospector Ironbands expedition i södra Loch Modan fick slut på sprängmedel skickades bud till ledningen för League i Ironforge. Prospector Stormpike godkände snabbt begäran och instruerade budet att samordna med Jern Hornhelm i Thelsamar, dalens främsta logistiknav."},{t="En missad avfärd",b="Eftersom tidigare försörjningskonvojer genom The Loch hade försvunnit eller utsatts för trakasserier från lokala troggs beordrade Stormpike uttryckligen kuriren att personligen skydda krutvagnen. Men byråkrati och restid arbetar emot League. När en kurir kommer fram till Stoutlager Inn i Thelsamar har Jern Hornhelm redan skickat iväg vagnen under bevakning av Huldar och två dvärgiska bärare, så kuriren måste skynda nerför vägen för att hinna ikapp."}},faq={{q="Varför skickas sprängkrut till Ironband?",a="Prospector Ironband leder en viktig arkeologisk utgrävning för dvärgarna i södra Loch Modan. För att gräva fram begravda reliker måste man spränga sig genom tät berggrund, och hans grupp har gjort slut på sitt förråd samtidigt som angreppen från troggs tilltar.",al={"varför behövs krut","ironbands sprängkrut","vad används krutet till"}},{q="Vem är Prospector Stormpike?",a="Prospector Stormpike är en högt uppsatt officer i Dwarven Explorer's League och är stationerad i Hall of Explorers i Ironforge. Han granskar fältförfrågningar, godkänner viktig utrustning och sköter logistiken för större utgrävningsplatser i Khaz Modan.",al={"stormpikes roll","vem gav uppdraget"}},{q="Vem är Jern Hornhelm?",a="Jern Hornhelm är en kontakt för Explorers' League som är stationerad i Thelsamar i Loch Modan. Han förbereder förnödenheter och organiserar transportgrupper som ska ta sig in i dalens farligare gränstrakter.",al={"jern hornhelms plats","var finns jern hornhelm"}},{q="Varför begärdes en personlig eskort för leveransen?",a="Tidigare leveranser till utgrävningen nådde inte fram. Loch Modan är översvämmat av troggs som strömmar ner från kullarna och utgrävningsplatserna, och försörjningslederna längs huvudvägen har blivit allt farligare.",al={"varför eskortera krutet","troggangrepp på vagnar"}},{q="Vad händer när du kommer till Thelsamar?",a="Jern Hornhelm har redan skickat iväg vagnen med Huldar och bärarna Miran och Saean. Du måste följa den södra vägen och hinna ikapp dem innan något går fel.",al={"missade jag vagnen","var finns leveransen"}},{q="Hur passar uppdraget in i Explorer's Leagues berättelse?",a="Uppdraget fungerar som kurirlänk mellan den första begäran från utgrävningsplatsen, de centrala myndigheterna i Ironforge och fältet via Thelsamar, där expeditionens pågående utgrävning ska skyddas.",al={"ironbands uppdragskedja","utgrävningarnas uppdragskedja"}}},fx={["8773e6dd"]={q="Varför skickar Prospector Stormpike en äventyrare i stället för officiella vakter?",a="Prospector Stormpike arbetar från Hall of Explorers i Ironforge, där han fokuserar på administration och tillstånd snarare än att leda trupper. Tidigare sändningar med sprängpulver har redan fallit offer för faror längs vägarna i Loch Modan. Därför litar han på en skicklig resenär som ändå ska ut i fält och kan se till att Jern Hornhelms förnödenheter når utgrävningsplatsen säkert.",al={"varför skicka mig","varför inte skicka vakter till ironband","varför en äventyrare"}}},fp="18,229,31.302.0,18.311.1,46.177.0,28.223.0,21.171.0,52.164.0,42.152.1,61.174.0"}
P.entries["quest:3022"] = {n="Handle With Care",s="Curgle Cranklehop ger dig en låda med ägg och ber dig bära den till druiden Erelas Ambersky, som finns i Rut'theran, en liten by på Teldrassil.",h="Curgle Cranklehop ger dig en låda med ägg och ber dig bära den till druiden Erelas Ambersky, som finns i...",kw={"curgle cranklehop","erelas ambersky","hippogryffägg","rut'theran village","tanaris","teldrassil"},sec={{t="En låda med ägg",b="Curgle Cranklehop ger dig en omsorgsfullt packad låda med ägg. Det är hippogryffägg, och de ska till en druid vid namn Erelas Ambersky."},{t="Druiden i Rut'theran",b="Erelas Ambersky är en druid som tar hand om de här äggen. Han hjälper dem att kläckas och tränar sedan de unga hippogryferna. Rut'theran Village är en liten by i södra Teldrassil."}},faq={{q="Vad finns i lådan från Curgle Cranklehop?",a="Den omsorgsfullt packade lådan innehåller hippogryffägg.",al={"vad finns i lådan","innehåll i omsorgsfullt packad låda","vad bär jag på"}},{q="Vart ska lådan?",a="Lådan ska till druiden Erelas Ambersky i den lilla byn Rut'theran på Teldrassil.",al={"vart ska jag ta lådan","erelas amberskys plats","var ligger rut'theran village"}},{q="Vem är Erelas Ambersky?",a="Erelas Ambersky är en druid i Rut'theran Village. Han tar hand om hippogryffägg och tränar de unga hippogryferna när de har kläckts.",al={"vem är erelas","amberskys bakgrund","vem tar emot äggen"}}},fp="16,161,15.141.0,23.178.0,48.49.0,32.94.0,23.130.0"}
P.entries["quest:303"] = {n="The Dark Iron War",s="Vid Wetlands norra gräns leder Motley Garmason ett desperat försvar för att återta Dun Modr från Dark Iron-klanen. Efter att fiendens sabotörer sprängde Thandol Span och intog staden håller Ironforge Mountaineers en skör försvarslinje i väntan på förstärkningar som kanske aldrig kommer.",h="Vid Wetlands norra gräns leder Motley Garmason ett desperat försvar för att återta Dun Modr från Dark...",kw={"bronzebeard","dark iron","rivningsexperter","dun modr","ironforge","motley garmason","sabotörer","thandol span","wetlands"},ang={["faction:Alliance"]="Förstörelsen av Thandol Span och Dun Modrs fall skär av landvägen mellan Stormwinds norra allierade och de södra kungadömena.",["profession:Engineering"]="Dark Iron-sabotörernas precision när de använde specialiserade sprängämnen för att krossa uråldrigt dvärgstenarbete visar en skrämmande skicklighet i att rasera konstruktioner.",["race:Dwarf"]="För Bronzebeard-dvärgarna är förlusten av Dun Modr en bitter förödmjukelse och ett direkt hot mot Khaz Modans självständighet. De kräver hämnd på sina ärkefiender."},sec={{t="En front vid norra porten",b="Dun Modr var en gång Ironforges stolta fäste som vaktade Thandol Spans södra ände, den väldiga bron som förband Khaz Modan med Lordaeron. När Dark Iron-sabotörer och rivningsexperter sprängde brons valv skar de av Alliansens färdväg och övermannade snabbt fästet. Motley Garmason och en handfull överlevande försvarare lyckades dra sig tillbaka precis långt nog för att upprätta ett spaningsläger, men utan omedelbara motanfall riskerar hela den norra porten att för alltid hamna under Dark Irons välde."},{t="Vinna tid åt reserverna",b="Eftersom dvärgtrupper har skickats till avlägsna alliansslagfält har Motleys lilla styrka i stort sett lämnats åt sig själv. Hans spejare försöker kalla på hjälp från Ironforge, men kommunikationen har sviktat och de utlovade reserverna syns inte till. För att vinna tid och störa fiendens befästningar beordrar Motley riktade anfall rakt in i Dun Modrs ruiner, för att minska antalet Dark Iron-ingenjörer, tunnelgrävare och frontsoldater innan de kan tränga längre söderut in i Wetlands."}},faq={{q="Vem är Motley Garmason?",a="Motley Garmason är en officer bland Ironforge Mountaineers som leder resterna av Dun Modrs garnison. Från en postering strax utanför den ockuperade staden samordnar han spaning och gerillaanfall mot Dark Iron-styrkorna som ockuperar området.",al={"motley garmason","vem är motley","dun modrs befälhavare"}},{q="Varför är Dun Modr så viktigt för Ironforge?",a="Dun Modr vaktar Thandol Spans södra fäste. Som den enda landvägen mellan Khaz Modan, Arathi Highlands och norra Lordaeron kontrollerar den som håller Dun Modr i praktiken all marktrafik och försörjning mellan regionerna.",al={"varför dun modr är viktigt","dun modrs betydelse","dun modrs historia"}},{q="Varför strider Dark Iron-dvärgar i Wetlands?",a="Dark Iron-klanen har länge försökt underminera sina kusiner av Bronzebeard-släkten och försvaga Alliansen. Genom att invadera Wetlands och förstöra Thandol Span skär de av Ironforges försörjningslinjer norrut och öppnar en fientlig andra front bakom Alliansens gränser.",al={"varför är dark iron här","dark iron i wetlands","orsaken till dark iron-kriget"}},{q="Vad hände med Thandol Span?",a="Dark Iron-tunnelgrävare och rivningsexperter placerade stora mängder sprängämnen i Thandol Spans grundvalv och skadade bron svårt. Syftet var att skära av Ironforges förstärkningar från Lordaeron innan de intog Dun Modr.",al={"thandol span förstörd","vem sprängde bron","explosionen vid thandol span"}},{q="Var är Ironforges reservstyrkor?",a="Ironforges militär är hårt pressad av flera fälttåg utomlands och försvaret på hemmaplan. Garmasons spejare Roggo har haft svårt att få tillförlitlig kontakt med högsta befälet, så utposten i Dun Modr håller linjen med de lokala allierade de kan hitta.",al={"ironforges reserver","var är förstärkningarna","roggos reservstyrka"}},{q="Vad händer efter att Dark Iron drivits tillbaka i Dun Modr?",a="När fotsoldaterna och sabotörerna rensats undan har ni vunnit dyrbar tid, men Roggos underrättelser avslöjar att Kam Deepfury, som hålls i Stormwind Stockade, hjälpte till att planera anfallet mot Thandol Span. Motley ber dig hämta Deepfurys huvud.",al={"nästa uppdrag efter dark iron war","uppdraget the fury runs deep","vad följer efter dark iron war"}}},fx={["07a4003e"]={q="Varför vill Motley Garmason få det här gjort?",a="Motley vill desperat återta Dun Modr och hejda Dark Irons framryckning in i Wetlands innan Ironforges territorium går helt förlorat. Dark Irons har redan sprängt Thandol Span i bitar och tagit över staden, vilket brutit de viktiga förbindelserna norrut. Motley hoppas att han genom omedelbara angrepp mot deras linjer kan hålla fronten tills förstärkningar från Ironforge anländer och driver tillbaka dem för gott.",al={"motley garmasons motiv","varför bekämpa dark irons","varför rensa dun modr"}},b2f42bee={q="Varför behöver Motley Garmason din hjälp i stället för sina egna trupper?",a="Ironforges stående armé är hårt pressad och strider långt hemifrån i främmande länder för Alliansens räkning. Efter Thandol Span och Dun Modrs fall lämnades Motley med bara en handfull försvarare och inga färska soldater till hands. Hans spejare lyckas inte kalla in reserverna, så han har inget annat val än att förlita sig på skickliga resenärer som du för att fortsätta striden.",al={"varför behöver motley mig","varför strider inte vakterna","var är ironforges trupper"}}},fp="17,273,28.416.0,28.485.0,23.213.0,42.249.0,51.260.0,34.234.0,39.232.0,59.231.1"}
P.entries["quest:304"] = {n="A Grim Task",s="Efter Dark Irons förödande angrepp på Dun Modr och Thandol Span söker Longbraid the Grim hämnd för fallna fränder och förlorade soldater. Han ger modiga resenärer i uppdrag att spåra upp och döda den svårfångade Dark Iron-häxmästaren Balgaras the Foul och ta hans öra som bevis.",h="Efter Dark Irons förödande angrepp på Dun Modr och Thandol Span söker Longbraid the Grim hämnd för fallna...",kw={"a grim task","balgaras the foul","dark iron","dun modr","longbraid the grim","roggo","thandol span","wetlands"},ang={["class:Warlock"]="Balgaras the Foul använder ondskefull magi från kaos för att organisera massakern på Dun Modrs försvarare. Det visar hur farliga ändamål Dark Irons använder sina färdigheter till.",["faction:Alliance"]="Thandol Span är den främsta landvägen mellan Khaz Modan och Lordaeron. Därför är det av högsta strategiska vikt för hela Alliansen att undanröja Dark Iron-sabotörer.",["race:Dwarf"]="För Ironforges dvärgar är Dark Iron-klanens svek och våld i Dun Modr en personlig skymf och ett nytt sår i den långa inbördes striden mellan klanerna."},sec={{t="Dun Modrs ruiner",b="I norra Wetlands har Mountaineers of Ironforge utkämpat hårda strider mot infiltratörer från Dark Iron-klanen. Under belägringen intogs staden Dun Modr och Thandol Spans västra bro krossades. Longbraid the Grim förlorade många trogna soldater i angreppet, liksom sin egen bror, och är fast besluten att fienden ska få betala med samma mynt."},{t="En feg befälhavare",b="Spaning utförd av spejare som Roggo visade att Dark Iron-styrkan som ockuperar Dun Modr leds av en häxmästare vid namn Balgaras the Foul. I stället för att möta sina fiender öga mot öga hukar Balgaras i gömställen medan han beordrar sina soldater att utföra hans mörka planer. Longbraid hoppas att Balgaras fall ska bryta ryggen på Dark Iron-styrkan, så att Ironforges överlevande kan säkra den viktiga passagen norrut."}},faq={{q="Vem är Balgaras the Foul?",a="Balgaras the Foul är en Dark Iron-häxmästare som leder styrkorna som ockuperar Dun Modr i norra Wetlands. Longbraid the Grim kallar honom feg. Han undviker direkt strid och skickar i stället horder av Dark Iron-soldater för att hålla regionen.",al={"balgaras","vem är balgaras","dark iron-ledare dun modr"}},{q="Vem är Longbraid the Grim?",a="Longbraid the Grim är en dvärgbefälhavare som slagit läger utanför ruinerna av Dun Modr. Han förlorade sin bror och många soldater när Dark Iron-styrkor intog bosättningen och förstörde den västra övergången vid Thandol Span.",al={"longbraid","longbraid the grim","uppdragsgivare dun modr"}},{q="Varför vill Longbraid ha Balgaras öra?",a="Balgaras är ett svårfångat mål som ofta gömmer sig för öppna strider. Därför kräver Longbraid ett konkret bevis på häxmästarens död, så att hotet verkligen är undanröjt.",al={"varför örat","ear of balgaras"}},{q="Vad hände med Thandol Span?",a="Dark Iron-dvärgar förstörde Thandol Spans västra bro under sitt överraskningsanfall mot Dun Modr och stängde därmed av en viktig väg mellan Wetlands och Arathi Highlands.",al={"thandol span-bron förstörd","varför är thandol span trasig"}},{q="Var gömmer sig Balgaras?",a="Balgaras håller sig gömd bland de erövrade befästningarna och ruinerna kring Dun Modr. Han gömmer sig bakom sina soldater i stället för att ge sig ut i de öppna träsken.",al={"var är balgaras","hitta balgaras"}},{q="Vad händer när Balgaras har dödats?",a="När Balgaras är död tror Longbraid att det blir mycket lättare att slå tillbaka de kvarvarande, oorganiserade Dark Iron-soldaterna innan en ny befälhavare anländer med förstärkningar.",al={"efter a grim task","vad händer sen i dun modr"}}},fx={["7a4e9943"]={q="Varför vill Longbraid the Grim få Balgaras dödad?",a="Longbraid förlorade många soldater i slaget om Dun Modr, däribland sin egen bror, som omkom när Dark Iron-dvärgarna krossade Thandol Spans västra bro. Balgaras leder de fientliga Dark Iron-styrkorna i Wetlands och beordrar anfall medan han själv håller sig trygg bakom sina undersåtar. Genom att avrätta häxmästaren vill Longbraid hämnas sina stupade släktingar och soldater, bryta upp Dark Iron-styrkans befälsordning och ge de överlevande ro i sinnet.",al={"varför döda balgaras","longbraids motiv","varför vill longbraid få det gjort"}}},fp="11,245,21.323.0,20.300.0,25.220.0,26.210.0,39.117.0,34.179.0,25.130.0,37.145.0"}
P.entries["quest:305"] = {n="In Search of The Excavation Team",s="Uppdraget In Search of the Excavation Team börjar med Tarrel Rockweaver i Wetlands, som är förtvivlad över att hans hustru Merrin plötsligt slutat höra av sig. Hon har fått i uppdrag att arbeta vid den ansedda Whelgar Excavation Site i öster och har missat två veckors regelbundna brev. Tarrel fruktar att en katastrof har drabbat expeditionen. Resenärer får i uppdrag att ge sig ut i träsket, hitta utgrävningsplatsen och ta reda på om hon är i säkerhet.",h="Uppdraget In Search of the Excavation Team börjar med Tarrel Rockweaver i Wetlands, som är förtvivlad över...",kw={"explorers league","in search of the excavation team","longbraid","merrin rockweaver","tarrel rockweaver","wetlands","whelgar excavation"},ang={["faction:Alliance"]="Det är viktigt att upprätthålla dvärgarnas fästen och forskningsexpeditioner i träskmarkerna för att skydda Wetlands mot vildmarkens växande faror.",["race:Dwarf"]="Explorers' League är mycket stolta över att gräva fram forntida historia. Därför är nödropet från släktingarna vid Whelgar Excavation en brådskande angelägenhet för varje kringvandrande dvärg."},sec={{t="En makes fruktan",b="Tarrel Rockweaver är stationerad i Wetlands våta vidder och väntar sig regelbundna brev från sin hustru Merrin. Merrin arbetar vid dvärgarnas utgrävning Whelgar Excavation Site och har brukat skicka veckovisa rapporter om arbetet. När två hela veckor går utan ett enda ord blir Tarrel övertygad om att en olycka har drabbat lägret. Dvärgarnas myndigheter har fullt upp, så han förlitar sig på förbipasserande spejare som vågar sig ut bland träskets faror för att se om grävarna fortfarande lever."},{t="Whelgarutgrävningen",b="Whelgar Excavation Site är ett typiskt dvärgprojekt för att gräva fram forntida Titanreliker och Titanernas historia, begravd i Wetlands gyttja. Men utgrävningar i förhistoriska jordlager ute i vildmarken utsätter ofta arbetslagen för vilda bestar och fientliga hot under jord. För att nå platsen måste du bege dig österut, långt från huvudvägarnas relativa trygghet. Vad som än avbröt grävarnas brevskrivande finns fortfarande kvar där."}},faq={{q="Vem är Tarrel Rockweaver?",a="Tarrel Rockweaver är en orolig dvärg i Wetlands. Han är förskräckt över att hans hustru Merrin plötsligt slutat skriva från utgrävningsplatsen i öster. När äventyrare passerar tror han att de är officiella spejare som skickats för att undersöka varför lägret tystnat.",al={"tarrel rockweaver","uppdragsgivare","vem ger uppdraget in search of the excavation team"}},{q="Vem är Merrin Rockweaver?",a="Merrin Rockweaver är en dvärgarkeolog som arbetar med Whelgar Excavation-teamet öster om Menethil Harbor i Wetlands. Hon brukade skriva regelbundet till sin make, tills en oväntad händelse plötsligt bröt kontakten.",al={"merrin rockweaver","tarrels hustru","vem är merrin"}},{q="Var ligger Whelgar Excavation Site?",a="Whelgar Excavation Site ligger öster om Menethil Harbor och sydväst om Dun Modr i Wetlands, bland klippiga höjder långt från huvudvägen.",al={"utgrävningsplatsens läge","var hittar man merrin","var ligger whelgar excavation"}},{q="Varför slutade Merrin skicka brev?",a="Tystnaden från utgrävningsplatsen berodde på ett hot som började visa sig där och isolerade dvärgforskarna från de vanliga kurirvägarna och lägrets vardagsliv.",al={"varför slutade breven komma","vad hände med utgrävningsteamet","varför kommer ingen post"}},{q="Vem är ”Longbraid” som Tarrel nämner?",a="Longbraid är en dvärgisk myndighetsperson som lovade att skicka spejare för att kontrollera Whelgar Excavation-teamet om kontakten bröts. Därför antar Tarrel att alla dugliga äventyrare som kommer för att hjälpa till har skickats på Longbraids order.",al={"vem är longbraid","longbraids spejare"}},{q="Är det säkert att närma sig utgrävningsplatsen?",a="Nej. Platsen ligger i Wetlands farliga vildmark, och det som störde teamets veckorapporter utgör en aktiv fara för alla som kommer till utgrävningen.",al={"är utgrävningen säker","farliga whelgar"}}},fx={d2e8931d={q="Varför behöver Tarrel Rockweaver en äventyrare som letar reda på utgrävningslaget?",a="Tarrel är förtvivlad i Menethil Harbor, men han är ingen beväpnad upptäcktsresande eller soldat som kan ta sig ensam genom de farliga träskmarkerna. Lokala ämbetsmän som Longbraid lovade att ordna en erfaren spejare för att undersöka tystnaden från utgrävningsplatsen. När du dyker upp ser Tarrel dig som den kapabla hjälp han utlovats, någon som vågar sig ut i vildmarken och ser till hans fru.",al={"varför skicka mig","varför inte vakter","varför kan inte tarrel åka"}}},fp="32,176,17.330.0,15.286.0,25.204.0,25.196.0,37.142.0,36.124.0,43.200.0,40.155.0"}
P.entries["quest:306"] = {n="In Search of The Excavation Team",s="Det här ärendet förmedlar bud om en katastrofal dinosaurieattack vid Whelgar's Excavation Site till Menethil Harbor. Merrin Rockweaver skriver ett hastigt brev för att lugna sin orolige make Tarrel och berättar hur expeditionen blev övermannad.",h="Det här ärendet förmedlar bud om en katastrofal dinosaurieattack vid Whelgar's Excavation Site till Menethil...",kw={"utgrävning","menethil harbor","merrin rockweaver","spräckliga rovfåglar","ormer","tarrel rockweaver","wetlands","whelgar"},ang={["faction:Alliance"]="Försörjningsvägarna och gränsprojekten i Wetlands är fortfarande farligt utsatta för vilda bestar, så resande från Alliansen måste ständigt vara på sin vakt.",["race:Dwarf"]="Katastrofen vid utgrävningen slår hårt mot dvärgarnas arkeologiska ambitioner och visar vilka faror kung Magnis upptäcktsresande möter långt från tryggheten i Ironforge."},sec={{t="Ett meddelande från ruinerna",b="Efter att ha hittat resterna av utgrävningsteamet, som hukar nära höjden med utsikt över utgrävningsplatsen, ger Merrin Rockweaver en hastig rapport. Det visade sig vara dödligt att gräva fram sällsynta artefakter tillsammans med väldiga förhistoriska fossil när flockar av lokala spräckliga rovfåglar svärmade över grävarna. Det plötsliga anfallet lämnade större delen av besättningen död och de överlevande avskurna från civilisationen."},{t="En bitter lättnad",b="Återkomsten till Menethil Harbor ger Tarrel Rockweaver en dyster tröst. Vetskapen om att hans hustru och minst två följeslagare överlevde tack vare en försvarare vid namn Ormer stillar hans oro, även om massakern på så många kollegor tynger stadens gränsbygdsanda."}},faq={{q="Vad hände med utgrävningsteamet i Wetlands?",a="När den dvärgiska expeditionen grävde fram sällsynta artefakter och väldiga uråldriga ben blev den överrumplad och övermannad av revirhävdande spräckliga rovfåglar. De flesta grävarna dödades, och bara en handfull överlevande blev kvar på klipporna ovanför utgrävningsplatsen.",al={"vad hände med utgrävningsplatsen","utgrävningskatastrofen i wetlands","varför misslyckades utgrävningen"}},{q="Vem räddade Merrin Rockweaver?",a="Merrin ger en modig försvarare vid namn Ormer äran för att ha kämpat bort rovfåglarna och eskorterat henne och prospektören till relativ säkerhet uppe på höjden när den nedre platsen föll samman.",al={"vem räddade merrin","ormer rockweaver","vem är ormer"}},{q="Vem är Tarrel Rockweaver?",a="Tarrel Rockweaver är Merrins make och är stationerad i Menethil Harbor. Orolig över att inga livstecken kom från utgrävningsplatsen sökte han resande som kunde undersöka var hon befann sig.",al={"vem är tarrel","var finns tarrel rockweaver"}},{q="Var ligger utgrävningsplatsen?",a="Utgrävningsplatsen ligger inåt land i Wetlands, öster om Menethil Harbor och sydväst om Dun Modr.",al={"var ligger utgrävningen","whelgars utgrävningsplats"}},{q="Vad grävde expeditionen efter?",a="Under dvärgiska prospektörers ledning grävde teamet efter sällsynta underjordiska artefakter och stora förhistoriska fossil begravda i träskmarkerna.",al={"vad grävde de efter","utgrävningsartefakter"}},{q="Finns det andra överlevande än Merrin?",a="Ja, Merrin nämner att Ormer och chefsprospektören lyckades fly från rovfåglarna tillsammans med henne. Det innebär att det finns tre kända överlevande.",al={"vilka andra överlevde","överlevande från utgrävningen"}}},fx={["2f0bde8f"]={q="Varför vill Merrin Rockweaver att du ska lämna över hennes brev?",a="Merrin vill lugna sin make Tarrel och berätta att hon överlevde det brutala anfallet mot utgrävningsplatsen. Rovfåglarna översvämmade lägret och slaktade många av arkeologerna, vilket lämnade Merrin, Prospector Whelgar och Ormer instängda i ett provisoriskt skydd. Eftersom de inte själva kan slå sig igenom odjuren anförtror hon dig brevet, så att Tarrel får veta att de lever och förstår expeditionens dystra öde.",al={"varför lämna merrins brev","merrin rockweavers motiv","varför lämna meddelandet till tarrel"}},f4e86a28={q="Varför kan inte Merrin Rockweaver själv lämna över meddelandet?",a="Merrin och de andra överlevande är avskurna och fast under angrepp från aggressiva fläckiga rovfåglar. Om de lämnade skyddet skulle de utsätta sig för de vildsinta bestarna som redan gett sig på resten av utgrävningslaget. Som en frisk och stark resenär som kan ta sig genom träskmarkerna och rovfågelsflockarna kan du tryggt föra besked till Menethil Harbor, vilket de själva inte kan.",al={"varför behöver merrin mig","varför kan inte merrin lämna utgrävningen","varför behöver merrin hjälp"}}},fp="32,194,24.315.0,15.237.0,53.201.0,28.122.0,25.163.0,30.99.0,36.148.0,40.95.0"}
P.entries["quest:3062"] = {n="Dark Heart",s="Talo Thornhoof i Camp Mojache vill ha det mörka hjärtat från Edana Hatetalon, harpyornas drottning i ruinerna västerut vid Northspring. Talo kallar henne ren ondska.",h="Talo Thornhoof i Camp Mojache vill ha det mörka hjärtat från Edana Hatetalon, harpyornas drottning i ruinerna...",kw={"camp mojache","mörkt hjärta","edana hatetalon","feralas","harpy","hatetalon-stenarna","northspring","talo thornhoof"},sec={{t="Harpyornas drottning",b="Edana Hatetalon är harpyornas drottning och härskar över Northspring-kullen i ruinerna västerut. Talo kallar henne ren ondska, utan andra känslor än hat mot alla, och har hört att hennes hjärta är av kristall. Talo vill att du möter henne och tar med hennes mörka hjärta tillbaka, för hatet hon sprider måste stoppas."},{t="En kallelse",b="Talo har hört talas om ett horn som harpyorna bär. Det sägs locka fram drottningen om man blåser i det nära Hatetalon-stenarna, uppe i ruinernas norra del. Talo njuter av tanken på att hennes släktingar inte ska svara, utan att hon ska möta sin död."},{t="När du återvänder",b="Talo är nu säker på att Edana är borta för gott och säger att hjärtat ska bevaras till minne av det du gjorde."}},faq={{q="Vem är Edana Hatetalon?",a="Hon härskar över Northspring-harpyorna i ruinerna västerut. Talo kallar henne ren ondska och säger att hon bara känner hat. Han har hört att hennes hjärta är av kristall.",al={"edana hatetalon","harpyernas drottning feralas","vem är harpyernas drottning"}},{q="Hur kan Edana Hatetalon lockas fram?",a="Talo har hört att harpyor bär ett horn, och att drottningen kan kallas fram om man blåser i det nära Hatetalon-stenarna vid ruinernas norra ände.",al={"hur man lockar fram edana","blåsa i horn feralas","hatetalon-stenarna"}},{q="Vem ger uppdraget att jaga Edana Hatetalon?",a="Talo Thornhoof i Camp Mojache.",al={"vem ger mörkt hjärta","talo thornhoof","var man får mörkt hjärta"}},{q="Varför vill Talo Thornhoof ha Edanas hjärta?",a="Talo vill få slut på hatet Edana sprider över landet och ber dig hämta hennes mörka hjärta.",al={"varför mörkt hjärta","talo thornhoofs motiv"}}},fp="10,170,15.315.0,9.230.0,14.107.1,23.148.0,36.142.0,39.32.0,43.89.0"}
P.entries["quest:3063"] = {n="Vengeance on the Northspring",s="Talo Thornhoof var en gång en erfaren jägare som inte fruktade någon varelse, tills harpyor överföll Talo i skogen. Hatet har kokat inom Talo sedan dess, och Talo ber dig hämnas på Northspring-harpyorna västerut.",h="Talo Thornhoof var en gång en erfaren jägare som inte fruktade någon varelse, tills harpyor överföll Talo i...",kw={"feralas","harpyor","northspring","hämnd","roguefeather","slayer","talo thornhoof","windcaller"},sec={{t="En gammal jägares agg",b="Talo minns tiden som erfaren jägare, då ingen levande varelse ingav fruktan. En dag i skogen, medan Talo vässade ett vapen efter en hård strid, omringades Talo av harpyor. Talo släpade sig nätt och jämnt i säkerhet, hör fortfarande deras skrin eka och blev aldrig sig lik igen. Alla dessa år senare kokar hatet fortfarande, och Talo vill ha hämnd."},{t="Northspring-harpyorna",b="Northspring-harpyorna håller till västerut. Talo vill att du dödar fyra av varje sort: Northspring Harpies, Roguefeathers, Windcallers och Slayers. Deras vingar är svarta som natten, varnar Talo, och de kan smita undan in i mörkret."},{t="Efter jakten",b="Talo tackar dig med en gammal taurens röst och säger att du har skänkt ett bekymrat sinne ro."}},faq={{q="Vem är Talo Thornhoof?",a="En erfaren jägare förr i tiden, som inte fruktade någon varelse förrän harpyor överföll Talo i skogen. Talo blev aldrig sig lik igen.",al={"talo thornhoof berättelse","vem ger uppdraget vengeance on the northspring","talo feralas"}},{q="Var håller Northspring-harpyorna till?",a="Väster om Talo Thornhoof.",al={"northspring-harpyornas plats","var finns northspring-harpyorna","harpyornas plats i feralas"}},{q="Varför vill Talo hämnas på harpyorna?",a="Harpyor överföll Talo i skogen och omringade Talo medan Talo vässade ett vapen efter en strid. Talo kom nätt och jämnt undan. Talo blev aldrig sig lik igen, och hatet kokar fortfarande inom Talo.",al={"varför döda northspring-harpyorna","talo thornhoofs bakgrund","varför talo hatar harpyor"}},{q="Vilka harpyor vill Talo döda?",a="Fyra av varje sort: Northspring Harpies, Northspring Roguefeathers, Northspring Windcallers och Northspring Slayers.",al={"målen i vengeance on the northspring","vilka harpyor ska dödas","northspring-harpyornas typer"}},{q="Hur ser Northspring-harpyorna ut?",a="Talo säger att deras vingar är svarta som natten och varnar för att de kan försvinna in i mörkret.",al={"harpyornas utseende","northspring-harpyornas vingar"}}},fp="28,228,22.338.0,23.229.0,14.91.1,22.132.0,42.30.0,47.174.0,36.113.0,42.91.0"}
P.entries["quest:3065"] = {n="Simple Tablet",s="I Valley of Trials skickar en märkt pergamentrulle dig till Frang när du har bevisat dig mot traktens bestar. Krigartränaren väntar utanför The Den.",h="I Valley of Trials skickar en märkt pergamentrulle dig till Frang när du har bevisat dig mot traktens bestar.",kw={"durotar","frang","gornek","simple tablet","the den","valley of trials","krigare"},ang={["class:Warrior"]="Som krigare markerar den här kallelsen ditt allra första steg på krigarens väg i Durotar. Frang lär dig grundläggande ställningar och slag.",["faction:Horde"]="Som medlem av Horden ansluter du dig till den stadiga strömmen av härdade frontkämpar som skickas för att säkra Durotars osäkra gränser mot kentaurer, quilboarer och mänskliga inkräktare.",["race:Troll"]="Som ett Darkspear-troll under träning i dalen kanske du får höra Frangs kärva kommentarer om att du föredrar spjut framför orchiska yxor. Han respekterar allt som dödar."},sec={{t="En kallelse till vapen",b="När du har visat att du kan möta Mottled Boars räcker Gornek över en pergamentrulle som är särskilt märkt för dig. Durotar är hårt, och Horden vägleder snabbt sina krigare. Pergamentrullen visar vägen till Frang, den erfarne krigartränaren utanför The Den."},{t="I The Dens skugga",b="Frang söker skydd i skuggan utanför The Den och ser rekryterna anlända från det röda busklandet. Med ett tränat öga bedömer han varje nyanländ innan han lär ut grunderna, oavsett om det gäller en tung yxa eller ett spjut. Han förbereder varje rekryt på att försvara den unga Hordens bräckliga bosättningar."}},faq={{q="Vad är Simple Tablet?",a="Simple Tablet vägleder unga krigare i Valley of Trials till Frang, krigartränaren som håller till där.",al={"simple tablet","vad är den här tabletten","krigarens anteckning"}},{q="Vem skickar tabletten?",a="Frang förmedlar budskapet. Den erfarne krigartränaren vilar utanför The Den och spanar efter nya kämpar.",al={"vem skrev tabletten","vem skickade simple tablet"}},{q="Var hittar jag Frang?",a="Frang väntar utanför The Den i Valley of Trials, skyddad från ökensolen under klippöverhäng.",al={"var finns frang","var är frang","hitta krigarinstruktören"}},{q="Varför nämner Frang spjut och yxor?",a="Frang medger att Hordens rekryter använder olika stridsstilar. Orcher föredrar tunga huggvapen som tvåhandsyxor, medan troll och andra kämpar ofta väljer spjut och lättare stångvapen; båda fungerar väl i strid.",al={"frangs uttalande om spjut","varför spjut"}},{q="Får andra klasser det här uppdraget?",a="Nej. Krigare får Simple Tablet, medan andra klasser inte får den och i stället hänvisas till sina egna mentorer genom en pergamentrulle, runa eller skriftrulle.",al={"är simple tablet bara för krigare","klassuppdrag i valley of trials"}},{q="Vad används The Den till?",a="The Den är ett skyddat grottkomplex i Valley of Trials där instruktörer, förråd och rekryter samlas för att komma undan den brännande hettan och kringströvande bestar.",al={"vad är the den","the den i durotar"}}},fp="13,152,17.255.0,26.288.0,26.103.0,21.109.0,23.106.0,39.215.0,32.148.0,31.164.0"}
P.entries["quest:307"] = {n="Filthy Paws",s="Filthy Paws är ett uppdrag från Mountaineer Stormpike där du ska hämta värdefull utrustning från det angripna Silver Stream Mine. Gruvan hade tömts på malm och gjordes om till ett förråd av Miners' League, innan framryckande kobolder tog över gångarna. Dvärgarnas myndigheter vill få tillbaka sina tåliga verktyg innan Mountaineers inleder en förödande utrensning av platsen.",h="Filthy Paws är ett uppdrag från Mountaineer Stormpike där du ska hämta värdefull utrustning från det angripna...",kw={"filthy paws","kobold","loch modan","gruvarbetarnas utrustning","miners' league","mountaineer stormpike","silver stream mine","thelsamar"},ang={["faction:Alliance"]="Dvärgarnas försvarsstyrkor är hårt ansatta i Khaz Modan, så när förråd säkras hålls viktig infrastruktur öppen för Alliansen.",["profession:Mining"]="Gruvarbetare förstår värdet av förstklassig dvärgutrustning och tragedin i att låta fungerande verktyg rosta bland grottodjurens tassar.",["race:Dwarf"]="För dvärgar är det en förolämpning att se grovhuggna kobolder vanhelga Miners' Leagues hantverk. Det kräver ett snabbt återtagande och skarpt stål."},sec={{t="Ett tömt förråd",b="Silver Stream Mine ligger gömd bland kullarna i norra Loch Modan, öster om Algaz Station, och gav sin sista silveråder för länge sedan. I stället för att överge det underjordiska komplexet gjorde dvärgarnas Miners' League om de torra schakten till ett säkert förråd för extra grävutrustning, hackor och material för arbetsplatser. Tåliga underjordiska gångar blir naturliga lagerutrymmen i Khaz Modan, så länge de hålls bemannade och låsta mot vildmarken."},{t="Tassar i förrådet",b="Dvärgarnas vaksamhet har avtagit i Loch Modan, och kobolderna har passat på att infiltrera schakten. De lockades av de mörka gångarna och de glänsande järnverktygen som lämnats kvar, och skadedjuren gjorde snabbt platsen till sitt näste. Mountaineer Stormpike vill gärna leda en grupp krigare in i gångarna för att utrota dem, men tunga stövlar och svepande hugg skulle krossa lådorna. En äventyrare måste smyga eller kämpa sig in och hämta ligans förråd innan det fullskaliga anfallet börjar."}},faq={{q="Varför lämnades utrustning i gruvan om malmen redan var slut?",a="Miners' League gjorde om Silver Stream Mine till ett centraliserat förråd när malmen tog slut. Dvärgarnas underjordiska gångar ger stadiga, torra skydd där skrymmande verktyg och förråd kan lagras tills de behövs någon annanstans.",al={"varför finns utrustning i silver stream mine","varför finns verktyg i gruvan","miners' league-förråd"}},{q="Varför röjer inte Mountaineer Stormpike gruvan själv?",a="Stormpike har fått order om att vänta. Dessutom vill Miners' League få ut sin utrustning först; väktare som stormar in i de trånga, mörka schakten skulle lätt kunna slå sönder de ömtåliga verktygen i lådorna mitt i striden.",al={"varför ger sig stormpike inte av","varför väntar mountaineers","orsaken till stormpikes uppdrag"}},{q="Var ligger Silver Stream Mine?",a="Gruvan ligger i norra Loch Modan, öster om Algaz Station och sydväst om Stonewrought Dam.",al={"silver stream mines läge","var ligger silver stream mine","var utspelar sig filthy paws"}},{q="Varför är kobolder så intresserade av dvärgverktyg?",a="Kobolder är tvångsmässiga asätare under jord. De vill åt metallhackor, spadar, ljus och färdiga järnföremål som underlättar deras ändlösa grävande, så ett förråd fullt av dvärgverktyg är ett oemotståndligt byte.",al={"varför vill kobolder ha utrustning","kobolder stjäl verktyg","kobolder i silver stream mine"}},{q="Är Silver Stream Mine farlig att utforska ensam?",a="De trånga gångarna och de täta grupperna av kobolder gör gruvan farlig. Mountaineer Stormpike varnar uttryckligen för att ensamvandrare kan vilja ta med sig följeslagare.",al={"är filthy paws svårt","silver stream mines svårighetsgrad","kan jag klara filthy paws ensam"}},{q="Vem äger förråden som lagras i gruvan?",a="Förråden tillhör Ironforge Miners' League, handelsgillet som ansvarar för stenbrytning, gruvdrift och förvaltning av underjordiska resurser i hela dvärgriket.",al={"vem äger utrustningen","miners' leagues lådor","vem leder miners' league"}}},fx={c638d192={q="Varför vill Mountaineer Stormpike att gruvarbetarnas utrustning hämtas?",a="Gruvarbetarnas förbund gjorde om den tömda Silver Stream Mine till ett förråd, men kobolder har invaderat gångarna och lagt beslag på utrustningen. Bergsvakterna planerar att snart rensa ut ohyran, men förbundet kräver att de värdefulla verktygen hämtas först. Stormpike skickar in dig före militärens rensning, så att de hårdhänta dvärgkrigarna inte krossar den ömtåliga utrustningen i det kommande anfallet.",al={"varför vill stormpike ha utrustningen","stormpikes motiv för filthy paws","varför hämta gruvarbetarnas utrustning"}},e40e35ce={q="Vad används Miners' Gear till?",a="Utrustningen består av kvalitetsverktyg och förnödenheter från Gruvarbetarnas förbund. När Silver Stream Mine tömdes på malm gjorde förbundet om gruvkamrarna till ett säkert förråd för arbetsutrustning. Förbundet behöver få tillbaka de värdefulla redskapen hela innan striderna förstör dem.",al={"vad är miners' gear","vad används miners' gear till","vad är dvärgverktygen till för"}},["31be8455"]={q="Vem har tagit över Silver Stream Mine?",a="En flock kobolder har tagit över den gamla gruvans gångar. De här skadedjuren dras naturligt till underjordiska boningar och glänsande metall, och flyttade in i de tömda schakten. Där började de rota bland den lagrade utrustningen och smutsa ner dvärgverktygen med sina tassar.",al={"vem finns i silver stream mine","fiender i filthy paws","vad tog över gruvan"}}},fp="11,238,16.342.0,17.421.0,56.174.0,57.184.0,40.108.0,50.183.0,53.137.0,41.153.0"}
P.entries["quest:308"] = {n="Distracting Jarven",s="Nere i Thunderbrew Distillerys källare står vakten Jarven Thunderbrew omgiven av tunnor han inte får röra. Han längtar efter att smaka familjens brygd och ber en äventyrare på genomresa om en mugg Thunder Ale som kan vässa hans tankar under vakten.",h="Nere i Thunderbrew Distillerys källare står vakten Jarven Thunderbrew omgiven av tunnor han inte får röra.",kw={"källare","destilleri","distrahera jarven","dun morogh","jarven thunderbrew","kharanos","thunder ale"},ang={["class:Rogue"]="Att distrahera en vakt med stark sprit är ett gammalt yrkesknep, även om Jarven gärna ber om distraktionen själv.",["race:Dwarf"]="Alla dvärgar förstår plågan i att stå vakt bredvid tunnor med legendariskt öl utan att få smaka en enda droppe."},sec={{t="En törstig vakt i tjänst",b="Jarven Thunderbrew har fått i uppgift att hålla uppsikt över Thunderbrew Distillerys djupa förråd i Kharanos. Trots att han är omgiven av den finaste stouten i Dun Morogh lyder han stränga familjeorder om att inte ta av lagret när han står vakt. Frestelsen blir för stor, och han ber förbipasserande resenärer hämta en mugg stark Thunder Ale från kranarna där uppe."},{t="En tvivelaktig uppiggare",b="Jarven hävdar att en god dryck bara vässar hans sinnen och gör honom bättre på att hålla vakt. Om det är klokt att bjuda en vakt i tjänst på något gott är en öppen fråga, men bland de härdade dvärgarna i Dun Morogh är det få som kan klandra en Thunderbrew för att vilja smaka på sin släkts världsberömda brygd."}},faq={{q="Vem är Jarven Thunderbrew?",a="Jarven tillhör den välkända familjen Thunderbrew och är stationerad nere i källaren på Thunderbrew Distillery i Kharanos för att hålla uppsikt över tunnorna i förrådet.",al={"vem är jarven","jarvens bakgrund","vakt i källaren"}},{q="Varför behöver Jarven någon som hämtar öl åt honom?",a="Jarven har stränga order från sin familj att inte dricka ur källarförrådet när han står vakt. För att kringgå reglerna utan att bryta upp de förseglade tunnorna ber han en utomstående hämta en färsk mugg där uppe.",al={"varför får jarven inte dricka","jarvens öluppdrag","varför hämta sprit"}},{q="Var hittar man Thunder Ale?",a="Thunder Ale serveras precis där uppe i Thunderbrew Distillerys stora värdshussal i Kharanos och säljs av värdshusvärden och bartenderna.",al={"hämta thunder ale","var finns thunder ale","köpa thunder ale"}},{q="Var ligger Thunderbrew Distillery?",a="Destilleriet fungerar som Kharanos livliga värdshus mitt i byn. Det ligger i Dun Moroghs snöiga hjärta, strax nedanför berget från Ironforge.",al={"kharanos destilleri","thunderbrew-källarens läge","var är jarven"}},{q="Varför är Thunderbrew-öl så berömt?",a="Thunderbrew-klanens stout och öl är legendariska i hela Khaz Modan och bortom, tack vare sin kraft, smak och dvärgaktiga styrka.",al={"thunderbrews rykte","vad är thunder ale"}},{q="Blir det några problem om Jarven blir full?",a="Jarven hävdar att ölet vässar hans tankar i stället för att slöa dem, men det håller honom helt klart sysselsatt så att han inte märker någon som rotar runt i det nedre förrådet.",al={"konsekvenser av att jarven blir full","vad händer efter att jarven distraherats"}}},fx={a200e5d8={q="Varför vill Jarven Thunderbrew ha ett fat Thunder Ale?",a="Jarven är stationerad för att vakta källarna, omgiven av tunnor med dvärgsprit, men strikta order förbjuder honom att ta något av lagret han vaktar. Han längtar efter en drink som kan skärpa sinnena och göra den långa vakten lättare. Därför behöver han någon diskret som kan smuggla till honom ett smakprov av Thunderbrews finaste brygd, så att han kan njuta utan att öppet bryta mot reglerna.",al={"varför vill jarven ha öl","jarvens motiv","varför vill jarven dricka"}},["8c39bfa0"]={q="Vad används Thunder Ale till?",a="Fatet Thunder Ale är en kraftig förfriskning som ska stilla Jarven Thunderbrews törst. När han står vakt djupt nere i destilleriets källare förlitar han sig på att du hämtar det från tappkranarna ovanför, så att han kan dricka utan att lämna sin post eller röra förrådslagret.",al={"vad är thunder ale till för","användning för thunder ale","varför hämta thunder ale"}}},fp="18,241,23.266.0,19.230.0,26.143.0,46.179.0,27.114.0,44.135.0,33.147.0,44.134.0"}
P.entries["quest:3082"] = {n="Etched Tablet",s="Gornek skickar en ristad tavla till jägare i Valley of Trials. Den bär Jen'shans märke och kallar dem till att börja träna i vildmarken.",h="Gornek skickar en ristad tavla till jägare i Valley of Trials.",kw={"darkspear","durotar","etched tablet","gornek","jägare","jen'shan","valley of trials"},ang={["class:Hunter"]="Som jägare får du din första plats bland Hordens jägare och börjar lära dig av din lokala tränare i vildmarken.",["faction:Horde"]="Som medlem av Horden ser du hur orcher och troll delar med sig av sina särskilda styrkor för att hjälpa båda folken att överleva.",["race:Orc"]="Som orch lär du dig förfinad smygning och spårning av dina Darkspear-allierade, vilket kompletterar ditt folks krigartraditioner.",["race:Troll"]="Som troll kan du se hur Darkspears jaktkunskap hjälpte Horden att överleva på Kalimdor och stödja sina allierade."},sec={{t="En kallelse till jakten",b="Gornek ger nyblivna jägare en ristad tavla när de har bevisat sig mot vildsvinen nära The Den. Stenen bär Jen'shans märke. Hon är en skicklig trolljägarinna som är stationerad i närheten, och meddelandet visar att erfarna jägare har lagt märke till den unga rekrytens uthållighet. Lärdomen går nu vidare från att överleva de lokala farorna till disciplinerad träning i vildmarken."},{t="Att dela kunskaper om överlevnad",b="Jen'shan lär ut att orcher och troll har en lång historia inom Horden. Orcherna förde med sig berömda traditioner av krigare och schamaner, medan Darkspear Trolls bar på urgamla färdigheter i att smyga, spåra och överleva. Dessa färdigheter hjälpte orcherna att uthärda livet på Azeroth. När Jen'shan tränar nya jägare fortsätter de två folken att dela med sig av sina kunskaper, förenade av respekt för jakten."}},faq={{q="Vem skickar Etched Tablet?",a="Jen'shan skickar den inskrivna stenen, och Gornek överlämnar den när du har bevisat dig i Valley of Trials.",al={"vem skrev etched tablet","vem skickade tavlan","vem gav mig tavlan"}},{q="Var finns Jen'shan?",a="Jen'shan finns i den norra delen av Valley of Trials i Durotar, bland de andra klassinstruktörerna nära The Den.",al={"var finns jen'shan","var är jen'shan","hitta jen'shan"}},{q="Varför tränar troll orcher till jägare här?",a="Jen'shan säger att Horden vände sig till trollen för jaktkunskap när de kämpade för att överleva på Azeroth. Orcherna kunde redan krigarnas och schamanernas vägar, och de två folken delar fortfarande sina färdigheter.",al={"varför troll som jägarlärare","troll lär orcher","darkspear-jägare"}},{q="Vad händer när jag lämnar in tavlan?",a="Jen'shan tar dig som sin lärling och erbjuder sig att lära dig grundläggande tekniker, skott och överlevnadskunskaper för Hordens jägare medan du får erfarenhet.",al={"vad händer efter tavlan","lore om etched tablets belöning","jen'shans uppföljning"}},{q="Vilket förhandsuppdrag måste vara klart innan jag får tavlan?",a="Du måste först slutföra Gorneks första uppgift, Cutting Teeth, genom att döda fläckiga vildsvin för att bevisa din uthållighet.",al={"förhandskrav för tavlan","hur låser jag upp etched tablet","förhandskrav för etched tablet"}},{q="Kan alla klasser slutföra det här uppdraget?",a="Endast nyblivna jägare kan få denna träningskallelse i Valley of Trials. Andra klasser får andra kallelser från Gornek.",al={"vem kan få etched tablet","klasskrav för etched tablet","är uppdraget bara för jägare"}}},fp="13,141,21.373.0,23.386.0,28.108.0,28.116.0,45.195.0,42.152.0,62.109.0,34.131.0"}
P.entries["quest:3083"] = {n="Encrypted Tablet",s="I Valley of Trials ger Gornek en kodad kallelse till blivande lönnmördare. Den skickar dem till Rwag i The Den, där utbildningen möter Shattered Hand.",h="I Valley of Trials ger Gornek en kodad kallelse till blivande lönnmördare.",kw={"durotar","encrypted tablet","gornek","skurkarnas tränare","rwag","shattered hand","the den","valley of trials"},ang={["class:Rogue"]="Som lönnmördare träffar du din första mentor, Rwag, genom den här tavlan och får uppleva Shattered Hands räckvidd i Durotar.",["race:Orc"]="Som ork kommer du från en kultur som ärar öppen strid på slagfältet, medan orkiska lönnmördare tjänar den moderna Horden som spejare och infiltratörer.",["race:Troll"]="Som troll tar du med dig djungelns spårningsinstinkter till klingkonsten som lärs ut av mentorerna i The Den och blir till nytta i det tysta bland dina orkiska allierade."},sec={{t="En kodad kallelse",b="Gornek ger en Encrypted Tablet till varje nykomling som bevisar sitt mod mot traktens vilda djur. Meddelandet är skrivet i chiffer, ett passande prov och en försiktighetsåtgärd för dem som tränas i smygande, gift och bedrägeri. Kallelsen leder rekryten in i The Den för att träffa Rwag, som tränar Hordens lönnmördare, tjuvar och ficktjuvar."},{t="Handens skugga",b="Inne i The Den hittar nykomlingarna Rwag, en agent med anknytning till Shattered Hand. Han säger till de nya lönnmördarna att gillet inte kommer att styra varje andetag de tar, men Shattered Hand håller honom ansvarig om en lärling inte sköter sig. Den spirande Horden är omringad av fiender och förlitar sig i hög grad på tysta spejare och smidiga ficktjuvar för att samla in underrättelser och undanröja hot från skuggorna."}},faq={{q="Vad är syftet med Encrypted Tablet?",a="Encrypted Tablet kallar nybörjarlönnmördare från Valley of Trials till ett möte med deras tränare, Rwag, inne i The Den.",al={"vad gör tabletten","encrypted tablets syfte","varför encrypted tablet"}},{q="Vem överlämnar tabletten till spelaren?",a="Gornek, som övervakar prövningarna i dalen, ger dig tavlan efter att du klarat ditt första stridsprov genom att döda Mottled Boars.",al={"vem ger encrypted tablet","tablettens uppdragsgivare","gornek och tabletten"}},{q="Var hittar man Rwag?",a="Rwag befinner sig djupt inne i The Den, grottkomplexet längs den norra klippsidan i Valley of Trials.",al={"rwags plats","var finns rwag","hitta rwag"}},{q="Vad menar Rwag med ”Handen”?",a="Rwag företräder Shattered Hand, ett hemligt nätverk och gille av lönnmördare, spioner och skurkar som tjänar hövding Thralls Horde.",al={"vad är handen","shattered hand och rwag","vem är handen"}},{q="Varför är tabletten skriven med ett krypterat chiffer?",a="Chiffret döljer känsliga angelägenheter för lönnmördare och deras kontaktpersoners identiteter för nyfikna ögon. Det prövar också om en nykomling kan hantera diskreta meddelanden.",al={"varför krypterad","varför chiffer","skurkens tablettkod"}},{q="Kan alla klasser anta det här uppdraget?",a="Nej. Endast troll-lönnmördare som inleder sin resa i Valley of Trials får Encrypted Tablet.",al={"är encrypted tablet bara för skurkar","kan krigare göra encrypted tablet","klassbegränsning för tabletten"}}},fp="16,157,15.335.0,22.376.0,44.113.0,38.132.0,24.101.0,37.124.0,49.160.0,35.99.0"}
P.entries["quest:3084"] = {n="Rune-Inscribed Tablet",s="I Valley of Trials får nya shamaner en kallelse från Shikrik. Den kallar lovande lärlingar till formell utbildning i andarna och elementen: jord, eld, vatten och luft.",h="I Valley of Trials får nya shamaner en kallelse från Shikrik.",kw={"durotar","element","gornek","schaman","shikrik","tavla","thrall","valley of trials"},ang={["class:Shaman"]="Som shaman får du den här tavlan som din formella invigning på vägen. Den ålägger dig att balansera elementens krafter och vägleda andra med förfädernas visdom.",["faction:Horde"]="Som medlem av Horden delar du en tradition av shamanism som skänker ära och balans längs den hårda gränsmarken.",["race:Orc"]="Som orc ser du i den här tavlan en återgång till den förfädersshamanism som Thrall förespråkade, och ett avståndstagande från den demoniska forntidens häxmästararv.",["race:Troll"]="Som troll finner du gemensam grund i shamanismen med orciska mentorer som Shikrik. Du förenar din förfäderskontakt med Hordens gemensamma elementtraditioner."},sec={{t="En kallelse till andarna",b="Gornek ger blivande shamaner en uthuggen stentavla när de visat sin första disciplin på Valley of Trials dammiga träningsplatser. Runorna bär en inbjudan från Shikrik, den lokala shamantränaren. Kallelsen säger till varje lärling att de är redo att se bortom fysisk strid och lyssna till naturens djupare krafter."},{t="Andligt ledarskap i den nya horden",b="Shamanismen har en helig plats i den återupplivade Horden. Shikrik lär ut att shamaner hämtar kraft från de fyra elementen och styrka från förfädernas andar. De följer Warchief Thralls exempel som andliga vägledare och kunskapskällor för sina samhällen. I hela Durotar skyddar de bosättningarna som slår rot."}},faq={{q="Vad är Rune-Inscribed Tablet?",a="Gornek ger nyblivna shamaner i Valley of Trials en ristad stentavla med en kallelse från Shikrik. Den kallar den unge äventyraren till formell utbildning i andliga och elementära konster.",al={"rune-inscribed tablet","tavelföremål","schamantavla"}},{q="Vem är Shikrik?",a="Shikrik är shamantränaren nära ingången till The Den i Valley of Trials. Hon vägleder nya orc- och trollshamaner i att bemästra elementen och lära sig sin plikt som andliga ledare inom Horden.",al={"shikrik","vem är shikrik","schamantränare valley of trials"}},{q="Varför nämner Shikrik Thrall när hon talar med nya schamaner?",a="Warchief Thrall ledde återupplivandet av förfädernas shamanism efter att demonisk förvridning slukat den gamla Horden. Shikrik lyfter fram honom som ett föredöme för en shamans plikt att bevara elementens harmoni och samtidigt vägleda och skydda sitt folk.",al={"varför thrall","shikrik nämner thrall"}},{q="Var finns Shikrik?",a="Shikrik står strax utanför ingången till The Den på den östra sidan av Valley of Trials, redo att lära nyblivna shamaner deras första tekniker.",al={"var finns shikrik","hitta shikrik"}},{q="Vem delar ut tavlan?",a="Gornek övervakar de första prövningarna för nykomlingar som anländer till Valley of Trials. Han ger tavlan till en lärling som har visat sitt grundläggande mod.",al={"vem ger tavlan","gornek tavla"}},{q="Vilken grundfilosofi lär Shikrik ut?",a="Shikrik lär ut att en shaman hämtar kraft från eld, jord, vatten och luft, och uthållighet och beslutsamhet från förfädernas andar. Shamaner förväntas erbjuda visdom och försvar åt de städer eller krigsband de ansluter sig till.",al={"shikriks filosofi","schamanlära"}}},fp="21,178,21.346.0,37.317.0,34.191.0,15.206.0,60.225.0,25.141.0,25.149.0,40.210.0"}
P.entries["quest:3085"] = {n="Hallowed Tablet",s="I Valley of Trials når ett budskap från Ken'jai de unga prästerna efter deras första prövning. Tavlan kallar dem att lära sig hur Darkspear-präster samtalar med andarna.",h="I Valley of Trials når ett budskap från Ken'jai de unga prästerna efter deras första prövning.",kw={"darkspear","durotar","gornek","hallowed tablet","ken'jai","präst","andar","the den","valley of trials"},ang={["class:Priest"]="Som präst lämnar du dalens vanliga prövningar och börjar din formella andliga undervisning hos Ken'jai utanför The Den.",["faction:Horde"]="Som medlem av Horde hjälper du till att hålla de andliga riterna och andarnas vilja centrala medan ditt folk bosätter sig i Durotar.",["race:Troll"]="Som troll följer du Darkspear-traditioner som hedrar förfäders andar och loa, i stället för utländska prästers dogmatiska seder."},sec={{t="Ett meddelande från Ken'jai",b="När du har bevisat dig mot vildsvinen under Gorneks uppsikt ger han dig en inskriven sten som kallas Hallowed Tablet. Dess budskap bär Ken'jais märke. Darkspear-mystikern väntar utanför The Den, där han vakar över nykomlingar som söker sig till tron och andlig magi."},{t="Gemenskap med andarna",b="Darkspear-präster bland Horde söker gemenskap med andar och loa, till skillnad från mänskliga och dvärgiska präster som följer Holy Light över havet. Ken'jai välkomnar dig till Durotar och lär dig att din kraft växer genom andlig disciplin. Han kommer att lära dig större riter när ditt band till andarna mognar."}},faq={{q="Vad är Hallowed Tablet?",a="Hallowed Tablet bär ett budskap från Ken'jai, trollprästernas tränare, till unga präster i Valley of Trials. Gornek förvarar den tills du bevisar dina grundläggande färdigheter i dalen.",al={"vad är hallowed tablet","föremålet hallowed tablet","tavlans historia"}},{q="Vem är Ken'jai?",a="Ken'jai är en prästtränare bland Darkspear-trollen utanför The Den i Valley of Trials. Han lär unga noviser att samtala med andar och att lära sig läkande och skuggiga andliga konster.",al={"kenjai","vem är kenjai","ken'jai tränare"}},{q="Varför börjar präster med att slåss mot fläckiga vildsvin?",a="Du bevisar att du klarar dig själv och har överlevnadsfärdigheter innan en specialistinstruktör lägger tid på att träna dig. Varje novis i Valley of Trials ställs inför den här prövningen, oavsett vilken väg hen valt.",al={"varför döda vildsvin","sambandet med cutting teeth"}},{q="Hur skiljer sig Ken'jais prästerskap från det Heliga ljuset?",a="Darkspear-präster åkallar andar och loa, medan mänskliga och dvärgiska kyrkor dyrkar Holy Light. Ken'jai lär ut att de måste bevara dessa osynliga makters välvilja och leva i harmoni med dem.",al={"trollprästernas historia","horde-präster","andar kontra ljuset"}},{q="Var ligger The Den?",a="The Den är en bosättning i en urholkad grotta i Valley of Trials i södra Durotar. Tränare och prövningsmästare använder den som ett nav för nya rekryter till Horde.",al={"the den durotar","var ligger the den","kenjais plats"}},{q="Kan orcher bli präster genom det här uppdraget?",a="Nej. Endast Darkspear-troll i Valley of Trials har de andliga traditioner som krävs för att tränas till präster under Ken'jai. Orkernas kultur följer i stället schamanism och häxmästarmagi.",al={"orchpräster","kan orcher bli präster","orchernas hallowed tablet"}}},fp="15,172,22.270.0,26.318.0,28.188.0,15.181.0,51.186.0,57.197.0,17.149.0,43.174.0"}
P.entries["quest:3086"] = {n="Glyphic Tablet",s="I Valley of Trials skickar en Glyphic Tablet unga magiker i Horde till Mai'ah. Gornek ger dem den när de har bevisat sin styrka, och trolltränaren väntar utanför The Den.",h="I Valley of Trials skickar en Glyphic Tablet unga magiker i Horde till Mai'ah.",kw={"arkan","durotar","glyphic tablet","gornek","magiker","mai'ah","the den","valley of trials"},ang={["class:Mage"]="Som magiker får du ett formellt välkomnande bland Hordes besvärjare av dalens tränare. Mai'ah lär dig disciplinen som krävs för att kontrollera rå magi.",["race:Orc"]="Som orch väljer du en ovanlig väg under Mai'ah. Orchkulturen har länge formats av schamaner och krigare, och få av ditt folk har prövat på arkan magi.",["race:Troll"]="Som Darkspear-troll speglar din träning hos Mai'ah stammens växande bruk av formell besvärjelsekonst vid sidan av dess traditionella andliga riter."},sec={{t="Ett meddelande i inhuggen sten",b="Du har bevisat din styrka mot Valley of Trials vilda djur, och Gornek ger dig en inskriven tavla. Mai'ah, dalens magiktränare, skickade den. Hon ber dig hitta henne vid ingången till The Den när du är redo att börja dina arkana studier."},{t="Farorna med det osedda",b="Mai'ah talar klarspråk om kraften magiker utövar och faran som följer med den. Hon varnar för att deras största hot är magins osynliga dragning mot fördärv, inte rivaliserande krigare eller fiendefolk. Ödmjukhet och tålamod spelar roll, säger hon, eftersom okontrollerad trolldom kan få en magiker att tro att hen behärskar mer än hen gör."}},faq={{q="Vem lämnar över Glyphic Tablet till spelaren?",a="Gornek ger dig tavlan när du har rensat Valley of Trials från spräckliga vildsvin.",al={"vem ger glyphic tablet","var får jag glyphic tablet","glyphic tablet för nybörjare"}},{q="Vem är Mai'ah?",a="Mai'ah är en magikertränare av Darkspear-trollen utanför The Den i Valley of Trials. Hon lär unga magiker i Horde sina första besvärjelser och varnar dem för arkan korruption.",al={"vem är mai'ah","mai'ahs bakgrund","trollmagikertränare"}},{q="Var finns Mai'ah?",a="Mai'ah väntar precis utanför ingången till The Den, till höger om tunnelmynningen i norra Valley of Trials.",al={"var finns mai'ah","mai'ahs plats","hitta mai'ah"}},{q="Vilken varning ger Mai'ah om magi?",a="Mai'ah varnar för att magi kan fördärva dem som utövar den. Hon säger att magiker bör frukta dess osynliga frestelser och vanföreställningar om makt mer än fysiska fiender som orcher, alver eller dvärgar.",al={"mai'ahs varning","magi och fördärv","vad säger mai'ah"}},{q="Får andra klasser Glyphic Tablet?",a="Nej. Glyphic Tablet är avsedd för nybörjarmagiker. Andra klasser får andra introduktionskallelser, som runor, skriftrullar eller sigill, anpassade efter deras tränare.",al={"kan andra klasser få glyphic tablet","är glyphic tablet bara för magiker"}},{q="Vilket krav måste uppfyllas för att få stentavlan?",a="Du måste först slutföra Gorneks inledande uppgift genom att döda spräckliga vildsvin på Valley of Trials röda jordslätter.",al={"krav för glyphic tablet","förkunskapskrav för glyphic tablet"}}},fp="14,179,28.251.0,25.328.0,46.86.0,14.168.0,24.112.0,42.188.0,44.158.0,53.121.0"}
P.entries["quest:3087"] = {n="Etched Parchment",s="I Valley of Trials kallar Etched Parchment en ung jägare till Jen'shan. Gornek överlämnar det efter den nyblivna jägarens första blodsdåd och öppnar vägen till vildmarksträning i Durotar.",h="I Valley of Trials kallar Etched Parchment en ung jägare till Jen'shan.",kw={"darkspear","durotar","etched parchment","gornek","jägarinstruktör","jen'shan","valley of trials"},ang={["class:Hunter"]="Som jägare visar den här kallelsen vägen till Jen'shan, där du kan vässa ditt sikte och förstå vildmarken.",["faction:Horde"]="Som jägare i Horde spanar du av gränserna och skaffar mat åt lägren. Den tidiga träningen hjälper till att hålla Durotar försörjt och bevakat.",["race:Orc"]="Som orc förlitar du dig på mentorer som Jen'shan för att anpassa klanernas jaktmetoder till Durotars torra klippor och dödliga bestar.",["race:Troll"]="Som Darkspear-rekryt håller du de urgamla spårningstraditionerna från djungeln vid liv genom att studera under Jen'shan."},sec={{t="En kallelse från vildmarken",b="Efter att ha bevisat sig mot fläckiga vildsvin får jägare i Valley of Trials ett etsat pergament av Gornek. Jen'shan, en skicklig Darkspear-jägare, skickade meddelandet efter att ha iakttagit nyanlända från lägrets utkanter. Det välkomnar den nyblivna jägaren till formell träning och erkänner instinkterna som krävs för att bemästra Durotars otämjda bestar och hårda land."},{t="Jägarens väg",b="Att inställa sig hos Jen'shan markerar övergången från rekryt till hängiven spårare. Hon varnar för att jakt inte är lättare än de arkaniska konsterna eller förfädernas shamanism. Att bemästra Durotars rovdjur, underhålla avståndsvapen och överleva i ett ogästvänligt landskap kräver disciplin. Jen'shan skickar sina lärlingar för att hjälpa dalens övriga invånare och pröva sina förmågor innan de återvänder för att lära sig mer avancerade överlevnadstekniker."}},faq={{q="Vad är Etched Parchment?",a="Etched Parchment är en skriftlig kallelse från Gornek på uppdrag av Jen'shan, jägarinstruktören. Den kallar lovande rekryter till henne för specialiserad strids- och vildmarksträning i Valley of Trials.",al={"vad är det här pergamentet","graverad pergamentlapp","jägarpergament"}},{q="Vem överlämnar kallelsen till spelaren?",a="Gornek ger dig pergamentet efter ditt första prov, då du dödar fläckiga vildsvin i Valley of Trials.",al={"vem ger etched parchment","var får jag uppdraget"}},{q="Vem är Jen'shan?",a="Jen'shan är en Darkspear-trolljägare stationerad i Valley of Trials. Hon bedömer nyblivna orc- och trolljägare och lär ut avståndsstrid, spårning och besthantering.",al={"jen'shans historia","vem är jen'shan"}},{q="Varför jämför Jen'shan jägare med magiker och schamaner?",a="Jen'shan varnar för att många misstar jakt för en lättare väg än förfädernas andar eller arkanisk magi. Dödlig skytteförmåga och mästerskap över vilda bestar kräver lika stor hängivenhet och innebär lika stor fara.",al={"varför är jakt inte lätt","vad betyder jen'shans dialog"}},{q="Vad händer när du har rapporterat till Jen'shan?",a="Jen'shan lär dig avancerade jägartekniker och skickar dig för att hjälpa Valley of Trials övriga invånare. Du övar på dina nyförvärvade färdigheter genom praktisk överlevnadsträning.",al={"vad händer efter etched parchment","fortsättning på jägaruppdraget"}},{q="Vem kan få det här uppdraget?",a="Endast nyskapade orc-jägare som tränar i Valley of Trials kan få det.",al={"vem får etched parchment","är uppdraget bara för jägare"}}},fp="16,182,23.365.0,16.423.0,29.203.0,40.101.0,16.165.0,55.194.0,41.183.0,27.79.0"}
P.entries["quest:3088"] = {n="Encrypted Parchment",s="I Valley of Trials skickar Encrypted Parchment beprövade, oerfarna orciska skurkar till The Den. Chiffertexten leder dem till Rwag, en agent åt Shattered Hand.",h="I Valley of Trials skickar Encrypted Parchment beprövade, oerfarna orciska skurkar till The Den.",kw={"durotar","encrypted parchment","gornek","orcisk skurk","rwag","shattered hand","the den","valley of trials"},ang={["class:Rogue"]="Som skurk markerar det här pergamentet att du upptas i Hordens hemliga led. Det för dig till Rwag och din första yrkesträning.",["faction:Horde"]="Som medlem av Horden vet du att även en hedervärd krigshövding som Thrall behöver spioner och spejare för att skydda Durotars unga land från dolda hot.",["race:Orc"]="Som orc balanserar du dina förfäders disciplin med den lågmälda list som Shattered Hand kräver, till skillnad från krigare som söker öppen, blodtörstig ära."},sec={{t="En kodad kallelse",b="Gornek ger det kodade pergamentet till oerfarna orcer som har bevisat sig mot traktens vilda djur. Andra tränare rekryterar elever öppet på gläntan, men skurk-tränaren Rwag skickar sina kallelser med chiffer. Meddelandet leder dig bortom det solbelysta lägret och djupt in i grottan som kallas The Den."},{t="Ögon i skuggorna",b="Inne i The Den hittar du Rwag, som håller vakt bland klipporna. Häxmästare lurar längre in i grottan, och han berättar att han håller uppsikt över rekryter åt Shattered Hand. Orcernas samhälle värdesätter öppen heder och ära i strid, medan Shattered Hand verkar som Hordens dolda nätverk av spioner, lönnmördare och underrättelseinhämtare."}},faq={{q="Vem skickar Encrypted Parchment?",a="Rwag, skurk-tränaren i Valley of Trials, skriver pergamentet. Han låter Gornek lämna det kodade meddelandet till lovande unga orcer efter att de har klarat sina första prövningar.",al={"vem skrev pergamentet","vem gav mig det krypterade pergamentet","vem skickade meddelandet"}},{q="Vad är syftet med det här uppdraget?",a="Pergamentet leder orciska skurkar till Rwag i The Den, där deras formella träning börjar. Han lär dem smygande, låsdyrkning och stridens list.",al={"varför behöver jag ett krypterat pergament","vad gör uppdraget"}},{q="Var finns Rwag?",a="Rwag håller sig gömd i The Den, en mörk grotta på norra sidan av Valley of Trials. Han håller sig nära ingången och aktar sig för häxmästarna längre in.",al={"var finns rwag","hitta rwag","rwags plats"}},{q="Varför är pergamentet krypterat?",a="Chiffret hindrar kringvandrande våldsverkare och nyfikna främlingar från att läsa kallelsen. Det prövar också om den som ska invigas kan tyda ett hemligt meddelande.",al={"varför chiffer","varför är meddelandet kodat"}},{q="Vilka är Shattered Hand?",a="Shattered Hand började som en ökänd orcisk klan, känd för självstympning. I Thralls Horde är den en organisation av spejare, lönnmördare och hemliga agenter som verkar i skuggorna för att skydda Hordens intressen.",al={"shattered hand i horden","vad är shattered hand"}},{q="Varför misstror Rwag Nartok?",a="Nartok är en häxmästartränare längre in i The Den. Rwag misstror de mörka magikerna, som öppet utför felritualer i grottans innersta hörn.",al={"rwag nartok","varför hatar rwag häxmästare"}}},fp="19,153,15.300.0,19.322.0,34.174.0,34.144.0,22.150.0,31.145.0,27.212.0,30.145.0"}
P.entries["quest:3089"] = {n="Rune-Inscribed Parchment",s="I Valley of Trials kallar en runristad kallelse nya schamaner till Shikrik. Gornek överlämnar pergamentet, som inleder deras formella utbildning i samspel med andar och element.",h="I Valley of Trials kallar en runristad kallelse nya schamaner till Shikrik.",kw={"förfäder","durotar","element","gornek","rune-inscribed parchment","shaman","shikrik","valley of trials"},ang={["class:Shaman"]="Som schaman markerar detta pergament ditt första steg på en andlig väg och knyter dig till andarna och Durotars obändiga element.",["race:Orc"]="Som ork hedrar din återkomst till schamanismen Draenors förfäders traditioner, som nästan utplånades av den demoniska korruptionen i Old Horde.",["race:Troll"]="Som Darkspear-troll för du med dig din naturliga förmåga att samspela med andar och vördnad för förfäderna in i Hordes gemensamma schamantraditioner."},sec={{t="En kallelse från andarna",b="Efter att ha visat att de kan överleva bland traktens vilda djur får nya orkschamaner ett runristat pergament av Gornek, som vakar över Valley of Trials. De mystiska orden kommer från Shikrik, dalens schamantränare, som vill träffa den nyanlända lärlingen."},{t="Shamanens väg",b="Mötet med Shikrik inleder schamanens heliga plikt gentemot Horde. Hon lär ut att schamaner tjänar som kanaler för förfädernas andar och använder elementens vrede. Under hennes vägledning lär sig nya schamaner att kanalisera andliga krafter, hela sår och åkalla Kalimdors naturkrafter."}},faq={{q="Vad är Rune-Inscribed Parchment?",a="Gornek ger nya schamaner i Valley of Trials en skriftlig kallelse att söka formell undervisning hos sin tränare, Shikrik.",al={"vad är det här för uppdrag","pergamentuppdrag","startmeddelande för shaman"}},{q="Vem skickar pergamentet?",a="Shikrik, schamantränaren nära hålorna i Valley of Trials, skrev meddelandet och väntar på dem som utsetts att vägleda sitt folk andligt.",al={"vem skrev pergamentet","shikriks meddelande","vem är shikrik"}},{q="Vart ska jag ta pergamentet?",a="Du går en kort bit inom Valley of Trials med pergamentet till Shikrik, som väntar under de röda klipporna för att träna orkschamaner och trollschamaner.",al={"vart ska jag gå","var finns shikrik","inlämningsplats"}},{q="Varför valdes min rollfigur att få det?",a="Shikrik säger att de som dras till schamanism har utsetts att tjäna som kanaler för förfäderna och tala med världens elementkrafter.",al={"varför shaman","varför utvald","shamanens kall i berättelsen"}},{q="Vad händer när jag visar upp pergamentet?",a="Shikrik tar emot dig som sin elev och introducerar dig till elementmagi, samspel med förfäderna samt grunderna i läkekonst och strid.",al={"nästa steg","vad gör shikrik","efter pergamentet"}},{q="Kan alla klasser slutföra det här uppdraget?",a="Nej. Rune-Inscribed Parchment är till för nya schamaner. Andra klasser får egna kallelser till sina tränare.",al={"bara för shamaner","vem får pergamentet","pergament för krigare"}}},fp="24,182,26.272.0,22.280.0,37.122.0,24.143.0,30.143.0,42.132.0,44.137.0,34.114.0"}
P.entries["quest:309"] = {n="Protecting the Shipment",s="Protecting the Shipment är ett eskortuppdrag i södra Loch Modan där äventyrare skyddar kuriren Miran på vägen till Ironband's Excavation Site. Miran har med sig en låda med flyktigt sprängkrut som Prospector Ironband behöver omgående. Resan blottlägger kvarvarande Dark Iron-sabotage som hotar dvärgarnas inland.",h="Protecting the Shipment är ett eskortuppdrag i södra Loch Modan där äventyrare skyddar kuriren Miran på vägen...",kw={"sprängkrut","dark iron-överfall","ironband's excavation site","eskortuppdrag i loch modan","miran","prospector ironband"},ang={["faction:Alliance"]="Alliansen är beroende av fungerande logistik i Loch Modan. När kurirer skyddas från underjordiska plundrare bevaras förbindelsen mellan Ironforge och de östra gränstrakterna.",["profession:Mining"]="Gruvarbetare vet mycket väl hur värdefullt och flyktigt sprängkrut är när man bryter sig genom Khaz Modans hårda berggrund.",["race:Dwarf"]="För Ironforges dvärgar är försvaret av Ironbands förnödenheter också ett direkt försvar av arvet: deras förfäders upptäckter skyddas från deras bittra Dark Iron-fränders sabotage."},sec={{t="En farlig krutleverans",b="Prospector Ironband bedriver en arkeologisk utgrävning i kullarna i södra Loch Modan och behöver en stadig tillförsel av sprängkrut för att ta sig igenom hård sten. När försörjningslinjerna bryter samman och kurirvagnar hotas blir kuriren Miran strandsatt på vägen med en tung last krut. Om du leder Miran säkert längs de ojämna vägarna till utgrävningsplatsen kan Ironbands arbete fortsätta."},{t="Dark Iron-sympatisörer",b="Vägen till utgrävningsplatsen hemsöks inte bara av vilda djur; Dark Iron-infiltratörer ligger aktivt i bakhåll för att snappa upp den explosiva lasten. Deras fräcka överfall nära platsen avslöjar en mörkare sanning för Ironband: Dark Iron-styrkor skaffar olagligt material och sprider aktivt splittring i hjärtat av Loch Modan. Leveransen gör att utgrävningen kan fortsätta, men väcker oro för hur djupt fiendens sabotage når in på Alliansens territorium."}},faq={{q="Vem är Miran?",a="Miran är en kurir åt Alliansen som fått i uppdrag att transportera viktiga förnödenheter, särskilt sprängkrut, längs Loch Modans farliga småvägar mot Ironband's Excavation Site.",al={"vem är miran","miran i loch modan","kuriren miran"}},{q="Varför behöver Prospector Ironband krutet?",a="Prospector Ironband leder en viktig arkeologisk utgrävning i södra Loch Modan. Hans team förlitar sig på kraftigt sprängkrut för att röja undan sten, gräva fram begravda reliker och hålla utgrävningen igång.",al={"varför ironband behöver krut","krutets syfte","ironbands sprängkrut"}},{q="Vem anfaller under eskortuppdraget?",a="Dark Iron-dvärgsabotörer överfaller kuriren strax före utgrävningsplatsen. De försöker lägga beslag på sprängämnena och hindra Ironforges verksamhet i området.",al={"vem överfaller miran","angripare i bakhåll","angripare under eskortuppdrag"}},{q="Vart leder eskortuppdraget?",a="Eskorten börjar längs Loch Modans södra väg och slutar vid Ironband's Excavation Site, i kullarna sydost om sjön.",al={"eskortens mål","vart tar miran vägen","var ligger ironband"}},{q="Varför finns Dark Iron i Loch Modan?",a="Dark Iron-klanen har hemliga enklaver och spioner runt om i Khaz Modan. De plundrar aktivt försörjningslinjer, saboterar Explorers' League-utgrävningar och försöker destabilisera Ironforges försvarsperimeter.",al={"dark iron i loch modan","varför är dark iron-dvärgar här","dark irons närvaro"}},{q="Vad händer när leveransen kommer fram?",a="Prospector Ironband tar tacksamt emot krutet och tackar Ljuset för att förnödenheterna kom fram, trots den oroande upptäckten att Dark Iron-sympatisörer verkar i närheten.",al={"fortsättning på uppdraget","vad händer efter att leveransen skyddats","nästa uppdrag"}}},fx={a48eefd2={q="Varför vill Miran få det här gjort?",a="Miran har fått i uppgift att föra livsviktigt sprängpulver genom fientligt område till Prospector Ironbands utgrävningsplats. Sändningen är tung och vägen förrädisk, med hotet från Dark Iron-bakhåll som lurar i närheten. Han klarar inte både att bära den explosiva lasten och försvara sig längs den farliga rutten.",al={"mirans motiv","varför eskortera miran","varför leverera pulver"}},bdc08a2b={q="Varför behöver Miran din hjälp i stället för de lokala vakterna?",a="Bergsvakterna i Loch Modan är hårt pressade när de håller tillbaka troggarnas intrång och säkrar regionens större bosättningar. Eftersom inga officiella patruller finns tillgängliga för att vakta leveransen förlitar sig Miran på skickliga äventyrare som du, som kan hålla Dark Iron-dvärgarna i kullarna stången.",al={"varför just jag åt miran","varför behöver miran hjälp","varför finns inga bergsvakter hos miran"}}},fp="23,214,21.234.0,22.293.1,13.155.0,45.165.0,30.146.0,27.123.0,33.171.0,40.129.0"}
P.entries["quest:3091"] = {n="Simple Note",s="Simple Note är en kort skriftlig inkallelse som en lokal budbärare levererar till unga taurenkrigare i Camp Narache. Den är skriven av tränaren Harutt Thunderhorn och kallar unga kämpar till tjänst. Den påminner dem om krigarnas viktiga roll vid sidan av druider och schamaner när stammens gränser ska försvaras mot centaur.",h="Simple Note är en kort skriftlig inkallelse som en lokal budbärare levererar till unga taurenkrigare i Camp...",kw={"camp narache","centaur","harutt thunderhorn","mulgore","red cloud mesa","simple note","tauren","krigare"},ang={["class:Warrior"]="Harutt Thunderhorn vägleder unga taurenkrigare och lär dem tygla sin krigiska stolthet och axla den tunga bördan att försvara Camp Narache mot anfallande centaur.",["race:Tauren"]="För unga tauren som påbörjar sin resa i Red Cloud Mesa betonar det här meddelandet att skyldigheten att försvara stammen står sida vid sida med andliga kall som schamanism och druidism."},sec={{t="En inkallelse till strid",b="När unga krigare anländer till Camp Narache får de en kort inkallelse av en budbärare från lägret. Den erfarne tränaren Harutt Thunderhorn har skrivit Simple Note, som uppmanar den spirande kämpen att genast inställa sig för att börja sin praktiska utbildning i att försvara stammen."},{t="Försvararens börda",b="Shu'halo vördar sina andliga ledare djupt, men Harutt påminner sina elever om att de fysiska försvararna bär en lika tung börda. Krigare ska patrullera stammens gränser, jaga flockar av rovlystna centaur och skydda sina fredliga stamfränder mot angrepp utifrån. Även om strid kan skänka ära måste varje krigare förbli ödmjuk och genomgå samma traditionella riter som schamaner och druider."}},faq={{q="Vem skrev Simple Note?",a="Harutt Thunderhorn, krigartränaren i Camp Narache, skickar meddelandet genom en budbärare som letar upp unga tauren redo att påbörja sin krigiska utbildning.",al={"vem skickade simple note","vem skrev meddelandet","avsändare simple note"}},{q="Vem är Harutt Thunderhorn?",a="Harutt Thunderhorn är en taurenkrigartränare stationerad i Camp Narache i Mulgore. Han tränar nya krigare som söker stridens ära och stammens urgamla krigstraditioner.",al={"vem är harutt","harutt thunderhorn","var är harutt"}},{q="Vad är syftet med Simple Note?",a="Meddelandet kallar nyvakna krigare till ett möte med sin tränare och påminner dem om att de som försvarar frontlinjen och jagar är lika viktiga för stammen som druider och schamaner.",al={"varför är meddelandet viktigt","vad står det i meddelandet"}},{q="Varför kallas krigare att jaga centaur?",a="Tauren i Mulgore står inför ständiga hot från fientliga centaurflockar längs sina gränser. Krigare som Harutt har fått i uppgift att träna stammens försvarare i att jaga dem och skydda lägret.",al={"varför strida mot centaur","tauren och centaurkonflikten"}},{q="Var ligger Camp Narache?",a="Camp Narache är Hawkwind-stammens urgamla träningsläger och startbosättning för unga tauren. Det ligger vid kanten av Red Cloud Mesa i Mulgore.",al={"camp naraches läge","var ligger camp narache"}},{q="Vilka stamriter nämner Harutt?",a="Alla i stammen, vare sig de är krigare, jägare, schamaner eller druider, måste genomgå stammens gemensamma urgamla riter för att bevisa sin styrka, ödmjukhet och hängivenhet till sitt folk.",al={"taurernas övergångsriter","vilka riter genomgår tauren"}}},fp="11,203,19.174.0,21.316.0,26.112.0,26.149.0,39.153.0,45.107.0,30.160.0,42.190.0"}
P.entries["quest:3092"] = {n="Etched Note",s="Etched Note är en formell kallelse till lovande unga taurenjägare i Camp Narache. Meddelandet framförs på tränaren Lanka Farshots vägnar och kallar novisen att börja bemästra vildmarkens praktiska och andliga konster.",h="Etched Note är en formell kallelse till lovande unga taurenjägare i Camp Narache.",kw={"camp narache","etched note","lanka farshot","mulgore","red cloud mesa","taurenjägare"},ang={["class:Hunter"]="Den här kallelsen markerar din formella invigning i jägarnas tradition och förbereder dig på att bemästra prickskyttets konst, överlevnad i vildmarken och sällskap med bestar.",["race:Tauren"]="För Shu'halo är jakt en helig plikt som hedrar Jordmodern genom respekten för de bestar som försörjer stammen på Mulgore slätter."},sec={{t="En kallelse till jakten",b="Under träningen bland klipporna på Red Cloud Mesa får unga tauren med fallenhet för prickskytte och spårning ett inristat meddelande. Grull Hawkwind framför budskapet att Lanka Farshot har lagt märke till den unges härkomst och medfödda förmåga, och uppmanar hen att formalisera sina studier under hans vakande blick."},{t="Slätternas tradition",b="För Shu'halo är en jägare mycket mer än en enkel spejare eller krigare. Jägarna försörjer stammarna genom sitt byte, skyddar nomadlägren och lever i nära balans med Kalimdors bestar. Genom att kalla novisen till träning lägger Lanka grunden för att bemästra vapen, förstå Mulgore varelser och så småningom utöva den uråldriga konsten att tämja vilda följeslagare."}},faq={{q="Vad är syftet med Etched Note?",a="Etched Note fungerar som en formell introduktion som förbinder en taurennovis med Lanka Farshot, den lokala klassinstruktören i Camp Narache.",al={"vad gör etched note","syftet med etched note","varför fick jag etched note"}},{q="Vem överlämnar meddelandet?",a="Grull Hawkwind lämnar över meddelandet och förklarar att ett sändebud från jägarinstruktören sökte upp den unge jägaren strax innan.",al={"vem ger etched note","uppdragsgivare för etched note","rohaku-meddelande"}},{q="Var finns Lanka Farshot?",a="Lanka Farshot finns i Camp Narache på Red Cloud Mesa, nära jägarträningsplatsen och redo att undervisa nya rekryter.",al={"var finns lanka farshot","hitta lanka farshot","lankas plats"}},{q="Varför är jägare så högt aktade bland tauren?",a="Jägare spelar en avgörande roll i taurens samhälle genom att skaffa mat, tyda den otämjda vildmarken och upprätthålla harmonin med slätternas andar.",al={"taurenjägarnas bakgrund","varför är taurenjägare viktiga"}},{q="Vilka färdigheter introduceras i träningen?",a="Lanka förbereder novisen med grundläggande jakttekniker, däribland bruket av avståndsvapen, förståelse för vilda bestar och till sist ritualerna som krävs för att tämja djurkamrater.",al={"vad lär lanka ut","grunderna för taurenjägare"}},{q="Vad är nästa steg efter att ha läst meddelandet?",a="När du anmäler dig hos Lanka Farshot fullföljer du kallelsen och får honom som tränare. Han lär dig att skjuta med gevär, tämja ett husdjur och mer allt eftersom du utvecklas.",al={"nästa uppdrag efter etched note","fortsättning på etched note"}}},fx={["69749d8d"]={q="Varför ger Grull Hawkwind dig den etsade lappen?",a="Grull Hawkwind vidarebefordrar bara ett meddelande från en budbärare som skickats genom Camp Narache. Lanka Farshot, lägrets jaktinstruktör, skickade budbäraren särskilt för att leta upp dig när du blev vuxen. Grull ser bara till att kallelsen når dig utan dröjsmål, så att du kan börja träna ordentligt bland ditt folk.",al={"varför ger rohaku en lapp","rohaku stonehoofs motiv","varför gav rohaku mig det här"}}},fp="11,145,21.280.0,23.299.0,39.96.0,22.126.0,31.116.0,44.94.0,41.124.0,45.135.0"}
P.entries["quest:3094"] = {n="Verdant Note",s="Verdant Note är en formell kallelse som når lovande unga tauren på Red Cloud Mesa. Grull Hawkwind har fått i uppdrag att överlämna meddelandet, som uppmanar blivande beskyddare av vildmarken att söka upp druidmentorn Gart Mistrunner i Camp Narache.",h="Verdant Note är en formell kallelse som når lovande unga tauren på Red Cloud Mesa.",kw={"camp narache","druid","jordemodern","gart mistrunner","grull hawkwind","mulgore","red cloud mesa","verdant note"},ang={["class:Druid"]="Denna kallelse markerar druidens första steg mot att kanalisera Azeroths vilda energier och oroliga andar.",["faction:Horde"]="Taurendruiderna är den främsta länken mellan den moderna Horden och Kalimdors naturmysterier, och ger fraktionen andlig balans vid sidan av dess råa militära styrka.",["race:Tauren"]="För tauren är druidism inte bara en magiskola, utan ett heligt förbund som ärvts från deras mytiska hängivenhet till Jordemodern."},sec={{t="En kallelse till stigen",b="Unga tauren som tar sina första steg in i sitt ansvar på Red Cloud Mesa blir snabbt uppmärksammade för sina naturliga gåvor. Grull Hawkwind överlämnar detta meddelande på uppdrag av en budbärare som sänts av Gart Mistrunner. Anteckningen är en inbjudan till taurernas uråldriga druidseder och kallar den invigde bort från enkla bysysslor för att lyssna till slätternas viskande balans."},{t="Jordemoderns röster",b="När den unge druideleven svarar på kallelsen varnar Gart Mistrunner för att förfädernas och naturens andar har blivit oroliga i Mulgore. Taurendruider ska verka som naturens levande avatarer och upprätthålla harmonin med Jordemoderns vilja, oavsett rivaliteter långt borta. Även om Night Elf utövar druidkonster varnar Gart för att deras högmod gör dem blinda för taurernas egen djupa samhörighet med naturen."}},faq={{q="Vad är Verdant Note?",a="Det är en inledande kallelse till unga taurendruider i Camp Narache. Den uppmanar mottagaren att söka upp den lokala tränaren Gart Mistrunner och påbörja strukturerad träning i druidkonsterna.",al={"verdant note","druidbrev","mulgore druideuppdragsanteckning"}},{q="Vem överlämnar anteckningen till spelaren?",a="Grull Hawkwind räcker anteckningen till den unge druideleven och nämner att en budbärare som sänts av Gart Mistrunner nyligen letade efter dem.",al={"vem ger verdant note","verdant note uppdragsstart"}},{q="Var finns Gart Mistrunner?",a="Gart Mistrunner finns i Camp Narache, under lä av lägrets naturliga klippor, där han ansvarar för träningen av nybörjare bland taurendruiderna.",al={"gart mistrunners plats","var finns gart"}},{q="Varför varnar Gart Mistrunner för Night Elf?",a="Båda folken vördar naturen och utövar druidism genom Cenarion Circle, men Gart anser att Night Elfs arrogans ofta färgar deras syn på andra kulturer. Han uppmanar sin elev att bortse från sådana attityder och helt fokusera på Jordemoderns visdom.",al={"tauren- och night elf-druider","night elfs druidhögmod"}},{q="Varför är andarna i Mulgore oroliga?",a="Gart Mistrunner känner hur störningar rör upp förfädernas och naturens andar över Mulgore slätter. Det är ett tidigt tecken på att den nya druidens livslånga ansvar blir att återställa balansen i vildmarken.",al={"oroliga andar i mulgore","varför är naturandarna arga"}},{q="Vilken förmåga lär Gart ut härnäst efter att uppdraget är slutfört?",a="När du rapporterar till Gart Mistrunner blir han den invigdes tränare och lovar att lära ut Jordemoderns gåvor allt eftersom eleven växer i visdom.",al={"vad händer efter verdant note","fortsättning på druiduppdrag"}}},fx={["92e5d696"]={q="Varför ger Grull Hawkwind dig Verdant Note?",a="En budbärare letade särskilt upp dig på Gart Mistrunners vägnar. Han är lägrets druivementor. Grull Hawkwind vidarebefordrar bara det brådskande meddelandet, så att du inte dröjer med att inleda din formella andliga träning under Garts ledning.",al={"varför ger rohaku en lapp","rohaku stonehoofs motiv","varför vill rohaku få det här gjort"}}},fp="12,134,21.325.0,25.337.0,25.124.0,36.117.0,35.126.0,54.146.0,40.157.0,62.144.0"}
P.entries["quest:3096"] = {n="Encrypted Scroll",s="Encrypted Scroll är en diskret kallelse till nyväckta Forsaken-skurkar i Deathknell. Shadow Priest Sarvis lämnar över chiffermeddelandet, som hänvisar rekryten till David Trias, en skurkmentor som verkar i det tysta på det lokala värdshuset.",h="Encrypted Scroll är en diskret kallelse till nyväckta Forsaken-skurkar i Deathknell.",kw={"david trias","deathknell","encrypted scroll","forsaken-skurk","shadow priest sarvis","shadowstalkers","tirisfal glades"},ang={["class:Rogue"]="Detta meddelande markerar din formella invigning i Forsakens hemliga nätverk och överbryggar avståndet mellan ett nyuppståndet lik och en blivande hemlig agent.",["race:Undead"]="Medan de nybildade Forsaken försvarar Tirisfal Glades mot Scourge och de levande som finns kvar är spejare och hemliga agenter avgörande för den Mörka Damens överlevnadsstrategi."},sec={{t="En tyst kallelse",b="Medan nyväckta Forsaken strider mot viljelösa zombier på kyrkogården lägger samhällets ledare märke till dem som har särskild fallenhet för smygande och list. Shadow Priest Sarvis lämnar över det förseglade pergamentet till lovande spejare när de har visat sig redo. Med David Trias diskreta sigill fungerar det som en tidig introduktion till det skuggiga nätverk som verkar under Forsakens hierarki."},{t="Ögon i skuggorna",b="David Trias håller uppsikt över vägskälet och värdshuset i Deathknell och spanar efter lämpliga kandidater för framtida hemliga uppdrag. Forsaken söker inte vanliga tjuvar eller vårdslösa ficktjuvar, utan disciplinerade hemliga agenter som kan tjäna det unga kungariket. Trias antyder att skickliga skurkar så småningom kan fånga Shadowstalkers uppmärksamhet. Det är en särskild grupp bland Forsaken som värdesätter list, precision och fullständig lojalitet mot den Mörka Damen."}},faq={{q="Vad är syftet med Encrypted Scroll?",a="Rullen är en privat inbjudan till nyväckta Forsaken-skurkar. Shadow Priest Sarvis lämnar över den när du har visat vad du går för och hänvisar dig till David Trias för specialträning.",al={"vad är encrypted scroll","vad gör rullen","varför encrypted scroll"}},{q="Vem är David Trias?",a="David Trias är skurkstränaren som finns på värdshuset i Deathknell. Han bedömer nya rekryter och spanar efter möjliga agenter till Forsakens större underrättelseoperationer.",al={"david trias","vem är trias","skurkstränare deathknell"}},{q="Vilka är Shadowstalkers som Trias nämner?",a="Shadowstalkers är en organisation av Forsaken-smygare och lönnmördare. Trias varnar nya skurkar för att Shadowstalkers bara rekryterar begåvade och disciplinerade agenter, inte klumpiga ficktjuvar.",al={"vilka är shadowstalkers","shadowstalkers forsaken","shadowstalkers"}},{q="Varför är meddelandet krypterat?",a="Forsaken-skurkar värdesätter hemlighetsmakeri och säkerhet under uppdrag. Genom att hänvisa kandidater med krypterade meddelanden skyddas känslig kommunikation från nyfikna ögon i en utsatt bosättning som Deathknell.",al={"varför krypterad","varför chiffer"}},{q="Var hittar du Shadow Priest Sarvis?",a="Shadow Priest Sarvis ansvarar för det första mottagandet av nya Forsaken i den centrala kryptan och kapellbyggnaden i Deathknell i Tirisfal Glades.",al={"var finns sarvis","sarvis plats","hitta shadow priest sarvis"}},{q="Var finns David Trias?",a="David Trias står inne i den skadade värdshusbyggnaden, strax nedför stigen från det centrala kapellet i Deathknell.",al={"var finns trias","david trias plats","värdshusets tränare i deathknell"}}},fp="16,154,15.339.0,19.365.0,44.173.0,19.145.0,46.129.0,29.171.0,39.137.0,29.91.0"}
P.entries["quest:3097"] = {n="Hallowed Scroll",s="Hallowed Scroll är en kallelse till nyvaknade Forsaken-präster i Deathknell. Shadow Priest Sarvis överlämnar brevet, som kallar novisen till Dark Cleric Duesten i byns raserade kapell för att lära sig hur de odöda brukar tron efter döden.",h="Hallowed Scroll är en kallelse till nyvaknade Forsaken-präster i Deathknell.",kw={"dark cleric duesten","deathknell","forsaken-präst","hallowed scroll","prästuppdrag","shadow priest sarvis","tirisfal glades"},ang={["class:Priest"]="Det här uppdraget är din filosofiska invigning i Forsaken-prästerskapet. Du förkastar traditionell fromhet och tar till dig självständighet, lidande och skuggmagi.",["race:Undead"]="Brevet visar Forsakens världsbild: avskurna från sin gamla mänskliga tro överlever de helt genom järnvilja och ömsesidigt beroende."},sec={{t="En kallelse i Deathknell",b="När nyvaknade odöda stapplar upp ur gravarna i Deathknell är de ofta omtumlade av pesten, döden och den plötsliga friheten från Lich Kings grepp. För dem som en gång var hängivna följare av Holy Light är förvirringen särskilt djup. Medan de nyvakna odöda kämpar mot den tanklösa Scourge som hemsöker bosättningens utkanter tar Shadow Priest Sarvis emot inkommande meddelanden. Med Dark Cleric Duestens sigill kallar Hallowed Scroll nyuppståndna präster att sluta irra omkring och infinna sig i stadens vanhelgade kapell."},{t="En ny syn på tron",b="När novisen lämnar över brevet möter hen Forsaken-prästerskapets hårda teologi. Dark Cleric Duesten lindar inte in orden: Holy Light övergav dem i döden, förfädernas andar är tomma sagor och demoner från andra plan bryr sig inte om deras lidande. I stället lär Forsakens präster att ren viljestyrka och radikal självständighet är de enda sanna källorna till frälsning. Under Duestens ledning lär sig nyuppståndna utövare att kanalisera både gudomlig disciplin och skugga. De brukar kraften inte av hängivenhet till avlägsna gudar, utan av en orubblig övertygelse om att de själva måste överleva."}},faq={{q="Vad är Hallowed Scroll?",a="Det är ett förseglat dokument som Shadow Priest Sarvis ger till nyuppståndna Forsaken-präster i Deathknell. Det instruerar dem att söka upp Dark Cleric Duesten i stadens kapell för att inleda sin formella prästutbildning.",al={"hallowed scroll","föremålet scroll","prästscroll"}},{q="Vem skickar brevet till spelaren?",a="Brevet bär Dark Cleric Duestens personliga sigill. Han är Forsaken-präst och mentor i Deathknells kapell, men det är Shadow Priest Sarvis som överlämnar det till dig.",al={"vem skickade brevet","duestens scroll","sarvis brev"}},{q="Kan Forsaken fortfarande bruka Holy Light?",a="Dark Cleric Duesten säger till de nya prästerna att Holy Light inte längre angår dem. Som han förklarar överger de traditionell vördnad för Ljuset och sätter i stället sin tro till sig själva och sin förmåga att bemästra skuggan.",al={"odöda använder ljuset","forsakens holy light","kan odöda kasta ljusmagi"}},{q="Var finns Dark Cleric Duesten?",a="Han finns inne i den raserade kyrkan mitt i Deathknell, i västra Tirisfal Glades, nära andra Forsaken-tränare.",al={"hitta duesten","duestens plats","var finns cleric duesten"}},{q="Varför avfärdar Duesten förfäder och demoner?",a="Duesten vill beröva de nyuppväckta odöda alla illusioner. Han säger att Ljuset inte längre angår dem, att förfädernas andar är sagor och att varelserna i Nether inte vill ha med dem att göra. I stället lär han att Forsaken har överlevt enbart genom viljestyrka.",al={"duestens tal","sagor","nether vill inte ha dig"}},{q="Vad händer efter att du läst brevet?",a="Du läser pergamentet och infinner dig hos Dark Cleric Duesten i Deathknells kapell. Då låser du upp dina första prästerliga förmågor och får honom som tränare i startområdet.",al={"hallowed scrolls mål","lämna in scrollen"}}},fp="15,218,23.456.0,15.447.0,28.167.0,35.107.0,40.195.0,37.133.0,46.241.0,38.163.0"}
P.entries["quest:3098"] = {n="Glyphic Scroll",s="Glyphic Scroll är en officiell kallelse till nyväckta Forsaken-magiker i Deathknell. Pergamentet bär magiläraren Isabellas sigill och uppmanar lovande utövare av arkan magi att söka upp henne i byns skändade kyrka för att tygla sina instabila krafter.",h="Glyphic Scroll är en officiell kallelse till nyväckta Forsaken-magiker i Deathknell.",kw={"arkan magi","deathknell","forsaken-magiker","glyphic scroll","isabella","magilärare","tirisfal glades"},ang={["class:Mage"]="Det här pergamentet markerar din formella invigning bland Forsaken-magikerna och knyter ditt magiska hantverk direkt till ditt nybefriade folks överlevnad och återuppståndelse.",["race:Undead"]="Forsaken-magiker brukar arkan magi med mörka avsikter. För dem är magi inget lärdomsspel från Dalaran, utan ett oumbärligt vapen för att återta sitt stulna hemland."},sec={{t="En kallelse till arkan magi",b="När en nyuppväckt Forsaken visar fallenhet för arkan magi medan hen rensar området kring Deathknell från viljelösa Scourge, väcker det snabbt de äldres uppmärksamhet. Glyphic Scroll överlämnas personligen och bär Isabellas magiska sigill. Hon är den lokala magiläraren. Pergamentet uppmanar den nyväckta utövaren att inställa sig hos henne i den förstörda kyrkan. Okontrollerad magisk begåvning är lika farlig för Forsaken som för deras fiender."},{t="Magi i odödlighetens grepp",b="I Deathknells förstörda kapell lär Isabella sina nybörjare att döden inte har befriat dem från arkanmagiens faror. Döden har visserligen befriat dem från kroppsliga svagheter, men magins instabila lockelse och fördärvande natur är lika starka som någonsin. För Forsaken är strävan efter arkan överlägsenhet inte bara en intellektuell sysselsättning, utan ett redskap för överlevnad och hämnd. Den hjälper dem att återta sitt öde och krossa alla som hotar deras bräckliga återtagande av Lordaeron."}},faq={{q="Vad är Glyphic Scroll?",a="Glyphic Scroll är ett instruktionsbrev med Isabella personliga sigill. Hon är magiläraren för Forsaken i Deathknell. Brevet instruerar nyväckta magiker att bege sig till den förstörda kyrkan för att fördjupa sina studier i arkan magi.",al={"uppdraget glyphic scroll","vad är det här pergamentet","pergament från deathknell"}},{q="Vem skickar Glyphic Scroll till dig?",a="Isabella, magiläraren i Deathknell, skickar pergamentet till dig när du har visat vad du går för genom att ta hand om de viljelösa Scourge i närheten.",al={"vem skickade pergamentet","vem skrev glyphic scroll","avsändaren av glyphic scroll"}},{q="Var finns Isabella?",a="Isabella håller till inne i den förstörda bykyrkan mitt i Deathknell. Där finns också andra klasslärare som vägleder nyväckta Forsaken.",al={"var finns isabella","hitta isabella","var finns magiläraren i deathknell"}},{q="Varför varnar Isabella dig för magiskt fördärv?",a="Isabella varnar för att den arkana kraftens instabila natur är oförändrad, trots att Forsaken är odöda. Magi innebär fortfarande en ständig risk för fördärv och beroende. Det krävs disciplin och viljestyrka för att bemästra den utan att uppslukas av den.",al={"magiskt fördärv och odöda","lore om arkan magi och fördärv","varför är magi farlig för odöda"}},{q="Varför är arkan magi viktig för Forsaken i Deathknell?",a="Forsaken-magiker ser arkan kraft som ett livsviktigt redskap för att återta Lordaeron och säkra sin självständighet mot de viljelösa Scourge, fientliga levande dödliga och Scarlet Crusade.",al={"varför använder forsaken magi","lore om odöda magiker"}},{q="Kan alla Forsaken-klasser få det här pergamentet?",a="Nej. Glyphic Scroll ges enbart till Forsaken-magiker som en inledande kallelse till deras främsta klasslärare i Deathknell.",al={"är glyphic scroll bara för magiker","kan häxmästare få glyphic scroll","vem får glyphic scroll"}}},fp="14,157,23.347.0,25.403.0,27.173.0,36.114.0,26.130.0,52.134.0,60.153.0,43.102.0"}
P.entries["quest:3099"] = {n="Tainted Scroll",s="The Tainted Scroll är ett tidigt uppdrag i Deathknell som leder nyvaknade Forsaken warlocks till deras tränare, Maximillion. I brevet uppmanar Maximillion novisen att omfamna makt och mörk tjänstgöring för att säkra verklig frihet.",h="The Tainted Scroll är ett tidigt uppdrag i Deathknell som leder nyvaknade Forsaken warlocks till deras...",kw={"deathknell","forsaken","maximillion","scourge","sylvanas","tainted scroll","tirisfal glades","warlock"},ang={["class:Warlock"]="Maximillion inviger nyvaknade Forsaken warlocks i Deathknell och framställer demonologi och underkuvande som det yttersta uttrycket för herravälde och frihet.",["race:Undead"]="Forsaken warlocks drar en mörk parallell mellan att bryta sig fria från Scourge och att söka upp demoniska tjänare att befalla över för sin egen överlevnad."},sec={{t="En mörk kallelse",b="Kort efter att nyuppståndna Forsaken börjar röja undan tanklösa rester av Scourge kring Deathknell anländer ett olycksbådande brev med Maximillions sigill, den lokala warlock-tränaren. Rullen uppmanar mottagaren att begrunda tjänstgöringens och självständighetens natur innan hen återvänder till den förstörda bosättningen för att tala med honom direkt."},{t="Kontrollens filosofi",b="När Maximillion svarar på kallelsen avslöjar han sin filosofi om makt och underkuvande. Han har brutit sig fri från Lich Kings tanklösa grepp och hävdar att en slav förblir slav oavsett vem mästaren är, om slaven inte tar sann makt. Enligt honom är det inte förräderi mot Sylvanas att kuva demoniska tjänare, utan den naturliga kulmen på Forsakens kamp för självbestämmande och respekt."}},faq={{q="Vem skickade The Tainted Scroll?",a="Rullen levereras med Maximillions personliga sigill. Han är warlock-tränaren i Deathknell och söker upp nyvaknade utövare av den mörka konsten.",al={"vem skickar tainted scroll","vem gav mig tainted scroll","tainted scroll avsändare"}},{q="Vem är Maximillion?",a="Maximillion är warlock-tränaren i Deathknell. Han lär nyuppståndna Forsaken den mörka konsten att frambesvärja och kontrollera demoniska väsen.",al={"vem är maximillion","maximillion deathknell","warlock-tränare deathknell"}},{q="Vad står det i The Tainted Scroll?",a="Rullen är ett brev till nyvaknade warlocks som begrundar frihet, makt och tjänstgöringens natur. Den uppmanar läsaren att besöka Maximillion för djupare undervisning.",al={"vad är tainted scroll","vad står det i rullen","rullens budskap"}},{q="Är Maximillion en förrädare mot Lady Sylvanas?",a="Maximillion säger uttryckligen att han inte är någon förrädare mot Lady Sylvanas. Han hävdar att Banshee Queen skulle uppskatta hans synsätt och menar att hennes egen strävan efter självbestämmande bröt deras bojor från Scourge.",al={"är maximillion en förrädare","förråder maximillion sylvanas","maximillions lojalitet"}},{q="Var hittar jag Maximillion?",a="Maximillion finns i Deathknell, den förstörda bosättningen i Tirisfal Glades där nyuppståndna Forsaken först stiger upp ur sina gravar.",al={"var hittar man maximillion","maximillions plats"}},{q="Vad är syftet med uppdraget?",a="Uppdraget är en inledande kallelse för nyuppståndna Forsaken warlocks. Det inleder deras klassutbildning och leder dem till deras lokala mentor i Deathknell.",al={"varför warlock-uppdraget tainted scroll","tainted scroll syfte"}}},fp="14,258,14.340.0,25.413.1,28.171.0,19.148.0,38.178.0,42.202.0,29.134.0,34.176.0"}
P.entries["quest:31"] = {n="Aquatic Form",s="Det här uppdraget markerar sista steget på en ung Horde-druids väg mot att bemästra vattnet. Efter att ha visat sig värdig och knutit an till sjölejonets aspekt i Moonglade återvänder druiden hem till Thunder Bluff för att få ett formellt erkännande och bemästra sin vattenform.",h="Det här uppdraget markerar sista steget på en ung Horde-druids väg mot att bemästra vattnet.",kw={"vattenform","dendrite starblaze","druid","moonglade","pendant of the sea lion","sjölejon","thunder bluff","turak runetotem"},ang={["class:Druid"]="När du uppnår din vattenform knyts land och hav samman, så att du obehindrat kan ta dig genom vatten och fly från rovdjur i djupet.",["faction:Horde"]="Tauren-druider står för Hordes andliga band till Cenarion Circle och rör sig mellan uråldriga neutrala fristäder och sina egna stamhuvudstäder.",["race:Tauren"]="Turak Runetotem påminner dig om att mästerskap över havets bestar hedrar dina förfäder och befäster taurenfolkets heliga återkomst till druidernas vägar."},sec={{t="Sjölejonets återkomst",b="Efter att ha klarat prövningarna i Moonglades heliga tillflyktsort hänvisas en tauren-druid i vardande tillbaka till Mulgore av Dendrite Starblaze. Med Pendant of the Sea Lion i sin ägo bär novisen ett fysiskt bevis på sin balans och hängivenhet genom Kalimdors vatten. Den är ett konkret bevis på att novisen har respekterat de uråldriga traditioner som krävs för att anta en vattenaspekt."},{t="Gemenskap med vattnet",b="När resenären har tagit sig upp till Thunder Bluffs höjder visar hen hänget för sin mentor, Turak Runetotem. Turak gläds åt att novisen har hedrat sina förfäder och funnit balans med naturen, och lär ut hemligheten bakom vattenformen. Med denna kunskap får druiden den medfödda förmågan att glida ner under floder och hav, andas fritt och ta sig fram i djupen som en havsvarelse."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här uppdraget avslutar övergångsriten för unga Horde-druider. De kan lämna in sitt välförtjänta Pendant of the Sea Lion i Thunder Bluff och till slut låsa upp sin skepnadsskiftande vattenform.",al={"varför göra det här uppdraget","vattenformens syfte","vad gör det här uppdraget"}},{q="Till vem ska jag ta Pendant of the Sea Lion?",a="Du måste ta hänget till Turak Runetotem, druidtränaren som finns på Thunder Bluffs övre avsatser i Mulgore.",al={"vem lämnar man in det till","var lämnar man in vattenform","turak runetotems plats"}},{q="Vem skickar dig tillbaka till Thunder Bluff?",a="Dendrite Starblaze, en Night Elf-druidvaktare i Moonglades neutrala fristad, skickar dig tillbaka när dina vattenprövningar är avklarade.",al={"vem ger uppdraget om vattenform","dendrite starblazes uppdrag"}},{q="Kan andra än druider slutföra det här uppdraget?",a="Nej. Den här uppdragskedjan är endast för druider och ingår i deras andliga och magiska utveckling mot att låsa upp djurformer.",al={"är det här bara för druider","kan andra klasser få vattenform"}},{q="Varför hjälper en Night Elf i Moonglade en Horde-druid?",a="Moonglade är en neutral fristad som övervakas av Cenarion Circle. När Night Elf-mentorer lär ut Cenarion-vägens uråldriga konster vägleder de tauren-druider utan politisk fientlighet och fokuserar helt på att bevara naturens balans.",al={"varför hjälper dendrite horde","moonglade horde alliance","druidernas neutralitet"}},{q="Vilken förmåga får man när man slutför det här uppdraget?",a="När du lämnar in uppdraget till Turak Runetotem lär du dig vattenform. Den ger ökad simhastighet och låter dig andas under vatten när du är skepnadsskiftad.",al={"vilken form får jag","vattenformsbesvärjelse","vattenform"}}},fx={["269933c9"]={q="Varför skickar Dendrite Starblaze dig tillbaka till Thunder Bluff?",a="Dendrite Starblaze övervakar dina prövningar i Moonglade på uppdrag av Cenarion Circle, men Moonglade är en fristad för undervisning, inte ditt hem. Du har visat din uthållighet och vördnad för vattnet, och Dendrites uppgift är slutförd. Han skickar dig tillbaka till din lokala mentor, Turak Runetotem på Elder Rise i Thunder Bluff, så att du kan visa upp bevis på dina riter och få den slutliga välsignelsen som ger dig vattenformen.",al={"varför skicka mig till turak","dendrite starblazes motiv","varför återvända till thunder bluff"}}},fp="12,200,22.290.0,25.337.0,34.148.0,46.114.0,36.86.0,35.108.0,53.187.0,46.101.0"}
P.entries["quest:310"] = {n="Bitter Rivals",s="Bitter Rivals är ett tidigt Alliance-uppdrag i Dun Morogh, sprunget ur den hårda konkurrensen mellan två stolta dvärgfamiljer som brygger öl.",h="Bitter Rivals är ett tidigt Alliance-uppdrag i Dun Morogh, sprunget ur den hårda konkurrensen mellan två...",kw={"barleybrew scalder","bitter rivals","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew distillery"},ang={["class:Rogue"]="Att ta sig in i en bevakad källare, distrahera vakten och i smyg byta ut smuggelgods är välbekant arbete för varje skurk, även när bytet är öl i stället för guld.",["faction:Alliance"]="Kharanos är Dun Moroghs kulturella och logistiska nav för Alliance-resenärer, så tvister på lokala värdshus blir ofta ett välkommet avbrott för rekryter på genomresa.",["race:Dwarf"]="För dvärgar är bryggning en allvarlig sak som står smide i anseende. Att dras in i ett källarbråk om rivaliserande öl känns helt rätt bland Dun Moroghs snöar."},sec={{t="En smak av konkurrens",b="Få saker i Khaz Modan väcker känslor lika snabbt som en stop öl. Barleybrew-familjen har länge stått i skuggan av det berömda Thunderbrew Distillery i Kharanos. Marleth Barleybrew medger motvilligt att Thunderbrews brygder håller god kvalitet, men hon står inte ut med tanken på att de skulle vara det enda berömda ölet i Dun Morogh. För att förändra den lokala smaken smider hon en plan: att byta ut ett fat Thunder Ale mot sin egen eldiga blandning, Barleybrew Scalder."},{t="List i källaren",b="För att genomföra planen måste du smyga rakt under näsan på gästerna i Kharanos. Under destilleriets kök ligger källarförrådet, där lagrade fat väntar på att tappas upp. Eftersom Thunderbrews har en vakt vid sitt mest värdefulla förråd måste en blivande sabotör hitta ett sätt att locka bort vakten innan faten byts ut i hemlighet."}},faq={{q="Vem ger uppdraget Bitter Rivals?",a="Marleth Barleybrew ger uppdraget. Hon är fast besluten att bevisa att familjens brygder kan mäta sig med de berömda dryckerna på Thunderbrew Distillery.",al={"vem startar bitter rivals","marleth uppdragsgivare"}},{q="Var ligger Thunderbrew-källaren?",a="Källaren ligger under Thunderbrew Distillery i byn Kharanos. Trappan ner är undangömd bakom ett bord i köket.",al={"var ligger thunderbrew-källaren","hur hittar jag destilleriets källare"}},{q="Vad är Barleybrew Scalder?",a="Barleybrew Scalder är Marleth Barleybrews starka husöl. Hon tror att gästerna i Kharanos till slut kommer att inse hur överlägsen hennes bryggkonst är om de får smaka den under täckmanteln Thunder Ale.",al={"barleybrew scalder","vilken öl ska jag byta ut"}},{q="Hur tar du dig förbi vakten som håller uppsikt över faten?",a="Thunderbrew-vakten som står nere i källaren ger ledtrådar om vad som kan fånga hans uppmärksamhet. Det ger dig precis tillräckligt med tid för att byta ut faten medan han är distraherad.",al={"distrahera källarvakten","obevakat thunder ale-fat","fatvakt"}},{q="Varför ligger Barleybrew-familjen och Thunderbrew-familjen i fejd?",a="Det handlar om dvärgarnas yrkesstolthet. Thunderbrews dominerar kroglivet i Kharanos, och Barleybrew-familjen vill bevisa att deras egna recept är minst lika bra, om inte bättre.",al={"bryggarfejd","varför hatar barleybrew thunderbrew"}},{q="Vilket uppdrag följer efter Bitter Rivals?",a="När fatet med Barleybrew Scalder är på plats leder uppdraget direkt vidare till Return to Marleth, där du rapporterar att du lyckats.",al={"nästa uppdrag efter bitter rivals","vad kommer efter bitter rivals"}}},fx={["6a423fcc"]={q="Varför vill Marleth Barleybrew byta ut ölfaten?",a="Marleth Barleybrew är inblandad i en hård och långvarig tävlan med Thunderbrew-klanen om vem som brygger Dun Moroghs bästa öl. Motvilligt medger hon att Thunderbrews gör en hyfsad dryck, men hon står inte ut med deras skryt och vill bevisa att hennes egen Barleybrew Scalder är överlägsen. Genom att smuggla in sin tunna i Thunderbrew Distillerys källare hoppas hon att deras egna trogna stamgäster ska dricka den, inse hur god den är och sätta Thunderbrews på plats.",al={"varför byta fat","marleths motiv","varför byta brygd"}},["41e8c9ba"]={q="Varför behöver Marleth Barleybrew dig i stället för att göra det själv?",a="Marleth är alldeles för välkänd i Kharanos för att obemärkt kunna smyga in i sin rival källare. Thunderbrew Distillery håller noga uppsikt över sin vinkällare, och om någon känner igen en Barleybrew slås larm direkt. Som obekant resenär kan du smyga in i destilleriet, hitta ett sätt förbi källarvakten och byta ut tunnorna utan att genast avslöja hela planen.",al={"varför kan inte marleth göra det","varför jag i bitter rivals","varför anlita en utomstående"}}},fp="13,126,22.247.0,17.190.0,34.129.0,40.109.0,27.156.0,49.134.0,49.172.0,33.94.0"}
P.entries["quest:3100"] = {n="Simple Letter",s="Simple Letter är en första instruktion som visar nybörjarkrigare till tränaren Llane Beshere i Northshire Abbey. Den markerar starten på deras formella stridsutbildning och uppmanar dem att hjälpa dalens nödställda invånare.",h="Simple Letter är en första instruktion som visar nybörjarkrigare till tränaren Llane Beshere i Northshire...",kw={"elwynn forest","knights of the silver hand","llane beshere","northshire abbey","northshire valley","simple letter","krigartränare"},ang={["class:Warrior"]="Llane Beshere är krigartränaren i Northshire Abbey. Därför är det här brevet den första kallelsen till stridsdisciplin för nyanlända kämpar.",["faction:Alliance"]="Även i den relativa tryggheten under Silver Hands beskydd kallas nyrekryter omedelbart att hjälpa alliansens nödställda invånare.",["race:Human"]="Northshire Abbey är vaggan för mänskliga äventyrare som ger sig ut i Elwynn Forest, där lokala rekryter får sina första instruktioner."},sec={{t="En uppmaning till vapen",b="Simple Letter är en första introduktion för blivande krigare som anländer till Northshire Valley. Brevet är adresserat till Llane Beshere, den lokale krigartränaren i Northshire Abbey, och uppmanar nyanlända kämpar att ta kontakt med sin instruktör, bekanta sig med omgivningen och förbereda sig på stridslivets krav."},{t="Trygga dalen",b="Northshire Abbey skyddas av Knights of the Silver Hand, men dalens fridfulla yta döljer djupare problem. När Beshere tar emot brevet berättar han att invånarna i trakten står inför många svårigheter som kräver dugliga beskyddare. Därför uppmanar han nykomlingarna att bemästra sina vapen och träda fram till rikets försvar."}},faq={{q="Vad är Simple Letter?",a="Simple Letter är ett introduktionsbrev som krigare i Northshire Valley får när de återvänder från koboldlägren. Det ber dem presentera sig för den lokale krigartränaren Llane Beshere för att inleda sin formella stridsutbildning.",al={"vad är simple letter","uppdraget simple letter","startbrev för mänsklig krigare"}},{q="Vem är Llane Beshere?",a="Llane Beshere är krigartränaren i Northshire Abbey. Han lär nybörjarkrigare stridstekniker och välkomnar rekryter som anländer till dalen med order eller rekommendationer om att söka upp honom.",al={"vem är llane beshere","beshere plats","var finns krigartränaren i northshire"}},{q="Var lämnar jag Simple Letter?",a="Brevet lämnas direkt till Llane Beshere, som finns i Northshire Abbey i Northshire Valley, omgiven av de skyddade markerna under den heliga ordens beskydd.",al={"var lämnar jag in simple letter","lämna in simple letter","llane beshere plats"}},{q="Vilken roll spelar Knights of the Silver Hand i Northshire?",a="Knights of the Silver Hand hjälper till att skydda Northshire Valley och håller klostret och dess närmaste omgivningar relativt trygga. Där kan rekryter, bönder och präster sköta sina sysslor trots de växande spänningarna i trakten.",al={"vad gör paladiner i northshire","silver hand i northshire abbey","paladiner i elwynn"}},{q="Varför behöver invånarna hjälp?",a="Även om klostret självt är ganska välförsvarat utsätts invånarna ständigt för intrång och brist på förnödenheter. Beshere råder nyanlända att utforska trakten och använda sin stridsstyrka för att hjälpa dem som behöver det.",al={"varför vill beshere att jag hjälper invånarna","problem i northshire","vem behöver hjälp i northshire"}},{q="När ska jag återvända till Llane Beshere efter att ha lämnat brevet?",a="Llane Beshere finns tillgänglig i klostret dag och natt, redo att undervisa krigare när de får stridserfarenhet och behöver mer avancerade stridsfärdigheter.",al={"när ska jag återvända till llane beshere","mer krigarträning i northshire","beshere träning"}}},fp="13,241,14.355.0,19.380.0,26.249.0,21.213.0,37.176.0,63.220.0,49.217.0,66.154.0"}
P.entries["quest:3101"] = {n="Consecrated Letter",s="Consecrated Letter är en inledande kallelse som bärs av Heliga ljusets noviser när de anländer till Northshire Valley. Den uppmanar mottagaren att söka upp sin klassinstruktör vid Northshire Abbey för att påbörja sin utbildning och omfamna sin roll som en synlig symbol för tron.",h="Consecrated Letter är en inledande kallelse som bärs av Heliga ljusets noviser när de anländer till...",kw={"brother sammuel","consecrated letter","elwynn forest","heliga ljuset","northshire","northshire abbey","paladin","instruktör"},ang={["class:Paladin"]="Som utövare av Heliga ljuset har paladiner i uppdrag att företräda dess dygder och vara hoppets ledstjärnor för sina allierade i Northshire och bortom dess gränser.",["faction:Alliance"]="De som företräder Heliga ljuset förväntas uppföra sig hedervärt och värna Alliansens moraliska anseende och försvar.",["race:Human"]="För människor som inleder sin tjänst vid Northshire Abbey betonar brevet deras ansvar att vara hedervärda symboler i ett kungarike som plågas av de senaste prövningarna."},sec={{t="En helig kallelse",b="Consecrated Letter markerar den formella början på en novis resa i Northshire Valley. Dokumentet är riktat till nyanlända som utövar Heliga ljuset och kallar mottagaren att söka upp sin instruktör vid Northshire Abbey för att inleda sin utbildning och ta på sig sina skyldigheter inom kungariket Stormwind."},{t="Att bära ljuset",b="När novisen visar upp brevet påminns hen om tyngden i sitt kall. Heliga ljuset lyser synligt inom dem som kanaliserar det, vilket gör dem till omedelbara hoppets symboler för allierade och tydliga måltavlor för sina fiender. Instruktören betonar att sådan kraft kräver disciplinerat uppförande och medvetenhet om vilket föredöme man visar offentligt."},{t="Vägledning och disciplin",b="Utöver de andliga förpliktelserna etablerar brevet en fortlöpande relation mellan elev och mentor. När novisen prövar sin styrka mot de lokala hoten i Northshire förväntas hen regelbundet återvända till klostrets område för att fördjupa sina kunskaper om strid och gudomlig nåd."}},faq={{q="Vad är Consecrated Letter?",a="Consecrated Letter är en inledande kallelse riktad till en novis i Heliga ljuset i Northshire Valley. Brevet uppmanar mottagaren att söka upp sin klassinstruktör vid Northshire Abbey för att inleda sin utbildning och påminna sig om sina heliga plikter.",al={"vad är consecrated letter","uppdraget consecrated letter"}},{q="Varifrån kommer Consecrated Letter?",a="När en ny paladin återvänder från koboldlägren överlämnar någon vid Northshire Abbey brevet, som är förseglat med Brother Sammuel insignium och säger åt paladinen att träffa honom.",al={"vem ger consecrated letter","vem skickar consecrated letter"}},{q="Vem tar emot Consecrated Letter?",a="Brevet levereras till Brother Sammuel, paladinernas instruktör som är stationerad nära ingången till Northshire Abbey i Elwynn Forest.",al={"vem lämnar in consecrated letter","vem läser consecrated letter"}},{q="Vilken roll har instruktören efter att ha läst brevet?",a="Instruktören vägleder novisen i Heliga ljusets vägar och lär ut stridstekniker, skyddande välsignelser och heliga besvärjelser medan novisen skaffar sig praktisk stridserfarenhet i dalen.",al={"vad lär instruktören ut","varför träna med instruktören"}},{q="Varför nämner brevet att vara en symbol?",a="De som kanaliserar Heliga ljuset ses som synliga förebilder för tro och dygd. Både vänner och fiender känner igen Ljusets kraft, vilket gör dess utövare till framträdande personer vars uppförande återspeglar tron själv.",al={"varför är jag en symbol","heliga ljuset symbol"}},{q="Var äger utbildningen rum?",a="Northshire Abbey ligger i den fridfulla norra dalen i Elwynn Forest. Det tjänar som en fristad för tron och som den främsta rekryteringsplatsen för dem som försvarar kungariket Stormwind.",al={"var ligger northshire abbey","var ska jag lämna brevet"}}},fp="18,271,16.325.0,18.350.0,23.308.0,31.246.0,44.187.0,36.129.0,57.204.0,43.222.0,36.182.0"}
P.entries["quest:3102"] = {n="Encrypted Letter",s="Det krypterade brevet är en hemlig kallelse till lovande skurkar vid Northshire Abbey, förseglad med Jorik Kerridans insignier. Det presenterar nya agenter för deras tränare i de avskilda stallen och ger tidiga råd om hur de överlever farliga organisationers intressen, som SI:7 och Defias Brotherhood.",h="Det krypterade brevet är en hemlig kallelse till lovande skurkar vid Northshire Abbey, förseglad med Jorik...",kw={"defias brotherhood","krypterat brev","jorik kerridan","northshire abbey","northshire valley","skurkarnas tränare","si:7"},ang={["class:Rogue"]="Det krypterade brevet markerar en ung skurks första möte med Jorik Kerridan och den större undre världen. Det ger tidiga råd om hur man navigerar bland fraktioner som SI:7 och Defias utan att förlora sin självständighet.",["faction:Alliance"]="Även bakom Northshire Abbeys fromma murar rekryterar och tränar kungariket Stormwinds skuggagenter i tysthet lovande agenter inför de kommande konflikterna."},sec={{t="En diskret kallelse",b="Bakom Northshire Abbeys fridfulla och fromma fasad rekryteras och tränas hemliga förmågor i tysthet. Det krypterade brevet överlämnas till lovande nybörjare efter att de har hanterat de framryckande koboldskadedjuren, och bär Jorik Kerridans sigill. För att hålla saken borta från prästers och paladinders nyfikna blickar är brevet diskret adresserat och visar mottagaren vägen till en avskild mötesplats i stallen bakom klostret."},{t="Skuggor i Northshire",b="Jorik Kerridan håller till i stallen just för att det är tyst där och väcker föga uppmärksamhet. Han välkomnar nykomlingar som anländer obemärkt och slösar ingen tid på att förklara den hårda verklighet som väntar tjuvar och spejare ute i den större världen. Mäktiga organisationer, från Stormwinds kungliga underrättelsetjänst SI:7 till det upproriska Defias Brotherhood, söker ständigt efter smygande agenter. Jorik råder dem att värna sin självständighet framför allt och varnar nybörjare för att låta mäktiga syndikat köra med dem. Han påminner dem om att en slug skurk har alla trumf på hand."}},faq={{q="Vem skickade det krypterade brevet?",a="Brevet är förseglat med Jorik Kerridans personliga insignier. Han är skurkarnas tränare i Northshire Valley. Det delas ut till lovande nybörjare som återvänder efter att ha spanat på de närliggande koboldlägren.",al={"vem skickade krypterat brev","vem gav mig krypterat brev","vem skrev det krypterade brevet"}},{q="Var finns Jorik Kerridan?",a="Jorik Kerridan håller låg profil i det tysta stallet bakom Northshire Abbey. Han håller sig medvetet utom synhåll för att inte väcka oönskad uppmärksamhet kring sitt hemliga arbete.",al={"var finns jorik","var hittar man jorik kerridan","joriks plats"}},{q="Vad är syftet med det krypterade brevet?",a="Brevet är en diskret inbjudan till blivande skurkar att presentera sig för sin lokala tränare. Eftersom skurkar lever på hemlighetsmakeri krypteras korrespondensen för att hålla känsliga träningsärenden borta från nyfikna blickar omkring klostret.",al={"varför krypterat brev","vad är krypterat brev till för","varför är brevet krypterat"}},{q="Vilka organisationer vill rekrytera skurkar?",a="Enligt Jorik Kerridan åtrår olika fraktioner över hela Azeroth skickliga skurkars talanger. Bland dem finns äventyrssällskap, Stormwinds hemliga underrättelsetjänst SI:7 och till och med laglösa som Defias Brotherhood, som söker spioner i Stormwind.",al={"vem vill ha skurkar","fraktioner intresserade av skurkar","vem åtrår skurkars färdigheter"}},{q="Vilka råd ger Jorik Kerridan?",a="Jorik uppmanar dig att förbli dig själv och aldrig låta mäktiga grupper tvinga dig att arbeta mot din vilja. Han påminner skurkar om att de har trumf på hand innan spelet är över och betonar vikten av självständighet och försiktighet.",al={"joriks råd","vad säger jorik till dig","joriks råd till skurkar"}},{q="Varför håller Jorik Kerridan till i stallet?",a="Jorik föredrar de avskilda stallen bakom Northshire Abbey eftersom platsen är trevlig och tyst och väcker väldigt lite uppmärksamhet. Hemliga tränare och agenter föredrar att träffas utan att klostrets präster eller vakter märker det.",al={"varför gömma sig i stall","varför håller jorik till bakom klostret","varför vara i tysta stall"}}},fp="16,163,18.319.0,21.362.0,30.131.0,32.121.0,44.149.0,50.163.0,37.142.0,43.191.0"}
P.entries["quest:3103"] = {n="Hallowed Letter",s="Hallowed Letter är en formell kallelse som Marshal McBride ger lovande unga präster på uppdrag av Northshire Abbeys prästlärare, Priestess Anetta. Den markerar början på en blivande prästs formella vägledning i den Heliga Lärans grundsatser, mitt i en orolig och utsatt värld.",h="Hallowed Letter är en formell kallelse som Marshal McBride ger lovande unga präster på uppdrag av Northshire...",kw={"elwynn","hallowed letter","holy light","marshal mcbride","northshire abbey","präst","priestess anetta"},ang={["class:Priest"]="Det här uppdraget markerar din officiella inskrivning som elev i den Heliga Läran under Priestess Anetta. Det framställer din gudomliga magi som en viktig plikt att hela en splittrad värld.",["race:Human"]="Northshire Abbey har länge varit en fristad för tro och återhämtning i Stormwinds kungarike. Klostret håller fast vid sina traditioner trots oron som sprider sig omkring Elwynn."},sec={{t="En kallelse till prästlivet",b="Efter att ha visat sitt mod mot koboldlägren runt Northshire får novispräster ett brev med Priestess Anettas heliga sigill. Marshal McBride överlämnar brevet, som är en inbjudan att på allvar studera den Heliga Läran i klostrets stilla salar."},{t="En värld i nöd",b="När Priestess Anetta får brevet ser hon till att hennes nya elev förstår rikets dystra tillstånd. Kvarvarande hot från Burning Legion kastar långa skuggor över Azeroth, medan kontinenterna kämpar med nya sår och oroligheter. Enligt henne är prästyrket inte bara en akademisk hängivenhet, utan ett akut moraliskt ansvar att skänka läkedom och tröst åt en lidande värld."}},faq={{q="Vad är Hallowed Letter?",a="Det är ett förseglat brev med Priestess Anettas emblem, som Marshal McBride överlämnar till nyanlända mänskliga präster i Northshire Valley. Det uppmanar novisen att fullborda sin formella utbildning i Northshire Abbey.",al={"hallowed letter","prästernas introduktionsuppdrag northshire","anettas brev"}},{q="Vem skickar Hallowed Letter?",a="Priestess Anetta, prästläraren i Northshire Abbey, skriver och förseglar brevet. Hon ber Marshal McBride att överlämna det när novisen återvänder efter att ha spanat på koboldangreppet.",al={"vem skrev hallowed letter","vem skickade brevet"}},{q="Varför kallar Priestess Anetta till sig nya präster?",a="Anetta ser novisens kallelse till den Heliga Läran och vill vägleda utbildningen. Med faror som kvarlevor av Burning Legion kvar i världen betonar hon att det behövs disciplinerade helare och vägvisare omedelbart.",al={"varför vill anetta ha mig","brevets syfte"}},{q="Var hittar man Priestess Anetta?",a="Hon finns i Northshire Abbeys stora sal, redo att utbilda mänskliga präster medan de lär sig sina första böner och ritualer.",al={"var finns anetta","priestess anettas plats"}},{q="Vad händer när man överlämnar brevet till Priestess Anetta?",a="När Anetta har läst brevet och hälsats välkommen tar hon emot spelaren som sin elev. Hon delar med sig av grundläggande visdom och ber spelaren återvända för mer utbildning när erfarenheten växer.",al={"nästa uppdrag efter hallowed letter","vad följer efter hallowed letter"}},{q="Varför nämns Burning Legion i Northshire?",a="Tredje kriget är över, men demoniska rester från Legion hemsöker fortfarande Azeroth. Priestess Anetta nämner detta globala hot för att understryka de större faror som väntar äventyrare som lämnar dalen.",al={"burning legion northshire","varför talar anetta om demoner"}}},fp="15,209,22.225.0,15.307.0,28.212.0,30.191.0,45.214.0,36.128.0,61.169.0,50.184.0"}
P.entries["quest:3104"] = {n="Glyphic Letter",s="En förseglad kallelse når mänskliga magiker under utbildning i Northshire Valley, skickad av Marshal McBride. Khelden Bremen kallar lovande trollkarlar till Northshire Abbey för att inleda deras magiska utbildning.",h="En förseglad kallelse når mänskliga magiker under utbildning i Northshire Valley, skickad av Marshal McBride.",kw={"magi","elwynn forest","glyphic letter","khelden bremen","magiker","marshal mcbride","northshire abbey"},ang={["class:Mage"]="Som magiker inleder du din officiella lärlingstid i Stormwinds magiska konster under Khelden Bremen.",["race:Human"]="Som människa bär du Northshires arv av magisk energi, som sträcker sig tillbaka till Dalarans första mänskliga magiker och Kirin Tor, in i kungariket Stormwind."},sec={{t="En kallelse till magins värld",b="Marshal McBride ger det runmärkta brevet till en blivande lärling som visat sin förmåga genom att hjälpa honom mot lokala skadedjur. Khelden Bremen, Northshires magitränare, skrev det. Han håller utkik efter magisk disciplin och talang hos nya rekryter som anländer till klostret."},{t="Trollkonstens tyngd",b="Northshire Abbey har länge varit en fristad för det Heliga Ljuset, men Stormwinds faror kräver utövare av alla discipliner. Brevet leder dig uppför trappan till Khelden Bremen. Han slösar inte med beröm. I stället varnar han för att behärskning av magisk kraft innebär att trotsa naturens gränser, vilket väcker både djup respekt och stark fruktan hos vanligt folk."}},faq={{q="Vem delar ut Glyphic Letter?",a="Marshal McBride ger brevet till nyanlända magiker utanför Northshire Abbey efter att de hjälpt till att röja undan närliggande koboldskadedjur.",al={"vem ger glyphic letter","uppdragsgivare för glyphic letter"}},{q="Vem skrev Glyphic Letter?",a="Khelden Bremen, magitränaren som håller till i Northshire Abbeys övre rum, skrev och förseglade brevet.",al={"författare till glyphic letter","vem skickade glyphic letter"}},{q="Var hittar jag Khelden Bremen?",a="Gå in i Northshire Abbey bakom Marshal McBride, ta korridoren till vänster och gå sedan uppför trappan. Khelden väntar i de bakre rummen för att undervisa.",al={"khelden bremen plats","var finns khelden"}},{q="Varför finns magitränaren i ett kloster?",a="Northshire Abbey är en helig fristad, men Stormwind använder dalen för att utbilda försvarare i alla discipliner. Magilärare arbetar där sida vid sida med präster och marskalkar.",al={"varför finns magiker i northshire abbey","magitränare i heligt kloster"}},{q="Vad händer när jag lämnar in brevet?",a="Khelden Bremen tar emot dig som sin elev, välkomnar din beslutsamhet att utöva magi trots dess faror och erbjuder dig direkt tillgång till grundläggande magiträning.",al={"vad händer efter glyphic letter","nästa uppdrag efter glyphic letter"}},{q="Varför varnar Khelden för att magiker kommer att fruktas?",a="Magisk energi kan böja verkligheten och är oberäknelig. Khelden varnar för att jakten på den högsta kunskapen överskrider gränser som vanligt folk finner djupt oroande.",al={"varför fruktas magiker","khelden bremens dialog"}}},fp="14,175,23.276.0,22.332.0,32.124.0,29.99.0,31.137.0,44.164.0,41.157.0,48.155.0"}
P.entries["quest:3105"] = {n="Tainted Letter",s="I Northshire kallar Tainted Letter mänskliga nybörjarhäxmästare bort från klostervakterna för att undervisas i de brinnande legionernas konster. Drusilla La Salle anförtor det åt Marshal McBride, som lämnar det till hennes rekryter.",h="I Northshire kallar Tainted Letter mänskliga nybörjarhäxmästare bort från klostervakterna för att undervisas...",kw={"fördärv","drusilla la salle","elwynn forest","marshal mcbride","northshire abbey","tainted letter","twisting nether","häxmästare"},ang={["class:Warlock"]="Som häxmästare får du formell undervisning i Northshire, samtidigt som du undviker vakternas granskning och lär dig bemästra farlig magi från Nether.",["race:Human"]="Som människa lever du i en kultur som vördar det heliga ljuset och Kirin Tors disciplinerade magi. Häxmästare utför sina kallelser i tysthet i utkanten av bosättningar som Northshire."},sec={{t="En diskret kallelse",b="Nybörjarhäxmästare får ett brev från Marshal McBride efter att ha visat vad de går för mot koboldhotet. Präster och paladiner studerar öppet i Northshire Abbey, men häxmästare måste gå försiktigt fram. Drusilla La Salles sigill pryder brevet, som uppmanar varje spirande trollkarl att söka upp hennes avskilda postering utanför klostrets huvudmurar innan andra uppgifter tar vid."},{t="Frestelse och ambition",b="Drusilla varnar för att häxmästare vandrar en vansklig väg under Stormwinds vakande vakter, som hon kallar ”patetiska dödliga”. Att hämta kraft från Twisting Nether och umgås med demoner innebär alltid risk för fördärv. Hon råder till tålamod, försiktighet och stark självbehärskning när man hanterar dessa mörka krafter, men säger att försiktigheten inte får släcka en häxmästares ambition."}},faq={{q="Vem skickar Tainted Letter?",a="Drusilla La Salle skriver och förseglar brevet från sin postering strax utanför Northshire Abbey. Hon ber Marshal McBride att lämna det när du återvänder efter att ha röjt de närliggande koboldlägren.",al={"vem skrev tainted letter","tainted letters författare","vem ger tainted letter"}},{q="Varför lämnar Marshal McBride över ett brev till en häxmästare?",a="Marshal McBride bär meddelanden till lovande rekryter i dalen. Han vet att brevet bär Drusillas sigill och säger att det har högsta prioritet, medan hans främsta uppgift fortfarande är att försvara och administrera Northshire, inte att övervaka försvararnas magiska bruk.",al={"varför har mcbride brevet","vet mcbride vad brevet är","mcbride häxmästarbrev"}},{q="Var hittar jag Drusilla La Salle?",a="Drusilla La Salle väntar utanför huvudingången till Northshire Abbey, nära de yttre murarna och tälten, avskild från klerikerna där inne.",al={"drusillas plats","var är drusilla la salle","hitta drusilla"}},{q="Varför tillåts häxmästare i Northshire Abbey?",a="Häxmästare i Alliansens områden väcker stark misstanke och håller låg profil. Drusilla tränar rekryter utomhus i Northshire, långt från helgedomen, för att undvika en direkt konfrontation med klerikerna och paladinerna i Holy Order of Northshire.",al={"häxmästare i northshire","är brinnande legionens magi laglig i northshire","varför tillåts häxmästare"}},{q="Vilken lärdom ger Drusilla när du får brevet?",a="Drusilla varnar för att den som hämtar kraft från Twisting Nether riskerar att fördärvas utan disciplin. Hon uppmanar till självbehärskning och försiktighet, men insisterar på att rädslan för fördärv inte får krossa en häxmästares ambition.",al={"drusillas råd","vad säger drusilla","lärdom från tainted letter"}},{q="Vad händer efter att du lämnat över Tainted Letter?",a="När du talar med Drusilla fullbordas kallelsen och hon blir din tränare. Hon ber dig återvända när du blir mäktigare, så att du kan lära dig mer om häxmästarens vägar.",al={"nästa uppdrag efter tainted letter","fortsättning på tainted letter"}}},fp="14,186,18.364.0,23.336.0,29.182.0,50.249.0,35.137.0,45.240.0,58.189.0,47.162.0"}
P.entries["quest:3106"] = {n="Simple Rune",s="Simple Rune är en introduktionsuppgift för nya dvärgkrigare i Coldridge Valley. Sten Stoutarm ger den på uppdrag av krigartränaren Thran Khorman och hänvisar de nyaste rekryterna till Anvilmar för att börja sin stridsträning.",h="Simple Rune är en introduktionsuppgift för nya dvärgkrigare i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","ironforge","simple rune","sten stoutarm","thran khorman","troggar","krigare"},ang={["class:Warrior"]="Runan markerar en krigares formella inträde i stridsdisciplinen och hänvisar nya svärd och klubbor direkt till Thran Khorman i Anvilmar.",["faction:Alliance"]="Coldridge Valley är det första träningsområdet för bergstrupperna som försvarar Alliansens södra tillfartsvägar till Khaz Modan.",["race:Dwarf"]="Thran Khorman är oerhört stolt över att lära dvärgiska rekryter att kämpa med traditionellt mod och förankra sin kultur i stål och järn i en värld som förändras snabbt.",["race:Gnome"]="Efter att ha förlorat Gnomeregan till troggar och strålning måste gnomkrigare som börjar i Coldridge Valley lära sig frontstrid tillsammans med dvärgiska mentorer för att överleva i exil."},sec={{t="En kallelse till städet",b="Medan unga rekryter rensar bort skadedjur och visar sitt mod i Coldridge Valley håller erfarna spejare utkik efter lovande kämpar. Sten Stoutarm överlämnar en ristad sten, en enkel runa, som han fått av Thran Khorman. Kallelsen leder stridslystna aspiranter från dalens snöiga stigar till Anvilmars varma smedjehall, där de formellt får svära sig till krigaryrket."},{t="Ett föränderligt Dun Morogh",b="När du rapporterar till Thran får du genast en inblick i den hårda verkligheten i dagens Dun Morogh. Den erfarne tränaren talar öppet om hur kungarikets landskap förändras: fördrivna gnomer söker skydd efter att katastrofala explosioner förstört Gnomeregan, andra dvärgar utövar främmande magiska konster eller har tagit till sig människornas tro på det Heliga Ljuset, och underjordiska troggar hotar ständigt och klöser vid bergen. I Thrans ögon är gedigen stridsdisciplin fortfarande grunden som krävs för att stå emot allt detta."}},faq={{q="Vad är Simple Rune?",a="Simple Rune är en liten, ristad skifferplatta som Sten Stoutarm överlämnar på uppdrag av Thran Khorman. Den fungerar som en officiell inbjudan och instruktion till nya krigare att infinna sig inomhus för yrkesmässig träning.",al={"föremålet simple rune","vad gör runan","simple rune-bakgrund"}},{q="Vem är Thran Khorman?",a="Thran Khorman är krigartränaren som tjänstgör inne i Anvilmar i Coldridge Valley. Han handleder unga dvärg- och gnomkrigare och lär dem grunderna i närstrid, disciplin och dvärgisk seghet.",al={"vem är thran","thran khorman-bakgrund","krigartränare i coldridge"}},{q="Varför bor det gnomer i Dun Morogh och Ironforge?",a="Gnomerna drevs nyligen bort från sitt underjordiska tekniska underverk, Gnomeregan, efter att ha utlöst katastrofala strålningssprängladdningar i ett desperat försök att slå tillbaka en invasion av underjordiska troggar. De överlevande flydde uppför bergssidan för att söka skydd hos sina dvärgallierade i Ironforge.",al={"varför är gnomerna här","gnomer i ironforge","flyktingar från gnomeregan"}},{q="Varför nämner Thran troggar?",a="Troggar är primitiva, våldsamma varelser som nyligen tog sig upp till grottorna vid ytan i Coldridge Valley och Dun Morogh efter att ha störts djupt under jord. De utgör en omedelbar fara för lokala bosättningar och handelsvägar, så försvararna i Anvilmar måste hålla vakt med vapen i hand.",al={"troggarnas hot","varför finns troggar här","troggar i coldridge"}},{q="Vad menar Thran med att dvärgar dyrkar det Heliga Ljuset?",a="Vissa dvärgar har nyligen börjat följa det Heliga Ljuset, trots sina traditionella band till bergens förfäders seder. Det beror på deras nära allians med människoriken som Lordaeron och Stormwind, och de utbildar nu egna paladiner och präster.",al={"dvärgar och heliga ljuset","dvärgpaladiner-bakgrund","dvärgpräster"}},{q="Vart ska jag ta Simple Rune?",a="Runan ska lämnas direkt till Thran Khorman, som står vid träningsområdet i Anvilmars stora bunkerhall, strax uppför stigen i Coldridge Valley.",al={"var lämnar man in simple rune","var finns thran khorman","hitta thran"}}},fp="11,159,22.283.0,21.368.0,24.123.0,21.160.0,50.192.0,30.242.0,62.154.0,32.129.0"}
P.entries["quest:3107"] = {n="Consecrated Rune",s="Consecrated Rune är en första kallelse till unga dvärgpaladiner i Coldridge Valley.",h="Consecrated Rune är en första kallelse till unga dvärgpaladiner i Coldridge Valley.",kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","det heliga ljuset","paladintränare","silver hand","sten stoutarm"},ang={["class:Paladin"]="Runan markerar ditt första formella steg in i Knights of the Silver Hand och fastslår din plikt att kanalisera ljuset till Ironforges försvar.",["race:Dwarf"]="Dvärgpaladiner förenar dvärgarnas traditionella härdighet med teologi som lärts ut av människor och bidrar med orubblig beslutsamhet till det heliga ljusets läror."},sec={{t="En kallelse till Anvilmar",b="Medan unga äventyrare rensar ut troggar och vargar i Coldridge Valley håller de lokala ledarna noga uppsikt över dem som visar anlag för gudomlig stridskonst. Sten Stoutarm överlämnar denna inskriberade runa till unga paladiner och uppmanar dem att söka upp Bromos Grummner i Anvilmars värme. Den fungerar både som en inbjudan och ett officiellt besked om att rå talang nu måste formas med disciplin."},{t="Dvärgar och det heliga ljuset",b="Även om Knights of the Silver Hand uppstod bland människorna i Lordaeron tog Ironforges dvärgar till sig det heliga ljusets filosofi med brinnande hängivenhet. Bromos Grummner välkomnar nya medlemmar i brödraskapet och påminner dem om att dvärgpaladiner nu delar den högtidliga plikten att skydda Azeroth. Orden bygger på uppoffring, tradition och krigisk dygd och kräver att rekryterna tar upp hammare och tro i lika mått."}},faq={{q="Vad är Consecrated Rune?",a="Det är en inskriberad symbol som överlämnas till unga dvärgpaladiner i Coldridge Valley och uppmanar dem att inställa sig hos Bromos Grummner i Anvilmar för formell träning.",al={"föremålet consecrated rune","vad gör runan","paladinruna coldridge"}},{q="Vem är Bromos Grummner?",a="Bromos Grummner är paladintränaren som finns i Anvilmar. Han tränar nya dvärgmedlemmar i Knights of the Silver Hand och förbereder dem för farorna som hotar Dun Morogh.",al={"vem är bromos","paladintränare anvilmar","bromos grummner bakgrund"}},{q="Varför är dvärgar med i Knights of the Silver Hand?",a="Under det andra kriget och dess efterdyningar introducerade mänskliga präster och paladiner det heliga ljusets läror för Ironforges dvärgar. Dvärgar hyser stor respekt för ordens krigiska disciplin och vilja att göra uppoffringar för att försvara Azeroth.",al={"dvärgpaladinernas bakgrund","varför har dvärgar paladiner","dvärgar i silver hand"}},{q="Vem ger dig Consecrated Rune?",a="Sten Stoutarm överlämnar runan till dig utanför Anvilmar efter att du hjälpt honom med lokala uppgifter och berättar att Bromos Grummner bad honom leverera den.",al={"var får jag runan","vem ger dig runan"}},{q="Var finns Bromos Grummner?",a="Bromos Grummner finns i Anvilmars stora sal i Coldridge Valley, tillsammans med andra klassmentorer.",al={"bromos plats","var finns bromos","hitta bromos grummner"}},{q="Vad händer när du visar runan för Bromos?",a="Bromos bekräftar att du har anslutit dig till Silver Hand och erbjuder din första formella strids- och heliga träning innan han skickar ut dig i Dun Morogh igen.",al={"what comes next","efter consecrated rune"}}},fp="16,135,21.242.0,26.390.0,29.178.0,23.176.0,55.228.0,35.135.0,33.103.0,49.179.0"}
P.entries["quest:3108"] = {n="Etched Rune",s="Etched Rune är en skriftlig kallelse till nya dvärgjägare som hjälper vakten i Coldridge Valley. Sten Stoutarm lämnar över den ristade stenen, som ber de unga spårarna söka upp Thorgas Grimson i Anvilmar för att börja sin formella träning i strid och vildmarksliv.",h="Etched Rune är en skriftlig kallelse till nya dvärgjägare som hjälper vakten i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","dvärg","etched rune","jägare","sten stoutarm","thorgas grimson"},ang={["class:Hunter"]="Den här runan inleder din resa som jägare i Dun Morogh och introducerar dig för Thorgas Grimson och dvärgarnas grundläggande traditioner inom spårning, vapenvård och överlevnad i vildmarken.",["race:Dwarf"]="Att rista meddelanden i massiv sten speglar dvärgarnas långvariga vördnad för bestående hantverk, även när det gäller vardagliga kallelser och instruktioner ute i fält."},sec={{t="En kallelse i sten",b="När lovande dvärgjägare hjälper Sten Stoutarm att hantera hoten i närheten av Coldridge Valley får de en ristad stentavla som kallas Etched Rune. I stället för att ge muntliga order eller enkel pergament föredrar dvärgarnas mentorer att förmedla formella meddelanden med runor inhuggna i sten. Runan säger åt mottagaren att se över sitt första arbete och bege sig in i Anvilmar för att få mer ingående undervisning i jaktkonsten."},{t="Dun Moroghs jägartraditioner",b="När jägaren visar runan för Thorgas Grimson inleder hen sin formella utbildning. Thorgas betonar att bergsklättring och överlevnad i Khaz Modan kräver stor respekt för den hårda miljön: att läsa spår i bitande snödrivor, sköta sitt vapen och sin ammunition och förstå de vilda djur som strövar bland klipporna. Den ristade stenen är jägarens första steg från ensam vandrare med bössa till lärling hos Anvilmars erfarna stigfinnare."}},faq={{q="Vad är Etched Rune?",a="Det är en ristad stentavla som ges till nya jägare i Coldridge Valley. Den är en skriftlig inbjudan att söka formell träning hos Thorgas Grimson i Anvilmar.",al={"vad är etched rune","föremålet etched rune","runans betydelse"}},{q="Vem skickar Etched Rune?",a="Jägartränaren Thorgas Grimson skickar den, men det är bergsklättraren Sten Stoutarm som räcker den till dig när du har visat grundläggande duglighet utanför Anvilmar.",al={"vem gav mig etched rune","avsändare av etched rune"}},{q="Vart ska jag ta Etched Rune?",a="Ta den till Thorgas Grimson, som finns i Anvilmars stora sal i Coldridge Valley.",al={"vart ska jag gå","vem ska jag lämna den till","var finns thorgas"}},{q="Varför använder dvärgar runor i stället för bokstäver?",a="Dvärgarnas kultur värdesätter stenhantverk, tradition och bestående skicklighet högt. När meddelanden och heliga instruktioner ristas in i stenrunor står de emot Dun Moroghs bitande vindar och hårda väder mycket bättre än ömtåligt pergament.",al={"varför etched rune","dvärgarnas runor i historien"}},{q="Vad händer när jag visar runan för Thorgas Grimson?",a="Thorgas välkomnar dig bland dvärgarnas spårare och förklarar grunderna i att överleva bland de frusna klipporna, sköta din utrustning och respektera vildmarkens djur. Sedan erbjuder han dig träning i jägarens grundtekniker.",al={"vad lär thorgas ut","lämna in etched rune"}},{q="Kan alla klasser få Etched Rune?",a="Nej. Etched Rune ges särskilt till dvärgjägare som påbörjar sin resa i Coldridge Valley. Andra klasser får egna rekryteringstecken som leder dem till sina respektive mentorer i Anvilmar.",al={"är etched rune bara för jägare","kan krigare få etched rune"}}},fp="11,154,18.308.0,35.434.0,24.154.0,26.140.0,32.96.0,44.197.0,58.201.0,38.174.0"}
P.entries["quest:3109"] = {n="Encrypted Rune",s="Encrypted Rune är ett kodat meddelande till blivande lönnmördare som tar sina första steg i Coldridge Valley. Sten Stoutarm lämnar över det ingraverade meddelandet, som leder lovande skuggor till Anvilmar för att rapportera till lönnmördartränaren Solm Hargrin.",h="Encrypted Rune är ett kodat meddelande till blivande lönnmördare som tar sina första steg i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","encrypted rune","gnomeregan","lönnmördartränare","solm hargrin","sten stoutarm"},ang={["class:Rogue"]="Runan är din första formella kontakt med lönnmördarorganisationen i Dun Morogh och leder dig till Solm Hargrin, där du kan börja finslipa din smygförmåga, dina stridsknep och din överlevnadskonst.",["race:Dwarf"]="Solm välkomnar dvärgar från klanen Ironforge till skuggorna och påpekar att det inte finns något som håller en operatör vid liv i Dun Morogh som en kall klinga och mörkret.",["race:Gnome"]="Solm uppmanar sina elever att visa gemenskap med gnomerna som fått skydd i Coldridge Valley efter den tragiska förlusten av sitt hem i Gnomeregan."},sec={{t="Ett kodat meddelande",b="När de hjälper Sten Stoutarm i de snötäckta passen i Coldridge Valley får skarpsynta lönnmördare en märklig, ingraverad sten. Sten berättar att någon smög till honom den för att lämna vidare, och han misstänker att den kom direkt från Solm Hargrin. I stället för att ropa över gården efter blivande spejare och skurkar använder Solm en krypterad runa för att pröva en novis diskretion och kalla in dem."},{t="Under Anvilmars takbjälkar",b="Inne i Anvilmar välkomnar Solm Hargrin nyanlända operatörer till yrket. Han erbjuder sig att lära ut manövrerna, huggen och de subtila konster som håller en operatör vid liv och fyller fickorna med mynt. Förutom att vässa deras dolkar påminner Solm lönnmördarna bland dvärgarna om att ta hand om sina fördrivna gnomiska allierade, som fortfarande återhämtar sig från Gnomeregans katastrofala fall."}},faq={{q="Vem har skrivit Encrypted Rune?",a="Runan är skriven av Solm Hargrin, lönnmördartränaren i Anvilmars stora sal. Han ber Sten Stoutarm att diskret lämna den vidare till lovande rekryter ute i snön.",al={"vem skrev runan","avsändare av encrypted rune","vem gav sten runan"}},{q="Var hittar jag Solm Hargrin?",a="Solm Hargrin finns i Anvilmars stora sal, stenfästet mitt i Coldridge Valley i Dun Morogh.",al={"var finns solm","solm hargrins plats","hitta solm"}},{q="Vad är syftet med runan?",a="Den fungerar som en första kallelse till novisa lönnmördare och uppmuntrar dem att tyda meddelandet, uppsöka sin klass tränare och börja lära sig avancerade stridstekniker och överlevnadsmanövrer.",al={"vad gör runan","encrypted runes syfte","varför encrypted rune"}},{q="Varför nämner Solm gnomerna?",a="Efter att Gnomeregan nyligen drabbats av en katastrof delar gnomiska flyktingar Coldridge Valley och Anvilmar med dvärgarna. Solm påminner sina elever om att gnomerna har haft det svårt och behöver stöd när de slår sig ner i sitt tillfälliga hem.",al={"varför hjälpa gnomerna","solms kommentar om gnomeregan"}},{q="Vem ger runan till spelaren?",a="Sten Stoutarm lämnar över stenen till äventyrare som är lönnmördare i Coldridge Valley efter att de först har hjälpt honom med uppgifter i dalen.",al={"vem inleder encrypted rune","uppdragsgivare för encrypted rune"}},{q="Kan andra klasser få den här runan?",a="Nej. Encrypted Rune är endast avsedd för lönnmördarnoviser som börjar sina äventyr i Coldridge Valley.",al={"är uppdraget bara för lönnmördare","kan krigare få encrypted rune"}}},fp="14,117,17.248.0,24.298.0,29.149.0,29.111.0,33.147.0,33.202.0,33.117.0,36.81.0"}
P.entries["quest:311"] = {n="Return to Marleth",s="Return to Marleth avslutar den heta bryggarfejden i Dun Morogh med ett finurligt spratt. Efter att ha tagit sig in i källaren i Kharanos och bytt ut en tunna mot Marleths starka Scalder återvänder en äventyrare till Brewnall Village med en tunna Thunder Ale som obestridligt bevis.",h="Return to Marleth avslutar den heta bryggarfejden i Dun Morogh med ett finurligt spratt.",kw={"brewnall village","dun morogh","kharanos","marleth barleybrew","scalder","thunder ale","thunderbrew"},ang={["class:Rogue"]="Att ta sig in i en bevakad källare och byta ut olovligt åtkomna tunnor bjuder på ett roligt prov i smygande och fingerfärdighet bland de snötäckta kullarna.",["race:Dwarf"]="I dvärgkulturen ses bryggning som både konst och en hederstävlan, så småaktigt källarspionage blir en källa till stor lokal stolthet."},sec={{t="Bytet efter sabotaget",b="Dvärgars rivaliteter avgörs sällan med diplomati när öl står på spel. Marleth Barleybrew i Brewnall Village hyser ett bittert tävlingsagg mot destillatörerna i Kharanos, som skapat det berömda Thunder Ale. Efter att hennes kraftiga Scalder obemärkt smugglats in i Thunderbrew-källaren kräver Marleth bevis på bedriften. Att bära iväg en äkta tunna Thunder Ale mitt framför näsan på dem fungerar både som trofé och påtryckning."},{t="En bitter brygdfejd avgjord",b="Att släpa den tunga tunnan tillbaka över de snötäckta bergsryggarna till Brewnall Village fullbordar kuppen. Marleth blir överlycklig när hon ser att planen lyckats och njuter av att ha överlistat vakterna och källarmästarna i Kharanos. Sprattet är harmlöst på ytan, men befäster den starka, kompromisslösa stolthet som olika dvärgfamiljer lägger i sina egna recept i Dun Morogh."}},faq={{q="Vad är syftet med uppdraget?",a="Du måste återlämna den stulna tunnan Thunder Ale till Marleth Barleybrew i Brewnall Village för att bevisa att du lyckades smuggla in hennes Scalder i källaren i Kharanos.",al={"vad ska jag göra","målet med return to marleth","lämna in tunnan"}},{q="Vem är Marleth Barleybrew?",a="Marleth är en dvärgbryggare som bor i Brewnall Village. Hon är mycket stolt över familjens kraftiga ölsorter och hyser en småaktig rivalitet med destillatörerna i Thunderbrew i Kharanos.",al={"vem är marleth","marleths historia","barleybrew"}},{q="Varifrån kommer tunnan?",a="Tunnan hämtas direkt från källarförrådet i Thunderbrew Distillery i Kharanos, efter att du bytt ut Marleths Scalder mot deras öl.",al={"varifrån kom tunnan","källaren i kharanos","var finns thunder ale"}},{q="Var ligger Brewnall Village?",a="Brewnall Village ligger längs den frusna stranden vid Iceflow Lake i västra Dun Morogh, nordväst om Kharanos.",al={"brewnalls läge","var ligger brewnall","hur hittar jag marleth"}},{q="Varför ligger Marleth i fejd med Kharanos?",a="Dvärgarnas bryggmästare tävlar hårt om sina recept. Marleth ville bevisa att hennes egen blandning, Scalder, kunde överträffa eller förödmjuka det hyllade Thunder Ale som Thunderbrew-familjen brygger.",al={"varför är de rivaler","marleth mot thunderbrew","bryggarfejd"}},{q="Vad gör Marleth med tunnan?",a="Tunnan fungerar främst som bevis på att bytet lyckades mitt framför näsan på vakterna i Kharanos, men Marleth blir utan tvekan glad över att behålla sin rivals öl.",al={"varför stjäla thunder ale","vad händer med ölet"}}},fp="17,144,22.153.0,21.211.0,34.143.0,26.145.0,33.122.0,26.103.0,37.166.0,37.125.0"}
P.entries["quest:3110"] = {n="Hallowed Rune",s="Hallowed Rune är ett introduktionsuppdrag för blivande dvärgpräster i Coldridge Valley. Sten Stoutarm vidarebefordrar en runa med inskrifter från prästtränaren Branstock Khalder, som kallar novisen till Anvilmar för att fördjupa sin förbindelse med det heliga ljuset.",h="Hallowed Rune är ett introduktionsuppdrag för blivande dvärgpräster i Coldridge Valley.",kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","dvärgpräst","hallowed rune","sten stoutarm"},ang={["class:Priest"]="Runan markerar att du formellt erkänns som det heliga ljusets tjänare i Dun Morogh och hänvisar dig till Branstock Khalder för dina första studier i besvärjelser.",["race:Dwarf"]="Dvärgpräster förenar djup hängivenhet till ljuset med bergsfolkets tålighet och är oumbärliga när Coldridge Valley ska försvaras mot invaderande troggar."},sec={{t="En kallelse till tyget",b="Medan en nyanländ präst hjälper Sten Stoutarm att rensa bort de omedelbara hoten utanför Anvilmar, fångar hen bosättningens andlige vägledares uppmärksamhet. Branstock Khalder anförtror Sten en helig runa med böner och vägledning, och ber den unga äventyraren att gå in i Anvilmars stadiga salar för att formellt inleda sina heliga studier."},{t="Coldridges försvarare",b="Även om dvärgarnas kultur ofta betonar krigisk styrka och tung plåt rustning, förblir det heliga ljuset en hörnsten i Ironforges samhälle. I Coldridge Valley spelar heliga magiker en avgörande roll tillsammans med krigare och jägare när de skyddar enklaven mot aggressiva troggangrepp och farligt djurliv som smyger genom snödrivorna."}},faq={{q="Vad är Hallowed Rune?",a="Det är en runa med prästerliga inskrifter som Sten Stoutarm överlämnar på uppdrag av Branstock Khalder. Att läsa den är en introduktion till grundläggande böner och uppmuntrar unga präster att söka formell träning.",al={"vad är hallowed rune","runans syfte"}},{q="Vem är Branstock Khalder?",a="Branstock Khalder är dvärgarnas prästtränare som håller till inne i Anvilmar. Han är känd för sin torra humor och orubbliga tro, vägleder blivande akolyter och lär dem grundläggande heliga besvärjelser som hjälper till att försvara Coldridge Valley.",al={"branstock","prästtränare i coldridge"}},{q="Var hittar jag Branstock Khalder?",a="Han finns inne i Anvilmars stora stenstuga, som ligger på den centrala gläntan i Coldridge Valley i Dun Morogh.",al={"branstocks plats","var finns branstock"}},{q="Varför behöver dvärgar präster i Coldridge Valley?",a="Troggar har tagit över delar av dalen, och de lokala vakterna förlitar sig på ljusbärarnas helande krafter och heliga smite för att hålla sina linjer och läka de sårade.",al={"varför dvärgpräster","präster i anvilmar"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Hallowed Rune ges endast till unga dvärgpräster som börjar sin resa i Coldridge Valley.",al={"vem kan få hallowed rune","är uppdraget endast för präster"}},{q="Vem överlämnar runan till spelaren?",a="Sten Stoutarm, en bergsvandrare från Anvilmar som övervakar prövningar strax utanför stugan, räcker över runan efter att du hjälpt honom med dalens inledande försvar.",al={"vem startar hallowed rune","sten stoutarms roll"}}},fp="13,225,22.306.0,22.269.0,26.168.0,25.186.0,34.117.0,48.148.0,30.99.0,36.160.0"}
P.entries["quest:3112"] = {n="Simple Memorandum",s="Simple Memorandum är ett brev till blivande gnomkrigare som börjar sin bana i Coldridge Valley. Sten Stoutarm delar ut det utanför och skickar de nyutbildade kämparna till Anvilmar för att träffa Thran Khorman, som har lovat att förbereda dem på att återta Gnomeregan.",h="Simple Memorandum är ett brev till blivande gnomkrigare som börjar sin bana i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","sten stoutarm","thran khorman","krigstränare"},ang={["class:Warrior"]="Det här brevet inleder formellt en gnomkrigares stridsutbildning och knyter ett band till Ironforges erfarna vapenmästare.",["race:Dwarf"]="Dvärgmentorer som Thran Khorman behandlar gnomernas utsatthet som likvärdig med deras egna urgamla fejder och visar djup solidaritet med sina fördrivna allierade.",["race:Gnome"]="Memorandumet lyfter fram gnomernas exil från Gnomeregan och deras stillsamma beslutsamhet att träna soldater som kan återta sin radioaktiva stad."},sec={{t="En kallelse till Anvilmar",b="Medan en ung gnomkrigare röjer undan troggs och vildsvin som plågar Coldridge Valley åt bergsjägaren Sten Stoutarm, får krigaren ett kort meddelande som någon har smugit ner i dvärgens händer. Veterantränaren Thran Khorman ser potential hos den nyanlända flyktingen och använder memorandumet för att kalla in nykomlingen till Anvilmars stora sal, där den riktiga stridsundervisningen börjar."},{t="Ett löfte om solidaritet",b="Dvärgtränare kan ibland retas med gnomkrigare för deras ringa storlek, men Thran Khorman tar deras kamp på allvar. Han känner med dem som förlorat Gnomeregan och jämför deras utsatthet med hur dvärgarna skulle känna om Ironforge föll för Dark Irons. För att hålla sitt löfte lovar han att lära exilkrigarna krigskonsten tills de är redo att återta sitt hem."}},faq={{q="Vad är Simple Memorandum?",a="Det är en introduktionshälsning som Sten Stoutarm ger till nybörjare bland gnomkrigarna i Coldridge Valley. Brevet instruerar krigaren att söka upp Thran Khorman, krigstränaren i Anvilmars stora sal.",al={"simple memorandum","vad är den här lappen","memorandumuppdrag"}},{q="Vem skickar memorandumet?",a="Det kommer från Thran Khorman, dvärgkrigstränaren som är stationerad i Anvilmar. Han ber Sten Stoutarm att lämna det vidare till lovande kämpar som hjälper bergsjägarna.",al={"vem skrev memorandumet","vem skickade simple memorandum"}},{q="Varför tränar Thran Khorman gnomkrigare?",a="Thran har lovat att hjälpa de fördrivna gnomerna. Han respekterar deras beslutsamhet och känner starkt med dem i deras tragedi. Han jämför Gnomeregans fall med hur det skulle vara om Ironforge erövrades av klanen Dark Iron.",al={"varför tränar thran gnomer","gnomkrigares historia"}},{q="Var hittar jag Thran Khorman?",a="Thran Khorman står i Anvilmars stora sal, den centrala bosättningen i Coldridge Valley i Dun Morogh.",al={"var finns thran khorman","thran khormans plats"}},{q="Vem är Sten Stoutarm?",a="Sten Stoutarm är en dvärgisk bergsjägare som är stationerad strax utanför Anvilmar i Coldridge Valley. Han samordnar det lokala försvaret mot aggressiva vildsvin och invaderande troggs.",al={"sten stoutarm","vem är sten"}},{q="Varför börjar gnomer i Coldridge Valley?",a="Efter Gnomeregans tragiska fall och strålning flydde överlevande gnomer till dvärgarnas områden som flyktingar. Anvilmar och Ironforge har öppnat sina dörrar för att ge dem skydd medan de bygger upp sina styrkor igen.",al={"varför är gnomerna här","gnomer i coldridge"}}},fp="17,208,21.219.0,22.310.0,30.143.0,25.104.0,44.182.0,30.90.0,21.149.0,44.191.0"}
P.entries["quest:3113"] = {n="Encrypted Memorandum",s="Encrypted Memorandum är en introducerande kallelse riktad till nyblivna gnomiska skurkar som anländer till Coldridge Valley. Genom Sten Stoutarm leder den förklädda lappen i tysthet nya agenter till Solm Hargrin i Anvilmar.",h="Encrypted Memorandum är en introducerande kallelse riktad till nyblivna gnomiska skurkar som anländer till...",kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","skurktränare","solm hargrin","sten stoutarm"},ang={["class:Rogue"]="Uppgiften är den första kallelsen för gnomiska skurkar och introducerar dem för Solm Hargrin och den ömsesidiga beskyddandets filosofi som krävs för att verka i det fördolda i dvärgarnas land.",["race:Dwarf"]="Dvärgiska bergsjägare som Sten Stoutarm förmedlar sådana kontakter och visar det praktiska samarbetet mellan Ironforge och de fördrivna gnomerna i Coldridge Valley.",["race:Gnome"]="Memorandumet lyfter fram de gnomiska flyktingarnas svåra situation efter katastrofen i Gnomeregan och visar hur överlevare sluter sig samman medan de bor som gäster hos dvärgarna."},sec={{t="En diskret introduktion",b="Medan nykomna gnomer hjälper Coldridge Valleys bergsjägare att hantera lokala troggar, överlämnar Sten Stoutarm ett vikt pergament som anförtrotts åt honom. Lappen utger sig för att vara ett officiellt memorandum och är en inbjudan att träffa Solm Hargrin, skurktränaren som håller till i Anvilmar."},{t="Delade vedermödor i snön",b="Meddelandet speglar den osäkra verklighet som gnomerna möter efter Gnomeregans plötsliga fall. Gnomiska överlevare har drivits bort från sitt hem under jord och måste trängas med sina dvärgiska värdar i Dun Morogh. Solm Hargrin vet att skurkar väcker misstankar när föremål försvinner, och han förespråkar en ordlös sammanhållning bland hantverkets utövare för att de ska överleva tillsammans."}},faq={{q="Vem skrev Encrypted Memorandum?",a="Solm Hargrin, skurktränaren som håller till i Anvilmar, skrev lappen. Han förklädde den till ett officiellt direktiv från högre ort så att Sten Stoutarm skulle lämna över den utan att väcka misstankar.",al={"vem skickade memorandumet","vem skrev lappen","solms lapp"}},{q="Varför är memorandumet förklätt?",a="Skurkar föredrar diskretion, särskilt i en livlig dvärgisk fästning som Anvilmar. Solm Hargrin håller låg profil för att undvika rykten eller anklagelser när utrustning försvinner och använder kodade hälsningar för att nå andra skurkar.",al={"varför förklädd","varför krypterad"}},{q="Vad avslöjar lappen om situationen i Dun Morogh?",a="Dialogen belyser motsättningarna och sammanhållningen mellan gnomer och dvärgar efter förlusten av Gnomeregan. Att tränga ihop båda folken i Ironforge och Dun Morogh tär på resurserna, men Solm betonar att de som verkar i skuggorna måste hålla varandra om ryggen.",al={"relationer mellan gnomer och dvärgar","gnomiska flyktingar i dun morogh"}},{q="Vem överlämnar memorandumet till spelaren?",a="Sten Stoutarm lämnar över dokumentet efter att du hjälpt honom i Coldridge Valley. Han antar att det kommer från Solm Hargrin och är avsett för din träning.",al={"sten stoutarm överlämning","vem lämnar över lappen"}},{q="Vilken roll har Solm Hargrin?",a="Solm Hargrin är skurktränaren i Anvilmars bergshall och ansvarar för att lära upp nya skurkar i stridsteknik och skuggkonster.",al={"solm hargrins roll","vad gör solm"}},{q="Har det här uppdraget samband med Gnomeregans fall?",a="Ja. Solm nämner direkt att Gnomeregan blev översvämmat av fiender och betonar att gnomiska skurkar på flykt kan lita på sin gemenskap för att hålla ut, trots att de förlorat sitt mekaniska hemland.",al={"lore om gnomeregans fall","gnomiska flyktingars situation"}}},fp="20,105,23.219.0,28.268.0,35.174.0,32.218.0,61.226.0,42.129.0,34.120.0,44.165.0"}
P.entries["quest:3114"] = {n="Glyphic Memorandum",s="Glyphic Memorandum är en introduktionsuppgift som leder nybörjarmagiker i Coldridge Valley till deras lokala tränare i Anvilmar. Bergsklättraren Sten Stoutarm har fått brevet i förtroende. Det kallar blivande utövare av de arkana konsterna till den excentriske gnomen Marryk Nurribit för att inleda sina formella studier i magi.",h="Glyphic Memorandum är en introduktionsuppgift som leder nybörjarmagiker i Coldridge Valley till deras lokala...",kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","magitränare","marryk nurribit","sten stoutarm"},ang={["class:Mage"]="Det här brevet markerar din officiella introduktion till magisk undervisning i Dun Morogh och för dig direkt till din första tränare.",["faction:Alliance"]="Det smidiga samarbetet mellan Sten Stoutarm och Marryk Nurribit visar det nära samarbetet mellan dvärgar och gnomer i Coldridge Valley.",["race:Gnome"]="Marryk Nurribit är en av flera gnomexperter som sökte skydd i dvärgarnas länder efter Gnomeregans fall, för att lära ut sitt traditionella hantverk."},sec={{t="Ett brev till nybörjarmagiker",b="När nyanlända magiker hjälper bergsklättraren Sten Stoutarm med de första uppgifterna i Coldridge Valley blir de kallade till den lokala auktoriteten inom de arkana konsterna. Sten får ett skriftligt memorandum adresserat till den blivande magikern och lämnar det vidare. Han råder dem att ta en stund och läsa innehållet, och sedan gå in i värmen i Anvilmar för att träffa brevets avsändare."},{t="Träning hos Marryk Nurribit",b="Memorandumets avsändare är Marryk Nurribit, en gnommagitränare som håller till i Anvilmar. I stället för att dränka sin elev i tung teori ger Marryk raka och jordnära råd: undvik allvarliga problem, spara mynt till träning och krogbesök, och håll dig absolut borta från den radioaktiva katastrofen som är det fallna Gnomeregan. När grundförväntningarna är klara står Marryk redo att lära nykomlingar de arkana konsterna."}},faq={{q="Vem överlämnar memorandumet?",a="Sten Stoutarm, en alliansens bergsklättrare stationerad i Coldridge Valley, ger dig memorandumet efter att du hjälpt honom med hans första uppgifter.",al={"vem ger glyphic memorandum","sten stoutarm uppdrag"}},{q="Vem är Marryk Nurribit?",a="Marryk Nurribit är en gnommagitränare som bor i Anvilmar i Coldridge Valley. Han lär blivande magiker deras första besvärjelser och grunderna i säker användning av de arkana konsterna.",al={"vem är marryk","magitränare i anvilmar"}},{q="Var hittar jag Marryk Nurribit?",a="Marryk håller till i Anvilmars stora sal, den centrala dvärgposteringen högst upp i Coldridge Valley i Dun Morogh.",al={"marryk nurribit plats","var finns magitränaren i coldridge valley"}},{q="Varför varnar Marryk för att besöka Gnomeregan?",a="Gnomeregan har nyligen tagits över av troggar och förorenats av ett katastrofalt utsläpp av radioaktiv gas. Därför är platsen farlig för alla nybörjaräventyrare som vandrar i Dun Morogh.",al={"marryk varning om gnomeregan","varför hålla sig borta från gnomeregan"}},{q="Vilka klasser får den här uppgiften?",a="Den här uppgiften ges endast till blivande magiker som inleder sin resa i Coldridge Valley, för att presentera dem för deras klasstränare.",al={"vem får glyphic memorandum","är uppdraget bara för magiker"}},{q="Vad förväntar sig Marryk av sina elever?",a="Marryk ställer enkla krav: han varnar eleverna för att hamna i trubbel, ber dem spara tillräckligt med silver för att betala för sina besvärjelser och bjuda honom på öl, och uppmanar dem att hålla sig långt borta från Gnomeregan.",al={"maryks förväntningar","vad vill tränaren"}}},fp="18,125,26.173.0,29.272.0,29.112.0,23.160.0,33.103.0,49.145.0,31.105.0,42.133.0"}
P.entries["quest:3115"] = {n="Tainted Memorandum",s="Tainted Memorandum är ett introduktionsuppdrag för nyblivna gnomiska häxmästare som tar sina första steg i Coldridge Valley. Meddelandet förmedlas diskret genom Sten Stoutarm och kallar novisen till skuggorna i Anvilmar för att möta Alamar Grimm, som predikar självständighet genom mörk kraft i stället för tillit till deras dvärgiska värdar.",h="Tainted Memorandum är ett introduktionsuppdrag för nyblivna gnomiska häxmästare som tar sina första steg i...",kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","gnomisk häxmästare","gnomeregan i exil","sten stoutarm","tainted memorandum"},ang={["class:Warlock"]="Det här meddelandet markerar ditt formella inträde i häxmästarkonsten och framställer demoniska pakter som pragmatism född ur överlevnad, inte som vansinne.",["race:Dwarf"]="Dvärgiska värdar tolererar de här mörka utövarna under sitt tak med tydlig motvilja och stor vaksamhet.",["race:Gnome"]="Memorandumet speglar den djupt rotade bitterhet som vissa gnomer i exil känner över sin fördrivna tillvaro och sitt beroende av Ironforge."},sec={{t="En diskret kallelse",b="Även i den frusna utposten Coldridge Valley möts utövandet av mörka konster med djup misstänksamhet. Medan de hjälper Sten Stoutarm att hantera lokala hot får unga gnomiska häxmästare en diskret överlämnad lapp. Sten lämnar motvilligt över den och ger röst åt den obekväma vapenvila som låter häxmästare verka i Alliansens länder: ”Se upp ... folk som ni är inte särskilt betrodda här omkring.”"},{t="Gnomisk bitterhet i exil",b="När häxmästaren svarar på lappen möter hen Alamar Grimm, som håller sig dold inne i Anvilmars salar. Grimm lindar inte in orden om gnomernas belägenhet. I hans ögon misslyckades konventionellt mekande och vanlig magi fullständigt med Gnomeregan, drev deras folk till randen av utrotning och lämnade dem strandsatta som andra klassens flyktingar, beroende av dvärgarnas välvilja. I stället för att be till det heliga ljuset eller sätta sin tilltro till dvärgisk politik uppmanar Grimm sin lärjunge att frammana och bemästra fiender som erbjuder ovillkorlig lydnad."}},faq={{q="Vad är Tainted Memorandum?",a="Det är ett skriftligt meddelande som Sten Stoutarm lämnar till noviser bland de gnomiska häxmästarna i Coldridge Valley. Det uppmanar dem att söka upp Alamar Grimm, den lokala häxmästartränaren i Anvilmar.",al={"tainted memorandum","häxmästarens lapp dun morogh","vad är memorandumet"}},{q="Varför misstror man häxmästare i Coldridge Valley?",a="Dvärgar och deras allierade i Alliansen håller traditionella dygder som krigisk heder och det heliga ljuset högt. De ser demonologi och skuggmagi som i grunden korrumperande och farliga. Gnomiska häxmästare lever under djup social misstänksamhet.",al={"varför tycker dvärgar illa om häxmästare","fördomar mot häxmästare anvilmar"}},{q="Vem är Alamar Grimm?",a="Alamar Grimm är en gnomisk häxmästartränare som bor i Anvilmar. Han är bitter över Gnomeregans fall och förödmjukelsen i att vara beroende av dvärgarnas välgörenhet, och lär unga gnomer att binda demoniska undersåtar för att trygga sin egen makt.",al={"alamar grimm berättelse","vem är alamar"}},{q="Varför kritiserar Grimm vanlig magi och teknik?",a="Grimm anser att konventionell ingenjörskonst och accepterade magiskolor svek gnomerna under katastrofen i Gnomeregan. De lämnades beroende av dvärgiska beskyddare som prioriterar banden till människor framför att återta gnomernas hemland.",al={"grimms syn på gnomeregan","varför mörk magi framför ingenjörskonst"}},{q="Kan dvärgiska häxmästare få det här uppdraget?",a="Nej. I Dun Morogh är det bara gnomer som kan följa häxmästarens väg, så kallelsen är exklusiv för nyanlända gnomiska utövare.",al={"dvärgisk häxmästare tainted memorandum","kan dvärgar vara häxmästare"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar nära Sten Stoutarm i Coldridge Valley och avslutas inne i Anvilmar, den centrala fästningen med utsikt över dalen i sydvästra Dun Morogh.",al={"var finns alamar grimm","lämna in tainted memorandum"}}},fp="18,142,18.270.0,27.373.0,31.177.0,48.178.0,20.213.0,53.233.0,38.118.0,33.147.0"}
P.entries["quest:3116"] = {n="Simple Sigil",s="Simple Sigil är en introducerande kallelse till blivande nattalvskrigare i Shadowglen. Conservator Ilthalaine överlämnar den på tränaren Alyissias vägnar och markerar därmed formellt rekrytens övergång till stridsträning för att skydda Teldrassils späda grenar.",h="Simple Sigil är en introducerande kallelse till blivande nattalvskrigare i Shadowglen.",kw={"aldrassil","alyissia","feralas","ilthalaine","shadowglen","simple sigil","teldrassil","krigare"},ang={["class:Warrior"]="Det här uppdraget markerar din formella början som Kaldoreikrigare och presenterar Alyissia som din första vapenlärare.",["faction:Alliance"]="Alyissias råd speglar nattalvernas tidiga försök att välkomna andra alliansraser till sina grenar efter århundraden av isolering.",["race:NightElf"]="Sigillet talar direkt om de snabba förändringarna kring Kaldorei, från planteringen av Teldrassil till att öppna sitt avskilda hem för utländska allierade."},sec={{t="En kallelse till vapen i Shadowglen",b="Efter att ha bevisat sina grundläggande överlevnadskunskaper mot det rastlösa djurlivet i Shadowglen får unga nattalvskrigare en inskriven sigill som överlämnas genom Conservator Ilthalaine. Den är en formell begäran från Alyissia, den lokala krigartränaren vid Aldrassil, som uppmanar novisen att träda fram och viga sin kampstyrka åt att försvara sitt folk."},{t="En omvälvande ny era",b="När krigaren rapporterar till Alyissia placerar hon träningen mot bakgrund av snabba och oroande förändringar. På bara några få år har nattalverna rest världsträdet Teldrassil, sett en lömsk smitta spridas bland skogens bestar nära och fjärran och återknutit banden till forntida förfädersområden som man en gång trodde var förlorade, såsom Feralas. För att möta dessa faror behövs dugliga försvarare omgående."},{t="Grenarna öppnas",b="Utöver stridsdisciplin förbereder Alyissia unga Kaldorei för världen utanför deras skyddade glänta. Hon råder rekryterna att inte hysa fördomar mot främlingar av andra raser som kommer till Teldrassil. Hon varnar för att inte alla resenärer handlar av ren osjälviskhet, men betonar att allierade är avgörande för Kaldoreis försvar och uppmanar sina elever att visa rimlig tillit när de tar sig an rollen som beskyddare."}},faq={{q="Vad är Simple Sigil?",a="Det är en inskriven sigill som skickas av Alyissia, krigartränaren i Shadowglen, och överlämnas till unga nattalvskrigare för att kalla dem till formell stridsundervisning.",al={"föremålet simple sigil","vad är det här sigillet","krigarens sigill"}},{q="Vem skickar dig för att hitta Alyissia?",a="Conservator Ilthalaine överlämnar sigillet och hänvisar dig till Alyissia när du har slutfört dina första uppgifter med att bevara balansen i Shadowglen.",al={"vem ger simple sigil","uppdragsgivare för simple sigil"}},{q="Var finns Alyissia?",a="Alyissia finns i den trygga tillflyktsorten Shadowglen, nära Aldrassils väldiga stam, där hon tränar blivande nattalvskrigare.",al={"alyissias plats","var finns alyissia","krigartränare i shadowglen"}},{q="Varför säger Alyissia att det behövs krigare just nu?",a="De senaste åren har fört med sig stora utmaningar: Teldrassils grundande, utbredd korruption som drabbar det lokala djurlivet och återupptäckten av sedan länge förlorade länder som Feralas. Skickliga kämpar behövs för att skydda Kaldorei från hoten som tränger sig allt närmare.",al={"varför behöver nattalver krigare","krigarlore i shadowglen"}},{q="Vad säger Alyissia om andra raser som besöker Teldrassil?",a="Hon avråder från fördomar och förklarar att främlingar av andra raser snart kommer att besöka Teldrassils grenar. Hon medger att alla besökare inte är helt osjälviska, men råder dig att visa en viss tillit så att de kan hjälpa till att försvara trädet.",al={"alyissia om andra raser","nattalver och främlingar","alliansen i teldrassil"}},{q="Varför nämns Feralas?",a="Feralas är ett forntida nattalvsland som länge var avskuret eller ansågs förlorat efter den stora klyvningen. Återupptäckten visar hur snabbt Kaldorei återknyter banden till den vida världen efter årtusenden av isolering.",al={"varför nämns feralas","kopplingen till feralas"}}},fp="12,180,28.325.0,20.333.0,18.324.0,25.159.0,31.143.0,28.110.0,52.222.0,61.192.0,47.200.0"}
P.entries["quest:3117"] = {n="Etched Sigil",s="Etched Sigil är en skriftlig kallelse som Conservator Ilthalaine överlämnar till unga Night Elf-jägare i Shadowglen. Den kallar dem upp bland Aldrassils väldiga grenar för att möta sin tränare, Ayanna Everstride, och formellt påbörja sin bana inom bågskytte och djurkunskap.",h="Etched Sigil är en skriftlig kallelse som Conservator Ilthalaine överlämnar till unga Night Elf-jägare i...",kw={"aldrassil","ayanna everstride","etched sigil","jägare","ilthalaine","shadowglen","teldrassil"},ang={["class:Hunter"]="Det här uppdraget är din officiella introduktion till jägarnas mentorskap på Teldrassil och öppnar dörren till att lära dig bågskytte, spårning och djurmästerskap.",["race:NightElf"]="För kaldorei är jakt en helig disciplin, sammanflätad med harmoni med naturen och vördnad för Elune, snarare än enbart en sport."},sec={{t="En kallelse bland grenarna",b="Efter att ha visat sin vaksamhet genom att försvara Shadowglen får unga kaldorei-jägare en inskriven bricka av Conservator Ilthalaine. Den bars ursprungligen av en budbärare från jägarnas mentor Ayanna Everstride. Den ingraverade sigillen uppmanar nybörjaren att klättra högt upp i Aldrassils övre delar, där tränarna vakar över trädtopparna."},{t="Jägarens bana",b="Mötet med Ayanna markerar den formella starten på jägarträningen på Teldrassil. Hon lär nybörjarna konsten att träffa med precision och förstå Kalimdors vilda djur. Ayanna betonar att en sann jägare måste behandla sina djurföljeslagare med respekt och vara uppmärksam och ödmjuk i en värld full av osedda faror."}},faq={{q="Vad är Etched Sigil?",a="Det är ett inskrivet meddelande från jägarnas tränare Ayanna Everstride, som visar lovande Night Elf-nybörjare till hennes plats högst upp i Aldrassil.",al={"etched sigil","vad är den här sigillen","sigillföremål"}},{q="Var finns Ayanna Everstride?",a="Du hittar henne på de övre terrasserna i Aldrassil, det väldiga världsträdet mitt i Shadowglen.",al={"var finns ayanna","hitta ayanna everstride","ayanna everstride plats"}},{q="Vem delar ut Etched Sigil?",a="Conservator Ilthalaine ger den till Night Elf-jägare när de börjar visa vad de går för genom att försvara den lokala skogen.",al={"vem ger uppdraget","uppdragsgivare","var får jag etched sigil"}},{q="Vad lär Ayanna Everstride ut?",a="Hon lär jägare traditionerna inom bågskytte, djurhållning och överlevnad i vildmarken, och varnar dem för att aldrig underskatta farorna som lurar där ute.",al={"jägarträning","vad lär ayanna ut","varför prata med ayanna"}},{q="Varför varnar Ayanna jägarna för deras husdjur?",a="Hon påminner sina elever om att vildmarken rymmer hot som är långt mäktigare än vad nybörjarjägare inser. Därför måste jägare respektera sina djurföljeslagare och inte ta deras förmågor för givna.",al={"fara från djur","varför respektera djur","varning om husdjur"}},{q="Är det här uppdraget tillgängligt för andra klasser?",a="Nej, Etched Sigil är en introduktionskallelse för en klass och är endast avsedd för Night Elf-jägare.",al={"kan druider göra det här","är det här bara för jägare","andra klasser"}}},fp="12,203,23.274.0,22.254.0,25.126.0,35.113.0,31.132.0,34.129.0,49.189.0,41.76.0"}
P.entries["quest:3118"] = {n="Encrypted Sigil",s="Encrypted Sigil är en första kallelse till nyanlända Night Elf-skurkar i Shadowglen. Conservator Ilthalaine bär den på Frahun Shadewhispers uppdrag. Den leder hemliga agenter till att inleda sin träning och ta den sköra fred som hotar Kalimdor på allvar.",h="Encrypted Sigil är en första kallelse till nyanlända Night Elf-skurkar i Shadowglen.",kw={"aldrassil","conservator ilthalaine","encrypted sigil","frahun shadewhisper","tränare för skurkar","shadowglen","teldrassil"},ang={["class:Rogue"]="Det här uppdraget markerar ditt inträde i kaldoreis nätverk av spejare, lönnmördare och underrättelseinhämtare, som har fått i uppgift att skydda Teldrassil från osedda fiender.",["faction:Alliance"]="Shadowglens tränare påminner rekryterna om att fördrag mellan fraktionerna är sköra och att underrättelsearbete är avgörande för att förhindra hordens intrång.",["race:NightElf"]="Även i Aldrassils avskilda fristad håller kaldorei vaksam uppsikt över Kalimdors skiftande gränser för att försvara sina nyplanterade trädgrenar."},sec={{t="Ett budskap i skuggorna",b="Medan yngre Night Elf studerar naturens balans under Conservator Ilthalaine får de som dras till smygande och ränker en tystare kallelse. En budbärare levererar Encrypted Sigil från Frahun Shadewhisper, Shadowglens mentor för skurkar. Den är inskriven med chiffer som bara är avsedda för yrkets invigda. Den uppmanar bäraren att tyda innehållet och söka upp Frahun nära Aldrassils rötter för att formellt inleda sin utbildning."},{t="Vaksam vid horisonten",b="Frahuns budskap är mer än en enkel tid för träning. Det är en allvarsam varning om de politiska realiteterna i Kalimdor. Tredje kriget är över, men freden mellan Alliansen och den framväxande horden är skör som papper. I Shadowglen uppmanas spejare och informatörer bland skurkarna att tidigt vässa syn och hörsel. De ska hålla uppsikt efter hot och hemliga provokationer som kan utlösa ett nytt krig över gränserna."}},faq={{q="Vad är Encrypted Sigil?",a="Det är en kodad symbol som mentorn för skurkar, Frahun Shadewhisper, skickar till nya skurkar i Shadowglen. Den uppmanar dem att anmäla sig hos honom under Aldrassil för formell träning.",al={"vad är det här sigillet","uppdraget encrypted sigil","sigillets föremål"}},{q="Vem överlämnar sigillet till unga Night Elf?",a="Conservator Ilthalaine överlämnar sigillet på Frahuns uppdrag när en invigd har visat grundläggande skicklighet i att hantera det lokala djurlivet bland Shadowglens trädgrenar.",al={"vem ger uppdraget","uppdragsgivare","conservator ilthalaine"}},{q="Var finns Frahun Shadewhisper?",a="Frahun Shadewhisper håller till i skyddet under det stora trädet Aldrassil i Shadowglen. Där är han redo att undervisa nyanlända Night Elf-skurkar.",al={"var finns frahun","hitta frahun shadewhisper","frahu n plats"}},{q="Varför behövs skurkar i fredliga Teldrassil?",a="Som Frahun påpekar är den rådande vapenvilan med yttre fraktioner osäker. Smygande spejare och underrättelseinhämtare är viktiga för att avslöja ränker, särskilt sådana som rör hordens rörelser och hot inifrån mot trädgrenarna.",al={"varför behöver night elf skurkar","skurkar i shadowglen","skurkarnas syfte"}},{q="Vad händer när jag visar sigillet för Frahun?",a="Frahun tar emot chiffret, bekräftar att du är redo och ber dig återkomma när du fått mer erfarenhet. Då kan han lära dig stridstekniker, vapenhantering och konsten att smyga.",al={"what comes next","efter encrypted sigil","sigillets berättelselore"}},{q="Hotar horden Shadowglen direkt?",a="Teldrassils avlägsna trädkronor ligger till stor del avskilda från öppna angrepp från horden. Men rykten om hordeagenter som sprider misstro i Kalimdor håller kaldoreis vaktposter och agenter på högsta beredskap.",al={"finns horden i teldrassil","hotar horden shadowglen","horden sprider misstro"}}},fp="15,194,24.369.0,20.335.0,28.154.0,41.158.0,39.144.0,45.169.0,50.201.0,53.166.0"}
P.entries["quest:3119"] = {n="Hallowed Sigil",s="Hallowed Sigil är en introducerande kallelse till unga Night Elf-präster som börjar sin träning i Shadowglen. Conservator Ilthalaine förmedlar budskapet från prästtränaren Shanda och uppmanar noviserna att söka vägledning i Aldrassil medan de lär sig att använda Elunes nåd.",h="Hallowed Sigil är en introducerande kallelse till unga Night Elf-präster som börjar sin träning i Shadowglen.",kw={"aldrassil","conservator ilthalaine","elune","hallowed sigil","präst","shadowglen","shanda","teldrassil"},ang={["class:Priest"]="Den här övergångsriten för samman en kaldorei-novispräst med Shanda och inleder hens formella utbildning i Elunes ljus och visdom.",["faction:Alliance"]="Shandas kommentarer visar hur de nyetablerade banden mellan Alliansen och andra för med sig främmande folkslag och resenärer ända till Teldrassils grenar.",["race:NightElf"]="Prästerskapet är centralt i kaldoreikulturen och styrs av uråldriga traditioner av månens dyrkan som har väglett deras folk i årtusenden."},sec={{t="En kallelse till tjänst",b="Präster har en helig plats i Night Elf-kulturen som mångudinnan Elunes tjänarinnor och tjänare. När en ung kaldorei i Shadowglen visar fallenhet för det gudomliga ljuset och hängivenhet, anförtror Conservator Ilthalaine dem en helgad sigill. Budbäraren har fått den av prästtränaren Shanda, och den fungerar som en formell inbjudan att infinna sig vid Aldrassils träd och inleda en hängiven andlig utbildning."},{t="En värld i förändring",b="När den unga akolyten möter Shanda upptäcker hen att Teldrassils skyddade fristad genomgår ovanliga omvälvningar. Shanda berättar att Världsträdets grenar fylls av resenärer, däribland medlemmar av den större Alliansen som fått tillstånd att träffa kaldorei. Medan den större världen kallar råder Shanda noviserna att först ta itu med problemen som Shadowglen står inför innan de ger sig in i konflikterna längre bort."}},faq={{q="Vad är Hallowed Sigil?",a="Det är en inskriven symbol som prästtränaren Shanda skickat med en budbärare till Conservator Ilthalaine för att kalla en novispräst till undervisning i Aldrassil.",al={"föremålet hallowed sigil","vad är det här sigillet","shandas sigill"}},{q="Vem är Shanda?",a="Shanda är prästtränaren som håller till i Aldrassil i Shadowglen. Hon vägleder unga Night Elf-präster i The Sisterhood of Elunes grundläggande riter, discipliner och böner.",al={"prästtränare i aldrassil","vem är shanda"}},{q="Var finns Shanda?",a="Shanda håller till inne i den urholkade basen av Aldrassil, det väldiga trädet mitt i Shadowglen på Teldrassil.",al={"hitta shanda","var lämnar man in hallowed sigil","var finns shanda"}},{q="Varför besöker Alliansens medlemmar Teldrassil?",a="Night Elf har knutit band till Alliansen efter Tredje kriget. Andra folkslag börjar anlända till Teldrassils grenar för att samordna sig och överlägga med kaldorei medan båda sidor förbereder sig för utmaningarna som Azeroth står inför.",al={"alliansen i teldrassil","varför finns främlingar på världsträdet"}},{q="Vad bör en präst göra efter att ha slutfört uppgiften?",a="Shanda råder präster att hjälpa de lokala försvararna och väktarna runtom i Shadowglen och återvända till henne när de behöver lära sig nya böner och tekniker.",al={"vad gör man efter sigillet","efter hallowed sigil"}},{q="Varför ger Ilthalaine det här uppdraget?",a="Conservator Ilthalaine ansvarar för novisernas första prövningar i Shadowglen. När en budbärare från Shanda anlände med sigillet behöll Ilthalaine det tills den blivande prästen visade sig redo att ta nästa steg.",al={"conservator ilthalaine präst","varför prata med ilthalaine"}}},fp="14,181,20.343.0,16.355.0,27.147.0,14.134.0,24.111.0,45.280.0,51.144.0,36.204.0"}
P.entries["quest:312"] = {n="Tundra MacGrann's Stolen Stash",s="Tundra MacGrann, en skadad dvärgjägare i Dun Moroghs kalla berg, har förlorat sina vinterförråd till ett fruktat odjur. En väldig yeti vid namn Old Icebeard släpade iväg MacGranns köttkista, förstärkt med thorium, till sitt näste. Eftersom jägaren inte kan springa ifrån odjuret med sitt skadade ben förlitar han sig på förbipasserande äventyrare som kan smyga in och hämta hans förråd.",h="Tundra MacGrann, en skadad dvärgjägare i Dun Moroghs kalla berg, har förlorat sina vinterförråd till ett...",kw={"torkat kött","dun morogh","köttkista","old icebeard","stulet förråd","thorium","tundra macgrann","yeti"},ang={["class:Hunter"]="Andra spårare kan förstå hur illa det måste kännas för MacGrann när månader av omsorgsfull styckning och konservering av vilt går om intet på grund av ett opportunistiskt odjur, medan han är ute och spårar hjort.",["class:Rogue"]="MacGrann söker särskilt efter smygande resenärer. Det här är ett skolboksexempel på ett uppdrag för spejare som kan slinka in bakom ryggen på Old Icebeard utan att dra ett enda vapen.",["race:Dwarf"]="Varje dvärg i Dun Morogh känner till hur skoningslöst en bergsvinter slår. Utan konserverat kött eller skydd kan inte ens en härdad bergsbo stå emot kylan."},sec={{t="Vinterförråd och stulna kistor",b="Att överleva Dun Moroghs hårda vintrar kräver förberedelser, särskilt för bergsbor långt från värmen i Kharanos och Ironforge. Tundra MacGrann hade noggrant saltat in torkat kött för en hel månad, så att det skulle räcka genom den annalkande kalla årstidens snöbyar. För att skydda ransonerna mot hungriga vildbjörnar förvarade han dem i en förstärkt köttkista av thorium. Tyvärr räknade han inte med bergyetiernas råstyrka. De bar iväg hela kistan i stället för att försöka öppna den på plats."},{t="Old Icebeards näste",b="Tjuven är Old Icebeard, en fruktad och våldsam yeti som håller till bland de karga kullarna. Medan MacGrann var ute och jagade hjort stal Icebeard kistan och släpade den till sin bergsgrotta. MacGrann är övertygad om att inte ens en yeti kan slå sönder den massiva thoriumplåten, men hans skadade ben gör ett försök att hämta den självmordsbenäget. Den som vågar sig in i grottan måste antingen möta odjuret eller passa på när det är ute och strövar bland snödrivorna."}},faq={{q="Vem är Tundra MacGrann?",a="Tundra MacGrann är en dvärgfångstman och jägare som bor i Dun Moroghs snöiga vidder. Med ett skadat ben är han beroende av sina insamlade förråd för att klara vinterns hårda förhållanden.",al={"tundra macgrann","macgrann","vem är macgrann"}},{q="Vem stal MacGranns köttkista?",a="En hotfull lokal yeti vid namn Old Icebeard stal kistan medan MacGrann var ute och jagade hjort och släpade den tunga thoriumkistan till sitt bergsbo.",al={"vem stal förrådet","vem tog köttet","tjuven som stal förrådet"}},{q="Varför kan MacGrann inte hämta köttet själv?",a="MacGrann har ett skadat ben som begränsar hans rörlighet kraftigt. Han vet att han inte kan ta sig in i Old Icebeards grotta och ut igen snabbt eller tyst nog för att undgå att bli upptäckt och söndersliten.",al={"varför kan macgrann inte hämta det","macgranns ben","skadat ben"}},{q="Åt yetin upp maten?",a="Nej. Det torkade köttet låg inlåst i en stadig kista av massivt thorium. Yetin lyckades bära iväg den tunga behållaren, men kan inte bryta igenom metallen.",al={"är maten uppäten","kan icebeard öppna kistan"}},{q="Måste du slåss mot Old Icebeard för att få tag på köttkistan?",a="Nej, du behöver inte nödvändigtvis slåss mot honom. Old Icebeard strövar regelbundet omkring utanför sitt näste, vilket ger smidiga äventyrare chansen att smyga in i grottan och plundra kistan obemärkt.",al={"kan man smyga förbi icebeard","måste jag döda icebeard"}},{q="Var finns det stulna förrådet?",a="Den stulna köttkistan står djupt inne i Old Icebeards bergsgrotta, i kullarna nära MacGranns läger i Dun Morogh.",al={"var ligger grottan","icebeards grotta plats"}}},fx={ceb049bb={q="Varför behöver Tundra MacGrann få tillbaka sitt köttförråd?",a="MacGrann tillbringade långa dagar med att jaga och salta en hel månads ransoner för att klara den hårda köldperioden i Dun Morogh. Utan det konserverade köttet riskerar han att svälta i sitt avlägsna bergsläger när vinterns snöbyar drar in. Hans skadade ben hindrar honom från att jaga tillräckligt med vilt för att fylla på vinterförrådet i tid.",al={"varför hjälpa tundra macgrann","macgranns motiv","varför hämta köttförrådet"}},["9ce729b1"]={q="Vad är MacGrann's Dried Meats?",a="Det är ett stort förråd av saltat hjortkött och vilt som Tundra MacGrann konserverade särskilt för att räcka hela bergsvintern. Han låste in köttet i en förstärkt thoriumkista för att hålla asätande björnar borta. Lyckligtvis visade den sig också tåla att Old Icebeard försökte slita sig in.",al={"macgranns torkade kött","vad är macgrann's dried meats","innehållet i macgranns köttförråd"}}},fp="30,181,32.217.0,18.290.0,23.153.0,33.141.0,46.118.0,26.128.0,57.107.0,34.116.0"}
P.entries["quest:3120"] = {n="Verdant Sigil",s="Verdant Sigil är en skriftlig kallelse som överlämnas till nyväckta nattalvdruider i Shadowglen. Conservator Ilthalaine för den vidare för att hänvisa nyblivna skepnadsskiftare till Mardant Strongoak bland Aldrassils grenar. Den markerar den formella början på en druids undervisning i naturens mysterier och Emerald Dream.",h="Verdant Sigil är en skriftlig kallelse som överlämnas till nyväckta nattalvdruider i Shadowglen.",kw={"aldrassil","druidtränare","emerald dream","ilthalaine","mardant strongoak","shadowglen","verdant sigil"},ang={["class:Druid"]="Det här uppdraget är din formella invigning i Cenarion Circles läror under Mardant Strongoak och inleder din långa väg mot förståelsen av Emerald Dream.",["race:NightElf"]="Druidismen är djupt sammanvävd med nattalvskulturen. När en novis visar det här sigillet vid Aldrassil tar hen sitt första steg in i en uråldrig tradition."},sec={{t="En kallelse till grenverket",b="När en ung nattalv visar prov på att bevara balansen i Shadowglen krävs en formell introduktion till deras orden. Conservator Ilthalaine tar emot Verdant Sigil via en budbärare och lämnar den till novisen. Den lilla symbolen visar att kretsen i Aldrassil har lagt märke till den unga druiden och inbjuder hen att inleda sin utbildning formellt."},{t="Gemenskap och drömmen",b="När novisen visar sigillet för Mardant Strongoak inne i Aldrassil välkomnas hen in i gemenskapen. Djupare gemenskap med Emerald Dream och mästerskap i djurformer väntar längre fram, men Mardant blir novisens första vägledare och får i uppgift att lära hen tolka naturens andar och kanalisera skogens råa kraft."}},faq={{q="Vad är Verdant Sigil?",a="Det är en inskriven kallelse som överlämnas genom Conservator Ilthalaine på uppdrag av Mardant Strongoak och kallar en nybörjardruid till sin formella utbildning i Aldrassil.",al={"föremålet verdant sigil","vad är det här sigillet","druidsigill"}},{q="Vart ska jag ta Verdant Sigil?",a="Ta den till Mardant Strongoak, druidtränaren som håller till i Aldrassils stora gravhögsträd, mitt i Shadowglen.",al={"var finns mardant","lämna in verdant sigil","vart ska jag gå"}},{q="Varför nämner Mardant Emerald Dream?",a="Druider hämtar mycket av sin kraft och visdom från Emerald Dream genom långa sömntrancer. En novis är ännu inte redo att vandra fritt i drömmen, men Mardant presenterar den som det grundläggande mysterium hen så småningom ska studera.",al={"varför emerald dream","mardants dialog om drömmen","druidtrance"}},{q="Vem skickar sigillet till Ilthalaine?",a="En budbärare utsänd av Mardant Strongoak överlämnade sigillet till Conservator Ilthalaine, så att det kunde hamna direkt i händerna på en lovande ung druid.",al={"vem skickade sigillet","sigillets budbärare"}},{q="Vad händer när jag visar sigillet?",a="Mardant Strongoak blir din främsta mentor i Shadowglen och låter dig lära dig dina första druidbesvärjelser och magiska tekniker medan du växer i kraft.",al={"vad lär jag mig härnäst","efter verdant sigil"}},{q="Kan icke-druider få det här uppdraget?",a="Nej. Verdant Sigil är endast avsett för nattalvdruider som börjar sin resa i Shadowglen. Andra klasser får egna kallelser till sina respektive tränare.",al={"är det här bara för druider","vem får verdant sigil"}}},fp="13,278,20.322.0,23.295.0,26.160.0,34.116.0,43.191.0,34.142.0,40.150.0,34.154.0"}
P.entries["quest:3121"] = {n="A Strange Request",s="Witch Doctor Uzer'i behöver en brygd som Neeru Fireblade i Orgrimmar har blandat till. Uzer'i ger dig ett krympt huvud, som utlovats till Neeru i utbyte mot örterna, och skickar dig till The Cleft of Shadow i Orgrimmar för att lämna över det.",h="Witch Doctor Uzer'i behöver en brygd som Neeru Fireblade i Orgrimmar har blandat till.",kw={"a strange request","cleft of shadow","feralas","neeru fireblade","orgrimmar","krympt huvud","witch doctor uzer'i"},sec={{t="En utlovad betalning",b="Witch Doctor Uzer'i säger att Neeru Fireblade i Orgrimmar har det som behövs för att komma igång i Feralas: en brygd till något som Uzer'i ännu inte vill förklara. Uzer'i ger dig ett krympt huvud, som utlovats till Neeru i utbyte mot örterna. Det är huvudet från en stackars dvärg som Uzer'i stötte på i skogen. Neeru finns i The Cleft of Shadow."},{t="Neerus örter",b="Neeru Fireblade har väntat på att Uzer'i ska leverera detta och lämnar över örtblandningen som förberetts för Uzer'is experiment."}},faq={{q="Vem ger uppdraget A Strange Request?",a="Witch Doctor Uzer'i, som låter dig ta ett krympt huvud till Orgrimmar.",al={"vem ger strange request","vem startar uppdraget","uppdragsgivare för strange request"}},{q="Var finns Neeru Fireblade?",a="I The Cleft of Shadow, i Orgrimmar.",al={"var finns neeru fireblade","vart ska jag gå","plats för leverans av krympt huvud"}},{q="Vems huvud är det krympta huvudet?",a="Uzer'i säger att det är huvudet från en stackars dvärg som hittades i skogen.",al={"vems huvud är det här","krympt huvud identitet","vem var dvärgen"}},{q="Varför skickar Uzer'i ett krympt huvud till Neeru?",a="Uzer'i lovade Neeru huvudet i utbyte mot örterna och behöver brygden som Neeru har blandat till.",al={"varför vill neeru ha huvudet","neeru fireblade byte"}},{q="Vad följer efter A Strange Request?",a="Uppdragskedjan fortsätter med Return to Witch Doctor Uzer'i.",al={"vad händer härnäst","nästa uppdrag efter strange request"}}},fp="17,230,18.343.0,13.133.1,28.67.0,25.37.0,32.71.0,46.99.0,31.53.0"}
P.entries["quest:3122"] = {n="Return to Witch Doctor Uzer'i",s="När du har lämnat över det krympta huvudet i A Strange Request ger Neeru Fireblade dig örterna och ber dig ta dem till Witch Doctor Uzer'i i Feralas, tillsammans med beskedet att Neeru är nöjd med huvudet.",h="När du har lämnat över det krympta huvudet i A Strange Request ger Neeru Fireblade dig örterna och ber dig ta...",kw={"feralas","örtpåse","muisek-kärl","krympt huvud","witch doctor uzer'i"},sec={{t="Örterna ska tillbaka",b="Efter A Strange Request ger Neeru Fireblade dig en påse med örter till Witch Doctor Uzer'i. Du ska också säga till Uzer'i att Neeru är nöjd med det krympta huvudet. Påsen ska till Uzer'i i Feralas."},{t="Ritualen börjar",b="Uzer'i säger att örterna är precis vad som behövs för att förbereda muisek-kärlet och hoppas att hans senaste besvärjelser är lika kraftfulla som han har hoppats. Han ber dig vänta en stund medan han utför ritualen och använder örterna."}},faq={{q="Vem ger örterna till Witch Doctor Uzer'i?",a="Neeru Fireblade, den du lämnade det krympta huvudet till.",al={"var börjar det här uppdraget","vem gav örterna"}},{q="Vart ska örterna?",a="Till Witch Doctor Uzer'i i Feralas.",al={"vilka örter är det här","vart ska jag ta örtpåsen"}},{q="Var Neeru nöjd med det krympta huvudet?",a="Ja. Neeru är nöjd med huvudet och ber dig säga det till Uzer'i.",al={"gillade neeru huvudet","neeru byter krympt huvud"}}},fp="29,207,17.216.0,17.225.1,43.58.0,22.34.0,41.71.0"}
P.entries["quest:3123"] = {n="Testing the Vessel",s="Witch Doctor Uzer'i säger, efter Return to Witch Doctor Uzer'i, att detta är ett prov på ritualen som Uzer'i utförde och på dina egna förmågor. Du får ett kärl som kan krympa och fånga en varelse, och skickas till The Hinterlands för att fånga tio wildkin och sedan ta dem tillbaka till Uzer'i i Feralas.",h="Witch Doctor Uzer'i säger, efter Return to Witch Doctor Uzer'i, att detta är ett prov på ritualen som Uzer'i...",kw={"elune","feralas","the hinterlands","muisek","owlbeast","uzer'i","kärl","wildkin"},sec={{t="Ett kärl för The Hinterlands",b="Witch Doctor Uzer'i kallar detta ett prov, både på ritualen som just utförts och på dina egna färdigheter. Kärlet du får kan krympa en varelse och fånga den inuti. Du beger dig till The Hinterlands och letar efter wildkin, vars släkte en gång hölls som husdjur av Elune, nattalvernas gudinna. Uzer'i pekar ut de ondskefulla, primitiva och vilda owlbeasts som ditt byte. Tio måste fällas, och var och en krympas in i kärlet innan dess ande hinner fly. Du tar de tio och kärlet tillbaka till Uzer'i i Feralas."},{t="Efteråt",b="När en varelse dör våldsamt kan dess muisek komma loss och söka hämnd, förklarar Uzer'i. Genom att krympa den fallna varelsen, som du gjorde, hindrar du muisek från att komma undan, och Uzer'i säger nu att den kan användas när som helst."}},faq={{q="Vem ger uppdraget Testing the Vessel?",a="Witch Doctor Uzer'i, som räcker dig kärlet.",al={"uppdragsgivare för testing the vessel","vem ger testing the vessel"}},{q="Var finns wildkin?",a="Uzer'i skickar dig till The Hinterlands för att leta efter dem.",al={"var man hittar wildkin","wildkin plats"}},{q="Vilka varelser är målen?",a="De ondskefulla, primitiva eller vilda owlbeasts som kallas wildkin. Tio behövs.",al={"vilka wildkin man ska döda","målen i testing the vessel"}},{q="Vad har wildkin för koppling till Elune?",a="Uzer'i säger att wildkin brukade vara husdjur åt Elune, nattalvernas gudinna.",al={"wildkin och elune i berättelsen","varför wildkin"}},{q="Vad kan kärlet göra?",a="Det låter dig krympa en fallen varelse och fånga den, så att dess ande inte kan komma undan.",al={"hur fungerar muisek-kärlet","kärlets kraft"}},{q="Vad följer efter Testing the Vessel?",a="Uppdragskedjan fortsätter med Hippogryph Muisek.",al={"nästa uppdrag efter testing the vessel","vad kommer efter testing the vessel"}}},fp="18,296,28.485.0,9.208.1,29.46.0,22.53.0,32.76.0,47.68.0,23.88.0,32.41.0"}
P.entries["quest:3124"] = {n="Hippogryph Muisek",s="Efter dina prövningar med muisekkärlet ber Witch Doctor Uzer'i dig att ta itu med en annan varelse. Frayfeather-hippogryfer i High Wilderness ska dödas och genast krympas in i kärlet, så att deras muisek bevaras.",h="Efter dina prövningar med muisekkärlet ber Witch Doctor Uzer'i dig att ta itu med en annan varelse.",kw={"feralas","frayfeather","high wilderness","hippogryf muisek","muisekkärl","witch doctor uzer'i"},sec={{t="Trogna följeslagare",b="Witch Doctor Uzer'i har bedömt att du är pålitlig och kan hantera kärlet, och vill nu ha en annan varelses ande. Hippogryfer är nattalvernas gamla följeslagare, och deras andar är trogna och ståndaktiga. Tio Frayfeather-hippogryfer av valfri sort ska dödas, krympas och fångas snabbt med kärlet så att deras muisek bevaras. Uzer'i placerar dem i High Wilderness, söder om lägret."},{t="Uzer'is varning",b="Uzer'i säger att om ett dödat djurs muisek tillåts fly, kan det anta formen av en ännu större varelse, och då får du aldrig någon ro från dess hämnd. Uzer'i kallar uppdraget farligt och säger att du har klarat det bra igen."}},faq={{q="Vem skickar dig för att fånga hippogryfer?",a="Witch Doctor Uzer'i. Du kommer till det här steget efter Testing the Vessel.",al={"hippogryf muisek uppdragsgivare","vem ger hippogryf muisek","var får man hippogryf muisek"}},{q="Var hittar man Frayfeather-hippogryferna?",a="De finns i High Wilderness, som Uzer'i placerar söder om lägret.",al={"var finns frayfeather-hippogryfer","hippogryf plats feralas","var hittar man hippogryfer i feralas"}},{q="Varför vill Witch Doctor Uzer'i ha hippogryfers andar?",a="Uzer'i talar om hippogryfer som nattalvernas gamla följeslagare, med trogna och ståndaktiga andar. Målet är att bevara deras muisek.",al={"varför hippogryfer","varför fånga hippogryf muisek","uzeri hippogryf motiv"}},{q="Hur fångas muisek?",a="Döda en Frayfeather-hippogryf och krymp och fånga den sedan snabbt med muisekkärlet. Tio behövs, av valfri sort.",al={"hur använder man muisekkärlet","hur får man hippogryf muisek","fånga frayfeather muisek"}},{q="Vilket steg kommer före detta i kedjan?",a="Testing the Vessel, där du visade dig vara pålitlig och kunna använda muisekkärlet.",al={"förkunskapskrav hippogryf muisek","föregående uppdrag hippogryf muisek","krav före hippogryf muisek"}}},fp="17,234,16.426.0,16.241.1,37.68.0,44.78.0,53.145.0,27.118.0,41.92.0"}
P.entries["quest:3125"] = {n="Faerie Dragon Muisek",s="Efter hippogryfernas andar vill Witch Doctor Uzer'i nu ha en faeriedrakes ande. Du skickas västerut för att jaga sprite darters och sprite dragons och fånga det som gör dem starka.",h="Efter hippogryfernas andar vill Witch Doctor Uzer'i nu ha en faeriedrakes ande.",kw={"faeriedrake-muisek","feralas","hippogryph-muisek","horde","muisek vessel","sprite darter","sprite dragon","treant-muisek","witch doctor uzer'i"},sec={{t="Skört yttre, stark ande",b="Uzer'i påpekar att faeriedrakar verkar sköra, men att deras ande är det verkliga priset. De har varit nattalvernas allierade, och Uzer'i vill att Horde också ska få del av den styrkan. Uzer'i ger dig ett Muisek Vessel och skickar dig västerut för att döda åtta sprite darters eller sprite dragons. Krymp sedan varje fallen faeriedrake och fånga den med kärlet."},{t="Tillbaka hos Uzer'i",b="När du återvänder med de fångade andarna tackar Uzer'i dig och säger att faeriedrakeandarnas kraft nu står till Hordes förfogande. Uzer'i hoppas också att du går med på ett jobb till."}},faq={{q="Varför vill Witch Doctor Uzer'i ha faeriedrakeandar?",a="Uzer'i säger att faeriedrakar ser sköra ut men har en mäktig ande, och att de har varit nattalvernas allierade. Uzer'i vill att Horde också ska dra nytta av den styrkan.",al={"varför faeriedrakar","syftet med faeriedrake-muisek","varför döda sprite darters"}},{q="Var hittar man faeriedrakarna?",a="Uzer'i säger att de finns väster om där Uzer'i står.",al={"var finns sprite darters","sprite darters plats","faeriedrake plats feralas"}},{q="Vilka varelser ger denna muisek?",a="Sprite darters och sprite dragons. Åtta av dem måste dödas och fångas.",al={"vilka fiender ger muisek","vad ska jag döda för faeriedrake-muisek","faeriedrake-muisek mål"}},{q="Vad måste göras med de fallna varelserna?",a="Använd Muisek Vessel på varje fallen faeriedrake för att krympa den och fånga dess muisek.",al={"hur får man faeriedrake-muisek","hur fungerar muisek vessel","fånga muisek"}},{q="Var passar det här steget in bland Uzer'is uppdrag?",a="Det kommer efter Hippogryph Muisek, och Treant Muisek är nästa steg.",al={"vilket uppdrag kommer före detta","ordning i muisek-uppdragskedjan","vad kommer efter faeriedrake-muisek"}}},fp="20,187,28.343.0,21.194.1,56.180.0,38.49.0,35.80.0,42.91.0,49.80.0"}
P.entries["quest:3126"] = {n="Treant Muisek",s="Witch Doctor Uzer'i har ett nytt mål: skogens vandrande väktare, treants som långsamt strövar genom skogen. Efter faerie dragons får du i uppdrag att hitta tre av dem.",h="Witch Doctor Uzer'i har ett nytt mål: skogens vandrande väktare, treants som långsamt strövar genom skogen.",kw={"feralas","muisek vessel","treant muisek","treants","uzer'i","vandrande skogsväktare"},sec={{t="Långsamma beskyddare",b="Uzer'i säger att nattalverna har rekryterat treants som allierade i sin kamp mot Horde. De rör sig långsamt, men Uzer'i menar att deras roll som beskyddare är obestridlig och tänker vända den kraften till Hordes egen fördel."},{t="Tre skogsvandrare",b="Uzer'i vill att du hittar och dödar tre vandrande skogsväktare och sedan krymper och fångar varje fallen treant med Muisek Vessel."},{t="Uzer'is dom",b="När du återvänder tackar Uzer'i dig och säger att samlingen av muisek nästan är komplett."}},faq={{q="Vem skickar äventyrare efter treants?",a="Witch Doctor Uzer'i, som ber om det här direkt efter faerie dragons.",al={"vem ger treant muisek","uppdragsgivare för treant muisek","uzeri treant-uppdrag"}},{q="Varför vill Witch Doctor Uzer'i ha treant-muisek?",a="Uzer'i säger att nattalverna har rekryterat treants som allierade i sin kamp mot Horde och vill använda deras beskyddande kraft till Hordes egen fördel.",al={"varför döda skogsväktare","varför treant muisek","uzeris motiv med treants"}},{q="Vilka varelser måste hittas för Treant Muisek?",a="Vandrande skogsväktare som strövar genom skogen. Tre av dem behövs.",al={"vilka treants ska dödas","vandrande skogsväktare","mål för treant muisek"}},{q="Hur fångas treants?",a="När en vandrande skogsväktare har fallit används Muisek Vessel för att krympa och fånga den.",al={"hur man använder muisek vessel","fånga skogsväktare","krympa treants"}},{q="Var i Uzer'is uppdrag kommer Treant Muisek?",a="Det följer efter Faerie Dragon Muisek, och Mountain Giant Muisek kommer därefter.",al={"treant muisek-uppdragskedja","vad kommer efter faerie dragon muisek","nästa uppdrag efter treant muisek"}}},fp="13,165,15.223.0,20.129.0,16.94.1,40.70.0,48.163.0,47.74.0,29.93.0,53.74.0"}
P.entries["quest:3127"] = {n="Mountain Giant Muisek",s="Witch Doctor Uzer'i kallar detta det sista uppdraget och skickar dig nordväst för att hitta den sista fienden: mountain giants, vars storlek och styrka Uzer'i gärna vill ta till vara på.",h="Witch Doctor Uzer'i kallar detta det sista uppdraget och skickar dig nordväst för att hitta den sista...",kw={"burning legion","cliff giant","feralas","land walker","mountain giant muisek","muisek vessel","treant muisek","witch doctor uzer'i"},sec={{t="Jättar på klippig mark",b="Enligt Uzer'i kom mountain giants ner från bergen för att hjälpa nattalverna när Burning Legion anlände till världen. De känns lätt igen på sin enorma storlek och skälvningarna under fötterna på deras klippiga mark. Uzer'i vill gärna ta till vara på krafter av den storleken. Uzer'i vill att du fäller sju Land Walkers eller Cliff Giants, krymper var och en och fångar dem med Muisek Vessel."},{t="Uzer'is skryt",b="När du återvänder talar Uzer'i om möjligheterna med det som nu har samlats in. Med materialet du samlat längs vägen hävdar Uzer'i att hen kan fånga dessa varelsers andar för gott i vad Uzer'i än önskar."}},faq={{q="Vem ber om mountain giants muisek?",a="Witch Doctor Uzer'i, som kallar det din sista begäran.",al={"uppdragsgivare","vem ger mountain giant muisek","uzeri uppdrag"}},{q="Var finns mountain giants?",a="Uzer'i skickar dig nordväst för att hitta dem på klippig mark.",al={"mountain giant plats","var finns land walkers","cliff giant plats"}},{q="Varför finns mountain giants här?",a="Enligt Uzer'i kom de ner från bergen för att hjälpa nattalverna när Burning Legion anlände till världen.",al={"varför finns jättarna här","mountain giant historia feralas"}},{q="Vilka varelser ger den muisek som behövs?",a="Land Walkers och Cliff Giants. Sju behövs, och Muisek Vessel krymper och fångar var och en som fälls.",al={"vad ska jag döda för muisek","vilka jättar räknas"}},{q="Vad kommer före detta i ordningen?",a="Det följer efter Treant Muisek, och Weapons of Spirit står efter det.",al={"föregående uppdrag","muisek-uppdragens ordning"}}},fp="21,161,26.395.0,14.235.1,41.58.0,38.67.0,29.124.0,44.108.0,39.67.0"}
P.entries["quest:3128"] = {n="Natural Materials",s="Witch Doctor Uzer'i i Camp Mojache behöver material för att slutföra ett uppdrag tillsammans med de andra prövningarna: splittrade stockar, mineraler med beläggning, seg senor och metallfragment från treanter, bergsjättar, älvdrakar, ugglebestar och hippogryfer.",h="Witch Doctor Uzer'i i Camp Mojache behöver material för att slutföra ett uppdrag tillsammans med de andra...",kw={"camp mojache","mineraler med beläggning","feralas","metallfragment","muisek","naturmaterial","seg sena","splittrad stock","the hinterlands","witch doctor uzer'i"},sec={{t="Insamling åt Witch Doctor",b="När du återvänder till Witch Doctor Uzer'i väntar en ytterligare materiallista som ska samlas in tillsammans med de andra prövningarna. Två splittrade stockar behövs från en treant i Feralas. Sex stycken mineraler med beläggning finns hos bergsjättar och älvdrakar västerut. Tjugo stycken seg sena får du från ugglebestar i The Hinterlands eller hippogryfer i Feralas. En stor mängd metallfragment, fyrtio stycken sammanlagt, kan komma från vilken som helst av dessa varelser."},{t="Uzer'is besked",b="När materialen lämnas tillbaka blir Uzer'i nöjd. Tillsammans med muisek bör de ge precis det resultat som eftersträvats."}},faq={{q="Vem efterfrågar de här naturmaterialen?",a="Witch Doctor Uzer'i i Camp Mojache.",al={"vem ger naturmaterial","uppdragsgivare för naturmaterial","var startar naturmaterial"}},{q="Vilka varelser har de splittrade stockarna?",a="En treant i Feralas; två splittrade stockar behövs.",al={"var hittar man splittrade stockar","vem släpper splittrad stock","källa till splittrad stock"}},{q="Var kan man samla mineraler med beläggning?",a="Bergsjättar och älvdrakar västerut bär på dem; sex stycken behövs.",al={"hur får man mineraler med beläggning","källa till mineraler med beläggning","vem släpper mineraler med beläggning"}},{q="Vilka bestar ger den sega senan?",a="Ugglebestarna i The Hinterlands eller hippogryferna i Feralas; tjugo stycken behövs.",al={"seg sena byte","var hittar man seg sena","vem har seg sena"}},{q="Varifrån kommer metallfragmenten?",a="Fyrtio stycken kommer från vilken som helst av de nämnda varelserna: treanter, bergsjättar, älvdrakar, ugglebestar och hippogryfer.",al={"källa till metallfragment","hur får man metallfragment","vem släpper metallfragment"}},{q="Vad föregick den här begäran?",a="Den här begäran följer på Return to Witch Doctor Uzer'i.",al={"förkunskapskrav för naturmaterial","föregående uppdrag naturmaterial","vad leder till naturmaterial"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="Weapons of Spirit",s="Witch Doctor Uzer'i har nu allt som behövs och andarna du fångade. Att binda dem till vapen är ett hårt arbete, så Uzer'i ber dig vänta en stund medan förberedelserna görs.",h="Witch Doctor Uzer'i har nu allt som behövs och andarna du fångade.",kw={"feralas","muisek","andevapen","weapons of spirit","witch doctor uzer'i"},sec={{t="Lite tålamod",b="Uzer'i medger att det är slitsamt att genomsyra vapen med muisek. Nu när allt material som behövs finns till hands, liksom andarna du fångade, kan Uzer'i sätta igång och ber dig vänta medan vapnen förbereds."},{t="När väntan är över",b="Uzer'i återvänder och låter dig välja bland vapnen. Uzer'i berättar att andarna från de fångade varelserna är förseglade i dem för gott. Nu kan du använda deras energi som din egen."}},faq={{q="Vem ligger bakom Weapons of Spirit?",a="Witch Doctor Uzer'i, samma person som skickade dig efter muisek. Det här uppdraget kommer efter Mountain Giant Muisek.",al={"vem ger weapons of spirit","uppdragsgivare för weapons of spirit","uzeri uppdrag"}},{q="Vad gör Witch Doctor Uzer'i under det här steget?",a="Uzer'i arbetar med att genomsyra vapen med det fångade muiseket. Processen beskrivs som svår, och Uzer'i ber dig vänta medan förberedelserna görs.",al={"vad händer i weapons of spirit","vad gör uzeri"}},{q="Vad behövs innan Uzer'i kan sätta igång?",a="Uzer'i säger att det material som behövs har samlats in och att andarna du fångade finns till hands, så arbetet kan börja.",al={"krav för weapons of spirit","förutsättningar för weapons of spirit"}}},fp="17,184,19.207.0,18.178.1,32.106.0,50.139.0,39.110.0"}
P.entries["quest:313"] = {n="The Grizzled Den",s="Pilot Stonegear från Kharanos söker någon med riktigt dvärgiskt gry för att piffa upp sin älskade belägringsmaskin, Trollplow. För att pröva en aspirerande äventyrares mod skickar han dem västerut till den farliga grottan The Grizzled Den för att jaga vilda wendigos och få deras tjocka pälsar.",h="Pilot Stonegear från Kharanos söker någon med riktigt dvärgiskt gry för att piffa upp sin älskade...",kw={"dun morogh","the grizzled den","kharanos","pilot stonegear","trollplow","wendigo","wendigo mane"},ang={["profession:Engineering"]="Den som uppskattar dvärgiska belägringsfordon vet att det krävs kreativa lösningar för att hålla förarhytten varm när tungt maskineri ska underhållas i minusgrader.",["race:Dwarf"]="För unga Mountaineers och äventyrare från Ironforge är det en klassisk lokal övergångsrit att ta sig an wendigos i The Grizzled Den.",["race:Gnome"]="Att leva sida vid sida med dvärgarna kring Kharanos innebär att hjälpa till med att utrusta Ironforges tunga pansarfordon."},sec={{t="Ett prov på mod",b="Att köra en massiv dvärgisk belägringstank kräver nerver av stål och en kropp som tål skramlande maskineri i den iskalla bergsluften. Pilot Stonegear, stationerad vid Steelgrill's Depot nära Kharanos, hävdar att han har gott om båda delarna. Han ger varken lätt upp arbete eller respekt, utan utmanar nykomlingar att visa samma ståndaktighet genom att ta sig ut i de frusna kullarna och möta traktens bestar."},{t="Bekvämligheter i Trollplow",b="Stonegears belägringsmaskin bär det stolta och föga subtila namnet Trollplow, men dess trånga, järnpläterade hytt är obarmhärtigt kall i det bistra klimatet i Dun Morogh. Stonegear kommer på en praktisk men vild lösning: wendigopäls. Genom att samla in tjocka manar från de våldsamma wendigos som stryker omkring i The Grizzled Den får han materialet som behövs för att tillverka en slitstark, varm matta till Trollplows däck, samtidigt som antalet lokala bestar hålls nere."}},faq={{q="Vem är Pilot Stonegear?",a="Pilot Stonegear är en dvärgisk förare av belägringsmaskiner, stationerad utanför Kharanos i Dun Morogh. Han styr en bepansrad krigsmaskin som fått det kärleksfulla namnet Trollplow och är mycket stolt över sina nerver av stål och sitt mekaniska hantverk.",al={"pilot stonegear","vem ger uppdraget","vem är stonegear"}},{q="Var ligger The Grizzled Den?",a="The Grizzled Den är ett snötäckt grottsystem i bergen direkt väster om Kharanos. Den är en ökänd lya för Dun Moroghs våldsamma wendigos.",al={"the grizzled den plats","var finns wendigogrottan","hur hittar man the grizzled den"}},{q="Varför vill Stonegear ha wendigomanar?",a="Stonegear vill ha wendigornas tjocka, värmande päls för att tillverka en mysig matta till belägringsmaskinen Trollplows inre däck, samtidigt som han prövar en äventyrares mod.",al={"varför wendigomanar","manarnas syfte","vad används manar till"}},{q="Vad är Trollplow?",a="Trollplow är Pilot Stonegears personliga dvärgiska belägringsmaskin. Dess aggressiva namn speglar den pågående konflikten mellan Ironforges dvärgar och de fientliga Frostmane-trollen som bor i de omgivande klipporna.",al={"trollplow","stonegears stridsvagn","vad är trollplow"}},{q="Vilka slags varelser bor i The Grizzled Den?",a="Grottan bebos av vilda wendigos, förvildade, apliknande bestar som hör hemma i Dun Moroghs snöiga höjder och aggressivt försvarar sitt revir mot alla inkräktare.",al={"monster i the grizzled den","vad bor i the grizzled den"}},{q="Är wendigos farliga för Kharanos?",a="Wendigos organiserar sällan samordnade attacker som Frostmane-trollen, men deras våldsamma ursinne och närhet till huvudvägarna gör dem till ett ständigt hot mot både resenärer och lokala hantverkare.",al={"är wendigos ett hot","wendigofara"}}},fx={["9edb896b"]={q="Vad används Wendigo Manes till?",a="Pilot Stonegear vill ha de tjocka, raggiga manarna från The Grizzled Dens wendigos av ett mycket praktiskt skäl: dvärgisk heminredning. När man kör ett enormt belägringsfordon som Trollplow i Dun Moroghs bitande kyla blir metalldäcket iskallt under fötterna. Stonegear tänker sy ihop de insamlade manarna till en varm, tung matta som gör Trollplows hytt mycket trivsammare under långa patruller.",al={"vad används wendigo mane till","vad är wendigo mane till för","varför wendigo-manar"}},["72b90979"]={q="Varför skickar Pilot Stonegear dig i stället för att hämta manarna själv?",a="Stonegear är förare av ett belägringsfordon, och att hålla en järnmaskin som Trollplow i gott skick och redo att försvara Kharanos kräver hans fulla uppmärksamhet. Att jaga snabba, våldsamma wendigos i trånga, frusna grottgångar är inget arbete för en massiv krigsmaskin. Stonegear ser också uppgiften som en öppen utmaning för att se om du har den beslutsamhet, styrka och det mod som krävs av Dun Moroghs försvarare.",al={"varför jag stonegear","varför behöver stonegear hjälp","varför hämtar han inte manarna själv"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
P.entries["quest:3130"] = {n="Against the Hatecrest",s="När du har rapporterat tillbaka skickar general Shandris Feathermoon dig vidare till Latronicus Moonspear, generalens närmaste man, i Feathermoon Stronghold. Shandris vill sätta in hela styrkan mot nagafolket, men lämnar inte fästet öppet för Horden eller något värre.",h="När du har rapporterat tillbaka skickar general Shandris Feathermoon dig vidare till Latronicus Moonspear...",kw={"against the hatecrest","feathermoon stronghold","feralas","hatecrest","horden","latronicus moonspear","nagafolket","shandris feathermoon"},sec={{t="Shandris väger riskerna",b="General Shandris Feathermoon skickar dig vidare till Latronicus Moonspear, generalens närmaste man, som hittills har hållit noggrann uppsikt över nagastyrkorna. Här ska Shandris bedöma den större situationen med nagafolket. Hon vill gärna sätta in hela styrkan mot dem, men det vore knappast klokt att lämna fästet öppet för en direkt attack från Horden eller något värre. Latronicus väntar på dig i Feathermoon Stronghold."},{t="Latronicus planer",b="Latronicus Moonspear säger att generalen har gett honom i uppdrag att ta itu med nagafolket direkt. Planen har två delar: minska deras antal och försvaga deras befäl, samt ta reda på vad de gör i ruinerna. Med din hjälp kan deras närvaro bekämpas samtidigt som fästet hålls säkert."}},faq={{q="Varför skickar Shandris Feathermoon dig till Latronicus?",a="Shandris sätter inte in hela styrkan mot nagafolket om det skulle lämna Feathermoon Stronghold utsatt för Horden eller något värre. I stället hänvisar generalen dig till sin närmaste man, Latronicus, som har hållit uppsikt över nagafolket.",al={"varför tala med latronicus","varför latronicus moonspear","hänvisning till feathermoon"}},{q="Var finns Latronicus Moonspear?",a="I Feathermoon Stronghold, dit Shandris skickar dig för att rapportera till honom.",al={"latronicus plats","var finns latronicus","hitta latronicus moonspear"}},{q="Vad hände före det här uppdraget?",a="Återvänd till Feathermoon Stronghold. Därefter skickar Shandris dig vidare till Latronicus.",al={"förkunskapskrav för against the hatecrest","föregående uppdrag","början på hatecrest-uppdragskedjan"}}},fp="21,266,24.411.0,23.288.1,53.232.0,38.69.0,33.82.0"}
P.entries["quest:314"] = {n="Protecting the Herd",s="Skydda hjorden är ett uppdrag från Rudra Amberstill på Amberstill Ranch i Dun Morogh. Ett våldsamt rovdjur vid namn Vagash har nattetid angripit ranchens värdefulla bergsbaggar. Ironforges militära garnison är utspridd över riket, så de lokala uppfödarna måste förlita sig på förbipasserande äventyrare för att försvara hjorden.",h="Skydda hjorden är ett uppdrag från Rudra Amberstill på Amberstill Ranch i Dun Morogh.",kw={"amberstill ranch","dun morogh","ironforge","bergsbaggar","skydda hjorden","rudra amberstill","vagash","veron amberstill"},ang={["class:Hunter"]="Att spåra upp ett beryktat topprovdjur som Vagash i hans bergshåla är ett klassiskt prov för den som vill vässa sina färdigheter som spårare i Dun Moroghs snödrivor.",["faction:Alliance"]="När regementen från High Seat skickas ut för att stärka Alliansens åtaganden i Eastern Kingdoms hjälper du till att stabilisera hemmafronten genom att bistå utsatta gårdar på landsbygden.",["race:Dwarf"]="För dvärgiska vandrare innebär försvaret av Amberstill Ranch att skydda just de bergsbaggar som bär dina fränder ut i strid i Khaz Modan."},sec={{t="Ett hot mot ranchen",b="Amberstill Ranch föder upp bergsbaggar som är ikoniska riddjur och arbetsdjur för Bronzebeard-dvärgarna. Att hålla hjordarna vid liv är avgörande för Dun Moroghs lantliga ekonomi. När natten föll och förtvivlade rop ekade över hagarna upptäckte familjen Amberstill att två av deras värdefulla baggar saknades. Den skyldige är Vagash, ett beryktat och vildsint odjur som lurar bland klipporna nära ranchen och är känt för att brutalt angripa den lokala boskapen."},{t="Ansträngt försvar",b="Vanligtvis skulle dvärgarnas bergsklättrare eller King Magni Bronzebeards kungliga styrkor ta hand om hot av den här omfattningen. Men Ironforges stående armé är för närvarande hårt ansatt på avlägsna gränser, där den stöder den större Alliansen. Utan en officiell militärstyrka som patrullerar bergskammarna tvingas Rudra Amberstill be fristående krigare att jaga Vagash och ta med en av odjurets dödliga huggtänder som bevis."}},faq={{q="Vem är Vagash?",a="Vagash är ett farligt rovdjur som stryker omkring på de snötäckta bergskammarna precis ovanför Amberstill Ranch. Han är fruktad för sin enorma styrka och glupska aptit och utgör ett dödligt hot mot både tamdjurens hjordar och oförsiktiga resenärer i östra Dun Morogh.",al={"vad är vagash","vagash odjur","vagash bakgrund"}},{q="Var hittar man Vagash?",a="Vagash har sitt bo i en snötäckt grotta högt uppe bland klipporna med utsikt över Amberstill Ranch. Gå uppför den snötäckta kullen strax förbi tallarna bakom gården, så kommer du direkt till ingången till hans håla.",al={"vagash plats","var finns vagash","hitta vagash"}},{q="Varför tar inte vakterna från Ironforge hand om det här?",a="King Magni Bronzebeards styrkor är för närvarande utspridda för att försvara strategiska garnisoner och stödja avlägsna fälttåg för Alliansen. Därför måste lantliga gårdar som Amberstill Ranch försvara sig själva eller rekrytera dugliga äventyrare.",al={"varför inga vakter","var är ironforges armé","varför hjälpa amberstill"}},{q="Vem är Veron som Rudra nämner?",a="Veron Amberstill är en mästerlig bagguppfödare på ranchen som tränar och sköter Bronzebeards berömda riddjur. Rudra nämner att Veron kommer att bli oerhört lättad när rovdjurshotet mot deras värdefulla djur har undanröjts.",al={"vem är veron","veron amberstill","veron"}},{q="Varför krävs det bevis på att odjuret dödats?",a="Rudra ber om Vagashs huggtand för att vara helt säker på att odjuret som terroriserar hjordarna verkligen har dödats, och inte någon vanlig jägare från bergssluttningarna.",al={"varför vagashs huggtand","fang of vagash","vad är beviset"}},{q="Hur viktiga är baggarna för Dun Morogh?",a="Bergsbaggar är tåliga och säkra på foten, och passar därför utmärkt för Khaz Modans isande, steniga terräng. De är oumbärliga som dragdjur, ullkällor och riddjur för dvärgarnas kungarike.",al={"varför är baggar viktiga","vad används amberstills baggar till","dvärgarnas baggar bakgrund"}}},fx={["81b569d0"]={q="Varför vill Rudra Amberstill att det här blir gjort?",a="Rudra Amberstill försvarar sin familjs försörjning. På Amberstill Ranch föder man upp och sköter de tåliga bergsbockar som är högt värderade i hela Dun Morogh och Ironforge. Vagash har börjat stryka kring gården och smyger in i skydd av mörkret för att slakta boskapen. Två värdefulla bockar har redan släpats bort under en enda natt. Gården kan inte överleva fortsatta räder från ett så vildsint rovdjur.",al={"varför vill rudra döda vagash","rudra amberstills motiv","varför döda vagash"}},["34abe682"]={q="Vad ska Fang of Vagash användas till?",a="Huggtanden är ett obestridligt, fysiskt bevis på att det fruktade odjuret verkligen har dödats. Vagash är ökänd på gården för sin storlek och våldsamhet. Rudra Amberstill behöver vara helt säker på att rovdjuret som stryker kring klipporna ovanför är dött innan hon och familjen kan känna sig trygga med den återstående hjorden.",al={"varför behövs fang of vagash","syftet med fang of vagash","vagashs tand"}}},fp="19,175,21.251.0,17.255.0,14.189.0,26.169.0,47.199.0,32.179.0,34.133.0,47.154.0"}
P.entries["quest:315"] = {n="The Perfect Stout",s="Rejold Barleybrew från Brewnall Village är fast besluten att brygga den ultimata dvärgölen och förena familjens bryggtradition med exotiska lokala ingredienser. För att fullända sitt experimentella recept söker han shimmerweed, en starkt doftande växt som odlas enbart av de fientliga Frostmane-trollen på Shimmer Ridge. Modiga resenärer skickas in i trollens läger för att ta örten direkt ur stammens korgar.",h="Rejold Barleybrew från Brewnall Village är fast besluten att brygga den ultimata dvärgölen och förena...",kw={"brewnall village","dun morogh","dvärgbrygd","frostmane","perfekt stout","rejold barleybrew","shimmer ridge","shimmerweed"},ang={["profession:Herbalism"]="Shimmerweed är ingen vanlig hantverksört, men dess unika botaniska egenskaper och frosttålighet gör den till en spännande kuriositet bland Dun Moroghs frusna klippor.",["race:Dwarf"]="För Bronzebeard-klanen är bryggning närmast helig, och att hitta en exotisk vild ört som kan överträffa rivaliserande värdshus ses som en ädel strävan."},sec={{t="En bryggares ambition",b="I Brewnall Village är bryggning mer än ett yrke – det är ett sätt att leva, särskilt för familjen Barleybrew. Rejold Barleybrew tror att storhet inom bryggning ligger i hans blod, men den legendariska ”perfekta stouten” kräver nytänkande. I stället för att enbart använda vanlig humle, malt och källvatten från bergen söker Rejold sig till Dun Moroghs otämjda växtlighet för att ge sitt öl en omisskännlig skärpa."},{t="Trollörten från Shimmer Ridge",b="Den hemliga ingrediens Rejold åtrår är shimmerweed, en köldtålig växt som odlas av Frostmane-trollen på Shimmer Ridge i öster. Frostmane-trollen samlar den till sina stamritualer och mystiska ceremonier, medan dvärgarna knappt har haft någon praktisk användning för den utöver dess skarpa, särpräglade smak. När den stjäls direkt ur förvaringskorgarna i trollbyn blir örten mittpunkten i Rejolds senaste och djärvaste jäsningsexperiment."}},faq={{q="Vad är shimmerweed?",a="Shimmerweed är en särpräglad växt som Frostmane-trollen odlar och skördar på Shimmer Ridge. Trollen använder den främst i stamceremonier och ritualer, men Rejold Barleybrew vill prova dess skarpa, unika smak som en ovanlig smaksättare i dvärgarnas bryggkonst.",al={"shimmerweed i berättelsen","vad gör shimmerweed","frostmane-växt"}},{q="Var ligger Shimmer Ridge?",a="Shimmer Ridge ligger bland de snöiga höjderna i norra Dun Morogh, öster om Brewnall Village. Platsen är ett befäst läger för de bofasta Frostmane-trollen, så varje försök att samla örter där innebär en farlig färd in på fientligt territorium.",al={"shimmer ridge plats","var ligger shimmer ridge","hur hittar man shimmer ridge"}},{q="Varför vill Rejold stjäla från Frostmane-trollen?",a="Frostmane-trollen har ensamrätt på att odla shimmerweed i Dun Morogh, och spänningarna mellan dvärgar och troll gör fredlig handel omöjlig. Eftersom växterna redan har skördats och lagts i stammens korgar i lägret är Rejolds enda möjlighet att smyga in eller slå sig igenom och ta dem.",al={"varför stjäla från troll","varför trollens korgar","rejolds trollplan"}},{q="Vem är Rejold Barleybrew?",a="Rejold Barleybrew är en ambitiös dvärgbryggare som bor i Brewnall Village. Han lever upp till sitt familjenamn och har vigt sitt hantverk åt att hitta receptet på den perfekta stouten. Han experimenterar ständigt med nya smaker och kraftfulla vilda ingredienser.",al={"vem är rejold","rejold barleybrew","barleybrew-familjen"}},{q="Räknas shimmerweed som en alkemisk ört?",a="Nej. Shimmerweed är inte en alkemisk ingrediens som samlas in från vilda växter. Det är ett uppdragsföremål som förvaras i flätade korgar och förråd i Frostmane-bosättningarna på Shimmer Ridge.",al={"kan örtletare plocka shimmerweed","är shimmerweed örtkunskap","samla shimmerweed"}},{q="Vad händer med shimmerweed när den lämnas in?",a="Rejold kastar den nyplockade shimmerweed direkt i en pågående jäsning i Brewnall Village, i hopp om att dess unika egenskaper äntligen ska leda till det felfria recept han sökt.",al={"blir stouten lyckad","resultatet av rejolds brygd","shimmerweed-öl"}}},fx={["3780a202"]={q="Vilka är Frostmane-trollen?",a="Frostmane är en ursprunglig stam istroll som hör hemma i de snöiga bergskammarna i Dun Morogh. De drevs bort från sina traditionella jaktmarker när dvärgarna i Ironforge bredde ut sig, och hyser ett djupt hat mot sina dvärgiska grannar. Från boplatser som den på Shimmer Ridge odlar de shimmerweed för sina stamritualer och försvarar sina läger ursinnigt mot inkräktare.",al={"frostmane-troll","vilka är trollen på shimmer ridge","frostmane-stammen"}}},fp="17,335,19.319.0,31.300.0,20.238.0,31.188.0,56.267.0,25.170.0,42.191.0,47.182.0"}
P.entries["quest:3161"] = {n="Gahz'ridian",s="Marvon Rivetseeker, vetenskapsman och skattjägare i hjärtat, vill ha trettio ornament som lämnats kvar av trollen som en gång bodde i Tanaris. Marvon ger dig en detektor som trollen själva uppfann för att hjälpa dig hitta dem.",h="Marvon Rivetseeker, vetenskapsman och skattjägare i hjärtat, vill ha trettio ornament som lämnats kvar av...",kw={"broken pillar","detektor","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris","troll"},sec={{t="Reliker från hydraguden",b="För länge sedan bodde troll i det här landet, och de tillverkade mängder av ornament föreställande Gahz'rilla, en hydra som de vördagde som en gud. Marvon Rivetseeker kallar grundämnet som ornamenten ristades ur för Gahz'ridian, efter hydraguden. Marvon har hittat några och vill gärna hitta fler att studera."},{t="Detektorn",b="Marvon har uppfunnit en detektor som gör det enkelt att hitta Gahz'ridian, och han ger den till dig. När du bär den börjar sökandet. Ornament kan hittas nästan var som helst i Tanaris, men de finns i störst mängd nära Broken Pillar, Eastmoon Ruins och Southmoon Ruins."}},faq={{q="Vem är Marvon Rivetseeker?",a="Marvon Rivetseeker är en vetenskapsman i Tanaris som också är skattjägare i hjärtat. Han studerar ornamenten som de gamla trollen tillverkade.",al={"marvon rivetseeker","vem ger gahzridian","uppdragsgivare"}},{q="Vad är Gahz'ridian?",a="Det är Marvon Rivetseekers namn på grundämnet som trollens hydraornament ristades ur, uppkallat efter hydraguden.",al={"vad är gahzridian","gahzridianmineral","gahzridianmaterial"}},{q="Vem är Gahz'rilla?",a="Gahz'rilla är en hydra som de gamla trollen vördagde som en gud. De tillverkade sina ornament i dess avbild.",al={"gahzrilla gudom","hydradyrkan","vem är gahzrilla"}},{q="Var hittar man Gahz'ridianornament?",a="Nästan var som helst i Tanaris, men de största mängderna finns kring Broken Pillar och Eastmoon Ruins samt Southmoon Ruins.",al={"var hittar man gahzridian","bästa platsen för gahzridian","gahzridianplatser"}},{q="Hur hittar man ornamenten?",a="Marvon har uppfunnit en detektor för ändamålet. När du bär den börjar sökandet.",al={"hur hittar man ornament","gahzridiandetektor","hitta gahzridian"}}},fp="11,207,23.285.0,12.263.0,26.130.0,20.119.0,18.102.0,38.125.0,30.77.0"}
P.entries["quest:317"] = {n="Stocking Jetsteam",s="Stocking Jetsteam är ett Alliance-uppdrag från Pilot Bellowfiz vid Steelgrill's Depot i Dun Morogh. Inför en längre insats med Ironforge Siege Brigade ber piloten lokala jägare samla in vildsvinskött och björnskinn som förnödenheter åt besättningen.",h="Stocking Jetsteam är ett Alliance-uppdrag från Pilot Bellowfiz vid Steelgrill's Depot i Dun Morogh.",kw={"björnskinn","vildsvinskött","dun morogh","the grizzled den","jetsteam","pilot bellowfiz","siege brigade","steelgrill's depot"},ang={["faction:Alliance"]="Samarbetet mellan dvärgarnas reparationsvarv och Siege Brigades bepansrade besättningar håller Alliances belägringsteknik vid fronten i drift.",["profession:Cooking"]="Att samla in rejäla stycken vildsvinskött i Dun Moroghs snödrivor visar hur viktigt viltkött är för de lokala bergsgarnisonerna.",["race:Dwarf"]="Vilt från Dun Moroghs bergsklyftor håller Siege Brigades dvärgbesättningar mätta och utvilade när de arbetar från Khaz Modans maskinverkstäder.",["race:Gnome"]="När du hjälper Bellowfiz får dvärgarnas Siege Brigade, Ironforges mekaniserade allierade till de landsförvisade gnomerna, fulla förråd inför de långa fälttågen som väntar."},sec={{t="Förnödenheter till motorn",b="Pilot Bellowfiz är stationerad strax utanför Kharanos vid Steelgrill's Depot och förbereder en lång insats åt Siege Brigade. Hans belägringstank Jetsteam behöver både finjusteras av mästeringenjören Beldin Steelgrill och förses med en månads fältransoner för att besättningen ska klara Dun Moroghs stränga köldgrader."},{t="Jakt på snöfälten",b="Eftersom Beldin Steelgrill arbetar under Jetsteams motorhuv kan Bellowfiz inte lämna sitt fordon för att samla in mat och isolering. Han skickar resenärer att jaga på de snötäckta slätterna söder om The Grizzled Den, där de lokala vildsvinen ger kraftigt kött och björnarna tjocka skinn som passar som varma bäddar i tanken."}},faq={{q="Vad är Jetsteam?",a="Jetsteam är belägringstanken som körs av dvärgen Pilot Bellowfiz. Den står vid Steelgrill's Depot och finjusteras samt förses med förnödenheter inför en längre militär insats åt Ironforge Siege Brigade.",al={"jetsteam","vem är jetsteam","vad är jetstream","bellowfiz tank"}},{q="Vem är Pilot Bellowfiz?",a="Pilot Bellowfiz, med smeknamnet Fizzer, är en dvärgpilot för belägringsmaskiner i Ironforge Siege Brigade. Medan hans fordon justeras mekaniskt vid Steelgrill's Depot samordnar han fältförnödenheter inför sitt kommande uppdrag.",al={"pilot bellowfiz","bellowfiz","vem är pilot bellowfiz"}},{q="Var kan man samla in förnödenheterna?",a="Pilot Bellowfiz hänvisar jägarna till de snötäckta slätterna söder om The Grizzled Den, där lokala vildsvin och björnar håller till. Deras kött och skinn ger tillräckligt med mat och bäddmaterial.",al={"var finns vildsvinen","var finns björnarna","jaktplats","vildsvinskött dun morogh"}},{q="Vad är Siege Brigade?",a="Siege Brigade är Ironforges kår av förare för belägringsmaskiner. De använder tungt bepansrade krigsmaskiner som Jetsteam och Trollplow till stöd för dvärgarnas försvar och Alliances fälttåg.",al={"siege brigade"}},{q="Vart leder uppdraget härnäst?",a="När Jetsteam har fyllts på med kött och pälsar skickar Pilot Bellowfiz resenärer västerut till Brewnall Village i uppdraget Evershine. Han söker en kraftig brygd som både håller honom varm och fungerar som reservbränsle till tankens ugn.",al={"nästa uppdrag","vad kommer efter stocking jetsteam","uppföljning på stocking jetsteam"}},{q="Varför behöver en belägringsmaskin djurpälsar?",a="Insidan av en dvärgisk eller gnomisk ångtank är kall och dragig under långa insatser i bergens snö. Tjocka björnskinn ger nödvändig värme och isolering åt besättningens bäddar under längre vistelser långt från lägret.",al={"varför päls","vad används thick bear fur till","bäddar"}}},fx={bd6a237a={q="Varför vill Pilot Bellowfiz att det här blir gjort?",a="Pilot Bellowfiz förbereder sig för en lång tjänstgöring hos Siege Brigade. Uppdraget framför honom kommer att hålla honom ute i fält i minst en månad, och verksamhet djupt inne i Dun Moroghs iskalla vildmark kräver noggranna förberedelser. Han behöver ordentligt med proviant ombord på Jetsteam innan han ger sig ut i aktiv tjänst.",al={"pilot bellowfiz motiv","varför fylla på jetsteam","varför behöver bellowfiz förnödenheter"}},f0e85f28={q="Vad ska Chunk of Boar Meat användas till?",a="Vildsvinsköttet är livsviktiga ransoner inför Pilot Bellowfiz kommande månadslånga tjänstgöring. Att köra ett tungt belägringsfordon i den iskalla kylan kräver mycket energi, och det hållbara köttet från de lokala klippvildsvinen ger honom näring när han är långt från vänligt sinnade utposter.",al={"vad ska chunk of boar meat användas till","varför vildsvinskött","vildsvinskött till jetsteam"}},["779906a6"]={q="Varför behöver Pilot Bellowfiz att du jagar?",a="Bellowfiz kan inte avvara tid till jakt eftersom han övervakar underhållet av Jetsteam. Mästermekanikern Beldin Steelgrill finjusterar och reparerar stridsvagnen på Steelgrill's Depot, så piloten måste hålla sig i närheten och se till att maskinen blir ordentligt förberedd för avfärd.",al={"varför kan inte bellowfiz jaga","varför jag bellowfiz","varför måste jag jaga åt bellowfiz"}}},fp="17,169,23.257.0,23.248.0,17.177.0,23.202.0,44.114.0,26.174.0,34.201.1,44.185.0"}
P.entries["quest:318"] = {n="Evershine",s="Evershine är ett leveransuppdrag för Alliansen som börjar hos Pilot Bellowfiz nära Kharanos. Den dvärgiske belägringsmaskinspiloten skickar resenärer västerut till Brewnall Village för att hämta ett kraftfullt dvärgbrygd som Rejold Barleybrew har bryggt. Drycken fungerar både som värmande dryck och som nödf bränsle med hög oktanhalt till Bellowfiz belägringsmaskin.",h="Evershine är ett leveransuppdrag för Alliansen som börjar hos Pilot Bellowfiz nära Kharanos.",kw={"brewnall village","dun morogh","evershine","jetsteam","kharanos","pilot bellowfiz","rejold barleybrew"},ang={["profession:Engineering"]="Att använda flyktig destillerad sprit som extra bränsle visar hur piloter som Bellowfiz håller sina belägringsmaskiner igång i hårda miljöer.",["race:Dwarf"]="Rejold Barleybrews kraftfulla sprit står för de eldigaste ytterligheterna i dvärgarnas bryggtradition, bland Dun Moroghs kalla bergstoppar.",["race:Gnome"]="Pilot Bellowfiz vana att använda vardagliga föremål på nya sätt, till och med dvärgarnas sprit, skulle imponera på vilken gnomisk uppfinnare som helst."},sec={{t="En kraftfull brygd",b="Dvärgbryggning är berömd i hela Khaz Modan, men Rejold Barleybrews recept i Brewnall Village tänjer på gränserna för vanlig jäsning. Hans experimentella dryck, Evershine, är ökänd för att slå omkull alla utom de tåligaste dvärgarna. Trots sin våldsamma styrka är den uppskattad i Dun Moroghs bitande kyla för sin rena värmande kraft."},{t="Bränsle åt Pilot Bellowfiz",b="Belägringspiloter hittar ofta okonventionella användningsområden för vardagliga material, och Pilot Bellowfiz är inget undantag. Bellowfiz, som arbetar från Steelgrill's Depot utanför Kharanos, förlitar sig på Evershine både som en sup för att hålla den iskalla vinden stången och som extra bränsle. När den flyktiga alkoholen hälls direkt i belägringsmaskinen Jetsteams ugn ger den en explosiv nödkraft som har räddat honom ur mer än en knipa."}},faq={{q="Vad är Evershine?",a="Evershine är en ovanligt stark, experimentell alkoholdryck som dvärgbryggmästaren Rejold Barleybrew har bryggt i Brewnall Village. Den är berömd för sin fräna smak och förmåga att fälla även härdade dvärgdrinkare.",al={"vad är evershine","evershine-brygd","vad är evershine för dryck"}},{q="Varför vill Pilot Bellowfiz ha Evershine?",a="Pilot Bellowfiz använder Evershine både för att hålla värmen i Dun Moroghs kyla och som bränsle i nödfall. När den hälls i ugnen på hans belägringsmaskin Jetsteam ger den flyktiga spriten en omedelbar kraftstöt.",al={"varför bellowfiz vill ha brygd","pilot bellowfiz evershine","varför behöver bellowfiz den"}},{q="Var ligger Brewnall Village?",a="Brewnall Village ligger i västra Dun Morogh, direkt längs vägen väster om Kharanos. Byn ligger inbäddad nära de snötäckta kullarna och är hem åt lokala bryggare som Rejold Barleybrew.",al={"var ligger brewnall","brewnall village plats","hitta brewnall"}},{q="Vem är Rejold Barleybrew?",a="Rejold Barleybrew är en experimentell dvärgbryggare stationerad i Brewnall Village. Han brygger en mängd olika drycker, från angenäma öl till kraftiga brygder som är starka nog att tända maskinugnar.",al={"vem är rejold","rejold barleybrew information","barleybrew bryggare"}},{q="Vad händer efter att man nått Rejold Barleybrew?",a="Rejold lämnar inte ifrån sig sin dyrbara dryck utan hjälp. När spelarna kommer till Brewnall Village får de uppdraget \"A Favor for Evershine\", där de måste hjälpa bryggaren innan han ger dem en tunna åt Pilot Bellowfiz.",al={"nästa uppdrag efter evershine","vad händer efter evershine","rejolds fortsättningsuppdrag"}},{q="Är Evershine verkligen säker att dricka?",a="Enligt Pilot Bellowfiz slår Evershine omkull nästan varje dvärg som provar den. Den kan tekniskt sett drickas av de mest hårdhudade bergsfolken, men dess extrema lättantändlighet gör den lika lämplig som bränsle i en maskinugn.",al={"kan man dricka evershine","är evershine giftigt","evershine farligt"}}},fp="9,179,19.179.0,24.268.0,18.177.0,40.201.0,26.144.0,25.171.0,49.181.1,33.188.0"}
P.entries["quest:3181"] = {n="The Horn of the Beast",s="Ett jättelikt horn från Margol the Rager i Searing Gorge är fullt av repor och sprickor. Ett trasigt yxhuvud sitter fast i den grova ytan. Yxhuvudet är märkt som Mountaineer Pebblebittys egendom, och det splittras i en miljon bitar när du försöker få loss det. Hornet ska lämnas till Pebblebitty.",h="Ett jättelikt horn från Margol the Rager i Searing Gorge är fullt av repor och sprickor.",kw={"jättelikt horn","loch modan","margol the rager","pebblebitty","searing gorge","stonewrought pass"},sec={{t="Ett krossat spår",b="Hornet från Margol the Rager är fullt av repor och sprickor. Ett ovanligt metallföremål sitter fast i det, ett trasigt yxhuvud märkt för att visa att det tillhörde Mountaineer Pebblebitty. När du försöker få loss det splittras det i en miljon bitar."},{t="Porten",b="Hornet inleder kedjan som öppnar Stonewrought Pass, som går mellan Loch Modan och Searing Gorge. Det ska lämnas till Mountaineer Pebblebitty, som inte tänker öppna porten."},{t="Vid porten",b="Pebblebitty kallar hornet en uppenbar förfalskning. Efter att själv ha mött Margol säger Pebblebitty att hennes horn är mycket större, minst åtta gånger så stort som ditt, och att ditt förmodligen kommer från en stormsnout i The Barrens."}},faq={{q="Var kommer hornet ifrån?",a="Det kommer från Margol the Rager i Searing Gorge.",al={"var hittar jag hornet","var finns margol the rager","vem släpper hornet"}},{q="Vem är Mountaineer Pebblebitty?",a="Pebblebitty är bergsbestigaren som hornet ska lämnas till och den som inte tänker öppna porten.",al={"pebblebitty","vem är pebblebitty","mountaineer pebblebitty"}},{q="Vad händer med yxhuvudet i hornet?",a="Det är märkt som Mountaineer Pebblebittys egendom, och det splittras i en miljon bitar när du försöker få loss det.",al={"varför satt pebblebittys yxa i hornet","inskription på yxhuvudet"}},{q="Vad leder hornet till?",a="Det inleder kedjan som öppnar vägen genom Stonewrought Pass och förbinder Loch Modan med Searing Gorge.",al={"stonewrought pass","vad är key to searing gorge"}}},fp="21,316,16.250.0,8.188.0,11.233.1,31.48.0,31.112.0,41.123.0,27.103.1"}
P.entries["quest:319"] = {n="A Favor for Evershine",s="För att få tag på en tunna Evershine åt Pilot Bellowfiz vid Steelgrill's Depot måste en äventyrare först hjälpa Brewnall Village. Bryggaren Rejold Barleybrew vägrar lämna ifrån sig sin sprit förrän de farliga rovdjuren i de närliggande snödrivorna har blivit färre.",h="För att få tag på en tunna Evershine åt Pilot Bellowfiz vid Steelgrill's Depot måste en äventyrare först...",kw={"bellowfiz","brewnall village","dun morogh","elder crag boar","evershine","ice claw bear","rejold barleybrew","snow leopard"},ang={["class:Hunter"]="Att gallra ut de aggressiva rovdjuren i västra Dun Morogh sätter din träffsäkerhet på prov mot de härdigaste vinterdjuren bland klipporna.",["race:Dwarf"]="Alla dvärgar vet hur viktigt det är att hålla vilda rovdjur borta från ett hederligt destilleri, så att Brewnalls legendariska tunnor får stå orörda.",["race:Gnome"]="Belägringsmaskinernas piloter och uppfinnarna vid Steelgrill's Depot väntar otåligt på tunnan. De förlitar sig på äventyrare som kan blidka den envisa bryggaren så att förberedelserna för Jetsteam kan fortsätta."},sec={{t="Bryggarens överenskommelse",b="Rejold Barleybrew har tunnan Evershine som Pilot Bellowfiz behöver, men han har ingen brådska att skänka bort sitt dyrbara brygd. I stället för att be om mynt ber Rejold om beskydd. Vilddjuren i västra Dun Morogh – glupska Ice Claw Bears, tjockhudade Elder Crag Boars och lurande Snow Leopards – strövar oroväckande nära Brewnall Village och skapar ständiga störningar och faror för invånarna."},{t="Ro för hantverkarna",b="Rejold hävdar bestämt att ingen dvärg med självrespekt hukar sig för vilda djur, men att hantera rovdjur dygnet runt tar dyrbar tid. När det lokala djurlivet gallras ut får byborna ro att ägna sig åt destillering och smide utan att ständigt behöva hålla ett öga på skogsbrynet."}},faq={{q="Varför vill Rejold att djuren dödas?",a="Björnar, vildsvin och snöleoparder strövar nära Brewnall Village. Dvärgarna är inte rädda för dem, men att driva bort dem tar dyrbar arbetstid som kunde ha ägnats åt bryggning och hantverk.",al={"varför döda björnar","varför gallra ut djur i brewnall","varför rejold ger uppdraget"}},{q="Vad är Evershine?",a="Evershine är en kraftig och berömd sprit som bryggs exklusivt i Brewnall Village av Rejold Barleybrew. Belägringsmaskinernas piloter, som Pilot Bellowfiz, har stor nytta av den både som dryck och som flyktigt bränsletillskott.",al={"vad är evershine","evershine-brygd","rejolds sprit"}},{q="Vem bad ursprungligen om Evershine?",a="Pilot Bellowfiz vid Steelgrill's Depot skickade dig för att skaffa den. Han vill hålla sig varm på vägen och kasta den i ugnen på sin egen belägringsmaskin, Jetsteam, för en kraftökning.",al={"vem skickade mig efter evershine","vem vill ha evershine","var börjar uppdragskedjan"}},{q="Var finns djuren?",a="De strövar omkring på de frusna fälten och klipporna alldeles intill Brewnall Village och Iceflow Lake i västra Dun Morogh.",al={"var finns ice claw bears","var finns snow leopard","var finns elder crag boar"}},{q="Vad händer när tjänsten är utförd?",a="När vilddjuren har gallrats ut räcker Rejold över tunnan med Evershine, så att du kan lämna tillbaka den direkt till Pilot Bellowfiz vid Steelgrill's Depot.",al={"nästa uppdrag","vad händer efter tjänsten för evershine"}},{q="Är byborna verkligen i fara på grund av rovdjuren?",a="Rejold hävdar att ingen dvärg med självrespekt fruktar ett vilddjur i snön, men farliga rovdjur som morrar utanför dörren stör arbetet och utgör en ständig fara.",al={"är brewnall i fara","är dvärgar rädda"}}},fx={["02738ac5"]={q="Vilka djur skickar Rejold Barleybrew dig att jaga?",a="Rejold skickar dig för att minska antalet rovdjur och bestar som strövar omkring i snödrivorna kring Brewnall Village: Ice Claw Bears, Elder Crag Boars och Snow Leopards. Dessa inhemska bestar kommer farligt nära byns utkant. De morrar och frustar utanför medan byborna sköter sina kar och verkstäder.",al={"rejolds mål","vilka bestar","djur att döda för evershine","vilka djur finns vid brewnall"}},fe0fe64f={q="Varför ber Rejold dig i stället för att låta byborna i Brewnall ta hand om bestarna?",a="Dvärgarna i Brewnall Village är knappast rädda för det lokala djurlivet. Ingen dvärg med självrespekt skulle darra inför ett vildsvin eller en snöleopard. Men att jaga flockar av strykande rovdjur tar värdefull tid från det de brinner för: att brygga öl, hantverka och sköta sina kar. Eftersom du är en stark resenär som redan letar efter en tunna Evershine gör Rejold upp med dig, så att hans folk kan arbeta vidare i fred.",al={"varför kan inte byborna döda dem","varför jag rejold","varför behöver rejold hjälp","jägare i brewnall village"}}},fp="21,187,18.238.0,23.265.0,42.176.0,18.185.0,39.168.0,31.108.0,40.120.0,54.133.0"}
P.entries["quest:32"] = {n="Rise of the Silithid",s="Senior Surveyor Fizzledowser ger dig rapporten om insekthotet och uppmanar dig att ta den till Orgrimmar, till en trollforskare vid namn Zilzibin Drumlore.",h="Senior Surveyor Fizzledowser ger dig rapporten om insekthotet och uppmanar dig att ta den till Orgrimmar...",kw={"drag","drumlore","fizzledowser","insekter","orgrimmar","silithider","tanaris","zilzibin"},sec={{t="Någon som vet",b="Fizzledowser vill att rapporten hamnar hos någon med praktisk kunskap om sådana frågor. Zilzibin Drumlore är en trollforskare som har ägnat mycket tid åt att studera livsformer som är unika för Azeroths ekologi, och dessutom är han historiker. Fizzledowser hoppas att Zilzibin kan ta reda på vad hotet egentligen är och hur det kan stoppas, och säger att all hjälp som finns kommer att behövas. Zilzibin bor i ett hus på Drag's andra nivå i Orgrimmar."},{t="Zilzibins svar",b="Zilzibin har haft med de här varelserna att göra tidigare och tycker att Fizzledowser gjorde rätt i att skicka rapporten och dig. De kommer snabbt att sluka Tanaris öken och räknas till de största hot någon kommer att ställas inför. De är silithiderna, verktyg för ett av de allvarligaste hoten mot både Horde och Alliance. Zilzibin beklagar att ingen var klok nog att inse det tidigare."}},faq={{q="Vem är Zilzibin Drumlore?",a="En trollforskare och historiker som har ägnat mycket tid åt att studera livsformer som är unika för Azeroths ekologi.",al={"vem är drumlore","zilzibin drumlore bakgrund","trollforskare i orgrimmar"}},{q="Vem skickar dig till Zilzibin?",a="Senior Surveyor Fizzledowser, som ger dig rapporten och ber dig ta den till Orgrimmar.",al={"rise of the silithid början","vem ger rise of the silithid"}},{q="Var i Orgrimmar finns Zilzibin Drumlore?",a="I ett hus på Drag, uppe på dess andra nivå i Orgrimmar.",al={"var finns zilzibin","var ligger drumlores hus"}},{q="Vad kommer direkt före det här steget?",a="Det följer efter Insect Part Analysis.",al={"föregående uppdrag rise of the silithid","vad ledde till rise of the silithid"}}},fp="20,153,17.452.0,17.367.1,25.115.0,26.93.0,48.60.0,37.32.0"}
P.entries["quest:320"] = {n="Return to Bellowfiz",s="Return to Bellowfiz är ett kort leveransuppdrag i Dun Morogh där en äventyrare lämnar en tunna lokal Evershine till Pilot Bellowfiz vid Steelgrill's Depot. Det avslutar en lokal gentjänst och belönar den törstige föraren med en välkommen dryck.",h="Return to Bellowfiz är ett kort leveransuppdrag i Dun Morogh där en äventyrare lämnar en tunna lokal...",kw={"tunna med evershine","dun morogh","evershine","kharanos","pilot bellowfiz","return to bellowfiz","steelgrill's depot"},ang={["faction:Alliance"]="Att springa ärenden mellan dvärgiska jägare och dvärgiska piloter hjälper till att hålla moralen och kamratskapen uppe bland Alliansens styrkor i Dun Morogh.",["race:Dwarf"]="Ett mustigt dvärgbryggt öl som Evershine är alltid efterfrågat i Dun Morogh, så att leverera det säkert till törstiga kamrater känns självklart.",["race:Gnome"]="Pilot Bellowfiz är en dvärgisk förare av en belägringsmaskin stationerad vid Steelgrill's Depot. Att hålla hårt arbetande ingenjörer pigga hjälper maskinerna att fungera smidigt."},sec={{t="En tunna till depån",b="Return to Bellowfiz är ett ärende i Dun Moroghs snöiga trakter. Efter att ha hjälpt till med den lokala jakten får en äventyrare en nybryggd tunna Evershine och instruktioner att genast bära den till Pilot Bellowfiz vid Steelgrill's Depot. Det är en enkel gentjänst som visar den informella kamratskap och ömsesidiga hjälp som håller den kalla gränsbygden igång."},{t="Törstiga flygare",b="Steelgrill's Depot är ett livligt centrum för mekaniska tester, fordonsunderhåll och gnomiskt hantverk strax utanför Kharanos. För piloter som är stationerade i de iskalla vindarna finns det inget som smakar bättre än en klunk stark lokal dryck. Pilot Bellowfiz slösar ingen tid när leveransen kommer, utan skyndar sig att genast korka upp en flaska och njuta av det lokala arbetets frukter."}},faq={{q="Vad är uppdraget Return to Bellowfiz?",a="Return to Bellowfiz är ett leveransuppdrag i Dun Morogh där en äventyrare lämnar en nyförvärvad tunna Evershine direkt till Pilot Bellowfiz vid Steelgrill's Depot.",al={"vad är return to bellowfiz","bellowfiz-uppdrag"}},{q="Vem är Pilot Bellowfiz?",a="Pilot Bellowfiz är en dvärgisk förare av en belägringsmaskin, stationerad vid Steelgrill's Depot strax utanför Kharanos i Dun Morogh. Han väntar ivrigt på en ny leverans Evershine att smaka på.",al={"vem vill ha evershine","vem är bellowfiz"}},{q="Vad är tunnan med Evershine?",a="Evershine är ett starkt lokalt bryggt öl från Dun Morogh, förvarat i en stadig tunna och uppskattat av både törstiga piloter och ortsbor.",al={"vad är evershine","tunna med evershine"}},{q="Var lämnar du tunnan?",a="Pilot Bellowfiz finns vid Steelgrill's Depot, ett ingenjörsnav och en verkstad strax öster om Kharanos i Dun Morogh.",al={"var finns bellowfiz","bellowfiz plats"}},{q="Varför skickades Evershine till Bellowfiz?",a="Efter att ha hjälpt till med jaktuppgifter i området får en äventyrare förtroendet att leverera en tunna Evershine till Pilot Bellowfiz, som ivrigt har sett fram emot att få smaka.",al={"varför leverera evershine","orsak till evershine-leverans"}},{q="Vad händer när Bellowfiz får Evershine?",a="När Pilot Bellowfiz får tunnan blir han mycket nöjd och säger att den duger alldeles utmärkt. Han skyndar sig genast att öppna en flaska för att smaka.",al={"vad gör bellowfiz med ölet","bellowfiz reaktion"}}},fp="19,233,20.367.0,16.361.0,38.167.0,23.182.0,30.127.0,30.127.0,40.177.0,51.160.0"}
P.entries["quest:321"] = {n="Lightforge Iron",s="Lightforge Iron är ett alliansuppdrag om bärgning som Glorin Steelbrow ger i Menethil Harbor. Äventyrare skickas för att genomsöka vraket efter Flying Osprey, en alvisk jagare som fraktade sällsynt, heligt järn och gick förlorad tillsammans med Kul Tiras tredje flotta under andra kriget.",h="Lightforge Iron är ett alliansuppdrag om bärgning som Glorin Steelbrow ger i Menethil Harbor.",kw={"flying osprey","glorin steelbrow","tacka","kul tiras","lightforge-järn","menethil harbor","murloc","tredje flottan","vattendränkt kista","wetlands"},ang={["class:Paladin"]="Vapen smidda av Lightforge-järn är djupt bundna till det Heliga Ljuset, vilket gör det andligt betydelsefullt att återfinna även en enda förlorad tacka.",["faction:Alliance"]="De sjunkna skeppen utanför Menethil Harbor är dystra minnesmärken över andra kriget, då modiga sjömän från Kul Tiras och Lordaeron föll för drakeld.",["profession:Blacksmithing"]="Smeder av alla slag vördar Lightforge-järn som materialens heliga graal. Det är känt för att bevara kraftfulla välsignelser och behålla en oöverträffad strukturell hållfasthet."},sec={{t="En helig last",b="De flesta sjunkna skrov längs Wetlands kust tillhörde Kul Tiras berömda tredje flotta, men ett fartyg stack ut: en alvisk jagare med namnet Flying Osprey. Fartyget kom från Lordaeron och sökte skydd i flottans följe, med en dyrbar last av Lightforge-järn. Att segla tillsammans med krigsskeppen hjälpte föga när Dragonmaw-klanens röda drakar, som hölls i slaveri, dök ner från himlen, satte flottan i brand och sänkte både soldater och helgat järn under vågorna."},{t="Plundrad av vågorna",b="När du når de krossade resterna av Flying Osprey söder om Menethil Harbor ser du att tiden och havet inte är de enda krafterna som verkat där. Den vattendränkta kistan som innehöll lasten har slagits upp och rivits sönder av klor. Kustens murlocer, som alltid gärna letar bland vrak, har plundrat lastrummet och spritt tackorna, så att knappt ett spår återstår av den dyrbara malm som Glorin Steelbrow söker."}},faq={{q="Vad är Flying Osprey?",a="Flying Osprey var en alvisk jagare som seglade från Lordaeron under andra kriget. Den fraktade en last sällsynt Lightforge-järn och färdades under beskydd av Kul Tiras tredje flotta, men brändes och sänktes tillsammans med resten av flottan av röda drakar som orcher höll i slaveri.",al={"flying osprey-lore","alvisk jagare i wetlands","vilket skepp fraktade järnet"}},{q="Vem är Glorin Steelbrow?",a="Glorin Steelbrow är en dvärg stationerad i Menethil Harbor i Wetlands. Han är intresserad av att bärga historiska fynd och värdefulla material från de sjunkna skeppen längs kusten, särskilt legendariska metaller som Lightforge-järn.",al={"glorin steelbrow","dvärg i menethil","vem ger lightforge iron"}},{q="Vad är Lightforge-järn?",a="Lightforge-järn är en ytterst sällsynt, helgad metall som används för att smida välsignade vapen och rustningar. Smeder och den Heliga Ljusets förkämpar värdesätter det för dess renhet och motståndskraftiga andliga egenskaper.",al={"lightforge-metall","vad är lightforge-järn","lightforge-tackor"}},{q="Varför sjönk skeppen i Wetlands?",a="Under andra kriget använde Hordens Dragonmaw-klan Demon Soul för att förslava den röda drakflykten. Drakryttare angrep Kul Tiras tredje flotta utanför Wetlands kust, satte skeppen i brand och sänkte dem till havsbotten.",al={"vem sänkte tredje flottan","varför är skeppsvraken i wetlands","röda drakar och flottan i wetlands"}},{q="Varför är kistan nästan tom?",a="Den vattendränkta kistan ombord på Flying Osprey har färska klomärken efter kustens murlocer. Varelserna bröt upp den och plundrade lasten, tog de flesta tackorna och spred resten längs den sumpiga stranden.",al={"var finns tackorna","varför finns klomärken på kistan","vem stal lightforge-järnet"}},{q="Var ligger vraket efter Flying Osprey?",a="Vraket ligger bland kustens grund utanför Wetlands västra strand, strax söder om Menethil Harbor, utspritt över grunden nära lokala murlocbosättningar.",al={"flying ospreys plats","var finns kistan","skeppsvrak i wetlands"}}},fx={["915ea990"]={q="Varför vill Glorin Steelbrow ha Lightforge iron?",a="Glorin Steelbrow är en präst som vill återfinna den sällsynta metallen för att kunna förbereda ett vapen mot Morbent Fel. Den sjunkna lasten från Flying Osprey ger en sällsynt möjlighet att bärga Lightforge iron, en dyrbar alvisk råvara som varit förlorad sedan det andra kriget. Genom att skicka dig för att hämta den hoppas han få ihop tillräckligt med bearbetbar metall för att smida vapen värdiga dess bestående legend.",al={"varför glorin vill ha järn","glorin steelbrows motiv för lightforge iron","varför hitta lightforge iron"}}},fp="15,197,14.334.0,22.251.1,26.235.0,24.213.0,24.167.0,40.227.0,30.162.0,51.192.0"}
P.entries["quest:322"] = {n="Blessed Arm",s="I Stormwind för Blessed Arm du ljusforgat järn som ska bli ett vapen mot Morbent Fel. Efter att ha bärgat tackorna från vraket efter Flying Osprey i Wetlands för du den dyrbara metallen till mästersmeden Grimand Elmore, som kan forma den för att möta nekromantikern.",h="I Stormwind för Blessed Arm du ljusforgat järn som ska bli ett vapen mot Morbent Fel.",kw={"blessed arm","dwarven district","glorin steelbrow","grimand elmore","ljusforgat järn","loch modan","morbent fel","stormwind"},ang={["class:Paladin"]="Som paladin följer du Silver Hands kallelse när du bär konsekrerat järn för att forma ett vapen mot en nekromantiker i Duskwood: möt mörk magi med helig vaksamhet.",["faction:Alliance"]="Som medlem av Alliansen för du hjälp mellan rikena, från en dvärgisk präst i Menethil Harbor till Stormwinds Dwarven District, för att bistå Duskwoods hårt ansatta folk.",["profession:Blacksmithing"]="Ljusforgat järn är sällsynt och svårt att bearbeta. När du ser den erfarne dvärgiske smeden Grimand Elmore ta sig an det får du se vilken skicklighet som krävs för att smida heliga vapen."},sec={{t="En sällsynt metall återvänder",b="Glorin Steelbrow packar det bärgade ljusforgade järnet för Stormwind. Metallen är sällsynt, och dess kraft mot vidriga och oheliga varelser kräver en smed som vet hur den ska bearbetas. När lasten kom från vraket efter Flying Osprey utanför Wetlands kust kände Glorin bara till en hantverkare i de södra rikena som kunde utföra uppgiften: mästervapensmeden Grimand Elmore."},{t="Dwarven Districts smedja",b="I Stormwinds Dwarven District håller Grimand Elmore en av stadens främsta städar. Det var många år sedan han senast hamrade ljusforgat järn, säger han när du kommer med den bärgade lasten. Den erfarne hantverkaren lockas av möjligheten att slå till mot nekromantikern Morbent Fel och går med på att sätta hammaren i arbete."}},faq={{q="Vad är syftet med den här leveransen?",a="Lådan innehåller ljusforgat järn som bärgats från Flying Ospreys vrak i Wetlands. Glorin Steelbrow skickar det till Grimand Elmore, som kan forma den konsekrerade metallen till ett vapen mot nekromantikern Morbent Fel.",al={"varför föra tackor till stormwind","syftet med blessed arm","vad används crate of lightforge ingots till"}},{q="Vem är Grimand Elmore?",a="Grimand Elmore är en respekterad dvärgisk vapensmed som arbetar i Stormwinds Dwarven District. Få hantverkare har utbildningen som krävs för att smida specialmetaller som ljusforgat järn.",al={"grimand elmores bakgrund","vem är smeden i dwarven district"}},{q="Varför är ljusforgat järn så viktigt mot Morbent Fel?",a="Ljusforgat järn är känt för sin kraft mot vidriga och oheliga varelser. Grimand Elmore kan forma den konsekrerade metallen till ett vapen för att möta nekromantikern Morbent Fel.",al={"varför ljusforgat järn","hur skadar ljusforgat järn morbent fel"}},{q="Vart skickar Glorin Steelbrow dig?",a="Glorin Steelbrow skickar dig från Menethil Harbor i Wetlands till Grimand Elmores smedja i Stormwind Citys Dwarven District.",al={"vart ska jag gå för blessed arm","var ligger grimand elmore"}},{q="Har Grimand Elmore arbetat med ljusforgat järn tidigare?",a="Ja. Grimand säger att det var många år sedan han senast arbetade med ljusforgat järn och välkomnar chansen att forma den berömda metallen igen.",al={"har grimand smitt ljusforgat järn tidigare","elmores smideserfarenhet"}},{q="Vad måste hända innan vapnet kan bli färdigt?",a="Grimand går med på att smida det bärgade ljusforgade järnet till Morbent's Bane. När han är klar tar du vapnet till Sven Yorgen i Duskwood.",al={"vad händer efter blessed arm","smids vapnet direkt"}}},fx={["983cc211"]={q="Varför vill Glorin Steelbrow att den här leveransen görs?",a="Glorin vet att vanligt stål inte kan bryta igenom de mörka skydd som omger Morbent Fel i Duskwood. Du har hämtat lightforge-järnet som du bärgade från vraket av Flying Osprey i Wetlands. Han känner till din kampanj mot nekromantikern och hänvisar dig till en skicklig smed som kan smida ett vapen som verkligen kan skada honom.",al={"glorin steelbrows motiv","varför hjälper glorin","varför skicka tackor till grimand"}}},fp="11,236,20.355.0,28.315.0,37.202.0,22.167.0,56.155.0,37.127.0,54.135.0,51.143.0"}
P.entries["quest:3221"] = {n="Speak with Renferrel",s="Speak with Renferrel är ett kort ärende i The Sepulcher i Silverpine Forest. High Executor Hadrec skickar dig tillbaka till Royal Apothecary Societys lokala forskare för att diskutera fynden om fördärvade varghjärtan.",h="Speak with Renferrel är ett kort ärende i The Sepulcher i Silverpine Forest.",kw={"hadrec","renferrel","royal apothecary society","the sepulcher","silverpine","varghjärtan"},ang={["faction:Horde"]="När Horde etablerar fotfästen runtom i Lordaeron är det livsviktigt att förstå fördärvet som drabbar traktens bestar för att säkra vildmarken.",["race:Undead"]="Royal Apothecary Society arbetar nära den militära ledningen vid The Sepulcher och ser till att varje biologisk avvikelse i Silverpine studeras till gagn för den Mörka damens mål."},sec={{t="En kallelse från sällskapet",b="Efter att ha hjälpt Deathstalkers runtom i Silverpine Forest vidarebefordrar High Executor Hadrec ett brådskande meddelande från Apothecary Renferrel. Renferrel har ägnat tid åt att analysera de missfärgade varghjärtan som samlats in från det lokala djurlivet och behöver att du kommer genast."},{t="Alkemiska egenheter",b="Apothecary Renferrel tjänar Royal Apothecary Society från sitt laboratorium i kryptan vid The Sepulcher. Hans pågående arbete undersöker hur mörk magi och sjukdom förändrar Silverpines bestar och förenar militär spaning vid fronten med kemisk forskning."}},faq={{q="Var finns Apothecary Renferrel?",a="Apothecary Renferrel finns i kryptan vid The Sepulcher i centrala Silverpine Forest. Han står nära sin alkemiska utrustning, bara några steg från High Executor Hadrec.",al={"renferrels plats","var finns renferrel","hitta renferrel"}},{q="Varför vill Apothecary Renferrel tala med mig?",a="Renferrel har analyserat missfärgade varghjärtan från lokala vargar i Silverpine och upptäckt egenheter i deras fördärv som kräver vidare undersökning och kontakt med Undercity.",al={"varför vill renferrel träffa mig","renferrel varghjärtan"}},{q="Vem skickar dig till Renferrel?",a="High Executor Hadrec, den fördömdes militäre befälhavare vid The Sepulcher, överlämnar Renferrels kallelse till dig när du återvänder efter att ha hjälpt hans Deathstalkers.",al={"vem ger speak with renferrel","uppdragsgivare"}},{q="Vad händer efter det här samtalet?",a="När du talar med Renferrel får du direkt uppgifter som hjälper till att knyta The Sepulchers regionala alkemiska forskning till högt uppsatta personer som Apothecary Zinge i Undercity.",al={"nästa uppdrag efter speak with renferrel","uppföljning för renferrel"}}},fx={["1f8d2902"]={q="Varför skickar High Executor Hadrec dig till Renferrel?",a="High Executor Hadrec vidarebefordrar helt enkelt en formell kallelse på uppdrag av Royal Apothecary Society. Medan du spanade vid frontlinjen i Silverpine för Deathstalkers bad Apothecary Renferrel dig att återvända för att tala om varghjärtana du tidigare samlade in åt hans alkemiska forskning. Hadrec ser till att viktiga ärenden mellan militärposteringen och sällskapet sköts smidigt.",al={"hadrecs motiv","varför vill hadrec att jag talar med renferrel","varför skicka mig till apothecary renferrel"}}},fp="20,179,24.235.0,22.251.0,38.149.0,52.168.0,27.141.0,31.164.0"}
P.entries["quest:323"] = {n="Proving Your Worth",s="Proving Your Worth är ett avgörande steg i Sven Yorgens hämndkampanj i västra Duskwood. Innan han låter en äventyrare möta nekromantikern Morbent Fel kräver den sörjande eremiten bevis på att äventyraren kan besegra de odöda legioner som hemsöker Raven Hill Cemetery.",h="Proving Your Worth är ett avgörande steg i Sven Yorgens hämndkampanj i västra Duskwood.",kw={"dark riders","duskwood","forlorn rowe","morbent fel","proving your worth","raven hill cemetery","skeletal healer","skeletal raider","skeletal warder","sven yorgen"},ang={["class:Paladin"]="Att rena Raven Hill Cemetery från Morbent Fels rastlösa döda är ett heligt arbete, som besvarar Duskwoods avlidnas obevitade rop med Light's Justice.",["class:Priest"]="Skändningen av Raven Hills gravar genom mörka ritualer ropar efter andlig rening, så att warders och healers som förvränger liv och död kan stoppas.",["faction:Alliance"]="Utan regelbundna patruller från Stormwind har västra Duskwood fallit i laglöshet, och utsatta nybyggare som Sven måste helt förlita sig på resande hjältar för att slå tillbaka de odödas härjningar."},sec={{t="En bitter eremits prövning",b="Sven Yorgen håller sig gömd i ett avskilt läger norr om de ylande skogarna, uppslukad av sorg och vrede efter att hans familj slaktats. Han har lagt ihop att de skuggfigurer till Dark Riders som jämnade hans hem med marken var allierade med en ondskefull nekromantiker vid namn Morbent Fel. Sven törstar efter hämnd, men är inte så dumdristig att han skickar en oprövad rekryt rakt i Fels klor. Han kräver att rekryten visar prov på ren strids skicklighet mot de skelettstyrkor som håller till på Raven Hill Cemetery."},{t="Kryptorna i Raven Hill",b="För att övertyga Sven måste äventyrare tränga djupt in i nekropolen vid Raven Hill, söder om Forlorn Rowe. Mausoleet och markerna runt omkring kryllar av rastlösa lik, bundna av Fels vidriga magi: svärdsvingande Skeletal Raiders patrullerar gravstenarna, medan Skeletal Warders och Skeletal Healers håller till i de mörkare kamrarna under jord. Att röja den här förtruppen är ett blodigt slit, särskilt med fasor som den hämndlystna vålnaden Mor'Ladim på strövtåg längs kyrkogårdens stigar."},{t="Vägen till nekromantikern",b="Att överleva katakomberna, beströdda med ben, övertygar Sven om att hans bundsförvant besitter mer än tomt mod. Men att besegra Fels svagare hantlangare är bara upptakten. Morbent Fel använder mörka skyddande förtrollningar som gör honom nästan osårbar för vanliga vapen. Därför måste Sven söka större visdom och forntida reliker innan den slutliga uppgörelsen kan börja."}},faq={{q="Varför låter Sven mig slåss mot skelett innan jag möter Morbent Fel?",a="Sven vet att Morbent Fel är en livsfarlig nekromantiker och allierad med de gåtfulla Dark Riders. Han vägrar skicka en bundsförvant mot en meningslös död innan denne visar uthålligheten och den taktiska skicklighet som krävs för att slå sig igenom en hel förtrupp av odöda hantlangare.",al={"varför proving your worth","varför låter sven mig döda skelett","svens prövning"}},{q="Var hittar jag Skeletal Warders och Skeletal Healers?",a="Skeletal Raiders strövar omkring på kyrkogårdens öppna marker söder om Forlorn Rowe, medan Skeletal Healers och Skeletal Warders främst finns samlade i och alldeles runt det stora mausoleet och kryptgångarna väster om kyrkogårdens mitt.",al={"var finns warders","var finns skeletal healers","hitta skeletal warders"}},{q="Vem är Mor'Ladim, och varför ska jag se upp för honom här?",a="Mor'Ladim är en mäktig, tragisk odöd riddare som strövar längs stigarna på Raven Hill Cemetery. Han är mycket starkare än de vanliga skeletten kring kryptorna och fäller snabbt oförsiktiga äventyrare.",al={"morladims fara","vem är mor'ladim","vandrande elit i raven hill"}},{q="Hur hänger Morbent Fel ihop med Dark Riders?",a="Sven upptäckte att Morbent Fel var allierad med de beslöjade Dark Riders som slaktade hans fru och barn. Ryttarna försvann tillbaka in i skuggorna, men Fel är fortfarande kvar i Duskwood och fortsätter med sin vidriga nekromanti.",al={"morbent fel och dark riders koppling","varför dark riders och fel","svens familjemördare"}},{q="Vad händer när jag har slutfört uppdraget?",a="När du har bevisat din stridsförmåga erkänner Sven din styrka, men förklarar att Morbent Fel inte kan dödas enbart med råstyrka. Han ber dig söka råd hos Bishop Farthing i Cathedral of Light i Stormwind för att hitta ett sätt att beröva nekromantikern hans oheliga skydd.",al={"nästa uppdrag efter proving your worth","vad gör jag efter skeletten"}},{q="Var ligger Sven Yorgens läger?",a="Sven har ett dolt läger i kullarna längs Duskwoods nordvästra utkant, tryggt undangömt norr om Raven Hill och väster om vägen till Westfall.",al={"var finns sven","svens lägerplats"}}},fx={["865aa68b"]={q="Vilka är de skelettliknande hantlangarna vid Raven Hill?",a="Skelettplundrarna, helarna och väktarna som hemsöker Raven Hill Cemetery är återuppväckta döda, resta av nekromantikern Morbent Fel. De kommer från de vanhelgade gravarna i Duskwood och bildar nu en ohelig försvarsmur kring kyrkogårdens kryptor, där de utför sin herres mörka vilja.",al={"skelettplundrare vid raven hill","vilka är skeletten vid raven hill","morbent fels hantlangare"}},fbdf818d={q="Varför behöver Sven Yorgen att du bekämpar Morbent Fels hantlangare?",a="Sven Yorgen är en isolerad eremit som överlever ensam i Duskwoods hemsökta vildmark. Sorgen har krossat honom, och hatet mot Dark Riders som slaktade hans familj driver honom. Han saknar styrkan och resurserna att ensam angripa Morbent Fels odöda armé. Därför vänder han sig till dugliga äventyrare som vågar ta sig an Raven Hill Cemetery för att utkräva hans hämnd.",al={"varför behöver sven hjälp","varför slåss inte sven","varför be mig sven"}}},fp="18,189,22.415.0,21.380.0,27.277.1,64.178.0,49.187.0,57.152.0,48.200.0,41.216.1,36.136.0"}
P.entries["quest:324"] = {n="The Lost Ingots",s="The Lost Ingots är ett uppdrag för Alliansen i Wetlands där du ska återvinna välsignad metall från ett skeppsvrak. I en sjunken kista hittar du bara en enda tacka, så du måste jaga rätt på de lokala Bluegill-murlocerna som plundrade resten av lasten.",h="The Lost Ingots är ett uppdrag för Alliansen i Wetlands där du ska återvinna välsignad metall från ett...",kw={"bluegill","flying osprey","glorin steelbrow","tackor","lightforge-järn","murloc","vattendränkt kista","wetlands"},ang={["class:Paladin"]="När du återtar Lightforge-järn från primitiva murlocer ser du till att heliga material bevaras för att smida välsignade vapen åt ljusets förkämpar.",["profession:Blacksmithing"]="Varje metallarbetare vet hur tragiskt det är att se förstklassigt material som Lightforge-järn bli prydnader i ett murlocbo vid kusten i stället för att hamna på städet.",["race:Dwarf"]="Att återvinna förlorad mästerlig malm och överlämna den till en dvärgpräst som Glorin Steelbrow hedrar dvärgarnas långa tradition av hantverk och återvinning."},sec={{t="Ett plundrat skeppsvrak",b="Utanför Wetlands dimhöljda stränder ligger vrakspillrorna efter Flying Osprey. Du skickas för att hämta dyrbart Lightforge-järn åt dvärgprästen Glorin Steelbrow, men upptäcker att den vattendränkta kistan i lastrummet nästan är tom. De glupska lokala Bluegill-murlocerna har redan plundrat resten av fartyget och tagit de glänsande tackorna åt sig själva."},{t="Återta den heliga metallen",b="Lightforge-järn är ingen vanlig malm. Det är en sällsynt specialmetall som lämpar sig för heligt smidesarbete. En ljusets dvärg kan inte låta den förfaras i murlocernas läger. Genom att jaga Bluegill-rövarna som svärmar i det grunda vattnet nära det krossade skrovet kan äventyrare återta de utspridda tackorna, så att Glorin Steelbrow kan se järnet smidas till ett vapen."}},faq={{q="Vilket skepp fraktade Lightforge-järnet?",a="Lasten kom med Flying Osprey, ett olyckligt fartyg som gick under utanför Wetlands kust. Dess sönderslagna timmer ligger nu delvis under vatten i det grunda vattnet.",al={"vilket skepp","flying osprey","skeppsvrakets namn"}},{q="Varför låg tackorna inte i kistan?",a="Bara en enda tacka fanns kvar i den vattendränkta kistan. Bluegill-murlocerna vid kusten hade redan tagit sig in i det sjunkna vraket och plundrat resten av lasten för att sprida den bland sina kustnära rövare.",al={"var finns tackorna","varför har murlocer järn","tom kista"}},{q="Vem är Glorin Steelbrow?",a="Glorin Steelbrow är en dvärgpräst i Church of the Holy Light som håller till i Deepwater Tavern i Menethil Harbor. Han är kollega till Bishop Farthing och söker Lightforge-järn för att smida ett vapen mot nekromantikern Morbent Fel.",al={"glorin","vem är glorin steelbrow","uppdragsgivare"}},{q="Vad är speciellt med Lightforge-järn?",a="Lightforge-järn är en sällsynt, välsignad metall som särskilt väl lämpar sig för heliga förtrollningar och smide. Hantverkare värdesätter den när de tillverkar vapenrustningar i linje med Holy Light.",al={"lightforge-järnets bakgrund","vad är lightforge-järn","varför är järnet viktigt"}},{q="Vilka murlocer tog järnet?",a="Det var Bluegill-stammen, närmare bestämt murloc-rövarna som stryker omkring i det grunda vattnet och på stränderna kring vraket efter Flying Osprey, som tog de saknade tackorna.",al={"vem stal tackorna","vilken stam","bluegill-rövare"}},{q="Vad händer efter att du lämnat tillbaka tackorna?",a="När Glorin Steelbrow fått alla tackorna packar han den välsignade metallen i en låda och skickar dig till vapensmeden Grimand Elmore i Stormwind för att få den smidd. Där fortsätter uppdraget i Blessed Arm.",al={"nästa uppdrag","vad gör glorin","uppdraget blessed arm"}}},fp="15,151,21.270.0,27.250.0,38.141.0,37.121.0,24.226.0,38.140.0,28.114.0,43.189.1"}
P.entries["quest:325"] = {n="Armed and Ready",s="Du för tillbaka Morbent's Bane till Sven Yorgen, vapnet som smiddes för att bryta Morbent Fels oheliga försvar.",h="Du för tillbaka Morbent's Bane till Sven Yorgen, vapnet som smiddes för att bryta Morbent Fels oheliga...",kw={"armed and ready","duskwood","grimand elmore","morbent fel","morbent's bane","raven hill","stormwind","sven yorgen"},ang={["class:Paladin"]="Som paladin vet du hur helig kraft förenad med dvärgstål kan bryta skydden som värnar de odöda.",["faction:Alliance"]="Som medlem av Alliansen ser du hur hantverkarna i Stormwind bidrar med den expertis som överlevande i Duskwood behöver för att möta den spridande plågan.",["profession:Blacksmithing"]="Som smed ser du hur Grimand Elmore förenade fint smide med heliga riter för att skapa ett vapen mot övernaturliga hot."},sec={{t="Ett smitt vapen",b="Morbent Fels grepp om Raven Hill Cemetery står emot vanligt stål. Svärd splittras eller glider av de mörka skydden kring nekromantikern. Nu är ett vapen smitt för att bryta skydden redo. Grimand Elmore formade metallen i Stormwinds Dwarven District, och helig kraft välsignade den. Morbent's Bane kan nu bryta Fels band till odödligheten."},{t="Återvänd till eremiten",b="Sven Yorgen väntar vid sitt ensliga läger nära Duskwoods västra gräns, efter att det framryckande mörkret ödelagt hans familj, gård och följeslagare. Du kommer med Morbent's Bane, smitt för att bryta Morbent Fels skydd. Sven känner igen vapnets gudomliga hantverk och elden i dina ögon. Med vapnet i handen kan han slå till mot Raven Hills herre."}},faq={{q="Vad är Morbent's Bane?",a="Morbent's Bane är ett vapen som smitts och välsignats för att bryta de magiska skydden kring Morbent Fel vid Raven Hill.",al={"morbent's bane","vad är vapnet","morbent bane svärd"}},{q="Vem tillverkade vapnet?",a="Grimand Elmore, en smed i Stormwind Citys Dwarven District, formade vapnet av välsignat lightforge-järn.",al={"vem gjorde morbent's bane","grimand elmore roll"}},{q="Var lämnar jag Morbent's Bane?",a="Du lämnar Morbent's Bane till Sven Yorgen vid hans läger i västra Duskwood, nära gränsen till Westfall.",al={"var är sven","sven yorgen plats","plats för inlämning"}},{q="Varför kan inte Sven Yorgen själv strida mot Morbent Fel?",a="De mörka krafterna i skogen drev Sven Yorgen från hans hem och tog hans familj och följeslagare ifrån honom. Isolerad och jagad är han beroende av Alliansens hjältar för att hämnas dem.",al={"varför slåss inte sven","sven yorgens bakgrund"}},{q="Vad händer när uppdraget Armed and Ready är slutfört?",a="När Sven fått det välsignade vapnet skickar han dig till Raven Hill Cemetery för att möta Morbent Fel och fälla honom.",al={"what comes next","nästa uppdrag efter armed and ready"}},{q="Vilken är den snabbaste vägen tillbaka till Svens läger?",a="Från Sentinel Hill i Westfall reser du österut över floden för att nå Svens läger. Det är en kortare och säkrare väg än att resa västerut genom Darkshires faror.",al={"snabbaste vägen till sven","hur tar man sig snabbt till sven"}}},fx={["4a0f4d98"]={q="Varför vill Grimand Elmore att Morbent's Bane levereras till Sven?",a="Grimand Elmore är en mästersmed i Stormwind som åtog sig att smida ett vapen som kan tränga igenom mörk magi. Nu när Morbent's Bane är färdigt skickar han ivrigt tillbaka dig till Duskwood, så att vapnet kan användas till det det skapades för. Han önskar dig seger över nekromantikern och ser fram emot att höra din triumfberättelse.",al={"grimand elmores motiv","varför hjälper grimand","varför hjälpa sven grimand"}},["2182c2f5"]={q="Varför behöver Grimand Elmore att du tar med dig vapnet i stället för att leverera det själv?",a="Grimand är en smed med verkstad i Dwarven District i Stormwind, inte en kringvandrande äventyrare eller kurir. Du kom till honom med materialet och de dystra nyheterna från Duskwood. Eftersom det är du som ska möta fienden tillsammans med Sven Yorgen faller det på dig att ta med den välsignade armen tillbaka till stridsfältet.",al={"varför jag i armed and ready","varför åker inte grimand till duskwood","varför skicka spelaren till sven"}}},fp="15,108,15.332.0,20.366.1,23.115.0,23.121.0,34.100.0,48.170.0,46.116.1,47.153.0"}
P.entries["quest:3261"] = {n="Jorn Skyseer",s="I södra Barrens söker erfarna jägare från Horde vägledning hos Jorn Skyseer. Efter att du jagat lokala rovfåglar åt Sergra Darkthorn skickar hon dig söderut till Camp Taurajo, där en äldre spårare erbjuder fördjupad undervisning.",h="I södra Barrens söker erfarna jägare från Horde vägledning hos Jorn Skyseer.",kw={"camp taurajo","jägarens väg","jorn skyseer","scytheclaws","sergra darkthorn","the barrens","the crossroads"},ang={["class:Hunter"]="Som jägare möter du Jorn Skyseer, som prövar din förmåga att överlista och besegra de legendariska toppredatorerna på de mellersta och södra slätterna.",["faction:Horde"]="Som medlem av Horde reser du från The Crossroads till Camp Taurajo, längre in i det omstridda södra The Barrens.",["race:Tauren"]="Som tauren på väg söderut mot Camp Taurajo knyter du åter samman stamjägarnas kunskap med det andliga ansvaret att vaka över The Barrens vildmark."},sec={{t="Att föra manteln vidare",b="Du har jagat de listiga sunscale- och scytheclaw-rovfåglarna som stryker omkring på den norra savannen och vunnit Sergra Darkthorns respekt vid The Crossroads. Hon vet att stridskonst måste förenas med förståelse för landets stora bestar. När hennes mentorskap är över skickar hon dig söderut."},{t="Vägen till Taurajo",b="Följ Gold Road söderut genom allt kargare slätter till Camp Taurajo, en viktig bosättning för tauren nära de södra vildmarkerna. Där väntar Jorn Skyseer, en äldre spårare som är redo att lära jägare att förfölja svårfångade, legendariska byten över The Barrens."}},faq={{q="Vem skickar mig till Jorn Skyseer?",a="När du har jagat de lokala scytheclaw-rovfåglarna skickar Sergra Darkthorn, rovfågeljägaren vid The Crossroads, dig söderut. Dina jakter visar din skicklighet i spårning och jakt.",al={"vem ger uppdraget jorn skyseer","vem startar jorn skyseer","sergra darkthorn uppdrag"}},{q="Var finns Jorn Skyseer?",a="Jorn Skyseer finns i Camp Taurajo, långt söderut längs huvudvägen genom The Barrens.",al={"var finns jorn skyseer","jorn skyseer plats","hitta jorn skyseer"}},{q="Vad händer när jag har nått Jorn Skyseer?",a="När du rapporterar till honom välkomnar Jorn dig till jägarens väg och börjar visa dig hur du ska spåra och jaga svårfångade bestar i södra The Barrens. Den första är den legendariska rovfågeln Ishamuhale.",al={"vad lär jorn ut","uppföljning till jorn skyseer","nästa uppdrag efter jorn skyseer"}},{q="Måste jag spela som jägare för att göra det här uppdraget?",a="Nej. Alla äventyrare från Horde som slutför Sergra Darkthorns rovfågeljakter kan följa den här vägen och lära sig att spåra på slätterna, oavsett klass.",al={"är uppdraget bara för jägare","klasskrav jorn skyseer"}},{q="Varför fortsätter inte Sergra att undervisa dig själv?",a="Sergra Darkthorn arbetar bland de norra rovfågelnästena nära The Crossroads. När du bemästrat jakterna skickar hon dig söderut till Jorn Skyseer, som leder mer avancerade expeditioner efter villebråd i söder.",al={"varför skickar sergra bort dig","sergras vägledning avslutad"}},{q="Vad är Camp Taurajo?",a="Camp Taurajo är ett taurenläger i södra The Barrens. Det är en jaktpost, handelsplats och kulturell rastplats för resande mellan de norra slätterna och Mulgore eller Thousand Needles.",al={"om camp taurajo","vad är taurajo"}}},fp="12,214,18.282.0,19.255.0,29.161.0,30.83.0,41.195.0,48.150.0,42.193.0,21.205.0"}
P.entries["quest:328"] = {n="The Hidden Key",s="Instucken i bokföringsboken Bookie Herod förvarar finns en liten mässingsnyckel och anteckningar om ett låst kassaskrin. Om du hittar det djupt inne i grottsystemet bakom Kurzen's Compound kan du få veta hur Private Thorsen förråddes.",h="Instucken i bokföringsboken Bookie Herod förvarar finns en liten mässingsnyckel och anteckningar om ett låst...",kw={"bookie herod","mässingsnyckel","kurzen's compound","private thorsen","stockpile","stranglethorn vale","kassaskrin"},sec={{t="En hemlighet i bokbandet",b="När du söker igenom Bookie Herods bokföringsböcker hittar du inget direkt omnämnande av Private Thorsen, men något annat framkommer: en liten mässingsnyckel gömd inuti ett bokband. Bland papperen finns korta omnämnanden av ett låst kassaskrin som gömts i Stockpile, grottsystemet längst bak i Kurzen's Compound. Om du öppnar skrinet kanske du får veta hur Thorsens täckmantel röjdes."},{t="Långt in i Stockpile",b="För att nå kassaskrinet måste du ta dig djupt in i grottsystemet bakom anläggningen. Den tunga kistan, förstärkt med brons och byggd för att hålla, står bland staplade lådor i grottan."}},faq={{q="Varifrån kommer den här mässingsnyckeln?",a="Den lilla mässingsnyckeln var gömd i bokbandet på en av Bookie Herods bokföringsböcker. Du hittade den när du granskade hans papper.",al={"var fanns nyckeln","hur fick jag nyckeln","varifrån kommer den lilla mässingsnyckeln"}},{q="Var finns Bookie Herods kassaskrin?",a="Kassaskrinet står i Stockpile, grottsystemet längst in i Kurzen's Compound.",al={"kassaskrinets plats","var finns kassaskrinet","var finns kistan"}},{q="Varför leta efter Herods kassaskrin?",a="Herods lösa papper förklarar inte hur Private Thorsens närvaro röjdes, men de nämner ett låst kassaskrin som kanske innehåller svaret.",al={"varför hitta kassaskrinet","vad finns i skrinet","syftet med kassaskrinet"}},{q="Vad hände före det här steget?",a="Det här följer på utredningen av Bookie Herod, då hans bokföringsböcker först letades upp och genomsöktes.",al={"föregående uppdrag","vilket uppdrag kommer först"}}},fp="14,246,24.393.0,23.177.0,35.129.0,42.111.0,33.148.0,27.110.0"}
P.entries["quest:3281"] = {n="Stolen Silver",s="Gazrog vid The Crossroads skickar dig efter lönesilver som stulits av raptorer. Rykten om deras slughet leder dig söder om Ratchet, in i Raptor Grounds. Garnisonen behöver få tillbaka sina löner.",h="Gazrog vid The Crossroads skickar dig efter lönesilver som stulits av raptorer.",kw={"the barrens","the crossroads","gazrog","löneutbetalning","raptor grounds","raptor thieves","ratchet","stolen silver"},ang={["class:Hunter"]="Som jägare ser du hur raptorerna i Barrens häckar i komplexa sociala grupper och dras till konstgjort, glänsande gods.",["faction:Horde"]="Som medlem i Horden vet du att The Crossroads ser till att vakterna får lön och mat för att hålla Kalimdors gräns."},sec={{t="Ett djuriskt rån",b="Gazrog behöver betala vakterna vid The Crossroads, och raptorerna har tagit deras lön. Du skickas för att återta det stulna myntet, inte bara straffa bestarna. När raptorer överföll lönetransporten sökte Gazrog först hämnd. Men att döda flocken skulle inte återställa de saknade pengarna. Horden måste ta reda på hur raptorerna bar bort tunga myntlådor och vart de förde dem."},{t="Raptor Grounds",b="Spanare hittade ett raptorbo mellan två karga bergstoppar, söder om Ratchet och nordväst om Northwatch Hold. Varelserna släpade den låsta kistan oskadd in på sitt revir, där de vaktar den tillsammans med ägg och färska byten. Gazrog tycker nu att berättelserna om raptorernas slughet och hamstring verkar sanna. Vanliga bestar gömmer sällan metallföremål av värde."}},faq={{q="Varför stal raprotor silver från första början?",a="Raptorerna i Barrens uppvisar förbluffande slughet och märkliga asätarvanor. De släpade den intakta kassakistan till sina gemensamma bon i Raptor Grounds, kanske lockade av dess glans, det behandlade lädret på kistan eller en instinkt att samla på sig saker.",al={"varför vill raprotor ha silver","varför silver raprotor","raptorernas motiv för mynten"}},{q="Vem är Gazrog?",a="Gazrog är en orcisk officer stationerad i The Crossroads huvudbunker. Han sköter säkerhet och logistik, däribland hot från det lokala djurlivet, centaurernas intrång och störningar i löneutbetalningarna.",al={"gazrog","vem ger uppdraget stolen silver","uppdragsgivare vid the crossroads gazrog"}},{q="Var ligger Raptor Grounds?",a="Raptor Grounds ligger i östra Barrens, söder om Ratchet och nordväst om Northwatch Hold. Bona fyller en oländig passage mellan två berg.",al={"raptor grounds plats","var hittar man stolen silver","stolen silver kassaskrinets plats"}},{q="Vad händer om silvret inte återtas?",a="Det stulna silvret motsvarar en månads lön för vakterna vid The Crossroads. Utan det riskerar utpostens försvarare att arbeta utan lön, och moralen kan svikta vid en fästning som hemsöks av quilboar, centaurer och alliansens plundrare.",al={"varför är stolen silver viktigt","vakternas lön vid the crossroads"}},{q="Är det här en del av en längre uppdragskedja?",a="Innan du söker efter gömstället måste du slutföra Raptor Thieves åt Gazrog. Där gallrar du ut raptorerna som anföll den första transporten och spårar upp var bytet gömts.",al={"krav för stolen silver","fortsättning efter raptor thieves"}},{q="Är Alliansen inblandad i stölden?",a="Nej. Northwatch Hold ligger sydöst om Raptor Grounds, men det var de inhemska raptorerna som utförde stölden. Deras tjuveri och hamstring överraskade till och med erfarna befälhavare i Horden.",al={"stal northwatch silver","alliansen raprotor barrens"}}},fx={f31163b7={q="Varför vill Gazrog få tillbaka silvret?",a="Det stulna silvret utgör nästa månads lön till vakterna vid The Crossroads. Som en viktig Horde-utpost som hotas av centaurer, quilboar och den närliggande Alliansen är The Crossroads starkt beroende av dessa vakter. Utan deras löner kan moralen och bosättningens försvar kollapsa, så Gazrog är fast besluten att återfå vartenda mynt.",al={"gazrogs motiv för stolen silver","varför behöver gazrog silvret","varför återta stolen silver"}},b903b9d8={q="Vad är Stolen Silver?",a="Silvret är lön till vakterna vid The Crossroads och förvaras i en låst kista tills listiga raptorer stal den. Kistan med mynt finns gömd djupt inne i Raptor Grounds, söder om Ratchet. Den står för försörjningen för utpostens beskyddare och tryggheten vid The Barrens viktigaste vägskäl.",al={"vad är stolen silver","stolen silver som uppdragsföremål","vem tillhör silvret"}},["03250c10"]={q="Vad möter du vid Raptor Grounds?",a="Du skickas till Raptor Grounds, en karg häckningsplats söder om Ratchet och nordväst om Northwatch Hold. Området myllrar av häftiga Sunscale-raptorer, förvånansvärt listiga bestar som samlar på sig glänsande värdesaker i sina bon och aggressivt försvarar den stulna kistan mot inkräktare.",al={"vem vaktar stolen silver","fiender i raptor grounds","vad finns i raptor grounds"}}},fp="13,185,15.381.0,18.329.0,48.236.0,14.185.0,37.150.0,44.214.0,37.176.0,38.168.0"}
P.entries["quest:329"] = {n="The Spy Revealed!",s="I Bookie Herods kassaskrin ligger en fuktig bit pergament med uppgifter om Private Thorsens dagliga rutiner. Brevet är bara signerat med M och tyder på att en informatör har nästlat sig in bland rebellerna i norra Stranglethorn Vale. Den leriga lappen är avsedd för Lieutenant Doren.",h="I Bookie Herods kassaskrin ligger en fuktig bit pergament med uppgifter om Private Thorsens dagliga rutiner.",kw={"doren","herod","lerig lapp","rebel camp","spion","stranglethorn","kassaskrin","thorsen","förrädare"},ang={["faction:Alliance"]="Att avslöja en informatör i Stranglethorn Vale skyddar den utsatta ställning som Alliansens rebeller håller mot lokala hot."},sec={{t="En förrädare bland rebellerna",b="När du öppnar kassaskrinet hittar du inte bara värdesaker, utan också ett schema över Private Thorsen. Den knappt läsliga texten beskriver hans patrullrundor, hans följeslagare och hans dagliga sysslor kring Rebel Camp, och avslutas med signaturen -M. Så detaljerade iakttagelser kan bara komma från någon som lever sida vid sida med Thorsen, vilket pekar på en förrädare i rebellernas läger."},{t="Rapportera till Doren",b="När du tar med det fuktiga pergamentet tillbaka till Rebel Camp får Lieutenant Doren veta sanningen. Med den signerade lappen får befälhavaren bevisen som behövs för att leta efter infiltratören som verkar inom deras egna gränser."}},faq={{q="Vad står det på den leriga lappen?",a="Lappen innehåller ett schema över Private Thorsens dagliga rutiner. Den beskriver var han patrullerar, vilka han talar med och hur han tillbringar sin tid i lägret, och avslutas med den ensamma bokstaven -M.",al={"text på den leriga lappen","vad står det på lappen","spionlappens detaljer"}},{q="Var kommer lappen ifrån?",a="Lappen hittas i Bookie Herods kassaskrin när du har låst upp det, bland kistans övriga innehåll.",al={"var hittar jag den leriga lappen","början på den avslöjade spionen","hur börjar jag den avslöjade spionen"}},{q="Vem ska få lappen?",a="Lappen ska lämnas till Lieutenant Doren på Rebel Camp i norra Stranglethorn Vale.",al={"vem lämnar jag den leriga lappen till","vart ska jag ta lappen","lämna in till lieutenant doren"}},{q="Vad händer efter att du rapporterat om lappen?",a="Efter rapporten fortsätter Lieutenant Dorens utredning med Patrol Schedules.",al={"vilket uppdrag kommer härnäst","nästa steg efter den avslöjade spionen","efter den avslöjade spionen"}}},fp="17,300,22.373.0,18.227.1,34.205.0,30.116.0,22.96.0,41.88.0"}
P.entries["quest:33"] = {n="Wolves Across the Border",s="Eagan Peltskinner ber dig jaga vargar som stryker omkring i Northshire Valley och ta med köttet till honom. Han väntar utanför Northshire Abbey, där dalens behov kvarstår trots att vakterna fokuserar på Defias-banditer.",h="Eagan Peltskinner ber dig jaga vargar som stryker omkring i Northshire Valley och ta med köttet till honom.",kw={"klostret","eagan","elwynn","kött","northshire","peltskinner","timmervarg","vargar"},ang={["profession:Cooking"]="Som kock lär du dig en sanning om gränslandet av Eagans längtan efter vargbiff: det du jagar kan ofta tillagas och ätas.",["race:Human"]="Som mänsklig rekryt i Northshire får du här ett av dina första praktiska sätt att hjälpa till att säkra Stormwinds närliggande gränser."},sec={{t="En praktisk begäran",b="Eagan Peltskinner väntar vid Northshire Abbeys murar och hyser agg mot traktens timmervargar. Marshal McBride och Stormwinds vakter har begränsade resurser att försvara klostret mot Defias-banditer, medan hantverkarna fortfarande har dagliga behov. Eagan ber dig minska vargarnas antal och ta med deras sega kött till hans matlagning."},{t="Northshires vildmark",b="Vargar strövar allt närmare Northshire Abbey när patrullerna blir färre. Kungariket Stormwind har för få soldater och pressas av bristen på ledarskap. Unga vargar och timmervargar stryker nu omkring på klostrets stigar och i dess fruktträdgårdar. När du jagar dem får Eagan mat till sitt skafferi och stigarna i närheten blir säkrare för noviser, arbetare och nyanlända försvarare."}},faq={{q="Vem är Eagan Peltskinner?",a="Eagan Peltskinner är jägare och köpman nära ingången till Northshire Abbey. Han ogillar traktens timmervargar och lagar gärna till deras kött och äter det.",al={"vem är eagan","peltskinner","eagan peltskinner"}},{q="Varför vill Eagan ha vargkött?",a="Eagan tycker om att äta vargbiff. Han erbjuder användbar utrustning och mynt till rekryter som kommer med färskt kött.",al={"varför vargkött","eagan hungrig","vad gör eagan med köttet"}},{q="Var finns vargarna?",a="Timmervargar och unga vargar strövar på Northshire Valleys fält, kullar och flodstränder, särskilt söder och öster om klostret.",al={"var finns vargarna","var vargar finns","hitta vargar"}},{q="Varför är vargar ett problem i Northshire?",a="Färre patruller och Defias-banditer har lämnat Northshires vägar och gårdar utsatta för vilda djur, så det är farligt för präster och arbetare att resa utan eskort.",al={"varför anfaller vargar","northshires vargproblem"}},{q="Måste jag prata med någon innan jag tar det här uppdraget?",a="Nej. Deputy Willem kan skicka nykomlingar till Eagan på ett introduktionsärende, men Eagan erbjuder jakten direkt till alla som kommer fram till honom utanför klostret.",al={"uppdragskrav","förkunskapskrav","vem ger uppdraget"}},{q="Används segt vargkött i matlagningsrecept?",a="Eagan tänker laga köttet själv. Kockar bland noviserna lär sig ofta att vargkött från Elwynn Forest är en grundingrediens i matlagning utomhus.",al={"matlagning med segt vargkött","kan spelare laga vargkött"}}},fx={["12d6ae41"]={q="Vad ska Tough Wolf Meat användas till?",a="Eagan Peltskinner tänker tillaga vargstek åt sig själv. Trots att han avskyr bestarna som stryker omkring i dalen har han fått god aptit på deras kött och byter gärna till sig användbar utrustning av den som kan förse hans bord.",al={"vad används tough wolf meat till","varför tough wolf meat","tough wolf meat användning"}},acd05579={q="Varför stryker vargar omkring i Northshire?",a="Unga vargar och timmervargar stryker naturligt omkring i Northshire Valleys skogskanter och öppna ängar. Men Stormwinds vakter är upptagna med det växande hotet från Defias Brotherhood, så rovdjuren kan ströva ända fram till klostrets område utan tillsyn.",al={"varför finns det vargar här","timmervargar i northshire","vargar i northshire"}}},fp="24,189,19.323.0,19.318.0,25.158.0,30.109.0,29.128.0,39.151.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="Patrol Schedules",s="Efter att ett komprometterande meddelande med endast en initial som underskrift har hittats försöker Lieutenant Doren avslöja förrädaren i Rebel Camp. Genom att jämföra tjänstgöringslistor kan man se vem som patrullerade tillsammans med Private Thorsen veckan innan.",h="Efter att ett komprometterande meddelande med endast en initial som underskrift har hittats försöker...",kw={"corporal sethman","kurzen","lieutenant doren","patrol schedules","private thorsen","rebel camp","stranglethorn vale"},sec={{t="En ledtråd i listorna",b="Den återfunna lappen är bara undertecknad med bokstaven M, vilket i sig säger föga om vem som hjälper Kurzen-styrkorna. Författaren nämner dock att hen regelbundet gick samma patrullstråk som Private Thorsen under veckan innan. Lieutenant Doren skickar dig genom Rebel Camp för att tala med Corporal Sethman, soldaten som ansvarar för tjänstgöringsjournalerna, och ta reda på vem som patrullerade med Thorsen."},{t="Vad journalerna visar",b="En granskning av de officiella journalerna bekräftar att Private Merle hade exakt samma tjänstgöringstider och patrullstråk som Thorsen under hela föregående vecka. Då står det klart att Merle är informatören som förser Kurzans män med underrättelser. När förrädaren avslöjas flyr hen lägret mot den norra gränsen till Duskwood."}},faq={{q="Varför skickar Lieutenant Doren dig till Corporal Sethman?",a="Corporal Sethman ansvarar för tjänstgöringsjournalerna och schemana i Rebel Camp. Eftersom den återfunna lappen nämner regelbundna patrullstråk tillsammans med Private Thorsen kan Sethmans journaler visa vem som hade samma tjänstgöring som honom.",al={"varför tala med sethman","corporal sethmans roll","sethmans patrullscheman"}},{q="Vilken ledtråd finns i den återfunna lappen?",a="Meddelandet är undertecknat med den enda bokstaven M och nämner uttryckligen att författaren gick samma patrullstråk som Private Thorsen veckan innan.",al={"lappens ledtråd","bokstavsledtråd","vem skrev under lappen"}},{q="Var sker undersökningen?",a="Undersökningen äger rum helt och hållet i Rebel Camp i norra Stranglethorn Vale, mellan Lieutenant Doren och Corporal Sethman.",al={"var finns patrol schedules","patrol schedules plats"}},{q="Vilken händelse föregick undersökningen?",a="I The Spy Revealed! tog du med den leriga lappen till Lieutenant Doren. Du hittade den bland Bookie Herods värdesaker, och den var bara undertecknad med en initial.",al={"föregående uppdrag","vad ledde till patrol schedules"}}},fp="16,279,21.417.0,21.337.1,55.225.0,41.158.0,35.148.0,33.131.0"}
P.entries["quest:3301"] = {n="Mura Runetotem",s="Du bär ett skal från en snapjaw från The Barrens över havet till Mura Runetotem i Silverpine Forest. Dess märkliga livskraft kan hjälpa taurenhelaren att bistå Forsaken.",h="Du bär ett skal från en snapjaw från The Barrens över havet till Mura Runetotem i Silverpine Forest.",kw={"the barrens","mura runetotem","oaser","the sepulcher","silverpine","snapjaw-skal","tonga runetotem"},ang={["class:Druid"]="Som druid studerar du ovanliga återverkningar av naturen, även sådana som uppstått genom märkliga mutationer, för att återställa balansen i skövlade länder.",["faction:Horde"]="Som medlem av Horde ser du dess växande band i samarbetet mellan Kalimdors försvarare och Forsaken i Lordaeron.",["race:Tauren"]="Som tauren ser du Runetotemklanens hängivenhet åt att vårda naturen sträcka sig över havet till Silverpines förtvinade dungar.",["race:Undead"]="Som odöd kan du se skogen kring The Sepulcher som förlorad åt röta och härjning, men taurendruider som Mura Runetotem försöker återställa den."},sec={{t="En bro över haven",b="Tonga Runetotem lägger märke till något egendomligt hos förändrade snapjaws när han undersöker det magiskt förändrade djurlivet kring oaserna i The Barrens. Deras skal pulserar av motståndskraftig energi trots att de är förvridna. Han ber dig föra ett skal över Great Sea till hans klanfrände Mura Runetotem, som är stationerad i Eastern Kingdoms."},{t="Hjälp åt de Förfallna",b="Mura Runetotem finns vid The Sepulcher, en utpost för Forsaken i Silverpine Forest. Hon gjorde den mödosamma resan dit för att hjälpa Hordens nyaste allierade att rena och återställa sin sjuka, härjade skog. Mura hoppas att skalets inre sken och bestående livsgnista ska visa hur man kan återställa livskraften på den norra kontinenten."}},faq={{q="Vem är Mura Runetotem?",a="Mura Runetotem är en taurendruid och Tonga Runetotems klanfrände. Hon reste över havet och slog sig ner vid The Sepulcher för att hjälpa Forsaken genom att studera hur deras döende skog kan läkas.",al={"mura","vem är mura","runetotem silverpine"}},{q="Var finns Mura Runetotem?",a="Mura Runetotem finns vid The Sepulcher, en stad för Forsaken längs vägen i centrala Silverpine Forest i Eastern Kingdoms.",al={"muras plats","var finns mura","hitta mura runetotem"}},{q="Varför vill Tonga skicka ett snapjaw-skal till Silverpine?",a="Förändrade snapjawskal nära oaserna i The Barrens uppvisar en onaturlig livskraft och ett inre sken. Tonga tror att studier av den motståndskraftiga livskraften kan ge Mura insikter i hur man läker Silverpine Forests härjade, döende ekosystem.",al={"varför skicka skalet","snapjaw-skalets syfte","varför mura behöver skalet"}},{q="Varför försöker taurerna läka de Förfallnas marker?",a="Tauren har en helig plikt att vårda och läka naturen. Mura ser att Silverpine Forest förfaller och är härjad, och hoppas kunna använda jordens läkande traditioner för att hjälpa Hordens nya allierade och återställa balansen i marken.",al={"taurer hjälper odöda","varför läka silverpine","druider i silverpine"}},{q="Hur knyter det här uppdraget samman The Barrens och Silverpine?",a="Skalets färd knyter samman Hordens tidiga territorier och för dig från Kalimdors slätter till skogarna i Eastern Kingdoms.",al={"uppdrag från the barrens till silverpine","uppdrag över kontinenter"}},{q="Vad händer när Mura får skalet?",a="Mura fascineras av skalets kvarvarande inre sken och beslutar sig för att studera det noga medan hon söker botemedel för Silverpines härjade skogar.",al={"fortsättning för mura","what comes next"}}},fx={["10ada1ab"]={q="Varför ber Tonga Runetotem dig att leverera skalet?",a="Tonga Runetotem är stationerad vid The Crossroads och upptagen med att undersöka de märkliga mutationerna som drabbar The Barrens oaser. En resa över havet till det avlägsna Lordaeron skulle hålla honom borta från hans brådskande uppgifter i Kalimdor. Därför är en äventyrlig budbärare det bästa valet för att föra provet till Mura.",al={"varför skicka mig","varför kan inte tonga leverera det","varför jag, mura runetotem"}}},fp="14,163,20.330.0,19.321.0,22.198.0,32.121.0,55.219.0,49.234.0,54.129.0,41.146.0"}
P.entries["quest:331"] = {n="Report to Doren",s="När du har fått informationen om patrullerna skickar Corporal Sethman dig tillbaka till Lieutenant Doren. När du överlämnar uppgifterna får rebellernas befälhavare i norra Stranglethorn Vale viktig militär underrättelse direkt.",h="När du har fått informationen om patrullerna skickar Corporal Sethman dig tillbaka till Lieutenant Doren.",kw={"doren","kurzen","patrullscheman","sethman","stranglethorn"},sec={{t="Överlämna underrättelserna",b="Corporal Sethman påminner dig om att Lieutenant Doren vill ha en direkt rapport om patrullinformationen. Du måste ta med dig det du fått veta tillbaka till Doren."},{t="En förrädare avslöjas",b="När du lägger fram informationen om patrullerna avslöjas att Merle förrådde lägret. Lieutenant Doren sörjer förlusten av en soldat som han en gång ansåg vara modig och lojal, men känner samtidigt en enorm lättnad över att ha avslöjat förrädaren innan Colonel Kurzen hann dra nytta av det."}},faq={{q="Vem skickar dig till Lieutenant Doren?",a="Corporal Sethman skickar dig för att rapportera till Lieutenant Doren när du har gått igenom patrullschemat med honom.",al={"vem inleder report to doren","vem skickar mig till doren","uppdragsgivare för report to doren"}},{q="Vad hände före den här rapporten?",a="Det här följer på Patrol Schedules, där Corporal Sethman går igenom patrullschemat med dig.",al={"föregående uppdrag","vad kommer före report to doren","patrullscheman"}},{q="Var lämnas rapporten?",a="Du lämnar rapporten direkt till Lieutenant Doren i Rebel Camp i norra Stranglethorn Vale.",al={"var finns lieutenant doren","doren plats","vart ska jag gå"}}},fp="15,223,27.146.0,18.265.1,34.111.0,29.96.0,31.101.0"}
P.entries["quest:332"] = {n="Wine Shop Advert",s="I Stormwind lockar Renato Gallina förbipasserande till familjens vinbutik. Han erbjuder en kupong på en gratis flaska årgångsvin från deras butik vid kanalen, ett litet tecken på handel i den återuppbyggda huvudstaden.",h="I Stormwind lockar Renato Gallina förbipasserande till familjens vinbutik.",kw={"kanaler","gallina winery","pinot noir","renato gallina","suzetta gallina","trade district","wine shop advert","wine ticket"},ang={["faction:Alliance"]="Även i oroliga tider, när kungar är försvunna och krig pågår, håller Trade District i Stormwind en livlig marknad för inhemska lyxvaror och importerade varor.",["profession:Cooking"]="Familjen Gallinas pinot noir passar till rejäla måltider som tillagas på tavernor runt om i Eastern Kingdoms.",["race:Human"]="Som människa som bygger upp ett liv i Stormwind kan du finna att familjeägda vingårdar längs kanalerna är ett tröstande tecken på stadens återhämtning."},sec={{t="En smak av kanalerna",b="Vardagslivet i Stormwind kretsar kring livlig handel. Renato Gallina går längs Trade Districts kullerstensgator och gör reklam för Gallina Winery, den lilla butik han driver med sin syster Suzetta. Han delar ut flygblad till törstiga resenärer och lokalbor, och vart och ett ger en gratis provsmakning."},{t="Pinot noir-årgången",b="Familjen Gallina erbjuder en flaska av sitt berömda pinot noir. Följ biljetten till vingårdens entré nära kanalerna, där Suzetta Gallina räcker över flaskan. Familjen hoppas att smaken av deras signaturvin ska få nykomlingar att återvända."}},faq={{q="Var ligger Gallina Winery?",a="Gallina Winery ligger i Stormwind Citys Trade District, längs kanalerna nära Renato Gallinas rutt.",al={"var ligger gallina winery","suzetta gallinas plats","var lämnar man in wine shop advert"}},{q="Vilka är Renato och Suzetta Gallina?",a="Renato och Suzetta Gallina är syskon som driver en vinbutik i Stormwind. Renato gör reklam för den med flygblad, medan Suzetta sköter butiken och serverar vinet.",al={"vilka är familjen gallina","renato gallina","suzetta gallinas historia"}},{q="Vilket vin får man med biljetten?",a="Biljetten ger en flaska av familjen Gallinas berömda pinot noir, deras signaturrödvin.",al={"pinot noir-vin","vilket vin får man","pinot noir i stormwind"}},{q="Varför delar Renato ut gratisbiljetter till vin?",a="Renato delar ut gratisbiljetter till vin för att locka kunder till butiken vid kanalen och få dem att återvända.",al={"varför gratis vin","syftet med vinbutikens biljett"}},{q="Innebär det här ärendet någon fara eller strid?",a="Nej. Du tar en reklamkupong från Renato och går en kort sträcka genom Trade Districts trygga gator till Suzetta vid butiken.",al={"är wine shop advert farligt","strider i vinuppdraget"}},{q="Säljer Gallina Winery andra varor?",a="Suzetta har vanliga viner och andra alkoholhaltiga drycker i lager för resenärer, vakter på rast och lokala tavernleverantörer.",al={"vad mer säljer suzetta","drycker på gallina winery"}}},fp="16,202,21.251.0,22.241.0,36.99.0,35.155.0,31.87.0,43.107.0,46.148.0,41.116.0"}
P.entries["quest:333"] = {n="Harlan Needs a Resupply",s="Harlan Bagley, en köpman från Stormwind, kan inte hålla lagret fyllt med slitstarka kläder och rustningar. När efterfrågan ökar skickar han en brådskande tygbeställning till Rema Schneider på Canal Tailor and Fit Shop, ovetande om konflikterna som växer bortom stadsmurarna.",h="Harlan Bagley, en köpman från Stormwind, kan inte hålla lagret fyllt med slitstarka kläder och rustningar.",kw={"bagley","kanal","tyg","harlan","rema","påfyllning","schneider","stormwind","skräddare"},ang={["faction:Alliance"]="Kunderna i Stormwind visar växande oro i Alliansens hjärtland medan King Varian Wrynn är frånvarande.",["profession:Tailoring"]="Stormwinds kanalverkstäder förser större butiker med varor och visar hur stadens textilhandel fungerar i vardagen.",["race:Human"]="Stormwinds arbetande hantverkare misstror sina ledare och misstänker att adeln håller vanligt folk ovetande om de hotande farorna."},sec={{t="Stor efterfrågan på slitstarka kläder",b="Över hela Stormwind City töms Harlan Bagleys hyllor snabbt. Invånare och kringvandrande äventyrare köper förstärkta tunikor, reskläder och rustningar redo för strid. Harlan undrar om folk förbereder sig för en hård årstid eller vinter, men rusningen har gjort att hans butik nästan saknar färdigsytt tyg."},{t="Frågor vid kanalerna",b="Harlan skickar en springpojke över stadens kanaler till Rema Schneider, sömmerska på Canal Tailor and Fit Shop. Hon uppskattar hans affärer, men den plötsliga efterfrågan på skyddande kläder oroar henne. Rykten om spänningar sprids genom kungariket, och Rema undrar om House of Nobles döljer tal om öppet krig för vanligt folk."}},faq={{q="Vem är Harlan Bagley?",a="Harlan Bagley är klädeshandlare och butiksägare i Stormwind City. Lokala skräddare förser honom med stickade varor och kläder som passar för resor.",al={"harlan bagley","vem är harlan","bagley i stormwind"}},{q="Vem är Rema Schneider?",a="Rema Schneider är yrkesskräddare och sömmerska på Canal Tailor and Fit Shop i Stormwind. Tillsammans med sin make Corbett förser hon stadens köpmän med nyss sydda tyger och plagg.",al={"rema schneider","skräddaren rema","canal tailor"}},{q="Varför håller Harlan på att få slut på kläder?",a="Invånare och resenärer köper rustningar och tåliga kläder i ovanligt stora mängder. Harlan skämtar om att de verkar vänta sig en sträng vinter, men den verkliga orsaken är den ökande oron och faran längs kungarikets gränser.",al={"varför tygbrist","varför köpa rustningar","harlans blomstrande affärer"}},{q="Varför misstänker Rema Schneider adeln?",a="Rema tycker att det är märkligt att vanligt folk plötsligt förbereder sig för strid utan någon officiell krigsförklaring. House of Nobles styr kungliga angelägenheter medan King Varian Wrynn är frånvarande, och hon fruktar att adeln döljer ett förestående krig för allmänheten.",al={"rema och adeln","stormwinds adel döljer krig","varför misstänks adeln"}},{q="Var ligger Canal Tailor and Fit Shop?",a="Canal Tailor and Fit Shop ligger längs vattenvägarna genom Stormwind City, mellan stadens större områden så att köpmän enkelt kan leverera varor.",al={"canal tailors plats","var finns rema schneider","var finns canal tailor"}},{q="Vad händer efter att tygbeställningen har levererats?",a="När Rema har tagit emot beställningen ber hon sin make Corbett Schneider att bära ytterligare ett lass stickade varor genom staden till Harlan på Lionheart Armory. På väg tillbaka till butiken stannar Corbett vid Trias' Cheese för ett mellanmål.",al={"corbett schneiders promenad","vad gör corbett","remas make"}}},fp="23,240,23.276.0,23.337.0,21.135.0,22.205.0,38.221.0,43.269.0,47.156.0,50.232.0"}
P.entries["quest:334"] = {n="Package for Thurman",s="I Stormwind City behöver Rema Schneider att hennes son Thurman får sina skrädderiverktyg på Larson Clothiers i Mage Quarter. Han gick hemifrån utan sax och nålar, och Rema ber dig bära dem till hans verkstad.",h="I Stormwind City behöver Rema Schneider att hennes son Thurman får sina skrädderiverktyg på Larson Clothiers...",kw={"lärling","klädbutik","larson","mage quarter","rema","schneider","syset","stormwind","thurman"},ang={["faction:Alliance"]="Stormwinds vanliga invånare och hantverkare håller huvudstaden klädd, mätt och i gång, ett ärende i taget.",["profession:Tailoring"]="Varje stor skräddare börjar längst ner, med att sy sömmar och hålla i nålar. På Larson Clothiers kanske till och med en lärling försöker smita från sysslorna."},sec={{t="Ett ärende åt mor",b="Rema Schneider oroar sig för att Thurman ska halka efter med skrädderiarbetet utan sin sax och sina nålar. Han rusade hemifrån, och hans mor ber dig bära verktygen över Stormwinds kanaler till hans verkstad."},{t="En motvillig lärling",b="Larson Clothiers ligger i Mage Quarter, nära Mage Tower. När Thurman får sina verktyg erkänner han att han lämnade dem med flit, så att han kunde slippa dagens sysslor och roa sig. Remas ingripande sätter stopp för hans lediga eftermiddag, och han återgår till sömnaden."}},faq={{q="Vem ger uppdraget Paket till Thurman?",a="Rema Schneider ber dig ta med ett syset till sin son, som arbetar i Mage Quarter.",al={"vem ger uppdraget","rema schneider uppdrag","uppdragsgivare"}},{q="Var hittar man Thurman Schneider?",a="Thurman Schneider arbetar inne på Larson Clothiers i Stormwinds Mage Quarter, nära stigen till Mage Tower.",al={"thurmans plats","var är thurman","hitta thurman"}},{q="Glömde Thurman verkligen sina verktyg av misstag?",a="Rema tror att Thurman skyndade hemifrån utan sitt syset och ber dig ta det till honom.",al={"glömde thurman","varför lämnade thurman verktygen","thurman smiter från arbetet"}},{q="I vilken butik går Thurman i lära?",a="Thurman går i skräddarlära på Larson Clothiers, en klädbutik i Stormwinds Mage Quarter som drivs av familjen Larson.",al={"var arbetar thurman","larson clothiers","vem arbetar thurman för"}},{q="Varför ber Rema Schneider en äventyrare om hjälp?",a="Rema tror att Thurm​​ans lärlingsplats är i fara utan hans syset. Eftersom hon själv inte kan lämna sina plikter ber hon resenärer på väg mot Mage Quarter om hjälp.",al={"varför be spelaren om hjälp","rema hjälp"}},{q="Vad händer när du har lämnat syset?",a="Thurman tar sitt syset och återgår till att hjälpa Larsonfamiljen med sömnaden.",al={"uppdragsbelöning","efter paket till thurman","thurmans reaktion"}}},fx={["3c7bea70"]={q="Varför vill Rema Schneider att det här blir gjort?",a="Rema tänker på sin son Thurmans framtid. Han har fått en lärlingsplats hos Larson Clothiers i Mage Quarter, men skyndade iväg utan sax och nålar. Utan sina verktyg kan Thurman varken sköta sina uppgifter eller lära sig yrket, och hans ställning hos arbetsgivarna kan hotas. Hon tror att det var en ärlig olyckshändelse och vill att hans utrustning levereras genast, så att utbildningen inte äventyras.",al={"varför behöver rema få syutrustningen levererad","rema schneiders motiv","varför leverera verktygen till thurman"}}},fp="19,179,17.193.0,22.236.1,41.101.0,37.111.0,50.86.1,38.123.0,51.173.0,46.69.1"}
P.entries["quest:335"] = {n="A Noble Brew",s="Zardeth of the Black Claw smider planer mot Stormwinds adelsmän från Slaughtered Lambs källare. Lord Wishocks krav på en utredning hotar det hemliga häxmästarsällskapet.",h="Zardeth of the Black Claw smider planer mot Stormwinds adelsmän från Slaughtered Lambs källare.",kw={"darkshire","house of nobles","musquash","slaughtered lamb","stonewrought dam","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Som häxmästare är kryptorna under Slaughtered Lamb din fristad i Stormwind. Genom att hjälpa Zardeth skyddar du dina bröder och systrar inom den mörka konsten från att upptäckas av rikets rättrogna adel.",["faction:Alliance"]="Medan kung Varian Wrynn fortfarande är försvunnen är den politiska maktkampen i House of Nobles intensivare än någonsin. Det gör skandaler i staden särskilt farliga för dess stabilitet.",["profession:Herbalism"]="Som örtmästare vet du att Tear of Tilloa och Musquash Root är sällsynta växter som bara växer i områden präglade av en dyster historia eller forsande, orört vatten."},sec={{t="Hot från adeln",b="Under gatorna i Mage Quarter samlas häxmästare på Slaughtered Lamb och håller sitt sällskap dolt. Lord Wishock, medlem av House of Nobles, har hört talas om den mörka magin under staden. Han uppmanar sina jämlikar att inleda en fullständig utredning, vilket kan leda stadsvakten och kungamakten till sällskapet."},{t="En brygd i skuggorna",b="För att undvika en öppen konflikt med Stormwinds styrande klass söker Zardeth of the Black Claw en diskret lösning som håller Lord Wishock sysselsatt. Brygden kräver sällsynta växter från avlägsna delar av Eastern Kingdoms: den bleka Tear of Tilloa från Duskwood och en Musquash Root som samlats under vatten nedanför Stonewrought Dam."}},faq={{q="Vem är Lord Wishock?",a="Lord Wishock är en adelsman i Stormwinds House of Nobles. Efter att ha hört antydningar om häxmästarverksamhet under Mage Quarter började han pressa rådet att inleda en formell utredning.",al={"wishock","lord wishock","vem är wishock"}},{q="Vem är Zardeth of the Black Claw?",a="Zardeth är en högt uppsatt häxmästare i kryptorna under Stormwinds Slaughtered Lamb. Han arbetar för att skydda stadens häxmästarkabal från att upptäckas och rensas ut av myndigheterna.",al={"zardeth","zardeth black claw","vem är zardeth"}},{q="Varifrån kommer Tear of Tilloa?",a="Tear of Tilloa är en skir vit blomma som växer i den igenvuxna Garden of Stalvan, i utkanten av Darkshire i Duskwood.",al={"tear of tilloa plats","tear of tilloa","var finns tear of tilloa"}},{q="Var hittar man Musquash Root?",a="Musquash Root växer endast i våtmarkerna längst ner vid de enorma vattenfallen nedanför Stonewrought Dam i Wetlands.",al={"musquash root plats","musquash root","var får man tag på musquash root"}},{q="Varför känner Stormwinds styre inte redan till häxmästarna?",a="Häxmästare är djupt misstrodda i Stormwind, så sällskapet under Slaughtered Lamb döljer sin verksamhet under jord, undan stadsvakten och adeln. Lord Wishock har först nyligen fått nys om den.",al={"stormwinds hemliga häxmästare","varför gömmer sig häxmästare","är häxmästare olagliga"}},{q="Vad tänker Zardeth brygga med dessa ingredienser?",a="Zardeth säger att brygden ska hålla Lord Wishock sysselsatt och fördröja utredningen. Vad han har i åtanke för adelsmannen blir klart först när brygden är färdig.",al={"vad är brygden","syftet med adelsbrygden","varför brygga drycken"}}},fx={e620a973={q="Varför vill Zardeth of the Black Claw att det här blir gjort?",a="Lord Wishock upptäckte det hemliga häxmästarsällskapet som verkar under Slaughtered Lamb i Stormwinds Mage Quarter. Wishock försöker aktivt samla House of Nobles för att inleda en formell utredning av deras närvaro. Zardeth behöver en brygd som håller den besvärlige adelsmannen upptagen innan stadens myndigheter slår ner på deras mörka seder.",al={"varför hjälpa zardeth","zardeths motiv","varför vill zardeth ha a noble brew"}},["9e466bd7"]={q="Vad ska Tear of Tilloa användas till?",a="Tear of Tilloa är en skir vit blomma som plockas i Garden of Stalvan nära Darkshire. Zardeth behöver den som en viktig ingrediens i en särskild blandning som ska neutralisera Lord Wishocks politiska kampanj mot sällskapet.",al={"vad gör tear of tilloa","tear of tilloa syfte","varför behövs tear of tilloa"}},["84ab02b5"]={q="Vad ska Musquash Root användas till?",a="Musquash Root växer vid det dimhöljda vattenfallet nedanför Stonewrought Dam i Wetlands. Zardeth använder dess kraftiga egenskaper tillsammans med Tear of Tilloa för att brygga något starkt nog att distrahera Lord Wishock.",al={"vad gör musquash root","musquash root syfte","varför behövs musquash root"}},["256dc9f2"]={q="Varför behöver Zardeth en äventyrare i stället för att hämta ingredienserna själv?",a="Zardeth och hans häxmästarkollegor måste hålla sig gömda under Slaughtered Lamb. Om de lämnar sitt gömställe riskerar de att genast dra till sig stadsvaktens och House of Nobles uppmärksamhet, särskilt medan Lord Wishock aktivt kräver en utredning.",al={"varför jag, a noble brew","varför behöver zardeth mig","varför kan inte zardeth hämta ingredienserna"}}},fp="12,156,24.304.0,27.311.1,20.186.0,33.170.0,40.130.0,33.128.0,67.202.0,53.158.1"}
P.entries["quest:336"] = {n="A Noble Brew",s="I Stormwind bär ett bud Black Claw Stout till Lord Baurles K. Wishock i kungliga borgen. Zardeth of the Black Claw har ordnat leveransen från källaren under Slaughtered Lamb.",h="I Stormwind bär ett bud Black Claw Stout till Lord Baurles K.",kw={"baurles wishock","black claw stout","hall of petitioners","nobel brygd","slaughtered lamb","stormwind keep","zardeth"},sec={{t="En ädel hycklare",b="Lord Baurles K. Wishock tillbringar tid i Hall of Petitioners i Stormwind Keep och talar om sin egen betydelse och rikets framtid. De som besöker Slaughtered Lamb känner till en annan sida av honom. Om nätterna dricker han i värdshusets rum på övervåningen och lämnar stora obetalda notor. Om dagarna försöker han få värdshuset stängt."},{t="En dödlig skål",b="Zardeth of the Black Claw brygger Black Claw Stout under Slaughtered Lamb för att göra upp med Wishocks skuld en gång för alla. Han säger att drycken har rejält med sting. I Hall of Petitioners misstar Wishock budet för en tjänare och slänger till honom ett kopparmynt. Han dricker stoutölet girigt och faller sedan död ihop i borgens salar."}},faq={{q="Vem är Zardeth of the Black Claw?",a="Zardeth of the Black Claw är en häxmästare med en hemlig kabal i katakomberna under The Slaughtered Lamb i Stormwinds Mage Quarter. Han utför farliga, hemliga uppdrag utom räckhåll för stadsvakten.",al={"vem är zardeth","zardeth of the black claw","vem ger uppdraget"}},{q="Varför riktar Zardeth in sig på Lord Wishock?",a="Wishock dricker på Slaughtered Lambs övervåning om nätterna utan att betala sina notor. Sedan tillbringar han dagarna i Hall of Petitioners med att be myndigheterna stänga värdshuset.",al={"varför döda wishock","wishocks motiv","varför förgiftad"}},{q="Var hittar man Lord Wishock?",a="Lord Baurles K. Wishock finns i Hall of Petitioners, en förstuga i Stormwind Keep där adelsmän och medborgare samlas för att påverka rikets regentskap.",al={"lord wishocks plats","var är wishock","wishock i hall of petitioners"}},{q="Hur får Lord Wishock drycken?",a="Wishock misstar budet för en tjänare, tar emot stoutölet som en uppfriskande dryck och avfärdar budet med ett kopparmynt.",al={"dör wishock","wishocks död","vad gör stoutölet"}},{q="Väcker leveransen av stoutölet vakternas uppmärksamhet?",a="Leveransen ser ut som en vanlig tjänare som kommer med en dryck, så budet kan fortsätta utan att hamna i konflikt med vakterna.",al={"angriper vakterna","är jag efterlyst i stormwind","följder av förgiftningen"}},{q="Vilket uppdrag följer efter leveransen?",a="Efter leveransen följer ”You Have Served Us Well”, som skickar dig tillbaka till Zardeth under Slaughtered Lamb.",al={"what comes next","efter a noble brew","nästa uppdrag"}}},fx={["46bddf0f"]={q="Vem är Lord Wishock, och varför är han måltavlan?",a="Lord Baurles K. Wishock är en självupptagen adelsman från Stormwind som dröjer sig kvar i Hall of Petitioners för att framföra sina önskemål till det kungliga hovet. Han ser sig själv som avgörande för rikets framtid, men tillbringar nätterna med att dricka på övervåningen i Slaughtered Lamb. Där drar han på sig enorma notor som han vägrar betala, samtidigt som han försöker få etablissemanget stängt. Zardeth riktar in sig på honom för att få slut på hans inblandning och driva in hans obetalda skulder.",al={"vem är lord wishock","varför döda wishock","vem är wishock","lord wishock"}},c4eeba5d={q="Varför vill Zardeth att du levererar ölet i stället för att göra det själv?",a="Zardeth och hans häxmästarkollegor håller till i hemlighet i kryptorna under Slaughtered Lamb, mitt i Stormwind. Om han visade sig inför adelsmännen och stadsvakterna i Stormwind Keep skulle han genast väcka misstankar och riskera att gripas, särskilt eftersom Lord Wishock redan känner till Zardeths etablissemang. När en diskret äventyrare levererar det ser det ut som en vanlig tjänare som kommer med förfriskningar, och Zardeths plan förblir dold.",al={"varför behöver zardeth mig","varför leverera brygden","varför kan inte zardeth ge den till honom"}}},fp="12,156,17.267.0,14.291.1,33.208.0,37.182.1,28.158.0,39.111.1,56.123.1,33.116.1"}
P.entries["quest:3361"] = {n="A Refugee's Quandary",s="Efter Gnomeregans katastrofala fall till troggar och strålning har fördrivna gnomer flytt till Dun Moroghs snöiga vildmarker. Utanför Anvilmar förlorade ingenjören Felix Whindlebolt sina livsviktiga ägodelar och verktyg till Frostmane-troll som plundrade under den panikartade evakueringen.",h="Efter Gnomeregans katastrofala fall till troggar och strålning har fördrivna gnomer flytt till Dun Moroghs...",kw={"anvilmar","hink med bultar","coldridge","felix whindlebolt","frostmane","gnomeregan","strålning"},ang={["profession:Engineering"]="Ingen hantverkare med självrespekt kan stå bredvid medan plundrare kommer undan med precisionsbultar, skjutmått och verktygslådor som det tagit en livstid att samla ihop.",["race:Dwarf"]="Coldridges berg har skyddat ditt folk i århundraden. När du hjälper gnomiska flyktingar att finna fotfäste i Anvilmar hedrar du den urgamla alliansen mellan Ironforge och Gnomeregan.",["race:Gnome"]="Det här uppdraget fångar den bittra tragedi som drabbat ditt folk: efter att ha förlorat sitt underbara hem genom gift och förräderi måste vanliga uppfinnare nu vädja till främlingar om hjälp att ta tillbaka grundläggande verktyg från primitiva troll."},sec={{t="Flykten från Gnomeregan",b="När underjordiska troggar invaderade Gnomeregans högteknologiska stad godkände översteingenjör Gelbin Mekkatorque och hans rådgivare utsläppet av radioaktiv gas i ett desperat försök att utrota inkräktarna. Planen slog katastrofalt fel. Den dödade tusentals oskyldiga, förvandlade överlevande till viljelösa spetälskegnomer och tvingade resten av befolkningen till en desperat flykt genom Dun Morogh."},{t="Plundrare i snön",b="Ingenjörer och uppfinnare på flykt tog med sig de värdefulla verktyg och ritningar de kunde rädda. Men de iskalla bergspassen mellan Gnomeregan och Coldridge Valley patrulleras av inhemska Frostmane-troll. När Felix Whindlebolt kämpade sig mot tryggheten i Anvilmar ryckte Frostmane-rövare åt sig hans verktygslåda, kassaskrin och hink med bultar och släpade dem till sina läger sydväst om staden."}},faq={{q="Vem är Felix Whindlebolt?",a="Felix Whindlebolt är en gnomisk ingenjör som med knapp nöd undkom Gnomeregans radioaktiva förstörelse. Eftersom han inte är skicklig nog i strid för att försvara sig mot farorna i Dun Morogh, håller han sig nära Anvilmar medan han försöker återfå sin stulna utrustning.",al={"felix whindlebolt","vem är felix","felix anvilmar"}},{q="Varför är Gnomeregan radioaktivt?",a="Under en oväntad trogginvasion släppte de gnomiska myndigheterna ut flyktig radioaktiv gas för att utplåna monstren. I stället förorenade gasen stadens ventilationssystem. Den dödade eller muterade de flesta invånarna och gjorde huvudstaden obeboelig.",al={"vad hände med gnomeregan","gnomeregans strålning","gnomeregans fall"}},{q="Vem stal Felix ägodelar?",a="Frostmane-troll tog hans kista, låda och hink med bultar. De här inhemska trollen överfaller resenärer längs Dun Moroghs bergsstigar och släpar tillbaka stulet skrot och utrustning till sina primitiva läger sydväst om Anvilmar.",al={"vem stal bultarna","vem har felix saker","frostmane-troll"}},{q="Vart sökte de fördrivna gnomerna sin tillflykt?",a="Många gnomer flydde genom Dun Morogh till dvärgarnas kungarike Ironforge. Andra sökte tillfälligt skydd i mindre bosättningar som Anvilmar och Kharanos i Dun Morogh.",al={"var bor gnomerna","gnomiska flyktingar","gnomisk bosättning"}},{q="Varför är en hink med bultar så viktig?",a="För en gnomisk uppfinnare i exil är verktyg, specialskruvar och maskinbearbetade bultar hela försörjningen. Utan rätt utrustning kan flyktingingenjörer inte utöva sitt yrke, bygga försvar eller skapa sig ett nytt liv i exil.",al={"varför bultar","felix hink med bultar"}},{q="Vilket hot utgör Frostmane-trollen mot Coldridge Valley?",a="Frostmane-stammen har länge levt i Dun Moroghs kärva bergstoppar. Efter de senaste troggutbrotten och kaoset kring evakueringen av Gnomeregan har trollen blivit djärvare. De plundrar försörjningsleder och överfaller resenärer.",al={"troll i dun morogh","frostmane-hot","frostmane-läger"}}},fx={["0b2d3aab"]={q="Varför vill Felix Whindlebolt få tillbaka sina tillhörigheter?",a="Felix flydde från strålningen i Gnomeregan med knappt kläderna på kroppen och förlorade då det sista av sin försörjning och sitt hantverk. Utan sin kista, låda och sina verktyg är han helt strandsatt i Anvilmar, utan möjlighet att bygga upp sitt liv eller utöva sitt yrke som flykting.",al={"felix motiv","varför behöver felix det här","felix whindlebolts tillhörigheter"}},["48f90e68"]={q="Varför kan Felix inte hämta sina tillhörigheter själv?",a="Felix är en vanlig uppfinnare och en flykting på flykt, inte en äventyrare eller soldat. Han är livrädd för den fientliga vildmarken och kan inte mäta sig med Frostmane-trollen som tog hans utrustning. Därför vågar han inte ensam bege sig in i deras läger.",al={"varför hämtar inte felix sina saker","varför behöver felix mig","felix varför jag"}},["6a13a14f"]={q="Vad finns i Felix's Box och Felix's Chest?",a="Felix's Chest och Felix's Box innehåller hans personliga tillhörigheter och specialverktyg som han lyckades packa när han flydde från katastrofen i Gnomeregan. För en hantverkare på flykt långt hemifrån innehåller de allt som behövs för att börja om.",al={"felix's box","felix's chest","vad finns i felix's chest"}}},fp="20,206,26.299.0,22.354.0,25.201.0,29.233.0,29.194.0,43.135.0,42.212.0,61.203.0"}
P.entries["quest:3362"] = {n="Thistleshrub Valley",s="Tran'rek i Gadgetzan vill ta sig in i Thistleshrub Valley, men de märkliga bestarna där håller dem borta. Röj undan några taggbuskar, så kanske Tran'rek överväger att återvända.",h="Tran'rek i Gadgetzan vill ta sig in i Thistleshrub Valley, men de märkliga bestarna där håller dem borta.",kw={"kaktus","gadgetzan","knotig taggbuske","rotskulptör","tanaris","taggbuske","tran'rek","thistleshrub valley"},sec={{t="En farlig dal",b="Thistleshrub Valley ligger sydväst om Gadgetzan, och Tran'rek kallar den en mycket farlig plats. De litar inte på de märkliga bestarna där, de knotiga taggbuskarna och taggbuskarnas rotskulptörer, och eftersom det finns så många tänker de inte återvända."},{t="Glesa ut taggbuskarna",b="Tran'rek vill att åtta knotiga taggbuskar och åtta taggbuskarnas rotskulptörer röjs undan. Det finns ett villkor: Tran'rek vill titta närmare på kaktusen i dalen, så en del av den måste lämnas orörd."}},faq={{q="Vem ber om hjälp med Thistleshrub Valley?",a="Tran'rek, som befinner sig i Gadgetzan.",al={"uppdragsgivare","tran'reks plats","vem erbjuder thistleshrub valley"}},{q="Var ligger Thistleshrub Valley?",a="Den ligger sydväst om Gadgetzan.",al={"thistleshrub valleys plats","var ligger dalen","hitta dalen i tanaris"}},{q="Vilka varelser behöver röjas undan?",a="Åtta knotiga taggbuskar och åtta taggbuskarnas rotskulptörer.",al={"mål","vad ska dödas","vilka taggbuskar"}},{q="Varför vill Tran'rek att en del av kaktusen lämnas orörd?",a="Tran'rek vill titta närmare på kaktusen i dalen, så en del av den bör lämnas orörd.",al={"tran'reks motiv","varför åka till dalen","intresse för kaktusar"}}},fp="19,185,18.240.0,26.213.0,43.30.0,29.32.0,34.63.0,60.108.0"}
P.entries["quest:3364"] = {n="Scalding Mornbrew Delivery",s="Scalding Mornbrew Delivery är ett brådskande ärende genom Coldridge Valley: du ska leverera färsk, het dryck innan den svalnar i bergsfrosten. Nori Pridedrift anförtror leveransen åt en äventyrare så att Durnan Furcutter får sitt Mornbrew rykande hett.",h="Scalding Mornbrew Delivery är ett brådskande ärende genom Coldridge Valley: du ska leverera färsk, het dryck...",kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","nori pridedrift"},ang={["profession:Cooking"]="Att servera drycker vid rätt temperatur visar verklig respekt för mat och dryck, särskilt under Dun Moroghs skoningslösa minusgrader.",["race:Dwarf"]="Alla dvärgar förstår tragedin med kall dryck i den iskalla bergsluften, så färden genom dalen handlar om ren princip."},sec={{t="En kamp mot frosten",b="Den bitande kylan i Dun Morogh har förstört många varma måltider, och Mornbrew är inget undantag. Efter att ha levererat till Grelin Whitebeard inser Nori Pridedrift att han inte hinner ta med ännu en färsk kopp till Anvilmar innan den fryser till en oaptitlig sörja. I stället för att svika sin kund anlitar han en snabb resenär som vågar trotsa snön."},{t="Priset för en varm mugg",b="Durnan Furcutter, som håller till i värmen i Anvilmars bergssal, är känd för att vara noga med sina förfriskningar. Ljummet Mornbrew duger helt enkelt inte. När den rykande heta drycken kommer fram oskadd får en trött dvärg en välbehövlig paus från sina plikter, men Nori förväntar sig fortfarande att få tillbaka sin favoritmugg hel."}},faq={{q="Vem är Durnan Furcutter?",a="Durnan Furcutter är en dvärg som bor i Anvilmars underjordiska sal i Coldridge Valley. Han är beroende av att Nori Pridedrift levererar hans varma Mornbrew.",al={"durnan furcutter","vem är durnan","furcutter"}},{q="Varför måste leveransen gå så fort?",a="Den iskalla alpina kylan i Coldridge Valley får varma drycker att svalna snabbt. Durnan har uttryckligen beställt skållhett Mornbrew, och enligt dvärgarnas måttstock är kall öl eller te förstört.",al={"varför tidsbegränsat","mornbrew-timer","varför bråttom"}},{q="Vem är Nori Pridedrift?",a="Nori Pridedrift är en dvärg som håller till ute på de snöiga stigarna i Coldridge Valley. Han sköter leveranser mellan lokala läger, bland annat drycker till Grelin Whitebeard och arbetarna i Anvilmar.",al={"nori pridedrift","nori","vem är nori"}},{q="Vad är Mornbrew?",a="Mornbrew är en varm, uppiggande morgondryck för dvärgar, bryggd för att stå emot den iskalla kylan på Dun Moroghs toppar och hålla bergsarbetare starka.",al={"vad är mornbrew","mornbrew-lore"}},{q="Var ligger Anvilmar?",a="Anvilmar ligger rakt nordost om Noris postering, uthugget i berggrunden i Coldridge Valley för att skydda unga bergsklättrare och hantverkare från snöstormarna.",al={"var ligger anvilmar","anvilmars läge","hitta anvilmar"}},{q="Vill Nori ha tillbaka muggen?",a="Ja. När Durnan har njutit färdigt av sin varma dryck lämnar han tillbaka den tomma muggen så att den kan återlämnas till Nori i Coldridge Valley.",al={"lämna tillbaka muggen","ta tillbaka muggen","nori's mug"}}},fx={["77d8ea01"]={q="Varför vill Nori Pridedrift att morgonbrygden levereras?",a="Nori skulle leverera färskbryggd, rykande het morgonbrygd till Durnan Furcutter, men en tidigare leverans till Grelin Whitebeard försenade honom. Durnan förväntar sig att brygden ska vara rykande het, inte ljummen eller kall, så Nori skyndar sig att få drycken till Anvilmar innan den svalnar helt.",al={"varför leverera morgonbrygd","noris motiv","varför behöver nori få det här levererat"}},["4fdc3467"]={q="Varför ber Nori dig leverera den i stället för att ta den själv?",a="Nori ligger redan efter schemat efter att ha stannat för att betjäna Grelin Whitebeard. Han vet att brygden bara håller sig skållhet i några få minuter och inser att han inte hinner springa uppför bergsstigen själv. När han får syn på dig litar han till dina friska ben för att rusa till Anvilmar innan drycken kallnar.",al={"varför behöver nori mig","varför kan inte nori leverera det","varför jag, noris leverans"}}},fp="26,157,24.205.0,23.249.0,24.120.0,41.133.0,23.187.0,17.141.0,26.155.0,28.94.0"}
P.entries["quest:3365"] = {n="Bring Back the Mug",s="När du har levererat rykande het Mornbrew över snödrivorna i Dun Morogh återstår ett sista ärende: att lämna tillbaka den tomma stopet. Durnan Furcutter skickar budet tillbaka genom Coldridge Valley för att återlämna Nori Pridedrifts dyrbara mugg. Det är en enkel artighet, men en som ölförsäljaren uppskattar djupt.",h="När du har levererat rykande het Mornbrew över snödrivorna i Dun Morogh återstår ett sista ärende: att lämna...",kw={"bring back the mug","dun morogh","durnan furcutter","kharanos","mornbrew","nori pridedrift","stop"},ang={["profession:Cooking"]="Varje riktig kock eller bryggare vet att god service inte är avslutad förrän servisen har räknats och lämnats tillbaka till köket.",["race:Dwarf"]="Varje dvärg vet att det snabbt kan bli slagsmål om man behåller en värdshusvärds stop. Att lämna tillbaka Nori's Mug är vanligt dvärgvett."},sec={{t="En fråga om värdshusvett",b="Att servera rykande het Mornbrew i Dun Moroghs bitande kyla är en vansklig uppgift. När Durnan Furcutter har värmt benen med det skållheta brygget kan den tomma stopet inte bara kastas i snön. Dvärgarnas gästfrihet bygger på ömsesidig respekt, och försvunnen servis är ett säkert sätt att bli utan framtida rundor."},{t="Muggar växer inte på träd",b="När du återvänder till Coldridge Valley är leveransrundan åt Nori Pridedrift avklarad. Som Nori gärna påminner tankspridda kurirer om växer tåliga dryckeskärl inte på träd, särskilt inte bland dvärgarnas hemlands frostkalla klippor. När du lämnar tillbaka kärlet helt och hållet får du rykte om dig att vara pålitlig i lokalsamhället."}},faq={{q="Vem ger dig det här ärendet?",a="Durnan Furcutter ger dig uppgiften direkt efter att du har levererat den nybryggda Mornbrew till honom i Dun Morogh.",al={"uppdragsgivare","vem ger bring back the mug","durnan furcutter uppdrag"}},{q="Vem ska jag lämna tillbaka muggen till?",a="Du lämnar tillbaka den tomma muggen till Nori Pridedrift, som vandrar omkring i Coldridge Valley i Dun Morogh och säljer sin mornbrew.",al={"var ska jag lämna muggen","vem ska ha muggen","noris plats"}},{q="Finns det en tidsgräns för att lämna tillbaka muggen?",a="Nej. Den första leveransen av Scalding Mornbrew hade en strikt tidsgräns för att drycken skulle hålla sig rykande het, men du kan lämna tillbaka den tomma muggen i din egen takt.",al={"är uppdraget tidsbegränsat","muggens tidsgräns","måste jag skynda mig tillbaka"}},{q="Varför bryr sig Nori så mycket om en tom mugg?",a="Kvalitetsmuggar och stop är värdefull barutrustning i Dun Morogh. Som Nori påpekar växer muggar inte på träd, och värdshus har inte råd att förlora dryckeskärl till varenda förbipasserande kurir.",al={"varför vill nori ha tillbaka muggen","muggens betydelse"}},{q="Vilket uppdrag leder direkt till det här?",a="Det här är den direkta fortsättningen på 'Scalding Mornbrew Delivery' och börjar i samma ögonblick som Durnan dricker drycken du tog med till honom.",al={"förutsättningsuppdrag","vad kommer före bring back the mug"}},{q="Var hittar man Durnan Furcutter?",a="Durnan Furcutter är en handlare som säljer tyg- och läderrustning. Han finns inne i Anvilmar, bosättningen som grävts ut i berget i Coldridge Valley.",al={"durnans plats","var finns durnan"}}},fx={aa771bb6={q="Varför vill Durnan Furcutter att det här blir gjort?",a="Durnan Furcutter har just njutit av den rykande heta, skållheta morgonbrygd som Nori levererade i Coldridge Valley för att hålla kylan borta. Att lämna tillbaka den tomma muggen är vanlig hövlighet mot Nori Pridedrift, som väntar sig att få tillbaka sitt glas i stället för att budbärare lämnar det i den iskalla snön i Dun Morogh.",al={"varför lämna tillbaka muggen","durnan lämnar tillbaka muggen","varför skicka tillbaka muggen"}}},fp="18,130,28.195.0,24.218.0,23.122.0,27.105.0,40.160.0,46.172.0,40.104.0,36.130.0"}
P.entries["quest:3367"] = {n="Suntara Stones",s="Dorius Stonetender är svårt skadad i Searing Gorge, yr, med en snurrande värld och inre blödningar. Han säger att han måste tillbaka till Ironforge och ber dig hjälpa honom dit.",h="Dorius Stonetender är svårt skadad i Searing Gorge, yr, med en snurrande värld och inre blödningar.",kw={"dorius stonetender","ironforge","searing gorge","svedt brev","stonewrought pass","suntara stones"},sec={{t="En vädjan om hjälp",b="Dorius stönar och säger att han är svårt skadad. Han känner sig yr, världen snurrar och han blöder invärtes. Hans enda önskan är att komma tillbaka till Ironforge, och han ber dig hjälpa honom på vägen."},{t="Vägen till passet",b="Vägen tar slut strax före Stonewrought Pass. Där blir Dorius skjuten och dör, och ett brev han bar på faller till marken, svedd."}},faq={{q="Vem är Dorius Stonetender?",a="Dorius Stonetender är svårt skadad i Searing Gorge och behöver hjälp att komma tillbaka till Ironforge.",al={"vem är dorius","dorius stonetender","skadad dvärg searing gorge"}},{q="Vart försöker Dorius ta sig?",a="Han vill tillbaka till Ironforge.",al={"dorius destination","vart ska dorius","dorius eskort plats"}},{q="I vilket skick är Dorius?",a="Han är svårt skadad och yr, och blöder invärtes. Världen snurrar omkring honom.",al={"dorius tillstånd","är dorius skadad","varför behöver dorius hjälp"}}},fp="14,188,15.204.0,20.135.1,26.94.0,29.34.0,28.95.0"}
P.entries["quest:3368"] = {n="Suntara Stones",s="Ett svedd brev som Dorius tappade är skrivet till hans bror. Det berättar att Suntara-stenarna finns på riktigt och är i Dark Irons händer. Deras ledare Lathoric the Black använder deras kraft för att förslava Dorius utgrävningsteam. Brevet är avsett för Thorius i Hall of Explorers i Ironforge, och det är du som ska bära dit det.",h="Ett svedd brev som Dorius tappade är skrivet till hans bror.",kw={"the cauldron","dorius","hall of explorers","ironforge","lathoric the black","obsidion","searing gorge","svedda brevet","suntara stones","thorius"},sec={{t="Den dödes brev",b="I brevet skriver Dorius till sin bror att om det läses är han borta. Stenarna finns, och Dark Irons har dem. Deras ledare, Lathoric the Black, använder deras kraft för att förslava Dorius utgrävningsteam. Teamet fördes till The Cauldron, och deras sinnen är förvridna medan de sliter dag och natt med att färdigställa något som kallas Obsidion. Dorius vädjar till sin bror att hjälpa dem, hans sista önskan, och ber att de som lämnar brevet ska tackas."},{t="Thorius får veta",b="Thorius snyftar när brevet överlämnas. Sedan torkar Thorius ansiktet och svär vid Ljusets namn att Dorius ska få sin önskan uppfylld."}},faq={{q="Vem skrev det svedda brevet?",a="Dorius skrev det till sin bror som ett meddelande att läsa efter hans död.",al={"vem skrev brevet","författare till det svedda brevet","dorius brev"}},{q="Var bor Thorius?",a="Curator Thorius finns i Hall of Explorers i Ironforge.",al={"var finns thorius","curator thorius plats","thorius hall of explorers"}},{q="Vad hände med Dorius utgrävningsteam?",a="I brevet står det att Lathoric the Black och Dark Irons använder stenarna för att förslava dem. De fördes till The Cauldron.",al={"vad hände med utgrävningsteamet","dorius utgrävningsteam","förslavade arbetare the cauldron"}},{q="Vad arbetar det förslavade teamet med?",a="I brevet står det att deras sinnen är förvridna och att de sliter dag och natt med något som kallas Obsidion.",al={"vad är obsidion","utgrävningsprojekt the cauldron","dark iron-projektet obsidion"}},{q="Vem är Lathoric the Black?",a="I brevet nämns han som ledare för Dark Irons, som har Suntara-stenarna och använder deras kraft för att förslava Dorius team.",al={"vem är lathoric","lathoric the black","dark irons ledare searing gorge"}},{q="Hur följer detta på det tidigare Suntara Stones?",a="Det följer på det första Suntara Stones, där Dorius blev skjuten och brevet föll från honom. Brevet ska bäras till Ironforge.",al={"tidigare uppdraget suntara stones","suntara stones-uppdragskedjan"}}},fp="14,334,21.458.0,22.134.1,28.72.0,26.67.0,42.124.0,37.104.0,26.127.0,48.133.0"}
P.entries["quest:3369"] = {n="In Nightmares",s="In Nightmares är ett uppdrag för Horde där en äventyrare ska bära en oroande relik, Nightmare Shard, till Arch Druid Hamuul Runetotem på toppen av Elder Rise i Thunder Bluff. Skärvan hittades först som ett lysande fragment i Wailing Caverns och avslöjar en djupt oroande korruption som sipprar in i The Emerald Dream.",h="In Nightmares är ett uppdrag för Horde där en äventyrare ska bära en oroande relik, Nightmare Shard, till...",kw={"elder rise","emerald dream","falla sagewind","glowing shard","hamuul runetotem","in nightmares","nightmare shard","thunder bluff","wailing caverns"},ang={["class:Druid"]="För druider är skärvan ett djupt oroande bevis på att The Emerald Dreams obefläckade helighet har skadats. Den bekräftar viskningarna om korruption som sprider sig genom Cenarionkretsarna.",["faction:Horde"]="Genom att överlämna skärvan skyddar du det andliga välbefinnandet i centrala Kalimdor och visar att Horde spelar en avgörande roll i att hejda svampkorruptionen och den drömfödda korruptionen som sprider sig från The Barrens.",["race:Tauren"]="Att återvända till Arch Druid Hamuul Runetotem understryker hur taurendruiderna får en allt viktigare roll inom Cenarion Circle, där de tillsammans med sina nattalviska läromästare möter uråldriga kosmiska hot."},sec={{t="En oroande upptäckt",b="Efter att ha undersökt den märkliga kristall som hämtats från djupet av Wailing Caverns känner Falla Sagewind igen den som något gjort av The Emerald Dreams rena essens. Men visionen inuti är mörk och kaotisk, och bär inte spår av fridfull sömn utan av en vaken mardröm. Hon vill inte tala öppet om så oroande omen och anförtror dig skärvan med instruktioner om att söka upp Thunder Bluffs mest vördnadsvärda äldre druid, Arch Druid Hamuul Runetotem."},{t="En hemlighet i drömmen",b="När Hamuul Runetotem får se Nightmare Shard på Elder Rise sviktar hans vanliga lugn när han blickar in i den. Inför de påtagliga bevisen för att The Emerald Dream håller på att lösas upp i en mardröm väljer ärkedruiden sina ord med omsorg. Han råder dig bestämt att vara diskret och varnar för att dessa känsliga frågor ligger långt bortom vanliga resenärers förståelse. I tysthet beslutar han sig för att undersöka den osynliga plåga som hotar den slumrande världen."}},faq={{q="Vad är Nightmare Shard?",a="Nightmare Shard är den lysande skärva som hämtades i Wailing Caverns och som Falla Sagewind anförtror dig efter att ha undersökt den. Den är smidd av The Emerald Dreams rena andliga essens, men bär på en rutten, förvriden vision som visar att något har gått fruktansvärt fel i drömmen.",al={"vad är nightmare shard","lysande mardrömsskärva","vad hittade falla"}},{q="Vem är Falla Sagewind?",a="Falla Sagewind är en kunnig taurendruid som håller till på bergssidan med utsikt över Wailing Caverns i The Barrens. Hon studerar de avvikande fenomen som uppstår i de fördärvade oaskavernorna och skickar kurirer från Horde till Hamuul Runetotem när farliga reliker upptäcks.",al={"falla sagewind","vem gav mig uppdraget","uppdragsgivare"}},{q="Var hittar jag Arch Druid Hamuul Runetotem?",a="Arch Druid Hamuul Runetotem bor på Elder Rise, en av Thunder Bluffs upphöjda mesas. Du hittar honom stående i druidcirkeln tillsammans med andra utövare från Cenarion Circle.",al={"var finns hamuul","hamuul runetotems plats","hamuul på elder rise"}},{q="Varför vill Hamuul hålla skärvan hemlig?",a="The Emerald Dream är naturens heliga fristad och de slumrande druidernas tillflykt. Påtagliga bevis för att den förvrids till en mardröm skulle kunna orsaka utbredd panik inom Cenarion Circle och undergräva de sköra försöken att återställa andlig balans i Kalimdor. Därför uppmanar Hamuul till tystnad.",al={"varför hålla det hemligt","hamuuls hemlighet","varför gömmer hamuul skärvan"}},{q="Har Alliance en version av det här uppdraget?",a="Ja. Medan Horde-mästare tar Nightmare Shard till Arch Druid Hamuul Runetotem i Thunder Bluff får Alliance-spelare som undersöker Wailing Caverns i uppdrag att föra sin skärva över havet till Darnassus och visa den för druiden Mathrengyl Bearwalker från Cenarion Circle.",al={"alliance-version","in nightmares för alliance","kan alliance göra det här"}},{q="Hur hänger det här ihop med Wailing Caverns?",a="Skärvan kommer från Wailing Caverns, där druiden Naralex gick in i en djup trans för att leda underjordiska källor till The Barrens. I stället för att läka landet förvandlades Naralex sömn till en vaken mardröm, som muterade grottans djurliv och sipprade in i kristallskärvor som den här.",al={"koppling till wailing caverns","koppling till naralex","hur hänger det ihop med naralex"}}},fx={d74ecb00={q="Varför vill Falla Sagewind att Nightmare Shard levereras till Hamuul Runetotem?",a="När Falla Sagewind undersöker skärvan känner hon igen den som ren essens från The Emerald Dream, men besudlad av syner från en vaknande mardröm. Hon blir illa till mods av det hon ser och inser att fyndet är alldeles för farligt och betydelsefullt för att hantera ensam. Hon vägrar säga mer och insisterar på att du genast för skärvan till Arch Druid Hamuul Runetotem i Thunder Bluff. Hon litar bara på en av de högst rankade och visaste druiderna i Cenarion Circle att förstå och hantera ett så olycksbådande tecken.",al={"varför skicka skärvan till hamuul","varför vill falla att det här blir gjort","falla sagewinds motiv"}}},fp="13,240,22.356.0,21.360.1,28.281.0,22.255.0,45.172.0,48.259.0,47.252.0,44.279.0"}
P.entries["quest:337"] = {n="An Old History Book",s="I Stormwind återvänder en försvunnen krönika till Royal Library. Den slitna boken heter The History of Stormwind och bär bibliotekets sigill. Den försvann innan kungariket återuppbyggdes efter första kriget. Återkomsten ger överbibliotekarien Milton Sheaf en chans att bevara historien om de södra människorikena.",h="I Stormwind återvänder en försvunnen krönika till Royal Library.",kw={"en gammal historiebok","duskwood","milton sheaf","bevara kunskap","southshore","stormwind keep","stormwinds bibliotek","the history of stormwind"},ang={["class:Mage"]="Som magiker vet du att uråldriga bibliotek rymmer kunskap som kan förfalla eller försummas när de lämnas i vildmarken.",["faction:Alliance"]="Som resenär i Alliance hjälper du till att återställa fragment av Stormwinds arv som överlevde första krigets förödelse.",["race:Human"]="Som människa från södern hjälper du till att återta skriftliga handlingar från vildmarken och återuppbygga en kultur som krossades av Old Horde."},sec={{t="En relik från första kriget",b="Duskwoods odöda och ogres strövar bland ruinerna där den här leriga volymen hittades. Boken är en sällsynt relik från tiden före Stormwinds förstörelse. På första sidan finns kungarikets officiella bibliotekssigill. Någon lånade den för årtionden sedan, innan Horde jämnade huvudstaden med marken, och man trodde att boken hade gått förlorad när södern föll."},{t="Att återställa bortglömda annaler",b="Milton Sheaf känner igen boken när den når honom i Royal Library i Stormwind Keep. Överbibliotekarien tänker placera den i arkivet för sällsynta böcker, men åren i den hemsökta vildmarken har skadat sidorna svårt. Fyndet får Sheaf att söka efter mer förlorad kunskap. Han vänder blicken norrut, mot Southshore, staden närmast det förstörda kungariket Alterac och dess övergivna bibliotek."}},faq={{q="Var hittar man den här boken?",a="Du hittar boken bland de fientliga varelserna som strövar omkring i Duskwood, oftast bland odöda på kyrkogårdarna och fälten eller ogres i de södra kullarna.",al={"var hittar man den gamla historieboken","var boken droppar","historiebok i duskwood"}},{q="Vem ska jag lämna boken till?",a="Lämna volymen till Milton Sheaf, överbibliotekarie i Royal Library inne i Stormwind Keep.",al={"var lämnar man in","var lämnar jag in den här","milton sheafs plats"}},{q="Varför är boken i så dåligt skick?",a="Boken lånades innan första kriget och Stormwind plundrades. Den tillbringade årtionden i Duskwoods vildmark, utsatt för smuts och förruttnelse och hanterad av kringströvande asätare och monster.",al={"varför är den lerig","varför är den skadad"}},{q="Leder återlämningen av boken till fler uppgifter?",a="Ja. Milton Sheaf skickar dig norrut till Southshore i Hillsbrad Foothills för att tala med Loremaster Dibbs, som kan hänvisa dig till böcker i Ruins of Alterac.",al={"what comes next","uppföljningsuppdrag","uppdragskedja med boken"}},{q="Varför bryr sig Milton Sheaf så mycket om just den här boken?",a="Få originalhandlingar överlevde när kungariket jämnades med marken och Stormwind brann under första kriget. Äkta texter från tiden före kriget hjälper forskare att pussla ihop kungarikets historia.",al={"varför är boken viktig","varför the history of stormwind är viktig"}},{q="Kan spelare i Horde slutföra det här uppdraget?",a="Nej. Boken tillhör Stormwinds Royal Library, och endast bibliotekarier i Alliance i Stormwind Keep kan ta emot den.",al={"horde-version","är det här bara för alliance"}}},fp="19,265,24.316.0,26.343.0,25.134.0,27.92.0,39.188.0,45.159.0,60.171.0,38.114.0"}
P.entries["quest:3370"] = {n="In Nightmares",s="Efter upptäckten av en märkligt lysande skärva inser Falla Sagewind att artefakten innehåller Emerald Dreams rena essens, besudlad av mörka syner. Hon skickar en äventyrare till Darnassus för att överlämna den oroande reliken direkt till Cenarion Circles äldsta druider.",h="Efter upptäckten av en märkligt lysande skärva inser Falla Sagewind att artefakten innehåller Emerald Dreams...",kw={"cenarion circle","cenarion enclave","darnassus","emerald dream","falla sagewind","glowing shard","in nightmares","mathrengyl bearwalker","nightmare shard"},ang={["class:Druid"]="För druider avslöjar det här uppdraget att den heliga Emerald Dream inte är den orörda fristad de lärt sig att kommunicera med, och antyder en djup fara inifrån.",["faction:Alliance"]="Alliansens äventyrare som bär reliken in i hjärtat av Darnassus ger nattalvernas ledare en tidig inblick i korrumperingen som sprider sig under världens yta.",["race:NightElf"]="Nattalverna vördar drömriket där Malfurion Stormrage sover. Att upptäcka en vaken mardröm i dess essens slår mot själva kärnan i deras andliga arv."},sec={{t="En oroande insikt",b="Den lysande skärvan från Wailing Caverns djup visar sig vara långt farligare än en vanlig kristall. När Falla Sagewind undersöker den känner hon igen den som en gestaltning av Emerald Dreams renaste essens. Men stenen återspeglar inte naturens grönskande harmoni, utan förvrids av oroande, skrämmande syner. Skakad av det hon ser vägrar Falla att själv undersöka saken närmare och insisterar på att skärvan måste överföras i trygghet till Cenarion Circles högsta ledning."},{t="Viskningar i Cenarion Enclave",b="I Darnassus överlämnas reliken till Mathrengyl Bearwalker, en erfaren druid i Cenarion Enclave. Mathrengyl tar först emot den med stillsam nyfikenhet, men blir synbart skakad så snart han blickar in i skärvans kärna. När han inser att korrumperingen som plågar The Barrens har direkt samband med störningar djupt inne i själva Emerald Dream, tystar han snabbt fortsatt diskussion. Den äldre druider varnar för att sådana skrämmande avvikelser inte är något för allmänhetens öron och tar tyst hand om Nightmare Shard för att studera den annalkande skuggan."}},faq={{q="Vad är Nightmare Shard?",a="Nightmare Shard är en kristalliserad bit av Emerald Dreams essens, som ursprungligen hittades som en mystisk lysande skärva. I stället för att återspegla naturens harmoni utstrålar den mörka syner och korrumperande kraft, vilket avslöjar att en ondskefull närvaro har börjat tränga in i Dream.",al={"vad är nightmare shard","lore om lysande skärva","skärva från emerald dream"}},{q="Vem är Falla Sagewind?",a="Falla Sagewind är en tauren-druid med kunskap om naturens läror som undersöker märkliga reliker funna ute i vildmarken. När hon inser den lysande skärvans verkliga, skrämmande ursprung hänvisar hon resande till högre druidauthoriteter i Darnassus.",al={"falla sagewind","vem är falla"}},{q="Vem är Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker är en äldre druidtränare i Cenarion Circle, stationerad vid Cenarion Enclave i Darnassus. Han är en erfaren mentor och undersöker allvarliga andliga hot mot naturen och Emerald Dream.",al={"mathrengyl bearwalker","bearwalker darnassus","vem är mathrengyl"}},{q="Varför är Mathrengyl så hemlighetsfull om skärvan?",a="Emerald Dream vördas som naturens orörda, okränkbara rike, lett av Green Dragonflight och de sovande druiderna. Bevis för att detta rike drabbats av mardrömslik korrumpering innebär en djup andlig kris, en som Cenarion Circle ogärna avslöjar för allmänheten.",al={"varför hemlighetsfull","vad döljer mathrengyl","varför vill mathrengyl inte prata"}},{q="Var börjar den här uppdragskedjan?",a="Berättelsen börjar med 'The Glowing Shard', ett föremål som hittas på Mutanus the Devourer vid slutet av Wailing Caverns. Skärvan förs till lärda som till slut spårar dess olycksbådande ursprung mot Darnassus eller Thunder Bluff.",al={"förkunskapskrav in nightmares","var började det här","hur får man in nightmares"}},{q="Har Hordespelare ett motsvarande uppdrag?",a="Ja. Medan Alliansens hjältar rapporterar till Mathrengyl Bearwalker i Darnassus överlämnar Hordens kämpar sina fynd till Hamuul Runetotem på Elder Rise i Thunder Bluff och får veta samma oroande nyheter om Emerald Dream.",al={"hordens version","finns in nightmares för horden","in nightmares horden"}}},fx={da5fa45e={q="Varför vill Falla Sagewind att Nightmare Shard ska levereras?",a="Falla Sagewind insåg att skärvan innehåller essensen av The Emerald Dream, men visionen hon skymtade inuti var djupt förvriden till en mardröm. Oroad över det hon såg och medveten om att sådan olycksbådande korruption ligger långt bortom hennes förståelse, insisterar hon på att den genast undersöks av en vis druid från Cenarion Circle i Darnassus.",al={"varför skicka skärvan till darnassus","varför vill falla att det görs","falla sagewinds motiv"}}},fp="13,144,22.386.0,32.435.1,28.232.1,22.215.0,29.200.0,47.270.1,34.197.0,42.231.0"}
P.entries["quest:3372"] = {n="Release Them",s="En döende arkeolog i Searing Gorge uppmanar dig att befria dem som Suntaras kraft fortfarande driver att fortsätta arbeta, trots att deras kroppar har gett upp. Allt hänger på Suntaras altare, där en relik som Twilight's Hammer vaktar måste placeras.",h="En döende arkeolog i Searing Gorge uppmanar dig att befria dem som Suntaras kraft fortfarande driver att...",kw={"suntaras altare","döende arkeolog","mysterious artifact","befria dem","searing gorge","the slag pit","twilight's hammer"},sec={{t="En döende vädjan",b="Innan arkeologen faller ihop ber hen dig att befria dem. Deras kroppar har gett upp, men Suntaras kraft driver dem vidare i arbetet. Nyckeln, säger arkeologen, är Suntaras altare."},{t="Suntaras altare",b="Gå nordväst, till kullarna ovanför grottan. Avgudadyrkare från Twilight's Hammer vaktar en relik där, kallad Mysterious Artifact. Ta den från dem och för den till The Slag Pit, där du ska placera den på Suntaras altare."}},faq={{q="Vem ber om hjälp med Release Them?",a="En döende arkeolog i Searing Gorge, som faller ihop efter sin vädjan.",al={"uppdragsgivare","vem ger uppdraget release them","döende arkeolog"}},{q="Var finns den mystiska artefakten?",a="Avgudadyrkare från Twilight's Hammer vaktar den i nordvästra delen av Searing Gorge, i kullarna ovanför grottan.",al={"mysterious artifact plats","var finns reliken","twilight's hammer-avgudadyrkare"}},{q="Vart måste artefakten föras?",a="Den förs till The Slag Pit och placeras på Suntaras altare.",al={"suntaras altare plats","var finns altaret","vart ska jag ta artefakten"}},{q="Varför kan offren inte vila?",a="Arkeologen säger att Suntaras kraft driver dem att fortsätta arbeta, trots att deras kroppar har gett upp.",al={"varför befria dem","vad händer med dem","suntaras kraft"}}},fp="12,276,12.212.0,20.212.0,36.69.0,41.109.0,37.62.0,35.114.0"}
P.entries["quest:3374"] = {n="The Essence of Eranikus",s="Du aktiverar Oathstone of Ysera's Dragonflight, och Itharius talar direkt in i ditt sinne. Att ta på sig uppdraget innebär att hjälpa Ysera's Dragonflight att rena Eranikus fördärvade själ, och det första offret är att ge Itharius ädelstenen som håller den del av Eranikus sinne som ännu är fri i bojor. Itharius väntar i Swamp of Sorrows.",h="Du aktiverar Oathstone of Ysera's Dragonflight, och Itharius talar direkt in i ditt sinne.",kw={"kedjad essens","eranikus","grön drakflygel","itharius","oathstone","swamp of sorrows","ysera"},sec={{t="En röst genom stenen",b="Genom Oathstone berättar Itharius för dig att du genom att ta på dig uppdraget hjälper Ysera's Dragonflight att rena Eranikus fördärvade själ. Itharius väntar sig många uppoffringar av er båda, och den första är att lämna över ädelstenen som håller den del av Eranikus sinne som fortfarande har fri vilja i bojor. Oathstone och Chained Essence of Eranikus måste föras till Itharius i Swamp of Sorrows, där du väljer om du vill hjälpa drakflygeln."},{t="Ett val är gjort",b="Itharius hälsar dig välkommen vid ännu ett vägskäl och frågar vilket val du gör. När du har valt säger Itharius att dina val hittills har varit de rätta och att dina handlingar hädanefter avgör om det fortsätter så."}},faq={{q="Vem är Itharius?",a="Itharius talar till ditt sinne genom Oathstone för Ysera's Dragonflight och väntar i Swamp of Sorrows, där han söker rena Eranikus fördärvade själ.",al={"vem är itharius","itharius roll","vem skickar meddelandet"}},{q="Vad är Chained Essence of Eranikus?",a="Det är ädelstenen som håller den del av Eranikus sinne som fortfarande är fri i bojor. Itharius ber dig att ge upp den som det första offret.",al={"chained essence of eranikus","vad är den kedjade ädelstenen","eranikus essens"}},{q="Vad hände före det här uppdraget?",a="Det följer på det första steget i The Essence of Eranikus, som har samma namn.",al={"förutsättningsuppdrag","föregående steg"}},{q="Vart för du Oathstone och essensen?",a="Till Itharius i Swamp of Sorrows, där du väljer om du vill hjälpa drakflygeln.",al={"vart lämna oathstone","var finns itharius","inlämningsplats"}}},fp="23,340,25.453.0,13.226.1,16.163.0,40.128.0,28.74.0,48.87.0"}
